import { LockedIcon, UnlockedIcon } from "../../lib/cccIcons"
import { useEffect, useState } from "react"
import { useTheme } from "../../contexts/ThemeContext"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import toast from "react-hot-toast"
import * as OTPAuth from "otpauth"
import QRCode from "qrcode"

export default function Admin2FA() {
  const { user, profile } = useAuth()
  const { theme } = useTheme()
  const [status, setStatus] = useState(null)
  const [step, setStep] = useState("loading")
  const [secret, setSecret] = useState("")
  const [qrUrl, setQrUrl] = useState("")
  const [code, setCode] = useState("")
  const [backupCodes, setBackupCodes] = useState([])
  const [verifying, setVerifying] = useState(false)
  const [disableCode, setDisableCode] = useState("")
  const [disabling, setDisabling] = useState(false)
  const [showBackup, setShowBackup] = useState(false)

  useEffect(() => { if (user) load() }, [user])

  async function load() {
    const { data } = await supabase.from("admin_2fa").select("*").eq("user_id", user.id).maybeSingle()
    setStatus(data||null)
    setStep(data?.is_enabled ? "enabled" : "setup")
  }

  async function generateSecret() {
    const totp = new OTPAuth.TOTP({
      issuer: "CarCareConnect",
      label: profile?.email || user.email || "Admin",
      algorithm: "SHA1",
      digits: 6,
      period: 30,
      secret: new OTPAuth.Secret()
    })
    const secretStr = totp.secret.base32
    setSecret(secretStr)
    const uri = totp.toString()
    const qr = await QRCode.toDataURL(uri)
    setQrUrl(qr)
    setStep("scan")
  }

  function generateBackupCodes() {
    const codes = []
    for (let i = 0; i < 8; i++) {
      const code = Math.random().toString(36).substring(2,6).toUpperCase() + "-" + Math.random().toString(36).substring(2,6).toUpperCase()
      codes.push(code)
    }
    return codes
  }

  function verifyCode(inputCode, secretStr) {
    try {
      const totp = new OTPAuth.TOTP({
        issuer: "CarCareConnect",
        label: "Admin",
        algorithm: "SHA1",
        digits: 6,
        period: 30,
        secret: OTPAuth.Secret.fromBase32(secretStr)
      })
      const delta = totp.validate({ token: inputCode, window: 1 })
      return delta !== null
    } catch { return false }
  }

  async function enable2FA(e) {
    e.preventDefault()
    if (code.length !== 6) return toast.error("Enter a 6-digit code")
    setVerifying(true)
    try {
      const valid = verifyCode(code, secret)
      if (!valid) { toast.error("Invalid code ΓÇö check your authenticator app"); setVerifying(false); return }
      const backup = generateBackupCodes()
      const { error } = await supabase.from("admin_2fa").upsert({
        user_id: user.id,
        secret,
        is_enabled: true,
        backup_codes: backup,
        updated_at: new Date().toISOString()
      }, { onConflict:"user_id" })
      if (error) throw error
      setBackupCodes(backup)
      setStep("backup")
      toast.success("2FA enabled successfully!")
    } catch(err) { toast.error(err.message) }
    finally { setVerifying(false) }
  }

  async function disable2FA(e) {
    e.preventDefault()
    if (!status?.secret) return
    setDisabling(true)
    try {
      const valid = verifyCode(disableCode, status.secret) ||
        status.backup_codes?.includes(disableCode.toUpperCase())
      if (!valid) { toast.error("Invalid code"); setDisabling(false); return }
      const { error } = await supabase.from("admin_2fa").update({
        is_enabled: false,
        secret: "",
        backup_codes: [],
        updated_at: new Date().toISOString()
      }).eq("user_id", user.id)
      if (error) throw error
      toast.success("2FA disabled")
      setDisableCode("")
      load()
    } catch(err) { toast.error(err.message) }
    finally { setDisabling(false) }
  }

  const inp = { width:"100%", background:"#ffffff", border:`1px solid ${"#f0f0f0"}`, borderRadius:8, padding:"12px 14px", color:"#000000", fontSize:14, outline:"none", fontFamily:"'DM Sans',sans-serif", letterSpacing:4, textAlign:"center", marginBottom:12 }

  if (step==="loading") return <div style={{ color:"#999999", fontSize:13 }}>Loading...</div>

  return (
    <div style={{ maxWidth:480 }}>
      <div style={{ marginBottom:"1.5rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:20, fontWeight:800, color:"#000000" }}>Two-Factor Authentication</div>
        <div style={{ fontSize:12, color:"#999999", marginTop:4 }}>Add an extra layer of security to your admin account</div>
      </div>

      <div style={{ background:"#ffffff", border:`1px solid ${status?.is_enabled?"#1d9e7540":"#eeeeee"}`, borderRadius:12, padding:"1.25rem", marginBottom:"1.5rem", display:"flex", alignItems:"center", gap:12 }}>
        <div style={{ width:44, height:44, borderRadius:10, background:status?.is_enabled?"#f0fdf4":"#f5f5f5", display:"flex", alignItems:"center", justifyContent:"center", fontSize:22, flexShrink:0 }}>
          {status?.is_enabled?<LockedIcon size={20} color="#1d9e75"/>:<UnlockedIcon size={20} color="#e6821e"/>}
        </div>
        <div style={{ flex:1 }}>
          <div style={{ fontSize:14, fontWeight:600, color:status?.is_enabled?"#1d9e75":"#000000" }}>
            2FA is {status?.is_enabled?"enabled":"disabled"}
          </div>
          <div style={{ fontSize:11, color:"#999999", marginTop:2 }}>
            {status?.is_enabled
              ? "Your account is protected with an authenticator app"
              : "Enable 2FA to secure your admin account"}
          </div>
        </div>
        {status?.is_enabled&&(
          <span style={{ fontSize:10, padding:"3px 10px", borderRadius:20, background:"#f0fdf4", color:"#1d9e75", border:"1px solid #1d9e7540" }}>Active</span>
        )}
      </div>

      {step==="setup"&&(
        <div style={{ background:"#ffffff", border:`1px solid ${"#eeeeee"}`, borderRadius:12, padding:"1.25rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:8, color:"#000000" }}>Setup authenticator</div>
          <div style={{ fontSize:12, color:"#666666", marginBottom:"1.5rem", lineHeight:1.6 }}>
            Use an authenticator app like <strong style={{ color:"#000000" }}>Google Authenticator</strong> or <strong style={{ color:"#000000" }}>Authy</strong> to generate time-based codes for login verification.
          </div>
          {[
            { step:"1", text:"Download Google Authenticator or Authy on your phone" },
            { step:"2", text:"Click the button below to generate your QR code" },
            { step:"3", text:"Scan the QR code with your authenticator app" },
            { step:"4", text:"Enter the 6-digit code to verify and enable 2FA" },
          ].map(s=>(
            <div key={s.step} style={{ display:"flex", gap:12, marginBottom:10 }}>
              <div style={{ width:28, height:28, borderRadius:"50%", background:"#fff8f0", border:"1px solid #e6821e30", display:"flex", alignItems:"center", justifyContent:"center", fontSize:12, fontWeight:700, color:"#e6821e", flexShrink:0 }}>{s.step}</div>
              <div style={{ fontSize:13, color:"#888", paddingTop:5, lineHeight:1.5 }}>{s.text}</div>
            </div>
          ))}
          <button onClick={generateSecret}
            style={{ width:"100%", marginTop:8, background:"#8b5cf6", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700, padding:"13px", cursor:"pointer" }}>
            Generate QR code
          </button>
        </div>
      )}

      {step==="scan"&&(
        <div>
          <div style={{ background:"#ffffff", border:`1px solid ${"#eeeeee"}`, borderRadius:12, padding:"1.25rem", marginBottom:"1rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:"1rem", color:"#000000" }}>Scan QR code</div>
            <div style={{ display:"flex", justifyContent:"center", marginBottom:"1rem" }}>
              {qrUrl&&<img src={qrUrl} alt="QR Code" style={{ width:180, height:180, borderRadius:10, border:"4px solid #fff" }}/>}
            </div>
            <div style={{ fontSize:11, color:"#999999", textAlign:"center", marginBottom:"1rem" }}>
              Can&apos;t scan? Enter this code manually:
            </div>
            <div style={{ background:"#ffffff", border:`1px solid ${"#f0f0f0"}`, borderRadius:8, padding:"0.75rem", fontFamily:"monospace", fontSize:13, color:"#e6821e", letterSpacing:3, textAlign:"center", wordBreak:"break-all", marginBottom:"1rem" }}>
              {secret}
            </div>
          </div>

          <div style={{ background:"#ffffff", border:`1px solid ${"#eeeeee"}`, borderRadius:12, padding:"1.25rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:4, color:"#000000" }}>Verify code</div>
            <div style={{ fontSize:12, color:"#666666", marginBottom:"1rem" }}>Enter the 6-digit code from your authenticator app</div>
            <form onSubmit={enable2FA}>
              <input
                style={inp}
                type="text"
                inputMode="numeric"
                maxLength={6}
                placeholder="000000"
                value={code}
                onChange={e=>setCode(e.target.value.replace(/\D/g,""))}
                autoComplete="one-time-code"
              />
              <div style={{ display:"flex", gap:8 }}>
                <button type="submit" disabled={verifying||code.length!==6}
                  style={{ flex:1, background:code.length===6?"#8b5cf6":"#e0e0e0", border:"none", borderRadius:9, color:code.length===6?"#fff":"#666", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"12px", cursor:code.length===6?"pointer":"not-allowed" }}>
                  {verifying?"Verifying...":"Enable 2FA"}
                </button>
                <button type="button" onClick={()=>setStep("setup")}
                  style={{ background:"none", border:"1px solid #dddddd", borderRadius:9, color:"#888", fontSize:13, padding:"12px 18px", cursor:"pointer" }}>
                  Back
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {step==="backup"&&(
        <div style={{ background:"#ffffff", border:"1px solid #1d9e7540", borderRadius:12, padding:"1.25rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:4, color:"#1d9e75" }}>Γ£ô 2FA enabled!</div>
          <div style={{ fontSize:12, color:"#666666", marginBottom:"1.25rem", lineHeight:1.6 }}>
            Save these backup codes in a safe place. Each can be used once to access your account if you lose your authenticator.
          </div>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6, marginBottom:"1.25rem" }}>
            {backupCodes.map((code,i)=>(
              <div key={i} style={{ background:"#ffffff", border:`1px solid ${"#f0f0f0"}`, borderRadius:7, padding:"8px 12px", fontFamily:"monospace", fontSize:13, color:"#000000", textAlign:"center", letterSpacing:2 }}>
                {code}
              </div>
            ))}
          </div>
          <button onClick={()=>{ navigator.clipboard.writeText(backupCodes.join("\n")); toast.success("Backup codes copied!") }}
            style={{ width:"100%", background:"#eff6ff", border:"1px solid #378add40", borderRadius:9, color:"#378add", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px", cursor:"pointer", marginBottom:8 }}>
            Copy backup codes
          </button>
          <button onClick={()=>{ setStep("enabled"); load() }}
            style={{ width:"100%", background:"#8b5cf6", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px", cursor:"pointer" }}>
            Done ΓÇö I&apos;ve saved my backup codes
          </button>
        </div>
      )}

      {step==="enabled"&&(
        <div>
          <div style={{ background:"#ffffff", border:`1px solid ${"#eeeeee"}`, borderRadius:12, padding:"1.25rem", marginBottom:"1rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:"1rem", color:"#000000" }}>Backup codes</div>
            <div style={{ fontSize:12, color:"#666666", marginBottom:10 }}>
              You have {status?.backup_codes?.length||0} backup codes remaining.
            </div>
            <button onClick={()=>setShowBackup(s=>!s)}
              style={{ background:"#ffffff", border:"1px solid #dddddd", borderRadius:8, color:"#888", fontSize:12, padding:"8px 14px", cursor:"pointer" }}>
              {showBackup?"Hide":"View"} backup codes
            </button>
            {showBackup&&(
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6, marginTop:10 }}>
                {(status?.backup_codes||[]).map((code,i)=>(
                  <div key={i} style={{ background:"#ffffff", border:`1px solid ${"#f0f0f0"}`, borderRadius:7, padding:"8px 12px", fontFamily:"monospace", fontSize:13, color:"#000000", textAlign:"center", letterSpacing:2 }}>
                    {code}
                  </div>
                ))}
              </div>
            )}
          </div>

          <div style={{ background:"#ffffff", border:"1px solid #e24b4a20", borderRadius:12, padding:"1.25rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:4, color:"#e24b4a" }}>Disable 2FA</div>
            <div style={{ fontSize:12, color:"#666666", marginBottom:"1rem" }}>
              Enter your current authenticator code or a backup code to disable 2FA.
            </div>
            <form onSubmit={disable2FA}>
              <input
                style={{ ...inp, letterSpacing:2 }}
                type="text"
                placeholder="000000 or XXXX-XXXX"
                value={disableCode}
                onChange={e=>setDisableCode(e.target.value)}
              />
              <button type="submit" disabled={disabling||!disableCode}
                style={{ width:"100%", background:disableCode?"#fff5f5":"#f5f5f5", border:`1px solid ${disableCode?"#e24b4a40":"#e0e0e0"}`, borderRadius:9, color:disableCode?"#e24b4a":"#555", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"12px", cursor:disableCode?"pointer":"not-allowed" }}>
                {disabling?"Disabling...":"Disable 2FA"}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

import { SecurityIcon } from "../../lib/cccIcons"
import { useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import { useTheme } from "../../contexts/ThemeContext"
import * as OTPAuth from "otpauth"
import toast from "react-hot-toast"

export default function Admin2FAVerify({ onVerified }) {
  const { user } = useAuth()
  const { theme } = useTheme()
  const [code, setCode] = useState("")
  const [verifying, setVerifying] = useState(false)

  async function verify(e) {
    e.preventDefault()
    if (!code) return
    setVerifying(true)
    try {
      const { data } = await supabase.from("admin_2fa")
        .select("secret,backup_codes,is_enabled")
        .eq("user_id", user.id)
        .maybeSingle()

      if (!data?.is_enabled) { onVerified(); return }

      const totp = new OTPAuth.TOTP({
        issuer: "CarCareConnect",
        label: "Admin",
        algorithm: "SHA1",
        digits: 6,
        period: 30,
        secret: OTPAuth.Secret.fromBase32(data.secret)
      })

      const delta = totp.validate({ token: code, window: 1 })
      const isBackup = data.backup_codes?.includes(code.toUpperCase())

      if (delta !== null || isBackup) {
        if (isBackup) {
          const newCodes = data.backup_codes.filter(c=>c!==code.toUpperCase())
          await supabase.from("admin_2fa").update({ backup_codes:newCodes }).eq("user_id", user.id)
        }
        onVerified()
      } else {
        toast.error("Invalid code ΓÇö try again")
        setCode("")
      }
    } catch(err) {
      toast.error(err.message)
    } finally {
      setVerifying(false)
    }
  }

  return (
    <div style={{ minHeight:"100vh", background:"#ffffff", display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"'DM Sans',sans-serif" }}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Syne:wght@700;800&family=DM+Sans:wght@300;400;500&display=swap');`}</style>
      <div style={{ width:"100%", maxWidth:380, padding:"0 1rem" }}>
        <div style={{ textAlign:"center", marginBottom:"2rem" }}>
          <div style={{ width:60, height:60, background:"#fff8f0", borderRadius:14, display:"flex", alignItems:"center", justifyContent:"center", margin:"0 auto 1rem", border:`1px solid ${"#e6821e30"}` }}><SecurityIcon size={28} color="#e6821e"/></div>
          <div style={{ fontFamily:"Syne", fontSize:22, fontWeight:800, color:"#000000", marginBottom:4 }}>Two-Factor Auth</div>
          <div style={{ fontSize:13, color:"#999999" }}>Enter the 6-digit code from your authenticator app</div>
        </div>

        <form onSubmit={verify}>
          <input
            type="text"
            inputMode="numeric"
            maxLength={8}
            placeholder="000000"
            value={code}
            onChange={e=>setCode(e.target.value.replace(/[^0-9A-Z-]/gi,""))}
            autoComplete="one-time-code"
            autoFocus
            style={{ width:"100%", background:"#ffffff", border:`1px solid ${"#f0f0f0"}`, borderRadius:10, padding:"16px", color:"#000000", fontSize:24, outline:"none", fontFamily:"monospace", letterSpacing:8, textAlign:"center", marginBottom:12 }}
          />
          <button type="submit" disabled={verifying||!code}
            style={{ width:"100%", background:code?"#8b5cf6":"#e0e0e0", border:"none", borderRadius:10, color:code?"#fff":"#666", fontFamily:"Syne,sans-serif", fontSize:15, fontWeight:700, padding:"14px", cursor:code?"pointer":"not-allowed", transition:"all 0.12s" }}>
            {verifying?"Verifying...":"Verify"}
          </button>
        </form>

        <div style={{ textAlign:"center", marginTop:"1.5rem", fontSize:12, color:"#cccccc" }}>
          Lost your device? Use a backup code instead.
        </div>
      </div>
    </div>
  )
}

import { useEffect, useState } from "react"
import { useAuth } from "../../contexts/AuthContext"
import { supabase } from "../../lib/supabase"
import toast from "react-hot-toast"
import { jsPDF } from "jspdf"

export default function AdminAIMonitor() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const [report, setReport] = useState(null)
  const [codeScan, setCodeScan] = useState(null)
  const [scanning, setScanning] = useState(false)


  const [loading, setLoading] = useState(true)
  const [open, setOpen] = useState(true)
  const [errorLogs, setErrorLogs] = useState([])
  const [loadingErrors, setLoadingErrors] = useState(false)
  const [chatInput, setChatInput] = useState("")
  const [chatMessages, setChatMessages] = useState([])
  const [chatLoading, setChatLoading] = useState(false)

  useEffect(() => { scanPlatform() }, [])

  async function loadErrorLogs() {
    setLoadingErrors(true)
    try {
      const { data } = await supabase.from("error_logs")
        .select("*").order("created_at",{ascending:false}).limit(30)
      setErrorLogs(data||[])
    } catch(e) { console.error(e) }
    finally { setLoadingErrors(false) }
  }

  async function clearErrorLogs() {
    await supabase.from("error_logs").delete().neq("id","00000000-0000-0000-0000-000000000000")
    setErrorLogs([])
    toast.success("Logs cleared")
  }

  async function scanCode() {
    setScanning(true)
    try {
      const files = [
        "src/App.jsx",
        "src/contexts/AuthContext.jsx",
        "src/contexts/MechanicAuthContext.jsx",
        "src/components/shared/Layout.jsx",
        "src/components/shared/EmergencySOS.jsx",
        "src/components/shared/AIAssistant.jsx",
        "src/components/admin/AdminDashboard.jsx",
        "src/components/admin/AdminAIMonitor.jsx",
        "src/components/provider/ProviderDashboard.jsx",
        "src/components/provider/ProviderProfile.jsx",
        "src/components/provider/ProviderBookings.jsx",
        "src/components/provider/ProviderPartsManager.jsx",
        "src/components/provider/ProviderGoRequests.jsx",
        "src/components/provider/ProviderMechanics.jsx",
        "src/components/driver/DriverProfile.jsx",
        "src/components/driver/DriverDashboard.jsx",
        "src/components/driver/DriverActiveDelivery.jsx",
        "src/components/customer/CustomerProfile.jsx",
        "src/components/customer/CustomerGoService.jsx",
        "src/components/mechanic/MechanicDashboard.jsx",
        "src/components/marketplace/Marketplace.jsx",
        "src/components/marketplace/MyListings.jsx",
        "src/lib/pushNotifications.js",
        "src/components/shared/ChatWindow.jsx",
        "src/components/admin/AdminLiveMap.jsx",
        "src/components/admin/AdminClaims.jsx",
        "src/components/admin/AdminCommissions.jsx",
        "src/components/admin/AdminSettings.jsx",
        "src/components/admin/AdminBookings.jsx",
        "src/components/customer/CustomerServices.jsx",
        "src/components/customer/CustomerBookings.jsx",
        "src/components/customer/ProviderStorefront.jsx",
        "src/components/auth/AuthPage.jsx",
        "src/components/auth/ResetPassword.jsx",
      ]
      const issues = []
      for (const file of files) {
        try {
          const res = await fetch(`https://raw.githubusercontent.com/brianbakari22-web/carcareconnect2-/main/${file}`)
          if (!res.ok) continue
          const code = await res.text()
          const lines = code.split("\n")

          // Pattern 3: duplicate function declarations in same file
          const funcDecls = [...code.matchAll(/function (\w+)\(/g)].map(m=>m[1])
          const seen = {}
          funcDecls.forEach(name => { seen[name] = (seen[name]||0) + 1 })
          Object.entries(seen).forEach(([name, n]) => {
            if (n > 1) issues.push({ file, line:0, code:"function "+name, issue:"Duplicate function declaration ("+n+"x) ΓÇö second definition silently overwrites the first" })
          })

          // Pattern 5: hardcoded fake-positive diagnostic values
          lines.forEach((line, i) => {
            if (line.match(/\bok\s*:\s*true\s*[,}]/) && !line.includes("AI Monitor")) {
              issues.push({ file, line:i+1, code:line.trim(), issue:"Hardcoded ok:true in diagnostic-looking code ΓÇö may give false confidence instead of checking real data" })
            }
          })

          // Pattern 6: silently swallowed errors (no user feedback, no error log)
          lines.forEach((line, i) => {
            if (line.match(/catch\(\w*\)\s*\{\s*console\.(error|log)\(/) && !line.includes("toast.") && !line.includes("error_logs")) {
              issues.push({ file, line:i+1, code:line.trim(), issue:"Error caught but only logged to console ΓÇö now also captured globally by window.onerror, but consider user-facing toast for better UX" })
            }
          })

          // Pattern 7: dead code landmines wrapped in &&false&&
          lines.forEach((line, i) => {
            if (line.match(/&&\s*false\s*&&\s*null/)) {
              issues.push({ file, line:i+1, code:line.trim(), issue:"Dead code reference wrapped in &&false&& ΓÇö landmine if condition logic changes later, references variable that may not exist in scope" })
            }
          })
        } catch(fe) { issues.push({ file, line:0, code:"", issue:"Could not fetch: "+fe.message }) }
      }
      setCodeScan({ issues, scannedAt:new Date().toLocaleString(), filesScanned:files.length })
    } catch(e) { console.error(e) }
    finally { setScanning(false) }
  }

  async function checkAPIHealth() {
    const checks = {}
    // Check Supabase
    try {
      const start = Date.now()
      await supabase.from("profiles").select("id",{count:"exact",head:true})
      checks.supabase = { status:"ok", ms:Date.now()-start }
    } catch(e) { checks.supabase = { status:"error", ms:0 } }

    // Check M-Pesa - verify edge function is deployed
    try {
      const start = Date.now()
      const res = await fetch("https://gcnefnqtjxtqbhynyoxe.supabase.co/functions/v1/daraja-stk-push", {
        method:"POST",
