                        const cutoff = new Date(Date.now()-24*60*60*1000).toISOString()
                        await supabase.from("bookings").update({status:"cancelled"}).eq("status","pending").lt("created_at",cutoff)
                        toast.success("Stuck bookings cancelled")
                        scanPlatform()
                      }} style={{ background:"#e24b4a", border:"none", borderRadius:7, color:"#fff", fontSize:11, padding:"6px 12px", cursor:"pointer", fontWeight:600 }}>
                        Cancel {report.platformData.stuck_bookings} stuck bookings
                      </button>
                    )}
                                        {report.platformData.inactive_customers_30days>0&&(
                      <button onClick={async()=>{
                        if(!confirm("Send re-engagement notification to "+report.platformData.inactive_customers_30days+" inactive customers?")) return
                        const { data: inactive } = await supabase.from("profiles").select("id").eq("role","customer").lt("updated_at", new Date(Date.now()-30*24*60*60*1000).toISOString())
                        if(inactive?.length>0) {
                          await supabase.from("notifications").insert(inactive.map(u=>({
                            user_id:u.id,
                            title:"We miss you! ≡ƒÜù",
                            message:"Book a service today and earn double loyalty points. Use code WELCOME back for 10% off.",
                            type:"info"
                          })))
                          toast.success("Re-engagement notifications sent!")
                        }
                        scanPlatform()
                      }} style={{ background:"#378add", border:"none", borderRadius:7, color:"#fff", fontSize:11, padding:"6px 12px", cursor:"pointer", fontWeight:600 }}>
                        Re-engage {report.platformData.inactive_customers_30days} inactive customers ≡ƒôº
                      </button>
                    )}
                  </div>
                </div>
              )}
              {/* Feature sync checklist */}
              <div style={{ background:"#ffffff", borderRadius:10, padding:"1rem", marginBottom:"1rem" }}>
                <div style={{ fontSize:12, fontWeight:600, color:"#000000", marginBottom:10 }}>≡ƒöä Feature Sync Checklist</div>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6 }}>
                  {[
          { f:"Customer booking", ok:true },
                    { f:"Payments (M-Pesa)", ok:report.platformData.api_health?.daraja?.status==="ok" },
          { f:"GO Service", ok:true },
          { f:"Marketplace", ok:true },
          { f:"Driver verification", ok:true },
          { f:"Reviews", ok:true },
          { f:"Escrow payments", ok:report.platformData.held_payments>=0 },
          { f:"Service bundles", ok:true },
          { f:"Provider support", ok:report.platformData.provider_tickets>=0 },
          { f:"Two-sided reviews", ok:report.platformData.customer_ratings_given>=0 },
                    { f:"Service claims", ok:report.platformData.total_claims>=0 },
                    { f:"Notifications", ok:report.platformData.total_notifications>0 },
          { f:"Chat system", ok:true },
          { f:"Loyalty points", ok:true },
                    { f:"Mechanics", ok:report.platformData.total_mechanics>=0 },
          { f:"Marketplace inspect", ok:true },
                    { f:"Employee mgmt", ok:report.platformData.total_employees>=0 },
                    { f:"Payment tracking", ok:report.platformData.total_payments>=0 },
                    { f:"AI Monitor", ok:true },
                    { f:"Provider types", ok:Object.keys(report.platformData.provider_type_breakdown||{}).length>0 },
                    { f:"Boda boda drivers", ok:report.platformData.boda_boda_drivers>=0 },
                    { f:"Inventory system", ok:report.platformData.parts_inventory_items>=0 },
                    { f:"Parts marketplace", ok:report.platformData.total_marketplace_transactions>=0 },
                    { f:"Order management", ok:report.platformData.pending_orders>=0 },
                    { f:"Promo codes", ok:report.platformData.total_promo_codes>0 },
          { f:"Vouchers", ok:true },
          { f:"Driver documents", ok:true },
          { f:"Support messages", ok:true },
          { f:"Favorites/wishlist", ok:true },
                    { f:"Referral program", ok:report.platformData.total_referrals>=0 },
                    { f:"Push notifications", ok:report.platformData.total_device_tokens>0 },
                  ].map(item=>(
                    <div key={item.f} style={{ display:"flex", alignItems:"center", gap:6, padding:"4px 0" }}>
                      <span style={{ fontSize:10, color:item.ok?"#1d9e75":"#e24b4a", flexShrink:0 }}>{item.ok?"Γ£à":"Γ¥î"}</span>
                      <span style={{ fontSize:11, color:item.ok?"#888":"#e24b4a" }}>{item.f}</span>
                    </div>
                  ))}
                </div>
              </div>

              <div style={{ borderTop:"1px solid #eeeeee", paddingTop:"1rem" }}>
                <div style={{ fontSize:11, color:"#8b5cf6", marginBottom:8, fontWeight:600 }}>Ask AI about any issue:</div>
                <div style={{ maxHeight:200, overflowY:"auto", marginBottom:8, display:"flex", flexDirection:"column", gap:6 }}>
                  {chatMessages.slice(1).map((m,i)=>(
                    <div key={i} style={{ display:"flex", justifyContent:m.role==="user"?"flex-end":"flex-start" }}>
                      <div style={{ maxWidth:"85%", padding:"8px 12px", borderRadius:m.role==="user"?"12px 12px 4px 12px":"12px 12px 12px 4px", background:m.role==="user"?"#8b5cf6":"#f5f5f5", color:"#000000", fontSize:12, lineHeight:1.5, whiteSpace:"pre-wrap" }}>
                        {m.content}
                        {m.needsConfirmation&&(
                          <div style={{ display:"flex", gap:6, marginTop:8 }}>
                            <button onClick={()=>confirmAction(m.needsConfirmation)} disabled={chatLoading}
                              style={{ background:"#e24b4a", border:"none", borderRadius:6, color:"#fff", fontSize:11, fontWeight:700, padding:"5px 12px", cursor:"pointer" }}>
                              Confirm
                            </button>
                            <button onClick={()=>{ const updated=[...chatMessages]; updated[i+1]={...updated[i+1],needsConfirmation:null}; setChatMessages(updated) }}
                              style={{ background:"none", border:"1px solid #ddd", borderRadius:6, color:"#888", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>
                              Cancel
                            </button>
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                  {chatLoading&&<div style={{ fontSize:20, color:"#888", letterSpacing:4 }}>ΓÇóΓÇóΓÇó</div>}
                </div>
                <form onSubmit={sendChat} style={{ display:"flex", gap:8 }}>
                  <input value={chatInput} onChange={e=>setChatInput(e.target.value)}
                    placeholder="e.g. Cancel stuck bookings, show claim details..."
                    style={{ flex:1, background:"#ffffff", border:"1px solid #f0f0f0", borderRadius:8, padding:"8px 12px", color:"#000000", fontSize:12, outline:"none" }}/>
                  <button type="submit" disabled={!chatInput.trim()||chatLoading}
                    style={{ background:chatInput.trim()&&!chatLoading?"#8b5cf6":"#f0f0f0", border:"none", borderRadius:8, color:chatInput.trim()&&!chatLoading?"#fff":"#555", fontSize:14, padding:"0 14px", cursor:"pointer" }}>
                    Γ₧ñ
                  </button>
                </form>
              </div>
            </>
          )}
      {/* CODE DIAGNOSTICS */}
      <div style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem", marginTop:"1.25rem" }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#000000" }}>≡ƒöì Code Diagnostics</div>
          <button onClick={scanCode} disabled={scanning}
            style={{ background:scanning?"#e0e0e0":"#8b5cf6", border:"none", borderRadius:8, color:"#fff", fontSize:12, fontWeight:600, padding:"6px 14px", cursor:scanning?"not-allowed":"pointer" }}>
            {scanning?"Scanning...":"Scan source code"}
          </button>
        </div>
        {!codeScan&&<div style={{ fontSize:12, color:"#888" }}>Click scan to check source files for common React errors.</div>}
        {codeScan&&(
          <div>
            <div style={{ fontSize:11, color:"#888", marginBottom:8 }}>Scanned {codeScan.filesScanned} files ┬╖ {codeScan.scannedAt}</div>
            {codeScan.issues.length===0&&<div style={{ fontSize:12, color:"#1d9e75" }}>Γ£à No issues found!</div>}
            {codeScan.issues.map((issue,i)=>(
              <div key={i} style={{ background:"#fff5f5", border:"1px solid #e24b4a30", borderRadius:8, padding:"0.75rem", marginBottom:6 }}>
                <div style={{ fontSize:11, color:"#e24b4a", fontWeight:600, marginBottom:2 }}>ΓÜá∩╕Å {issue.file} ΓÇö Line {issue.line}</div>
                <div style={{ fontSize:11, color:"#888", marginBottom:4, fontFamily:"monospace" }}>{issue.code}</div>
                <div style={{ fontSize:11, color:"#888" }}>{issue.issue}</div>
              </div>
            ))}
          </div>
        )}
      </div>
        </div>
      )}
      {/* LIVE ERROR TRACKER */}
      <div style={{ background:"#f8f8f8", border:"1px solid #e24b4a30", borderRadius:12, padding:"1.25rem", marginTop:"1.25rem" }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#e24b4a" }}>≡ƒö┤ Live Error Tracker</div>
          <div style={{ display:"flex", gap:8 }}>
            <button onClick={loadErrorLogs} disabled={loadingErrors}
              style={{ background:"#e24b4a", border:"none", borderRadius:8, color:"#fff", fontSize:11, fontWeight:600, padding:"5px 12px", cursor:"pointer" }}>
              {loadingErrors?"Loading...":"Refresh errors"}
            </button>
            {errorLogs.length>0&&<button onClick={clearErrorLogs}
              style={{ background:"#e0e0e0", border:"none", borderRadius:8, color:"#888", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>
              Clear
            </button>}
          </div>
        </div>
        {errorLogs.length===0&&<div style={{ fontSize:12, color:"#888" }}>No errors logged yet. Click Refresh after reproducing an error.</div>}
        {errorLogs.map((e,i)=>(
          <div key={e.id||i} style={{ background:"#fff5f5", border:"1px solid #e24b4a20", borderRadius:8, padding:"0.75rem", marginBottom:6 }}>
            <div style={{ display:"flex", justifyContent:"space-between", marginBottom:4, flexWrap:"wrap", gap:4 }}>
              <span style={{ fontSize:10, color:"#e24b4a", fontWeight:600 }}>{e.user_role}{e.provider_type?" ("+e.provider_type+")":""} ┬╖ {e.page_url}</span>
              <span style={{ fontSize:10, color:"#888" }}>{new Date(e.created_at).toLocaleTimeString()}</span>
            </div>
            <div style={{ fontSize:11, color:"#000000", marginBottom:2, fontFamily:"monospace", wordBreak:"break-all" }}>{e.error_message}</div>
            <div style={{ fontSize:10, color:"#888" }}>{e.error_source} ┬╖ line {e.error_line}:{e.error_col}</div>
          </div>
        ))}
      </div>
    </div>
  )
}

import { ProfileIcon, LocationIcon, VehicleIcon, ServicesIcon, NoteIcon } from "../../lib/cccIcons"
import useIsMobile from "../../lib/useIsMobile"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { auditLog, AUDIT_ACTIONS } from "../../lib/auditLog"
import toast from "react-hot-toast"
import { useAuth } from "../../contexts/AuthContext"

const SC = { pending:"#e6821e", confirmed:"#378add", "in-progress":"#8b5cf6", completed:"#1d9e75", cancelled:"#e24b4a" }
const SB = { pending:"#fff8f0", confirmed:"#eff6ff", "in-progress":"#f5f3ff", completed:"#f0fdf4", cancelled:"#fff5f5" }
const PC = { paid:"#1d9e75", pending:"#e6821e", partial:"#378add", refunded:"#8b5cf6" }

export default function AdminBookings() {
  const { user, profile } = useAuth()
  if(!user || profile?.role !== "admin") return null
  const isMobile = useIsMobile()
  const [bookings, setBookings] = useState([])
  const [filter, setFilter] = useState("all")
  const [payFilter, setPayFilter] = useState("all")
  const [search, setSearch] = useState("")
  const [loading, setLoading] = useState(true)
  const [expanded, setExpanded] = useState(null)
  const [updating, setUpdating] = useState(null)
  const [refundModal, setRefundModal] = useState(null)
  const [refundAmount, setRefundAmount] = useState("")
  const [refundReason, setRefundReason] = useState("")
  const [refundPhone, setRefundPhone] = useState("")
  const [processingRefund, setProcessingRefund] = useState(false)

  useEffect(() => {
    load()
    const sub = supabase.channel("admin-bookings-page")
      .on("postgres_changes", { event:"*", schema:"public", table:"bookings" }, () => load())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [])

  async function load() {
    const { data: bks } = await supabase.from("bookings").select("*").eq("is_archived", false).order("created_at", { ascending:false })
    if (!bks?.length) { setBookings([]); setLoading(false); return }
    const userIds = [...new Set([...bks.map(b=>b.customer_id), ...bks.map(b=>b.provider_id)].filter(Boolean))]
    const { data: profs } = await supabase.from("profile_public").select("id,first_name,last_name,business_name").in("id", userIds)
    const profMap = {}
    profs?.forEach(p => { profMap[p.id] = p })
    setBookings(bks.map(b => ({...b, customer:profMap[b.customer_id]||null, provider:profMap[b.provider_id]||null})))
    setLoading(false)
  }

  async function updateStatus(id, status) {
    setUpdating(id)
    await supabase.from("bookings").update({ status }).eq("id", id)
    const booking = bookings.find(b=>b.id===id)
    if (booking?.customer_id) {
      const msgs = { confirmed:"Your booking has been confirmed Γ£à", "in-progress":"Your service is now in progress ≡ƒöº", completed:"Your service has been completed Γ£à Please leave a review!", cancelled:"Your booking has been cancelled Γ¥î" }
      if (msgs[status]) {
        await supabase.from("notifications").insert({ user_id: booking.customer_id, title: msgs[status], message: booking.service_name+" #"+booking.booking_number, type: status==="cancelled"?"error":status==="completed"?"success":"info" })
      }
    }
    toast.success("Booking "+status)
    load()
    setUpdating(null)
}

  async function updatePayment(id, payment_status) {
    setUpdating(id)
    await supabase.from("bookings").update({ payment_status }).eq("id", id)
    toast.success(`Payment marked as ${payment_status}`)
    load()
    setUpdating(null)
  }

  async function openRefundModal(b) {
    setRefundAmount(String(b.total_amount))
    setRefundReason("")
    setRefundPhone("")
    setRefundModal(b)
  }

  async function processRefund() {
    if (!refundAmount || !refundReason) return toast.error("Amount and reason required")
    if (!refundPhone) return toast.error("Customer M-Pesa number required")
    setProcessingRefund(true)
    try {
      // Record refund in database
      await supabase.from("refund_requests").insert({
        booking_id: refundModal.id,
        customer_id: refundModal.customer_id,
        amount: Number(refundAmount),
        reason: refundReason,
        customer_phone: refundPhone,
        status: "pending",
        original_amount: Number(refundModal.total_amount),
      })
      // Update booking payment status
      await supabase.from("bookings").update({
        payment_status: "refunded",
        status: "cancelled"
      }).eq("id", refundModal.id)
      // Notify customer
      await supabase.from("notifications").insert({
        user_id: refundModal.customer_id,
        title: "Refund initiated ≡ƒÆ╕",
        message: `Your refund of KES ${Number(refundAmount).toLocaleString()} for "${refundModal.service_name}" is being processed. You will receive it on ${refundPhone} shortly.`,
        type: "info"
      })
      toast.success(`Refund of KES ${Number(refundAmount).toLocaleString()} recorded! Send money to ${refundPhone} via M-Pesa`)
      setRefundModal(null)
      setRefundAmount("")
      setRefundReason("")
      setRefundPhone("")
      load()
    } catch(e) { toast.error(e.message) }
    finally { setProcessingRefund(false) }
  }

  const filtered = bookings.filter(b => {
    const matchStatus = filter==="all" || b.status===filter
    const matchPay = payFilter==="all" || b.payment_status===payFilter
    const matchSearch = !search || 
      b.booking_number?.toLowerCase().includes(search.toLowerCase()) ||
      b.service_name?.toLowerCase().includes(search.toLowerCase()) ||
      `${b.customer?.first_name} ${b.customer?.last_name}`.toLowerCase().includes(search.toLowerCase()) ||
      b.provider?.business_name?.toLowerCase().includes(search.toLowerCase())
    return matchStatus && matchPay && matchSearch
  })

  const stats = {
    total: bookings.length,
    pending: bookings.filter(b=>b.status==="pending").length,
    confirmed: bookings.filter(b=>b.status==="confirmed").length,
    completed: bookings.filter(b=>b.status==="completed").length,
    revenue: bookings.filter(b=>b.payment_status==="paid").reduce((s,b)=>s+Number(b.platform_commission||0),0)
  }

  return (
    <div>
      {/* Stats */}
      <div style={{ display:"grid", gridTemplateColumns:isMobile?"repeat(2,1fr)":"repeat(5,1fr)", gap:8, marginBottom:"1.25rem" }}>
        {[
          { label:"Total", value:stats.total, color:"#000" },
          { label:"Pending", value:stats.pending, color:"#e6821e" },
          { label:"Confirmed", value:stats.confirmed, color:"#378add" },
          { label:"Completed", value:stats.completed, color:"#1d9e75" },
          { label:"Commission", value:`KES ${stats.revenue.toLocaleString()}`, color:"#8b5cf6" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.75rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontSize:10, color:"#888", textTransform:"uppercase", marginBottom:4 }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:s.color }}>{s.value}</div>
          </div>
        ))}
      </div>

      {/* Search */}
      <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search by booking #, customer, provider, service..."
        style={{ width:"100%", background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:8, padding:"10px 14px", fontSize:13, outline:"none", marginBottom:10, fontFamily:"DM Sans,sans-serif" }}/>

      {/* Filters */}
      <div style={{ display:"flex", gap:6, marginBottom:6, flexWrap:"wrap" }}>
        {["all","pending","confirmed","in-progress","completed","cancelled"].map(s=>(
          <button key={s} onClick={()=>setFilter(s)} style={{ padding:"6px 12px", borderRadius:6, border:"none", fontSize:11, cursor:"pointer", background:filter===s?"#e6821e":"#f8f8f8", color:filter===s?"#fff":"#666" }}>
            {s==="all"?"All statuses":s}
          </button>
        ))}
      </div>
      <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap" }}>
        {["all","paid","pending","partial","refunded"].map(s=>(
          <button key={s} onClick={()=>setPayFilter(s)} style={{ padding:"5px 10px", borderRadius:6, border:"none", fontSize:11, cursor:"pointer", background:payFilter===s?"#8b5cf6":"#f8f8f8", color:payFilter===s?"#fff":"#666" }}>
            {s==="all"?"All payments":s}
          </button>
        ))}
      </div>

      <div style={{ fontSize:12, color:"#888", marginBottom:10 }}>{filtered.length} booking{filtered.length!==1?"s":""}</div>

      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}

      {filtered.map(b=>(
        <div key={b.id} style={{ background:"#f8f8f8", border:"1px solid #eee", borderLeft:`4px solid ${SC[b.status]||"#eee"}`, borderRadius:10, padding:"1rem", marginBottom:8 }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:6 }}>
            <div style={{ flex:1, minWidth:0, marginRight:8 }}>
              <div style={{ fontSize:13, fontWeight:600, color:"#000", marginBottom:2 }}>{b.service_name}</div>
              <div style={{ fontSize:11, color:"#888" }}>
                ≡ƒæñ {b.customer?.first_name} {b.customer?.last_name} {""}
              </div>
              <div style={{ fontSize:11, color:"#888" }}>
                ≡ƒÅ¬ {b.provider?.business_name||`${b.provider?.first_name} ${b.provider?.last_name}`}
              </div>
              <div style={{ fontSize:10, color:"#aaa", marginTop:2 }}>#{b.booking_number} ┬╖ {b.booking_date} {b.booking_time?.slice(0,5)}</div>
              {(b.before_photo_url||b.after_photo_url)&&(
                <div style={{ display:"flex", gap:6, marginTop:6 }}>
                  {b.before_photo_url&&<img src={b.before_photo_url} alt="Before" style={{ width:40, height:40, objectFit:"cover", borderRadius:6, border:"1px solid #eee" }}/>}
                  {b.after_photo_url&&<img src={b.after_photo_url} alt="After" style={{ width:40, height:40, objectFit:"cover", borderRadius:6, border:"1px solid #eee" }}/>}
                </div>
              )}
            </div>
            <div style={{ textAlign:"right", flexShrink:0 }}>
              <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:SB[b.status]||"#f8f8f8", color:SC[b.status]||"#888", border:`1px solid ${SC[b.status]||"#888"}30`, display:"block", marginBottom:4 }}>{b.status}</span>
              <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:`${PC[b.payment_status]||"#888"}15`, color:PC[b.payment_status]||"#888", display:"block", marginBottom:4 }}>{b.payment_status}</span>
              <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#e6821e" }}>KES {Number(b.total_amount).toLocaleString()}</div>
            </div>
          </div>

          <div style={{ display:"flex", gap:6, flexWrap:"wrap", alignItems:"center" }}>
            <button onClick={()=>setExpanded(expanded===b.id?null:b.id)}
              style={{ background:"none", border:"1px solid #ddd", borderRadius:6, color:"#555", fontSize:11, padding:"4px 10px", cursor:"pointer" }}>
              {expanded===b.id?"Hide details":"View details"}
            </button>
            {b.status==="pending"&&<button onClick={()=>updateStatus(b.id,"confirmed")} disabled={updating===b.id} style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:6, color:"#378add", fontSize:11, padding:"4px 10px", cursor:"pointer" }}>Confirm</button>}
            {b.status==="confirmed"&&<button onClick={()=>updateStatus(b.id,"in-progress")} disabled={updating===b.id} style={{ background:"#f5f3ff", border:"1px solid #8b5cf640", borderRadius:6, color:"#8b5cf6", fontSize:11, padding:"4px 10px", cursor:"pointer" }}>Start</button>}
            {b.status==="in-progress"&&<button onClick={()=>updateStatus(b.id,"completed")} disabled={updating===b.id} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:6, color:"#1d9e75", fontSize:11, padding:"4px 10px", cursor:"pointer" }}>Complete</button>}
            {b.payment_status==="pending"&&<button onClick={()=>updatePayment(b.id,"paid")} disabled={updating===b.id} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:6, color:"#1d9e75", fontSize:11, padding:"4px 10px", cursor:"pointer" }}>Mark paid</button>}
            {!["completed","cancelled"].includes(b.status)&&<button onClick={()=>updateStatus(b.id,"cancelled")} disabled={updating===b.id} style={{ background:"none", border:"1px solid #e24b4a30", borderRadius:6, color:"#e24b4a", fontSize:11, padding:"4px 10px", cursor:"pointer" }}>Cancel</button>}
            {b.payment_status==="paid"&&<button onClick={()=>openRefundModal(b)} style={{ background:"#faf5ff", border:"1px solid #8b5cf640", borderRadius:6, color:"#8b5cf6", fontSize:11, padding:"4px 10px", cursor:"pointer" }}>≡ƒÆ╕ Refund</button>}
          </div>

          {expanded===b.id&&(
            <div style={{ marginTop:10, paddingTop:10, borderTop:"1px solid #eeeeee" }}>
              <div style={{ display:"grid", gridTemplateColumns:"repeat(2,1fr)", gap:8, fontSize:11 }}>
                {[
                  {l:"Booking ID", v:b.id},
