export default function AdminCategories() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const isMobile = useIsMobile()
  const [categories, setCategories] = useState([])
  const [form, setForm] = useState({ name:"", icon:"≡ƒöº", description:"" })
  const [editing, setEditing] = useState(null)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)

  useEffect(() => { load() }, [])

  async function load() {
    const { data } = await supabase.from("service_categories").select("*").order("name")
    if (data && data.length > 0) {
      setCategories(data)
    } else {
      setCategories(DEFAULT_CATEGORIES.map((c,i) => ({ ...c, id:i+1, is_active:true, service_count:0 })))
    }
    setLoading(false)
  }

  async function save(e) {
    e.preventDefault()
    setSaving(true)
    try {
      if (editing) {
        const { error } = await supabase.from("service_categories")
          .update({ name:form.name, icon:form.icon, description:form.description })
          .eq("id", editing)
        if (error) throw error
        toast.success("Category updated")
        setEditing(null)
      } else {
        const { error } = await supabase.from("service_categories")
          .insert({ name:form.name, icon:form.icon, description:form.description, is_active:true })
        if (error) throw error
        toast.success("Category added")
      }
      setForm({ name:"", icon:"≡ƒöº", description:"" })
      load()
    } catch(err) {
      toast.error(err.message)
    } finally { setSaving(false) }
  }

  async function toggleActive(id, is_active) {
    await supabase.from("service_categories").update({ is_active:!is_active }).eq("id", id)
    toast.success(is_active ? "Category hidden" : "Category visible")
    load()
  }

  async function deleteCategory(id, name) {
    if (!confirm(`Delete category "${name}"? Services using this category will be unaffected.`)) return
    await supabase.from("service_categories").delete().eq("id", id)
    toast.success("Category deleted")
    load()
  }

  function startEdit(c) {
    setEditing(c.id)
    setForm({ name:c.name, icon:c.icon||"≡ƒöº", description:c.description||"" })
    window.scrollTo({ top:document.body.scrollHeight, behavior:"smooth" })
  }

  const inp = { width:"100%", background:"#ffffff", border:"1px solid #f0f0f0", borderRadius:8, padding:"10px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif", marginBottom:10 }
  const lbl = { fontSize:11, color:"#888", textTransform:"uppercase", letterSpacing:"0.05em", display:"block", marginBottom:4 }

  return (
    <div>
      <div style={{ display:"grid", gridTemplateColumns:isMobile?"repeat(2,1fr)":"repeat(3,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Total categories", value:categories.length },
          { label:"Active", value:categories.filter(c=>c.is_active!==false).length, color:"#1d9e75" },
          { label:"Hidden", value:categories.filter(c=>c.is_active===false).length },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"1rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontSize:11, color:"#888", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:6 }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:22, fontWeight:800, color:s.color||"#000000" }}>{s.value}</div>
          </div>
        ))}
      </div>

      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}

      <div style={{ display:"grid", gap:8, marginBottom:"1.5rem" }}>
        {categories.map(c=>(
          <div key={c.id} style={{ background:"#f8f8f8", border:`1px solid ${c.is_active===false?"#e24b4a20":"#eeeeee"}`, borderRadius:10, padding:"1rem", display:"flex", alignItems:"center", gap:12 }}>
            <div style={{ width:44, height:44, borderRadius:10, background:"#f5f5f5", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>
              {c.icon==="oil"?<OilIcon size={22} color="#e6821e"/>:
               c.icon==="vehicle"?<VehicleIcon size={22} color="#e6821e"/>:
               c.icon==="services"?<ServicesIcon size={22} color="#e6821e"/>:
               c.icon==="discover"?<DiscoverIcon size={22} color="#e6821e"/>:
               c.icon==="power"?<PowerIcon size={22} color="#e6821e"/>:
               c.icon==="settings"?<SettingsIcon size={22} color="#e6821e"/>:
               c.icon==="note"?<NoteIcon size={22} color="#e6821e"/>:
               c.icon==="towing"?<TowingIcon size={22} color="#e6821e"/>:
               c.icon==="aircon"?<AirconIcon size={22} color="#e6821e"/>:
               c.icon==="mechanic"?<MechanicIcon size={22} color="#e6821e"/>:
               c.icon==="globe"?<GlobeIcon size={22} color="#e6821e"/>:
               <ServicesIcon size={22} color="#e6821e"/>}
            </div>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:2 }}>
                <div style={{ fontSize:13, fontWeight:600, color:c.is_active===false?"#555":"#000000" }}>{c.name}</div>
                {c.is_active===false&&<span style={{ fontSize:10, color:"#e24b4a", background:"#fff5f5", padding:"1px 6px", borderRadius:10 }}>Hidden</span>}
              </div>
              {c.description&&<div style={{ fontSize:11, color:"#888" }}>{c.description}</div>}
            </div>
            <div style={{ display:"flex", gap:6, flexShrink:0 }}>
              <button onClick={()=>startEdit(c)}
                style={{ background:"none", border:"1px solid #dddddd", borderRadius:7, color:"#888", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                Edit
              </button>
              {typeof c.is_active !== "undefined" && (
                <button onClick={()=>toggleActive(c.id, c.is_active)}
                  style={{ background:"none", border:`1px solid ${c.is_active===false?"#1d9e7540":"#e24b4a40"}`, borderRadius:7, color:c.is_active===false?"#1d9e75":"#e24b4a", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                  {c.is_active===false?"Show":"Hide"}
                </button>
              )}
              <button onClick={()=>deleteCategory(c.id, c.name)}
                style={{ background:"none", border:"1px solid #e24b4a40", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                Delete
              </button>
            </div>
          </div>
        ))}
      </div>

      <div style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:"1rem", color:"#000000" }}>
          {editing ? "Edit category" : "Add new category"}
        </div>
        <form onSubmit={save}>
          <div style={{ display:"grid", gridTemplateColumns:"80px 1fr", gap:10 }}>
            <div>
              <label style={lbl}>Icon</label>
              <input style={inp} placeholder="≡ƒöº" value={form.icon} onChange={e=>setForm(f=>({...f,icon:e.target.value}))} maxLength={4}/>
            </div>
            <div>
              <label style={lbl}>Category name</label>
              <input style={inp} placeholder="e.g. Suspension Repair" value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))} required/>
            </div>
          </div>
          <label style={lbl}>Description</label>
          <input style={inp} placeholder="Brief description of this category" value={form.description} onChange={e=>setForm(f=>({...f,description:e.target.value}))}/>
          <div style={{ display:"flex", gap:8 }}>
            <button type="submit" disabled={saving}
              style={{ background:saving?"#e0e0e0":"#8b5cf6", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"10px 20px", cursor:saving?"not-allowed":"pointer" }}>
              {saving?"Saving...":editing?"Update category":"Add category"}
            </button>
            {editing&&(
              <button type="button" onClick={()=>{ setEditing(null); setForm({ name:"", icon:"≡ƒöº", description:"" }) }}
                style={{ background:"none", border:"1px solid #dddddd", borderRadius:8, color:"#888", fontSize:13, padding:"10px 20px", cursor:"pointer" }}>
                Cancel
              </button>
            )}
          </div>
        </form>
      </div>
    </div>
  )
}

import { ShieldIcon, WarningIcon, CameraIcon, ChatIcon } from "../../lib/cccIcons"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"
import ClaimChat from "../shared/ClaimChat"

function generateVoucherCode() {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
  const segments = [4,4,4].map(len=>Array.from({length:len},()=>chars[Math.floor(Math.random()*chars.length)]).join(""))
  return "CCC-" + segments.join("-")
}

export default function AdminClaims() {
  const { user } = useAuth()
  const isMobile = useIsMobile()
  const [claims, setClaims] = useState([])
  const [penalties, setPenalties] = useState([])
  const [loading, setLoading] = useState(true)
  const [tab, setTab] = useState("claims")
  const [claimDirection, setClaimDirection] = useState("all")
  const [selected, setSelected] = useState(null)
  const [adminNotes, setAdminNotes] = useState("")
  const [processing, setProcessing] = useState(false)
  const [chattingWith, setChattingWith] = useState(null) // {claimId, userId, name, role}
  const [claimMessages, setClaimMessages] = useState([])
  useEffect(() => {
    if(!user) return
    // Remove stale channels first
    supabase.getChannels().forEach(ch => {
      if(ch.topic === "realtime:admin-claims-live") supabase.removeChannel(ch)
    })
    const sub = supabase.channel("admin-claims-live")
      .on("postgres_changes", { event:"*", schema:"public", table:"service_claims" }, () => load())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [])
  async function loadClaimMessages() {
    const { data } = await supabase.from("chat_messages")
      .select("*, profiles!chat_messages_sender_id_fkey(first_name,last_name,role)")
      .not("claim_id","is",null)
      .eq("is_read",false)
      .neq("sender_id",user.id)
      .order("created_at",{ascending:false})
    setClaimMessages(data||[])
  }


  async function load() {
    const [{ data: cls }, { data: pens }] = await Promise.all([
      supabase.from("service_claims")
        .select("*, bookings(service_name,booking_number,booking_date,total_amount,provider_id), orders(order_number,subtotal,created_at,provider_id), customer:profiles!service_claims_customer_id_fkey(first_name,last_name), provider:profiles!service_claims_provider_id_fkey(first_name,last_name,business_name), driver:profiles!service_claims_driver_id_fkey(first_name,last_name), claimant:profiles!service_claims_claimant_id_fkey(first_name,last_name,role), against:profiles!service_claims_against_id_fkey(first_name,last_name,role)")
        .order("created_at",{ascending:false}),
      supabase.from("provider_penalties").select("*, profiles(first_name,last_name,business_name)").order("created_at",{ascending:false}),
    ])
    setClaims(cls||[])
    setPenalties(pens||[])
    setLoading(false)
  }

  async function requestEvidence(claim) {
    try {
      await supabase.from("notifications").insert([
        { user_id:claim.customer_id, title:"Evidence requested ≡ƒô╕", message:"Admin has requested additional evidence for your claim #"+claim.id?.slice(0,8).toUpperCase()+". Please add photos or details in the claim chat.", type:"warning" },
        { user_id:claim.provider_id, title:"Evidence requested ≡ƒô╕", message:"Admin has requested your response and evidence for claim #"+claim.id?.slice(0,8).toUpperCase()+". Please respond in the claim chat.", type:"warning" }
      ])
      await supabase.from("service_claims").update({ status:"under_review" }).eq("id",claim.id)
      toast.success("Evidence requested from both parties")
      load()
    } catch(e) { toast.error(e.message) }
  }
    async function approveClaim(claim) {
    setProcessing(true)
    try {
      const voucherCode = generateVoucherCode()
      const amount = Number(claim.bookings?.total_amount||0)
      const expires = new Date(Date.now()+30*24*60*60*1000).toISOString()

      // Get provider penalty count
      const { data: existingPenalties } = await supabase.from("provider_penalties")
        .select("id").eq("provider_id",claim.provider_id).eq("is_active",true)
      const penaltyCount = existingPenalties?.length||0

      let penaltyType = "warning"
      let suspendUntil = null
      let suspendProvider = false
      if (penaltyCount===1) { penaltyType="suspension_7d"; suspendUntil=new Date(Date.now()+7*24*60*60*1000).toISOString(); suspendProvider=true }
      if (penaltyCount>=2) { penaltyType="permanent_ban"; suspendProvider=true }

      await Promise.all([
        // Update claim status
        supabase.from("service_claims").update({ status:"approved", admin_notes:adminNotes, resolved_by:user.id, resolved_at:new Date().toISOString() }).eq("id",claim.id),
        // Close out original booking payment - provider must NOT be paid, customer got a voucher instead
        supabase.from("bookings").update({ payment_held:false, payment_released:false, payment_status:"refunded_as_voucher" }).eq("id", claim.booking_id),

        // Create voucher for customer
        supabase.from("service_vouchers").insert({
          claim_id: claim.id,
          customer_id: claim.customer_id,
          voucher_code: voucherCode,
          original_booking_id: claim.booking_id,
          original_provider_id: claim.provider_id,
          amount: amount,
          expires_at: expires,
        }),

        // Record provider penalty
        supabase.from("provider_penalties").insert({
          provider_id: penalizedId,
          claim_id: claim.id,
          penalty_type: penaltyType,
          amount_deducted: amount,
          reason: `Service claim approved ΓÇö ${claim.reason}`,
          is_active: true,
          expires_at: suspendUntil,
          applied_by: user.id,
        }),

        // Save voucher to database
        supabase.from("vouchers").insert({
          code: voucherCode,
          customer_id: claim.customer_id,
          value: amount,
          original_value: amount,
          claim_id: claim.id,
          expires_at: expires,
        }),
        // Notify customer
        supabase.from("notifications").insert({
          user_id: claim.customer_id,
          title: "Claim approved ΓÇö voucher issued! ≡ƒÄƒ∩╕Å",
          message: `Your service claim has been approved. We have issued a service voucher worth KES ${amount.toLocaleString()} (code: ${voucherCode}). Valid for 30 days. Use it to rebook with any other provider at no charge.`,
          type: "success",
        }),

        // Notify penalized party
        supabase.from("notifications").insert({
          user_id: penalizedId,
          title: isProviderClaim ? "Service claim against you ΓÜá∩╕Å" : "Claim filed against you by provider ΓÜá∩╕Å",
          message: `A service claim has been approved regarding booking #${claim.bookings?.booking_number}. Penalty: ${penaltyType.replace(/_/g," ")}. Reason: ${claim.reason}.`,
          type: "error",
        }),
      ])

      // Suspend provider if needed
      if (suspendProvider) {
        await supabase.from("profiles").update({
          is_active: penaltyType!=="permanent_ban",
          is_suspended: penaltyType==="suspension_7d" || penaltyType==="suspension_30d",
          is_banned: penaltyType==="permanent_ban",
          suspension_expires_at: suspendUntil
        }).eq("id",penalizedId)
      }

      toast.success(`Claim approved ΓÇö voucher ${voucherCode} issued to customer`)
      setSelected(null)
      setAdminNotes("")
      load()
    } catch(err) {
      toast.error(err.message)
    } finally {
      setProcessing(false)
    }
  }

  async function rejectClaim(claimId) {
    if (!adminNotes) return toast.error("Please add a reason for rejection")
    setProcessing(true)
    try {
      const claim = claims.find(c=>c.id===claimId)
      await Promise.all([
        supabase.from("service_claims").update({ status:"rejected", admin_notes:adminNotes, resolved_by:user.id, resolved_at:new Date().toISOString() }).eq("id",claimId),
        supabase.from("notifications").insert({
          user_id: claim.customer_id,
          title: "Claim update",
          message: `Your service claim has been reviewed. Decision: Not approved. Reason: ${adminNotes}. Contact support if you have questions.`,
          type: "warning",
        }),
      ])
      toast.success("Claim rejected")
      setSelected(null)
      setAdminNotes("")
      load()
    } catch(err) {
      toast.error(err.message)
    } finally {
      setProcessing(false)
    }
  }

  async function issueCashRefund(claim) {
    if (!adminNotes) return toast.error("Please add reason for cash refund exception")
    if (!confirm("Issue cash refund? This is an exception ΓÇö use only when voucher is not appropriate.")) return
    setProcessing(true)
    try {
      const amount = Number(claim.bookings?.total_amount||0)
      await Promise.all([
        supabase.from("service_claims").update({ status:"approved", admin_notes:`CASH REFUND: ${adminNotes}`, resolved_by:user.id, resolved_at:new Date().toISOString() }).eq("id",claim.id),
        supabase.from("bookings").update({ payment_held:false, payment_released:false, payment_status:"refunded_cash" }).eq("id", claim.booking_id),
        supabase.from("notifications").insert({ user_id:claim.customer_id, title:"Cash refund approved ≡ƒÆ░", message:`A cash refund of KES ${amount.toLocaleString()} has been approved. Allow 3-5 business days for processing.`, type:"success" }),
        supabase.from("notifications").insert({ user_id:claim.provider_id, title:"Cash refund issued against you ΓÜá∩╕Å", message:`A cash refund of KES ${amount.toLocaleString()} was issued due to: ${claim.reason}. Deducted from your earnings.`, type:"error" }),
        supabase.from("provider_penalties").insert({ provider_id:claim.provider_id, claim_id:claim.id, penalty_type:"deduction", amount_deducted:amount, reason:`Cash refund exception ΓÇö ${claim.reason}`, is_active:true, applied_by:user.id }),
      ])
      toast.success("Cash refund approved")
      setSelected(null); setAdminNotes(""); load()
    } catch(err) { toast.error(err.message) }
    finally { setProcessing(false) }
  }

  const pending = claims.filter(c=>c.status==="pending")
  const underReview = claims.filter(c=>c.status==="under_review")
  const approved = claims.filter(c=>c.status==="approved")
  const SC = { pending:"#e6821e", under_review:"#8b5cf6", approved:"#1d9e75", rejected:"#e24b4a" }

  return (
    <div>
      {/* Stats */}
      <div style={{ display:"grid", gridTemplateColumns:isMobile?"repeat(2,1fr)":"repeat(4,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Total claims", value:claims.length, color:"#000000" },
          { label:"Pending review", value:pending.length, color:"#e6821e" },
          { label:"Approved", value:approved.length, color:"#1d9e75" },
          { label:"Provider penalties", value:penalties.length, color:"#e24b4a" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:isMobile?"0.75rem":"1rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontSize:10, color:"#888", textTransform:"uppercase", marginBottom:4 }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:s.color }}>{s.value}</div>
          </div>
        ))}
      </div>

      {/* Urgent banner */}
      {pending.length>0&&(
        <div style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:10, padding:"0.9rem", marginBottom:"1.25rem" }}>
          <div style={{ fontSize:13, color:"#e6821e", fontWeight:600 }}>ΓÜá∩╕Å {pending.length} claim{pending.length>1?"s":""} pending review ΓÇö respond within 24 hours</div>
        </div>
      )}

      {/* Tabs */}
      <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap" }}>
        {[{ k:"claims", l:"All claims" },{ k:"penalties", l:"Penalties ("+penalties.length+")" }].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{ padding:"8px 16px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#8b5cf6":"#f8f8f8", color:tab===t.k?"#fff":"#666", fontWeight:tab===t.k?700:400 }}>
            {t.l}
          </button>
        ))}
      </div>
      {tab==="claims"&&(
        <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap" }}>
          {[{ k:"all", l:"All" },{ k:"against_provider", l:"By customers" },{ k:"against_customer", l:"By providers/drivers" }].map(d=>(
            <button key={d.k} onClick={()=>setClaimDirection(d.k)}
              style={{ padding:"5px 12px", borderRadius:7, border:"none", fontSize:11, cursor:"pointer", background:claimDirection===d.k?"#e6821e":"#f0f0f0", color:claimDirection===d.k?"#fff":"#555" }}>
              {d.l}
            </button>
          ))}
        </div>
      )}
      {/* CLAIMS TAB */}
      {tab==="claims"&&(
        <div>
          {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
          {!loading&&claims.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No claims yet</div>}
          {claims.filter(c=> claimDirection==="all" ? true : claimDirection==="against_provider" ? (!c.claimant_type||c.claimant_type==="customer") : c.claimant_type==="provider").map(c=>(
            <div key={c.id} onClick={()=>setSelected(selected===c.id?null:c.id)} style={{ background:"#f8f8f8", border:`1px solid ${SC[c.status]||"#eeeeee"}30`, borderRadius:12, padding:"1rem", marginBottom:10 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:10 }}>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4, flexWrap:"wrap" }}>
                    <div style={{ fontSize:13, fontWeight:600, color:"#000000" }}>{c.bookings?.service_name || (c.orders ? "Order #"+c.orders.order_number : "Unknown")}</div>
                    <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:`${SC[c.status]||"#888"}20`, color:SC[c.status]||"#888" }}>{c.status?.replace("_"," ")}</span>
                  </div>
                  <div style={{ fontSize:11, color:"#888", marginBottom:2 }}>{c.bookings ? "#"+c.bookings.booking_number+" ┬╖ "+c.bookings.booking_date : c.orders ? "Order ┬╖ KES "+Number(c.orders.subtotal||0).toLocaleString()+" ┬╖ "+new Date(c.orders.created_at).toLocaleDateString() : ""}</div>
                  <div style={{ fontSize:11, color:"#888", marginBottom:2 }}>≡ƒæñ Filed by: {c.claimant?.first_name} {c.claimant?.last_name} ({c.claimant_type||"customer"}) ΓåÆ Against: {c.against?.first_name} {c.against?.last_name} ({c.against_type||"provider"})</div>
                  <div style={{ fontSize:11, color:"#888", marginBottom:4 }}>≡ƒÅ¬ Provider: {c.provider?.business_name||`${c.provider?.first_name} ${c.provider?.last_name}`}</div>
                  <div style={{ fontSize:12, color:"#e6821e", marginBottom:2 }}>Reason: {c.reason}</div>
                  <div style={{ fontSize:11, color:"#888", fontStyle:"italic" }}>&quot;{c.description}&quot;</div>
                  {c.evidence_urls?.length>0&&(
                    <div style={{ marginTop:6, marginBottom:4 }}>
                      <div style={{ fontSize:10, color:"#888", marginBottom:4 }}>≡ƒô╕ Evidence submitted:</div>
                      <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                        {c.evidence_urls.map((url,i)=>(
                          <img key={i} src={url} alt="Evidence" onClick={()=>window.open(url,"_blank")}
                            style={{ width:60, height:60, objectFit:"cover", borderRadius:6, cursor:"pointer", border:"1px solid #eee" }}/>
                        ))}
                      </div>
                    </div>
                  )}
                  {c.admin_notes&&<div style={{ fontSize:11, color:"#378add", marginTop:4 }}>Decision notes: &quot;{c.admin_notes}&quot;</div>}
                  <div style={{ fontSize:10, color:"#888", marginTop:4 }}>{new Date(c.created_at).toLocaleString()}</div>
                </div>
                <div style={{ textAlign:"right", flexShrink:0 }}>
                  <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#e6821e" }}>KES {Number(c.bookings?.total_amount||0).toLocaleString()}</div>
                  <div style={{ display:"flex", flexDirection:"column", gap:4, marginTop:6 }}>
                    {c.status==="pending"&&(
                      <button onClick={()=>{ setSelected(selected===c.id?null:c.id); setAdminNotes("") }}
                        style={{ background:"#f5f3ff", border:"1px solid #8b5cf640", borderRadius:7, color:"#8b5cf6", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                        Review
                      </button>
                    )}
                    {(c.status==="approved"||c.status==="rejected")&&(
                      <button onClick={()=>{ setSelected(selected===c.id?null:c.id); setAdminNotes(c.admin_notes||"") }}
                        style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                        {selected===c.id?"Close":"View details"}
                      </button>
                    )}
                    {c.status==="approved"&&(
                      <button onClick={()=>setChattingWith({claimId:c.id, userId:c.customer_id, name:c.customer?.first_name+" "+c.customer?.last_name, role:"customer"})}
                        style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                        ≡ƒÆ¼ Message customer
                      </button>
                    )}
                    {c.status==="approved"&&(
                      <button onClick={()=>setChattingWith({claimId:c.id, userId:c.provider_id, name:c.provider?.first_name+" "+c.provider?.last_name, role:"provider"})}
                        style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:7, color:"#e6821e", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                        ≡ƒÆ¼ Message provider
                      </button>
                    )}
                  </div>
                </div>
              </div>

              {selected===c.id&&(
                <div onClick={e=>e.stopPropagation()} style={{ borderTop:"1px solid #eeeeee", paddingTop:12, display:selected===c.id?"block":"none" }}>
                  <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#000000", marginBottom:8 }}>Review this claim</div>

                  {/* Provider penalty preview */}
                  <div style={{ background:"#fff5f5", border:"1px solid #e24b4a30", borderRadius:8, padding:"0.75rem", marginBottom:12 }}>
                    <div style={{ fontSize:11, color:"#e24b4a", fontWeight:600, marginBottom:4 }}>If approved ΓÇö provider consequences:</div>
                    <div style={{ fontSize:11, color:"#888" }}>ΓÇó KES {Number(c.bookings?.total_amount||0).toLocaleString()} deducted from provider earnings</div>
                    <div style={{ fontSize:11, color:"#888" }}>ΓÇó Penalty recorded against provider account</div>
                    <div style={{ fontSize:11, color:"#888" }}>ΓÇó Provider notified immediately</div>
                    {c.refund_preference&&<div style={{ fontSize:11, color:"#378add", fontWeight:600, marginTop:4 }}>ΓÇó Customer requested: {c.refund_preference==="cash"?"≡ƒÆ░ Cash Refund":c.refund_preference==="redo"?"≡ƒöº Redo the service":"≡ƒÄƒ∩╕Å Service Voucher"}</div>}
                    <div style={{ fontSize:11, color:"#1d9e75", marginTop:4 }}>ΓÇó Customer receives voucher worth KES {Number(c.bookings?.total_amount||0).toLocaleString()} valid 30 days</div>
                  </div>

                  <div style={{ marginBottom:12 }}>
                    <label style={{ fontSize:11, color:"#888", display:"block", marginBottom:4 }}>Decision notes (required for rejection)</label>
                    <textarea value={adminNotes} onChange={e=>setAdminNotes(e.target.value)}
                      placeholder="Add notes about your decision..."
                      style={{ width:"100%", background:"#ffffff", border:"1px solid #f0f0f0", borderRadius:8, padding:"9px 12px", color:"#000000", fontSize:12, outline:"none", resize:"vertical", minHeight:60, fontFamily:"'DM Sans',sans-serif" }}/>
                  </div>

                  
                  {/* Investigation chat */}
                  <div style={{ marginBottom:12 }}>
                    <div style={{ fontSize:11, color:"#888", marginBottom:6, fontWeight:600 }}>≡ƒôï Investigation ΓÇö Message parties</div>
                    <div style={{ display:"flex", gap:6, marginBottom:8 }}>
                      <button onClick={()=>requestEvidence(c)}
        style={{ background:"#f5f3ff", border:"1px solid #8b5cf640", borderRadius:7, color:"#8b5cf6", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>
        ≡ƒô╕ Request Evidence from Both
      </button>
      <button onClick={()=>setChattingWith(chattingWith?.claimId===c.id&&chattingWith?.userId===c.provider_id?null:{ claimId:c.id, userId:c.provider_id, name:c.provider?.business_name||`${c.provider?.first_name} ${c.provider?.last_name}`, role:"provider" })}
                        style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>
                        ≡ƒÆ¼ Message provider
                      </button>
                      <button onClick={()=>setChattingWith(chattingWith?.claimId===c.id&&chattingWith?.userId===c.customer_id?null:{ claimId:c.id, userId:c.customer_id, name:`${c.customer?.first_name} ${c.customer?.last_name}`, role:"customer" })}
                        style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:7, color:"#e6821e", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>
                        ≡ƒÆ¼ Message customer
                    {c.driver_id&&(
                      <button onClick={()=>setChattingWith(chattingWith?.claimId===c.id&&chattingWith?.userId===c.driver_id?null:{ claimId:c.id, userId:c.driver_id, name:(c.driver?.first_name||"Driver")+" "+(c.driver?.last_name||""), role:"driver" })}
                        style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>
                        ≡ƒÆ¼ Message driver
                      </button>
                    )}
                      </button>
                    </div>
                    {/* Only render ClaimChat when selected to avoid multiple realtime subscriptions */}
                    {selected===c.id&&(
                      <div style={{ marginBottom:8 }}>
                        {!chattingWith&&<ClaimChat claimId={c.id} claim={c} onClose={()=>setChattingWith(null)} threadLabel="≡ƒ¢í∩╕Å Full Claim Thread"/>}
                      {chattingWith?.claimId===c.id&&(
                        <ClaimChat
                          claimId={c.id}
                          claim={c}
                          receiverId={chattingWith.userId}
                          threadLabel={"≡ƒÆ¼ Private: Admin Γåö "+chattingWith.name}
                          onClose={()=>setChattingWith(null)}
                        />
                      )}
                      </div>
                    )}
                  </div>
                  <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
                    <button onClick={async()=>{ await supabase.from("service_claims").update({status:"under_review"}).eq("id",c.id); load(); toast.success("Marked as under review") }} disabled={processing}
                      style={{ background:"#f5f3ff", border:"1px solid #8b5cf640", borderRadius:8, color:"#8b5cf6", fontSize:12, fontWeight:700, padding:"8px 16px", cursor:"pointer" }}>
                      ≡ƒöì Mark Under Review
                    </button>
                    <button onClick={()=>requestEvidence(c)} style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:8, color:"#e6821e", fontSize:12, padding:"8px 14px", cursor:"pointer" }}>≡ƒô╕ Request Evidence</button>
                    <button onClick={()=>approveClaim(c)} disabled={processing}
                      style={{ background:processing?"#e0e0e0":"#1d9e75", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"9px 18px", cursor:processing?"not-allowed":"pointer" }}>
                      Γ£ô Approve & issue voucher
                    </button>
                    <button onClick={()=>issueCashRefund(c)} disabled={processing}
                      style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:8, color:"#1d9e75", fontSize:12, padding:"9px 14px", cursor:processing?"not-allowed":"pointer" }}>
                      ≡ƒÆ░ Cash refund (exception)
                    </button>
                    <button onClick={()=>rejectClaim(c.id)} disabled={processing}
                      style={{ background:"none", border:"1px solid #e24b4a40", borderRadius:8, color:"#e24b4a", fontSize:12, padding:"9px 14px", cursor:processing?"not-allowed":"pointer" }}>
                      Reject claim
                    </button>
                    <button onClick={()=>setSelected(null)}
                      style={{ background:"none", border:"1px solid #dddddd", borderRadius:8, color:"#888", fontSize:12, padding:"9px 14px", cursor:"pointer" }}>
                      Cancel
                    </button>
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {/* PENALTIES TAB */}
      {tab==="penalties"&&(
        <div>
          {penalties.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No provider penalties yet</div>}
          {penalties.map(p=>(
            <div key={p.id} style={{ background:"#f8f8f8", border:`1px solid ${p.is_active?"#e24b4a20":"#eeeeee"}`, borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:600, color:"#000000", marginBottom:2 }}>
                    {p.profiles?.business_name||`${p.profiles?.first_name} ${p.profiles?.last_name}`}
                  </div>
                  <div style={{ fontSize:11, color:"#e24b4a", marginBottom:2 }}>{p.penalty_type?.replace(/_/g," ").toUpperCase()}</div>
                  <div style={{ fontSize:11, color:"#888", marginBottom:2 }}>{p.reason}</div>
                  {p.expires_at&&<div style={{ fontSize:10, color:"#888" }}>Until: {new Date(p.expires_at).toLocaleString()}</div>}
                  <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{new Date(p.created_at).toLocaleString()}</div>
                </div>
                <div style={{ textAlign:"right" }}>
                  {p.amount_deducted>0&&<div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#e24b4a" }}>-KES {Number(p.amount_deducted).toLocaleString()}</div>}
                  <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:p.is_active?"#fff5f5":"#f8f8f8", color:p.is_active?"#e24b4a":"#cccccc" }}>
                    {p.is_active?"Active":"Resolved"}
                  </span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { ServicesIcon, VehicleIcon, GOServiceIcon, DiscoverIcon, PartsIcon, MarketplaceIcon } from "../../lib/cccIcons"
import { useEffect, useState } from "react"
import { useAuth } from "../../contexts/AuthContext"
import { supabase } from "../../lib/supabase"
import { auditLog, AUDIT_ACTIONS } from "../../lib/auditLog"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const PROVIDER_TYPES = [
  { key:"garage_shop_standard", label:"Garage - In Shop", icon:"services" },
  { key:"garage_shop_premium", label:"Garage - Mobile Mechanic", icon:"vehicle" },
  { key:"garage_go_service", label:"Garage - GO Emergency", icon:"emergency" },
  { key:"panel_beater_shop_standard", label:"Panel Beater - In Shop", icon:"≡ƒö¿" },
  { key:"panel_beater_shop_premium", label:"Panel Beater - On Site", icon:"≡ƒö¿" },
  { key:"auto_glass_shop_standard", label:"Auto Glass - In Shop", icon:"≡ƒ¬ƒ" },
  { key:"auto_glass_shop_premium", label:"Auto Glass - On Site", icon:"≡ƒ¬ƒ" },
  { key:"auto_electrician_shop_standard", label:"Auto Electrician - In Shop", icon:"ΓÜí" },
  { key:"auto_electrician_shop_premium", label:"Auto Electrician - On Site", icon:"ΓÜí" },
  { key:"car_wash_basic_wash", label:"Car Wash - Basic", icon:"≡ƒÜ┐" },
  { key:"car_wash_standard_wash", label:"Car Wash - Standard", icon:"≡ƒÜ┐" },
  { key:"car_wash_premium_detail", label:"Car Wash - Premium Detail", icon:"Γ£¿" },
  { key:"parts_dealer", label:"Parts Dealer", icon:"parts" },
  { key:"accessories_shop", label:"Accessories Shop", icon:"Γ£¿" },
  { key:"tyre_shop", label:"Tyre Shop", icon:"≡ƒ¢₧" },
  { key:"marketplace_vehicle", label:"Marketplace - Vehicle Sale", icon:"≡ƒÜÖ" },
  { key:"marketplace_item", label:"Marketplace - Part/Accessory Sale", icon:"≡ƒôª" },
]

export default function AdminCommissions() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const isMobile = useIsMobile()
  const [rates, setRates] = useState([])
  const [loading, setLoading] = useState(true)
  const [editing, setEditing] = useState(null)
  const [saving, setSaving] = useState(false)
  const [form, setForm] = useState({ platform_rate:"", provider_rate:"", description:"" })

  useEffect(() => { load() }, [])

  async function load() {
    const { data } = await supabase.from("commission_rates").select("*").order("provider_type")
    setRates(data||[])
    setLoading(false)
  }

  function startEdit(rate) {
    setEditing(rate.id)
    setForm({
      platform_rate: (rate.platform_rate*100).toString(),
      provider_rate: (rate.provider_rate*100).toString(),
      description: rate.description||""
    })
  }

  async function save() {
    if (!editing) return
    const platform = parseFloat(form.platform_rate)/100
    const provider = parseFloat(form.provider_rate)/100
    if (Math.abs(platform + provider - 1) > 0.001) {
      return toast.error("Platform + Provider rates must add up to 100%")
    }
    setSaving(true)
    try {
      // Log commission change
    await auditLog({ action: AUDIT_ACTIONS.COMMISSION_CHANGED, entityType: "commission_rate", entityId: editing, oldData: { platform_rate: rates.find(r=>r.id===editing)?.platform_rate }, newData: { platform_rate: platform, provider_rate: provider } })
    const { error } = await supabase.from("commission_rates").update({
        platform_rate: platform,
        provider_rate: provider,
        description: form.description,
      }).eq("id", editing)
      if (error) throw error
      toast.success("Commission rate updated!")
      setEditing(null)
      load()
    } catch(e) { toast.error(e.message) }
    finally { setSaving(false) }
  }

  const totalRevenue = rates.reduce((s,r) => s + (r.platform_rate*100), 0) / rates.length

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:"#000000", marginBottom:4 }}>Commission Rates</div>
      <div style={{ fontSize:12, color:"#888", marginBottom:"1.5rem" }}>Manage platform and provider revenue splits for each business type</div>

      {/* Summary */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Provider types", value:rates.length, color:"#378add" },
          { label:"Avg platform cut", value:`${totalRevenue.toFixed(1)}%`, color:"#e6821e" },
          { label:"Avg provider keep", value:`${(100-totalRevenue).toFixed(1)}%`, color:"#1d9e75" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:10, padding:"0.75rem", textAlign:"center" }}>
            <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>

      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}

      {rates.map(rate=>{
        const typeInfo = PROVIDER_TYPES.find(t=>t.key===rate.provider_type)||{ icon:"≡ƒöº", label:rate.provider_type }
        const isEditing = editing===rate.id
        return (
          <div key={rate.id} style={{ background:"#f8f8f8", border:`1px solid ${isEditing?"#8b5cf6":"#eeeeee"}`, borderRadius:12, padding:"1rem", marginBottom:10, transition:"border-color 0.2s" }}>
            <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:isEditing?12:0 }}>
              <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                <div style={{ width:40, height:40, borderRadius:10, background:"#ffffff", display:"flex", alignItems:"center", justifyContent:"center" }}>
                  {typeInfo.icon==="services"?<ServicesIcon size={20} color="#e6821e"/>:
                   typeInfo.icon==="vehicle"?<VehicleIcon size={20} color="#378add"/>:
                   typeInfo.icon==="emergency"?<GOServiceIcon size={20} color="#e24b4a"/>:
                   typeInfo.icon==="discover"?<DiscoverIcon size={20} color="#1d9e75"/>:
                   typeInfo.icon==="parts"?<PartsIcon size={20} color="#8b5cf6"/>:
                   typeInfo.icon==="marketplace"?<MarketplaceIcon size={20} color="#e6821e"/>:
                   <ServicesIcon size={20} color="#64748B"/>}
                </div>
                <div>
                  <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#000000" }}>{typeInfo.label}</div>
                  <div style={{ fontSize:11, color:"#888" }}>{rate.description}</div>
                </div>
              </div>
              <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                {!isEditing&&(
                  <div style={{ textAlign:"right" }}>
                    <div style={{ fontSize:12, color:"#1d9e75", fontWeight:600 }}>Provider keeps {(rate.provider_rate*100).toFixed(0)}%</div>
                    <div style={{ fontSize:11, color:"#e6821e" }}>Platform earns {(rate.platform_rate*100).toFixed(0)}%</div>
                  </div>
                )}
                <button onClick={()=>isEditing?setEditing(null):startEdit(rate)}
                  style={{ background:isEditing?"#e0e0e0":"#f8f8f8", border:`1px solid ${isEditing?"#555":"#e0e0e0"}`, borderRadius:8, color:isEditing?"#888":"#e6821e", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>
                  {isEditing?"Cancel":"Edit"}
                </button>
              </div>
            </div>

            {isEditing&&(
              <div>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10, marginBottom:10 }}>
                  <div>
                    <label style={{ fontSize:11, color:"#888", textTransform:"uppercase", letterSpacing:"0.05em", display:"block", marginBottom:4 }}>Platform % (e.g. 10)</label>
                    <input type="number" min="0" max="100" step="0.5" value={form.platform_rate}
                      onChange={e=>{ setForm(f=>({...f, platform_rate:e.target.value, provider_rate:(100-parseFloat(e.target.value||0)).toString()})) }}
                      style={{ width:"100%", background:"#ffffff", border:"1px solid #dddddd", borderRadius:8, padding:"9px 12px", color:"#000000", fontSize:13, outline:"none" }}/>
                  </div>
                  <div>
                    <label style={{ fontSize:11, color:"#888", textTransform:"uppercase", letterSpacing:"0.05em", display:"block", marginBottom:4 }}>Provider % (auto)</label>
                    <input type="number" min="0" max="100" step="0.5" value={form.provider_rate}
                      onChange={e=>setForm(f=>({...f, provider_rate:e.target.value}))}
                      style={{ width:"100%", background:"#ffffff", border:"1px solid #dddddd", borderRadius:8, padding:"9px 12px", color:"#000000", fontSize:13, outline:"none" }}/>
                  </div>
                </div>
                <div style={{ marginBottom:10 }}>
                  <label style={{ fontSize:11, color:"#888", textTransform:"uppercase", letterSpacing:"0.05em", display:"block", marginBottom:4 }}>Description</label>
                  <input value={form.description} onChange={e=>setForm(f=>({...f,description:e.target.value}))}
                    style={{ width:"100%", background:"#ffffff", border:"1px solid #dddddd", borderRadius:8, padding:"9px 12px", color:"#000000", fontSize:13, outline:"none" }}/>
                </div>
                <div style={{ background:"#ffffff", borderRadius:8, padding:"0.75rem", marginBottom:10, display:"flex", justifyContent:"space-between" }}>
                  <span style={{ fontSize:12, color:"#888" }}>Total must equal 100%</span>
                  <span style={{ fontSize:12, color:(parseFloat(form.platform_rate||0)+parseFloat(form.provider_rate||0))===100?"#1d9e75":"#e24b4a", fontWeight:600 }}>
                    {parseFloat(form.platform_rate||0)+parseFloat(form.provider_rate||0)}%
                  </span>
                </div>
                <button onClick={save} disabled={saving}
                  style={{ background:saving?"#e0e0e0":"#8b5cf6", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"10px 24px", cursor:saving?"not-allowed":"pointer" }}>
                  {saving?"Saving...":"Save changes"}
                </button>
              </div>
            )}
          </div>
        )
      })}
    </div>
  )
}

