    youtube: `${name}\n\nPrice: KES ${Number(price).toLocaleString()}\nShowroom: ${showroom}\n\nCar Care Connect is Nairobi's #1 automotive services marketplace. Browse new cars, book services, find parts and accessories ΓÇö all in one place.\n\n≡ƒöù Visit us: ${url}\n≡ƒô₧ Call us: 0113858966\nΓ£ë∩╕Å Email: carcareconnect254@gmail.com\n\n${tags}`,
  }
  return captions[platform] || captions.whatsapp
}

function getItemUrl(item) {
  const base = "https://carcareconnect.care"
  if (!item) return base
  if (item._type === "car") return `${base}/provider/${item.provider_id||item.id}`
  if (item._type === "service") return `${base}/service/${item.id}`
  if (item._type === "parts") return `${base}/parts/${item.id}`
  if (item._type === "provider") return `${base}/provider/${item.id}`
  return base
}

