    finally { setDownloading(false) }
  }

  // Canvas icon drawing helpers - line-icon style matching cccIcons.jsx
  function drawServicesIcon(ctx, cx, cy, r, color) {
    ctx.save()
    ctx.strokeStyle = color
    ctx.lineWidth = r * 0.12
    ctx.lineCap = "round"
    ctx.lineJoin = "round"
    ctx.beginPath()
    ctx.moveTo(cx - r*0.5, cy + r*0.6)
    ctx.lineTo(cx + r*0.1, cy)
    ctx.arc(cx + r*0.35, cy - r*0.25, r*0.35, Math.PI*0.75, Math.PI*1.75)
    ctx.lineTo(cx - r*0.1, cy - r*0.05)
    ctx.lineTo(cx - r*0.6, cy + r*0.45)
    ctx.closePath()
    ctx.stroke()
    ctx.restore()
  }
  function drawBuildingIcon(ctx, x, y, size, color) {
    ctx.save()
    ctx.strokeStyle = color
    ctx.lineWidth = size * 0.09
    ctx.lineJoin = "round"
    const w = size * 0.7, h = size
    ctx.strokeRect(x, y - h, w, h)
    ctx.beginPath()
    for (let i = 1; i <= 3; i++) {
      const wy = y - h + (h/4)*i
      ctx.moveTo(x + w*0.15, wy - h*0.1)
      ctx.lineTo(x + w*0.15, wy)
      ctx.moveTo(x + w*0.55, wy - h*0.1)
      ctx.lineTo(x + w*0.55, wy)
    }
    ctx.stroke()
    ctx.restore()
  }
  function drawPhoneIcon(ctx, x, y, size, color) {
    ctx.save()
    const scale = size / 24
    ctx.translate(x - size/2, y - size/2)
    ctx.scale(scale, scale)
    ctx.fillStyle = color
    ctx.beginPath()
    const path = new Path2D("M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z")
    ctx.fill(path)
    ctx.restore()
  }
  function drawEnvelopeIcon(ctx, x, y, size, color) {
    ctx.save()
    ctx.strokeStyle = color
    ctx.lineWidth = size * 0.08
    ctx.lineJoin = "round"
    const w = size, h = size * 0.65
    ctx.strokeRect(x, y - h, w, h)
    ctx.beginPath()
    ctx.moveTo(x, y - h)
    ctx.lineTo(x + w/2, y - h/2)
    ctx.lineTo(x + w, y - h)
    ctx.stroke()
    ctx.restore()
  }
  function drawCheckIcon(ctx, cx, cy, size, color) {
    ctx.save()
    ctx.strokeStyle = color
    ctx.lineWidth = size * 0.15
    ctx.lineCap = "round"
    ctx.lineJoin = "round"
    ctx.beginPath()
    ctx.moveTo(cx - size*0.4, cy)
    ctx.lineTo(cx - size*0.1, cy + size*0.3)
    ctx.lineTo(cx + size*0.45, cy - size*0.35)
    ctx.stroke()
    ctx.restore()
  }
  function drawPlatformDot(ctx, cx, cy, r, key) {
    const colors = { whatsapp:"#25D366", tiktok:"#000000", instagram:"#E1306C", facebook:"#1877F2", x:"#000000", youtube:"#FF0000" }
    const labels = { whatsapp:"W", tiktok:"T", instagram:"I", facebook:"F", x:"X", youtube:"Y" }
    ctx.save()
    ctx.fillStyle = colors[key] || "#666666"
    ctx.beginPath()
    ctx.arc(cx, cy, r, 0, Math.PI*2)
    ctx.fill()
    ctx.fillStyle = "#ffffff"
    ctx.font = "bold " + Math.round(r*1.1) + "px Arial"
    ctx.textAlign = "center"
    ctx.textBaseline = "middle"
    ctx.fillText(labels[key] || "?", cx, cy+2)
    ctx.textAlign = "left"
    ctx.textBaseline = "alphabetic"
    ctx.restore()
  }
  async function generateContentCard(item) {
    setDownloading(true)
    try {
      const canvas = document.createElement("canvas")
      canvas.width = 1080
      canvas.height = 1080
      const ctx = canvas.getContext("2d")
      // === ROUNDED CARD CLIP (transparent corners in exported PNG) ===
      ctx.save()
      ctx.beginPath()
      ctx.roundRect(0, 0, 1080, 1080, 32)
      ctx.clip()
      // === BACKGROUND ===
      ctx.fillStyle = "#0f0f0f"
      ctx.fillRect(0, 0, 1080, 1080)
      // === PHOTO SECTION (full bleed with gradient) - slightly shorter to give price/CTA more room ===
      const photoToUse = selectedPhoto || item._photos?.[0]
      if (photoToUse) {
        try {
          const img = new Image()
          img.crossOrigin = "anonymous"
          await new Promise((res, rej) => { img.onload = res; img.onerror = rej; img.src = photoToUse })
          const imgAspect = img.width / img.height
          const canvasAspect = 1080 / 620
          let drawX = 0, drawY = 0, drawW = 1080, drawH = 620
          if (imgAspect > canvasAspect) { drawH = 620; drawW = img.width*(620/img.height); drawX = (1080-drawW)/2 }
          else { drawW = 1080; drawH = img.height*(1080/img.width); drawY = (620-drawH)/2 }
          ctx.save(); ctx.beginPath(); ctx.rect(0,0,1080,620); ctx.clip()
          ctx.drawImage(img, drawX, drawY, drawW, drawH)
          ctx.restore()
        } catch(e) {
          ctx.fillStyle = "#1a1a1a"
          ctx.fillRect(0,0,1080,620)
          drawServicesIcon(ctx, 540, 320, 100, "#444444")
        }
      } else {
        ctx.fillStyle = "#1a1a1a"
        ctx.fillRect(0,0,1080,620)
        drawServicesIcon(ctx, 540, 320, 100, "#444444")
      }
      // === GRADIENT OVERLAY on photo ===
      const grad = ctx.createLinearGradient(0, 260, 0, 620)
      grad.addColorStop(0, "rgba(0,0,0,0)")
      grad.addColorStop(1, "rgba(0,0,0,0.85)")
      ctx.fillStyle = grad
      ctx.fillRect(0, 0, 1080, 620)
      // === LOGO top-left ===
      ctx.fillStyle = "#E6821E"
      ctx.beginPath()
      ctx.roundRect(30, 30, 220, 60, 12)
      ctx.fill()
      ctx.fillStyle = "#ffffff"
      ctx.font = "bold 28px Arial"
      ctx.fillText("CarCare Connect", 50, 70)
      // === CATEGORY BADGE top-right ===
      const typeLabel = item._type==="service"?"SERVICE":item._type==="car"?"NEW CAR":item._type==="parts"?"PARTS":"PRODUCT"
      ctx.fillStyle = "rgba(0,0,0,0.6)"
      ctx.beginPath()
      ctx.roundRect(830, 30, 220, 60, 12)
      ctx.fill()
      ctx.fillStyle = "#E6821E"
      ctx.font = "bold 24px Arial"
      ctx.textAlign = "center"
      ctx.fillText(typeLabel, 940, 70)
      ctx.textAlign = "left"
      // === BOTTOM INFO PANEL (taller, more room) ===
      ctx.fillStyle = "#111111"
      ctx.fillRect(0, 620, 1080, 460)
      // === SUBTLE BRAND GLOW ACCENT in panel ===
      const glow1 = ctx.createRadialGradient(1000, 1000, 0, 1000, 1000, 340)
      glow1.addColorStop(0, "rgba(230,130,30,0.10)")
      glow1.addColorStop(1, "rgba(230,130,30,0)")
      ctx.fillStyle = glow1
      ctx.fillRect(620, 620, 460, 460)
      const glow2 = ctx.createRadialGradient(0, 620, 0, 0, 620, 260)
      glow2.addColorStop(0, "rgba(230,130,30,0.06)")
      glow2.addColorStop(1, "rgba(230,130,30,0)")
      ctx.fillStyle = glow2
      ctx.fillRect(0, 620, 300, 300)
      // === PRICE (now the loudest element - biggest, boldest) ===
      const hasPrice = item._price && Number(item._price) > 0
      if (hasPrice) {
        ctx.fillStyle = "#E6821E"
        ctx.font = "bold 86px Arial"
        ctx.fillText(`KES ${Number(item._price).toLocaleString()}`, 40, 730)
      }
      // === CTA BADGE top-right of panel ===
      ctx.fillStyle = "#E6821E"
      ctx.beginPath()
      ctx.roundRect(830, 650, 210, 62, 31)
      ctx.fill()
      ctx.fillStyle = "#ffffff"
      ctx.font = "bold 26px Arial"
      ctx.textAlign = "center"
      ctx.fillText("BOOK NOW", 935, 689)
      ctx.textAlign = "left"
      // === ITEM NAME (secondary to price now) ===
      ctx.fillStyle = "#111111"
      ctx.font = "bold 38px Arial"
      const label = item._label || "Amazing Deal"
      const shortLabel = label.length > 32 ? label.substring(0,32)+"..." : label
      ctx.fillText(shortLabel, 40, hasPrice ? 790 : 730)
      // === DESCRIPTION ===
      if (item.description || item.name) {
        const desc = (item.description||item.name||"").substring(0,60)
        ctx.fillStyle = "#888888"
        ctx.font = "24px Arial"
        ctx.fillText(desc.length>55?desc.substring(0,55)+"...":desc, 40, hasPrice ? 828 : 768)
      }
      // === PROVIDER ===
      const sub = item.showroom_name || item.business_name || ""
      if (sub) {
        ctx.fillStyle = "#555555"
        ctx.font = "26px Arial"
        drawBuildingIcon(ctx, 40, 880, 20, "#555555")
        ctx.fillText(`${sub}`, 70, 880)
      }
      // === VERIFIED BADGE if applicable ===
      if (item.is_verified) {
        ctx.fillStyle = "#1d9e75"
        ctx.beginPath()
        ctx.roundRect(830, 730, 210, 44, 22)
        ctx.fill()
        ctx.fillStyle = "#ffffff"
        ctx.font = "bold 20px Arial"
        drawCheckIcon(ctx, 858, 752, 14, "#ffffff")
        ctx.fillText("VERIFIED", 878, 758)
      }
      // === DIVIDER ===
      ctx.fillStyle = "#eeeeee"
      ctx.fillRect(40, 930, 1000, 2)
      // === SIMPLIFIED FOOTER - website + phone only, bigger and clearer ===
      ctx.fillStyle = "#E6821E"
      ctx.font = "bold 34px Arial"
      ctx.fillText("carcareconnect.care", 40, 990)
      ctx.fillStyle = "#999999"
      ctx.font = "26px Arial"
      drawPhoneIcon(ctx, 700, 980, 22, "#999999")
      ctx.fillText("0113858966", 730, 990)
      ctx.restore()
      // === DOWNLOAD ===
      canvas.toBlob(blob => {
        const url = URL.createObjectURL(blob)
        const link = document.createElement("a")
        link.download = `CCC-${(item._label||"content").replace(/\s+/g,"-")}-card.png`
        link.href = url
        document.body.appendChild(link)
        link.click()
        document.body.removeChild(link)
        setTimeout(() => URL.revokeObjectURL(url), 1000)
        toast.success("Content card downloaded! ≡ƒÄ¿")
      }, "image/png")
    } catch(e) { toast.error("Card generation failed: " + e.message) }
    finally { setDownloading(false) }
  }


  async function generateCampaignCard(campaign) {
    setDownloading(true)
    try {
      const canvas = document.createElement("canvas")
      canvas.width = 1080
      canvas.height = 1080
      const ctx = canvas.getContext("2d")
      const campColor = campaign.color || "#E6821E"

      // === BACKGROUND - dark gradient ===
      const bgGrad = ctx.createLinearGradient(0, 0, 1080, 1080)
      bgGrad.addColorStop(0, "#0f0f0f")
      bgGrad.addColorStop(1, "#1a1a1a")
      ctx.fillStyle = bgGrad
      ctx.fillRect(0, 0, 1080, 1080)

      // === ACCENT LINE top ===
      ctx.fillStyle = campColor
      ctx.fillRect(0, 0, 1080, 8)

      // === CCC LOGO BADGE ===
      ctx.fillStyle = campColor
      ctx.beginPath()
      ctx.roundRect(40, 40, 260, 70, 14)
      ctx.fill()
      ctx.fillStyle = "#ffffff"
      ctx.font = "bold 32px Arial"
      ctx.fillText("CarCare Connect", 60, 85)

      // === LAUNCH BADGE top right ===
      ctx.fillStyle = "rgba(255,255,255,0.08)"
      ctx.beginPath()
      ctx.roundRect(800, 40, 240, 70, 14)
      ctx.fill()
      ctx.fillStyle = campColor
      ctx.font = "bold 26px Arial"
      ctx.textAlign = "center"
      ctx.fillText("CAMPAIGN", 920, 82)
      ctx.textAlign = "left"

      // === BIG CAMPAIGN NAME ===
      ctx.fillStyle = "#ffffff"
      ctx.font = "bold 72px Arial"
      const campName = campaign.name || "Campaign"
      const shortName = campName.length > 18 ? campName.substring(0,18)+"..." : campName
      ctx.fillText(shortName, 40, 280)

      // === DIVIDER LINE ===
      ctx.fillStyle = campColor
      ctx.fillRect(40, 300, 200, 6)

      // === DESCRIPTION ===
      if (campaign.description) {
        ctx.fillStyle = "#aaaaaa"
        ctx.font = "32px Arial"
        const desc = campaign.description.substring(0, 55)
        ctx.fillText(desc.length > 50 ? desc+"..." : desc, 40, 370)
      }

      // === GOAL ===
      if (campaign.goal) {
        ctx.fillStyle = campColor
        ctx.font = "bold 36px Arial"
        ctx.fillText("Goal: "+campaign.goal.substring(0,40), 40, 450)
      }

      // === DATES ===
      if (campaign.start_date) {
        ctx.fillStyle = "#666666"
        ctx.font = "28px Arial"
        ctx.fillText(campaign.start_date + " - " + (campaign.end_date||"ongoing"), 40, 510)
      }

      // === PLATFORM ICONS ===
      if (campaign.target_platforms?.length > 0) {
        ctx.fillStyle = "#444444"
        ctx.font = "24px Arial"
        ctx.fillText("Platforms:", 40, 590)
        campaign.target_platforms.forEach((p, i) => {
          drawPlatformDot(ctx, 40 + (i * 80) + 26, 640, 26, p)
        })
      }

      // === BOTTOM PANEL ===
      ctx.fillStyle = campColor
      ctx.fillRect(0, 860, 1080, 220)

      // === WEBSITE ===
      ctx.fillStyle = "#ffffff"
      ctx.font = "bold 48px Arial"
      ctx.textAlign = "center"
      ctx.fillText("carcareconnect.care", 540, 940)

      // === TAGLINE ===
      ctx.fillStyle = "rgba(255,255,255,0.8)"
      ctx.font = "32px Arial"
      ctx.fillText("Your Car, Our Care, Simplified", 540, 1000)

      // === PHONE ===
      ctx.fillStyle = "rgba(255,255,255,0.6)"
      ctx.font = "26px Arial"
      drawPhoneIcon(ctx, 540, 1050, 20, "#666666")
      ctx.fillText("0113858966", 568, 1050)
      ctx.textAlign = "left"

      // === DOWNLOAD ===
      const link = document.createElement("a")
      link.download = `CCC-Campaign-${(campaign.name||"launch").replace(/\s+/g,"-")}.png`
      link.href = canvas.toDataURL("image/png")
      link.click()
      toast.success("Campaign card downloaded! ≡ƒÄ¿")
    } catch(e) { toast.error("Card generation failed: " + e.message) }
    finally { setDownloading(false) }
  }


  async function addToCampaign(campaignId) {
    if (!selected) return
    await supabase.from("content_posts").insert({
      item_id: selected.id,
      item_type: selected._type,
      platform,
      caption,
      campaign_id: campaignId,
      status: "draft",
      item_label: selected._label,
      item_photo: selected._photos?.[0]||null,
    })
    toast.success("Added to campaign!")
    loadCampaignPosts(campaignId)
  }

  async function markAsPosted(itemId, platform) {
    const { error } = await supabase.from("content_posts").insert({
      item_id: itemId,
      item_type: selected?._type,
      platform,
      posted_at: new Date().toISOString(),
      caption,
    })
    if (error) return toast.error(error.message)
    toast.success(`Γ£à Marked as posted on ${platformInfo?.label}!`)
  }

  async function schedulePost() {
    if (!scheduleForm.date||!scheduleForm.time) return toast.error("Please select date and time")
    const { error } = await supabase.from("scheduled_posts").insert({
      item_id: selected.id,
      item_type: selected._type,
      item_label: selected._label,
      platform,
      caption,
      scheduled_for: `${scheduleForm.date}T${scheduleForm.time}:00`,
      status: "scheduled"
    })
    if (error) return toast.error(error.message)
    toast.success("Post scheduled!")
    setShowScheduleForm(false)
    setScheduleForm({ date:"", time:"" })
    loadScheduledPosts()
  }

  async function loadScheduledPosts() {
    const { data } = await supabase.from("scheduled_posts").select("*").eq("status","scheduled").order("scheduled_for",{ascending:true})
    setScheduledPosts(data||[])
  }

  useEffect(() => { loadScheduledPosts() }, [])

  async function createCampaign(e) {
    if (e?.preventDefault) e.preventDefault()
    if (!campaignForm.name.trim()) return toast.error("Campaign name required")
    const { data, error } = await supabase.from("content_campaigns").insert({
      name: campaignForm.name.trim(),
      description: campaignForm.description,
      goal: campaignForm.goal,
      start_date: campaignForm.start_date||null,
      end_date: campaignForm.end_date||null,
      color: campaignForm.color||"#e6821e",
      target_platforms: campaignForm.target_platforms,
      post_count_target: campaignForm.post_count_target,
      status: "active",
      created_by: (await supabase.auth.getUser()).data.user?.id
    }).select()
    if (error) { console.error(error); return toast.error("Failed: "+error.message) }
    toast.success("Campaign created!")
    setCampaignForm({ name:"", description:"", goal:"", start_date:"", end_date:"", color:"#e6821e", target_platforms:[], post_count_target:7 })
    setShowCampaignForm(false)
    loadCampaigns()
  }

