                  <div style={{ fontSize:12, fontWeight:600, color:"#000" }}>{p.item_label}</div>
                  <span style={{ fontSize:10, background:"#8b5cf6", color:"#fff", padding:"2px 8px", borderRadius:10 }}>{p.platform}</span>
