          </div>
          {sosAlerts.map(a=>(
            <div key={a.id} style={{ background:"#ffffff", borderRadius:8, padding:"0.75rem", marginBottom:6, display:"flex", justifyContent:"space-between", alignItems:"center", flexWrap:"wrap", gap:8 }}>
