            <div style={{ flexShrink:0, textAlign:"right" }}>
              <div style={{ fontSize:9, padding:"2px 6px", borderRadius:8, background:"#f5f5f5", color:"#888", marginBottom:2 }}>{a.tag}</div>
              <div style={{ fontSize:9, color:"#aaa" }}>{new Date(a.time).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})}</div>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

import { RefreshIcon, DeleteIcon, WarningIcon } from "../../lib/cccIcons"
import { useState, useEffect } from "react"
import { useAuth } from "../../contexts/AuthContext"
import { supabase } from "../../lib/supabase"
import toast from "react-hot-toast"

export default function AdminDeletionRequests() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const [requests, setRequests] = useState([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState("pending")

  useEffect(() => { load() }, [filter])

  async function load() {
    setLoading(true)
    const { data } = await supabase
      .from("deletion_requests")
      .select("*, profiles(first_name, last_name, role, marketplace_rating)")
      .eq("status", filter)
      .order("scheduled_for", { ascending: true })
    setRequests(data||[])
    setLoading(false)
  }

  async function cancelDeletion(id, userId) {
    if(!window.confirm("Cancel this deletion request? The user will be notified.")) return
    try {
      await supabase.from("deletion_requests").update({ status:"cancelled" }).eq("id", id)
      await supabase.from("notifications").insert({
        user_id: userId,
        type: "account_deletion",
        title: "Account deletion cancelled Γ£à",
        message: "Your account deletion request has been cancelled by our team. Your account is safe.",
      })
      toast.success("Deletion cancelled and user notified")
      load()
    } catch(e) { toast.error(e.message) }
  }

  async function processDeletion(id, userId) {
    if(!window.confirm("Permanently delete this account? This CANNOT be undone.")) return
    try {
      // Anonymize profile data
      await supabase.from("profiles").update({
        first_name: "Deleted",
        last_name: "User",
        city: null,
        avatar_url: null,
        business_name: null,
        latitude: null,
        longitude: null,
      }).eq("id", userId)
      // Delete sensitive data
      await supabase.from("profile_sensitive").delete().eq("id", userId)
      // Mark deletion as completed
      await supabase.from("deletion_requests").update({ status:"completed" }).eq("id", id)
      toast.success("Account data deleted successfully")
      load()
    } catch(e) { toast.error(e.message) }
  }

  const STATUS_COLORS = {
    pending: { bg:"#fff8f0", color:"#e6821e", label:"Pending" },
    processing: { bg:"#eff6ff", color:"#378add", label:"Processing" },
    completed: { bg:"#f0fdf4", color:"#1d9e75", label:"Completed" },
    cancelled: { bg:"#f5f5f5", color:"#888", label:"Cancelled" },
  }

  return (
    <div>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1rem" }}>
        <div>
          <div style={{ fontFamily:"Syne", fontSize:20, fontWeight:800 }}>Account Deletion Requests</div>
          <div style={{ fontSize:12, color:"#888" }}>Manage user account deletion requests</div>
        </div>
        <button onClick={load} style={{ padding:"6px 14px", borderRadius:8, border:"0.5px solid #ddd", background:"#f5f5f5", fontSize:12, cursor:"pointer" }}>
          <><RefreshIcon size={13} color="currentColor"/> Refresh</>
        </button>
      </div>

      {/* Filter tabs */}
      <div style={{ display:"flex", gap:6, marginBottom:"1rem" }}>
        {["pending","processing","completed","cancelled"].map(s=>(
          <button key={s} onClick={()=>setFilter(s)}
            style={{ padding:"6px 14px", borderRadius:8, border:"0.5px solid "+(filter===s?"#e6821e":"#ddd"), background:filter===s?"#e6821e":"#fff", color:filter===s?"#fff":"#555", fontSize:12, cursor:"pointer", textTransform:"capitalize" }}>
            {s}
          </button>
        ))}
      </div>

      {loading ? (
        <div style={{ textAlign:"center", padding:"3rem", color:"#888" }}>Loading...</div>
      ) : requests.length === 0 ? (
        <div style={{ textAlign:"center", padding:"3rem", color:"#888" }}>
          <div style={{ fontSize:48, marginBottom:12 }}>Γ£à</div>
          <div style={{ fontWeight:600 }}>No {filter} deletion requests</div>
        </div>
      ) : (
        <div>
          {requests.map(r => {
            const s = STATUS_COLORS[r.status] || STATUS_COLORS.pending
            const hoursLeft = Math.ceil((new Date(r.scheduled_for) - new Date()) / 3600000)
            const isOverdue = hoursLeft < 0
            return (
              <div key={r.id} style={{ background:"#fff", border:"0.5px solid "+(isOverdue?"#e24b4a":"#eee"), borderRadius:12, padding:"1rem", marginBottom:10 }}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
                  <div>
                    <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:700 }}>
                      {r.profiles?.first_name} {r.profiles?.last_name}
                      <span style={{ marginLeft:8, fontSize:11, padding:"2px 8px", borderRadius:8, background:"#f5f5f5", color:"#888" }}>{r.profiles?.role}</span>
                    </div>
                    <div style={{ fontSize:12, color:"#888", marginTop:2 }}>ID: {r.user_id?.slice(0,8)}...</div>
                  </div>
                  <span style={{ fontSize:11, padding:"3px 10px", borderRadius:8, background:s.bg, color:s.color, fontWeight:600 }}>{s.label}</span>
                </div>

                <div style={{ display:"flex", gap:16, fontSize:12, color:"#888", marginBottom:12 }}>
                  <span>Requested: {new Date(r.requested_at).toLocaleString()}</span>
                  <span style={{ color:isOverdue?"#e24b4a":"#555" }}>
                    Due: {new Date(r.scheduled_for).toLocaleString()}
                    {r.status==="pending" && (isOverdue ? " ΓÜá∩╕Å OVERDUE" : " ("+hoursLeft+"h left)")}
                  </span>
                </div>

                {r.reason && <div style={{ fontSize:12, color:"#555", background:"#f9f9f9", padding:"6px 10px", borderRadius:6, marginBottom:10 }}>{r.reason}</div>}

                {r.status==="pending"&&(
                  <div style={{ display:"flex", gap:8 }}>
                    <button onClick={()=>processDeletion(r.id, r.user_id)}
                      style={{ background:"#e24b4a", border:"none", borderRadius:8, color:"#fff", fontSize:12, fontWeight:600, padding:"8px 16px", cursor:"pointer" }}>
                      <><DeleteIcon size={13} color="currentColor"/> Delete Account</>
                    </button>
                    <button onClick={()=>cancelDeletion(r.id, r.user_id)}
                      style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:8, color:"#1d9e75", fontSize:12, fontWeight:600, padding:"8px 16px", cursor:"pointer" }}>
                      Γ£ô Cancel Request
                    </button>
                  </div>
                )}
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

import { NoteIcon, ProfileIcon, WarningIcon, CheckIcon } from "../../lib/cccIcons"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"
import { useAuth } from "../../contexts/AuthContext"

const FUEL_LABELS = { empty:"Empty", quarter:"1/4", half:"1/2", three_quarter:"3/4", full:"Full" }

export default function AdminDisputes() {
  const { user } = useAuth()
  const isMobile = useIsMobile()
  const [disputes, setDisputes] = useState([])
  const [alerts, setAlerts] = useState([])
  const [reports, setReports] = useState([])
  const [loading, setLoading] = useState(true)
  const [tab, setTab] = useState("disputes")
  const [selected, setSelected] = useState(null)
  const [adminNotes, setAdminNotes] = useState("")
  const [resolving, setResolving] = useState(false)

  useEffect(() => { load() }, [])

  async function load() {
    const [{ data: disps }, { data: alts }, { data: reps }] = await Promise.all([
      supabase.from("vehicle_disputes").select("*, bookings(service_name,booking_number,booking_date), profiles(first_name,last_name,email)").order("created_at",{ascending:false}),
      supabase.from("mileage_alerts").select("*, bookings(service_name,booking_number,customer_id)").order("created_at",{ascending:false}),
      supabase.from("vehicle_condition_reports").select("*, profiles(first_name,last_name,role)").order("created_at",{ascending:false}).limit(50),
    ])
    setDisputes(disps||[])
    setAlerts(alts||[])
    setReports(reps||[])
    setLoading(false)
  }

  async function resolveDispute(id, status) {
    setResolving(true)
    try {
      const { error } = await supabase.from("vehicle_disputes").update({
        status,
        admin_notes: adminNotes,
        resolved_by: user.id,
        resolved_at: new Date().toISOString(),
      }).eq("id",id)
      if (error) throw error
      toast.success(`Dispute ${status}`)
      setSelected(null)
      setAdminNotes("")
      load()
    } catch(err) { toast.error(err.message) }
    finally { setResolving(false) }
  }

  const open = disputes.filter(d=>d.status==="open").length
  const underReview = disputes.filter(d=>d.status==="under_review").length
  const highMileage = alerts.filter(a=>a.difference>30).length

  const TABS = [
    { k:"disputes", l:`Disputes (${disputes.length})` },
    { k:"alerts", l:`Mileage alerts (${alerts.length})` },
    { k:"reports", l:`Condition reports (${reports.length})` },
  ]

  return (
    <div>
      <div style={{ display:"grid", gridTemplateColumns:isMobile?"repeat(2,1fr)":"repeat(4,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Open disputes", value:open, color:"#e24b4a" },
          { label:"Under review", value:underReview, color:"#e6821e" },
          { label:"Mileage alerts", value:highMileage, color:"#8b5cf6" },
          { label:"Total reports", value:reports.length, color:"#378add" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:isMobile?"0.75rem":"1rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontSize:10, color:"#888", textTransform:"uppercase", marginBottom:4 }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:s.color }}>{s.value}</div>
          </div>
        ))}
      </div>

      <div style={{ display:"flex", gap:6, marginBottom:"1.25rem", flexWrap:"wrap" }}>
        {TABS.map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{ padding:"8px 16px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#8b5cf6":"#f8f8f8", color:tab===t.k?"#fff":"#666", fontFamily:"'DM Sans',sans-serif", fontWeight:tab===t.k?700:400 }}>
            {t.l}
          </button>
        ))}
      </div>

      {/* DISPUTES */}
      {tab==="disputes"&&(
        <div>
          {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
          {!loading&&disputes.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No disputes yet</div>}
          {disputes.map(d=>(
            <div key={d.id} style={{ background:"#f8f8f8", border:`1px solid ${d.status==="open"?"#e24b4a30":d.status==="resolved"?"#1d9e7530":"#eeeeee"}`, borderRadius:12, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4, flexWrap:"wrap" }}>
                    <div style={{ fontSize:13, fontWeight:600, color:"#000000" }}>{d.dispute_type?.replace("_"," ").toUpperCase()} dispute</div>
                    <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:d.status==="open"?"#fff5f5":d.status==="resolved"?"#f0fdf4":"#fff8f0", color:d.status==="open"?"#e24b4a":d.status==="resolved"?"#1d9e75":"#e6821e" }}>{d.status}</span>
                  </div>
                  <div style={{ fontSize:12, color:"#888", marginBottom:2, display:"flex", alignItems:"center", gap:3 }}><NoteIcon size={12} color="#888"/> {d.bookings?.service_name} ΓÇö #{d.bookings?.booking_number}</div>
                  <div style={{ fontSize:11, color:"#888", marginBottom:2, display:"flex", alignItems:"center", gap:3 }}><ProfileIcon size={11} color="#888"/> {d.profiles?.first_name} {d.profiles?.last_name}</div>
                  <div style={{ fontSize:11, color:"#888", lineHeight:1.5 }}>&quot;{d.description}&quot;</div>
                  {d.admin_notes&&<div style={{ fontSize:11, color:"#378add", marginTop:4 }}>Admin: &quot;{d.admin_notes}&quot;</div>}
                  <div style={{ fontSize:10, color:"#888", marginTop:4 }}>{new Date(d.created_at).toLocaleString()}</div>
                </div>
                {d.status==="open"&&(
                  <button onClick={()=>setSelected(selected===d.id?null:d.id)}
                    style={{ background:"#f5f3ff", border:"1px solid #8b5cf640", borderRadius:7, color:"#8b5cf6", fontSize:11, padding:"5px 10px", cursor:"pointer", flexShrink:0 }}>
                    Review
                  </button>
                )}
              </div>

              {selected===d.id&&(
                <div style={{ borderTop:"1px solid #eeeeee", paddingTop:10 }}>
                  <div style={{ marginBottom:10 }}>
                    <label style={{ fontSize:11, color:"#888", display:"block", marginBottom:4 }}>Admin notes</label>
                    <textarea value={adminNotes} onChange={e=>setAdminNotes(e.target.value)}
                      placeholder="Add resolution notes..."
                      style={{ width:"100%", background:"#ffffff", border:"1px solid #f0f0f0", borderRadius:8, padding:"9px 12px", color:"#000000", fontSize:12, outline:"none", resize:"vertical", minHeight:60, fontFamily:"'DM Sans',sans-serif" }}/>
                  </div>
                  <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
                    <button onClick={()=>resolveDispute(d.id,"under_review")} disabled={resolving}
                      style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:7, color:"#e6821e", fontSize:12, padding:"7px 14px", cursor:"pointer" }}>
                      Mark under review
                    </button>
                    <button onClick={()=>resolveDispute(d.id,"resolved")} disabled={resolving}
                      style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:12, padding:"7px 14px", cursor:"pointer" }}>
                      Resolve
                    </button>
                    <button onClick={()=>resolveDispute(d.id,"dismissed")} disabled={resolving}
                      style={{ background:"none", border:"1px solid #e24b4a30", borderRadius:7, color:"#e24b4a", fontSize:12, padding:"7px 14px", cursor:"pointer" }}>
                      Dismiss
                    </button>
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {/* MILEAGE ALERTS */}
      {tab==="alerts"&&(
        <div>
          {alerts.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No mileage alerts</div>}
          {alerts.map(a=>(
            <div key={a.id} style={{ background:"#f8f8f8", border:`1px solid ${a.difference>30?"#e6821e30":"#eeeeee"}`, borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:600, color:"#000000", marginBottom:4 }}>{a.bookings?.service_name}</div>
                  <div style={{ fontSize:11, color:"#888", marginBottom:4 }}>#{a.bookings?.booking_number}</div>
                  <div style={{ display:"flex", gap:16, flexWrap:"wrap" }}>
                    <div>
                      <div style={{ fontSize:10, color:"#888" }}>Pickup</div>
                      <div style={{ fontSize:13, color:"#000000", fontWeight:600 }}>{a.pickup_odometer?.toLocaleString()} km</div>
                    </div>
                    <div>
                      <div style={{ fontSize:10, color:"#888" }}>Dropoff</div>
                      <div style={{ fontSize:13, color:"#000000", fontWeight:600 }}>{a.dropoff_odometer?.toLocaleString()} km</div>
                    </div>
                    <div>
                      <div style={{ fontSize:10, color:"#888" }}>Difference</div>
                      <div style={{ fontSize:13, fontWeight:800, color:a.difference>30?"#e24b4a":"#1d9e75" }}>{a.difference} km</div>
                    </div>
                  </div>
                </div>
                <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:a.difference>30?"#fff5f5":"#f0fdf4", color:a.difference>30?"#e24b4a":"#1d9e75" }}>
                  {a.difference>30?"ΓÜá∩╕Å Alert":"Γ£ô Normal"}
                </span>
              </div>
              <div style={{ fontSize:10, color:"#888", marginTop:6 }}>{new Date(a.created_at).toLocaleString()}</div>
            </div>
          ))}
        </div>
      )}

      {/* CONDITION REPORTS */}
      {tab==="reports"&&(
        <div>
          {reports.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No condition reports yet</div>}
          {reports.map(r=>(
            <div key={r.id} style={{ background:"#f8f8f8", border:`1px solid ${r.report_type==="pickup"?"#378add20":"#1d9e7520"}`, borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div>
                  <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4, flexWrap:"wrap" }}>
                    <span style={{ fontSize:14 }}>{r.report_type==="pickup"?"≡ƒÜù":"Γ£à"}</span>
                    <div style={{ fontSize:13, fontWeight:600, color:r.report_type==="pickup"?"#378add":"#1d9e75" }}>
                      {r.report_type==="pickup"?"Pickup":"Dropoff"} report
                    </div>
                    <span style={{ fontSize:10, color:"#888" }}>by {r.profiles?.first_name} {r.profiles?.last_name} ({r.profiles?.role})</span>
                  </div>
                  <div style={{ fontSize:11, color:"#888", marginBottom:4 }}>
                    Odometer: {r.odometer_reading?.toLocaleString()} km ┬╖ Fuel: {FUEL_LABELS[r.fuel_level]||r.fuel_level}
                  </div>
                  <div style={{ display:"flex", flexWrap:"wrap", gap:4 }}>
                    {["has_scratches","has_dents","has_broken_lights","has_missing_parts","dirty_interior","dirty_exterior"].filter(k=>r[k]).map(k=>(
                      <span key={k} style={{ fontSize:10, padding:"1px 7px", borderRadius:10, background:"#fff5f5", color:"#e24b4a" }}>
                        {k.replace("has_","").replace("_"," ")}
                      </span>
                    ))}
                    {!["has_scratches","has_dents","has_broken_lights","has_missing_parts","dirty_interior","dirty_exterior"].some(k=>r[k])&&(
                      <span style={{ fontSize:10, color:"#1d9e75" }}>Γ£ô No issues</span>
                    )}
                  </div>
                  {r.condition_notes&&<div style={{ fontSize:11, color:"#888", marginTop:4, fontStyle:"italic" }}>&quot;{r.condition_notes}&quot;</div>}
                </div>
                <div style={{ fontSize:10, color:"#888", flexShrink:0 }}>{new Date(r.created_at).toLocaleString()}</div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { VehicleIcon, CheckIcon, DocumentIcon, ShieldIcon } from "../../lib/cccIcons"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const STATUS_COLORS = {
  scheduled: "#e6821e", completed: "#1d9e75", cancelled: "#e24b4a",
  approved: "#1d9e75", rejected: "#e24b4a", pending: "#888"
}

export default function AdminDriverVetting() {
  const { user } = useAuth()
  const isMobile = useIsMobile()
  const [appointments, setAppointments] = useState([])
  const [selected, setSelected] = useState(null)
  const [documents, setDocuments] = useState([])
  const [loading, setLoading] = useState(true)
  const [tab, setTab] = useState("pending")
  const [result, setResult] = useState("")
  const [notes, setNotes] = useState("")
  const [saving, setSaving] = useState(false)
  const [rescheduling, setRescheduling] = useState(null)
  const [rescheduleForm, setRescheduleForm] = useState({ date:"", time:"" })
  const [search, setSearch] = useState("")
  const [unverifiedDrivers, setUnverifiedDrivers] = useState([])
  const [bulkVerifying, setBulkVerifying] = useState(false)

  useEffect(() => { load() }, [])

  async function load() {
    const { data } = await supabase.from("driver_vetting_appointments")
      .select("*, driver:profiles!driver_vetting_appointments_driver_id_fkey(id,first_name,last_name,driver_vehicle_type,vetting_status,is_verified,driver_category)")
      .order("appointment_date", { ascending:true })
    setAppointments(data||[])
    // Load unverified drivers
    const { data: unverified } = await supabase.from("profiles")
      .select("id,first_name,last_name,driver_vehicle_type,created_at")
      .eq("role","driver")
      .eq("is_verified",false)
      .order("created_at",{ascending:false})
    setUnverifiedDrivers(unverified||[])
    setLoading(false)
  }

  async function loadDocuments(driverId) {
    const { data } = await supabase.from("driver_documents").select("*").eq("driver_id", driverId)
    setDocuments(data||[])
  }

  async function selectAppointment(appt) {
    setSelected(appt)
    setResult("")
    setNotes("")
    await loadDocuments(appt.driver_id)
  }

  async function verifySingleDriver(driverId, name) {
    if(!confirm("Verify "+name+"? Make sure you have reviewed their documents.")) return
    await supabase.from("profiles").update({
      is_verified: true,
      documents_verified: true,
      vetting_status: "approved",
      verified_by: user.id,
      verified_at: new Date().toISOString(),
    }).eq("id", driverId)
    await supabase.from("notifications").insert({
      user_id: driverId,
      title: "Account Verified! Γ£à",
      message: "Congratulations! Your driver account has been verified. You can now accept delivery and concierge jobs.",
      type: "success"
    })
    toast.success(name+" verified!")
    load()
  }
  async function verifyDocument(docId, verified) {
    await supabase.from("driver_documents").update({ is_verified: verified }).eq("id", docId)
    await loadDocuments(selected.driver_id)
    toast.success(verified ? "Document verified Γ£ô" : "Document marked unverified")
  }

  async function submitAssessment() {
    if (!result) return toast.error("Please select assessment result")
    setSaving(true)
    try {
      const passed = result === "passed"
      const conditional = result === "conditional"

      // Update appointment
      await supabase.from("driver_vetting_appointments").update({
        status: "completed",
        assessment_result: result,
        assessment_notes: notes,
        assessed_by: user.id,
        updated_at: new Date().toISOString()
      }).eq("id", selected.id)

      if (conditional) {
        // Conditional ΓÇö schedule follow-up, don't approve yet
        await Promise.all([
          supabase.from("profiles").update({ vetting_status:"conditional" }).eq("id", selected.driver_id),
          supabase.from("notifications").insert({
            user_id: selected.driver_id,
            title: "Application Update ΓÇö Conditional",
            message: "Your vetting assessment had a conditional result. " + (notes||"Please contact support for next steps."),
            type: "warning",
          })
        ])
        toast.success("Driver marked conditional ΓÇö notified")
      } else if (passed) {
        // Approve driver ΓÇö create probation record
        await Promise.all([
          supabase.from("profiles").update({
            is_verified: true,
            documents_verified: true,
            vetting_status: "approved",
            verified_by: user.id,
            verified_at: new Date().toISOString(),
          }).eq("id", selected.driver_id),
          supabase.from("driver_probation").upsert({
            driver_id: selected.driver_id,
            status: "probation",
            jobs_completed: 0,
            jobs_required: 10,
            started_at: new Date().toISOString(),
          }, { onConflict: "driver_id" }),
          supabase.from("notifications").insert({
            user_id: selected.driver_id,
            title: "≡ƒÄë Application Approved!",
            message: "Congratulations! You have been approved as a CCC Driver. You are now on probation for your first 10 jobs ΓÇö maintain a 4.5+ star rating to complete probation successfully.",
            type: "success",
          })
        ])
        toast.success("Driver approved ΓÇö probation started!")
      } else {
        // Reject driver
        await Promise.all([
          supabase.from("profiles").update({
            vetting_status: "rejected",
          }).eq("id", selected.driver_id),
          supabase.from("notifications").insert({
            user_id: selected.driver_id,
            title: "Application Update",
            message: `Your CCC Driver application was not successful at this time. ${notes ? "Assessor notes: " + notes : "Please contact support for more information."}`,
            type: "warning",
          })
        ])
        toast.success("Driver rejected ΓÇö notified")
      }

      setSelected(null)
      load()
    } catch(e) { toast.error(e.message) }
    finally { setSaving(false) }
  }

  async function rescheduleAppointment() {
    if (!rescheduleForm.date || !rescheduleForm.time) return toast.error("Please enter date and time")
    await supabase.from("driver_vetting_appointments").update({
      appointment_date: rescheduleForm.date,
      appointment_time: rescheduleForm.time,
      status: "rescheduled",
      updated_at: new Date().toISOString()
    }).eq("id", rescheduling)
    toast.success("Appointment rescheduled")
    setRescheduling(null)
    setRescheduleForm({ date:"", time:"" })
    load()
  }

  const pending = appointments.filter(a=>["scheduled","rescheduled"].includes(a.status))
  const completed = appointments.filter(a=>a.status==="completed")

  const filtered = tab === "pending" ? pending : completed

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:"#000", marginBottom:4 }}>Driver Vetting</div>
      <div style={{ fontSize:12, color:"#888", marginBottom:"1.5rem" }}>Review applications and conduct vetting appointments</div>

      {/* Stats */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Pending appointments", value:pending.length, color:"#e6821e" },
          { label:"Completed", value:completed.length, color:"#1d9e75" },
          { label:"Total applicants", value:appointments.length, color:"#378add" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.75rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontFamily:"Syne", fontSize:20, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>

      {/* Tabs */}
      <div style={{ display:"flex", gap:6, marginBottom:"1rem" }}>
        {[{k:"pending",l:`Pending (${pending.length})`},{k:"completed",l:`Completed (${completed.length})`}].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{ padding:"7px 14px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#8b5cf6":"#f8f8f8", color:tab===t.k?"#fff":"#666", fontFamily:"DM Sans,sans-serif", fontWeight:tab===t.k?700:400 }}>
            {t.l}
          </button>
        ))}
      </div>

      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}

      {/* Selected appointment detail */}
      {selected&&(
        <div style={{ background:"#f8f8f8", border:"1px solid #8b5cf640", borderRadius:12, padding:"1.25rem", marginBottom:"1rem" }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:"1rem" }}>
            <div>
              <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#000" }}>{selected.driver?.first_name} {selected.driver?.last_name}</div>
              <div style={{ fontSize:11, color:"#888" }}>{selected.driver?.email} ┬╖ {selected.driver?.phone}</div>
              <div style={{ fontSize:11, color:"#888", display:"flex", alignItems:"center", gap:3 }}><VehicleIcon size={11} color="#888"/> Vehicle: {selected.driver?.driver_category==="concierge"?"≡ƒºæΓÇìΓ£ê∩╕Å Concierge Driver":(selected.driver?.driver_vehicle_type||"ΓÇö")} ┬╖ {selected.appointment_date} at {selected.appointment_time}</div>
            </div>
            <button onClick={()=>setSelected(null)} style={{ background:"none", border:"none", fontSize:18, color:"#888", cursor:"pointer" }}>├ù</button>
          </div>

          {/* Documents */}
          <div style={{ marginBottom:"1rem" }}>
            <div style={{ fontSize:12, fontWeight:600, color:"#000", marginBottom:8 }}>≡ƒôä Submitted Documents</div>
            {documents.length===0&&<div style={{ fontSize:11, color:"#888" }}>No documents uploaded yet</div>}
            {documents.map(doc=>(
              <div key={doc.id} style={{ display:"flex", alignItems:"center", justifyContent:"space-between", background:"#ffffff", borderRadius:8, padding:"0.6rem 0.75rem", marginBottom:6, border:"1px solid #eeeeee" }}>
                <div>
                  <div style={{ fontSize:12, fontWeight:600, color:"#000" }}>{doc.type.replace(/_/g," ").replace(/\b\w/g,l=>l.toUpperCase())}</div>
                  <a href={doc.document_url} target="_blank" rel="noopener noreferrer" style={{ fontSize:10, color:"#378add" }}>View document ΓåÆ</a>
                </div>
                <div style={{ display:"flex", gap:6 }}>
                  <button onClick={()=>verifyDocument(doc.id, true)} disabled={doc.is_verified}
                    style={{ background:doc.is_verified?"#f0fdf4":"#ffffff", border:`1px solid ${doc.is_verified?"#1d9e7540":"#dddddd"}`, borderRadius:6, color:doc.is_verified?"#1d9e75":"#555", fontSize:10, padding:"3px 8px", cursor:doc.is_verified?"default":"pointer" }}>
                    {doc.is_verified?"Γ£ô Verified":"Verify"}
                  </button>
                  {doc.is_verified&&<button onClick={()=>verifyDocument(doc.id, false)}
                    style={{ background:"none", border:"1px solid #e24b4a30", borderRadius:6, color:"#e24b4a", fontSize:10, padding:"3px 8px", cursor:"pointer" }}>
                    Unverify
                  </button>}
                </div>
              </div>
            ))}
          </div>

          {/* Assessment */}
          {selected.status!=="completed"&&(
            <div>
              <div style={{ fontSize:12, fontWeight:600, color:"#000", marginBottom:8 }}>≡ƒô¥ Assessment Result</div>
              <div style={{ display:"flex", gap:8, marginBottom:10 }}>
                {["passed","failed","conditional"].map(r=>(
                  <button key={r} onClick={()=>setResult(r)}
                    style={{ flex:1, background:result===r?(r==="passed"?"#1d9e75":r==="failed"?"#e24b4a":"#e6821e"):"#ffffff", border:`1px solid ${result===r?(r==="passed"?"#1d9e75":r==="failed"?"#e24b4a":"#e6821e"):"#eeeeee"}`, borderRadius:8, padding:"8px", cursor:"pointer", color:result===r?"#fff":"#555", fontSize:12, fontWeight:result===r?700:400, textTransform:"capitalize" }}>
                    {r==="passed"?"Γ£ô Passed":r==="failed"?"Γ£ù Failed":"ΓÜá∩╕Å Conditional"}
                  </button>
                ))}
              </div>
              <textarea value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Assessment notes (shared with driver if rejected)..."
                style={{ width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"10px 12px", color:"#000", fontSize:12, outline:"none", resize:"vertical", minHeight:80, marginBottom:10, fontFamily:"DM Sans,sans-serif" }}/>
              <div style={{ display:"flex", gap:8 }}>
                <button onClick={()=>{ setRescheduling(selected.id); setRescheduleForm({ date:selected.appointment_date||"", time:selected.appointment_time||"" }) }}
                  style={{ flex:1, background:"none", border:"1px solid #e6821e40", borderRadius:8, color:"#e6821e", fontSize:12, padding:"9px", cursor:"pointer" }}>
                  Reschedule
                </button>
                <button onClick={submitAssessment} disabled={saving||!result}
                  style={{ flex:2, background:saving||!result?"#e0e0e0":"#8b5cf6", border:"none", borderRadius:8, color:saving||!result?"#555":"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"9px 20px", cursor:saving||!result?"not-allowed":"pointer" }}>
                  {saving?"Saving...":"Submit Assessment"}
                </button>
              </div>
            </div>
          )}
          {selected.status==="completed"&&(
            <div style={{ background:selected.assessment_result==="passed"?"#f0fdf4":"#fff5f5", borderRadius:8, padding:"0.75rem" }}>
              <div style={{ fontSize:12, fontWeight:600, color:selected.assessment_result==="passed"?"#1d9e75":"#e24b4a" }}>
                Result: {selected.assessment_result?.toUpperCase()}
              </div>
              {selected.assessment_notes&&<div style={{ fontSize:11, color:"#555", marginTop:4 }}>{selected.assessment_notes}</div>}
            </div>
          )}
        </div>
      )}

      {/* Reschedule Modal */}
      {rescheduling&&(
        <div style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:12, padding:"1.25rem", marginBottom:"1rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#e6821e", marginBottom:12 }}>≡ƒôà Reschedule Appointment</div>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10, marginBottom:12 }}>
            <div>
              <label style={{ fontSize:11, color:"#666", display:"block", marginBottom:4 }}>New date</label>
              <input type="date" value={rescheduleForm.date} onChange={e=>setRescheduleForm(f=>({...f,date:e.target.value}))}
                style={{ width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"9px 12px", fontSize:12, outline:"none" }}/>
            </div>
            <div>
              <label style={{ fontSize:11, color:"#666", display:"block", marginBottom:4 }}>New time</label>
              <input type="time" value={rescheduleForm.time} onChange={e=>setRescheduleForm(f=>({...f,time:e.target.value}))}
                style={{ width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"9px 12px", fontSize:12, outline:"none" }}/>
            </div>
          </div>
          <div style={{ display:"flex", gap:8 }}>
            <button onClick={rescheduleAppointment} style={{ background:"#e6821e", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"9px 20px", cursor:"pointer" }}>Confirm reschedule</button>
            <button onClick={()=>setRescheduling(null)} style={{ background:"none", border:"1px solid #ddd", borderRadius:8, color:"#888", fontSize:12, padding:"9px 16px", cursor:"pointer" }}>Cancel</button>
          </div>
        </div>
      )}

      {/* Search */}
      {/* Unverified drivers quick panel */}
      {unverifiedDrivers.length>0&&(
        <div style={{ background:"#fff8f0", border:"1px solid #e6821e30", borderRadius:12, padding:"1rem", marginBottom:"1.25rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#e6821e", marginBottom:8 }}>ΓÜá∩╕Å {unverifiedDrivers.length} drivers awaiting verification</div>
          <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
            {unverifiedDrivers.map(d=>(
              <div key={d.id} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", background:"#fff", borderRadius:8, padding:"8px 12px" }}>
                <div>
                  <div style={{ fontSize:12, fontWeight:600 }}>{d.first_name} {d.last_name}</div>
                  <div style={{ fontSize:10, color:"#888" }}>{d.driver_vehicle_type} ┬╖ Joined {new Date(d.created_at).toLocaleDateString()}</div>
                </div>
                <button onClick={()=>verifySingleDriver(d.id, d.first_name+" "+d.last_name)}
                  style={{ background:"#1d9e75", border:"none", borderRadius:7, color:"#fff", fontSize:11, fontWeight:700, padding:"5px 12px", cursor:"pointer" }}>
                  Γ£à Verify
                </button>
              </div>
            ))}
          </div>
        </div>
      )}
      <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search by driver name..."
        style={{ width:"100%", background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:8, padding:"9px 12px", fontSize:12, outline:"none", marginBottom:10, fontFamily:"DM Sans,sans-serif" }}/>

      {/* Appointments list */}
      {filtered.filter(a=>`${a.driver?.first_name} ${a.driver?.last_name}`.toLowerCase().includes(search.toLowerCase())).map(appt=>(
        <div key={appt.id} onClick={()=>selectAppointment(appt)}
          style={{ background:"#f8f8f8", border:`1px solid ${selected?.id===appt.id?"#8b5cf6":"#eeeeee"}`, borderRadius:10, padding:"1rem", marginBottom:8, cursor:"pointer" }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
            <div>
              <div style={{ fontSize:13, fontWeight:600, color:"#000", marginBottom:2 }}>{appt.driver?.first_name} {appt.driver?.last_name}</div>
              <div style={{ fontSize:11, color:"#888", marginBottom:2 }}>≡ƒôà {appt.appointment_date} ┬╖ ΓÅ░ {appt.appointment_time}</div>
              <div style={{ fontSize:11, color:"#888" }}>Vehicle: {appt.driver?.driver_category==="concierge"?"≡ƒºæΓÇìΓ£ê∩╕Å Concierge Driver":(appt.driver?.driver_vehicle_type||"ΓÇö")}</div>
            </div>
            <div style={{ textAlign:"right" }}>
              <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:`${STATUS_COLORS[appt.status]||"#888"}20`, color:STATUS_COLORS[appt.status]||"#888", fontWeight:600 }}>{appt.status}</span>
              {appt.assessment_result&&<div style={{ fontSize:10, color:appt.assessment_result==="passed"?"#1d9e75":"#e24b4a", marginTop:4, fontWeight:600 }}>{appt.assessment_result}</div>}
            </div>
          </div>
        </div>
      ))}
      {!loading&&filtered.length===0&&(
        <div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>
          No {tab} appointments
        </div>
      )}
    </div>
  )
}

import { VehicleIcon, WarningIcon, CheckIcon, LocationIcon, StarIcon, AnalyticsIcon, TripReportIcon, MotorcycleIcon, TukTukIcon, DeliveryIcon, DriversIcon, CloseIcon } from "../../lib/cccIcons"
import { useEffect, useState, useRef } from "react"
import { useAuth } from "../../contexts/AuthContext"
import { supabase } from "../../lib/supabase"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"
import { validateFile } from "../../lib/uploadValidation"

export default function AdminDrivers() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const isMobile = useIsMobile()
  const [drivers, setDrivers] = useState([])
  const [driverDocs, setDriverDocs] = useState({})
  const [driverStatuses, setDriverStatuses] = useState([])
  const [loading, setLoading] = useState(true)
  const [showMap, setShowMap] = useState(false)
  const [onlineDrivers, setOnlineDrivers] = useState([])
  const mapRef = useRef(null)
  const mapInstanceRef = useRef(null)
  const markersRef = useRef({})
  const [tab, setTab] = useState("all")
  const [selected, setSelected] = useState(null)
  const [search, setSearch] = useState("")
  const [categoryFilter, setCategoryFilter] = useState("all")
  const [rejectingId, setRejectingId] = useState(null)
  const [rejectReason, setRejectReason] = useState("")
  const [viewingDocs, setViewingDocs] = useState(null)
  const [probations, setProbations] = useState([])
    
  useEffect(() => {
    load()
    const sub = supabase.channel("admin-drivers-live")
      .on("postgres_changes", { event:"*", schema:"public", table:"driver_status" }, () => loadStatuses())
      .on("postgres_changes", { event:"*", schema:"public", table:"profiles" }, () => loadDrivers())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [])

  useEffect(() => {
    if (tab==="map") initMap()
    return () => { if (mapInstanceRef.current) { mapInstanceRef.current.remove(); mapInstanceRef.current = null } }
  }, [tab, driverStatuses])

  async function load() {
    await Promise.all([loadDrivers(), loadStatuses()])
    setLoading(false)
  }

  async function loadOnlineDrivers() {
    const { data } = await supabase.from("driver_status")
      .select("*, profiles!driver_status_driver_id_fkey(first_name,last_name)")
      .eq("is_online", true)
      .not("current_latitude", "is", null)
    setOnlineDrivers(data||[])
  }

  useEffect(() => {
    if (!showMap) return
    loadOnlineDrivers()
    const interval = setInterval(loadOnlineDrivers, 15000)
    return () => clearInterval(interval)
  }, [showMap])

  useEffect(() => {
    if (!showMap || !mapRef.current) return
    function initMap() {
      if (mapInstanceRef.current) {
        Object.keys(markersRef.current).forEach(k => { try{markersRef.current[k].remove()}catch(e){/* marker already removed */} })
        markersRef.current = {}
        onlineDrivers.forEach(d => {
          if (!d.current_latitude) return
          const m = window.L.marker([d.current_latitude, d.current_longitude])
            .bindPopup("≡ƒÜù " + (d.profiles?.first_name||"") + " " + (d.profiles?.last_name||"")).addTo(mapInstanceRef.current)
          markersRef.current[d.driver_id] = m
        })
        return
      }
      const map = window.L.map(mapRef.current, { zoomControl:true, attributionControl:false }).setView([-1.2921, 36.8219], 12)
      window.L.tileLayer("https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png").addTo(map)
      mapInstanceRef.current = map
      onlineDrivers.forEach(d => {
        if (!d.current_latitude) return
        const m = window.L.marker([d.current_latitude, d.current_longitude])
          .bindPopup("≡ƒÜù " + (d.profiles?.first_name||"") + " " + (d.profiles?.last_name||"")).addTo(map)
        markersRef.current[d.driver_id] = m
      })
    }
    if (!window.L) {
      if (!document.getElementById("leaflet-css")) {
        const link = document.createElement("link"); link.id="leaflet-css"; link.rel="stylesheet"
        link.href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"; document.head.appendChild(link)
      }
      const script = document.createElement("script")
      script.src = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"
      script.onload = initMap; document.head.appendChild(script)
    } else { initMap() }
  }, [showMap, onlineDrivers])

  async function loadDrivers() {
    const [{ data: drvs }, { data: probs }, { data: docs }] = await Promise.all([
      supabase.from("profiles").select("*").eq("role","driver").order("created_at",{ascending:false}),
      supabase.from("driver_probation").select("*"),
      supabase.from("driver_documents").select("*")
    ])
    setDrivers(drvs||[])
    setProbations(probs||[])
    const docMap = {}
    ;(docs||[]).forEach(doc => {
      if (!docMap[doc.driver_id]) docMap[doc.driver_id] = {}
      if (!docMap[doc.driver_id][doc.type] || new Date(doc.created_at) > new Date(docMap[doc.driver_id][doc.type].created_at)) {
        docMap[doc.driver_id][doc.type] = doc
      }
    })
    setDriverDocs(docMap)
  }

  async function loadStatuses() {
    const { data } = await supabase.from("driver_status").select("*")
    setDriverStatuses(data||[])
  }

  function getProbation(driverId) {
    return probations.find(p=>p.driver_id===driverId)
  }

  function getStatus(driverId) {
    return driverStatuses.find(s=>s.driver_id===driverId)
  }

  async function verifyDriver(driverId, verified) {
    try {
      const { data, error } = await supabase
        .from("profiles")
        .update({ documents_verified: verified, is_active: true })
        .eq("id", driverId)
        .select()
      if (error) throw error
      await supabase.from("driver_documents").update({ is_verified: verified, status: verified?"approved":"pending", verified_at: verified?new Date().toISOString():null }).eq("driver_id", driverId)
      await supabase.from("notifications").insert({
        user_id: driverId,
        title: verified ? "Account verified! Γ£à" : "Verification revoked ΓÜá∩╕Å",
        message: verified ? "Your documents have been verified. You can now go online and accept jobs!" : "Your account verification has been revoked. Contact support.",
        type: verified ? "success" : "warning",
      })
      toast.success(verified ? "Driver verified Γ£ô" : "Verification revoked")
      loadDrivers()
    } catch(err) {
      toast.error(err.message)
    }
  }

  async function rejectDriver(driverId) {
    if (!rejectReason.trim()) return toast.error("Please add a rejection reason")
    try {
      const { error } = await supabase
        .from("profiles")
        .update({ documents_verified: false, is_active: false })
        .eq("id", driverId)
      if (error) throw error
      await supabase.from("notifications").insert({
        user_id: driverId,
        title: "Verification rejected Γ¥î",
        message: "Your driver verification was rejected: " + rejectReason + ". Please update your documents and resubmit.",
        type: "error",
      })
      toast.success("Driver rejected and notified")
      setRejectingId(null)
      setRejectReason("")
      loadDrivers()
    } catch(err) {
      toast.error(err.message)
    }
  }

  async function suspendDriver(driverId, suspend) {
    const { error } = await supabase.from("profiles").update({ is_active:!suspend }).eq("id",driverId)
    if (error) return toast.error(error.message)
    if (suspend) await supabase.from("driver_status").update({ is_online:false }).eq("driver_id",driverId)
    toast.success(suspend?"Driver suspended":"Driver reactivated")
    loadDrivers()
  }

  async function recordNoShow(driverId) {
    if (!confirm("Record a no-show for this driver?")) return
    const { data: status } = await supabase.from("driver_status").select("no_show_count").eq("driver_id",driverId).maybeSingle()
    const noShowCount = (status?.no_show_count||0) + 1
    let penaltyType = "warning"
    let suspendUntil = null
    let isSuspended = false
    if (noShowCount === 2) { penaltyType = "suspension_24h"; suspendUntil = new Date(Date.now()+24*60*60*1000).toISOString(); isSuspended = true }
    if (noShowCount === 3) { penaltyType = "suspension_72h"; suspendUntil = new Date(Date.now()+72*60*60*1000).toISOString(); isSuspended = true }
    if (noShowCount >= 4) { penaltyType = "permanent_ban"; suspendUntil = null; isSuspended = true }
    await Promise.all([
      supabase.from("driver_penalties").insert({ driver_id:driverId, penalty_type:penaltyType, reason:"No-show ΓÇö failed to complete accepted job", is_active:true, expires_at:suspendUntil }),
      supabase.from("driver_status").update({ no_show_count:noShowCount, is_suspended:isSuspended, suspension_expires_at:suspendUntil, is_online:false }).eq("driver_id",driverId),
      supabase.from("notifications").insert({ user_id:driverId, title:"Penalty recorded ΓÜá∩╕Å", message:`No-show recorded. Count: ${noShowCount}. ${isSuspended?"Account suspended.":"Please complete accepted jobs."}`, type:"error" }),
    ])
    toast.success(`No-show recorded ΓÇö ${penaltyType.replace(/_/g," ")}`)
    load()
  }

  async function clearPenalties(driverId) {
    if (!confirm("Clear all penalties for this driver?")) return
    await Promise.all([
      supabase.from("driver_penalties").update({ is_active:false }).eq("driver_id",driverId),
      supabase.from("driver_status").update({ no_show_count:0, is_suspended:false, suspension_expires_at:null }).eq("driver_id",driverId),
    ])
    toast.success("Penalties cleared")
    load()
  }

  function initMap() {
    setTimeout(() => {
      if (!mapRef.current || !window.L) return
      if (mapInstanceRef.current) { mapInstanceRef.current.remove(); mapInstanceRef.current = null }
      const L = window.L
      const map = L.map(mapRef.current).setView([-1.2921,36.8219],11)
      L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png").addTo(map)
      driverStatuses.filter(s=>s.current_latitude&&s.is_online).forEach(s=>{
        const driver = drivers.find(d=>d.id===s.driver_id)
        const icon = L.divIcon({ className:"", html:`<div style="background:#1d9e75;width:34px;height:34px;border-radius:50%;border:3px solid #fff;display:flex;align-items:center;justify-content:center;font-size:16px;">≡ƒÜù</div>`, iconSize:[34,34], iconAnchor:[17,17] })
        L.marker([s.current_latitude,s.current_longitude],{icon}).addTo(map).bindPopup(`<b>${driver?.first_name||""} ${driver?.last_name||""}</b><br>${s.current_booking_id?"On job":"Available"}`)
      })
      mapInstanceRef.current = map
    }, 200)
  }

  const filtered = drivers.filter(d=>{
    const matchSearch = `${d.first_name} ${d.last_name} ${d.license_number||""} ${d.id_number||""}`.toLowerCase().includes(search.toLowerCase())
    const matchCategory = categoryFilter==="all" || (d.driver_category||"marketplace")===categoryFilter
    const status = getStatus(d.id)
    if (tab==="online") return matchSearch && matchCategory && status?.is_online
    if (tab==="verified") return matchSearch && matchCategory && d.documents_verified
    if (tab==="pending") return matchSearch && matchCategory && !d.documents_verified && d.is_active
    if (tab==="suspended") return matchSearch && matchCategory && (!d.is_active || status?.is_suspended)
    return matchSearch && matchCategory
  })

  const onlineCount = driverStatuses.filter(s=>s.is_online).length
  const verifiedCount = drivers.filter(d=>d.documents_verified).length
  const pendingCount = drivers.filter(d=>!d.documents_verified&&d.is_active).length
  const suspendedCount = drivers.filter(d=>!d.is_active||driverStatuses.find(s=>s.driver_id===d.id)?.is_suspended).length

  const TABS = [
    { k:"all", l:`All (${drivers.length})` },
    { k:"online", l:`Online (${onlineCount})` },
    { k:"verified", l:`Verified (${verifiedCount})` },
    { k:"pending", l:`Pending (${pendingCount})` },
    { k:"suspended", l:`Suspended (${suspendedCount})` },
    { k:"map", l:"Live map", icon:"map" },
  ]

  return (
    <div>
      <style>{`@import url('https://unpkg.com/leaflet@1.9.4/dist/leaflet.css');`}</style>
      <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"/>

      {/* Stats */}
      <div style={{ display:"grid", gridTemplateColumns:isMobile?"repeat(2,1fr)":"repeat(4,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Total drivers", value:drivers.length, color:"#000000" },
          { label:"Online now", value:onlineCount, color:"#1d9e75" },
          { label:"Verified", value:verifiedCount, color:"#378add" },
          { label:"Pending verification", value:pendingCount, color:"#e6821e" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:isMobile?"0.75rem":"1rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontSize:10, color:"#888", textTransform:"uppercase", marginBottom:4 }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:s.color }}>{s.value}</div>
          </div>
        ))}
      </div>

      {/* Tabs */}
      <div style={{ display:"flex", gap:6, marginBottom:"1.25rem", flexWrap:"wrap" }}>
        {TABS.map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{ padding:"8px 14px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#8b5cf6":"#f8f8f8", color:tab===t.k?"#fff":"#666", fontFamily:"'DM Sans',sans-serif", fontWeight:tab===t.k?700:400 }}>
            {t.l}
          </button>
        ))}

      {/* Category filter */}
      <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap" }}>
        {[{k:"all",l:"All categories"},{k:"concierge",l:"Concierge",icon:"concierge"},{k:"marketplace",l:"Marketplace",icon:"vehicle"}].map(c=>(
          <button key={c.k} onClick={()=>setCategoryFilter(c.k)}
            style={{ padding:"6px 12px", borderRadius:7, border:"none", fontSize:11, cursor:"pointer", background:categoryFilter===c.k?"#e6821e":"#f0f0f0", color:categoryFilter===c.k?"#fff":"#555", fontWeight:categoryFilter===c.k?700:400 }}>
            {c.l}
          </button>
        ))}
      </div>
      </div>

      {/* Search */}
      {tab!=="map"&&(
        <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search by name, ID or license..."
          style={{ width:"100%", background:"#f8f8f8", border:"1px solid #f0f0f0", borderRadius:8, padding:"9px 12px", color:"#000000", fontSize:13, outline:"none", marginBottom:"1rem", fontFamily:"'DM Sans',sans-serif" }}/>
      )}

      {/* MAP */}
      {tab==="map"&&(
        <div style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:12, padding:"1rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#000000", marginBottom:6 }}>Live driver locations</div>
          <div style={{ fontSize:11, color:"#888", marginBottom:10 }}>{onlineCount} driver{onlineCount!==1?"s":""} online</div>
          <div ref={mapRef} style={{ height:isMobile?300:450, borderRadius:10, overflow:"hidden", background:"#f5f5f5" }}>
            {onlineCount===0&&(
              <div style={{ height:"100%", display:"flex", alignItems:"center", justifyContent:"center", flexDirection:"column", gap:8 }}>
                <div style={{ display:"flex", justifyContent:"center" }}><TripReportIcon size={32} color="#e6821e"/></div>
                <div style={{ fontSize:12, color:"#888" }}>No drivers online</div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* DRIVERS LIST */}
      {tab!=="map"&&(
        <div>
          {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
          {!loading&&filtered.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No drivers found</div>}

          {filtered.map(d=>{
            const status = getStatus(d.id)
            const isOnline = status?.is_online
            const onJob = status?.current_booking_id
            const isSuspended = !d.is_active || status?.is_suspended
            const noShowCount = status?.no_show_count||0
            return (
              <div key={d.id} style={{ background:"#f8f8f8", border:`1px solid ${isSuspended?"#e24b4a20":d.documents_verified?"#378add20":"#e6821e20"}`, borderRadius:12, padding:isMobile?"0.9rem":"1.1rem", marginBottom:10 }}>
                <div style={{ display:"flex", alignItems:"flex-start", gap:12 }}>
                  <div style={{ width:48, height:48, borderRadius:12, background:isOnline?"#f0fdf4":"#f5f5f5", border:`2px solid ${isOnline?"#1d9e7540":"#e0e0e0"}`, display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontSize:16, fontWeight:800, color:isOnline?"#1d9e75":"#555", flexShrink:0 }}>
                    {d.first_name?.[0]}{d.last_name?.[0]}
                  </div>

                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:6, flexWrap:"wrap" }}>
                      <div style={{ fontSize:14, fontWeight:600, color:"#000000" }}>{d.first_name} {d.last_name}</div>
                      {d.documents_verified&&<span style={{ fontSize:10, color:"#1d9e75", background:"#f0fdf4", padding:"2px 7px", borderRadius:10, border:"1px solid #1d9e7540" }}>Γ£ô Verified</span>}
                      {!d.documents_verified&&d.is_active&&<span style={{ fontSize:10, color:"#e6821e", background:"#fff8f0", padding:"2px 7px", borderRadius:10 }}>ΓÅ│ Pending</span>}
                      {isSuspended&&<span style={{ fontSize:10, color:"#e24b4a", background:"#fff5f5", padding:"2px 7px", borderRadius:10 }}>≡ƒÜ½ Suspended</span>}
                      {(()=>{ const prob = getProbation(d.id); if (!prob) return null; return prob.status==="probation" ? <span style={{ fontSize:10, color:"#8b5cf6", background:"#faf5ff", padding:"2px 7px", borderRadius:10, border:"1px solid #8b5cf640" }}>≡ƒöì Probation ({prob.jobs_completed}/{prob.jobs_required})</span> : prob.status==="completed" ? <span style={{ fontSize:10, color:"#1d9e75", background:"#f0fdf4", padding:"2px 7px", borderRadius:10 }}>Γ£ô Probation passed</span> : null })()}
                      {d.vetting_status==="pending"&&!d.documents_verified&&<span style={{ fontSize:10, color:"#888", background:"#f5f5f5", padding:"2px 7px", borderRadius:10 }}>≡ƒôï Not applied</span>}
                      {d.vetting_status==="documents_submitted"&&<span style={{ fontSize:10, color:"#378add", background:"#eff6ff", padding:"2px 7px", borderRadius:10 }}>≡ƒôä Docs submitted</span>}
                      {d.vetting_status==="approved"&&<span style={{ fontSize:10, color:"#1d9e75", background:"#f0fdf4", padding:"2px 7px", borderRadius:10 }}>≡ƒ¬¬ Vetted</span>}
                      {d.vetting_status==="rejected"&&<span style={{ fontSize:10, color:"#e24b4a", background:"#fff5f5", padding:"2px 7px", borderRadius:10 }}>Γ¥î Rejected</span>}
                      {isOnline&&!isSuspended&&<span style={{ fontSize:10, color:"#1d9e75" }}>≡ƒƒó Online{onJob?" ┬╖ On job":""}</span>}
                      {noShowCount>0&&<span style={{ fontSize:10, color:"#e6821e", background:"#fff8f0", padding:"2px 7px", borderRadius:10 }}>ΓÜá∩╕Å {noShowCount} no-show{noShowCount>1?"s":""}</span>}
                      <span style={{ fontSize:10, color:(d.driver_category||"marketplace")==="concierge"?"#e6821e":"#378add", background:(d.driver_category||"marketplace")==="concierge"?"#fff8f0":"#eff6ff", padding:"2px 7px", borderRadius:10, fontWeight:600 }}>{(d.driver_category||"marketplace")==="concierge"?"≡ƒºæΓÇìΓ£ê∩╕Å Concierge":"≡ƒÜù Marketplace"}</span>
                      {(d.driver_category!=="concierge")&&d.driver_vehicle_type&&<span style={{ fontSize:10, color:"#8b5cf6", background:"#f5f3ff", padding:"2px 7px", borderRadius:10 }}>
                        {d.driver_vehicle_type==="motorcycle"?<><MotorcycleIcon size={12} color="currentColor"/> Boda Boda</>:d.driver_vehicle_type==="tuktuk"?<><TukTukIcon size={12} color="currentColor"/> Tuktuk</>:d.driver_vehicle_type==="van"?"≡ƒÜÉ Van":"≡ƒÜù Car"}
                      </span>}
                    </div>

