function DriverStats({ driverId, isMobile }) {
  const [stats, setStats] = useState(null)
  const [penalties, setPenalties] = useState([])

  useEffect(() => {
    async function load() {
      const [{ data: bks }, { data: revs }, { data: pens }] = await Promise.all([
        supabase.from("bookings").select("id,status,driver_earnings,transport_allowance,booking_date").eq("driver_id",driverId).eq("is_archived",false),
        supabase.from("reviews").select("driver_rating").eq("driver_id",driverId).not("driver_rating","is",null),
        supabase.from("driver_penalties").select("*").eq("driver_id",driverId).order("created_at",{ascending:false}),
      ])
      const completed = bks?.filter(b=>b.status==="completed")||[]
      const totalEarnings = completed.reduce((s,b)=>s+Number(b.driver_earnings||0)+Number(b.transport_allowance||0),0)
      const avgRating = revs?.length?(revs.reduce((s,r)=>s+Number(r.driver_rating),0)/revs.length).toFixed(1):"ΓÇö"
      setStats({ total:bks?.length||0, completed:completed.length, earnings:totalEarnings, rating:avgRating })
      setPenalties(pens||[])
    }
    load()
  }, [driverId])

  if (!stats) return <div style={{ fontSize:12, color:"#888", marginTop:10 }}>Loading stats...</div>

  return (
    <div style={{ marginTop:12, paddingTop:12, borderTop:"1px solid #eeeeee" }}>
      <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:8, marginBottom:12 }}>
        {[
          { label:"Total jobs", value:stats.total, color:"#000000" },
          { label:"Completed", value:stats.completed, color:"#1d9e75" },
          { label:"Rating", value:stats.rating, color:"#e6821e" },
          { label:"Total earned", value:`KES ${Number(stats.earnings).toLocaleString()}`, color:"#8b5cf6" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#ffffff", borderRadius:8, padding:"0.6rem", textAlign:"center" }}>
            <div style={{ fontFamily:"Syne", fontSize:isMobile?12:14, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:9, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>

      {penalties.length>0&&(
        <div>
          <div style={{ fontSize:11, color:"#888", marginBottom:6 }}>Penalty history</div>
          {penalties.slice(0,5).map(p=>(
            <div key={p.id} style={{ display:"flex", justifyContent:"space-between", padding:"5px 0", borderBottom:"1px solid #f5f5f5", fontSize:11 }}>
              <span style={{ color:p.is_active?"#e24b4a":"#cccccc" }}>{p.penalty_type?.replace(/_/g," ")}</span>
              <span style={{ color:"#888" }}>{new Date(p.created_at).toLocaleDateString()}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

