const CATEGORY_COLORS = {
  business:"#e6821e", payments:"#1d9e75", users:"#378add", system:"#8b5cf6"
}

const DIAGNOSTICS = {
  stuck_bookings: {
    causes:["Provider has not confirmed the booking","Provider may be offline","Provider missed the notification"],
    resolution:"Send reminder notification to provider",
    link:"/admin-dashboard/bookings",
    autoFix: async () => {
      const dayAgo = new Date(Date.now()-24*60*60*1000).toISOString()
      const { data } = await supabase.from("bookings").select("provider_id,service_name,booking_number").eq("status","pending").lt("created_at",dayAgo)
      if (!data?.length) return "No stuck bookings found"
      for (const b of data) {
        await supabase.from("notifications").insert({ user_id:b.provider_id, title:"ΓÅ░ Booking needs attention", message:`Booking #${b.booking_number} for ${b.service_name} has been pending over 24 hours. Please confirm or decline.`, type:"warning" })
      }
      return `Reminder sent to ${data.length} provider(s)`
    }
  },
  go_service_timeout: {
    causes:["No providers currently online","All nearby providers declined","Provider not checking app"],
    resolution:"Notify all active providers of pending emergency",
    link:"/admin-dashboard/mechanics",
    autoFix: async () => {
      const { data: providers } = await supabase.from("profiles").select("id").eq("role","provider").eq("is_active",true)
      if (!providers?.length) return "No providers found"
      for (const p of providers) {
        await supabase.from("notifications").insert({ user_id:p.id, title:"≡ƒÜ¿ Emergency request waiting", message:"A customer has an emergency GO Service request with no provider response. Check your GO Requests tab.", type:"error" })
      }
      return `Alert sent to ${providers.length} provider(s)`
    }
  },
  pending_claims: {
    causes:["Admin has not reviewed the claim","High volume of claims","Claim requires investigation"],
    resolution:"Mark claims as under review to acknowledge them",
    link:"/admin-dashboard/claims",
    autoFix: async () => {
      const dayAgo = new Date(Date.now()-24*60*60*1000).toISOString()
      const { data } = await supabase.from("service_claims").select("id,customer_id").eq("status","pending").lt("created_at",dayAgo)
      if (!data?.length) return "No pending claims found"
      const ids = data.map(c=>c.id)
      await supabase.from("service_claims").update({ status:"under_review" }).in("id",ids)
      for (const c of data) {
        await supabase.from("notifications").insert({ user_id:c.customer_id, title:"Claim update ≡ƒôï", message:"Your service claim is now under review. We will respond within 24 hours.", type:"info" })
      }
      return `${data.length} claim(s) marked under review`
    }
  },
  unanswered_tickets: {
    causes:["Support team missed tickets","High volume of requests","Notification not seen"],
    resolution:"Send acknowledgement to customers with open tickets",
    link:"/admin-dashboard/support",
    autoFix: async () => {
      const dayAgo = new Date(Date.now()-24*60*60*1000).toISOString()
      const { data } = await supabase.from("support_tickets").select("id,customer_id,subject").eq("status","open").lt("created_at",dayAgo)
      if (!data?.length) return "No open tickets found"
      for (const t of data) {
        await supabase.from("notifications").insert({ user_id:t.customer_id, title:"Support update", message:`Your ticket "${t.subject}" is being reviewed. We apologize for the delay.`, type:"info" })
      }
      return `Acknowledgement sent for ${data.length} ticket(s)`
    }
  },
  mileage_alerts: {
    causes:["Driver used vehicle for personal errands","Long service route","Odometer reading error"],
    resolution:"Review and resolve disputes in Disputes & Reports",
    link:"/admin-dashboard/disputes",
    autoFix: null
  },
  pending_payouts: {
    causes:["Payout not processed manually","Provider banking details incomplete"],
    resolution:"Go to Payouts page to process manually",
    link:"/admin-dashboard/payouts",
    autoFix: null
  },
  unpaid_bookings: {
    causes:["Customer paid cash but not marked paid","Payment gateway issue","Provider forgot to mark paid"],
    resolution:"Review and mark completed bookings as paid",
    link:"/admin-dashboard/bookings",
    autoFix: null
  },
  unverified_drivers: {
    causes:["Driver submitted credentials but admin not notified","Documents need manual review"],
    resolution:"Verify drivers in the Drivers section",
    link:"/admin-dashboard/drivers",
    autoFix: null
  },
  mechanics_no_account: {
    causes:["Mechanic was added before the account-linking fix","Edge Function failed during mechanic creation"],
    resolution:"Re-add the mechanic or manually link their account in Mechanics section",
    link:"/admin-dashboard/mechanics",
    autoFix: null
  },
  expiring_vouchers: {
    causes:["Customer not aware voucher is expiring","Customer forgot to use voucher"],
    resolution:"Send reminder to customers with expiring vouchers",
    link:"/admin-dashboard/claims",
    autoFix: async () => {
      const threeDays = new Date(Date.now()+3*24*60*60*1000).toISOString()
      const now = new Date().toISOString()
      const { data } = await supabase.from("service_vouchers").select("customer_id,voucher_code,amount,expires_at").eq("is_used",false).lt("expires_at",threeDays).gt("expires_at",now)
      if (!data?.length) return "No expiring vouchers"
      for (const v of data) {
        await supabase.from("notifications").insert({ user_id:v.customer_id, title:"ΓÅ░ Voucher expiring soon!", message:`Your voucher ${v.voucher_code} worth KES ${Number(v.amount).toLocaleString()} expires ${new Date(v.expires_at).toLocaleDateString()}. Use it before it expires!`, type:"warning" })
      }
      return `Reminder sent for ${data.length} voucher(s)`
    }
  },
  idle_drivers: {
    causes:["Driver forgot to go offline","No concierge bookings available","Driver waiting for jobs"],
    resolution:"Send reminder to go offline if not available",
    link:"/admin-dashboard/drivers",
    autoFix: async () => {
      const { data } = await supabase.from("driver_status").select("driver_id,is_online,current_booking_id,last_seen").eq("is_online",true)
      const fourHrsAgo = new Date(Date.now()-4*60*60*1000).toISOString()
      const idle = data?.filter(d=>!d.current_booking_id&&d.last_seen<fourHrsAgo)||[]
      if (!idle.length) return "No idle drivers found"
      for (const d of idle) {
        await supabase.from("notifications").insert({ user_id:d.driver_id, title:"Reminder", message:"You have been online for over 4 hours with no active job. Please go offline if you are no longer available.", type:"info" })
      }
      return `Reminder sent to ${idle.length} driver(s)`
    }
  },
  database: {
    causes:["High server load","Network latency","Supabase free tier limitations"],
    resolution:"Monitor response times ΓÇö consider upgrading to Supabase Pro",
    link:"https://supabase.com/dashboard",
    autoFix: null
  },
}

function DiagnosticPanel({ checkKey, onResolved }) {
  const [expanded, setExpanded] = useState(false)
  const [resolving, setResolving] = useState(false)
  const diag = DIAGNOSTICS[checkKey]
  if (!diag) return null

  async function handleAutoFix() {
    if (!diag.autoFix) return
    setResolving(true)
    try {
      const msg = await diag.autoFix()
      toast.success(msg||"Action completed")
      if (onResolved) onResolved()
    } catch(err) { toast.error(err.message) }
    finally { setResolving(false) }
  }

  return (
    <div style={{ marginTop:8 }}>
      <button onClick={()=>setExpanded(e=>!e)}
        style={{ background:"none", border:"none", color:"#8b5cf6", fontSize:11, cursor:"pointer", padding:0, fontWeight:600 }}>
        {expanded?"Γû▓ Hide diagnosis":"Γû╝ Show diagnosis & fix"}
      </button>
      {expanded&&(
        <div style={{ marginTop:8, background:"#ffffff", borderRadius:8, padding:"0.9rem" }}>
          <div style={{ marginBottom:10 }}>
            <div style={{ fontSize:11, color:"#888", textTransform:"uppercase", marginBottom:6 }}>Possible causes:</div>
            {diag.causes.map((c,i)=>(
              <div key={i} style={{ display:"flex", gap:8, marginBottom:4 }}>
                <span style={{ color:"#888", flexShrink:0 }}>ΓÇó</span>
                <span style={{ fontSize:11, color:"#888" }}>{c}</span>
              </div>
            ))}
          </div>
          <div style={{ marginBottom:10 }}>
            <div style={{ fontSize:11, color:"#888", textTransform:"uppercase", marginBottom:4 }}>Recommended action:</div>
            <div style={{ fontSize:12, color:"#e6821e" }}>ΓåÆ {diag.resolution}</div>
          </div>
          <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
            {diag.autoFix&&(
              <button onClick={handleAutoFix} disabled={resolving}
                style={{ background:resolving?"#e0e0e0":"#1d9e75", border:"none", borderRadius:7, color:resolving?"#555":"#fff", fontFamily:"Syne,sans-serif", fontSize:11, fontWeight:700, padding:"7px 14px", cursor:resolving?"not-allowed":"pointer" }}>
                {resolving?"Processing...":"ΓÜí Auto-fix"}
              </button>
            )}
            {diag.link&&(
              <a href={diag.link} target={diag.link.startsWith("http")?"_blank":"_self"} rel={diag.link.startsWith("http")?"noopener noreferrer":undefined}
                style={{ background:"#f5f3ff", border:"1px solid #8b5cf640", borderRadius:7, color:"#8b5cf6", fontSize:11, fontWeight:600, padding:"7px 14px", textDecoration:"none" }}>
                Go fix it ΓåÆ
              </a>
            )}
          </div>
        </div>
      )}
    </div>
  )
}

export default function AdminHealth() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const isMobile = useIsMobile()
  const [results, setResults] = useState({})
  const [loading, setLoading] = useState(true)
  const [lastChecked, setLastChecked] = useState(null)
  const [running, setRunning] = useState(false)
  const [logs, setLogs] = useState([])
  const [tab, setTab] = useState("dashboard")

  useEffect(() => { runChecks(); loadLogs() }, [])

  async function loadLogs() {
    const { data } = await supabase.from("system_health_logs").select("*").order("checked_at",{ascending:false}).limit(50)
    setLogs(data||[])
  }

  async function runChecks() {
    setRunning(true)
    const checkResults = {}
    const now = new Date()
    try {
      const dayAgo = new Date(now-24*60*60*1000).toISOString()
      const twoDaysAgo = new Date(now-48*60*60*1000).toISOString()
      const weekAgo = new Date(now-7*24*60*60*1000).toISOString()
      const fourHrsAgo = new Date(now-4*60*60*1000).toISOString()
      const threeDays = new Date(now.getTime()+3*24*60*60*1000).toISOString()

      // Database check
      const dbStart = Date.now()
      const { error: dbError } = await supabase.from("profiles").select("id").limit(1)
      const dbTime = Date.now() - dbStart
      checkResults.database = dbError
        ? { status:"critical", count:0, message:`Database error: ${dbError.message}`, details:[] }
        : { status:dbTime>2000?"warning":"healthy", count:0, message:`Response time: ${dbTime}ms`, details:[] }

      // All other checks
      const [
        { data: stuckBks },
        { data: goTimeouts },
        { data: pendingClaims },
        { data: openTickets },
        { data: mileageAlerts },
        { data: pendingPayouts },
        { data: unpaidBks },
        { data: unverifiedDrivers },
        { data: expiringVouchers },
        { data: onlineDrivers },
        { data: mechanicsNoAccount },
      ] = await Promise.all([
        supabase.from("bookings").select("id,booking_number,service_name,created_at").eq("status","pending").lt("created_at",dayAgo),
        supabase.from("go_service_requests").select("id,attempt_number,sent_at").eq("status","pending"),
        supabase.from("service_claims").select("id,reason,created_at").eq("status","pending").lt("created_at",dayAgo),
        supabase.from("support_tickets").select("id,subject,created_at").eq("status","open").lt("created_at",dayAgo),
        supabase.from("mileage_alerts").select("id,difference,created_at").eq("resolved",false).gt("difference",30).lt("created_at",twoDaysAgo),
        supabase.from("payout_requests").select("id,amount,created_at").eq("status","pending").lt("created_at",weekAgo),
        supabase.from("bookings").select("id,booking_number,total_amount,created_at").eq("status","completed").eq("payment_status","pending").lt("created_at",dayAgo),
        supabase.from("profiles").select("id,first_name,last_name,created_at").eq("role","driver").eq("documents_verified",false).eq("is_active",true).not("license_number","is",null),
        supabase.from("service_vouchers").select("id,voucher_code,amount,expires_at").eq("is_used",false).lt("expires_at",threeDays).gt("expires_at",now.toISOString()),
        supabase.from("driver_status").select("driver_id,is_online,current_booking_id,last_seen").eq("is_online",true),
        supabase.from("mechanics").select("id,first_name,last_name,created_at").is("user_id",null).eq("is_active",true),
      ])

      const idleDrivers = onlineDrivers?.filter(d=>!d.current_booking_id&&(d.last_seen||"")< fourHrsAgo)||[]

      const mk = (data, crit, warn, goodMsg, badMsg, detailFn) => ({
        status: (data?.length||0)>=crit?"critical":(data?.length||0)>=warn?"warning":"healthy",
        count: data?.length||0,
        message: (data?.length||0)>0?`${data.length} ${badMsg}`:`Γ£ô ${goodMsg}`,
        details: data?.slice(0,5).map(detailFn)||[]
      })

      checkResults.stuck_bookings = mk(stuckBks,5,1,"All bookings processing","booking(s) stuck in pending",b=>({label:`#${b.booking_number} ΓÇö ${b.service_name}`,time:b.created_at}))
      checkResults.go_service_timeout = mk(goTimeouts,1,1,"No pending emergencies","emergency request(s) awaiting response",r=>({label:`Attempt ${r.attempt_number}/5`,time:r.sent_at}))
      checkResults.pending_claims = mk(pendingClaims,3,1,"All claims reviewed","claim(s) awaiting review >24hrs",c=>({label:c.reason,time:c.created_at}))
      checkResults.unanswered_tickets = mk(openTickets,5,1,"All tickets answered","ticket(s) unanswered >24hrs",t=>({label:t.subject,time:t.created_at}))
      checkResults.mileage_alerts = mk(mileageAlerts,5,1,"All mileage alerts resolved","mileage alert(s) unresolved >48hrs",a=>({label:`${a.difference}km over threshold`,time:a.created_at}))
      checkResults.pending_payouts = mk(pendingPayouts,3,1,"All payouts processed","payout(s) pending >7 days",p=>({label:`KES ${Number(p.amount).toLocaleString()}`,time:p.created_at}))
      checkResults.unpaid_bookings = mk(unpaidBks,10,1,"All payments up to date","completed booking(s) unpaid",b=>({label:`#${b.booking_number} ΓÇö KES ${Number(b.total_amount).toLocaleString()}`,time:b.created_at}))
      checkResults.unverified_drivers = mk(unverifiedDrivers,5,1,"All drivers verified","driver(s) awaiting verification",d=>({label:`${d.first_name} ${d.last_name}`,time:d.created_at}))
      checkResults.mechanics_no_account = mk(mechanicsNoAccount,3,1,"All mechanics have accounts","mechanic(s) missing a linked login account",m=>({label:`${m.first_name} ${m.last_name||""}`,time:m.created_at}))
      checkResults.expiring_vouchers = mk(expiringVouchers,5,1,"No vouchers expiring soon","voucher(s) expiring within 3 days",v=>({label:`${v.voucher_code} ΓÇö KES ${Number(v.amount).toLocaleString()}`,time:v.expires_at}))
      checkResults.idle_drivers = mk(idleDrivers,3,1,"All online drivers active","driver(s) idle online >4hrs",d=>({label:`Driver: ${d.driver_id?.slice(0,8)}`,time:d.last_seen}))

      setResults(checkResults)
      setLastChecked(new Date())

      const criticalCount = Object.values(checkResults).filter(r=>r.status==="critical").length
      const warningCount = Object.values(checkResults).filter(r=>r.status==="warning").length
      const overallStatus = criticalCount>0?"critical":warningCount>0?"warning":"healthy"

      await supabase.from("system_health_logs").insert({
        check_type:"full_scan", status:overallStatus,
        message:`${criticalCount} critical, ${warningCount} warnings`,
        affected_count:criticalCount+warningCount,
        details:checkResults,
      })

      if (criticalCount>0) toast.error(`≡ƒö┤ ${criticalCount} critical issue(s) found`,{duration:8000})
      else if (warningCount>0) toast(`ΓÜá∩╕Å ${warningCount} warning(s) found`,{duration:5000})
      else toast.success("Γ£à All systems healthy")
      loadLogs()
    } catch(err) {
      toast.error("Health check failed: "+err.message)
    } finally {
      setRunning(false)
      setLoading(false)
    }
  }

  const critical = Object.values(results).filter(r=>r?.status==="critical").length
  const warnings = Object.values(results).filter(r=>r?.status==="warning").length
  const healthy = Object.values(results).filter(r=>r?.status==="healthy").length
  const overallStatus = critical>0?"critical":warnings>0?"warning":"healthy"
  const overallColor = overallStatus==="critical"?"#e24b4a":overallStatus==="warning"?"#e6821e":"#1d9e75"
  const categories = [...new Set(CHECKS.map(c=>c.category))]

  return (
    <div>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:"1.5rem", flexWrap:"wrap", gap:10 }}>
        <div>
          <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:"#000000" }}>System Health Monitor</div>
          <div style={{ fontSize:12, color:"#888", marginTop:2 }}>{lastChecked?`Last checked: ${lastChecked.toLocaleTimeString()}`:"Running checks..."}</div>
        </div>
        <button onClick={runChecks} disabled={running}
          style={{ background:running?"#e0e0e0":"#8b5cf6", border:"none", borderRadius:9, color:running?"#555":"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"10px 20px", cursor:running?"not-allowed":"pointer" }}>
          {running?"ΓÅ│ Checking...":"≡ƒöä Run checks"}
        </button>
      </div>

      {/* Overall status */}
      <div style={{ background:overallStatus==="critical"?"#fff5f5":overallStatus==="warning"?"#fff8f0":"#f0fdf4", border:`2px solid ${overallColor}`, borderRadius:14, padding:"1.25rem", marginBottom:"1.5rem", textAlign:"center" }}>
        <div style={{ fontSize:40, marginBottom:8 }}>{overallStatus==="critical"?"≡ƒö┤":overallStatus==="warning"?"≡ƒƒí":"≡ƒƒó"}</div>
        <div style={{ fontFamily:"Syne", fontSize:isMobile?18:22, fontWeight:800, color:overallColor, marginBottom:4 }}>
          {overallStatus==="critical"?"CRITICAL ISSUES FOUND":overallStatus==="warning"?"WARNINGS DETECTED":"ALL SYSTEMS HEALTHY"}
        </div>
        <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:10, marginTop:12, maxWidth:360, margin:"12px auto 0" }}>
          {[
            { label:"Critical", value:critical, color:"#e24b4a" },
            { label:"Warnings", value:warnings, color:"#e6821e" },
            { label:"Healthy", value:healthy, color:"#1d9e75" },
          ].map(s=>(
            <div key={s.label} style={{ background:"rgba(0,0,0,0.3)", borderRadius:8, padding:"0.6rem" }}>
              <div style={{ fontFamily:"Syne", fontSize:20, fontWeight:800, color:s.color }}>{s.value}</div>
              <div style={{ fontSize:10, color:"#888" }}>{s.label}</div>
            </div>
          ))}
        </div>
      </div>

      {/* Tabs */}
      <div style={{ display:"flex", gap:6, marginBottom:"1.25rem" }}>
        {[{k:"dashboard",l:"Dashboard"},{k:"logs",l:`History (${logs.length})`}].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{ padding:"8px 16px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#8b5cf6":"#f8f8f8", color:tab===t.k?"#fff":"#666", fontFamily:"'DM Sans',sans-serif", fontWeight:tab===t.k?700:400 }}>
            {t.l}
          </button>
        ))}
      </div>

      {/* DASHBOARD */}
      {tab==="dashboard"&&(
        <div>
          {loading&&(
            <div style={{ textAlign:"center", padding:"3rem", color:"#888", fontSize:13 }}>
              <div style={{ fontSize:32, marginBottom:10 }}>ΓÅ│</div>
              Running system checks...
            </div>
          )}
          {!loading&&categories.map(cat=>(
            <div key={cat} style={{ marginBottom:"1.5rem" }}>
              <div style={{ fontSize:11, fontWeight:700, textTransform:"uppercase", letterSpacing:"0.05em", color:CATEGORY_COLORS[cat], marginBottom:8 }}>
                {cat==="business"?"≡ƒôè Business":cat==="payments"?"≡ƒÆ░ Payments":cat==="users"?"≡ƒæÑ Users":"≡ƒûÑ∩╕Å System"}
              </div>
              {CHECKS.filter(c=>c.category===cat).map(check=>{
                const result = results[check.key]
                if (!result) return null
                const color = result.status==="critical"?"#e24b4a":result.status==="warning"?"#e6821e":"#1d9e75"
                return (
                  <div key={check.key} style={{ background:"#f8f8f8", border:`1px solid ${color}30`, borderRadius:10, padding:"0.9rem", marginBottom:8 }}>
                    <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                      <div style={{ flex:1, minWidth:0 }}>
                        <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4, flexWrap:"wrap" }}>
                          <span style={{ fontSize:16 }}>{check.icon}</span>
                          <div style={{ fontSize:13, fontWeight:600, color:"#000000" }}>{check.label}</div>
                          <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:`${color}20`, color }}>{result.status}</span>
                          {result.count>0&&<span style={{ fontSize:10, color:"#888" }}>{result.count} affected</span>}
                        </div>
                        <div style={{ fontSize:12, color:"#888" }}>{result.message}</div>
                      </div>
                      <div style={{ width:10, height:10, borderRadius:"50%", background:color, boxShadow:`0 0 6px ${color}`, flexShrink:0, marginTop:4 }}/>
                    </div>
                    {result.details?.length>0&&(
                      <div style={{ marginTop:8, paddingTop:8, borderTop:`1px solid ${color}20` }}>
                        {result.details.map((d,i)=>(
                          <div key={i} style={{ display:"flex", justifyContent:"space-between", fontSize:11, padding:"4px 0", borderBottom:"1px solid #f5f5f5" }}>
                            <span style={{ color:"#888" }}>{d.label}</span>
                            <span style={{ color:"#888" }}>{d.time?new Date(d.time).toLocaleString():""}</span>
                          </div>
                        ))}
                      </div>
                    )}
                    {result.status!=="healthy"&&<DiagnosticPanel checkKey={check.key} onResolved={runChecks}/>}
                  </div>
                )
              })}
            </div>
          ))}
        </div>
      )}

      {/* LOGS */}
      {tab==="logs"&&(
        <div>
          {logs.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No health check history yet</div>}
          {logs.map(log=>{
            const color = log.status==="critical"?"#e24b4a":log.status==="warning"?"#e6821e":"#1d9e75"
            return (
              <div key={log.id} style={{ background:"#f8f8f8", border:`1px solid ${color}20`, borderRadius:10, padding:"0.9rem", marginBottom:8 }}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                  <div>
                    <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4 }}>
                      <div style={{ width:8, height:8, borderRadius:"50%", background:color }}/>
                      <div style={{ fontSize:12, fontWeight:600, color }}>{log.status?.toUpperCase()}</div>
                      <div style={{ fontSize:11, color:"#888" }}>{log.affected_count} issue{log.affected_count!==1?"s":""}</div>
                    </div>
                    <div style={{ fontSize:12, color:"#888" }}>{log.message}</div>
                  </div>
                  <div style={{ fontSize:10, color:"#888", flexShrink:0 }}>{new Date(log.checked_at).toLocaleString()}</div>
                </div>
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

import { WarningIcon, MarketplaceIcon } from "../../lib/cccIcons"
import { useEffect, useState } from "react"
import { useAuth } from "../../contexts/AuthContext"
import { supabase } from "../../lib/supabase"
import useIsMobile from "../../lib/useIsMobile"

export default function AdminInventory() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const isMobile = useIsMobile()
  const [items, setItems] = useState([])
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useState("")
  const [catFilter, setCatFilter] = useState("all")
  const [providerFilter, setProviderFilter] = useState("all")
  const [providers, setProviders] = useState([])

  useEffect(() => { load() }, [])

  async function load() {
    const { data } = await supabase.from("inventory")
      .select("*, profiles!inventory_provider_id_fkey(id,business_name,first_name,last_name,provider_type,city)")
      .order("created_at", { ascending:false })
    setItems(data||[])
    const unique = [...new Map((data||[]).map(i=>[i.provider_id, i.profiles])).values()]
    setProviders(unique.filter(Boolean))
    setLoading(false)
  }

  const filtered = items.filter(i=>{
    const matchCat = catFilter==="all"||i.category===catFilter
    const matchProvider = providerFilter==="all"||i.provider_id===providerFilter
    const matchSearch = i.name.toLowerCase().includes(search.toLowerCase())||
      (i.brand||"").toLowerCase().includes(search.toLowerCase())
    return matchCat&&matchProvider&&matchSearch
  })

  const totalItems = items.length
  const activeItems = items.filter(i=>i.is_active).length
  const lowStock = items.filter(i=>i.stock_quantity<=5&&i.is_active).length
  const outOfStock = items.filter(i=>i.stock_quantity===0).length
  const totalValue = items.reduce((s,i)=>s+Number(i.price||0)*Number(i.stock_quantity||0),0)

  const CATS = ["all","parts","accessories","tyres","oils","electrical","body","tools","other"]

  return (
    <div>
      <div style={{ marginBottom:"1.25rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:"#000000" }}>Inventory Oversight</div>
        <div style={{ fontSize:12, color:"#888" }}>All provider inventory across platform</div>
      </div>

      <div style={{ display:"grid", gridTemplateColumns:"repeat(5,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Total items", value:totalItems, color:"#000000" },
          { label:"Active", value:activeItems, color:"#1d9e75" },
          { label:"Low stock", value:lowStock, color:lowStock>0?"#e6821e":"#555" },
          { label:"Out of stock", value:outOfStock, color:outOfStock>0?"#e24b4a":"#555" },
          { label:"Total value", value:"KES "+totalValue.toLocaleString(), color:"#8b5cf6" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.75rem", border:"1px solid #eeeeee", textAlign:"center" }}>
            <div style={{ fontFamily:"Syne", fontSize:isMobile?12:16, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:9, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>

      {lowStock>0&&(
        <div style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:10, padding:"0.75rem", marginBottom:"1rem" }}>
          <div style={{ fontSize:13, color:"#e6821e", fontWeight:600, display:"flex", alignItems:"center", gap:4 }}><WarningIcon size={13} color="#e6821e"/> {lowStock} item{lowStock>1?"s":""} low on stock ┬╖ {outOfStock} out of stock</div>
        </div>
      )}

      <div style={{ display:"flex", gap:8, marginBottom:"1rem", flexWrap:"wrap" }}>
        <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search items..."
          style={{ flex:1, minWidth:150, background:"#f8f8f8", border:"1px solid #f0f0f0", borderRadius:8, padding:"8px 12px", color:"#000000", fontSize:12, outline:"none" }}/>
        <select value={providerFilter} onChange={e=>setProviderFilter(e.target.value)}
          style={{ background:"#f8f8f8", border:"1px solid #f0f0f0", borderRadius:8, padding:"8px 12px", color:"#000000", fontSize:12, outline:"none" }}>
          <option value="all">All providers</option>
          {providers.map(p=><option key={p.id} value={p.id}>{p.business_name||p.first_name}</option>)}
        </select>
      </div>

      <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap" }}>
        {CATS.map(c=>(
          <button key={c} onClick={()=>setCatFilter(c)}
            style={{ padding:"5px 10px", borderRadius:7, border:"none", fontSize:11, cursor:"pointer", background:catFilter===c?"#8b5cf6":"#f8f8f8", color:catFilter===c?"#fff":"#666" }}>
            {c}
          </button>
        ))}
      </div>

      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
      {!loading&&filtered.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No items found</div>}

      {filtered.map(item=>(
        <div key={item.id} style={{ background:"#f8f8f8", border:"1px solid "+(item.stock_quantity===0?"#e24b4a30":item.stock_quantity<=5?"#e6821e30":"#eeeeee"), borderRadius:12, padding:"1rem", marginBottom:8, opacity:item.is_active?1:0.6 }}>
          <div style={{ display:"flex", gap:12, alignItems:"flex-start" }}>
            {item.photos?.[0]&&(
              <img src={item.photos[0]} alt="" style={{ width:60, height:60, objectFit:"cover", borderRadius:8, flexShrink:0, border:"1px solid #eee" }}/>
            )}
            <div style={{ flex:1, minWidth:0 }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4, flexWrap:"wrap" }}>
                <div style={{ fontSize:13, fontWeight:600, color:"#000000" }}>{item.name}</div>
                {item.brand&&<span style={{ fontSize:10, color:"#888", background:"#f5f5f5", padding:"1px 6px", borderRadius:6 }}>{item.brand}</span>}
                {!item.is_active&&<span style={{ fontSize:10, color:"#888", background:"#f5f5f5", padding:"1px 6px", borderRadius:6 }}>Hidden</span>}
                {item.stock_quantity===0&&<span style={{ fontSize:10, color:"#e24b4a", background:"#fff5f5", padding:"1px 6px", borderRadius:6 }}>Out of stock</span>}
                {item.stock_quantity>0&&item.stock_quantity<=5&&<span style={{ fontSize:10, color:"#e6821e", background:"#fff8f0", padding:"1px 6px", borderRadius:6 }}>ΓÜá∩╕Å Low: {item.stock_quantity}</span>}
              </div>
              <div style={{ fontSize:11, color:"#888", marginBottom:2 }}>{item.category} {item.subcategory?`┬╖ ${item.subcategory}`:""}</div>
              <div style={{ fontSize:11, color:"#888" }}>
                <><MarketplaceIcon size={12} color="#64748B"/> {item.profiles?.business_name||item.profiles?.first_name}</> ┬╖ {item.profiles?.city||"ΓÇö"}
                <span style={{ color:"#8b5cf6", marginLeft:6 }}>{item.profiles?.provider_type?.replace(/_/g," ")}</span>
              </div>
              {item.compatible_cars?.length>0&&<div style={{ fontSize:10, color:"#888", marginTop:2 }}>≡ƒÜù {item.compatible_cars.join(", ")}</div>}
            </div>
            <div style={{ textAlign:"right", flexShrink:0 }}>
              <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#e6821e" }}>KES {Number(item.price).toLocaleString()}</div>
              <div style={{ fontSize:11, color:"#888" }}>{item.stock_quantity} {item.unit}s</div>
            </div>
          </div>
        </div>
            </div>
          </div>
      ))}
    </div>
  )
}

import { GOServiceIcon, VehicleIcon, LocationIcon, AnalyticsIcon, TripReportIcon, MechanicIcon, CheckIcon, PhoneCallIcon, StarIcon, RefreshIcon } from "../../lib/cccIcons"
import { useEffect, useState, useRef } from "react"
import { useAuth } from "../../contexts/AuthContext"
import { supabase } from "../../lib/supabase"

export default function AdminLiveMap() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const [drivers, setDrivers] = useState([])
  const [goRequests, setGoRequests] = useState([])
  const [sosAlerts, setSosAlerts] = useState([])
  const [mechanics, setMechanics] = useState([])
  const [tab, setTab] = useState("map")
  const [loading, setLoading] = useState(true)
  const [selected, setSelected] = useState(null)
  const [filter, setFilter] = useState("all")
  const mapRef = useRef(null)
  const mapInstanceRef = useRef(null)
  const markersRef = useRef({})
  const sosMarkersRef = useRef({})

  useEffect(() => {
    load()
    const sub = supabase.channel("admin-live-map")
      .on("postgres_changes", { event:"*", schema:"public", table:"driver_status" }, () => load())
      .subscribe()
    const interval = setInterval(load, 30000)
    return () => { 
      supabase.removeChannel(sub)
      clearInterval(interval)
      // Cleanup map on unmount
      if (mapInstanceRef.current) {
        mapInstanceRef.current = null
      }
      Object.keys(markersRef.current).forEach(id => {
        markersRef.current[id].setMap(null)
      })
      markersRef.current = {}
      Object.keys(sosMarkersRef.current).forEach(id => {
        sosMarkersRef.current[id].setMap(null)
      })
      sosMarkersRef.current = {}
    }
  }, [])

  useEffect(() => {
    if (!loading) initMap()
  }, [drivers, sosAlerts, loading])

  useEffect(() => {
    if (!selected?.current_lat) return
    // Wait for DOM to render the street view div
    setTimeout(() => {
      const svDiv = document.getElementById("admin-street-view")
      if (!svDiv || !window.google?.maps?.StreetViewPanorama) return
      try {
        const sv = new window.google.maps.StreetViewService()
        sv.getPanorama({ location:{ lat:selected.current_lat, lng:selected.current_lng }, radius:100 }, (data, status) => {
          if (status === "OK") {
            const panorama = new window.google.maps.StreetViewPanorama(svDiv, {
              position: { lat: selected.current_lat, lng: selected.current_lng },
              pov: { heading: 34, pitch: 10 },
              zoom: 1,
              addressControl: false,
              showRoadLabels: true,
              motionTracking: false,
            })
            window.google.maps.event.trigger(panorama, "resize")
            setTimeout(() => window.google.maps.event.trigger(panorama, "resize"), 300)
          } else {
            svDiv.innerHTML = "<div style=\"display:flex;align-items:center;justify-content:center;height:100%;color:#888;font-size:12px;flex-direction:column;gap:8px\">Street View not available at this location</div>"
          }
        })
      } catch(e) { svDiv.innerHTML = "<div style=\"display:flex;align-items:center;justify-content:center;height:100%;color:#888;font-size:12px;\">Street View unavailable</div>" }
    }, 300)
  }, [selected?.driver_id])

  if (!user || profile?.role !== "admin") return null

  async function load() {
    const { data } = await supabase.from("driver_status")
      .select("*, driver:profiles!driver_status_driver_id_fkey(first_name,last_name,driver_vehicle_type,driver_category,documents_verified)")
      .not("current_lat","is",null)
    setDrivers(data||[])
    const { data: go } = await supabase.from("go_service_requests").select("*, booking:bookings!go_service_requests_booking_id_fkey(id,service_name,customer_id), provider:profiles!go_service_requests_provider_id_fkey(first_name,last_name,business_name)").in("status",["pending","accepted","en_route"]).order("created_at",{ascending:false})
    setGoRequests(go||[])
    const { data: sos } = await supabase.from("emergency_alerts").select("*, user:profiles!emergency_alerts_user_id_fkey(first_name,last_name)").eq("status","active").order("created_at",{ascending:false})
    let sosWithPhones = sos||[]
    if (sosWithPhones.length > 0) {
      const userIds = sosWithPhones.map(s=>s.user_id).filter(Boolean)
      const { data: sensRows } = await supabase.from("profile_sensitive").select("id,phone").in("id", userIds)
      const phoneMap = Object.fromEntries((sensRows||[]).map(r=>[r.id, r.phone]))
      sosWithPhones = sosWithPhones.map(s=>({ ...s, phone: phoneMap[s.user_id]||null }))
    }
    setSosAlerts(sosWithPhones)
    const { data: mechs } = await supabase.from("mechanics").select("*, profile:profiles!mechanics_user_id_fkey(first_name,last_name)").eq("is_active",true)
    setMechanics(mechs||[])
    setLoading(false)
  }
  async function resolveSOS(id) {
    await supabase.from("emergency_alerts").update({ status:"resolved", resolved_at:new Date().toISOString() }).eq("id", id)
    setSosAlerts(prev => prev.filter(s => s.id !== id))
  }

  function initMap() {
    if (!mapRef.current) return
    function buildMap() {
      if (!window.google?.maps?.Map) return
      const online = drivers.filter(d=>d.current_lat&&d.current_lng)
      if (!online.length) return
      const center = { lat: online[0].current_lat, lng: online[0].current_lng }
      if (!mapInstanceRef.current) {
        mapInstanceRef.current = new window.google.maps.Map(mapRef.current, {
          center, zoom:12, mapTypeControl:false, streetViewControl:false,
          fullscreenControl:true, zoomControl:true, gestureHandling:"greedy"
        })
      }
      online.forEach(d => {
        const icon = d.driver?.driver_category==="concierge"?"\u{1F9D1}\u{200D}\u{2708}\u{FE0F}":
          d.driver?.driver_vehicle_type==="motorcycle"?"\u{1F3CD}\u{FE0F}":
          d.driver?.driver_vehicle_type==="tuktuk"?"\u{1F6FA}":
          d.driver?.driver_vehicle_type==="van"?"\u{1F690}":"\u{1F697}"
        const color = d.is_online&&!isStale(d)?"#1d9e75":"#888888"
        const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 48 48"><circle cx="24" cy="24" r="22" fill="${color}" stroke="white" stroke-width="3"/><text x="24" y="32" font-size="20" text-anchor="middle">${icon}</text></svg>`
        const markerIcon = { url:"data:image/svg+xml;charset=UTF-8,"+encodeURIComponent(svg), scaledSize:new window.google.maps.Size(48,48), anchor:new window.google.maps.Point(24,24) }
        if (markersRef.current[d.driver_id]) {
          markersRef.current[d.driver_id].setPosition({lat:d.current_lat,lng:d.current_lng})
          markersRef.current[d.driver_id].setIcon(markerIcon)
        } else {
          const marker = new window.google.maps.Marker({ position:{lat:d.current_lat,lng:d.current_lng}, map:mapInstanceRef.current, title:`${d.driver?.first_name} ${d.driver?.last_name}`, icon:markerIcon })
          marker.addListener("click", () => setSelected(d))
          markersRef.current[d.driver_id] = marker
        }
      })
      // Plot SOS emergency alert markers
      const activeSosWithLoc = sosAlerts.filter(s=>s.latitude&&s.longitude)
      Object.keys(sosMarkersRef.current).forEach(id => {
        if (!activeSosWithLoc.find(s=>s.id===id)) {
          sosMarkersRef.current[id].setMap(null)
          delete sosMarkersRef.current[id]
        }
      })
      activeSosWithLoc.forEach(s => {
        const sosSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="52" height="52" viewBox="0 0 52 52"><circle cx="26" cy="26" r="24" fill="#e24b4a" stroke="white" stroke-width="3"/><text x="26" y="34" font-size="22" text-anchor="middle">≡ƒåÿ</text></svg>`
        const sosIcon = { url:"data:image/svg+xml;charset=UTF-8,"+encodeURIComponent(sosSvg), scaledSize:new window.google.maps.Size(52,52), anchor:new window.google.maps.Point(26,26) }
        if (sosMarkersRef.current[s.id]) {
          sosMarkersRef.current[s.id].setPosition({ lat:Number(s.latitude), lng:Number(s.longitude) })
        } else {
          const sosMarker = new window.google.maps.Marker({ position:{ lat:Number(s.latitude), lng:Number(s.longitude) }, map:mapInstanceRef.current, title:`SOS: ${s.user_name||"Unknown"}`, icon:sosIcon, zIndex:999 })
          sosMarker.addListener("click", () => {
            mapInstanceRef.current.panTo({ lat:Number(s.latitude), lng:Number(s.longitude) })
            mapInstanceRef.current.setZoom(16)
          })
          sosMarkersRef.current[s.id] = sosMarker
        }
      })
    }
    if (window.google?.maps?.Map) {
      buildMap()
    } else {
      // Use existing SDK script or load new one
      const existingScript = document.getElementById("google-maps-sdk") || document.getElementById("google-maps-admin")
      if (existingScript) {
        // Script already loading - wait for it
        existingScript.addEventListener("load", buildMap)
      } else {
        const s = document.createElement("script")
        s.id = "google-maps-admin"
        s.src = `https://maps.googleapis.com/maps/api/js?key=${import.meta.env.VITE_GOOGLE_MAPS_KEY}&libraries=marker,places&loading=async`
        s.onload = () => { setTimeout(buildMap, 100) }
        document.head.appendChild(s)
      }
    }
  }

  const filtered = drivers.filter(d => {
    if (filter==="online") return d.is_online
    if (filter==="concierge") return d.driver?.driver_category==="concierge"
    if (filter==="marketplace") return d.driver?.driver_category==="marketplace"
    return true
  })

  function isStale(d) {
    if (!d.updated_at) return true
    return (Date.now() - new Date(d.updated_at).getTime()) > 10*60*1000
  }
  function timeAgo(dateStr) {
    if (!dateStr) return "never"
    const diff = Date.now() - new Date(dateStr).getTime()
    const mins = Math.floor(diff/60000)
    if (mins < 1) return "just now"
    if (mins < 60) return mins+"m ago"
    const hrs = Math.floor(mins/60)
    if (hrs < 24) return hrs+"h ago"
    return Math.floor(hrs/24)+"d ago"
  }
  const onlineCount = drivers.filter(d=>d.is_online && !isStale(d)).length
  const conciergeCount = drivers.filter(d=>d.driver?.driver_category==="concierge").length
  const marketplaceCount = drivers.filter(d=>d.driver?.driver_category==="marketplace").length
  const activeGoRequests = goRequests.filter(g=>g.status==="pending"||g.status==="accepted").length
  const activeSOS = sosAlerts.length

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:"#000", marginBottom:"1rem", display:"flex", alignItems:"center", gap:8 }}><TripReportIcon size={20} color="#e6821e"/> Live Driver Map</div>
      <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:6, marginBottom:"1rem" }}>
        {[
          { label:"Total drivers", value:drivers.length, color:"#000" },
          { label:"Online now", value:onlineCount, color:"#1d9e75" },
          { label:"Concierge", value:conciergeCount, color:"#8b5cf6" },
          { label:"Marketplace", value:marketplaceCount, color:"#e6821e" },
          { label:"GO Requests", value:activeGoRequests, color:activeGoRequests>0?"#e24b4a":"#888" },
          { label:"SOS Active", value:activeSOS, color:activeSOS>0?"#e24b4a":"#888" },
          { label:"Mechanics", value:mechanics.length, color:"#378add" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.75rem", border:"1px solid #eee", textAlign:"center" }}>
            <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>
      {/* Tab buttons */}
      <div style={{ display:"flex", gap:4, marginBottom:"1rem", overflowX:"auto", paddingBottom:4, WebkitOverflowScrolling:"touch" }}>
        {[
          {k:"map",l:"Live Map"},
          {k:"go",l:"GO ("+goRequests.length+")"},
          {k:"sos",l:"SOS ("+sosAlerts.length+")"},
          {k:"mechanics",l:"Mechanics ("+mechanics.length+")"},
        ].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)} style={{ padding:"7px 14px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#e6821e":"#f0f0f0", color:tab===t.k?"#fff":"#555", fontWeight:tab===t.k?700:400, whiteSpace:"nowrap" }}>{t.l}</button>
        ))}
