import { TrophyIcon } from "../../lib/cccIcons"
import useIsMobile from "../../lib/useIsMobile"
import { useAuth } from "../../contexts/AuthContext"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import toast from "react-hot-toast"

export default function AdminLoyalty() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const isMobile = useIsMobile()
  const [loyalty, setLoyalty] = useState([])
  const [leaderboard, setLeaderboard] = useState([])
  const [loading, setLoading] = useState(true)
  const [adjusting, setAdjusting] = useState(null)
  const [adjustForm, setAdjustForm] = useState({ points:"", reason:"" })

  useEffect(() => { load() }, [])

  async function load() {
    const { data: lp } = await supabase.from("loyalty_points")
      .select("*, profile_public(first_name,last_name,business_name,role)")
      .order("points",{ascending:false})
    setLoyalty(lp||[])
    const { data: lb } = await supabase.rpc("get_referral_leaderboard", { limit_count: 10 })
    setLeaderboard(lb||[])
    setLoading(false)
  }

  async function adjustPoints(e) {
    e.preventDefault()
    const pts = parseInt(adjustForm.points)
    if (isNaN(pts)) return toast.error("Enter a valid number")
    const current = loyalty.find(l=>l.user_id===adjusting)
    const newPoints = Math.max(0, (current?.points||0) + pts)
    const newLifetime = pts > 0 ? (current?.lifetime_points||0) + pts : current?.lifetime_points||0
    const { error } = await supabase.from("loyalty_points").upsert({
      user_id: adjusting,
      points: newPoints,
      lifetime_points: newLifetime
    })
    if (error) return toast.error(error.message)
    await supabase.from("notifications").insert({
      user_id: adjusting,
      title: pts>0?"Loyalty points added":"Loyalty points deducted",
      message: `${Math.abs(pts)} points ${pts>0?"added to":"deducted from"} your account. ${adjustForm.reason?`Reason: ${adjustForm.reason}`:""}`,
      type: pts>0?"success":"info"
    })
    toast.success(`Points ${pts>0?"added":"deducted"} successfully`)
    setAdjusting(null)
    setAdjustForm({ points:"", reason:"" })
    load()
  }

  function getTier(points) {
    if (points>=10000) return { name:"Platinum", color:"#d4537e" }
    if (points>=5000) return { name:"Gold", color:"#e6821e" }
    if (points>=1000) return { name:"Silver", color:"#aaa" }
    return { name:"Bronze", color:"#cd7f32" }
  }

  const inp = { width:"100%", background:"#f8f8f8", border:"1px solid #f0f0f0", borderRadius:8, padding:"10px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif", marginBottom:10 }

  return (
    <div>
      <div style={{ display:"grid", gridTemplateColumns:isMobile?"repeat(2,1fr)":"repeat(3,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Total members", value:loyalty.length },
          { label:"Total points issued", value:loyalty.reduce((s,l)=>s+(l.lifetime_points||0),0).toLocaleString(), color:"#e6821e" },
          { label:"Platinum members", value:loyalty.filter(l=>l.points>=10000).length, color:"#d4537e" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"1rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontSize:11, color:"#888", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:6 }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:22, fontWeight:800, color:s.color||"#000000" }}>{s.value}</div>
          </div>
        ))}
      </div>

      <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:10, color:"#000000" }}>
        Loyalty leaderboard
      </div>

      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
      {!loading&&loyalty.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No loyalty members yet</div>}

      {loyalty.map((l,i)=>{
        const tier = getTier(l.points||0)
        const profile = l.profile_public
        const name = profile?.business_name||`${profile?.first_name||""} ${profile?.last_name||""}`.trim()||"User"
        return (
          <div key={l.user_id} style={{ background:"#f8f8f8", border:`1px solid ${adjusting===l.user_id?"#e6821e40":"#eeeeee"}`, borderRadius:10, padding:"1rem", marginBottom:8 }}>
            <div style={{ display:"flex", alignItems:"center", gap:12 }}>
              <div style={{ width:32, height:32, borderRadius:"50%", background:`${tier.color}20`, display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontSize:14, fontWeight:800, color:tier.color, flexShrink:0 }}>
                {i+1}
              </div>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:2 }}>
                  <div style={{ fontSize:13, fontWeight:500, color:"#000000", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{name}</div>
                  <span style={{ fontSize:10, padding:"1px 6px", borderRadius:10, background:`${tier.color}20`, color:tier.color, flexShrink:0 }}>{tier.name}</span>
                </div>
                <div style={{ fontSize:11, color:"#888" }}>
                  {(l.points||0).toLocaleString()} pts ┬╖ lifetime {(l.lifetime_points||0).toLocaleString()}
                </div>
              </div>
              <button onClick={()=>setAdjusting(adjusting===l.user_id?null:l.user_id)}
                style={{ background:"none", border:"1px solid #dddddd", borderRadius:7, color:"#888", fontSize:11, padding:"5px 10px", cursor:"pointer", flexShrink:0 }}>
                {adjusting===l.user_id?"Close":"Adjust"}
              </button>
            </div>

            {adjusting===l.user_id&&(
              <div style={{ marginTop:12, paddingTop:12, borderTop:"1px solid #eeeeee" }}>
                <div style={{ fontSize:12, color:"#888", marginBottom:10 }}>
                  Current balance: <span style={{ color:"#e6821e", fontWeight:600 }}>{(l.points||0).toLocaleString()} points</span>
                </div>
                <form onSubmit={adjustPoints}>
                  <label style={{ fontSize:11, color:"#888", textTransform:"uppercase", letterSpacing:"0.05em", display:"block", marginBottom:4 }}>Points to add (use negative to deduct)</label>
                  <input style={inp} type="number" placeholder="e.g. 500 or -200" value={adjustForm.points} onChange={e=>setAdjustForm(f=>({...f,points:e.target.value}))} required/>
                  <label style={{ fontSize:11, color:"#888", textTransform:"uppercase", letterSpacing:"0.05em", display:"block", marginBottom:4 }}>Reason</label>
                  <input style={inp} placeholder="e.g. Promotional bonus, correction" value={adjustForm.reason} onChange={e=>setAdjustForm(f=>({...f,reason:e.target.value}))}/>
                  <div style={{ display:"flex", gap:8 }}>
                    <button type="submit" style={{ background:"#e6821e", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"9px 20px", cursor:"pointer" }}>Apply adjustment</button>
                    <button type="button" onClick={()=>setAdjusting(null)} style={{ background:"none", border:"1px solid #dddddd", borderRadius:8, color:"#888", fontSize:13, padding:"9px 20px", cursor:"pointer" }}>Cancel</button>
                  </div>
                </form>
              </div>
            )}
          </div>
        )
      })}
    <div style={{ marginTop:"1.5rem" }}>
      <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:10, color:"#000000" }}>≡ƒÅå Referral Leaderboard (Top 10)</div>
      {leaderboard.length===0&&<div style={{ color:"#888", fontSize:13 }}>No completed referrals yet</div>}
      {leaderboard.map((row,i)=>(
        <div key={row.user_id} style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:10, padding:"0.75rem 1rem", marginBottom:6, display:"flex", alignItems:"center", gap:10 }}>
          <div style={{ width:28, textAlign:"center", fontFamily:"Syne", fontSize:14, fontWeight:800, color:i===0?"#e6821e":i===1?"#888":i===2?"#a0703a":"#bbb" }}>
            {i===0?<TrophyIcon size={16} color="#e6821e"/>:i===1?<TrophyIcon size={16} color="#aaa"/>:i===2?<TrophyIcon size={16} color="#cd7f32"/>:i+1}
          </div>
          <div style={{ flex:1, fontSize:13, color:"#000000" }}>{row.first_name} {row.last_name}</div>
          <div style={{ fontSize:11, color:"#777" }}>{row.total_referrals} referral{row.total_referrals!==1?"s":""}</div>
          <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#e6821e" }}>{row.total_points.toLocaleString()} pts</div>
        </div>
      ))}
    </div>
    </div>
  )
}

import { LocationIcon, EyeIcon, VehicleIcon, WarningIcon } from "../../lib/cccIcons"
import { jsPDF } from "jspdf"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

export default function AdminMarketplace() {
  const isMobile = useIsMobile()
  const { user } = useAuth()
  const [listings, setListings] = useState([])
  const [selectedComments, setSelectedComments] = useState([])
  const [showComments, setShowComments] = useState(null)
  const [offers, setOffers] = useState([])
  const [transactions, setTransactions] = useState([])
  const [disputes, setDisputes] = useState([])
  const [mechanics, setMechanics] = useState([])
  const [allCCCMechanics, setAllCCCMechanics] = useState([])
  const [inspections, setInspections] = useState([])
  const [loading, setLoading] = useState(true)
  const [tab, setTab] = useState("pending")
  const [selected, setSelected] = useState(null)
  const [adminNotes, setAdminNotes] = useState("")
  const [processing, setProcessing] = useState(false)
  const [search, setSearch] = useState("")
  const [showAddMech, setShowAddMech] = useState(false)
  const [mechForm, setMechForm] = useState({ first_name:"", last_name:"", phone:"", specialization:"" })
  const [addingMech, setAddingMech] = useState(false)
  const [pinPanel, setPinPanel] = useState(null)
  const [pin, setPin] = useState("")
  const [settingPin, setSettingPin] = useState(false)
  const [editingMech, setEditingMech] = useState(null)
  const [editForm, setEditForm] = useState({ first_name:"", last_name:"", phone:"", specialization:"" })
  const [savingEdit, setSavingEdit] = useState(false)

  useEffect(() => {
    load()
    const sub = supabase.channel("admin-marketplace-live")
      .on("postgres_changes", { event:"*", schema:"public", table:"marketplace_listings" }, () => load())
      .on("postgres_changes", { event:"*", schema:"public", table:"marketplace_offers" }, () => loadOffers())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [])

  async function load() {
    await Promise.all([loadListings(), loadOffers(), loadTransactions(), loadDisputes(), loadInspections(), loadAllCCCMechanics()])
    supabase.from("mechanics").select("id,first_name,last_name,specialization").eq("is_active",true).is("provider_id", null)
      .then(({ data }) => setMechanics(data||[]))
    setLoading(false)
  }

  async function loadListings() {
    const { data } = await supabase.from("marketplace_listings")
      .select("*, profiles(first_name,last_name,role,business_name)")
      .order("created_at", { ascending:false })
    setListings(data||[])
  }

  async function loadOffers() {
    const { data } = await supabase.from("marketplace_offers")
      .select("*, marketplace_listings(title,price), buyer:profiles!marketplace_offers_buyer_id_fkey(first_name,last_name), seller:profiles!marketplace_offers_seller_id_fkey(first_name,last_name)")
      .order("created_at", { ascending:false })
    setOffers(data||[])
  }

  async function loadTransactions() {
    const { data } = await supabase.from("marketplace_transactions")
      .select("*, marketplace_listings(title), buyer:profiles!marketplace_transactions_buyer_id_fkey(first_name,last_name), seller:profiles!marketplace_transactions_seller_id_fkey(first_name,last_name)")
      .order("created_at", { ascending:false })
    setTransactions(data||[])
  }

  async function loadInspections() {
    const { data } = await supabase.from("inspection_requests")
      .select("*, marketplace_listings(title), profiles(first_name,last_name)")
      .order("created_at",{ascending:false})
    setInspections(data||[])
  }

  async function addCCCMechanic(e) {
    e.preventDefault()
    if (!mechForm.first_name) return toast.error("First name required")
    setAddingMech(true)
    try {
      // CCC's own in-house inspection mechanic - no provider_id at all, since these
      // aren't tied to any provider's own garage/team.
