                            <div key={cm.id} style={{ display:"flex", gap:8, alignItems:"flex-start", marginBottom:8, background:"#ffffff", borderRadius:8, padding:"8px 10px" }}>
                              <div style={{ flex:1 }}>
                                <div style={{ fontSize:11, fontWeight:700, color:"#000" }}>{cm.profiles?.first_name} {cm.profiles?.last_name}</div>
                                <div style={{ fontSize:11, color:"#444", marginTop:2 }}>{cm.comment}</div>
                                <div style={{ fontSize:9, color:"#888", marginTop:2 }}>{new Date(cm.created_at).toLocaleString()}</div>
                              </div>
                              <button onClick={()=>deleteComment(cm.id)}
                                style={{ background:"#fff5f5", border:"1px solid #e24b4a30", borderRadius:6, color:"#e24b4a", fontSize:10, fontWeight:700, padding:"3px 8px", cursor:"pointer", flexShrink:0 }}>
                                ≡ƒùæ∩╕Å Remove
                              </button>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>

                    <div style={{ marginBottom:10 }}>
                      <label style={{ fontSize:11, color:"#888", display:"block", marginBottom:4 }}>Admin notes (required for rejection)</label>
                      <textarea value={adminNotes} onChange={e=>setAdminNotes(e.target.value)}
                        placeholder="Add notes..."
                        style={{ width:"100%", background:"#ffffff", border:"1px solid #f0f0f0", borderRadius:8, padding:"9px 12px", color:"#000000", fontSize:12, outline:"none", resize:"vertical", minHeight:60, fontFamily:"'DM Sans',sans-serif" }}/>
                    </div>

                    {/* Photo gallery */}
                    {l.marketplace_photos?.length>0&&(
                      <div style={{ marginBottom:12 }}>
                        <div style={{ fontSize:12, fontWeight:700, color:"#555", marginBottom:8 }}>≡ƒô╕ Photos ({l.marketplace_photos.length})</div>
                        <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                          {l.marketplace_photos.sort((a,b)=>a.display_order-b.display_order).map((p,i)=>(
                            <a key={i} href={p.photo_url} target="_blank" rel="noopener noreferrer">
                              <img src={p.photo_url} alt="" style={{ width:70, height:70, objectFit:"cover", borderRadius:6, border:"1px solid #eeeeee" }}/>
                            </a>
                          ))}
                        </div>
                      </div>
                    )}
                    {l.video_url&&(
                      <div style={{ marginTop:12, background:"#f8f8f8", borderRadius:10, padding:"1rem" }}>
                        <div style={{ fontSize:12, fontWeight:700, color:"#555", marginBottom:8 }}>
                          ≡ƒÄÑ Video Review
                          <span style={{ marginLeft:8, fontSize:10, padding:"2px 8px", borderRadius:10,
                            background:l.video_status==="approved"?"#f0fdf4":l.video_status==="rejected"?"#fff5f5":"#fff8f0",
                            color:l.video_status==="approved"?"#1d9e75":l.video_status==="rejected"?"#e24b4a":"#e6821e" }}>
                            {l.video_status==="approved"?"Γ£ô Approved":l.video_status==="rejected"?"Γ£ù Rejected":"ΓÅ│ Pending Review"}
                          </span>
                        </div>
                        <video src={l.video_url} controls style={{ width:"100%", borderRadius:8, maxHeight:200, marginBottom:8 }}/>
                        <div style={{ display:"flex", gap:8 }}>
                          {l.video_status!=="approved"&&(
                            <button onClick={()=>approveVideo(l.id)}
                              style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, fontWeight:700, padding:"6px 14px", cursor:"pointer" }}>
                              Γ£ô Approve Video
                            </button>
                          )}
                          {l.video_status!=="rejected"&&(
                            <button onClick={()=>{ const r=window.prompt("Reason for rejection?","Does not meet content guidelines"); if(r!==null) rejectVideo(l.id,r) }}
                              style={{ background:"#fff5f5", border:"1px solid #e24b4a40", borderRadius:7, color:"#e24b4a", fontSize:11, fontWeight:700, padding:"6px 14px", cursor:"pointer" }}>
                              Γ£ù Reject Video
                            </button>
                          )}
                        </div>
                      </div>
                    )}

                    <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>

                      {/* Vehicle inspection workflow */}
                      {l.listing_type==="vehicle"&&!l.is_inspected&&l.inspection_status!=="requested"&&(
                        <button onClick={()=>requestInspection(l)} disabled={processing}
                          style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:8, color:"#e6821e", fontSize:12, fontWeight:700, padding:"9px 18px", cursor:processing?"not-allowed":"pointer" }}>
                          ≡ƒöì Request inspection
                        </button>
                      )}

                      {l.listing_type==="vehicle"&&l.inspection_status==="requested"&&!l.is_inspected&&(
                        <div style={{ width:"100%", background:"#eff6ff", border:"1px solid #378add40", borderRadius:8, padding:"0.75rem", marginBottom:8 }}>
                          <div style={{ fontSize:11, color:"#378add", fontWeight:600, marginBottom:8 }}>≡ƒöì Inspection in progress</div>
                          <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                            <button onClick={()=>passInspection(l)} disabled={processing}
                              style={{ background:"#1d9e75", border:"none", borderRadius:7, color:"#fff", fontSize:11, fontWeight:700, padding:"7px 14px", cursor:"pointer" }}>
                              Γ£ô Mark as passed
                            </button>
                            <button onClick={()=>rejectListing(l.id)} disabled={processing}
                              style={{ background:"none", border:"1px solid #e24b4a40", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"7px 12px", cursor:"pointer" }}>
                              Γ£ù Mark as failed
                            </button>
                          </div>
                        </div>
                      )}

                      {l.is_inspected&&(
                        <div style={{ fontSize:11, color:"#1d9e75", padding:"7px 12px", background:"#f0fdf4", borderRadius:8, border:"1px solid #1d9e7540" }}>
                          Γ£ô CCC Inspected
                        </div>
                      )}

                      <button onClick={()=>approveListing(l.id)} disabled={processing||(l.listing_type==="vehicle"&&!l.is_inspected)}
                        style={{ background:processing||(l.listing_type==="vehicle"&&!l.is_inspected)?"#e0e0e0":"#1d9e75", border:"none", borderRadius:8, color:processing||(l.listing_type==="vehicle"&&!l.is_inspected)?"#555":"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"9px 18px", cursor:processing||(l.listing_type==="vehicle"&&!l.is_inspected)?"not-allowed":"pointer" }}>
                        {l.listing_type==="vehicle"&&!l.is_inspected?"≡ƒöÆ Inspect first":"Γ£ô Approve & publish"}
                      </button>

                      <button onClick={()=>rejectListing(l.id)} disabled={processing}
                        style={{ background:"none", border:"1px solid #e24b4a40", borderRadius:8, color:"#e24b4a", fontSize:12, padding:"9px 14px", cursor:processing?"not-allowed":"pointer" }}>
                        Reject
                      </button>
                      <button onClick={()=>setSelected(null)}
                        style={{ background:"none", border:"1px solid #dddddd", borderRadius:8, color:"#888", fontSize:12, padding:"9px 14px", cursor:"pointer" }}>
                        Cancel
                      </button>
                    </div>
                  </div>
                )}
              </div>
            )
          })}
        </div>
      )}

      {/* OFFERS TAB */}
      {tab==="offers"&&(
        <div>
          {offers.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No offers yet</div>}
          {offers.map(o=>(
            <div key={o.id} style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:600, color:"#000000", marginBottom:4 }}>{o.marketplace_listings?.title}</div>
                  <div style={{ fontSize:11, color:"#888", marginBottom:2 }}>
                    Asking: KES {Number(o.marketplace_listings?.price||0).toLocaleString()}
                  </div>
                  <div style={{ fontSize:11, color:"#888", marginBottom:2 }}>
                    Buyer: {o.buyer?.first_name} {o.buyer?.last_name}
                  </div>
                  <div style={{ fontSize:11, color:"#888", marginBottom:4 }}>
                    Seller: {o.seller?.first_name} {o.seller?.last_name}
                  </div>
                  {o.message&&<div style={{ fontSize:11, color:"#888", fontStyle:"italic" }}>&quot;{o.message}&quot;</div>}
                  <div style={{ fontSize:10, color:"#888", marginTop:4 }}>{new Date(o.created_at).toLocaleString()}</div>
                </div>
                <div style={{ textAlign:"right" }}>
                  <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#e6821e" }}>KES {Number(o.offered_price).toLocaleString()}</div>
                  {o.counter_price&&<div style={{ fontSize:11, color:"#8b5cf6", marginTop:2 }}>Counter: KES {Number(o.counter_price).toLocaleString()}</div>}
                  <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:"#f5f5f5", color:"#888", marginTop:4, display:"inline-block" }}>{o.status}</span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* TRANSACTIONS TAB */}
      {tab==="transactions"&&(
        <div>
          {transactions.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No transactions yet</div>}
          {transactions.map(t=>(
            <div key={t.id} style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:600, color:"#000000", marginBottom:4 }}>{t.marketplace_listings?.title}</div>
                  <div style={{ fontSize:11, color:"#888", marginBottom:2 }}>Buyer: {t.buyer?.first_name} {t.buyer?.last_name}</div>
                  <div style={{ fontSize:11, color:"#888", marginBottom:2 }}>Seller: {t.seller?.first_name} {t.seller?.last_name}</div>
                  <div style={{ fontSize:11, color:t.buyer_confirmed?"#1d9e75":"#e6821e" }}>{t.buyer_confirmed?"Γ£ô Buyer confirmed":"ΓÅ│ Awaiting buyer confirmation"}</div>
                  <div style={{ fontSize:10, color:"#888", marginTop:4 }}>{new Date(t.created_at).toLocaleString()}</div>
                </div>
                <div style={{ textAlign:"right" }}>
                  <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#e6821e" }}>KES {Number(t.sale_price).toLocaleString()}</div>
                  <div style={{ fontSize:11, color:"#1d9e75", marginTop:2 }}>Platform: KES {Number(t.platform_commission).toLocaleString()}</div>
                  <div style={{ fontSize:11, color:"#888" }}>Seller: KES {Number(t.seller_earnings).toLocaleString()}</div>
                  <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:"#f5f5f5", color:"#888", marginTop:4, display:"inline-block" }}>{t.payment_status}</span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {tab==="inspections"&&(
        <div>
          <div style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:10, padding:"0.75rem", marginBottom:16 }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom: showAddMech?10:0 }}>
              <div style={{ fontSize:12, fontWeight:700, color:"#000" }}>CCC Inspection Mechanics ({mechanics.length})</div>
              <button onClick={()=>setShowAddMech(!showAddMech)} style={{ background:"#e6821e", border:"none", borderRadius:7, color:"#fff", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>{showAddMech?"Cancel":"+ Add mechanic"}</button>
            </div>
            {showAddMech&&(
              <form onSubmit={addCCCMechanic} style={{ display:"grid", gridTemplateColumns:"repeat(2,1fr)", gap:8, marginTop:8 }}>
                <input placeholder="First name" value={mechForm.first_name} onChange={e=>setMechForm(f=>({...f,first_name:e.target.value}))} required style={{ fontSize:12, border:"1px solid #ddd", borderRadius:6, padding:"7px 10px", outline:"none" }}/>
                <input placeholder="Last name" value={mechForm.last_name} onChange={e=>setMechForm(f=>({...f,last_name:e.target.value}))} style={{ fontSize:12, border:"1px solid #ddd", borderRadius:6, padding:"7px 10px", outline:"none" }}/>
                <input placeholder="Phone" value={mechForm.phone} onChange={e=>setMechForm(f=>({...f,phone:e.target.value}))} style={{ fontSize:12, border:"1px solid #ddd", borderRadius:6, padding:"7px 10px", outline:"none" }}/>
                <input placeholder="Specialization (optional)" value={mechForm.specialization} onChange={e=>setMechForm(f=>({...f,specialization:e.target.value}))} style={{ fontSize:12, border:"1px solid #ddd", borderRadius:6, padding:"7px 10px", outline:"none" }}/>
                <button type="submit" disabled={addingMech} style={{ gridColumn:"span 2", background:"#1d9e75", border:"none", borderRadius:7, color:"#fff", fontSize:12, fontWeight:700, padding:"8px", cursor:addingMech?"not-allowed":"pointer" }}>{addingMech?"Creating...":"Create mechanic account"}</button>
              </form>
            )}
            {allCCCMechanics.length>0&&(
              <div style={{ marginTop:10, display:"grid", gap:6 }}>
                {allCCCMechanics.map(m=>(
                  <div key={m.id} style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:8, padding:"0.5rem 0.75rem", opacity:m.is_active?1:0.55 }}>
                    <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", flexWrap:"wrap", gap:4 }}>
                      <div>
                        <div style={{ fontSize:12, color:"#000" }}>{m.first_name} {m.last_name}{m.specialization?" - "+m.specialization:""}{!m.is_active&&<span style={{ marginLeft:6, fontSize:10, color:"#e24b4a" }}>(inactive)</span>}</div>
                        <div style={{ fontSize:10, color:"#888" }}>{m.phone||"No phone on file"}</div>
                      </div>
                      <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                        <button onClick={()=>startEditMech(m)} style={{ background:"none", border:"1px solid #ddd", borderRadius:6, color:"#555", fontSize:10, padding:"4px 10px", cursor:"pointer" }}>
                          Edit
                        </button>
                        <button onClick={()=>toggleMechAvailable(m)} style={{ background:m.is_available?"#f0fdf4":"#fff8f0", border:"1px solid "+(m.is_available?"#1d9e7540":"#e6821e40"), borderRadius:6, color:m.is_available?"#1d9e75":"#e6821e", fontSize:10, padding:"4px 10px", cursor:"pointer" }}>
                          {m.is_available?"Available":"Unavailable"}
                        </button>
                        <button onClick={()=>toggleMechActive(m)} style={{ background:"none", border:"1px solid "+(m.is_active?"#e24b4a40":"#1d9e7540"), borderRadius:6, color:m.is_active?"#e24b4a":"#1d9e75", fontSize:10, padding:"4px 10px", cursor:"pointer" }}>
                          {m.is_active?"Deactivate":"Activate"}
                        </button>
                        <button onClick={()=>{ setPinPanel(pinPanel===m.id?null:m.id); setPin("") }} style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:6, color:"#378add", fontSize:10, padding:"4px 10px", cursor:"pointer" }}>
                          ≡ƒöæ {m.mechanic_code?"Reset PIN":"Set PIN"}
                        </button>
                      </div>
                    </div>
                    {editingMech===m.id&&(
                      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6, marginTop:8 }}>
                        <input placeholder="First name" value={editForm.first_name} onChange={e=>setEditForm(f=>({...f,first_name:e.target.value}))} style={{ fontSize:12, border:"1px solid #ddd", borderRadius:6, padding:"6px 9px", outline:"none" }}/>
                        <input placeholder="Last name" value={editForm.last_name} onChange={e=>setEditForm(f=>({...f,last_name:e.target.value}))} style={{ fontSize:12, border:"1px solid #ddd", borderRadius:6, padding:"6px 9px", outline:"none" }}/>
                        <input placeholder="Phone" value={editForm.phone} onChange={e=>setEditForm(f=>({...f,phone:e.target.value}))} style={{ fontSize:12, border:"1px solid #ddd", borderRadius:6, padding:"6px 9px", outline:"none" }}/>
                        <input placeholder="Specialization" value={editForm.specialization} onChange={e=>setEditForm(f=>({...f,specialization:e.target.value}))} style={{ fontSize:12, border:"1px solid #ddd", borderRadius:6, padding:"6px 9px", outline:"none" }}/>
                        <button onClick={()=>saveEditMech(m.id)} disabled={savingEdit} style={{ gridColumn:"span 2", background:"#1d9e75", border:"none", borderRadius:6, color:"#fff", fontSize:11, fontWeight:700, padding:"7px", cursor:"pointer" }}>{savingEdit?"Saving...":"Save changes"}</button>
                      </div>
                    )}
                    {pinPanel===m.id&&(
                      <div style={{ display:"flex", gap:6, marginTop:8 }}>
                        <input type="password" value={pin} onChange={e=>setPin(e.target.value.replace(/\D/g,"").slice(0,6))} placeholder="e.g. 1234" maxLength={6} style={{ flex:1, background:"#f8f8f8", border:"1px solid #ddd", borderRadius:6, padding:"7px 10px", fontSize:13, letterSpacing:3, outline:"none" }}/>
                        <button onClick={()=>setMechanicPin(m.id)} disabled={settingPin||pin.length<4} style={{ background:pin.length>=4?"#378add":"#ccc", border:"none", borderRadius:6, color:"#fff", fontSize:11, fontWeight:700, padding:"7px 14px", cursor:"pointer", whiteSpace:"nowrap" }}>{settingPin?"Saving...":"Save PIN"}</button>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
          {inspections.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No inspection requests</div>}
          {inspections.map(insp=>(
            <div key={insp.id} style={{ background:"#f8f8f8", border:`1px solid ${insp.status==="pending"?"#e6821e20":"#eeeeee"}`, borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:600, color:"#000000", marginBottom:4 }}>{insp.marketplace_listings?.title}</div>
                  <div style={{ fontSize:11, color:"#888", marginBottom:2 }}>Seller: {insp.profiles?.first_name} {insp.profiles?.last_name}</div>
                  <div style={{ fontSize:11, color:"#888", marginBottom:2 }}>Preferred date: {insp.scheduled_date}</div>
                  <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:"#fff8f0", color:"#e6821e" }}>{insp.status}</span>
                </div>
                <div style={{ textAlign:"right" }}>
                  <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#1d9e75" }}>KES {Number(insp.amount).toLocaleString()}</div>
                  <div style={{ fontSize:10, color:insp.payment_status==="paid"?"#1d9e75":"#e24b4a", marginTop:2 }}>{insp.payment_status}</div>
                  {insp.status==="pending"&&(
                    <div style={{ marginTop:6 }}>
                    <select id={`mech-${insp.id}`} style={{ fontSize:11, border:"1px solid #ddd", borderRadius:6, padding:"4px 8px", marginRight:6, outline:"none" }}>
                      <option value="">Select mechanic...</option>
                      {mechanics.map(m=>(<option key={m.id} value={m.id}>{m.first_name} {m.last_name}{m.specialization?" ΓÇö "+m.specialization:""}</option>))}
                    </select>
                    <button onClick={async()=>{
                      const mechId = document.getElementById(`mech-${insp.id}`)?.value
                      if (!mechId) return toast.error("Please select a mechanic")
                      const mech = mechanics.find(m=>m.id===mechId)
                      await supabase.from("inspection_requests").update({ status:"assigned", mechanic_id:mechId }).eq("id",insp.id)
                      await supabase.from("notifications").insert({ user_id:insp.seller_id, title:"Inspection assigned ≡ƒöì", message:`${mech?.first_name} ${mech?.last_name} has been assigned to inspect "${insp.marketplace_listings?.title}". Scheduled: ${insp.scheduled_date}`, type:"info" })
                      loadInspections()
                      toast.success("Mechanic assigned!")
                    }}
                      style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:10, padding:"4px 10px", cursor:"pointer" }}>
                      Assign
                    </button>
                  </div>
                  )}
                  {(insp.status==="assigned"||insp.status==="pending")&&(
                    <button onClick={()=>downloadJobSheet(insp)}
                      style={{ background:"#f5f3ff", border:"1px solid #8b5cf640", borderRadius:7, color:"#8b5cf6", fontSize:10, padding:"4px 10px", cursor:"pointer", marginTop:6, display:"block" }}>
                      ≡ƒôä Download job sheet
                    </button>
                  )}

                  {insp.status==="assigned"&&(
                    <button onClick={async()=>{
                      const result = prompt("Inspection result (passed/failed/conditional):")
                      const notes = prompt("Inspection notes:")
                      if (!result) return
                      await supabase.from("inspection_requests").update({ status:"completed", inspection_result:result, inspection_notes:notes, completed_at:new Date().toISOString() }).eq("id",insp.id)
                      if (result==="passed") await supabase.from("marketplace_listings").update({ is_inspected:true }).eq("id",insp.listing_id)
                      await supabase.from("notifications").insert({ user_id:insp.seller_id, title:"Inspection complete Γ£à", message:`Your vehicle inspection is complete. Result: ${result?.toUpperCase()}. ${notes}`, type:result==="passed"?"success":"warning" })
                      loadInspections()
                    }}
                      style={{ background:"#f5f3ff", border:"1px solid #8b5cf640", borderRadius:7, color:"#8b5cf6", fontSize:10, padding:"4px 10px", cursor:"pointer", marginTop:6 }}>
                      Complete inspection
                    </button>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* DISPUTES TAB */}
      {tab==="disputes"&&(
        <div>
          {disputes.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No disputes</div>}
          {disputes.map(d=>(
            <div key={d.id} style={{ background:"#f8f8f8", border:`1px solid ${d.status==="open"?"#e24b4a20":"#eeeeee"}`, borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div>
                  <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4 }}>
                    <div style={{ fontSize:13, fontWeight:600, color:"#000000" }}>{d.reason}</div>
                    <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:d.status==="open"?"#fff5f5":"#f8f8f8", color:d.status==="open"?"#e24b4a":"#555" }}>{d.status}</span>
                  </div>
                  <div style={{ fontSize:11, color:"#888", marginBottom:2 }}>Raised by: {d.profiles?.first_name} {d.profiles?.last_name}</div>
                  {d.description&&<div style={{ fontSize:11, color:"#888", fontStyle:"italic" }}>&quot;{d.description}&quot;</div>}
                  {d.status==="open"&&(
                    <div style={{ display:"flex", gap:6, marginTop:10 }}>
                      <button onClick={()=>resolveDispute(d,"buyer")}
                        style={{ background:"#fff5f5", border:"1px solid #e24b4a40", borderRadius:7, color:"#e24b4a", fontSize:11, fontWeight:600, padding:"6px 12px", cursor:"pointer" }}>
                        ≡ƒÆ░ Refund buyer
                      </button>
                      <button onClick={()=>resolveDispute(d,"seller")}
                        style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, fontWeight:600, padding:"6px 12px", cursor:"pointer" }}>
                        Γ£ô Release to seller
                      </button>
                    </div>
                  )}
                  <div style={{ fontSize:10, color:"#888", marginTop:4 }}>{new Date(d.created_at).toLocaleString()}</div>
                </div>
                <div style={{ textAlign:"right" }}>
                  <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#e6821e" }}>KES {Number(d.marketplace_transactions?.sale_price||0).toLocaleString()}</div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { MarketplaceIcon, HomeIcon, GOServiceIcon, MechanicIcon, DiscoverIcon, ServicesIcon, LocationIcon, StarIcon } from "../../lib/cccIcons"
import { useEffect, useState, useRef } from "react"
import { useAuth } from "../../contexts/AuthContext"
import { supabase } from "../../lib/supabase"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const CATEGORIES = {
  shop_standard: { label:"Shop Standard", icon:MarketplaceIcon, color:"#378add", bg:"#eff6ff" },
  shop_premium: { label:"Shop Premium", icon:HomeIcon, color:"#8b5cf6", bg:"#f5f3ff" },
  go_service: { label:"GO Service", icon:GOServiceIcon, color:"#e24b4a", bg:"#fff5f5" },
}

const EICONS = { flat_tire:"≡ƒ¢₧", dead_battery:"≡ƒöï", out_of_fuel:"Γ¢╜", car_wont_start:"≡ƒöæ", overheating:"≡ƒîí∩╕Å", towing:"≡ƒÜÜ", other:"≡ƒåÿ" }
const SC = { pending:"#e6821e", confirmed:"#378add", "in-progress":"#8b5cf6", completed:"#1d9e75", cancelled:"#e24b4a" }
const GC = { pending:"#e6821e", accepted:"#1d9e75", declined:"#e24b4a", timeout:"#555" }

export default function AdminMechanics() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const isMobile = useIsMobile()
  const [mechanics, setMechanics] = useState([])
  const [providers, setProviders] = useState([])
  const [services, setServices] = useState([])
  const [bookings, setBookings] = useState([])
  const [goRequests, setGoRequests] = useState([])
  const [mechanicDocs, setMechanicDocs] = useState({})
  const [showDocs, setShowDocs] = useState(null)
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useState("")
  const [filter, setFilter] = useState("all")
  const [tab, setTab] = useState("mechanics")
  const [categoryFilter, setCategoryFilter] = useState("all")
  const mapRef = useRef(null)
  const mapInstanceRef = useRef(null)
  const markersRef = useRef({})

  useEffect(() => {
    load()
    const sub = supabase.channel("admin-mechanics-live")
      .on("postgres_changes", { event:"*", schema:"public", table:"mechanics" }, () => loadMechanics())
      .on("postgres_changes", { event:"*", schema:"public", table:"bookings" }, () => loadBookings())
      .on("postgres_changes", { event:"*", schema:"public", table:"go_service_requests" }, () => loadGoRequests())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [])

  useEffect(() => {
    return () => { mapInstanceRef.current = null; Object.values(markersRef.current||{}).forEach(m=>{try{m.setMap(null)}catch(e){}}); markersRef.current = {} }
    return () => { if (mapInstanceRef.current) { mapInstanceRef.current.remove(); mapInstanceRef.current = null } }
  }, [tab])

  async function load() {
    await Promise.all([loadMechanics(), loadProviders(), loadServices(), loadBookings(), loadGoRequests()])
    setLoading(false)
  }

  async function loadMechanics() {
    const { data } = await supabase.from("mechanics").select("*, profiles!mechanics_provider_id_fkey(business_name,first_name,last_name,city)").order("created_at", { ascending:false })
    setMechanics(data||[])
  }

  async function loadMechanicDocs(mechanicId) {
    const { data } = await supabase.from("driver_documents")
      .select("*").eq("driver_id", mechanicId)
    setMechanicDocs(prev => ({...prev, [mechanicId]: data||[]}))
    setShowDocs(showDocs===mechanicId?null:mechanicId)
  }

  async function verifyDoc(docId, mechanicId, status) {
    await supabase.from("driver_documents").update({ status, verified_at: new Date().toISOString() }).eq("id", docId)
    toast.success("Document " + status)
    loadMechanicDocs(mechanicId)
  }

  async function adminResetPin(mechanicId, mechanicName) {
    const newPin = window.prompt("Set new PIN for " + mechanicName + " (4-6 digits):")
    if (!newPin) return
    if (!/^\d{4,6}$/.test(newPin)) return alert("PIN must be 4-6 digits")
    try {
      await supabase.rpc("set_mechanic_pin", { p_mechanic_id: mechanicId, p_pin: newPin })
      alert("PIN set! " + mechanicName + " can login at carcareconnect.care/mechanic-login with their phone + " + newPin)
      load()
    } catch(e) { alert("Error: " + e.message) }
  }

  async function loadProviders() {
    const { data } = await supabase.from("profiles").select("id,first_name,last_name,business_name,city").eq("role","provider")
    setProviders(data||[])
  }

  async function loadServices() {
    const { data } = await supabase.from("services").select("*").order("created_at", { ascending:false })
    setServices(data||[])
  }

  async function loadBookings() {
    const { data } = await supabase.from("bookings").select("*").order("created_at", { ascending:false }).limit(100)
    setBookings(data||[])
  }

  async function loadGoRequests() {
    const { data } = await supabase.from("go_service_requests")
      .select("*, bookings(emergency_type,emergency_location_address,total_amount,service_name), profiles(first_name,last_name,business_name)")
      .order("sent_at", { ascending:false }).limit(50)
    setGoRequests(data||[])
  }

  function initMap() {
    const liveMechanics = mechanics.filter(m=>m.current_latitude&&m.current_longitude&&m.is_active)
    function buildMap() {
      if (!window.google?.maps?.Map || !mapRef.current) return
      const center = liveMechanics.length>0 ? { lat:liveMechanics[0].current_latitude, lng:liveMechanics[0].current_longitude } : { lat:-1.2921, lng:36.8219 }
      if (!mapInstanceRef.current) {
        mapInstanceRef.current = new window.google.maps.Map(mapRef.current, { center, zoom:12, mapTypeControl:false, streetViewControl:false, fullscreenControl:true, zoomControl:true, gestureHandling:"greedy" })
      }
      Object.values(markersRef.current).forEach(m=>m.setMap(null))
      markersRef.current = {}
      liveMechanics.forEach(m=>{
        const color = m.is_available?"#1d9e75":"#e6821e"
        const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 48 48"><circle cx="24" cy="24" r="22" fill="'+color+'" stroke="white" stroke-width="3"/><text x="24" y="32" font-size="20" text-anchor="middle">\u{1F527}</text></svg>'
        const icon = { url:"data:image/svg+xml;charset=UTF-8,"+encodeURIComponent(svg), scaledSize:new window.google.maps.Size(48,48), anchor:new window.google.maps.Point(24,24) }
        const marker = new window.google.maps.Marker({ position:{lat:m.current_latitude,lng:m.current_longitude}, map:mapInstanceRef.current, title:m.first_name+" "+m.last_name, icon })
        const info = new window.google.maps.InfoWindow({ content:'<div style="font-family:sans-serif;padding:6px"><b>'+m.first_name+' '+m.last_name+'</b><br/>'+( m.specialization||'General mechanic')+'<br/><span style="color:'+color+'">'+(m.is_available?'Available':'On job')+'</span></div>' })
        marker.addListener("click", ()=>info.open(mapInstanceRef.current, marker))
        markersRef.current[m.id] = marker
      })
    }
    if (window.google?.maps?.Map) {
      buildMap()
    } else {
      const ex = document.getElementById("google-maps-sdk")||document.getElementById("google-maps-admin")
      if(ex) { ex.addEventListener("load", buildMap) }
      else {
        const s = document.createElement("script")
        s.id = "google-maps-mechanic"
        s.src = "https://maps.googleapis.com/maps/api/js?key="+import.meta.env.VITE_GOOGLE_MAPS_KEY+"&libraries=marker,places&loading=async"
        s.onload = ()=>setTimeout(buildMap, 100)
        document.head.appendChild(s)
      }
    }
  }

  function getProvider(id) {
    const p = providers.find(p=>p.id===id)
    return p ? (p.business_name||`${p.first_name} ${p.last_name}`) : "Unknown"
  }

  const filteredMechanics = mechanics.filter(m => {
    const matchSearch = `${m.first_name} ${m.last_name} ${m.specialization||""} ${m.phone||""}`.toLowerCase().includes(search.toLowerCase())
    const matchFilter = filter==="all"||(filter==="available"&&m.is_available&&m.is_active)||(filter==="on_job"&&!m.is_available&&m.is_active)||(filter==="inactive"&&!m.is_active)
    return matchSearch && matchFilter
  })

  const filteredServices = categoryFilter==="all" ? services : services.filter(s=>s.category===categoryFilter)
  const filteredBookings = categoryFilter==="all" ? bookings : bookings.filter(b=>b.service_category===categoryFilter)

  const available = mechanics.filter(m=>m.is_available&&m.is_active).length
  const onJob = mechanics.filter(m=>!m.is_available&&m.is_active).length
  const liveCount = mechanics.filter(m=>m.current_latitude).length

  const TABS = [
    { k:"mechanics", l:"≡ƒæ¿ΓÇì≡ƒöº Mechanics" },
    { k:"services", l:"≡ƒöº Services" },
    { k:"bookings", l:"≡ƒôà Bookings" },
    { k:"go", l:"≡ƒÜ¿ GO Requests" },
    { k:"map", l:"≡ƒù║∩╕Å Live map" },
  ]

  return (
    <div>
      
      

      {/* Overview stats */}
      <div style={{ display:"grid", gridTemplateColumns:isMobile?"repeat(2,1fr)":"repeat(4,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Total mechanics", value:mechanics.length, color:"#000000" },
          { label:"Available", value:available, color:"#1d9e75" },
          { label:"On job", value:onJob, color:"#e6821e" },
          { label:"Live tracking", value:liveCount, color:"#8b5cf6" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:isMobile?"0.75rem":"1rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontSize:10, color:"#888", textTransform:"uppercase", marginBottom:4 }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:s.color }}>{s.value}</div>
          </div>
        ))}
      </div>

      {/* Category stats */}
      <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"repeat(3,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {Object.entries(CATEGORIES).map(([key, cat])=>(
          <div key={key} style={{ background:cat.bg, border:`1px solid ${cat.color}30`, borderRadius:12, padding:"1rem" }}>
            <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:6 }}>
              <cat.icon size={20} color={cat.color}/>
              <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:800, color:cat.color }}>{cat.label}</div>
            </div>
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
              <div>
                <div style={{ fontSize:10, color:"#888", marginBottom:2 }}>Services</div>
                <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:cat.color }}>{services.filter(s=>s.category===key).length}</div>
              </div>
              <div>
                <div style={{ fontSize:10, color:"#888", marginBottom:2 }}>Bookings</div>
                <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:cat.color }}>{bookings.filter(b=>b.service_category===key).length}</div>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Tabs */}
      <div style={{ display:"flex", gap:6, marginBottom:"1.25rem", flexWrap:"wrap" }}>
        {TABS.map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{ padding:"8px 16px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#8b5cf6":"#f8f8f8", color:tab===t.k?"#fff":"#666", fontFamily:"'DM Sans',sans-serif", fontWeight:tab===t.k?700:400 }}>
            {t.l}
          </button>
        ))}
      </div>

      {/* MECHANICS TAB */}
      {tab==="mechanics"&&(
        <div>
          <div style={{ display:"flex", gap:8, marginBottom:"1rem", flexWrap:"wrap" }}>
            <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search mechanics..."
              style={{ flex:1, minWidth:180, background:"#f8f8f8", border:"1px solid #f0f0f0", borderRadius:8, padding:"9px 12px", color:"#000000", fontSize:13, outline:"none" }}/>
            {["all","available","on_job","inactive"].map(f=>(
              <button key={f} onClick={()=>setFilter(f)}
                style={{ padding:"8px 14px", borderRadius:7, border:"none", fontSize:12, cursor:"pointer", background:filter===f?"#8b5cf6":"#f8f8f8", color:filter===f?"#fff":"#666", fontFamily:"'DM Sans',sans-serif" }}>
                {f==="all"?"All":f==="on_job"?"On job":f.charAt(0).toUpperCase()+f.slice(1)}
              </button>
            ))}
          </div>
          {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
          {!loading&&filteredMechanics.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No mechanics found</div>}
          {filteredMechanics.map(m=>(
            <div key={m.id} style={{ background:"#f8f8f8", border:`1px solid ${m.is_active?m.is_available?"#1d9e7530":"#e6821e30":"#eeeeee"}`, borderRadius:10, padding:isMobile?"0.75rem":"1rem", marginBottom:8, opacity:m.is_active?1:0.6 }}>
              <div style={{ display:"flex", alignItems:"flex-start", gap:12 }}>
                <div style={{ width:44, height:44, borderRadius:"50%", background:m.is_available&&m.is_active?"#f0fdf4":"#f5f5f5", border:`1px solid ${m.is_available&&m.is_active?"#1d9e7540":"#e0e0e0"}`, display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontSize:14, fontWeight:800, color:m.is_available&&m.is_active?"#1d9e75":"#555", flexShrink:0 }}>
                  {m.first_name[0]}{m.last_name[0]}
                </div>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4, flexWrap:"wrap" }}>
                    <div style={{ fontSize:13, fontWeight:600, color:"#000000" }}>{m.first_name} {m.last_name}</div>
                    <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:m.is_available&&m.is_active?"#f0fdf4":"#f5f5f5", color:m.is_available&&m.is_active?"#1d9e75":"#555" }}>
                      {m.is_active?(m.is_available?"Available":"On job"):"Inactive"}
                    </span>
                    {m.current_latitude&&<span style={{ fontSize:10, color:"#8b5cf6" }}>≡ƒôì Live</span>}
                  </div>
                  <div style={{ fontSize:11, color:"#888", marginBottom:2 }}>≡ƒöº {m.specialization}</div>
                  {m.phone&&<div style={{ fontSize:11, color:"#888", marginBottom:2 }}>≡ƒô₧ {m.phone}</div>}
                  <div style={{ fontSize:11, color:"#378add" }}>≡ƒÅ¬ {getProvider(m.provider_id)}</div>
                  {m.commission_rate>0&&<div style={{ fontSize:10, color:"#1d9e75", marginTop:2 }}>
                    ≡ƒÆ░ {m.commission_type==="fixed"?"KES "+Number(m.commission_rate).toLocaleString()+" per job":Math.round(m.commission_rate*100)+"% commission"}
                  </div>}
                  {m.last_location_update&&<div style={{ fontSize:10, color:"#888", marginTop:2 }}>Last seen: {new Date(m.last_location_update).toLocaleString()}</div>}
                  <div style={{ display:"flex", gap:6, marginTop:6, flexWrap:"wrap" }}>
                    {m.mechanic_code?(
                      <span style={{ fontSize:10, background:"#f0fdf4", color:"#1d9e75", padding:"2px 8px", borderRadius:8, fontWeight:700 }}>
                        Γ£ô Portal: {m.mechanic_code}
                      </span>
                    ):(
                      <span style={{ fontSize:10, background:"#fff8f0", color:"#e6821e", padding:"2px 8px", borderRadius:8 }}>
                        No PIN set
                      </span>
                    )}
                    <button onClick={()=>adminResetPin(m.id, m.first_name + " " + m.last_name)}
                      style={{ fontSize:10, background:"#eff6ff", border:"1px solid #378add30", borderRadius:6, color:"#378add", padding:"2px 8px", cursor:"pointer", fontWeight:700 }}>
                      ≡ƒöæ {m.mechanic_code?"Reset PIN":"Set PIN"}
                    </button>
              <button onClick={()=>loadMechanicDocs(m.user_id||m.id)}
                      style={{ fontSize:10, background:"#f0fdf4", border:"1px solid #1d9e7530", borderRadius:6, color:"#1d9e75", padding:"2px 8px", cursor:"pointer", fontWeight:700 }}>
              ≡ƒôä {showDocs===(m.user_id||m.id)?"Hide":"View Docs"}
                    </button>
                  </div>
                </div>
                {m.current_latitude&&(
                  <div style={{ textAlign:"right", flexShrink:0 }}>
                    <div style={{ fontSize:10, color:"#888", marginBottom:2 }}>Location</div>
                    <div style={{ fontSize:10, color:"#8b5cf6", fontFamily:"monospace" }}>{m.current_latitude?.toFixed(4)}, {m.current_longitude?.toFixed(4)}</div>
                  </div>
                )}
                {/* Document verification */}
            {showDocs===(m.user_id||m.id)&&(
                  <div style={{ marginTop:8, background:"#f8f8f8", borderRadius:10, padding:"0.75rem" }}>
                    <div style={{ fontSize:12, fontWeight:700, color:"#555", marginBottom:8 }}>≡ƒôä Documents</div>
                    {(!mechanicDocs[m.user_id||m.id]||mechanicDocs[m.user_id||m.id].length===0)&&(
                      <div style={{ fontSize:11, color:"#888" }}>No documents uploaded yet</div>
                    )}
                    {(mechanicDocs[m.user_id||m.id]||[]).map(doc=>(
                      <div key={doc.id} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:6, background:"#fff", borderRadius:7, padding:"6px 10px" }}>
                        <div>
                          <div style={{ fontSize:11, fontWeight:600, color:"#000" }}>{doc.type?.replace(/_/g," ")||"Document"}</div>
                          <span style={{ fontSize:10, color:doc.status==="approved"?"#1d9e75":doc.status==="rejected"?"#e24b4a":"#e6821e", fontWeight:700 }}>
                            {doc.status}
                          </span>
                        </div>
                        <div style={{ display:"flex", gap:4, alignItems:"center" }}>
                          <a href={doc.document_url} target="_blank" rel="noopener noreferrer"
                            style={{ fontSize:10, color:"#378add", textDecoration:"none" }}>View</a>
                          {doc.status!=="approved"&&(<button onClick={()=>verifyDoc(doc.id, m.user_id||m.id, "approved")} style={{ background:"#f0fdf4", border:"1px solid #1d9e7530", borderRadius:5, color:"#1d9e75", fontSize:9, fontWeight:700, padding:"2px 6px", cursor:"pointer" }}>Γ£ô</button>)}
                            <button onClick={()=>verifyDoc(doc.id, m.user_id||m.id, "rejected")}
                              style={{ background:"#fff5f5", border:"1px solid #e24b4a30", borderRadius:5, color:"#e24b4a", fontSize:9, fontWeight:700, padding:"2px 6px", cursor:"pointer" }}>
                              Γ£ù
                            </button>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* SERVICES TAB */}
      {tab==="services"&&(
        <div>
          <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap" }}>
            {["all","shop_standard","shop_premium","go_service"].map(k=>(
              <button key={k} onClick={()=>setCategoryFilter(k)}
                style={{ padding:"7px 14px", borderRadius:7, border:"none", fontSize:12, cursor:"pointer", background:categoryFilter===k?"#8b5cf6":"#f8f8f8", color:categoryFilter===k?"#fff":"#666", fontFamily:"'DM Sans',sans-serif" }}>
                {k==="all"?"All":CATEGORIES[k]?.label}
              </button>
            ))}
          </div>
          <div style={{ fontSize:12, color:"#888", marginBottom:10 }}>{filteredServices.length} service{filteredServices.length!==1?"s":""}</div>
          {filteredServices.map(s=>{
            const cat = CATEGORIES[s.category]||CATEGORIES.shop_standard
            const provider = providers.find(p=>p.id===s.provider_id)
            return (
              <div key={s.id} style={{ background:"#ffffff", border:`1px solid ${cat.color}20`, borderRadius:12, marginBottom:10, overflow:"hidden", opacity:s.is_active?1:0.6 }}>
                {s.photos?.length>0&&<img src={s.photos[0]} alt={s.name} style={{ width:"100%", height:120, objectFit:"cover", display:"block" }}/>}
                <div style={{ padding:"0.75rem" }}>
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", gap:8 }}>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:4, flexWrap:"wrap" }}>
                        <cat.icon size={16} color={cat.color}/>
                        <div style={{ fontSize:13, fontWeight:700, color:"#000" }}>{s.name}</div>
                        <span style={{ fontSize:9, padding:"1px 6px", borderRadius:8, background:cat.bg, color:cat.color }}>{cat.label}</span>
                        {!s.is_active&&<span style={{ fontSize:9, color:"#888", background:"#f0f0f0", padding:"1px 6px", borderRadius:8 }}>Inactive</span>}
                      </div>
                      <div style={{ fontSize:11, color:"#555", marginBottom:2 }}>≡ƒÅ¬ {provider?.business_name||`${provider?.first_name} ${provider?.last_name}`}</div>
                      {s.description&&<div style={{ fontSize:10, color:"#888", lineHeight:1.4 }}>{s.description.substring(0,80)}{s.description.length>80?"...":""}</div>}
                    </div>
                    <div style={{ textAlign:"right", flexShrink:0 }}>
                      <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#e6821e" }}>KES {Number(s.price).toLocaleString()}</div>
                      <div style={{ fontSize:9, color:cat.color, marginTop:1 }}>{Math.round((s.platform_commission_rate||0.1)*100)}% platform</div>
                      <div style={{ fontSize:9, color:"#888" }}>ΓÅ▒ {s.duration_minutes||60} min</div>
                      {s.photos?.length>0&&<div style={{ fontSize:9, color:"#378add", marginTop:2 }}>≡ƒô╖ {s.photos.length} photo{s.photos.length>1?"s":""}</div>}
                    </div>
                  </div>
                </div>
              </div>
              )
          })}
        </div>
      )}

      {/* BOOKINGS TAB */}
      {tab==="bookings"&&(
        <div>
          <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap" }}>
            {["all","shop_standard","shop_premium","go_service"].map(k=>(
              <button key={k} onClick={()=>setCategoryFilter(k)}
                style={{ padding:"7px 14px", borderRadius:7, border:"none", fontSize:12, cursor:"pointer", background:categoryFilter===k?"#8b5cf6":"#f8f8f8", color:categoryFilter===k?"#fff":"#666", fontFamily:"'DM Sans',sans-serif" }}>
                {k==="all"?"All":CATEGORIES[k]?.label}
              </button>
            ))}
          </div>
          <div style={{ fontSize:12, color:"#888", marginBottom:10 }}>{filteredBookings.length} booking{filteredBookings.length!==1?"s":""}</div>
          {filteredBookings.slice(0,50).map(b=>{
            const cat = CATEGORIES[b.service_category]||CATEGORIES.shop_standard
            return (
              <div key={b.id} style={{ background:"#f8f8f8", border:`1px solid ${cat.color}15`, borderRadius:10, padding:"0.9rem", marginBottom:8 }}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", gap:10 }}>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:4, flexWrap:"wrap" }}>
                      <cat.icon size={16} color={cat.color}/>
                      <div style={{ fontSize:13, fontWeight:600, color:"#000000" }}>{b.service_name}</div>
                      <span style={{ fontSize:10, padding:"1px 7px", borderRadius:10, background:cat.bg, color:cat.color }}>{cat.label}</span>
                      <span style={{ fontSize:10, padding:"1px 7px", borderRadius:10, background:`${SC[b.status]||"#888"}20`, color:SC[b.status]||"#888" }}>{b.status}</span>
                    </div>
                    <div style={{ fontSize:11, color:"#888" }}>#{b.booking_number} ┬╖ {b.booking_date}</div>
                    {b.assigned_mechanic_id&&<div style={{ fontSize:11, color:"#1d9e75", marginTop:2 }}>≡ƒæ¿ΓÇì≡ƒöº Mechanic assigned</div>}
                    {b.is_emergency&&<div style={{ fontSize:11, color:"#e24b4a", marginTop:2 }}>≡ƒÜ¿ Emergency</div>}
                  </div>
                  <div style={{ textAlign:"right", flexShrink:0 }}>
                    <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:800, color:"#e6821e" }}>KES {Number(b.total_amount).toLocaleString()}</div>
                    <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{b.payment_status}</div>
                  </div>
                </div>
              </div>
            )
          })}
        </div>
      )}

      {/* GO REQUESTS TAB */}
      {tab==="go"&&(
        <div>
          <div style={{ display:"grid", gridTemplateColumns:isMobile?"repeat(2,1fr)":"repeat(4,1fr)", gap:10, marginBottom:"1.25rem" }}>
            {[
              { label:"Total", value:goRequests.length, color:"#e24b4a" },
              { label:"Pending", value:goRequests.filter(r=>r.status==="pending").length, color:"#e6821e" },
              { label:"Accepted", value:goRequests.filter(r=>r.status==="accepted").length, color:"#1d9e75" },
              { label:"Timed out", value:goRequests.filter(r=>r.status==="timeout").length, color:"#888" },
            ].map(s=>(
              <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.9rem", border:"1px solid #eeeeee" }}>
                <div style={{ fontSize:10, color:"#888", textTransform:"uppercase", marginBottom:4 }}>{s.label}</div>
                <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:s.color }}>{s.value}</div>
              </div>
            ))}
          </div>
          {goRequests.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No GO requests yet</div>}
          {goRequests.map(r=>(
            <div key={r.id} style={{ background:"#f8f8f8", border:`1px solid ${GC[r.status]||"#eeeeee"}30`, borderRadius:10, padding:"0.9rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", gap:10 }}>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4, flexWrap:"wrap" }}>
                    <span style={{ fontSize:18 }}>{EICONS[r.bookings?.emergency_type]||"≡ƒåÿ"}</span>
                    <div style={{ fontSize:13, fontWeight:600, color:"#000000" }}>{r.bookings?.emergency_type?.replace(/_/g," ")||r.bookings?.service_name}</div>
                    <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:`${GC[r.status]||"#888"}20`, color:GC[r.status]||"#888" }}>{r.status}</span>
                    <span style={{ fontSize:10, color:"#888" }}>Attempt {r.attempt_number}/5</span>
                  </div>
                  <div style={{ fontSize:11, color:"#888", marginBottom:2 }}>≡ƒôì {r.bookings?.emergency_location_address||"ΓÇö"}</div>
                  <div style={{ fontSize:11, color:"#378add" }}>≡ƒÅ¬ {r.profiles?.business_name||`${r.profiles?.first_name||""} ${r.profiles?.last_name||""}`}</div>
                  <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{new Date(r.sent_at).toLocaleString()}</div>
                </div>
                <div style={{ textAlign:"right", flexShrink:0 }}>
                  <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:800, color:"#e6821e" }}>KES {Number(r.bookings?.total_amount||0).toLocaleString()}</div>
                  {r.responded_at&&<div style={{ fontSize:10, color:"#888", marginTop:2 }}>{new Date(r.responded_at).toLocaleTimeString()}</div>}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* MAP TAB */}
      {tab==="map"&&(
        <div>
          <div style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:12, padding:"1rem", marginBottom:"1rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#000000", marginBottom:6 }}>Live mechanic map</div>
            <div style={{ display:"flex", gap:12, marginBottom:10, flexWrap:"wrap" }}>
              <div style={{ display:"flex", alignItems:"center", gap:6 }}>
                <div style={{ width:12, height:12, borderRadius:"50%", background:"#1d9e75" }}/>
                <span style={{ fontSize:11, color:"#888" }}>Available ({available})</span>
              </div>
              <div style={{ display:"flex", alignItems:"center", gap:6 }}>
                <div style={{ width:12, height:12, borderRadius:"50%", background:"#e6821e" }}/>
                <span style={{ fontSize:11, color:"#888" }}>On job ({onJob})</span>
              </div>
              <div style={{ fontSize:11, color:"#888" }}>{liveCount} live location{liveCount!==1?"s":""}</div>
            </div>
            <div ref={mapRef} style={{ height:isMobile?300:450, borderRadius:10, overflow:"hidden", background:"#f5f5f5" }}>
              {liveCount===0&&(
                <div style={{ height:"100%", display:"flex", alignItems:"center", justifyContent:"center", flexDirection:"column", gap:8 }}>
                  <div style={{ fontSize:32 }}>≡ƒù║∩╕Å</div>
                  <div style={{ fontSize:12, color:"#888" }}>No mechanics sharing location</div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

import { VehicleIcon, WarningIcon, CheckIcon, CloseIcon } from "../../lib/cccIcons"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

export default function AdminNewCars() {
  const { user } = useAuth()
  const isMobile = useIsMobile()
  const [listings, setListings] = useState([])
  const [enquiries, setEnquiries] = useState([])
  const [brands, setBrands] = useState([])
  const [loading, setLoading] = useState(true)
  const [tab, setTab] = useState("all")
  const [selected, setSelected] = useState(null)
  const [adminNotes, setAdminNotes] = useState("")
  const [processing, setProcessing] = useState(false)
  const [brandForm, setBrandForm] = useState({ name:"", is_popular:false })
  const [showBrandForm, setShowBrandForm] = useState(false)
  const [applications, setApplications] = useState([])

  useEffect(() => { load() }, [])

  async function load() {
    const [{ data: lst }, { data: enq }, { data: brs }, { data: apps }] = await Promise.all([
      supabase.from("new_car_listings").select("*, dealer:profiles!new_car_listings_dealer_id_fkey(first_name,last_name,provider_type,city)").order("created_at",{ascending:false}),
      supabase.from("car_enquiries").select("*, new_car_listings(brand,model,year), customer:profiles!car_enquiries_customer_id_fkey(first_name,last_name)").order("created_at",{ascending:false}),
      supabase.from("car_brands").select("*").order("display_order"),
      supabase.from("dealer_applications").select("*, profiles!dealer_applications_user_id_fkey(first_name,last_name)").order("created_at",{ascending:false})
    ])
    setListings(lst||[])
    setEnquiries(enq||[])
    setBrands(brs||[])
    setApplications(apps||[])
    setLoading(false)
  }

  async function approveListing(id) {
    setProcessing(true)
    try {
      const expires = new Date(Date.now() + 30*24*60*60*1000).toISOString()
      await supabase.from("new_car_listings").update({
        is_active: true, listing_fee_paid: true,
        listing_paid_at: new Date().toISOString(),
        listing_expires_at: expires,
        approved_by: user.id, approved_at: new Date().toISOString(),
        admin_notes: adminNotes||null, rejection_reason: null
      }).eq("id", id)
      const listing = listings.find(l=>l.id===id)
      if (listing) {
        await supabase.from("notifications").insert({ user_id:listing.dealer_id, title:"Listing Approved! Γ£à", message:`Your ${listing.year} ${listing.brand} ${listing.model} listing has been approved and is now live.`, type:"success" })
      }
      toast.success("Listing approved and activated!")
      setSelected(null); setAdminNotes(""); load()
    } catch(e) { toast.error(e.message) }
    finally { setProcessing(false) }
  }

  async function rejectListing(id) {
    if (!adminNotes) return toast.error("Please add a rejection reason")
    setProcessing(true)
    try {
      await supabase.from("new_car_listings").update({ rejection_reason: adminNotes, is_active:false }).eq("id", id)
      const listing = listings.find(l=>l.id===id)
      if (listing) {
        await supabase.from("notifications").insert({ user_id:listing.dealer_id, title:"Listing Update Required", message:`Your ${listing.year} ${listing.brand} ${listing.model} listing was not approved: ${adminNotes}`, type:"warning" })
      }
      toast.success("Listing rejected")
      setSelected(null); setAdminNotes(""); load()
    } catch(e) { toast.error(e.message) }
    finally { setProcessing(false) }
  }

  async function toggleFeatured(id, is_featured) {
    await supabase.from("new_car_listings").update({ is_featured:!is_featured }).eq("id",id)
    toast.success(is_featured?"Removed from featured":"Added to featured!")
    load()
  }

  async function markSold(id) {
    await supabase.from("new_car_listings").update({ is_sold:true, is_active:false }).eq("id",id)
    toast.success("Marked as sold")
    load()
  }

  async function suspendListing(id) {
    if (!confirm("Suspend this listing?")) return
    await supabase.from("new_car_listings").update({ is_active:false }).eq("id",id)
    toast.success("Listing suspended")
    load()
  }

  async function deleteListing(id) {
    if (!confirm("Delete this listing permanently?")) return
    await supabase.from("new_car_listings").delete().eq("id",id)
    toast.success("Listing deleted")
    load()
  }

  async function addBrand(e) {
    e.preventDefault()
    await supabase.from("car_brands").insert({ name:brandForm.name, is_popular:brandForm.is_popular, display_order:brands.length+1 })
    toast.success("Brand added!")
    setBrandForm({ name:"", is_popular:false }); setShowBrandForm(false); load()
  }

  async function approveApplication(app) {
    await supabase.from("dealer_applications").update({ status:"approved", reviewed_by:user.id, reviewed_at:new Date().toISOString() }).eq("id",app.id)
    await supabase.from("profiles").update({ is_dealer:true }).eq("id", app.user_id)
    await supabase.from("notifications").insert({ user_id:app.user_id, title:"Dealer Application Approved! ≡ƒÅó", message:`Welcome to CCC! Your dealership ${app.showroom_name} has been approved. You can now list vehicles.`, type:"success" })
    toast.success("Application approved!")
    load()
  }

  async function rejectApplication(app) {
    await supabase.from("dealer_applications").update({ status:"rejected", reviewed_by:user.id, reviewed_at:new Date().toISOString() }).eq("id",app.id)
    await supabase.from("notifications").insert({ user_id:app.user_id, title:"Dealer Application Update", message:`Your dealership application for ${app.showroom_name} was not approved. Contact support for more information.`, type:"warning" })
    toast.success("Application rejected")
    load()
  }

  const pending = listings.filter(l=>l.listing_fee_paid&&!l.is_active&&!l.rejection_reason)
  const active = listings.filter(l=>l.is_active)
  const rejected = listings.filter(l=>l.rejection_reason)
  const unpaid = listings.filter(l=>!l.listing_fee_paid)
  const newEnquiries = enquiries.filter(e=>e.status==="new").length
  const converted = enquiries.filter(e=>e.status==="converted").length
  const pendingApps = applications.filter(a=>a.status==="pending").length

  const tabListings = tab==="pending" ? pending : tab==="active" ? active : tab==="rejected" ? rejected : tab==="unpaid" ? unpaid : listings

  const STATUS_COLOR = { pending:"#e6821e", active:"#1d9e75", rejected:"#e24b4a", unpaid:"#8b5cf6" }

  function getListingStatus(l) {
    if (l.is_sold) return { label:"Sold", color:"#888" }
    if (l.rejection_reason) return { label:"Rejected", color:"#e24b4a" }
    if (!l.listing_fee_paid) return { label:"Unpaid", color:"#8b5cf6" }
    if (!l.is_active) return { label:"Pending review", color:"#e6821e" }
    return { label:"Active", color:"#1d9e75" }
  }

  return (
    <div>
      {/* Header */}
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:"#000", marginBottom:4 }}>New Car Marketplace</div>
      <div style={{ fontSize:12, color:"#777", marginBottom:"1.25rem" }}>Manage listings, brands and dealer applications</div>

      {/* Gradient stats header */}
      <div style={{ background:"linear-gradient(135deg,#8b5cf6,#a78bfa)", borderRadius:14, padding:"1rem 1.25rem", marginBottom:"1.25rem", display:"flex", justifyContent:"space-between", alignItems:"center" }}>
        <div>
          <div style={{ fontFamily:"Syne", fontSize:22, fontWeight:800, color:"#fff" }}>{listings.length} listings</div>
          <div style={{ fontSize:11, color:"rgba(255,255,255,0.8)", marginTop:2 }}>{active.length} active ┬╖ {pending.length} pending ┬╖ {enquiries.length} enquiries</div>
        </div>
        <div style={{ display:"flex", gap:16 }}>
          {pending.length>0&&<div style={{ textAlign:"center" }}>
            <div style={{ fontFamily:"Syne", fontSize:20, fontWeight:800, color:"#fde68a" }}>{pending.length}</div>
            <div style={{ fontSize:10, color:"rgba(255,255,255,0.7)" }}>Need review</div>
          </div>}
          {pendingApps>0&&<div style={{ textAlign:"center" }}>
            <div style={{ fontFamily:"Syne", fontSize:20, fontWeight:800, color:"#fde68a" }}>{pendingApps}</div>
            <div style={{ fontSize:10, color:"rgba(255,255,255,0.7)" }}>Dealer apps</div>
          </div>}
          <div style={{ textAlign:"center" }}>
            <div style={{ fontFamily:"Syne", fontSize:20, fontWeight:800, color:"rgba(255,255,255,0.9)" }}>{converted}</div>
            <div style={{ fontSize:10, color:"rgba(255,255,255,0.7)" }}>Converted</div>
          </div>
        </div>
      </div>

      {/* Alert for pending items */}
      {(pending.length>0||pendingApps>0)&&(
        <div style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:10, padding:"0.75rem 1rem", marginBottom:"1rem", display:"flex", gap:8, alignItems:"center" }}>
          <WarningIcon size={14} color="#e6821e"/>
          <span style={{ fontSize:12, color:"#e6821e", fontWeight:600 }}>
            {pending.length>0&&`${pending.length} listing${pending.length>1?"s":""} awaiting review`}
            {pending.length>0&&pendingApps>0&&" ┬╖ "}
            {pendingApps>0&&`${pendingApps} dealer application${pendingApps>1?"s":""} pending`}
          </span>
        </div>
      )}

      {/* Tabs */}
      <div style={{ display:"flex", gap:6, marginBottom:"1.25rem", flexWrap:"wrap" }}>
        {[
          {k:"all",l:"All listings",count:listings.length},
          {k:"pending",l:"Pending",count:pending.length,alert:pending.length>0},
          {k:"active",l:"Active",count:active.length},
          {k:"unpaid",l:"Unpaid",count:unpaid.length},
          {k:"rejected",l:"Rejected",count:rejected.length},
          {k:"enquiries",l:"Enquiries",count:enquiries.length},
          {k:"brands",l:"Brands",count:brands.length},
          {k:"applications",l:"Dealers",count:applications.length,alert:pendingApps>0},
        ].map(t=>(
          <button key={t.k} onClick={()=>{ setTab(t.k); setSelected(null) }}
            style={{ padding:"7px 14px", borderRadius:8, border:"none", fontSize:11, cursor:"pointer", background:tab===t.k?"#8b5cf6":"#f0f0f0", color:tab===t.k?"#fff":"#555", fontWeight:tab===t.k?700:400, position:"relative" }}>
            {t.l} ({t.count})
            {t.alert&&t.count>0&&<span style={{ position:"absolute", top:-4, right:-4, width:8, height:8, borderRadius:"50%", background:"#e24b4a" }}/>}
          </button>
        ))}
      </div>

      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}

      {/* Listings */}
      {["all","pending","active","unpaid","rejected"].includes(tab)&&(
        <div>
          {tabListings.length===0&&(
            <div style={{ textAlign:"center", padding:"2rem", color:"#888" }}>
              <div style={{ marginBottom:8, display:"flex", justifyContent:"center" }}><VehicleIcon size={32} color="#e6821e"/></div>
              <div style={{ fontSize:13 }}>No listings in this category</div>
            </div>
          )}
          {tabListings.map(l=>{
            const status = getListingStatus(l)
            return (
              <div key={l.id} style={{ background:"#ffffff", border:"1px solid "+(selected===l.id?"#8b5cf6":"#eeeeee"), borderRadius:14, padding:"1rem", marginBottom:10, boxShadow:"0 1px 4px rgba(0,0,0,0.04)" }}>
                <div style={{ display:"flex", gap:12, alignItems:"flex-start", flexDirection:isMobile?"column":"row" }}>
                  {/* Photos strip */}
                  <div style={{ flexShrink:0, width:isMobile?"100%":"auto" }}>
                    {l.photos?.length>0 ? (
                      <div style={{ display:"flex", gap:3, flexDirection:"column" }}>
                        <img src={l.photos[0]} alt="" onClick={()=>window.open(l.photos[0],"_blank")}
                          style={{ width:isMobile?"100%":80, height:isMobile?160:60, objectFit:"cover", borderRadius:8, cursor:"pointer", border:"1px solid #eee" }}/>
                        {l.photos.length>1&&(
                          <div style={{ display:"flex", gap:3 }}>
                            {l.photos.slice(1,3).map((p,i)=>(
                              <img key={i} src={p} alt="" onClick={()=>window.open(p,"_blank")}
                                style={{ width:38, height:28, objectFit:"cover", borderRadius:5, cursor:"pointer", border:"1px solid #eee" }}/>
                            ))}
                            {l.photos.length>3&&<div style={{ width:38, height:28, borderRadius:5, background:"#f0f0f0", display:"flex", alignItems:"center", justifyContent:"center", fontSize:9, color:"#888", fontWeight:700 }}>+{l.photos.length-3}</div>}
                          </div>
                        )}
                        {l.video_url&&<div style={{ fontSize:9, color:"#8b5cf6", marginTop:2 }}>≡ƒÄÑ Has video</div>}
                      </div>
                    ):(
                      <div style={{ width:80, height:80, borderRadius:8, background:"#f0f0f0", display:"flex", alignItems:"center", justifyContent:"center", fontSize:28 }}>≡ƒÜù</div>
                    )}
                  </div>

                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:6 }}>
                      <div style={{ flex:1, minWidth:0, marginRight:8 }}>
                        <div style={{ fontSize:14, fontWeight:700, color:"#000", marginBottom:2 }}>{l.year} {l.brand} {l.model} {l.variant||""}</div>
                        <div style={{ fontSize:11, color:"#888" }}>≡ƒÅó {l.showroom_name} ┬╖ ≡ƒôì {l.showroom_location}</div>
                        <div style={{ fontSize:11, color:"#888" }}>≡ƒæñ {l.dealer?.first_name} {l.dealer?.last_name}</div>
                        <div style={{ fontSize:10, color:"#aaa", marginTop:2 }}>{new Date(l.created_at).toLocaleDateString()} ┬╖ ≡ƒæü {l.views||0} views ┬╖ ≡ƒÆ¼ {l.enquiries||0} enquiries</div>
                      </div>
                      <div style={{ textAlign:"right", flexShrink:0 }}>
                        <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#e6821e" }}>KES {Number(l.price).toLocaleString()}</div>
                        {l.discount_price&&<div style={{ fontSize:11, color:"#1d9e75" }}>Offer: KES {Number(l.discount_price).toLocaleString()}</div>}
                        <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:status.color+"20", color:status.color, fontWeight:600, border:"1px solid "+status.color+"30" }}>{status.label}</span>
                        {l.is_featured&&<div style={{ fontSize:10, color:"#e6821e", marginTop:2 }}>Γ¡É Featured</div>}
                      </div>
                    </div>

                    {/* Video preview */}
                    {selected===l.id&&l.video_url&&(
                      <div style={{ marginBottom:8 }}>
                        <video src={l.video_url} controls style={{ width:"100%", maxHeight:180, borderRadius:8 }}/>
                      </div>
                    )}

