import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const TYPE_COLORS = {
  success: { color:"#1d9e75", bg:"#f0fdf4", border:"#1d9e7530" },
  warning: { color:"#e6821e", bg:"#fff8f0", border:"#e6821e30" },
  error: { color:"#e24b4a", bg:"#fff5f5", border:"#e24b4a30" },
  info: { color:"#378add", bg:"#eff6ff", border:"#378add30" },
}

const PRIORITY = {
  "≡ƒÜ¿": 1, "ΓÜá∩╕Å": 2, "≡ƒÆ░": 2, "≡ƒÄ½": 3, "≡ƒæñ": 4, "≡ƒôï": 5, "≡ƒÜù": 2
}

export default function AdminNotifications() {
  const { user } = useAuth()
  const isMobile = useIsMobile()
  const [notifications, setNotifications] = useState([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState("all")
  const [unreadCount, setUnreadCount] = useState(0)

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("admin-notifs-live")
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"notifications", filter:`user_id=eq.${user.id}` },
        payload => {
          setNotifications(prev => [payload.new, ...prev])
          setUnreadCount(c => c + 1)
          toast(payload.new.title, { icon: payload.new.type==="warning"?"ΓÜá∩╕Å":payload.new.type==="error"?"≡ƒÜ¿":"≡ƒôó", duration:5000 })
        })
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function load() {
    const { data } = await supabase.from("notifications")
      .select("*")
      .eq("user_id", user.id)
      .order("created_at", { ascending:false })
      .limit(100)
    setNotifications(data||[])
    setUnreadCount(data?.filter(n=>!n.is_read).length||0)
    setLoading(false)
  }

  async function markRead(id) {
    await supabase.from("notifications").update({ is_read:true }).eq("id",id)
    setNotifications(prev => prev.map(n => n.id===id ? {...n,is_read:true} : n))
    setUnreadCount(c => Math.max(0,c-1))
  }

  async function markAllRead() {
    await supabase.from("notifications").update({ is_read:true }).eq("user_id",user.id).eq("is_read",false)
    setNotifications(prev => prev.map(n => ({...n,is_read:true})))
    setUnreadCount(0)
    toast.success("All marked as read")
  }

  async function deleteNotification(id) {
    await supabase.from("notifications").delete().eq("id",id)
    setNotifications(prev => prev.filter(n=>n.id!==id))
  }

  async function clearAll() {
    if (!confirm("Clear all notifications?")) return
    await supabase.from("notifications").delete().eq("user_id",user.id)
    setNotifications([])
    setUnreadCount(0)
    toast.success("All notifications cleared")
  }

  const filtered = notifications.filter(n => {
    if (filter==="unread") return !n.is_read
    if (filter==="warning") return n.type==="warning"||n.type==="error"
    if (filter==="info") return n.type==="info"||n.type==="success"
    return true
  })

  const grouped = {
    urgent: filtered.filter(n=>n.title?.includes("≡ƒÜ¿")||n.title?.includes("dispute")||n.title?.includes("Dispute")||n.type==="error"),
    warning: filtered.filter(n=>(n.title?.includes("ΓÜá∩╕Å")||n.title?.includes("≡ƒÆ░")||n.title?.includes("Mileage")||n.title?.includes("Payout"))&&n.type==="warning"),
    info: filtered.filter(n=>n.type==="info"||n.type==="success"),
  }

  return (
    <div>
      {/* Header */}
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1.5rem", flexWrap:"wrap", gap:10 }}>
        <div>
          <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:"#000000" }}>
            Notifications
            {unreadCount>0&&<span style={{ marginLeft:8, background:"#e24b4a", color:"#fff", borderRadius:20, fontSize:11, padding:"2px 8px", fontFamily:"'DM Sans',sans-serif" }}>{unreadCount} new</span>}
          </div>
          <div style={{ fontSize:12, color:"#888", marginTop:2 }}>Real-time platform activity</div>
        </div>
        <div style={{ display:"flex", gap:8 }}>
          {unreadCount>0&&(
            <button onClick={markAllRead}
              style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:8, color:"#1d9e75", fontSize:12, padding:"8px 14px", cursor:"pointer" }}>
              Γ£ô Mark all read
            </button>
          )}
          <button onClick={clearAll}
            style={{ background:"none", border:"1px solid #dddddd", borderRadius:8, color:"#888", fontSize:12, padding:"8px 14px", cursor:"pointer" }}>
            Clear all
          </button>
        </div>
      </div>

      {/* Stats */}
      <div style={{ display:"grid", gridTemplateColumns:isMobile?"repeat(2,1fr)":"repeat(4,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Total", value:notifications.length, color:"#000000" },
          { label:"Unread", value:unreadCount, color:"#e24b4a" },
          { label:"Urgent", value:grouped.urgent.length, color:"#e6821e" },
          { label:"Today", value:notifications.filter(n=>n.created_at?.startsWith(new Date().toISOString().split("T")[0])).length, color:"#378add" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:isMobile?"0.75rem":"1rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontSize:10, color:"#888", textTransform:"uppercase", marginBottom:4 }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:s.color }}>{s.value}</div>
          </div>
        ))}
      </div>

      {/* Filters */}
      <div style={{ display:"flex", gap:6, marginBottom:"1.25rem", flexWrap:"wrap" }}>
        {[
          { k:"all", l:"All" },
          { k:"unread", l:`Unread (${unreadCount})` },
          { k:"warning", l:"Urgent & warnings" },
          { k:"info", l:"Info" },
        ].map(f=>(
          <button key={f.k} onClick={()=>setFilter(f.k)}
            style={{ padding:"7px 14px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:filter===f.k?"#8b5cf6":"#f8f8f8", color:filter===f.k?"#fff":"#666", fontFamily:"'DM Sans',sans-serif", fontWeight:filter===f.k?700:400 }}>
            {f.l}
          </button>
        ))}
      </div>

      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
      {!loading&&filtered.length===0&&(
        <div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"3rem" }}>
          <div style={{ fontSize:32, marginBottom:10 }}>≡ƒöö</div>
          No notifications
        </div>
      )}

      {/* Urgent section */}
      {filter==="all"&&grouped.urgent.length>0&&(
        <div style={{ marginBottom:"1.5rem" }}>
          <div style={{ fontSize:11, color:"#e24b4a", fontWeight:700, textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:8 }}>≡ƒÜ¿ Urgent</div>
          {grouped.urgent.map(n=><NotifCard key={n.id} n={n} onRead={markRead} onDelete={deleteNotification}/>)}
        </div>
      )}

      {/* Warning section */}
      {filter==="all"&&grouped.warning.length>0&&(
        <div style={{ marginBottom:"1.5rem" }}>
          <div style={{ fontSize:11, color:"#e6821e", fontWeight:700, textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:8 }}>ΓÜá∩╕Å Needs attention</div>
          {grouped.warning.map(n=><NotifCard key={n.id} n={n} onRead={markRead} onDelete={deleteNotification}/>)}
        </div>
      )}

      {/* Info section */}
      {filter==="all"&&grouped.info.length>0&&(
        <div style={{ marginBottom:"1.5rem" }}>
          <div style={{ fontSize:11, color:"#378add", fontWeight:700, textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:8 }}>≡ƒôó Activity</div>
          {grouped.info.map(n=><NotifCard key={n.id} n={n} onRead={markRead} onDelete={deleteNotification}/>)}
        </div>
      )}

      {/* Filtered list */}
      {filter!=="all"&&filtered.map(n=><NotifCard key={n.id} n={n} onRead={markRead} onDelete={deleteNotification}/>)}
    </div>
  )
}

function NotifCard({ n, onRead, onDelete }) {
  const c = TYPE_COLORS[n.type]||TYPE_COLORS.info
  const timeAgo = (date) => {
    const diff = Date.now() - new Date(date).getTime()
    const mins = Math.floor(diff/60000)
    const hrs = Math.floor(mins/60)
    const days = Math.floor(hrs/24)
    if (days>0) return `${days}d ago`
    if (hrs>0) return `${hrs}h ago`
    if (mins>0) return `${mins}m ago`
    return "Just now"
  }

  return (
    <div style={{ background:n.is_read?"#f8f8f8":c.bg, border:`1px solid ${n.is_read?"#eeeeee":c.border}`, borderRadius:10, padding:"0.9rem", marginBottom:8, opacity:n.is_read?0.7:1, transition:"all 0.2s" }}>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", gap:10 }}>
        <div style={{ flex:1, minWidth:0 }}>
          <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4 }}>
            {!n.is_read&&<div style={{ width:7, height:7, borderRadius:"50%", background:c.color, boxShadow:`0 0 6px ${c.color}`, flexShrink:0 }}/>}
            <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:n.is_read?"#666":c.color }}>{n.title}</div>
          </div>
          <div style={{ fontSize:12, color:"#888", lineHeight:1.5, marginBottom:4 }}>{n.message}</div>
          <div style={{ fontSize:10, color:"#888" }}>{timeAgo(n.created_at)}</div>
        </div>
        <div style={{ display:"flex", gap:6, flexShrink:0 }}>
          {!n.is_read&&(
            <button onClick={()=>onRead(n.id)}
              style={{ background:"none", border:`1px solid ${c.color}30`, borderRadius:6, color:c.color, fontSize:10, padding:"3px 8px", cursor:"pointer" }}>
              Mark read
            </button>
          )}
          <button onClick={()=>onDelete(n.id)}
            style={{ background:"none", border:"1px solid #dddddd", borderRadius:6, color:"#888", fontSize:10, padding:"3px 8px", cursor:"pointer" }}>
            ├ù
          </button>
        </div>
      </div>
    </div>
  )
}

import { LocationIcon, ServicesIcon, DeliveryIcon, ProfileIcon, MarketplaceIcon, WalletIcon } from "../../lib/cccIcons"
import { useEffect, useState } from "react"
import { useAuth } from "../../contexts/AuthContext"
import { supabase } from "../../lib/supabase"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const SC = { pending:"#e6821e", confirmed:"#378add", processing:"#8b5cf6", ready:"#1d9e75", delivered:"#1d9e75", cancelled:"#e24b4a" }

export default function AdminOrders() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const isMobile = useIsMobile()
  const [orders, setOrders] = useState([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState("all")
  const [zones, setZones] = useState([])
  const [showZones, setShowZones] = useState(false)
  const [search, setSearch] = useState("")
  const [zoneForm, setZoneForm] = useState({ name:"", base_fee:"", per_km_fee:"" })
  const [editingZoneId, setEditingZoneId] = useState(null)
  const [editZoneForm, setEditZoneForm] = useState({ base_fee:"", per_km_fee:"" })

  useEffect(() => { load(); loadZones() }, [])

  async function load() {
    const { data } = await supabase.from("orders")
      .select("*, order_items(name,quantity,unit_price), profiles!orders_customer_id_fkey(first_name,last_name), provider:profiles!orders_provider_id_fkey(first_name,last_name,business_name), driver:profiles!orders_delivery_driver_id_fkey(first_name,last_name,driver_vehicle_type)")
      .order("created_at", { ascending:false })
    setOrders(data||[])
    setLoading(false)
  }

  async function loadZones() {
    const { data } = await supabase.from("delivery_zones").select("*").order("name")
    setZones(data||[])
  }

  async function addZone(e) {
    e.preventDefault()
    await supabase.from("delivery_zones").insert({
      name: zoneForm.name,
      base_fee: Number(zoneForm.base_fee),
      per_km_fee: Number(zoneForm.per_km_fee),
    })
    toast.success("Zone added")
    setZoneForm({ name:"", base_fee:"", per_km_fee:"" })
    loadZones()
  }

  async function toggleZone(id, active) {
    await supabase.from("delivery_zones").update({ is_active:!active }).eq("id", id)
    loadZones()
  }
  function startEditZone(z) {
    setEditingZoneId(z.id)
    setEditZoneForm({ base_fee: String(z.base_fee), per_km_fee: String(z.per_km_fee) })
  }
  async function saveEditZone(id) {
    await supabase.from("delivery_zones").update({
      base_fee: Number(editZoneForm.base_fee),
      per_km_fee: Number(editZoneForm.per_km_fee),
    }).eq("id", id)
    toast.success("Zone fees updated")
    setEditingZoneId(null)
    loadZones()
  }

  async function assignDriver(orderId) {
    const order = orders.find(o=>o.id===orderId)
    const itemCount = order?.order_items?.length||1
    const preferredType = itemCount<=3?"motorcycle":itemCount<=6?"tuktuk":"van"
    const { data: drivers } = await supabase.from("profiles")
      .select("id,first_name,last_name,driver_vehicle_type")
      .eq("role","driver")
      .eq("is_active",true)
      .eq("documents_verified",true)
    if (!drivers?.length) return toast.error("No verified drivers available")
    const preferred = drivers.filter(d=>d.driver_vehicle_type===preferredType)
    const driver = preferred.length>0 ? preferred[0] : drivers[0]
    await supabase.from("orders").update({ delivery_driver_id:driver.id, delivery_status:"driver_assigned" }).eq("id", orderId)
    await supabase.from("notifications").insert({
      user_id: driver.id,
      title: "≡ƒÜÜ Delivery assigned by admin!",
      message: "New delivery: "+itemCount+" item(s) to "+order?.delivery_address+". Zone: "+order?.delivery_zone,
      type: "success"
    })
    toast.success("Smart match: "+driver.first_name+" ("+driver.driver_vehicle_type+")")
    load()
  }

  const filtered = orders.filter(o => {
    const matchStatus = filter==="all" || o.status===filter
    const matchSearch = !search || 
      o.order_number?.toLowerCase().includes(search.toLowerCase()) ||
      `${o.profiles?.first_name} ${o.profiles?.last_name}`.toLowerCase().includes(search.toLowerCase()) ||
      o.provider?.business_name?.toLowerCase().includes(search.toLowerCase())
    return matchStatus && matchSearch
  })
  const totalRevenue = orders.filter(o=>o.status==="delivered").reduce((s,o)=>s+Number(o.platform_commission||0),0)
  const pendingOrders = orders.filter(o=>o.status==="pending").length
  const todayOrders = orders.filter(o=>new Date(o.created_at).toDateString()===new Date().toDateString()).length

  const inp = { width:"100%", background:"#ffffff", border:"1px solid #f0f0f0", borderRadius:8, padding:"9px 12px", color:"#000000", fontSize:12, outline:"none", fontFamily:"DM Sans,sans-serif", marginBottom:8 }

  return (
    <div>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1.25rem", flexWrap:"wrap", gap:10 }}>
        <div>
          <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:"#000000" }}>Orders Management</div>
          <div style={{ fontSize:12, color:"#888" }}>Parts and accessories orders across platform</div>
        </div>
        <button onClick={()=>setShowZones(!showZones)}
          style={{ background:"#f5f3ff", border:"1px solid #8b5cf640", borderRadius:9, color:"#8b5cf6", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"9px 16px", cursor:"pointer" }}>
          <><LocationIcon size={13} color="currentColor"/> Delivery zones</>
        </button>
      </div>

      <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Total orders", value:orders.length, color:"#000000" },
          { label:"Pending", value:pendingOrders, color:pendingOrders>0?"#e6821e":"#555" },
          { label:"Today", value:todayOrders, color:"#378add" },
          { label:"Platform revenue", value:"KES "+totalRevenue.toLocaleString(), color:"#1d9e75" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.75rem", border:"1px solid #eeeeee", textAlign:"center" }}>
            <div style={{ fontFamily:"Syne", fontSize:isMobile?13:17, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:9, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>

      {showZones&&(
        <div style={{ background:"#f8f8f8", border:"1px solid #8b5cf630", borderRadius:12, padding:"1.25rem", marginBottom:"1.5rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#8b5cf6", marginBottom:"1rem", display:"flex", alignItems:"center", gap:6 }}><LocationIcon size={14} color="#8b5cf6"/> Delivery Zones</div>
          <form onSubmit={addZone} style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr auto", gap:8, marginBottom:"1rem", alignItems:"end" }}>
            <div><label style={{ fontSize:10, color:"#888", display:"block", marginBottom:3 }}>Zone name</label><input style={inp} value={zoneForm.name} onChange={e=>setZoneForm(f=>({...f,name:e.target.value}))} placeholder="e.g. Westlands" required/></div>
            <div><label style={{ fontSize:10, color:"#888", display:"block", marginBottom:3 }}>Base fee (KES)</label><input type="number" style={inp} value={zoneForm.base_fee} onChange={e=>setZoneForm(f=>({...f,base_fee:e.target.value}))} required/></div>
            <div><label style={{ fontSize:10, color:"#888", display:"block", marginBottom:3 }}>Per km (KES)</label><input type="number" style={inp} value={zoneForm.per_km_fee} onChange={e=>setZoneForm(f=>({...f,per_km_fee:e.target.value}))} required/></div>
            <button type="submit" style={{ background:"#8b5cf6", border:"none", borderRadius:8, color:"#fff", fontSize:12, fontWeight:700, padding:"9px 16px", cursor:"pointer", marginBottom:8 }}>Add</button>
          </form>
          <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(200px,1fr))", gap:8 }}>
            {zones.map(z=>(
              <div key={z.id} style={{ background:"#ffffff", borderRadius:8, padding:"0.75rem", border:"1px solid "+(z.is_active?"#1d9e7530":"#eeeeee"), opacity:z.is_active?1:0.6 }}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                  <div style={{ fontSize:12, fontWeight:600, color:"#000000" }}>{z.name}</div>
                  <div style={{ display:"flex", gap:8 }}>
                    {editingZoneId!==z.id&&<button onClick={()=>startEditZone(z)} style={{ background:"none", border:"none", fontSize:10, color:"#378add", cursor:"pointer" }}>Edit</button>}
                    <button onClick={()=>toggleZone(z.id,z.is_active)} style={{ background:"none", border:"none", fontSize:10, color:z.is_active?"#e24b4a":"#1d9e75", cursor:"pointer" }}>{z.is_active?"Disable":"Enable"}</button>
                  </div>
                </div>
                {editingZoneId===z.id ? (
                  <div style={{ marginTop:6 }}>
                    <div style={{ display:"flex", gap:6, marginBottom:6 }}>
                      <input type="number" style={{ ...inp, fontSize:11, padding:"5px 8px" }} value={editZoneForm.base_fee} onChange={e=>setEditZoneForm(f=>({...f,base_fee:e.target.value}))} placeholder="Base fee"/>
                      <input type="number" style={{ ...inp, fontSize:11, padding:"5px 8px" }} value={editZoneForm.per_km_fee} onChange={e=>setEditZoneForm(f=>({...f,per_km_fee:e.target.value}))} placeholder="Per km"/>
                    </div>
                    <div style={{ display:"flex", gap:6 }}>
                      <button onClick={()=>saveEditZone(z.id)} style={{ flex:1, background:"#8b5cf6", border:"none", borderRadius:6, color:"#fff", fontSize:11, fontWeight:700, padding:"6px", cursor:"pointer" }}>Save</button>
                      <button onClick={()=>setEditingZoneId(null)} style={{ flex:1, background:"none", border:"1px solid #ddd", borderRadius:6, color:"#888", fontSize:11, padding:"6px", cursor:"pointer" }}>Cancel</button>
                    </div>
                  </div>
                ) : (
                  <div style={{ fontSize:11, color:"#888", marginTop:4 }}>Base: KES {Number(z.base_fee).toLocaleString()} ┬╖ Per km: KES {Number(z.per_km_fee).toLocaleString()}</div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search by order #, customer, provider..."
        style={{ width:"100%", background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:8, padding:"9px 12px", fontSize:12, outline:"none", marginBottom:10, fontFamily:"DM Sans,sans-serif" }}/>
      <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap" }}>
        {["all","pending","confirmed","processing","ready","delivered","cancelled"].map(f=>(
          <button key={f} onClick={()=>setFilter(f)}
            style={{ padding:"5px 12px", borderRadius:7, border:"none", fontSize:11, cursor:"pointer", background:filter===f?(SC[f]||"#8b5cf6"):"#f8f8f8", color:filter===f?"#fff":"#666" }}>
            {f} ({f==="all"?orders.length:orders.filter(o=>o.status===f).length})
          </button>
        ))}
      </div>

      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
      {!loading&&filtered.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No orders found</div>}

      {filtered.map(o=>(
        <div key={o.id} style={{ background:"#f8f8f8", border:"1px solid "+(SC[o.status]||"#eeeeee")+"30", borderRadius:10, padding:"1rem", marginBottom:8 }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
            <div>
              <div style={{ fontSize:13, fontWeight:600, color:"#000000" }}>#{o.order_number}</div>
              <div style={{ fontSize:11, color:"#888", display:"flex", alignItems:"center", gap:4 }}><ProfileIcon size={10} color="#888"/> {o.profiles?.first_name} {o.profiles?.last_name}</div>
              <div style={{ fontSize:11, color:"#888", display:"flex", alignItems:"center", gap:4 }}><MarketplaceIcon size={10} color="#888"/> {o.provider?.business_name||o.provider?.first_name}</div>
              {o.delivery_driver_id&&<div style={{ fontSize:11, color:"#378add", display:"flex", alignItems:"center", gap:4 }}><DeliveryIcon size={10} color="#378add"/> Driver: {o.driver?.first_name} {o.driver?.last_name} ({o.driver?.driver_vehicle_type})</div>}
              <div style={{ fontSize:11, color:"#888", display:"flex", alignItems:"center", gap:4 }}>{o.fulfillment_type==="delivery"?<><DeliveryIcon size={10} color="#888"/> {o.delivery_address}</>:<><MarketplaceIcon size={10} color="#888"/> Pickup</>}</div>
              {o.delivery_zone&&<div style={{ fontSize:10, color:"#378add" }}>Zone: {o.delivery_zone}</div>}
              <div style={{ fontSize:10, color:"#888" }}>{new Date(o.created_at).toLocaleString()}</div>
            </div>
            <div style={{ textAlign:"right" }}>
              <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#e6821e" }}>KES {Number(o.subtotal||0).toLocaleString()}</div>
              <div style={{ fontSize:10, color:"#1d9e75" }}>Commission: KES {Number(o.platform_commission||0).toLocaleString()}</div>
              <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:(SC[o.status]||"#888")+"20", color:SC[o.status]||"#888", display:"inline-block", marginTop:4 }}>{o.status}</span>
              <div style={{ fontSize:10, color:o.payment_status==="paid"?"#1d9e75":o.payment_status==="awaiting_payment"?"#e6821e":"#888", marginTop:2, display:"flex", alignItems:"center", justifyContent:"flex-end", gap:3 }}><WalletIcon size={10} color={o.payment_status==="paid"?"#1d9e75":o.payment_status==="awaiting_payment"?"#e6821e":"#888"}/> {o.payment_status||"pending"}</div>
              <div style={{ fontSize:10, color:"#888", marginTop:2, display:"flex", alignItems:"center", justifyContent:"flex-end", gap:3 }}><WalletIcon size={10} color="#888"/> {o.payment_method==="cash"?"Cash":"Online"}</div>
            </div>
          </div>
          <div style={{ background:"#ffffff", borderRadius:8, padding:"0.6rem", marginBottom:8 }}>
            {o.order_items?.map((oi,i)=>(
              <div key={i} style={{ display:"flex", justifyContent:"space-between", fontSize:11, color:"#888", padding:"2px 0" }}>
                <span>{oi.name} ├ù {oi.quantity}</span>
                <span>KES {Number(oi.unit_price*oi.quantity).toLocaleString()}</span>
              </div>
            ))}
          </div>
          {o.status==="ready"&&o.fulfillment_type==="delivery"&&!o.delivery_driver_id&&(
            <button onClick={()=>assignDriver(o.id)} style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>
              <DeliveryIcon size={11} color="#378add"/> Assign driver
            </button>
          )}
        </div>
      ))}
    </div>
  )
}

import { GOServiceIcon, WalletIcon, WarningIcon } from "../../lib/cccIcons"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

import { useAuth } from "../../contexts/AuthContext"
export default function AdminPaymentTracking() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const isMobile = useIsMobile()
  const [bookings, setBookings] = useState([])
  const [goPayments, setGoPayments] = useState([])
  const [mpesaTransactions, setMpesaTransactions] = useState([])
  const [marketplace, setMarketplace] = useState([])
  const [loading, setLoading] = useState(true)
  const [escrowBookings, setEscrowBookings] = useState([])
  const [tab, setTab] = useState("overview")
  const [filter, setFilter] = useState("all")

  useEffect(() => { load() }, [])

  async function load() {
    // Load M-Pesa Safaricom Daraja transactions
    const { data: mpesaTxns } = await supabase.from("payment_transactions")
      .select("*, profiles(first_name,last_name)")
      .order("created_at", { ascending:false })
      .limit(100)
    setMpesaTransactions(mpesaTxns||[])
    const [{ data: bks }, { data: goPays }, { data: mkt }] = await Promise.all([
      supabase.from("bookings")
        .select("*, profiles!bookings_customer_id_fkey(first_name,last_name), provider:profiles!bookings_provider_id_fkey(first_name,last_name,business_name)")
        .order("created_at", { ascending:false })
        .limit(100),
      supabase.from("bookings")
        .select("*, profiles!bookings_customer_id_fkey(first_name,last_name), provider:profiles!bookings_provider_id_fkey(first_name,last_name,business_name)")
        .eq("is_emergency", true)
        .order("created_at", { ascending:false }),
      supabase.from("marketplace_transactions")
        .select("*, marketplace_listings(title), buyer:profiles!marketplace_transactions_buyer_id_fkey(first_name,last_name), seller:profiles!marketplace_transactions_seller_id_fkey(first_name,last_name)")
        .order("created_at", { ascending:false })
    ])
    setBookings(bks||[])
    // Load escrow bookings
    const { data: escrow } = await supabase.from("bookings")
      .select("*, profiles!bookings_customer_id_fkey(first_name,last_name), provider:profiles!bookings_provider_id_fkey(first_name,last_name,business_name)")
      .eq("payment_held", true)
      .eq("payment_released", false)
      .order("created_at", { ascending:false })
    setEscrowBookings(escrow||[])
    setGoPayments(goPays||[])
    setMarketplace(mkt||[])
    setLoading(false)
  }

  async function releasePayment(bookingId) {
    if (!confirm("Release payment to provider? Make sure service is completed.")) return
    await supabase.from("bookings").update({ payment_status:"paid", provider_paid:true }).eq("id", bookingId)
    toast.success("Payment released to provider")
    load()
  }

  async function adminReleaseEscrow(booking) {
    if(!confirm("Release escrow payment to provider? KES "+Number(booking.provider_earnings||0).toLocaleString())) return
    try {
      const resp = await fetch(import.meta.env.VITE_SUPABASE_URL+"/functions/v1/release-payment", {
        method:"POST",
        headers:{"Content-Type":"application/json","Authorization":"Bearer "+import.meta.env.VITE_SUPABASE_ANON_KEY},
        body:JSON.stringify({ booking_id:booking.id, confirmed_by:"admin" })
      })
      const data = await resp.json()
      if(data.error) throw new Error(data.error)
      toast.success("Escrow released! KES "+Number(booking.provider_earnings||0).toLocaleString()+" sent to provider")
      load()
    } catch(err) { toast.error(err.message) }
  }
  async function holdPayment(bookingId) {
    await supabase.from("bookings").update({ payment_status:"disputed" }).eq("id", bookingId)
    toast.success("Payment held ΓÇö dispute flagged")
    load()
  }

  async function releaseEscrow(txnId) {
    if (!confirm("Release escrow to seller?")) return
    await supabase.from("marketplace_transactions").update({ payment_status:"released", escrow_released:true, escrow_released_at:new Date().toISOString() }).eq("id", txnId)
    toast.success("Escrow released to seller")
    load()
  }

  // Stats
  const totalRevenue = bookings.filter(b=>b.payment_status==="paid").reduce((s,b)=>s+Number(b.platform_commission||0),0)
  const pendingRevenue = bookings.filter(b=>b.status==="completed"&&b.payment_status!=="paid").reduce((s,b)=>s+Number(b.platform_commission||0),0)
  const goRevenue = goPayments.filter(b=>b.go_callout_paid).length * 75
  const escrowTotal = marketplace.filter(m=>m.payment_status==="pending"||m.payment_status==="processing"||m.payment_status==="paid").reduce((s,m)=>s+Number(m.sale_price||0),0)
  const bookingEscrowTotal = escrowBookings.reduce((s,b)=>s+Number(b.provider_earnings||0),0)
  const autoReleaseToday = escrowBookings.filter(b=>b.auto_release_at&&new Date(b.auto_release_at)<new Date(Date.now()+24*60*60*1000)).length
  const partsRevenue = bookings.filter(b=>b.parts_approved).reduce((s,b)=>s+Number(b.parts_commission||0),0)
  const transportAllowanceDue = bookings.filter(b=>b.is_concierge&&!b.transport_allowance_paid&&b.status==="completed").length * 200
  const anticipatedRevenue = bookings.filter(b=>b.status!=="cancelled").reduce((s,b)=>s+Number(b.platform_commission||0),0)
  const mpesaCollected = mpesaTransactions.filter(t=>t.status==="completed").reduce((s,t)=>s+Number(t.amount_paid||t.amount||0),0)
  const mpesaPending = mpesaTransactions.filter(t=>t.status==="pending").length
  const mpesaFailed = mpesaTransactions.filter(t=>t.status==="failed"||t.status==="cancelled").length

  const filtered = tab==="bookings" ? (filter==="all"?bookings:bookings.filter(b=>b.payment_status===filter)) :
                   tab==="mpesa" ? mpesaTransactions :
                   tab==="marketplace" ? marketplace : []

  const SC = { paid:"#1d9e75", pending:"#e6821e", disputed:"#e24b4a", processing:"#378add", partial:"#8b5cf6" }

  return (
    <div>
      <div style={{ marginBottom:"1.25rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:"#000000" }}>Payment Tracking</div>
        <div style={{ fontSize:12, color:"#888" }}>Monitor all platform payments and revenue</div>
      </div>

      <div style={{ display:"grid", gridTemplateColumns:isMobile?"repeat(2,1fr)":"repeat(4,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Total revenue", value:"KES "+totalRevenue.toLocaleString(), color:"#1d9e75" },
          { label:"Pending release", value:"KES "+pendingRevenue.toLocaleString(), color:"#e6821e" },
          { label:"Anticipated revenue", value:"KES "+anticipatedRevenue.toLocaleString(), color:"#378add" },
          { label:"Escrow held", value:"KES "+escrowTotal.toLocaleString(), color:"#8b5cf6" },
          { label:"GO callout revenue", value:"KES "+goRevenue.toLocaleString(), color:"#e24b4a" },
          { label:"Parts revenue", value:"KES "+partsRevenue.toLocaleString(), color:"#8b5cf6" },
          { label:"Transport allowance due", value:"KES "+transportAllowanceDue.toLocaleString(), color:"#e6821e" },
          { label:"Marketplace commission", value:"KES "+marketplace.reduce((s,m)=>s+Number(m.commission||0),0).toLocaleString(), color:"#1d9e75" },
          { label:"Booking escrow held", value:"KES "+bookingEscrowTotal.toLocaleString(), color:"#8b5cf6" },
          { label:"Auto-release today", value:autoReleaseToday, color:"#e24b4a" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"1rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontSize:10, color:"#888", marginBottom:4, textTransform:"uppercase" }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:isMobile?14:18, fontWeight:800, color:s.color }}>{s.value}</div>
          </div>
        ))}
      </div>

      <div style={{ display:"flex", gap:6, marginBottom:"1.25rem", flexWrap:"wrap" }}>
        {[{k:"overview",l:"Overview"},{k:"bookings",l:"Bookings"},{k:"go",l:"GO Service"},{k:"marketplace",l:"Marketplace"},{k:"escrow",l:"Escrow ("+escrowBookings.length+")"}].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{ padding:"7px 14px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#e6821e":"#f8f8f8", color:tab===t.k?"#fff":"#666", fontFamily:"DM Sans,sans-serif", fontWeight:tab===t.k?700:400 }}>
            {t.l}
          </button>
        ))}
      </div>

      {tab==="overview"&&(
        <div>
          <div style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem", marginBottom:"1rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#000000", marginBottom:12 }}>Payment status summary</div>
            {[
              { label:"Completed & paid", count:bookings.filter(b=>b.payment_status==="paid").length, color:"#1d9e75" },
              { label:"Completed ΓÇö awaiting release", count:bookings.filter(b=>b.status==="completed"&&b.payment_status!=="paid").length, color:"#e6821e" },
              { label:"Pending bookings", count:bookings.filter(b=>b.status==="pending").length, color:"#888" },
              { label:"Disputed payments", count:bookings.filter(b=>b.payment_status==="disputed").length, color:"#e24b4a" },
              { label:"GO callout fees paid", count:goPayments.filter(b=>b.go_callout_paid).length, color:"#e24b4a" },
              { label:"Marketplace escrow active", count:marketplace.filter(m=>m.status==="pending"||m.status==="processing").length, color:"#8b5cf6" },
            ].map(s=>(
              <div key={s.label} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", padding:"10px 0", borderBottom:"1px solid #eeeeee" }}>
                <div style={{ fontSize:13, color:"#888" }}>{s.label}</div>
                <span style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:s.color }}>{s.count}</span>
              </div>
            ))}
          </div>

          <div style={{ background:"#f8f8f8", border:"1px solid #e6821e30", borderRadius:12, padding:"1.25rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#e6821e", marginBottom:12 }}>ΓÜá∩╕Å Action required</div>
