          {filtered.map(b=>(
            <div key={b.id} style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:600, color:"#000000" }}>{b.service_name}</div>
                  <div style={{ fontSize:11, color:"#888" }}>#{b.booking_number} ┬╖ {b.profiles?.first_name} {b.profiles?.last_name}</div>
                  <div style={{ fontSize:11, color:"#888" }}>Provider: {b.provider?.business_name||b.provider?.first_name}</div>
                  <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{new Date(b.created_at).toLocaleString()}</div>
                </div>
                <div style={{ textAlign:"right" }}>
                  <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:800, color:"#e6821e" }}>KES {Number(b.total_amount||0).toLocaleString()}</div>
                  <div style={{ fontSize:10, color:"#888" }}>Platform: KES {Number(b.platform_commission||0).toLocaleString()}</div>
                  <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:(SC[b.payment_status]||"#888")+"20", color:SC[b.payment_status]||"#888", display:"inline-block", marginTop:4 }}>{b.payment_status||"pending"}</span>
                </div>
              </div>
              <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:6, marginBottom:8 }}>
                {[
                  { l:"Total", v:"KES "+Number(b.total_amount||0).toLocaleString() },
                  { l:"Platform", v:"KES "+Number(b.platform_commission||0).toLocaleString() },
                  { l:"Provider", v:"KES "+Number(b.provider_earnings||0).toLocaleString() },
                  { l:"Driver", v:"KES "+Number(b.driver_earnings||0).toLocaleString() },
                  { l:"Parts", v:"KES "+Number(b.parts_cost||0).toLocaleString() },
                  { l:"Discount", v:"KES "+Number(b.discount_amount||0).toLocaleString() },
                ].map(f=>(
                  <div key={f.l} style={{ background:"#ffffff", borderRadius:6, padding:"6px 8px" }}>
                    <div style={{ fontSize:9, color:"#888", textTransform:"uppercase" }}>{f.l}</div>
                    <div style={{ fontSize:11, color:"#000000" }}>{f.v}</div>
