                ))}
              </div>
              <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginBottom:6 }}>
                <span style={{ fontSize:10, padding:"2px 8px", borderRadius:8, background:"#f5f5f5", color:b.status==="completed"?"#1d9e75":"#888" }}>Status: {b.status}</span>
                <span style={{ fontSize:10, padding:"2px 8px", borderRadius:8, background:"#f5f5f5", color:"#888" }}>Method: {b.payment_method||"ΓÇö"}</span>
                {b.is_concierge&&<span style={{ fontSize:10, padding:"2px 8px", borderRadius:8, background:"#f0fdf4", color:"#1d9e75" }}>Concierge</span>}
                {b.is_emergency&&<span style={{ fontSize:10, padding:"2px 8px", borderRadius:8, background:"#fff5f5", color:"#e24b4a" }}>Emergency</span>}
                {b.promo_code&&<span style={{ fontSize:10, padding:"2px 8px", borderRadius:8, background:"#f5f3ff", color:"#8b5cf6" }}>Promo: {b.promo_code}</span>}
                {b.parts_needed&&<span style={{ fontSize:10, padding:"2px 8px", borderRadius:8, background:"#fff8f0", color:"#e6821e" }}>Parts needed</span>}
                {b.mpesa_code&&<span style={{ fontSize:10, padding:"2px 8px", borderRadius:8, background:"#eff6ff", color:"#378add" }}>M-Pesa tracked</span>}
              </div>
              <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                {b.status==="completed"&&b.payment_status!=="paid"&&(
                  <>
                    <button onClick={()=>releasePayment(b.id)} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:6, color:"#1d9e75", fontSize:10, padding:"4px 10px", cursor:"pointer" }}>Γ£ô Release payment</button>
                    <button onClick={()=>holdPayment(b.id)} style={{ background:"none", border:"1px solid #e24b4a30", borderRadius:6, color:"#e24b4a", fontSize:10, padding:"4px 8px", cursor:"pointer" }}>Hold</button>
                  </>
                )}
                {b.parts_needed&&!b.parts_approved&&b.status!=="completed"&&(
                  <button onClick={async()=>{ await supabase.from("bookings").update({parts_approved:true}).eq("id",b.id); toast.success("Parts approved"); load() }}
                    style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:6, color:"#e6821e", fontSize:10, padding:"4px 10px", cursor:"pointer" }}>
                    Approve parts
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {tab==="go"&&(
        <div>
          {goPayments.map(b=>(
            <div key={b.id} style={{ background:"#f8f8f8", border:"1px solid #e24b4a30", borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:600, color:"#000000", display:"flex", alignItems:"center", gap:4 }}><GOServiceIcon size={13} color="#e24b4a"/> {b.emergency_type?.replace(/_/g," ")||"Emergency"}</div>
                  <div style={{ fontSize:11, color:"#888" }}>{b.profiles?.first_name} {b.profiles?.last_name}</div>
                  <div style={{ fontSize:11, color:"#888" }}>Provider: {b.provider?.business_name||b.provider?.first_name}</div>
                  <div style={{ fontSize:10, color:"#888" }}>{new Date(b.created_at).toLocaleString()}</div>
                </div>
                <div style={{ textAlign:"right" }}>
                  <div style={{ fontSize:12, color:"#e6821e", fontWeight:600 }}>Callout: KES 500</div>
                  <div style={{ fontSize:10, color:"#888" }}>Service: KES {Number(b.total_amount||0).toLocaleString()}</div>
                  <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:b.go_callout_paid?"#f0fdf4":"#fff5f5", color:b.go_callout_paid?"#1d9e75":"#e24b4a", display:"inline-block", marginTop:4 }}>
                    Callout: {b.go_callout_paid?"Paid":"Unpaid"}
                  </span>
                </div>
              </div>
            </div>
          ))}
          {goPayments.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"3rem" }}>No GO service payments yet</div>}
        </div>
      )}

      {tab==="marketplace"&&(
        <div>
          {marketplace.map(m=>(
            <div key={m.id} style={{ background:"#f8f8f8", border:"1px solid #8b5cf630", borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:600, color:"#000000" }}>{m.marketplace_listings?.title||"Listing"}</div>
                  <div style={{ fontSize:11, color:"#888" }}>Buyer: {m.buyer?.first_name} {m.buyer?.last_name}</div>
                  <div style={{ fontSize:11, color:"#888" }}>Seller: {m.seller?.first_name} {m.seller?.last_name}</div>
                  <div style={{ fontSize:10, color:"#888" }}>{new Date(m.created_at).toLocaleString()}</div>
                </div>
                <div style={{ textAlign:"right" }}>
                  <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:800, color:"#e6821e" }}>KES {Number(m.amount||0).toLocaleString()}</div>
                  <div style={{ fontSize:10, color:"#888" }}>Commission: KES {Number(m.commission||0).toLocaleString()}</div>
                  <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:(SC[m.status]||"#888")+"20", color:SC[m.status]||"#888", display:"inline-block", marginTop:4 }}>{m.status}</span>
                </div>
              </div>
              {(m.status==="pending"||m.status==="processing")&&(
                <button onClick={()=>releaseEscrow(m.id)} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>
                  ≡ƒöô Release escrow to seller
                </button>
              )}
            </div>
          ))}
          {marketplace.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"3rem" }}>No marketplace transactions yet</div>}
        </div>
      )}
    </div>
  )
}

import { WalletIcon, WarningIcon, CheckIcon } from "../../lib/cccIcons"
import useIsMobile from "../../lib/useIsMobile"
import { useAuth } from "../../contexts/AuthContext"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import toast from "react-hot-toast"
import { sendPayoutProcessed } from "../../lib/email"

export default function AdminPayouts() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const isMobile = useIsMobile()
  const [payouts, setPayouts] = useState([])
  const [filter, setFilter] = useState("pending")
  const [loading, setLoading] = useState(true)
  const [goPartsRequests, setGoPartsRequests] = useState([])
  const [note, setNote] = useState({})
  const [selected, setSelected] = useState([])
  const [walletBalance, setWalletBalance] = useState(null)
  const [failedPayouts, setFailedPayouts] = useState([])
  const [totalCommission, setTotalCommission] = useState(0)
  const [withdrawing, setWithdrawing] = useState(false)

  useEffect(() => {
    loadWalletData()
    supabase.from("go_parts_requests").select("*, inventory(name,price), mechanic:profiles!go_parts_requests_mechanic_id_fkey(first_name,last_name), parts_provider:profiles!go_parts_requests_provider_id_fkey(first_name,last_name,business_name)").order("created_at",{ascending:false}).limit(20).then(({data})=>setGoPartsRequests(data||[]))
  }, [])

  async function loadWalletData() {
    try {
      // Get total commission from the real, already-correctly-calculated platform_commission
      // field on each booking, instead of assuming a blanket 10% rate (rates actually vary by
      // service category and can be customized per-booking)
      const { data: bks } = await supabase
        .from("bookings")
        .select("platform_commission")
        .eq("payment_status", "paid")

      if(bks) {
        const total = bks.reduce((sum, b) => sum + Number(b.platform_commission||0), 0)
        setTotalCommission(Math.floor(total))
      }

      // Get failed payouts
      const { data: failed } = await supabase
        .from("payment_transactions")
        .select("*, profiles!payment_transactions_provider_id_fkey(first_name,last_name)")
        .eq("status", "failed")
        .eq("type", "payout")
        .order("created_at", { ascending:false })
      
      setFailedPayouts(failed||[])
    } catch(e) { console.error(e) }
  }

  async function retryPayout(txn) {
    try {
      const { data } = await supabase.functions.invoke("daraja-b2c-payout", {
        body: {
          booking_id: txn.booking_id,
          provider_id: txn.provider_id,
          amount: txn.amount,
          phone: txn.phone,
          narrative: "Retry payout - CCC"
        }
      })
      if(data?.success) {
        toast.success("Payout retry initiated!")
        loadWalletData()
      }
    } catch(e) { toast.error(e.message) }
  }

  useEffect(() => {
    load()
    const sub = supabase.channel("admin-payouts")
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"payout_requests" }, () => { load(); toast("New payout request", { icon:"≡ƒÅª" }) })
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [])

  async function load() {
    const { data } = await supabase.from("payout_requests")
      .select("*, profile_public!payout_requests_user_id_fkey(first_name,last_name,business_name,role)")
      .order("created_at",{ascending:false})
    // Enrich with sensitive data for payment processing
    if (data?.length) {
      const ids = [...new Set(data.map(p=>p.user_id))]
      const { data: sens } = await supabase.from("profile_sensitive").select("id,phone,mpesa_number,id_number,kra_pin").in("id", ids)
      const sensMap = {}
      sens?.forEach(s => { sensMap[s.id] = s })
      data.forEach(p => { Object.assign(p, sensMap[p.user_id]||{}) })
    }
    setPayouts(data||[])
    setLoading(false)
  }

  async function updatePayout(id, status) {
    const { error } = await supabase.from("payout_requests").update({ status, admin_note:note[id]||null, updated_at:new Date().toISOString() }).eq("id",id)
    if (error) return toast.error(error.message)
    const payout = payouts.find(p=>p.id===id)
    if (payout) {
      const titles = {
        paid: "Money sent! ≡ƒÆ╕",
        approved: "Payout approved Γ£à",
        rejected: "Payout request declined",
      }
      const messages = {
        paid: `KES ${Number(payout.amount).toLocaleString()} has been sent your way. Check your account!`,
        approved: `Your payout of KES ${Number(payout.amount).toLocaleString()} has been approved and is being processed.`,
        rejected: `Your payout request of KES ${Number(payout.amount).toLocaleString()} was declined.${note[id]?" Reason: "+note[id]:""}`,
      }
      await supabase.from("notifications").insert({
        user_id: payout.user_id,
        title: titles[status] || `Payout ${status}`,
        message: messages[status] || `Your payout of KES ${Number(payout.amount).toLocaleString()} has been ${status}`,
        type: status==="paid"?"success":status==="approved"?"info":"error"
      })
    }
    toast.success(`Payout ${status}`)
    if (status === "paid" && payout) {
      const { data: sens } = await supabase.from("profile_sensitive").select("email").eq("id", payout.user_id).single()
      if (sens?.email) await sendPayoutProcessed(sens.email, payout)
    }
    load()
  }

  async function bulkApprove() {
    if (selected.length===0) return toast.error("Select payouts first")
    for (const id of selected) {
      await supabase.from("payout_requests").update({ status:"approved", updated_at:new Date().toISOString() }).eq("id",id)
      const payout = payouts.find(p=>p.id===id)
      if (payout) await supabase.from("notifications").insert({ user_id:payout.user_id, title:"Payout approved Γ£à", message:`Your payout of KES ${Number(payout.amount).toLocaleString()} has been approved and is being processed.`, type:"info" })
    }
    toast.success(`${selected.length} payouts approved`)
    setSelected([])
    load()
  }

  async function bulkMarkPaid() {
    if (selected.length===0) return toast.error("Select payouts first")
    for (const id of selected) {
      await supabase.from("payout_requests").update({ status:"paid", updated_at:new Date().toISOString() }).eq("id",id)
      const payout = payouts.find(p=>p.id===id)
      if (payout) {
        await supabase.from("notifications").insert({ user_id:payout.user_id, title:"Money sent! ≡ƒÆ╕", message:`KES ${Number(payout.amount).toLocaleString()} has been sent your way. Check your account!`, type:"success" })
        const { data: sens } = await supabase.from("profile_sensitive").select("email").eq("id", payout.user_id).single()
        if (sens?.email) await sendPayoutProcessed(sens.email, payout)
      }
    }
    toast.success(`${selected.length} payouts marked as paid`)
    setSelected([])
    load()
  }

  function toggleSelect(id) {
    setSelected(s => s.includes(id) ? s.filter(x=>x!==id) : [...s,id])
  }

  function selectAll() {
    const ids = filtered.map(p=>p.id)
    setSelected(s => s.length===ids.length ? [] : ids)
  }

  const filtered = filter==="all" ? payouts : payouts.filter(p=>p.status===filter)
  const RC = { pending:"#e6821e", approved:"#378add", paid:"#1d9e75", rejected:"#e24b4a" }
  const roleColor = { provider:"#378add", driver:"#1d9e75" }

  return (
    <div>
      {/* Daraja Commission Wallet */}
      <div style={{ background:"linear-gradient(135deg,#e6821e15,#fff8f0)", border:"1px solid #e6821e30", borderRadius:12, padding:"1.25rem", marginBottom:"1.5rem" }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:12 }}>
          <div>
            <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:700 }}>Daraja Commission Wallet</div>
            <div style={{ fontSize:12, color:"#888" }}>CCC earnings from completed bookings</div>
          </div>
          <a href="https://payment.daraja.com" target="_blank" rel="noreferrer"
            style={{ background:"#e6821e", border:"none", borderRadius:8, color:"#fff", fontSize:12, fontWeight:700, padding:"8px 14px", textDecoration:"none", cursor:"pointer" }}>
            Open Daraja
          </a>
        </div>
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10 }}>
          <div style={{ background:"#fff", borderRadius:8, padding:"0.75rem", border:"1px solid #e6821e20" }}>
            <div style={{ fontSize:11, color:"#888", marginBottom:4 }}>Total Commission Earned</div>
            <div style={{ fontFamily:"Syne", fontSize:20, fontWeight:800, color:"#e6821e" }}>KES {totalCommission.toLocaleString()}</div>
          </div>
          <div style={{ background:"#fff", borderRadius:8, padding:"0.75rem", border:"1px solid #e6821e20" }}>
            <div style={{ fontSize:11, color:"#888", marginBottom:4 }}>Failed Payouts</div>
            <div style={{ fontFamily:"Syne", fontSize:20, fontWeight:800, color:failedPayouts.length>0?"#e24b4a":"#1d9e75" }}>{failedPayouts.length}</div>
          </div>
        </div>
        {failedPayouts.length>0&&(
          <div style={{ marginTop:12 }}>
            <div style={{ fontSize:12, fontWeight:700, color:"#e24b4a", marginBottom:8 }}>Failed Payouts ΓÇö Retry Required</div>
            {failedPayouts.map(f=>(
              <div key={f.id} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", background:"#fff5f5", border:"1px solid #e24b4a20", borderRadius:8, padding:"8px 12px", marginBottom:6 }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:600 }}>{f.profiles?.first_name} {f.profiles?.last_name}</div>
                  <div style={{ fontSize:11, color:"#888" }}>KES {Number(f.amount).toLocaleString()} ┬╖ {f.phone}</div>
                </div>
                <button onClick={()=>retryPayout(f)}
                  style={{ background:"#e6821e", border:"none", borderRadius:6, color:"#fff", fontSize:11, fontWeight:700, padding:"6px 12px", cursor:"pointer" }}>
                  Retry
                </button>
              </div>
            ))}
          </div>
        )}
      {goPartsRequests.length>0&&(
        <div style={{ background:"#f3f0ff", border:"1px solid #8b5cf640", borderRadius:12, padding:"1.25rem", marginBottom:"1.5rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#8b5cf6", marginBottom:10 }}>≡ƒöº GO Service Parts Requests</div>
          {goPartsRequests.map(r=>(
            <div key={r.id} style={{ background:"#fff", borderRadius:10, padding:"0.75rem", marginBottom:8, display:"flex", justifyContent:"space-between", alignItems:"center" }}>
              <div>
                <div style={{ fontSize:12, fontWeight:600 }}>{r.inventory?.name} x{r.quantity}</div>
                <div style={{ fontSize:11, color:"#888" }}>Mechanic: {r.mechanic?.first_name} {r.mechanic?.last_name}</div>
                <div style={{ fontSize:11, color:"#888" }}>Supplier: {r.parts_provider?.business_name||r.parts_provider?.first_name}</div>
                <div style={{ fontSize:11, color:"#e6821e", fontWeight:600 }}>KES {Number(r.total_amount).toLocaleString()}</div>
              </div>
              <span style={{ fontSize:10, padding:"3px 10px", borderRadius:8, background:r.status==="delivered"?"#f0fdf4":r.status==="accepted"?"#eff6ff":"#fff8f0", color:r.status==="delivered"?"#1d9e75":r.status==="accepted"?"#378add":"#e6821e", fontWeight:600 }}>{r.status}</span>
            </div>
          ))}
        </div>
      )}
      </div>
      <div style={{ display:"grid", gridTemplateColumns:isMobile?"repeat(2,1fr)":"repeat(4,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Pending", value:payouts.filter(p=>p.status==="pending").length, color:"#e6821e" },
          { label:"Approved", value:payouts.filter(p=>p.status==="approved").length, color:"#378add" },
          { label:"Total paid", value:`KES ${payouts.filter(p=>p.status==="paid").reduce((s,p)=>s+Number(p.amount),0).toLocaleString()}`, color:"#1d9e75" },
          { label:"Total requested", value:`KES ${payouts.reduce((s,p)=>s+Number(p.amount),0).toLocaleString()}` },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"1rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontSize:11, color:"#888", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:6 }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:20, fontWeight:800, color:s.color||"#000000" }}>{s.value}</div>
          </div>
        ))}
      </div>

      <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap", alignItems:"center" }}>
        {[{k:"pending",l:"Pending"},{k:"approved",l:"Approved"},{k:"paid",l:"Paid"},{k:"rejected",l:"Rejected"},{k:"all",l:"All"}].map(t=>(
          <button key={t.k} onClick={()=>{ setFilter(t.k); setSelected([]) }}
            style={{ padding:"6px 14px", borderRadius:6, border:"none", fontSize:12, cursor:"pointer", background:filter===t.k?"#e6821e":"#f8f8f8", color:filter===t.k?"#fff":"#666", fontFamily:"'DM Sans',sans-serif" }}>
            {t.l}
          </button>
        ))}
        {filtered.length>0&&<>
          <button onClick={selectAll} style={{ padding:"6px 14px", borderRadius:6, border:"1px solid #dddddd", fontSize:12, cursor:"pointer", background:"none", color:"#888", fontFamily:"'DM Sans',sans-serif" }}>
            {selected.length===filtered.length?"Deselect all":"Select all"}
          </button>
          {selected.length>0&&<>
            <button onClick={bulkApprove} style={{ padding:"6px 14px", borderRadius:6, border:"1px solid #378add40", fontSize:12, cursor:"pointer", background:"#eff6ff", color:"#378add", fontFamily:"'DM Sans',sans-serif" }}>
              Approve {selected.length}
            </button>
            <button onClick={bulkMarkPaid} style={{ padding:"6px 14px", borderRadius:6, border:"1px solid #1d9e7540", fontSize:12, cursor:"pointer", background:"#f0fdf4", color:"#1d9e75", fontFamily:"'DM Sans',sans-serif" }}>
              Mark paid {selected.length}
            </button>
          </>}
        </>}
      </div>

      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
      {!loading&&filtered.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No payout requests</div>}

      {filtered.map(p=>(
        <div key={p.id} style={{ background:"#f8f8f8", border:`1px solid ${selected.includes(p.id)?"#e6821e40":p.status==="pending"?"#e6821e20":"#eeeeee"}`, borderRadius:10, padding:"1rem", marginBottom:10 }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
            <div style={{ display:"flex", alignItems:"flex-start", gap:10 }}>
              <input type="checkbox" checked={selected.includes(p.id)} onChange={()=>toggleSelect(p.id)} style={{ marginTop:3, cursor:"pointer" }}/>
              <div>
                <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:2 }}>
                  <div style={{ fontSize:14, fontWeight:500, color:"#000000" }}>KES {Number(p.amount).toLocaleString()}</div>
                  <span style={{ fontSize:10, padding:"2px 7px", borderRadius:10, background:`${roleColor[p.profile_public?.role]||"#cccccc"}20`, color:roleColor[p.profile_public?.role]||"#888" }}>
                    {p.profile_public?.role}
                  </span>
                </div>
                <div style={{ fontSize:12, color:"#888" }}>
                  {p.profile_public?.business_name||`${p.profile_public?.first_name} ${p.profile_public?.last_name}`}
                </div>
                <div style={{ fontSize:11, color:"#888", marginTop:2 }}>
                  ≡ƒÅª {p.bank_name} ┬╖ {p.bank_account_name} ┬╖ {p.bank_account_number}
                </div>
                {p.mpesa_number&&<div style={{ fontSize:11, color:"#1d9e75", marginTop:2 }}>≡ƒô▒ M-Pesa: {p.mpesa_number}</div>}
                {p.id_number&&<div style={{ fontSize:11, color:"#888", marginTop:2 }}>≡ƒ¬¬ ID: {p.id_number}</div>}
                {p.kra_pin&&<div style={{ fontSize:11, color:"#888", marginTop:2 }}>≡ƒôï KRA PIN: {p.kra_pin}</div>}
                <div style={{ fontSize:10, color:"#888" }}>{new Date(p.created_at).toLocaleDateString()}</div>
              </div>
            </div>
            <span style={{ fontSize:11, padding:"3px 9px", borderRadius:20, background:`${RC[p.status]}20`, color:RC[p.status], border:`1px solid ${RC[p.status]}40`, flexShrink:0 }}>
              {p.status}
            </span>
          </div>

          {p.status==="pending"&&(
            <div>
              <input placeholder="Admin note (optional)" value={note[p.id]||""} onChange={e=>setNote(n=>({...n,[p.id]:e.target.value}))}
                style={{ width:"100%", background:"#ffffff", border:"1px solid #f0f0f0", borderRadius:7, padding:"8px 10px", color:"#000000", fontSize:12, outline:"none", fontFamily:"'DM Sans',sans-serif", marginBottom:8 }}/>
              <div style={{ display:"flex", gap:8 }}>
                <button onClick={()=>updatePayout(p.id,"approved")} style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:12, padding:"6px 14px", cursor:"pointer" }}>Approve</button>
                <button onClick={()=>updatePayout(p.id,"rejected")} style={{ background:"none", border:"1px solid #e24b4a40", borderRadius:7, color:"#e24b4a", fontSize:12, padding:"6px 14px", cursor:"pointer" }}>Reject</button>
              </div>
            </div>
          )}
          {p.status==="approved"&&(
            <div style={{ display:"flex", gap:8, alignItems:"center" }}>
              <input placeholder="Payment reference (optional)" value={note[p.id]||""} onChange={e=>setNote(n=>({...n,[p.id]:e.target.value}))}
                style={{ flex:1, background:"#ffffff", border:"1px solid #f0f0f0", borderRadius:7, padding:"8px 10px", color:"#000000", fontSize:12, outline:"none", fontFamily:"'DM Sans',sans-serif" }}/>
              <button onClick={()=>updatePayout(p.id,"paid")} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:12, padding:"6px 14px", cursor:"pointer", whiteSpace:"nowrap" }}>Mark paid</button>
            </div>
          )}
          {p.admin_note&&<div style={{ fontSize:11, color:"#888", marginTop:8, fontStyle:"italic" }}>Note: &quot;{p.admin_note}&quot;</div>}
        </div>
      ))}
    </div>
  )
}

import { ClockIcon, CloseIcon, WarningIcon, ShieldIcon, StarIcon, ServicesIcon } from "../../lib/cccIcons"
import { useState, useEffect } from "react"
import { useAuth } from "../../contexts/AuthContext"
import { supabase } from "../../lib/supabase"
import toast from "react-hot-toast"

const VIOLATION_TYPES = [
  { key:"no_show",      label:"No Show",                icon:"≡ƒòÉ", color:"#e6821e" },
  { key:"cancellation", label:"Repeated Cancellation",  icon:"Γ¥î", color:"#378add" },
  { key:"abuse",        label:"Abusive Behavior",       icon:"≡ƒÜ½", color:"#e24b4a" },
  { key:"false_claim",  label:"False Claim",            icon:"ΓÜá∩╕Å", color:"#8b5cf6" },
  { key:"fraud",        label:"Fraud / Scam",           icon:"≡ƒö┤", color:"#e24b4a" },
  { key:"other",        label:"Other",                  icon:"≡ƒôï", color:"#888888" },
]

const PENALTY_RULES = {
  1: { type:"warning",       label:"Warning",       icon:"ΓÜá∩╕Å", color:"#e6821e", bg:"#fff8f0" },
  2: { type:"suspension",    label:"Suspension",    icon:"ΓÅ╕∩╕Å", color:"#378add", bg:"#eff6ff" },
  3: { type:"permanent_ban", label:"Permanent Ban", icon:"≡ƒÜ½", color:"#e24b4a", bg:"#fff5f5" },
}

const ROLE_COLORS = { customer:"#e6821e", provider:"#378add", driver:"#1d9e75", admin:"#8b5cf6" }

function Badge({ label, color, bg, icon }) {
  return (
    <span style={{ background:bg||color+"15", color, padding:"3px 10px", borderRadius:20, fontSize:11, fontWeight:600, display:"inline-flex", alignItems:"center", gap:4 }}>
      {icon&&<span>{icon}</span>}{label}
    </span>
  )
}

export default function AdminPenalties() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const [users, setUsers] = useState([])
  const [violations, setViolations] = useState([])
  const [penalties, setPenalties] = useState([])
  const [claimPenalties, setClaimPenalties] = useState([])
  const [loading, setLoading] = useState(true)
  const [tab, setTab] = useState("overview")
  const [showForm, setShowForm] = useState(false)
  const [search, setSearch] = useState("")
  const [searchResults, setSearchResults] = useState([])
  const [selectedUser, setSelectedUser] = useState(null)
  const [form, setForm] = useState({ user_id:"", role:"", violation_type:"no_show", description:"" })
  const [suspendHours, setSuspendHours] = useState(24)

  useEffect(() => { load() }, [])
  useEffect(() => {
    if (search.length > 1) {
      const results = users.filter(u => `${u.first_name} ${u.last_name} ${u.role}`.toLowerCase().includes(search.toLowerCase()))
      setSearchResults(results.slice(0,6))
    } else {
      setSearchResults([])
    }
  }, [search, users])

  async function load() {
    setLoading(true)
    const [{ data: v }, { data: p }, { data: cp }, { data: u }] = await Promise.all([
      supabase.from("user_violations").select("*, profiles!user_id(first_name,last_name,role)").order("created_at",{ascending:false}),
      supabase.from("provider_penalties").select("*, profiles!provider_id(first_name,last_name,business_name), service_claims(reason,booking_id)").order("created_at",{ascending:false}),
      supabase.from("provider_penalties").select("*, provider:profiles!provider_id(first_name,last_name,business_name), claim:service_claims(reason,booking_id)").order("created_at",{ascending:false}),
      supabase.from("user_penalties").select("*, profiles!user_id(first_name,last_name,role)").order("created_at",{ascending:false}),
      supabase.from("profiles").select("id,first_name,last_name,role,is_suspended,is_banned,violation_count,warning_count,suspension_expires_at").neq("role","admin").order("first_name"),
    ])
    setViolations(v||[])
    setPenalties(p||[])
    setClaimPenalties(cp||[])
    setUsers(u||[])
    setLoading(false)
  }

  async function submitViolation() {
    if (!form.user_id) return toast.error("Please select a user")
    if (!form.description.trim()) return toast.error("Please provide a description")
    const { data: profile } = await supabase.from("profiles").select("violation_count,warning_count,role").eq("id", form.user_id).single()
    const currentCount = (profile?.violation_count||0) + 1
    const penaltyLevel = Math.min(currentCount, 3)
    const penalty = PENALTY_RULES[penaltyLevel]
    const { data: violation, error: vErr } = await supabase.from("user_violations").insert({
      user_id: form.user_id, role: form.role||profile?.role,
      violation_type: form.violation_type, description: form.description,
    }).select().single()
    if (vErr) return toast.error(vErr.message)
    const suspExpiry = penalty.type==="suspension" ? new Date(Date.now()+suspendHours*3600000).toISOString() : null
    await supabase.from("user_penalties").insert({
      user_id: form.user_id, role: form.role||profile?.role,
      penalty_level: penaltyLevel, penalty_type: penalty.type,
      reason: form.description, violation_id: violation.id,
      suspension_hours: penalty.type==="suspension"?suspendHours:null,
      suspension_expires_at: suspExpiry, is_active: true,
    })
    await supabase.from("profiles").update({
      violation_count: currentCount,
      is_suspended: penalty.type==="suspension",
      is_banned: penalty.type==="permanent_ban",
      suspension_expires_at: suspExpiry,
      warning_count: penalty.type==="warning"?(profile?.warning_count||0)+1:profile?.warning_count||0,
    }).eq("id", form.user_id)
    if ((form.role||profile?.role)==="driver") {
      await supabase.from("driver_status").upsert({
        driver_id: form.user_id,
        is_suspended: penalty.type==="suspension"||penalty.type==="permanent_ban",
        suspension_expires_at: suspExpiry,
      }, { onConflict:"driver_id" })
    }
    await supabase.from("notifications").insert({
      user_id: form.user_id,
      title: `Account ${penalty.label}`,
      message: penalty.type==="warning"
        ? `Warning issued: ${form.description}. Further violations will result in suspension.`
        : penalty.type==="suspension"
        ? `Your account has been suspended for ${suspendHours} hours: ${form.description}`
        : `Your account has been permanently banned: ${form.description}. Contact support to appeal.`,
      type: penalty.type==="warning"?"warning":"error",
    })
    toast.success(`${penalty.label} issued!`)
    setShowForm(false)
    setForm({ user_id:"", role:"", violation_type:"no_show", description:"" })
    setSelectedUser(null)
    setSearch("")
    load()
  }

  async function removeRestriction(userId, userName) {
    if (!confirm(`Remove all restrictions from ${userName}?`)) return
    await supabase.from("profiles").update({ is_suspended:false, is_banned:false, suspension_expires_at:null }).eq("id", userId)
    await supabase.from("driver_status").update({ is_suspended:false, suspension_expires_at:null }).eq("driver_id", userId)
    await supabase.from("user_penalties").update({ is_active:false }).eq("user_id", userId).eq("is_active", true)
    await supabase.from("notifications").insert({
      user_id: userId, title:"Account restriction removed",
      message:"Your account restriction has been lifted. You can now use the platform normally.", type:"success",
    })
    toast.success("Restriction removed")
    load()
  }

  const activePenalties = penalties.filter(p=>p.is_active)
  const suspendedUsers = users.filter(u=>u.is_suspended||u.is_banned)
  const recentViolations = violations.slice(0,5)

  const inp = { width:"100%", border:"1px solid #e5e5e5", borderRadius:10, padding:"10px 12px", fontSize:13, outline:"none", fontFamily:"DM Sans,sans-serif", background:"#fafafa" }

  return (
    <div style={{ fontFamily:"DM Sans,sans-serif" }}>
      {/* Header */}
      <div style={{ background:"#e24b4a", borderRadius:16, padding:"1.5rem", marginBottom:"1.5rem", display:"flex", justifyContent:"space-between", alignItems:"center" }}>
        <div>
          <div style={{ fontFamily:"Syne", fontSize:22, fontWeight:800, color:"#fff" }}>Penalties & Violations</div>
          <div style={{ fontSize:13, color:"rgba(255,255,255,0.8)", marginTop:2 }}>Manage user violations and enforce platform policies</div>
        </div>
        <button onClick={()=>setShowForm(!showForm)}
          style={{ background:"#fff", border:"none", borderRadius:10, color:"#e24b4a", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"10px 20px", cursor:"pointer" }}>
          {showForm?"Γ£ò Cancel":"+ Issue Violation"}
        </button>
      </div>

      {/* Stats */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(140px,1fr))", gap:12, marginBottom:"1.5rem" }}>
        {[
          { label:"Total violations", value:violations.length, color:"#e6821e", icon:"ΓÜá∩╕Å", bg:"#fff8f0" },
          { label:"Active penalties", value:activePenalties.length, color:"#e24b4a", icon:"≡ƒÜ½", bg:"#fff5f5" },
          { label:"Suspended", value:suspendedUsers.filter(u=>u.is_suspended&&!u.is_banned).length, color:"#378add", icon:"ΓÅ╕∩╕Å", bg:"#eff6ff" },
          { label:"Banned", value:suspendedUsers.filter(u=>u.is_banned).length, color:"#e24b4a", icon:"Γ¥î", bg:"#fff5f5" },
        ].map(s=>(
          <div key={s.label} style={{ background:s.bg, border:`1px solid ${s.color}20`, borderRadius:14, padding:"1rem" }}>
            <div style={{ fontSize:28, marginBottom:6 }}>{s.icon}</div>
            <div style={{ fontFamily:"Syne", fontSize:26, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:12, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>

      {/* Issue violation form */}
      {showForm&&(
        <div style={{ background:"#fff", border:"2px solid #e24b4a20", borderRadius:16, padding:"1.5rem", marginBottom:"1.5rem", boxShadow:"0 4px 20px rgba(226,75,74,0.08)" }}>
          <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, marginBottom:"1.25rem", display:"flex", alignItems:"center", gap:8 }}>
            <span style={{ background:"#e24b4a", color:"#fff", borderRadius:8, padding:"4px 10px", fontSize:13 }}>New Violation</span>
            <span style={{ color:"#888", fontSize:13, fontWeight:400 }}>System will auto-assign penalty based on violation count</span>
          </div>

          {/* User search */}
          <div style={{ marginBottom:14, position:"relative" }}>
            <label style={{ fontSize:12, color:"#888", display:"block", marginBottom:4, fontWeight:600 }}>Search & Select User *</label>
            <input value={search} onChange={e=>{ setSearch(e.target.value); if(!e.target.value){setSelectedUser(null);setForm(f=>({...f,user_id:"",role:""}))}} }
              placeholder="Type name or role to search..."
              style={{ ...inp, border:selectedUser?"1px solid #1d9e75":"1px solid #e5e5e5" }}/>
            {selectedUser&&(
              <div style={{ position:"absolute", right:10, top:32, color:"#1d9e75", fontSize:13 }}>Γ£ô Selected</div>
            )}
            {searchResults.length>0&&!selectedUser&&(
              <div style={{ position:"absolute", top:"100%", left:0, right:0, background:"#fff", border:"1px solid #eee", borderRadius:10, boxShadow:"0 8px 24px rgba(0,0,0,0.1)", zIndex:10, overflow:"hidden" }}>
                {searchResults.map(u=>(
                  <div key={u.id} onClick={()=>{ setSelectedUser(u); setForm(f=>({...f,user_id:u.id,role:u.role})); setSearch(`${u.first_name} ${u.last_name}`); setSearchResults([]) }}
                    style={{ padding:"10px 14px", cursor:"pointer", display:"flex", justifyContent:"space-between", alignItems:"center", borderBottom:"1px solid #f5f5f5" }}
                    onMouseEnter={e=>e.currentTarget.style.background="#f8f8f8"}
                    onMouseLeave={e=>e.currentTarget.style.background="#fff"}>
                    <div>
                      <div style={{ fontSize:13, fontWeight:600, color:"#000000" }}>{u.first_name} {u.last_name}</div>
                      <div style={{ fontSize:11, color:"#888" }}>{u.violation_count||0} violations ┬╖ {u.warning_count||0} warnings</div>
                    </div>
                    <Badge label={u.role} color={ROLE_COLORS[u.role]||"#888"}/>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Selected user preview */}
          {selectedUser&&(
            <div style={{ background:"#f8f8f8", borderRadius:10, padding:"0.85rem 1rem", marginBottom:14, display:"flex", justifyContent:"space-between", alignItems:"center" }}>
              <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                <div style={{ width:36, height:36, borderRadius:8, background:ROLE_COLORS[selectedUser.role]||"#e6821e", display:"flex", alignItems:"center", justifyContent:"center", color:"#fff", fontFamily:"Syne", fontWeight:800, fontSize:14 }}>
                  {selectedUser.first_name[0]}{selectedUser.last_name[0]}
                </div>
                <div>
                  <div style={{ fontSize:13, fontWeight:600, color:"#ffffff" }}>{selectedUser.first_name} {selectedUser.last_name}</div>
                  <div style={{ fontSize:11, color:"#888" }}>{selectedUser.role} ┬╖ {selectedUser.violation_count||0} past violations</div>
                </div>
              </div>
              {(() => {
                const count = (selectedUser.violation_count||0) + 1
                const level = Math.min(count, 3)
                const p = PENALTY_RULES[level]
                return (
                  <div style={{ textAlign:"right" }}>
                    <div style={{ fontSize:11, color:"#888", marginBottom:2 }}>This violation will trigger:</div>
                    <Badge label={p.label} color={p.color} icon={p.icon} bg={p.bg}/>
                  </div>
                )
              })()}
            </div>
          )}

          <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(280px,1fr))", gap:12, marginBottom:14 }}>
            <div>
              <label style={{ fontSize:12, color:"#888", display:"block", marginBottom:4, fontWeight:600 }}>Violation Type *</label>
              <select value={form.violation_type} onChange={e=>setForm(f=>({...f,violation_type:e.target.value}))} style={inp}>
                {VIOLATION_TYPES.map(v=>(<option key={v.key} value={v.key}>{v.icon} {v.label}</option>))}
              </select>
            </div>
            <div>
              <label style={{ fontSize:12, color:"#888", display:"block", marginBottom:4, fontWeight:600 }}>Suspension duration (if 2nd offense)</label>
              <select value={suspendHours} onChange={e=>setSuspendHours(Number(e.target.value))} style={inp}>
                <option value={24}>24 hours</option>
                <option value={48}>48 hours</option>
                <option value={72}>72 hours (3 days)</option>
                <option value={168}>7 days</option>
                <option value={336}>14 days</option>
                <option value={720}>30 days</option>
              </select>
            </div>
          </div>

          <div style={{ marginBottom:16 }}>
            <label style={{ fontSize:12, color:"#888", display:"block", marginBottom:4, fontWeight:600 }}>Description / Evidence *</label>
            <textarea value={form.description} onChange={e=>setForm(f=>({...f,description:e.target.value}))}
              placeholder="Describe the violation clearly. This will be sent to the user and kept on record..."
              style={{ ...inp, height:80, resize:"vertical" }}/>
          </div>

          <div style={{ display:"flex", gap:10 }}>
            <button onClick={submitViolation}
              style={{ background:"#e24b4a", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px 24px", cursor:"pointer" }}>
              Issue Violation & Apply Penalty
            </button>
            <button onClick={()=>{ setShowForm(false); setSearch(""); setSelectedUser(null) }}
              style={{ background:"#f5f5f5", border:"none", borderRadius:10, color:"#888", fontSize:13, padding:"11px 18px", cursor:"pointer" }}>
              Cancel
            </button>
          </div>
        </div>
      )}

      {/* Tabs */}
      <div style={{ display:"flex", gap:8, marginBottom:"1.25rem", overflowX:"auto", paddingBottom:4, WebkitOverflowScrolling:"touch" }}>
        {[
          { k:"overview", l:"Overview" },
          { k:"violations", l:`Violations (${violations.length})` },
          { k:"penalties", l:`Active Penalties (${activePenalties.length})` },
    { k:"claim_penalties", l:`Claim Penalties (${claimPenalties.length})` },
          { k:"restricted", l:`Restricted Users (${suspendedUsers.length})` },
        ].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{ padding:"8px 14px", borderRadius:20, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#e24b4a":"#f0f0f0", color:tab===t.k?"#fff":"#555", fontWeight:tab===t.k?700:400, whiteSpace:"nowrap", flexShrink:0 }}>
            {t.l}
          </button>
        ))}
      </div>

      {loading&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>Loading...</div>}

      {/* OVERVIEW TAB */}
      {tab==="overview"&&!loading&&(
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:16 }}>
          {/* Recent violations */}
          <div style={{ background:"#fff", border:"1px solid #eee", borderRadius:14, padding:"1rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, marginBottom:"1rem", display:"flex", justifyContent:"space-between" }}>
              Recent Violations
              <button onClick={()=>setTab("violations")} style={{ background:"none", border:"none", color:"#e6821e", fontSize:12, cursor:"pointer" }}>View all ΓåÆ</button>
            </div>
            {recentViolations.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"1rem" }}>No violations yet</div>}
            {recentViolations.map(v=>(
              <div key={v.id} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", padding:"8px 0", borderBottom:"0.5px solid #f5f5f5" }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:500 }}>{v.profiles?.first_name} {v.profiles?.last_name}</div>
                  <div style={{ fontSize:11, color:"#888" }}>{new Date(v.created_at).toLocaleDateString("en-KE")}</div>
                </div>
                <Badge label={VIOLATION_TYPES.find(x=>x.key===v.violation_type)?.label||v.violation_type} color={VIOLATION_TYPES.find(x=>x.key===v.violation_type)?.color||"#888"}/>
              </div>
            ))}
          </div>

          {/* Policy reminder */}
          <div style={{ background:"#fff", border:"1px solid #eee", borderRadius:14, padding:"1rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, marginBottom:"1rem" }}>Penalty Policy</div>
            {Object.entries(PENALTY_RULES).map(([level,p])=>(
              <div key={level} style={{ display:"flex", alignItems:"center", gap:10, padding:"8px 0", borderBottom:"0.5px solid #f5f5f5" }}>
                <div style={{ width:28, height:28, borderRadius:8, background:p.bg, border:`1px solid ${p.color}30`, display:"flex", alignItems:"center", justifyContent:"center", fontSize:14, flexShrink:0 }}>{p.icon}</div>
                <div>
                  <div style={{ fontSize:12, fontWeight:600, color:p.color }}>{level === "1"?"1st violation":level==="2"?"2nd violation":"3rd+ violation"} ΓåÆ {p.label}</div>
                  <div style={{ fontSize:11, color:"#888" }}>
                    {p.type==="warning"?"Notification sent to user":p.type==="suspension"?"Account temporarily disabled":"Permanent platform ban"}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* VIOLATIONS TAB */}
      {tab==="violations"&&!loading&&(
        <div>
          {violations.length===0&&<div style={{ color:"#888", textAlign:"center", padding:"2rem", background:"#f8f8f8", borderRadius:12 }}>No violations recorded yet</div>}
          {violations.map(v=>(
            <div key={v.id} style={{ background:"#fff", border:"1px solid #eee", borderRadius:12, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div style={{ display:"flex", gap:10, alignItems:"flex-start" }}>
                  <div style={{ width:36, height:36, borderRadius:8, background:ROLE_COLORS[v.profiles?.role]+"20", display:"flex", alignItems:"center", justifyContent:"center", fontSize:16, flexShrink:0 }}>
                    {VIOLATION_TYPES.find(x=>x.key===v.violation_type)?.icon||"ΓÜá∩╕Å"}
                  </div>
                  <div>
                    <div style={{ fontSize:13, fontWeight:600, color:"#ffffff" }}>
                      {v.profiles?.first_name} {v.profiles?.last_name}
                      <span style={{ marginLeft:8 }}><Badge label={v.profiles?.role||""} color={ROLE_COLORS[v.profiles?.role]||"#888"}/></span>
                    </div>
                    <div style={{ fontSize:12, color:"#888", marginTop:2 }}>{v.description}</div>
                    <div style={{ fontSize:11, color:"#aaa", marginTop:2 }}>{new Date(v.created_at).toLocaleString("en-KE")}</div>
                  </div>
                </div>
                <Badge label={VIOLATION_TYPES.find(x=>x.key===v.violation_type)?.label||v.violation_type} color={VIOLATION_TYPES.find(x=>x.key===v.violation_type)?.color||"#888"}/>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* PENALTIES TAB */}
      {tab==="penalties"&&!loading&&(
        <div>
          {activePenalties.length===0&&<div style={{ color:"#888", textAlign:"center", padding:"2rem", background:"#f8f8f8", borderRadius:12 }}>No active penalties</div>}
          {activePenalties.map(p=>(
            <div key={p.id} style={{ background:"#fff", border:`1px solid ${PENALTY_RULES[p.penalty_level]?.color||"#eee"}20`, borderRadius:12, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div style={{ display:"flex", gap:10, alignItems:"flex-start" }}>
                  <div style={{ width:36, height:36, borderRadius:8, background:PENALTY_RULES[p.penalty_level]?.bg||"#f5f5f5", display:"flex", alignItems:"center", justifyContent:"center", fontSize:18, flexShrink:0 }}>
                    {PENALTY_RULES[p.penalty_level]?.icon||"ΓÜá∩╕Å"}
                  </div>
                  <div>
                    <div style={{ fontSize:13, fontWeight:600, color:"#ffffff" }}>
                      {p.profiles?.first_name} {p.profiles?.last_name}
                      <span style={{ marginLeft:8 }}><Badge label={p.profiles?.role||""} color={ROLE_COLORS[p.profiles?.role]||"#888"}/></span>
                    </div>
                    <div style={{ fontSize:12, color:"#888", marginTop:2 }}>{p.reason}</div>
                    {p.suspension_expires_at&&(
                      <div style={{ fontSize:11, color:"#378add", marginTop:2 }}>
                        Expires: {new Date(p.suspension_expires_at).toLocaleString("en-KE")}
                      </div>
                    )}
                    <div style={{ fontSize:11, color:"#aaa", marginTop:2 }}>{new Date(p.created_at).toLocaleString("en-KE")}</div>
                  </div>
                </div>
                <div style={{ display:"flex", flexDirection:"column", alignItems:"flex-end", gap:8 }}>
                  <Badge label={p.penalty_type?.replace("_"," ").toUpperCase()} color={PENALTY_RULES[p.penalty_level]?.color||"#888"} bg={PENALTY_RULES[p.penalty_level]?.bg}/>
                  <button onClick={()=>removeRestriction(p.user_id, `${p.profiles?.first_name} ${p.profiles?.last_name}`)}
                    style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:8, color:"#1d9e75", fontSize:11, padding:"5px 12px", cursor:"pointer", fontWeight:600 }}>
                    Lift restriction
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
      {/* CLAIM PENALTIES TAB */}
      {tab==="claim_penalties"&&!loading&&(
        <div>
          {claimPenalties.length===0&&<div style={{ color:"#888", textAlign:"center", padding:"2rem", background:"#f8f8f8", borderRadius:12 }}>No claim-based penalties yet</div>}
          {claimPenalties.map(p=>(
            <div key={p.id} style={{ background:"#fff", border:"1px solid #e24b4a20", borderRadius:12, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:700 }}>{p.profiles?.business_name||p.profiles?.first_name} {p.profiles?.last_name}</div>
                  <div style={{ fontSize:11, color:"#888", marginTop:2 }}>Claim reason: {p.service_claims?.reason||"ΓÇö"}</div>
                  <div style={{ fontSize:11, color:"#888" }}>{new Date(p.created_at).toLocaleDateString()}</div>
                </div>
                <div style={{ textAlign:"right" }}>
                  <span style={{ fontSize:11, padding:"3px 10px", borderRadius:20, background:p.penalty_type==="permanent_ban"?"#fff5f5":p.penalty_type==="suspension_7d"?"#eff6ff":"#fff8f0", color:p.penalty_type==="permanent_ban"?"#e24b4a":p.penalty_type==="suspension_7d"?"#378add":"#e6821e", fontWeight:600 }}>{p.penalty_type?.replace(/_/g," ")}</span>
                  <div style={{ fontSize:12, color:"#e24b4a", fontWeight:700, marginTop:4 }}>KES {Number(p.amount_deducted||0).toLocaleString()} deducted</div>
                </div>
              </div>
              <div style={{ fontSize:11, color:"#555", background:"#f8f8f8", borderRadius:8, padding:"8px 10px" }}>{p.reason}</div>
              <div style={{ fontSize:10, color:p.is_active?"#e24b4a":"#1d9e75", marginTop:6, fontWeight:600 }}>{p.is_active?"≡ƒö┤ Active":"Γ£à Resolved"}{p.expires_at?" ┬╖ Expires: "+new Date(p.expires_at).toLocaleDateString():""}</div>
            </div>
          ))}
        </div>
      )}

      {/* RESTRICTED USERS TAB */}
      {tab==="restricted"&&!loading&&(
        <div>
          {suspendedUsers.length===0&&<div style={{ color:"#888", textAlign:"center", padding:"2rem", background:"#f8f8f8", borderRadius:12 }}>No restricted users</div>}
          {suspendedUsers.map(u=>(
            <div key={u.id} style={{ background:"#fff", border:`1px solid ${u.is_banned?"#e24b4a":"#378add"}20`, borderRadius:12, padding:"1rem", marginBottom:8 }}>
