                  <div style={{ width:44, height:44, borderRadius:10, background:u.is_banned?"#fff5f5":"#eff6ff", border:`1px solid ${u.is_banned?"#e24b4a":"#378add"}30`, display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontWeight:800, fontSize:16, color:u.is_banned?"#e24b4a":"#378add" }}>
                    {u.first_name?.[0]}{u.last_name?.[0]}
                  </div>
                  <div>
                    <div style={{ fontSize:14, fontWeight:600, color:"#ffffff" }}>{u.first_name} {u.last_name}</div>
                    <div style={{ display:"flex", gap:6, marginTop:4, flexWrap:"wrap" }}>
                      <Badge label={u.role} color={ROLE_COLORS[u.role]||"#888"}/>
                      <span style={{ fontSize:11, color:"#888" }}>ΓÜá∩╕Å {u.violation_count||0} violations</span>
                      <span style={{ fontSize:11, color:"#888" }}>≡ƒöö {u.warning_count||0} warnings</span>
                    </div>
                    {u.suspension_expires_at&&(
                      <div style={{ fontSize:11, color:"#378add", marginTop:4 }}>
                        Suspended until: {new Date(u.suspension_expires_at).toLocaleString("en-KE")}
                      </div>
                    )}
                  </div>
                </div>
                <div style={{ display:"flex", flexDirection:"column", alignItems:"flex-end", gap:8 }}>
                  <Badge label={u.is_banned?"BANNED":"SUSPENDED"} color={u.is_banned?"#e24b4a":"#378add"} bg={u.is_banned?"#fff5f5":"#eff6ff"}/>
                  <button onClick={()=>removeRestriction(u.id, `${u.first_name} ${u.last_name}`)}
                    style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:8, color:"#1d9e75", fontSize:11, padding:"5px 12px", cursor:"pointer", fontWeight:600 }}>
                    Lift restriction
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { UploadShareIcon } from "../../lib/cccIcons"
import useIsMobile from "../../lib/useIsMobile"
import { useAuth } from "../../contexts/AuthContext"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import toast from "react-hot-toast"

export default function AdminPromos() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const isMobile = useIsMobile()
  const [promos, setPromos] = useState([])
  const [form, setForm] = useState({ code:"", description:"", discount_type:"percentage", discount_value:"", min_purchase:"0", usage_limit:"100", valid_until:"" })
  const [loading, setLoading] = useState(true)
  const [distributePanel, setDistributePanel] = useState(null)
  const [audience, setAudience] = useState("all")
  const [searchPhone, setSearchPhone] = useState("")
  const [sending, setSending] = useState(false)

  useEffect(() => { load() }, [])

  async function load() {
    const { data } = await supabase.from("promo_codes").select("*").order("created_at",{ascending:false})
    setPromos(data||[])
    setLoading(false)
  }

  async function create(e) {
    e.preventDefault()
    if (form.discount_type==="percentage" && Number(form.discount_value) > 100) {
      return toast.error("Percentage discount cannot exceed 100%")
    }
    if (Number(form.discount_value) <= 0) {
      return toast.error("Discount value must be greater than 0")
    }
    const { error } = await supabase.from("promo_codes").insert({
      code: form.code.toUpperCase(),
      description: form.description,
      discount_type: form.discount_type,
      discount_value: Number(form.discount_value),
      min_purchase: Number(form.min_purchase),
      usage_limit: Number(form.usage_limit),
      valid_until: form.valid_until || null,
      is_active: true,
    })
    if (error) return toast.error(error.message)
    toast.success("Promo code created")
    setForm({ code:"", description:"", discount_type:"percentage", discount_value:"", min_purchase:"0", usage_limit:"100", valid_until:"" })
    load()
  }

  async function togglePromo(id, is_active) {
    await supabase.from("promo_codes").update({ is_active:!is_active }).eq("id",id)
    load()
  }

  async function distributePromo(promo) {
    setSending(true)
    try {
      let userIds = []

      if (audience === "all") {
        const { data } = await supabase.from("profiles").select("id").eq("role","customer")
        userIds = (data||[]).map(p=>p.id)
      } else if (audience === "inactive") {
        const cutoff = new Date(Date.now()-30*24*60*60*1000).toISOString()
        const { data } = await supabase.from("profiles").select("id").eq("role","customer").lt("updated_at", cutoff)
        userIds = (data||[]).map(p=>p.id)
      } else if (audience === "specific") {
        if (!searchPhone.trim()) { toast.error("Enter a phone or email to search"); setSending(false); return }
        const { data: sens } = await supabase.from("profile_sensitive").select("id").or(`phone.ilike.%${searchPhone.trim()}%,email.ilike.%${searchPhone.trim()}%`)
        userIds = (sens||[]).map(s=>s.id)
        if (userIds.length === 0) { toast.error("No matching customer found"); setSending(false); return }
      }

      if (userIds.length === 0) { toast.error("No recipients found for this audience"); setSending(false); return }

      if (!confirm(`Send promo ${promo.code} to ${userIds.length} customer${userIds.length!==1?"s":""}?`)) { setSending(false); return }

      const discountText = promo.discount_type==="percentage" ? `${promo.discount_value}% off` : `KES ${promo.discount_value} off`
      await supabase.from("notifications").insert(userIds.map(uid => ({
        user_id: uid,
        title: "Special offer just for you! ≡ƒÄë",
        message: `Use code ${promo.code} for ${discountText} your next booking${promo.min_purchase>0?` (min KES ${promo.min_purchase})`:""}${promo.valid_until?`. Valid until ${new Date(promo.valid_until).toLocaleDateString()}`:""}.`,
        type: "info"
      })))

      toast.success(`Promo sent to ${userIds.length} customer${userIds.length!==1?"s":""}!`)
      setDistributePanel(null)
      setSearchPhone("")
      setAudience("all")
    } catch(err) {
      toast.error(err.message)
    } finally {
      setSending(false)
    }
  }

  async function deletePromo(id) {
    if (!confirm("Delete this promo code?")) return
    await supabase.from("promo_codes").delete().eq("id",id)
    toast.success("Promo deleted")
    load()
  }

  const inp = { width:"100%", background:"#ffffff", border:"1px solid #f0f0f0", borderRadius:8, padding:"10px 12px", color:"#000000", fontSize:13, outline:"none", marginBottom:10, fontFamily:"'DM Sans',sans-serif" }
  const lbl = { fontSize:11, color:"#888", textTransform:"uppercase", letterSpacing:"0.05em", display:"block", marginBottom:4 }

  return (
    <div>
      {loading && <div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
      {promos.map(p => (
        <div key={p.id} style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:8, display:"flex", alignItems:"center", gap:12 }}>
          <div style={{ flex:1 }}>
            <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4 }}>
              <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#e6821e" }}>{p.code}</div>
              <span style={{ fontSize:10, padding:"2px 8px", borderRadius:20, background:p.is_active?"#f0fdf4":"#f5f5f5", color:p.is_active?"#1d9e75":"#555" }}>
                {p.is_active?"Active":"Inactive"}
              </span>
            </div>
            <div style={{ fontSize:11, color:"#888" }}>
              {p.discount_type==="percentage"?`${p.discount_value}% off`:`KES ${p.discount_value} off`}
              {p.min_purchase>0&&` ┬╖ min KES ${p.min_purchase}`}
              {` ┬╖ ${p.used_count}/${p.usage_limit} used`}
              {p.valid_until&&` ┬╖ expires ${new Date(p.valid_until).toLocaleDateString()}`}
            </div>
          </div>
          <div style={{ display:"flex", gap:6 }}>
            <button onClick={()=>setDistributePanel(distributePanel===p.id?null:p.id)} style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:7, color:"#e6821e", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
              <><UploadShareIcon size={13} color="currentColor"/> Distribute</>
            </button>
            <button onClick={()=>togglePromo(p.id,p.is_active)} style={{ background:"none", border:"1px solid #dddddd", borderRadius:7, color:"#888", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
              {p.is_active?"Disable":"Enable"}
            </button>
            <button onClick={()=>deletePromo(p.id)} style={{ background:"none", border:"1px solid #e24b4a40", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
              Delete
            </button>
          </div>
          {distributePanel===p.id&&(
            <div style={{ background:"#fff", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginTop:10, width:"100%" }}>
              <div style={{ fontSize:12, fontWeight:700, color:"#000", marginBottom:8 }}>Send {p.code} to:</div>
              <div style={{ display:"flex", gap:6, marginBottom:10, flexWrap:"wrap" }}>
                {[{k:"all",l:"All customers"},{k:"inactive",l:"Inactive 30+ days"},{k:"specific",l:"Specific customer"}].map(a=>(
                  <button key={a.k} onClick={()=>setAudience(a.k)}
                    style={{ padding:"6px 12px", borderRadius:6, border:"none", fontSize:11, cursor:"pointer", background:audience===a.k?"#e6821e":"#f0f0f0", color:audience===a.k?"#fff":"#666" }}>
                    {a.l}
                  </button>
                ))}
              </div>
              {audience==="specific"&&(
                <input value={searchPhone} onChange={e=>setSearchPhone(e.target.value)} placeholder="Search by phone or email"
                  style={{ width:"100%", background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:8, padding:"9px 12px", fontSize:13, color:"#000", outline:"none", marginBottom:10, boxSizing:"border-box" }}/>
              )}
              <button onClick={()=>distributePromo(p)} disabled={sending}
                style={{ background:sending?"#ccc":"#e6821e", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"8px 16px", cursor:sending?"not-allowed":"pointer" }}>
                {sending?"Sending...":"Send notification"}
              </button>
            </div>
          )}
        </div>
      ))}
      {!loading && promos.length===0 && <div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"1.5rem" }}>No promo codes yet</div>}

      <div style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:10, padding:"1.25rem", marginTop:"1.5rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:"1rem" }}>Create promo code</div>
        <form onSubmit={create}>
          <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"1fr 1fr", gap:10 }}>
            <div><label style={lbl}>Code</label><input style={inp} placeholder="SAVE20" value={form.code} onChange={e=>setForm(f=>({...f,code:e.target.value}))} required /></div>
            <div><label style={lbl}>Discount type</label>
              <select style={inp} value={form.discount_type} onChange={e=>setForm(f=>({...f,discount_type:e.target.value}))}>
                <option value="percentage">Percentage (%)</option>
                <option value="fixed">Fixed ($)</option>
              </select>
            </div>
            <div><label style={lbl}>Value</label><input style={inp} type="number" min="0" placeholder="20" value={form.discount_value} onChange={e=>setForm(f=>({...f,discount_value:e.target.value}))} required /></div>
            <div><label style={lbl}>Min purchase (KES)</label><input style={inp} type="number" min="0" value={form.min_purchase} onChange={e=>setForm(f=>({...f,min_purchase:e.target.value}))} /></div>
            <div><label style={lbl}>Usage limit</label><input style={inp} type="number" min="1" value={form.usage_limit} onChange={e=>setForm(f=>({...f,usage_limit:e.target.value}))} /></div>
            <div><label style={lbl}>Expires (optional)</label><input style={inp} type="date" value={form.valid_until} onChange={e=>setForm(f=>({...f,valid_until:e.target.value}))} /></div>
          </div>
          <div><label style={lbl}>Description</label><input style={inp} placeholder="e.g. 20% off first booking" value={form.description} onChange={e=>setForm(f=>({...f,description:e.target.value}))} /></div>
          <button type="submit" style={{ background:"#e6821e", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"10px 20px", cursor:"pointer" }}>
            Create promo code
          </button>
        </form>
      </div>
    </div>
  )
}

import { LocationIcon, ServicesIcon, WarningIcon, CheckIcon } from "../../lib/cccIcons"
import useIsMobile from "../../lib/useIsMobile"
import { useAuth } from "../../contexts/AuthContext"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import toast from "react-hot-toast"

export default function AdminProviders() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const isMobile = useIsMobile()
  const [providers, setProviders] = useState([])
  const [services, setServices] = useState({})
  const [earnings, setEarnings] = useState({})
  const [loading, setLoading] = useState(true)
  const [selected, setSelected] = useState(null)
  const [search, setSearch] = useState("")
  const [typeFilter, setTypeFilter] = useState("all")
  const [rejectingId, setRejectingId] = useState(null)
  const [rejectReason, setRejectReason] = useState("")

  useEffect(() => {
    load()
    const sub = supabase.channel("admin-providers-live")
      .on("postgres_changes", { event:"*", schema:"public", table:"profiles", filter:"role=eq.provider" }, () => load())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [])
  async function load() {
    const [{ data: ps }, { data: svcs }, { data: bks }] = await Promise.all([
      supabase.from("profiles").select("*").eq("role","provider").order("created_at",{ascending:false}),
      supabase.from("services").select("provider_id,id,is_active"),
      supabase.from("bookings").select("provider_id,provider_earnings,status").eq("is_archived",false)
    ])
    setProviders(ps||[])
    const svcMap = {}
    ;(svcs||[]).forEach(s=>{ if (!svcMap[s.provider_id]) svcMap[s.provider_id]={total:0,active:0}; svcMap[s.provider_id].total++; if(s.is_active) svcMap[s.provider_id].active++ })
    setServices(svcMap)
    const earnMap = {}
    ;(bks||[]).filter(b=>b.status==="completed").forEach(b=>{ earnMap[b.provider_id]=(earnMap[b.provider_id]||0)+Number(b.provider_earnings||0) })
    setEarnings(earnMap)
    setLoading(false)
  }

  async function markCommissionPaid(providerId, amount) {
    await supabase.from("profiles").update({
      cash_commission_balance: 0,
      last_commission_paid_at: new Date().toISOString(),
      is_active: true
    }).eq("id", providerId)
    toast.success("KES " + amount.toLocaleString() + " commission marked as paid")
    load()
  }

  async function toggleVerified(id, is_verified) {
    const newStatus = !is_verified
    await supabase.from("profiles").update({ 
      is_verified: newStatus,
      verification_status: newStatus ? "approved" : "pending",
      verified_at: newStatus ? new Date().toISOString() : null,
    }).eq("id",id)
    
    await supabase.from("notifications").insert({
      user_id: id,
      title: newStatus ? "You're Verified! Γ£ô" : "Verification Removed",
      message: newStatus 
        ? "Your provider account has been verified. You now appear in customer search results with a verified badge!" 
        : "Your verification status has been changed. Please contact support if you have questions.",
      type: newStatus ? "success" : "warning",
    })
    
    toast.success(is_verified?"Verification removed":"Provider verified Γ£ô")
    load()
  }

  async function rejectVerification(id) {
    if (!rejectReason.trim()) return toast.error("Please add a rejection reason")
    await supabase.from("profiles").update({
      verification_status: "rejected",
      verification_notes: rejectReason,
    }).eq("id",id)
    await supabase.from("notifications").insert({
      user_id: id,
      title: "Verification Update Required",
      message: "Your verification was not approved: " + rejectReason + ". Please update your profile and documents, then contact support.",
      type: "warning",
    })
    toast.success("Provider notified of rejection")
    setRejectingId(null)
    setRejectReason("")
    load()
  }

  async function toggleActive(id, is_active) {
    await supabase.from("profiles").update({
      is_active: !is_active,
      is_suspended: is_active, // suspending if currently active
      suspension_expires_at: is_active ? new Date(Date.now()+7*24*60*60*1000).toISOString() : null
    }).eq("id",id)
    // Notify provider
    await supabase.from("notifications").insert({ user_id: id, title: is_active?"Account suspended ΓÜá∩╕Å":"Account reactivated Γ£à", message: is_active?"Your provider account has been temporarily suspended. Contact support for details.":"Your provider account has been reactivated. You can now accept bookings.", type: is_active?"error":"success" })
    toast.success(is_active?"Provider suspended":"Provider activated")
  }

  const filtered = providers.filter(p=>
    (typeFilter==="all"||p.provider_type===typeFilter) &&
    `${p.first_name} ${p.last_name} ${p.business_name||""} ${p.city||""}`.toLowerCase().includes(search.toLowerCase())
  )

  return (
    <div>
      <div style={{ display:"grid", gridTemplateColumns:isMobile?"repeat(2,1fr)":"repeat(3,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Total providers", value:providers.length },
          { label:"Verified", value:providers.filter(p=>p.is_verified).length, color:"#1d9e75" },
          { label:"Suspended", value:providers.filter(p=>!p.is_active).length, color:providers.filter(p=>!p.is_active).length>0?"#e24b4a":undefined },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"1rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontSize:11, color:"#888", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:6 }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:22, fontWeight:800, color:s.color||"#000000" }}>{s.value}</div>
          </div>
        ))}
      </div>

      <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search providers..."
        style={{ width:"100%", background:"#f8f8f8", border:"1px solid #f0f0f0", borderRadius:8, padding:"9px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif", marginBottom:"1rem" }}/>

      <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap" }}>
        {["all","garage","parts_dealer","accessories_shop","tyre_shop","auto_electrician","car_wash","panel_beater","auto_glass","mobile_mechanic"].map(t=>(
          <button key={t} onClick={()=>setTypeFilter(t)}
            style={{ padding:"5px 12px", borderRadius:7, border:"none", fontSize:11, cursor:"pointer", background:typeFilter===t?"#8b5cf6":"#f8f8f8", color:typeFilter===t?"#fff":"#666" }}>
            {t==="all"?"All types":t.replace(/_/g," ")}
          </button>
        ))}
      </div>
      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
      {filtered.map(p=>(
        <div key={p.id} style={{ background:"#f8f8f8", border:`1px solid ${!p.is_active?"#e24b4a20":"#eeeeee"}`, borderRadius:10, padding:"1rem", marginBottom:8 }}>
          <div style={{ display:"flex", alignItems:"center", gap:12 }}>
            <div style={{ width:44, height:44, borderRadius:10, background:"#eff6ff", border:"1px solid #378add30", display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontSize:16, fontWeight:800, color:"#378add", flexShrink:0 }}>
              {(p.business_name||p.first_name||"?")[0].toUpperCase()}
            </div>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ display:"flex", alignItems:"center", gap:6, flexWrap:"wrap", marginBottom:2 }}>
                <div style={{ fontSize:13, fontWeight:600, color:p.is_active?"#000000":"#555" }}>{p.business_name||`${p.first_name} ${p.last_name}`}</div>
                {p.is_verified&&<span style={{ fontSize:10, color:"#1d9e75", background:"#f0fdf4", padding:"1px 6px", borderRadius:10 }}>Γ£ô Verified</span>}
                {!p.is_verified&&p.verification_status==="rejected"&&<span style={{ fontSize:10, color:"#e24b4a", background:"#fff5f5", padding:"1px 6px", borderRadius:10 }}>Rejected</span>}
                {!p.is_verified&&p.verification_status==="pending"&&<span style={{ fontSize:10, color:"#e6821e", background:"#fff8f0", padding:"1px 6px", borderRadius:10 }}>Pending review</span>}
                {!p.is_active&&<span style={{ fontSize:10, color:"#e24b4a", background:"#fff5f5", padding:"1px 6px", borderRadius:10 }}>Suspended</span>}
                {p.provider_type&&<span style={{ fontSize:10, color:"#8b5cf6", background:"#f5f3ff", padding:"1px 6px", borderRadius:10 }}>{p.provider_type.replace(/_/g," ")}</span>}
              </div>
              <div style={{ fontSize:11, color:"#888" }}>
                {p.business_name&&`${p.first_name} ${p.last_name} ┬╖ `}
                {p.city&&`${p.city} ┬╖ `}
                {services[p.id]?.active||0} services ┬╖ KES {Number(earnings[p.id]||0).toLocaleString()} earned
              </div>
              {p.email&&<div style={{ fontSize:10, color:"#888" }}>Γ£ë∩╕Å {p.email}</div>}
              {p.phone&&<div style={{ fontSize:10, color:"#888" }}>≡ƒô₧ {p.phone}</div>}
            </div>
            <div style={{ display:"flex", flexDirection:"column", gap:6, alignItems:"flex-end", flexShrink:0 }}>
              {p.cash_commission_balance>0&&(
                <div style={{ background:"#fff5f5", border:"1px solid #e24b4a30", borderRadius:8, padding:"4px 8px", textAlign:"center" }}>
                  <div style={{ fontSize:10, color:"#e24b4a", fontWeight:700 }}>≡ƒÆ░ Cash Commission Due</div>
                  <div style={{ fontSize:12, fontWeight:800, color:"#e24b4a" }}>KES {Number(p.cash_commission_balance).toLocaleString()}</div>
                  {p.cash_commission_due_date&&<div style={{ fontSize:9, color:"#888" }}>Due: {new Date(p.cash_commission_due_date).toLocaleDateString()}</div>}
                  <button onClick={()=>{ if(window.confirm("Mark KES "+Number(p.cash_commission_balance).toLocaleString()+" as paid by "+((p.business_name||p.first_name))+"?")) markCommissionPaid(p.id, p.cash_commission_balance) }}
                    style={{ marginTop:4, background:"#1d9e75", border:"none", borderRadius:6, color:"#fff", fontSize:10, fontWeight:700, padding:"3px 8px", cursor:"pointer", width:"100%" }}>
                    Γ£ô Mark Paid
                  </button>
                </div>
              )}
              {p.cash_commission_strikes>0&&(
                <div style={{ fontSize:10, color:"#e24b4a" }}>ΓÜá∩╕Å {p.cash_commission_strikes} strike{p.cash_commission_strikes>1?"s":""}</div>
              )}
              <button onClick={()=>setSelected(selected===p.id?null:p.id)}
                style={{ background:"none", border:"1px solid #dddddd", borderRadius:7, color:"#888", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                {selected===p.id?"Close":"Manage"}
              </button>
            </div>
          </div>
          {selected===p.id&&(
            <div style={{ marginTop:10, paddingTop:10, borderTop:"1px solid #eeeeee", display:"flex", gap:8, flexWrap:"wrap" }}>
              <button onClick={()=>toggleVerified(p.id,p.is_verified)} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:12, padding:"6px 12px", cursor:"pointer" }}>
                {p.is_verified?"Remove verification":"Γ£ô Verify provider"}
              </button>
              {!p.is_verified&&(
                <button onClick={()=>{ setRejectingId(rejectingId===p.id?null:p.id); setRejectReason("") }} style={{ background:"#fff5f5", border:"1px solid #e24b4a40", borderRadius:7, color:"#e24b4a", fontSize:12, padding:"6px 12px", cursor:"pointer" }}>
                  Γ£ù Reject verification
                </button>
              )}
              {rejectingId===p.id&&(
                <div style={{ width:"100%", marginTop:8, background:"#fff5f5", border:"1px solid #e24b4a30", borderRadius:8, padding:"0.75rem" }}>
                  <div style={{ fontSize:11, color:"#e24b4a", marginBottom:6 }}>Rejection reason (sent to provider):</div>
                  <input value={rejectReason} onChange={e=>setRejectReason(e.target.value)} placeholder="e.g. Documents unclear, expired license..."
                    style={{ width:"100%", background:"#fff", border:"1px solid #dddddd", borderRadius:7, padding:"8px 10px", fontSize:12, outline:"none", marginBottom:8 }}/>
                  <div style={{ display:"flex", gap:6 }}>
                    <button onClick={()=>rejectVerification(p.id)} style={{ background:"#e24b4a", border:"none", borderRadius:7, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"7px 14px", cursor:"pointer" }}>Send rejection</button>
                    <button onClick={()=>{ setRejectingId(null); setRejectReason("") }} style={{ background:"none", border:"1px solid #ddd", borderRadius:7, color:"#888", fontSize:12, padding:"7px 12px", cursor:"pointer" }}>Cancel</button>
                  </div>
                </div>
              )}
              <button onClick={()=>toggleActive(p.id,p.is_active)} style={{ background:p.is_active?"#fff5f5":"#f0fdf4", border:`1px solid ${p.is_active?"#e24b4a40":"#1d9e7540"}`, borderRadius:7, color:p.is_active?"#e24b4a":"#1d9e75", fontSize:12, padding:"6px 12px", cursor:"pointer" }}>
                {p.is_active?"Suspend":"Activate"}
              </button>
            </div>
          )}
        </div>
      ))}
    </div>
  )
}

import { WarningIcon, SuccessIcon } from "../../lib/cccIcons"
import useIsMobile from "../../lib/useIsMobile"
import { useAuth } from "../../contexts/AuthContext"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"

export default function AdminRevenue() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const isMobile = useIsMobile()
  const [bookings, setBookings] = useState([])
  const [clvData, setClvData] = useState([])
  const [tab, setTab] = useState("revenue")
  const [heatmap, setHeatmap] = useState({ byDay:{}, byService:{}, byHour:{} })
  const [gaps, setGaps] = useState([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    load()
    const sub = supabase.channel("admin-revenue")
      .on("postgres_changes", { event:"*", schema:"public", table:"bookings" }, () => load())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [])

  async function load() {
    const [{ data }, { data: allBookings }, { data: allDemandBookings }] = await Promise.all([
      supabase.from("bookings").select("*").eq("status","completed").order("created_at",{ascending:false}),
      supabase.from("bookings").select("customer_id, total_amount, booking_date, status").eq("status","completed"),
      supabase.from("bookings").select("booking_date, booking_time, service_name, service_category")
    ])
    setBookings(data||[])
    const clvMap = {}
    ;(allBookings||[]).forEach(b => {
      if (!clvMap[b.customer_id]) clvMap[b.customer_id] = { total:0, count:0, lastDate:null }
      clvMap[b.customer_id].total += Number(b.total_amount)
      clvMap[b.customer_id].count++
      if (!clvMap[b.customer_id].lastDate || b.booking_date > clvMap[b.customer_id].lastDate)
        clvMap[b.customer_id].lastDate = b.booking_date
    })
    const clv = Object.entries(clvMap).map(([id, v]) => ({
      customer_id: id,
      total_spend: v.total,
      bookings: v.count,
      avg_order: v.total / v.count,
      last_booking: v.lastDate,
      predicted_clv: (v.total / v.count) * Math.min(v.count * 1.5, 20)
    })).sort((a,b)=>b.predicted_clv-a.predicted_clv).slice(0,20)
    // Fetch customer names for CLV
    const custIds = clv.map(r=>r.customer_id)
    const { data: custProfs } = custIds.length>0 ? await supabase.from("profile_public").select("id,first_name,last_name").in("id", custIds) : { data:[] }
    const custMap = {}
    custProfs?.forEach(p => { custMap[p.id] = p })
    setClvData(clv.map(r=>({...r, customerName:`${custMap[r.customer_id]?.first_name||""} ${custMap[r.customer_id]?.last_name||""}`.trim()||"Customer"})))
    // Compute demand heatmap
    const byDay = {}; const byService = {}; const byHour = {}
    const days = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"]
    ;(allDemandBookings||[]).forEach(b => {
      if (b.booking_date) {
        const day = days[new Date(b.booking_date).getDay()]
        byDay[day] = (byDay[day]||0) + 1
      }
      const svc = b.service_name||(b.service_category)||"Other"
      byService[svc] = (byService[svc]||0) + 1
      if (b.booking_time) {
        const hr = b.booking_time.slice(0,2)+":00"
        byHour[hr] = (byHour[hr]||0) + 1
      }
    })
    setHeatmap({ byDay, byService, byHour })
    // Provider gap analysis
    const { data: providers } = await supabase.from("profiles").select("provider_type, city").eq("role","provider").eq("is_active",true)
    const providersByCity = {}
    ;(providers||[]).forEach(p => {
      if (!p.city) return
      if (!providersByCity[p.city]) providersByCity[p.city] = {}
      providersByCity[p.city][p.provider_type] = (providersByCity[p.city][p.provider_type]||0) + 1
    })
    // Find cities with high booking demand but few providers
    // Use allDemandBookings and match to provider cities
    const cityDemand = {}
    ;(allDemandBookings||[]).forEach(b => {
      const city = b.service_location_city || b.city || "Nairobi"
      cityDemand[city] = (cityDemand[city]||0) + 1
    })
    // Also count by provider city to show where bookings are going
    Object.keys(providersByCity).forEach(city => {
      if (!cityDemand[city]) cityDemand[city] = 0
    })
    const gapAnalysis = Object.entries(cityDemand).map(([city, demand]) => ({
      city,
      demand,
      providerCount: Object.values(providersByCity[city]||{}).reduce((s,v)=>s+v,0),
      ratio: demand / Math.max(Object.values(providersByCity[city]||{}).reduce((s,v)=>s+v,0), 1),
      missingTypes: ["garage","car_wash","mobile_mechanic"].filter(t => !(providersByCity[city]||{})[t])
    })).filter(g=>g.demand>0).sort((a,b)=>b.ratio-a.ratio).slice(0,10)
    setGaps(gapAnalysis)
    setLoading(false)
  }

  const total = bookings.reduce((s,b)=>s+Number(b.total_amount),0)
  const heldEscrow = bookings.filter(b=>b.payment_held&&!b.payment_released).reduce((s,b)=>s+Number(b.provider_earnings||0),0)
  const commission = bookings.reduce((s,b)=>s+Number(b.platform_commission||0),0)
  const providerPaid = bookings.reduce((s,b)=>s+Number(b.provider_earnings||0),0)
  const driverPaid = bookings.reduce((s,b)=>s+Number(b.driver_earnings||0),0)

  const byMonth = bookings.reduce((acc,b)=>{
    const month = b.booking_date?.slice(0,7)
    if (!month) return acc
    acc[month] = (acc[month]||0) + Number(b.total_amount)
    return acc
  },{})

  function forecastNextMonth() {
    const months = Object.entries(byMonth).sort((a,b)=>a[0].localeCompare(b[0]))
    if (months.length < 2) return null
    const last3 = months.slice(-3)
    const n = last3.length
    const avgGrowth = last3.reduce((sum,[,v],i) => {
      if (i===0) return sum
      const prev = Number(last3[i-1][1])
      return sum + (prev > 0 ? (Number(v)-prev)/prev : 0)
    }, 0) / (n-1)
    const lastRevenue = Number(last3[n-1][1])
    const nextMonth = new Date(last3[n-1][0]+"-01")
    nextMonth.setMonth(nextMonth.getMonth()+1)
    return {
      amount: Math.max(0, lastRevenue*(1+avgGrowth)),
      month: nextMonth.toLocaleString("default",{month:"long",year:"numeric"}),
      growth: (avgGrowth*100).toFixed(1),
      trend: avgGrowth>=0?"up":"down"
    }
  }

  const forecast = forecastNextMonth()
  const sortedMonths = Object.entries(byMonth).sort((a,b)=>b[0].localeCompare(a[0]))
  const maxMonthly = Math.max(...sortedMonths.map(([,v])=>Number(v)),1)

  if (loading) return <div style={{color:"#888",fontSize:13}}>Loading...</div>

  return (
    <div>
      <div style={{display:"flex",gap:8,marginBottom:"1.5rem"}}>
        <button onClick={()=>setTab("revenue")} style={{padding:"6px 16px",borderRadius:8,border:"none",fontSize:12,fontWeight:700,cursor:"pointer",background:tab==="revenue"?"#e6821e":"#f8f8f8",color:tab==="revenue"?"#fff":"#666"}}>Revenue</button>
        <button onClick={()=>setTab("clv")} style={{padding:"6px 16px",borderRadius:8,border:"none",fontSize:12,fontWeight:700,cursor:"pointer",background:tab==="clv"?"#8b5cf6":"#f8f8f8",color:tab==="clv"?"#fff":"#666"}}>Customer LTV</button>
        <button onClick={()=>setTab("heatmap")} style={{padding:"6px 16px",borderRadius:8,border:"none",fontSize:12,fontWeight:700,cursor:"pointer",background:tab==="heatmap"?"#378add":"#f8f8f8",color:tab==="heatmap"?"#fff":"#666"}}>Demand Heatmap</button>
        <button onClick={()=>setTab("gaps")} style={{padding:"6px 16px",borderRadius:8,border:"none",fontSize:12,fontWeight:700,cursor:"pointer",background:tab==="gaps"?"#1d9e75":"#f8f8f8",color:tab==="gaps"?"#fff":"#666"}}>Provider Gaps</button>
      </div>

      {tab==="revenue"&&(
        <>
          <div style={{display:"grid",gridTemplateColumns:isMobile?"repeat(2,1fr)":"repeat(4,1fr)",gap:10,marginBottom:"1.5rem"}}>
            {[
              {label:"Total revenue",value:`KES ${total.toLocaleString()}`},
              {label:"Platform commission",value:`KES ${commission.toLocaleString()}`,color:"#e6821e"},
              {label:"Paid to providers",value:`KES ${providerPaid.toLocaleString()}`},
              {label:"Paid to drivers",value:`KES ${driverPaid.toLocaleString()}`},
            ].map(s=>(
              <div key={s.label} style={{background:"#f8f8f8",borderRadius:10,padding:"1rem",border:"1px solid #eeeeee"}}>
                <div style={{fontSize:11,color:"#888",textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:6}}>{s.label}</div>
                <div style={{fontFamily:"Syne",fontSize:isMobile?16:22,fontWeight:800,color:s.color||"#000000"}}>{s.value}</div>
              </div>
            ))}
          </div>

          {forecast&&(
            <div style={{background:forecast.trend==="up"?"#f0fdf4":"#fff5f5",border:`1px solid ${forecast.trend==="up"?"#1d9e7540":"#e24b4a40"}`,borderRadius:12,padding:"1.25rem",marginBottom:"1.5rem"}}>
              <div style={{fontFamily:"Syne",fontSize:14,fontWeight:700,marginBottom:4,color:"#000000"}}>≡ƒôê Revenue Forecast ΓÇö {forecast.month}</div>
              <div style={{display:"flex",alignItems:"baseline",gap:12}}>
                <div style={{fontFamily:"Syne",fontSize:28,fontWeight:800,color:forecast.trend==="up"?"#1d9e75":"#e24b4a"}}>KES {Math.round(forecast.amount).toLocaleString()}</div>
                <div style={{fontSize:13,color:forecast.trend==="up"?"#1d9e75":"#e24b4a"}}>{forecast.trend==="up"?"Γåæ":"Γåô"} {Math.abs(forecast.growth)}% vs last month</div>
              </div>
              <div style={{fontSize:11,color:"#888",marginTop:4}}>Based on average growth rate over last 3 months</div>
            </div>
          )}

          <div style={{fontFamily:"Syne",fontSize:14,fontWeight:700,marginBottom:10}}>Revenue by month</div>
          {sortedMonths.length===0&&<div style={{color:"#888",fontSize:13,textAlign:"center",padding:"2rem"}}>No completed bookings yet</div>}
          {sortedMonths.map(([month,amount])=>(
            <div key={month} style={{background:"#f8f8f8",border:"1px solid #eeeeee",borderRadius:10,padding:"1rem",marginBottom:8}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6}}>
                <div style={{fontSize:13}}>{new Date(month+"-01").toLocaleString("default",{month:"long",year:"numeric"})}</div>
                <div style={{fontFamily:"Syne",fontSize:14,fontWeight:700,color:"#e6821e"}}>KES {Number(amount).toLocaleString()}</div>
              </div>
              <div style={{height:6,background:"#eeeeee",borderRadius:3,overflow:"hidden"}}>
                <div style={{height:"100%",background:"#e6821e",borderRadius:3,width:`${(Number(amount)/maxMonthly)*100}%`,transition:"width 0.5s"}}/>
              </div>
            </div>
          ))}
        </>
      )}

      {tab==="clv"&&(
        <div>
          <div style={{fontSize:12,color:"#888",marginBottom:"1rem"}}>Top 20 customers by predicted lifetime value. LTV = avg order value ├ù projected future bookings.</div>
          {clvData.length===0&&<div style={{color:"#888",fontSize:13,textAlign:"center",padding:"2rem"}}>No completed bookings yet</div>}
          {clvData.map((row,i)=>(
            <div key={row.customer_id} style={{background:"#f8f8f8",border:"1px solid #eeeeee",borderRadius:10,padding:"1rem",marginBottom:8}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"start",marginBottom:6}}>
                <div style={{display:"flex",alignItems:"center",gap:8}}>
                  <div style={{width:24,textAlign:"center",fontFamily:"Syne",fontSize:12,fontWeight:800,color:i===0?"#e6821e":i===1?"#888":i===2?"#a0703a":"#bbb"}}>{i+1}</div>
                  <div>
                    <div style={{fontSize:12,color:"#888"}}>{row.customerName}</div>
                    <div style={{fontSize:11,color:"#666",marginTop:2}}>{row.bookings} booking{row.bookings!==1?"s":""} ┬╖ Last: {row.last_booking}</div>
                  </div>
                </div>
                <div style={{textAlign:"right"}}>
                  <div style={{fontFamily:"Syne",fontSize:14,fontWeight:800,color:"#8b5cf6"}}>KES {Math.round(row.predicted_clv).toLocaleString()}</div>
                  <div style={{fontSize:10,color:"#888"}}>predicted LTV</div>
                </div>
              </div>
              <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8}}>
                {[
                  {l:"Total spent",v:`KES ${Math.round(row.total_spend).toLocaleString()}`},
                  {l:"Avg order",v:`KES ${Math.round(row.avg_order).toLocaleString()}`},
                  {l:"Bookings",v:row.bookings},
                ].map(f=>(
                  <div key={f.l}>
                    <div style={{fontSize:10,color:"#888",textTransform:"uppercase"}}>{f.l}</div>
                    <div style={{fontSize:12,fontWeight:600,marginTop:2}}>{f.v}</div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}

      {tab==="heatmap"&&(
        <div>
          <div style={{fontFamily:"Syne",fontSize:14,fontWeight:700,marginBottom:10}}>Bookings by Day of Week</div>
          {Object.entries(heatmap.byDay).sort((a,b)=>["Sun","Mon","Tue","Wed","Thu","Fri","Sat"].indexOf(a[0])-["Sun","Mon","Tue","Wed","Thu","Fri","Sat"].indexOf(b[0])).map(([day,count])=>{
            const max = Math.max(...Object.values(heatmap.byDay),1)
            return (
              <div key={day} style={{display:"flex",alignItems:"center",gap:10,marginBottom:6}}>
                <div style={{width:32,fontSize:11,color:"#888"}}>{day}</div>
                <div style={{flex:1,height:20,background:"#eeeeee",borderRadius:4,overflow:"hidden"}}>
                  <div style={{height:"100%",background:"#378add",borderRadius:4,width:`${(count/max)*100}%`,transition:"width 0.5s"}}/>
                </div>
                <div style={{width:24,fontSize:11,fontWeight:700,color:"#378add"}}>{count}</div>
              </div>
            )
          })}
          <div style={{fontFamily:"Syne",fontSize:14,fontWeight:700,margin:"1.5rem 0 10px"}}>Top Services by Demand</div>
          {Object.entries(heatmap.byService).sort((a,b)=>b[1]-a[1]).slice(0,10).map(([svc,count])=>{
            const max = Math.max(...Object.values(heatmap.byService),1)
            return (
              <div key={svc} style={{display:"flex",alignItems:"center",gap:10,marginBottom:6}}>
                <div style={{flex:1,fontSize:12,color:"#000",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{svc}</div>
                <div style={{width:120,height:16,background:"#eeeeee",borderRadius:4,overflow:"hidden"}}>
                  <div style={{height:"100%",background:"#e6821e",borderRadius:4,width:`${(count/max)*100}%`}}/>
                </div>
                <div style={{width:24,fontSize:11,fontWeight:700,color:"#e6821e"}}>{count}</div>
              </div>
            )
          })}
          <div style={{fontFamily:"Syne",fontSize:14,fontWeight:700,margin:"1.5rem 0 10px"}}>Bookings by Hour</div>
          {Object.entries(heatmap.byHour).sort((a,b)=>a[0].localeCompare(b[0])).map(([hr,count])=>{
            const max = Math.max(...Object.values(heatmap.byHour),1)
            return (
              <div key={hr} style={{display:"flex",alignItems:"center",gap:10,marginBottom:4}}>
                <div style={{width:40,fontSize:11,color:"#888"}}>{hr}</div>
                <div style={{flex:1,height:14,background:"#eeeeee",borderRadius:4,overflow:"hidden"}}>
                  <div style={{height:"100%",background:"#1d9e75",borderRadius:4,width:`${(count/max)*100}%`}}/>
                </div>
                <div style={{width:24,fontSize:11,fontWeight:700,color:"#1d9e75"}}>{count}</div>
              </div>
            )
          })}
        </div>
      )}
      {tab==="gaps"&&(
        <div>
          <div style={{fontSize:12,color:"#888",marginBottom:"1rem"}}>Areas with high booking demand but low provider coverage. These locations need more providers.</div>
          {gaps.length===0&&<div style={{color:"#888",fontSize:13,textAlign:"center",padding:"2rem"}}>Not enough data yet</div>}
          {gaps.map((g,i)=>(
            <div key={g.city} style={{background:"#f8f8f8",border:`1px solid ${g.ratio>3?"#e24b4a30":g.ratio>1.5?"#e6821e30":"#eeeeee"}`,borderRadius:10,padding:"1rem",marginBottom:8}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"start",marginBottom:6}}>
                <div>
                  <div style={{fontSize:14,fontWeight:700,color:"#000"}}>{g.city}</div>
                  <div style={{fontSize:11,color:"#888",marginTop:2}}>{g.demand} bookings ┬╖ {g.providerCount} provider{g.providerCount!==1?"s":""}</div>
                </div>
                <span style={{fontSize:11,padding:"2px 8px",borderRadius:10,background:g.ratio>3?"#fff5f5":g.ratio>1.5?"#fff8f0":"#f0fdf4",color:g.ratio>3?"#e24b4a":g.ratio>1.5?"#e6821e":"#1d9e75"}}>
                  {g.ratio>3?<><WarningIcon size={12} color="#e24b4a"/> Critical</>:g.ratio>1.5?<><WarningIcon size={12} color="#e6821e"/> Needed</>:<><SuccessIcon size={12} color="#1d9e75"/> OK</>}
                </span>
              </div>
              {g.missingTypes.length>0&&(
                <div style={{fontSize:11,color:"#555",marginTop:4}}>
                  Missing: {g.missingTypes.map(t=>t.replace(/_/g," ")).join(", ")}
                </div>
              )}
              <div style={{marginTop:8,height:4,background:"#eeeeee",borderRadius:2,overflow:"hidden"}}>
                <div style={{height:"100%",background:g.ratio>3?"#e24b4a":g.ratio>1.5?"#e6821e":"#1d9e75",borderRadius:2,width:`${Math.min(g.ratio*20,100)}%`}}/>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

export default function AdminReviews() {
  const isMobile = useIsMobile()
  const { user } = useAuth()
  const [reviews, setReviews] = useState([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState("all")
  const [tab, setTab] = useState("all")
  const [adminNote, setAdminNote] = useState("")
  const [notingId, setNotingId] = useState(null)

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("admin-reviews-live")
      .on("postgres_changes", { event:"*", schema:"public", table:"reviews" }, () => load())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function load() {
    const { data } = await supabase.from("reviews")
      .select("*, customer:profile_public!customer_id(first_name,last_name), provider:profile_public!provider_id(first_name,last_name,business_name)")
      .order("created_at", { ascending:false })
    setReviews(data||[])
    setLoading(false)
  }

  async function toggleHide(id, is_hidden) {
    await supabase.from("reviews").update({ is_hidden:!is_hidden }).eq("id", id)
    toast.success(is_hidden?"Review visible":"Review hidden")
    load()
  }

  async function toggleFlag(id, is_flagged) {
    await supabase.from("reviews").update({ is_flagged:!is_flagged }).eq("id", id)
    toast.success(is_flagged?"Flag removed":"Review flagged for moderation")
    load()
  }

  async function deleteReview(id) {
    if (!confirm("Delete this review permanently?")) return
    await supabase.from("reviews").delete().eq("id", id)
    toast.success("Review deleted")
    load()
  }

  async function saveNote(id) {
    if (!adminNote.trim()) return
    await supabase.from("reviews").update({ admin_notes: adminNote }).eq("id", id)
    toast.success("Note saved")
    setNotingId(null); setAdminNote(""); load()
  }

  const allFiltered = tab==="flagged" ? reviews.filter(r=>r.is_flagged) :
    tab==="hidden" ? reviews.filter(r=>r.is_hidden) :
    tab==="provider" ? reviews.filter(r=>r.provider_rating) :
    tab==="driver" ? reviews.filter(r=>r.driver_rating) :
    tab==="mechanic" ? reviews.filter(r=>r.mechanic_rating) : reviews

  const avgRating = reviews.length > 0 ? (reviews.reduce((s,r)=>s+(r.provider_rating||0),0)/reviews.filter(r=>r.provider_rating).length||0).toFixed(1) : "0.0"

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, marginBottom:"1.25rem" }}>Reviews & Ratings</div>
      <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(120px,1fr))", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Total reviews", value:reviews.length, color:"#000" },
          { label:"Provider avg", value:avgRating+" Γÿà", color:"#e6821e" },
          { label:"Flagged", value:reviews.filter(r=>r.is_flagged).length, color:"#e24b4a" },
          { label:"Hidden", value:reviews.filter(r=>r.is_hidden).length, color:"#888" },
          { label:"With response", value:reviews.filter(r=>r.provider_response||r.driver_response).length, color:"#1d9e75" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.75rem", border:"1px solid #eee", textAlign:"center" }}>
            <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>
      <div style={{ overflowX:"auto", marginBottom:"1rem", paddingBottom:4 }}>
        <div style={{ display:"flex", gap:6, minWidth:"max-content" }}>
          {[
            {k:"all",l:"All ("+reviews.length+")"},
            {k:"flagged",l:"Flagged ("+reviews.filter(r=>r.is_flagged).length+")"},
            {k:"hidden",l:"Hidden ("+reviews.filter(r=>r.is_hidden).length+")"},
            {k:"provider",l:"Provider"},
            {k:"driver",l:"Driver"},
            {k:"mechanic",l:"Mechanic"},
          ].map(t=>(
            <button key={t.k} onClick={()=>setTab(t.k)}
              style={{ padding:"6px 14px", borderRadius:6, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#e24b4a":"#f0f0f0", color:tab===t.k?"#fff":"#666", whiteSpace:"nowrap" }}>
              {t.l}
            </button>
          ))}
        </div>
      </div>
      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
      {!loading&&allFiltered.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No reviews found</div>}
      {allFiltered.map(r=>(
        <div key={r.id} style={{ background:"#f8f8f8", border:"1px solid "+(r.is_flagged?"#e24b4a":r.is_hidden?"#888":"#eee")+"30", borderRadius:12, padding:"1rem", marginBottom:10, opacity:r.is_hidden?0.6:1 }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
            <div>
              <div style={{ display:"flex", gap:6, alignItems:"center", flexWrap:"wrap", marginBottom:4 }}>
                <div style={{ fontSize:13, fontWeight:600 }}>{r.provider?.business_name||r.provider?.first_name+" "+r.provider?.last_name||"Unknown provider"}</div>
                {r.is_flagged&&<span style={{ fontSize:10, color:"#e24b4a", background:"#fff5f5", padding:"1px 8px", borderRadius:10 }}>≡ƒÜ⌐ Flagged</span>}
                {r.is_hidden&&<span style={{ fontSize:10, color:"#888", background:"#f0f0f0", padding:"1px 8px", borderRadius:10 }}>Hidden</span>}
              </div>
              <div style={{ fontSize:11, color:"#888" }}>By: {r.customer?.first_name} {r.customer?.last_name} ┬╖ {new Date(r.created_at).toLocaleDateString()}</div>
            </div>
            <div style={{ textAlign:"right" }}>
              {r.provider_rating&&<div style={{ fontSize:12, color:"#e6821e" }}>Provider: {"Γÿà".repeat(r.provider_rating)}</div>}
              {r.driver_rating&&<div style={{ fontSize:12, color:"#378add" }}>Driver: {"Γÿà".repeat(r.driver_rating)}</div>}
              {r.mechanic_rating&&<div style={{ fontSize:12, color:"#1d9e75" }}>Mechanic: {"Γÿà".repeat(r.mechanic_rating)}</div>}
            </div>
          </div>
          {r.provider_review&&<div style={{ fontSize:12, color:"#555", fontStyle:"italic", marginBottom:6 }}>"{r.provider_review}"</div>}
          {r.driver_review&&<div style={{ fontSize:12, color:"#378add", fontStyle:"italic", marginBottom:6 }}>Driver: "{r.driver_review}"</div>}
          {r.mechanic_review&&<div style={{ fontSize:12, color:"#1d9e75", fontStyle:"italic", marginBottom:6 }}>Mechanic: "{r.mechanic_review}"</div>}
          {r.provider_response&&<div style={{ background:"#fff8f0", border:"1px solid #e6821e20", borderRadius:8, padding:"0.5rem 0.75rem", fontSize:11, color:"#555", marginBottom:6 }}>Provider reply: {r.provider_response}</div>}
          {r.driver_response&&<div style={{ background:"#eff6ff", border:"1px solid #378add20", borderRadius:8, padding:"0.5rem 0.75rem", fontSize:11, color:"#555", marginBottom:6 }}>Driver reply: {r.driver_response}</div>}
          {r.admin_notes&&<div style={{ background:"#f5f3ff", border:"1px solid #8b5cf620", borderRadius:8, padding:"0.5rem 0.75rem", fontSize:11, color:"#8b5cf6", marginBottom:6 }}>Admin note: {r.admin_notes}</div>}
          {notingId===r.id&&(
            <div style={{ marginBottom:8 }}>
              <textarea value={adminNote} onChange={e=>setAdminNote(e.target.value)} placeholder="Add internal admin note..." rows={2}
                style={{ width:"100%", background:"#fff", border:"1px solid #8b5cf640", borderRadius:8, padding:"8px 10px", fontSize:12, outline:"none", resize:"none", boxSizing:"border-box" }}/>
              <div style={{ display:"flex", gap:6, marginTop:4 }}>
                <button onClick={()=>saveNote(r.id)} style={{ background:"#8b5cf6", border:"none", borderRadius:6, color:"#fff", fontSize:11, padding:"6px 12px", cursor:"pointer" }}>Save Note</button>
                <button onClick={()=>{ setNotingId(null); setAdminNote("") }} style={{ background:"#f0f0f0", border:"none", borderRadius:6, color:"#555", fontSize:11, padding:"6px 10px", cursor:"pointer" }}>Cancel</button>
              </div>
            </div>
          )}
          <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginTop:8 }}>
            <button onClick={()=>toggleFlag(r.id, r.is_flagged)}
              style={{ background:r.is_flagged?"#fff5f5":"#f8f8f8", border:"1px solid "+(r.is_flagged?"#e24b4a40":"#ddd"), borderRadius:6, color:r.is_flagged?"#e24b4a":"#555", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
              {r.is_flagged?"≡ƒÜ⌐ Unflag":"≡ƒÜ⌐ Flag"}
            </button>
            <button onClick={()=>toggleHide(r.id, r.is_hidden)}
              style={{ background:"#f8f8f8", border:"1px solid #ddd", borderRadius:6, color:"#555", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
              {r.is_hidden?"≡ƒæü∩╕Å Show":"≡ƒÖê Hide"}
            </button>
            <button onClick={()=>{ setNotingId(r.id); setAdminNote(r.admin_notes||"") }}
              style={{ background:"#f5f3ff", border:"1px solid #8b5cf620", borderRadius:6, color:"#8b5cf6", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
              ≡ƒô¥ Note
            </button>
            <button onClick={()=>deleteReview(r.id)}
              style={{ background:"#fff5f5", border:"1px solid #e24b4a30", borderRadius:6, color:"#e24b4a", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
              ≡ƒùæ∩╕Å Delete
            </button>
          </div>
        </div>
      ))}
    </div>
  )
}

import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import toast from "react-hot-toast"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"

export default function AdminServices() {
  const { user, profile } = useAuth()
  if(!user || profile?.role !== "admin") return null
  const [services, setServices] = useState([])
  const [loading, setLoading] = useState(true)
  const isMobile = useIsMobile()
  const [search, setSearch] = useState("")
  const [statusFilter, setStatusFilter] = useState("active")
  const [providerFilter, setProviderFilter] = useState("all")
  const [tab, setTab] = useState("services")
  const [bundles, setBundles] = useState([])

  useEffect(() => {
    load()
    const sub = supabase.channel("admin-services")
      .on("postgres_changes", { event:"*", schema:"public", table:"services" }, () => { load(); toast("Services updated", { icon:"≡ƒöº" }) })
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [])

  async function load() {
    const [{ data }, { data: bds }] = await Promise.all([
      supabase.from("services")
        .select("*, profile_public(first_name, last_name, business_name)")
        .order("created_at", { ascending:false }),
      supabase.from("service_bundles")
        .select("*, profile_public:profiles!service_bundles_provider_id_fkey(first_name, last_name, business_name)")
        .order("created_at", { ascending:false })
    ])
    setServices(data || [])
    setBundles(bds || [])
    setLoading(false)
  }
  async function toggleBundleActive(id, is_active) {
    await supabase.from("service_bundles").update({ is_active: !is_active }).eq("id", id)
    toast.success(is_active ? "Bundle hidden" : "Bundle activated")
    load()
  }
  async function deleteBundle(id) {
    if (!confirm("Delete this bundle permanently?")) return
    await supabase.from("service_bundles").delete().eq("id", id)
    toast.success("Bundle deleted")
    load()
  }

  async function toggleActive(id, is_active) {
    await supabase.from("services").update({ is_active: !is_active }).eq("id", id)
    toast.success(is_active ? "Service hidden" : "Service activated")
    load()
  }

  async function deleteService(id) {
    if (!confirm("Delete this service permanently?")) return
    await supabase.from("services").delete().eq("id", id)
    toast.success("Service deleted")
    load()
  }

  const filtered = services.filter(s => {
    const matchSearch = s.name?.toLowerCase().includes(search.toLowerCase()) || s.category?.toLowerCase().includes(search.toLowerCase())
    const matchStatus = statusFilter==="all" || (statusFilter==="active" ? s.is_active : !s.is_active)
    return matchSearch && matchStatus
  })

  return (
    <div>
      <div style={{ display:"flex", gap:8, marginBottom:"1rem" }}>
        <button onClick={()=>setTab("services")} style={{ padding:"6px 16px", borderRadius:8, border:"none", fontSize:12, fontWeight:700, cursor:"pointer", background:tab==="services"?"#8b5cf6":"#f8f8f8", color:tab==="services"?"#fff":"#666" }}>
          Services ({services.length})
        </button>
        <button onClick={()=>setTab("bundles")} style={{ padding:"6px 16px", borderRadius:8, border:"none", fontSize:12, fontWeight:700, cursor:"pointer", background:tab==="bundles"?"#e6821e":"#f8f8f8", color:tab==="bundles"?"#fff":"#666" }}>
          Bundles ({bundles.length})
        </button>
      </div>
      {tab==="services"&&(<>
      <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(120px,1fr))", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Total", value:services.length, color:"#000" },
          { label:"Active", value:services.filter(s=>s.is_active).length, color:"#1d9e75" },
          { label:"Inactive", value:services.filter(s=>!s.is_active).length, color:"#888" },
          { label:"With photos", value:services.filter(s=>s.photos?.length>0).length, color:"#378add" },
          { label:"Discounted", value:services.filter(s=>s.discounted_price).length, color:"#8b5cf6" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.75rem", border:"1px solid #eee", textAlign:"center" }}>
            <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>
      <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap" }}>
        {[{k:"active",l:"Active"},{k:"inactive",l:"Inactive"},{k:"all",l:"All"}].map(t=>(
          <button key={t.k} onClick={()=>setStatusFilter(t.k)} style={{ padding:"6px 14px", borderRadius:6, border:"none", fontSize:12, cursor:"pointer", background:statusFilter===t.k?"#e6821e":"#f0f0f0", color:statusFilter===t.k?"#fff":"#555" }}>{t.l}</button>
        ))}
      </div>
      <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search services..."
        style={{ width:"100%", background:"#f8f8f8", border:"1px solid #f0f0f0", borderRadius:8, padding:"10px 12px", color:"#000000", fontSize:13, outline:"none", marginBottom:"1rem", fontFamily:"'DM Sans',sans-serif" }} />
      <div style={{ fontSize:12, color:"#888", marginBottom:10 }}>{filtered.length} service{filtered.length!==1?"s":""}</div>
      {loading && <div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
      {filtered.map(s => (
        <div key={s.id} style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:8, display:"flex", alignItems:"center", gap:12 }}>
          <div style={{ flex:1 }}>
            <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4 }}>
              <div style={{ fontSize:14, fontWeight:500, color:"#000000" }}>{s.name}</div>
              <span style={{ fontSize:10, padding:"2px 8px", borderRadius:20, background:s.is_active?"#f0fdf4":"#f5f5f5", color:s.is_active?"#1d9e75":"#555" }}>
                {s.is_active?"Active":"Hidden"}
              </span>
            </div>
            <div style={{ fontSize:11, color:"#888" }}>
              {s.category} ┬╖ {s.duration_minutes||s.duration||60}min ┬╖
              {s.discounted_price ? (
                <span><span style={{ textDecoration:"line-through", color:"#aaa" }}>KES {Number(s.price).toLocaleString()}</span> <span style={{ color:"#1d9e75", fontWeight:700 }}>KES {Number(s.discounted_price).toLocaleString()}</span> <span style={{ color:"#1d9e75", fontSize:10 }}>({Math.round((1-s.discounted_price/s.price)*100)}% OFF)</span></span>
              ) : (
                <span>KES {Number(s.price).toLocaleString()}</span>
              )}
              <span style={{ marginLeft:8 }}>{s.profile_public?.business_name||`${s.profile_public?.first_name||""} ${s.profile_public?.last_name||""}`}</span>
            </div>
          </div>
          <div style={{ display:"flex", gap:6 }}>
            <button onClick={()=>toggleActive(s.id,s.is_active)} style={{ background:"none", border:"1px solid #dddddd", borderRadius:7, color:"#888", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
              {s.is_active?"Hide":"Show"}
            </button>
            <button onClick={()=>deleteService(s.id)} style={{ background:"none", border:"1px solid #e24b4a40", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
              Delete
            </button>
          </div>
        </div>
      ))}
      {!loading && filtered.length===0 && <div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No services yet</div>}
      </>)}
      {tab==="bundles"&&(
        <div>
          <div style={{ fontSize:12, color:"#888", marginBottom:10 }}>{bundles.length} bundle{bundles.length!==1?"s":""}</div>
          {loading && <div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
          {bundles.map(b => {
            const savings = Number(b.original_price) - Number(b.bundle_price)
            const savingsPct = Math.round((savings / Number(b.original_price)) * 100)
            return (
              <div key={b.id} style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:8, display:"flex", alignItems:"center", gap:12 }}>
                <div style={{ flex:1 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4 }}>
                    <div style={{ fontSize:14, fontWeight:500, color:"#000000" }}>{b.name}</div>
                    <span style={{ fontSize:10, padding:"2px 8px", borderRadius:20, background:b.is_active?"#f0fdf4":"#f5f5f5", color:b.is_active?"#1d9e75":"#555" }}>
                      {b.is_active?"Active":"Hidden"}
                    </span>
                    <span style={{ fontSize:10, padding:"2px 8px", borderRadius:20, background:"#fff8f0", color:"#e6821e" }}>
                      Save {savingsPct}%
                    </span>
                  </div>
                  <div style={{ fontSize:11, color:"#888" }}>
                    KES {Number(b.bundle_price).toLocaleString()} (was {Number(b.original_price).toLocaleString()}) ┬╖ {b.service_ids?.length||0} services ┬╖ {b.platform_commission_rate?(b.platform_commission_rate*100).toFixed(1)+"% commission":""}
                    <span style={{ marginLeft:8 }}>{b.profile_public?.business_name||`${b.profile_public?.first_name||""} ${b.profile_public?.last_name||""}`}</span>
                  </div>
                </div>
                <div style={{ display:"flex", gap:6 }}>
                  <button onClick={()=>toggleBundleActive(b.id,b.is_active)} style={{ background:"none", border:"1px solid #dddddd", borderRadius:7, color:"#888", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                    {b.is_active?"Hide":"Show"}
                  </button>
                  <button onClick={()=>deleteBundle(b.id)} style={{ background:"none", border:"1px solid #e24b4a40", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                    Delete
                  </button>
                </div>
              </div>
            )
          })}
          {!loading && bundles.length===0 && <div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No bundles yet</div>}
        </div>
      )}
    </div>
  )
}

import { WalletIcon, GOServiceIcon, VehicleIcon, ShieldIcon, SettingsIcon } from "../../lib/cccIcons"
import { useEffect, useState, useRef } from "react"
import { supabase } from "../../lib/supabase"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"
import { validateFile } from "../../lib/uploadValidation"
import { useAuth } from "../../contexts/AuthContext"

const SETTING_CATEGORIES = {
  "Commissions & Fees": { icon:"wallet", color:"#1d9e75", keys:["inspection_fee","go_service_callout_fee","concierge_surcharge_rate","marketplace_processing_fee_rate","marketplace_driver_commission_rate","marketplace_driver_commission_rate_motorcycle","marketplace_driver_commission_rate_tuktuk","marketplace_driver_commission_rate_van","marketplace_driver_commission_rate_car","marketplace_delivery_fee_multiplier_motorcycle","marketplace_delivery_fee_multiplier_tuktuk","marketplace_delivery_fee_multiplier_van","marketplace_delivery_fee_multiplier_car"] },
  "GO Service Rates": { icon:"emergency", color:"#e24b4a", keys:["go_callout_fee","go_callout_provider_rate","go_callout_platform_rate","go_service_provider_rate","go_service_platform_rate","go_parts_provider_rate","go_parts_platform_rate","go_provider_strike_limit"] },
  "New Car Marketplace": { icon:"vehicle", color:"#378add", keys:["new_car_listing_fee","new_car_lead_fee","new_car_featured_fee_day","new_car_featured_fee_week","new_car_featured_fee_month","new_car_listing_duration_days"] },
  "Payment & Banking": { icon:"≡ƒÅª", color:"#8b5cf6", keys:["go_callout_fee","min_payout_amount","platform_bank_name","platform_bank_account","platform_bank_account_name","daraja_wallet_id"] },
}

export default function AdminSettings() {
  const { user, profile } = useAuth()
  if(!user || profile?.role !== "admin") return null
  const isMobile = useIsMobile()
  const [settings, setSettings] = useState([])
  const [loading, setLoading] = useState(true)
  const [editing, setEditing] = useState(null)
  const [form, setForm] = useState({ value:"", description:"" })
  const [saving, setSaving] = useState(false)
  const [logoUrl, setLogoUrl] = useState("/logo_c.svg")
  const [uploadingLogo, setUploadingLogo] = useState(false)
  const [expandedCat, setExpandedCat] = useState("Commissions & Fees")
  const logoInputRef = useRef(null)

  useEffect(() => { load(); loadLogo() }, [])

  async function loadLogo() {
    const { data } = await supabase.from("platform_settings").select("value").eq("key","logo_url").single()
    if (data?.value) setLogoUrl(data.value)
  }

  async function uploadLogo(e) {
    const file = e.target.files[0]
    if (!file) return
    setUploadingLogo(true)
    try {
      const ext = file.name.split(".").pop()
      const path = `logo/platform_logo.${ext}`
      const { error } = await supabase.storage.from("platform-assets").upload(path, file, { upsert:true })
      if (error) throw error
      const { data } = supabase.storage.from("platform-assets").getPublicUrl(path)
      const url = data.publicUrl
      await supabase.from("platform_settings").upsert({ key:"logo_url", value:url, updated_at:new Date().toISOString() }, { onConflict:"key" })
      setLogoUrl(url)
      toast.success("Logo updated! Refresh to see changes everywhere.")
    } catch(err) { toast.error(err.message) }
    setUploadingLogo(false)
  }

  async function load() {
    const { data, error } = await supabase.from("app_settings").select("*").order("label")
    if (error) console.error("Settings load error:", error)
    setSettings(data||[])
    setLoading(false)
  }

  function startEdit(s) { setEditing(s.id); setForm({ value:s.value, description:s.description||"" }) }

  async function save() {
    if (!editing) return
    setSaving(true)
    try {
      const { error } = await supabase.from("app_settings").update({ value:form.value, description:form.description, updated_at:new Date().toISOString() }).eq("id", editing)
      if (error) throw error
      toast.success("Setting updated!")
      setEditing(null); load()
    } catch(e) { toast.error(e.message) }
    finally { setSaving(false) }
  }

  async function toggleBoolean(s) {
    setSaving(true)
    try {
      const newValue = s.value==="true" ? "false" : "true"
      const { error } = await supabase.from("app_settings").update({ value:newValue, updated_at:new Date().toISOString() }).eq("id", s.id)
      if (error) throw error
      toast.success(s.label+": "+(newValue==="true"?"enabled":"disabled"))
      load()
    } catch(e) { toast.error(e.message) }
    finally { setSaving(false) }
  }
  function formatValue(s) {
    if (s.type==="currency") return "KES "+Number(s.value).toLocaleString()
    if (s.type==="percentage") return s.value+"%"
    if (s.type==="boolean") return s.value==="true"?"Enabled":"Disabled"
    return s.value
  }

  function getCategory(key) {
    for (const [cat, config] of Object.entries(SETTING_CATEGORIES)) {
      if (config.keys.includes(key)) return cat
    }
    return "Other Settings"
  }

  const grouped = {}
  settings.forEach(s => { const cat = getCategory(s.key); if (!grouped[cat]) grouped[cat]=[]; grouped[cat].push(s) })
  const lastUpdated = settings.length>0 ? new Date(Math.max(...settings.map(s=>new Date(s.updated_at)))).toLocaleDateString() : "ΓÇö"

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:"#000", marginBottom:4 }}>Platform Settings</div>
      <div style={{ fontSize:12, color:"#888", marginBottom:"1.5rem" }}>Configure platform branding, fees, rates and settings</div>
      <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr 1fr":"1fr 1fr 1fr", gap:8, marginBottom:"1.5rem" }}>
        {[
          { label:"Total settings", value:settings.length, color:"#000" },
          { label:"Last updated", value:lastUpdated, color:"#378add" },
          { label:"Categories", value:Object.keys(grouped).length, color:"#8b5cf6" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.75rem", border:"1px solid #eee", textAlign:"center" }}>
            <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, color:s.color }}><span style={{ wordBreak:"break-all", fontSize:12 }}>{s.value||"ΓÇö"}</span></div>
            <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>
      {/* Settings Categories */}
      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading settings...</div>}
      {Object.entries(grouped).map(([category, catSettings]) => {
        const catConfig = SETTING_CATEGORIES[category] || { icon:"ΓÜÖ∩╕Å", color:"#888" }
        const isExpanded = expandedCat === category
        return (
          <div key={category} style={{ background:"#f8f8f8", border:"1px solid #eee", borderRadius:12, marginBottom:10, overflow:"hidden" }}>
            <button onClick={()=>setExpandedCat(isExpanded?null:category)}
              style={{ width:"100%", background:"none", border:"none", padding:"1rem", display:"flex", justifyContent:"space-between", alignItems:"center", cursor:"pointer" }}>
              <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                <div style={{ width:36, height:36, borderRadius:8, background:catConfig.color+"15", display:"flex", alignItems:"center", justifyContent:"center" }}>
                  {catConfig.icon==="wallet"?<WalletIcon size={18} color={catConfig.color}/>:
                   catConfig.icon==="emergency"?<GOServiceIcon size={18} color={catConfig.color}/>:
                   catConfig.icon==="vehicle"?<VehicleIcon size={18} color={catConfig.color}/>:
                   catConfig.icon==="shield"?<ShieldIcon size={18} color={catConfig.color}/>:
                   <SettingsIcon size={18} color={catConfig.color}/>}
                </div>
                <div style={{ textAlign:"left" }}>
                  <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#000" }}>{category}</div>
                  <div style={{ fontSize:11, color:"#888" }}>{catSettings.length} setting{catSettings.length!==1?"s":""}</div>
                </div>
              </div>
              <span style={{ color:"#e6821e", fontSize:16 }}>{isExpanded?"ΓêÆ":"+"}</span>
            </button>
            {isExpanded&&(
              <div style={{ borderTop:"1px solid #eee" }}>
                {catSettings.map(s=>(
                  <div key={s.id} style={{ padding:"0.75rem 1rem", borderBottom:"1px solid #eee", background:editing===s.id?"#fffbf7":"#fff" }}>
                    <div style={{ display:"flex", flexDirection:isMobile?"column":"row", justifyContent:"space-between", alignItems:isMobile?"flex-start":"center", gap:isMobile?8:0 }}>
                      <div style={{ flex:1, minWidth:0, marginRight:isMobile?0:8, wordBreak:"break-word" }}>
                        <div style={{ fontFamily:"Syne", fontSize:12, fontWeight:700, color:"#000", wordBreak:"break-word" }}>{s.label}</div>
                        {s.description&&<div style={{ fontSize:11, color:"#888", marginTop:1, wordBreak:"break-word" }}>{s.description}</div>}
                      </div>
                      <div style={{ display:"flex", alignItems:"center", gap:8, flexShrink:0, width:isMobile?"100%":"auto", justifyContent:isMobile?"space-between":"flex-start" }}>
                        <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:catConfig.color, wordBreak:"break-word", maxWidth:isMobile?"60%":"none" }}>{formatValue(s)}</div>
                        {s.type==="boolean" ? (
                          <button onClick={()=>toggleBoolean(s)} disabled={saving}
                            style={{ background:s.value==="true"?"#1d9e75":"#e5e5e5", border:"none", borderRadius:20, width:44, height:24, position:"relative", cursor:saving?"not-allowed":"pointer", transition:"background 0.2s", flexShrink:0 }}>
                            <div style={{ position:"absolute", top:2, left:s.value==="true"?22:2, width:20, height:20, borderRadius:"50%", background:"#fff", transition:"left 0.2s", boxShadow:"0 1px 3px rgba(0,0,0,0.3)" }}/>
                          </button>
                        ) : editing===s.id?(
                          <button onClick={()=>setEditing(null)} style={{ background:"none", border:"1px solid #ddd", borderRadius:6, color:"#888", fontSize:11, padding:"4px 8px", cursor:"pointer" }}>Cancel</button>
                        ):(
                          <button onClick={()=>startEdit(s)} style={{ background:"#f0f0f0", border:"none", borderRadius:6, color:"#555", fontSize:11, padding:"4px 8px", cursor:"pointer" }}>Edit</button>
                        )}
                      </div>
                    </div>
                    {editing===s.id&&(
                      <div style={{ marginTop:10 }}>
                        <input value={form.value} onChange={e=>setForm(f=>({...f,value:e.target.value}))}
                          style={{ width:"100%", background:"#f5f5f5", border:"1px solid #e6821e40", borderRadius:7, padding:"8px 10px", fontSize:13, outline:"none", marginBottom:8, boxSizing:"border-box" }}/>
                        <input value={form.description} onChange={e=>setForm(f=>({...f,description:e.target.value}))} placeholder="Description (optional)"
                          style={{ width:"100%", background:"#f5f5f5", border:"1px solid #eee", borderRadius:7, padding:"8px 10px", fontSize:12, outline:"none", marginBottom:8, boxSizing:"border-box" }}/>
                        <button onClick={save} disabled={saving}
                          style={{ background:"#e6821e", border:"none", borderRadius:7, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"8px 16px", cursor:saving?"not-allowed":"pointer" }}>
                          {saving?"Saving...":"Save changes"}
                        </button>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        )
      })}
    </div>
  )
}

import { BookingsIcon, PaymentsIcon, VehicleIcon, OrdersIcon, ProfileIcon, ServicesIcon, ChatIcon } from "../../lib/cccIcons"
import { useEffect, useState, useRef } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const SC = { open:"#e6821e", in_progress:"#378add", resolved:"#1d9e75", closed:"#555" }
const PC = { low:"#1d9e75", medium:"#e6821e", high:"#e24b4a", urgent:"#d4537e" }
const CAT_ICON = { booking:"bookings", payment:"payments", driver:"vehicle", parts:"orders", account:"profile", technical:"≡ƒöº", other:"≡ƒÆ¼" }

export default function AdminSupport() {
  const isMobile = useIsMobile()
  const { user } = useAuth()
  const [tickets, setTickets] = useState([])
  const [selected, setSelected] = useState(null)
  const [messages, setMessages] = useState([])
  const [reply, setReply] = useState("")
  const [sending, setSending] = useState(false)
  const [filter, setFilter] = useState("open")
  const [search, setSearch] = useState("")
  const [loading, setLoading] = useState(true)
  const messagesEndRef = useRef(null)

  useEffect(() => {
    load()
    const sub = supabase.channel("admin-support-live")
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"support_tickets" }, () => { load(); toast("New support ticket received!", { icon:"≡ƒÄ½" }) })
      .on("postgres_changes", { event:"UPDATE", schema:"public", table:"support_tickets" }, () => load())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [])

  useEffect(() => {
    if (!selected) return
    loadMessages(selected.id)
    const sub = supabase.channel("admin-ticket-"+selected.id)
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"support_messages", filter:`ticket_id=eq.${selected.id}` },
        payload => { setMessages(m=>[...m,payload.new]); setTimeout(()=>messagesEndRef.current?.scrollIntoView({behavior:"smooth"}),100) })
      .on("postgres_changes", { event:"UPDATE", schema:"public", table:"support_tickets", filter:`id=eq.${selected.id}` },
        payload => setSelected(prev=>({...prev,...payload.new})))
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [selected?.id])

  async function load() {
    const { data } = await supabase.from("support_tickets")
      .select("*, customer:profiles!support_tickets_customer_id_fkey(first_name,last_name,role), user:profiles!support_tickets_user_id_fkey(first_name,last_name,role)")
      .order("created_at", { ascending:false })
    setTickets(data||[])
    setLoading(false)
  }

  async function loadMessages(ticketId) {
    const { data } = await supabase.from("support_messages")
      .select("*, sender:profiles!support_messages_sender_id_fkey(first_name,last_name,role)")
      .eq("ticket_id", ticketId).order("created_at", { ascending:true })
    setMessages(data||[])
    setTimeout(()=>messagesEndRef.current?.scrollIntoView({behavior:"smooth"}),100)
  }

  async function sendReply(e) {
    e.preventDefault()
    if (!reply.trim() || !selected) return
    setSending(true)
    const { error } = await supabase.from("support_messages").insert({
      ticket_id: selected.id, sender_id: user.id, message: reply.trim(), is_staff: true
    })
    if (error) { toast.error(error.message); setSending(false); return }
    await supabase.from("support_tickets").update({ status:"in_progress", updated_at:new Date().toISOString() }).eq("id", selected.id)
    await supabase.from("notifications").insert({
      user_id: selected.customer_id,
      title: "Support reply ≡ƒÆ¼",
      message: "Your ticket #"+selected.ticket_number+" has a new reply from our support team.",
      type: "info"
    })
    setReply(""); setSending(false)
  }

  async function updateStatus(ticketId, status) {
    const updates = { status, updated_at:new Date().toISOString() }
    if (status==="resolved") updates.resolved_at = new Date().toISOString()
    await supabase.from("support_tickets").update(updates).eq("id", ticketId)
    const ticket = tickets.find(t=>t.id===ticketId)
    if (ticket) {
      const msg = status==="resolved" ? "Your support ticket #"+ticket.ticket_number+" has been resolved. Please rate our support." : "Your ticket #"+ticket.ticket_number+" status updated to "+status+"."
      await supabase.from("notifications").insert({ user_id: ticket.customer_id, title: "Ticket "+status+" "+( status==="resolved"?"Γ£à":"≡ƒôï"), message: msg, type: status==="resolved"?"success":"info" })
    }
    if (selected?.id === ticketId) setSelected(s=>({...s,status}))
    load(); toast.success("Status updated to "+status)
  }

  async function updatePriority(ticketId, priority) {
    await supabase.from("support_tickets").update({ priority, updated_at:new Date().toISOString() }).eq("id", ticketId)
    if (selected?.id === ticketId) setSelected(s=>({...s,priority}))
    load(); toast.success("Priority updated")
  }

  const filtered = tickets.filter(t => {
    const matchFilter = filter==="all" || t.status===filter
    const matchSearch = !search || (t.subject+t.ticket_number+(t.customer?.first_name||"")+(t.customer?.last_name||"")).toLowerCase().includes(search.toLowerCase())
    return matchFilter && matchSearch
  })

  const stats = {
    open: tickets.filter(t=>t.status==="open").length,
    in_progress: tickets.filter(t=>t.status==="in_progress").length,
    resolved: tickets.filter(t=>t.status==="resolved").length,
    high: tickets.filter(t=>t.priority==="high"&&(t.status==="open"||t.status==="in_progress")).length,
  }

  if (selected) return (
    <div style={{ display:"flex", flexDirection:"column", height:isMobile?"calc(100vh-120px)":"calc(100vh-140px)" }}>
      <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:"1rem", flexShrink:0, flexWrap:"wrap" }}>
        <button onClick={()=>setSelected(null)} style={{ background:"none", border:"none", color:"#e6821e", cursor:"pointer", fontSize:13, padding:0 }}>ΓåÉ Back</button>
        <div style={{ flex:1 }}>
          <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:800 }}>{selected.subject}</div>
          <div style={{ fontSize:11, color:"#888" }}>
            #{selected.ticket_number} ┬╖ {CAT_ICON[selected.category]} {selected.category}
            ┬╖ {selected.customer?.first_name} {selected.customer?.last_name}
          </div>
        </div>
      </div>
      {/* Status + Priority controls */}
      <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexShrink:0, flexWrap:"wrap" }}>
        <div style={{ fontSize:11, color:"#666", alignSelf:"center" }}>Status:</div>
        {["open","in_progress","resolved","closed"].map(s=>(
          <button key={s} onClick={()=>updateStatus(selected.id,s)}
            style={{ padding:"4px 10px", borderRadius:6, border:"1px solid "+(selected.status===s?SC[s]:"#eee"), background:selected.status===s?SC[s]+"20":"#f8f8f8", color:selected.status===s?SC[s]:"#888", fontSize:11, cursor:"pointer", fontWeight:selected.status===s?700:400 }}>
            {s.replace("_"," ")}
          </button>
        ))}
        <div style={{ fontSize:11, color:"#666", alignSelf:"center", marginLeft:8 }}>Priority:</div>
        {["low","medium","high"].map(p=>(
          <button key={p} onClick={()=>updatePriority(selected.id,p)}
            style={{ padding:"4px 10px", borderRadius:6, border:"1px solid "+(selected.priority===p?PC[p]:"#eee"), background:selected.priority===p?PC[p]+"20":"#f8f8f8", color:selected.priority===p?PC[p]:"#888", fontSize:11, cursor:"pointer", fontWeight:selected.priority===p?700:400 }}>
            {p}
          </button>
        ))}
      </div>
      {/* Messages */}
      <div style={{ flex:1, overflowY:"auto", paddingBottom:"0.5rem", marginBottom:"0.5rem" }}>
        {messages.map(m=>{
          const isStaff = m.is_staff
          return (
            <div key={m.id} style={{ display:"flex", justifyContent:isStaff?"flex-end":"flex-start", marginBottom:8 }}>
              <div style={{ maxWidth:"80%", background:isStaff?"#378add":m.sender?.role==="admin"?"#e6821e20":"#f5f5f5", borderRadius:isStaff?"12px 12px 4px 12px":"12px 12px 12px 4px", padding:"10px 14px" }}>
                <div style={{ fontSize:10, color:isStaff?"rgba(255,255,255,0.8)":"#aaa", marginBottom:4 }}>
                  {isStaff?"≡ƒÄ½ Support Staff":"≡ƒæñ "+( m.sender?.first_name||"Customer")}
                </div>
                <div style={{ fontSize:13, color:isStaff?"#fff":"#000", lineHeight:1.5 }}>{m.message}</div>
                <div style={{ fontSize:10, color:isStaff?"rgba(255,255,255,0.6)":"#aaa", marginTop:4, textAlign:"right" }}>{new Date(m.created_at).toLocaleString()}</div>
              </div>
            </div>
          )
        })}
        <div ref={messagesEndRef}/>
      </div>
      {/* Reply */}
      {(selected.status==="open"||selected.status==="in_progress") ? (
        <form onSubmit={sendReply} style={{ display:"flex", gap:8, flexShrink:0 }}>
          <input value={reply} onChange={e=>setReply(e.target.value)} placeholder="Type your reply..."
            style={{ flex:1, background:"#f5f5f5", border:"1px solid #e0e0e0", borderRadius:10, padding:"10px 14px", fontSize:13, outline:"none" }}/>
          <button type="submit" disabled={sending||!reply.trim()} style={{ background:"#378add", border:"none", borderRadius:10, color:"#fff", padding:"10px 16px", cursor:"pointer", fontSize:13, fontWeight:700 }}>
            {sending?"...":"Reply"}
          </button>
        </form>
      ) : (
        <div style={{ textAlign:"center", fontSize:12, color:"#888", padding:"0.75rem", background:"#f5f5f5", borderRadius:10 }}>
          Ticket is {selected.status}. Change status to reply.
        </div>
      )}
    </div>
  )

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:"#000", marginBottom:"1rem" }}>≡ƒÄ½ Support Tickets</div>
      {/* Stats */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:8, marginBottom:"1rem" }}>
        {[
          { label:"Open", value:stats.open, color:"#e6821e" },
          { label:"In progress", value:stats.in_progress, color:"#378add" },
          { label:"Resolved", value:stats.resolved, color:"#1d9e75" },
          { label:"High priority", value:stats.high, color:"#e24b4a" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.75rem", textAlign:"center", border:"1px solid #eee" }}>
            <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>
      {/* Search */}
      <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search tickets, customers..."
        style={{ width:"100%", background:"#f8f8f8", border:"1px solid #eee", borderRadius:8, padding:"9px 12px", fontSize:13, outline:"none", marginBottom:"0.75rem", boxSizing:"border-box" }}/>
      {/* Filter tabs */}
      <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap" }}>
        {[["all","All"],["open","Open"],["in_progress","In Progress"],["resolved","Resolved"],["closed","Closed"]].map(([k,l])=>(
          <button key={k} onClick={()=>setFilter(k)}
            style={{ padding:"6px 12px", borderRadius:7, border:"none", fontSize:12, cursor:"pointer", background:filter===k?"#e6821e":"#f8f8f8", color:filter===k?"#fff":"#666", fontWeight:filter===k?700:400 }}>
            {l} {k!=="all"&&tickets.filter(t=>t.status===k).length>0&&"("+tickets.filter(t=>t.status===k).length+")"}
          </button>
        ))}
      </div>
      {/* Ticket list */}
      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
      {!loading&&filtered.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No tickets found</div>}
      {filtered.map(t=>(
        <div key={t.id} onClick={()=>setSelected(t)}
          style={{ background:"#f8f8f8", border:`1px solid ${SC[t.status]||"#eee"}30`, borderRadius:10, padding:"1rem", marginBottom:8, cursor:"pointer", borderLeft:`3px solid ${SC[t.status]||"#eee"}` }}
          onMouseEnter={e=>e.currentTarget.style.background="#f0f0f0"}
          onMouseLeave={e=>e.currentTarget.style.background="#f8f8f8"}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
            <div style={{ flex:1, minWidth:0, marginRight:8 }}>
              <div style={{ display:"flex", gap:6, alignItems:"center", marginBottom:2 }}>
                {t.priority==="high"&&<span style={{ fontSize:10, background:"#e24b4a20", color:"#e24b4a", padding:"1px 6px", borderRadius:4, fontWeight:700 }}>≡ƒö┤ HIGH</span>}
                <span style={{ fontSize:13, fontWeight:700, color:"#000" }}>{t.subject}</span>
              </div>
              <div style={{ fontSize:11, color:"#888" }}>
                {CAT_ICON[t.category]} {t.category} ┬╖ ≡ƒæñ {t.customer?.first_name} {t.customer?.last_name}
              </div>
              <div style={{ fontSize:11, color:"#aaa", marginTop:2 }}>#{t.ticket_number} ┬╖ {new Date(t.created_at).toLocaleDateString()}</div>
            </div>
            <div style={{ textAlign:"right", flexShrink:0 }}>
              <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:(SC[t.status]||"#888")+"20", color:SC[t.status]||"#888", fontWeight:600, display:"block", marginBottom:4 }}>{t.status?.replace("_"," ")}</span>
              <span style={{ fontSize:11, color:"#e6821e" }}>View ΓåÆ</span>
            </div>
          </div>
        </div>
      ))}
    </div>
  )
}

import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const TABLES = ["profiles","bookings","services","inventory","orders","order_items","delivery_zones","notifications","reviews","support_tickets","service_claims","marketplace_listings","employees","commission_rates","error_logs"]

const ROUTES = [
  { path:"/dashboard", role:"customer", desc:"Customer dashboard" },
  { path:"/dashboard/bookings", role:"customer", desc:"Customer bookings" },
  { path:"/dashboard/parts", role:"customer", desc:"Parts marketplace" },
  { path:"/provider-dashboard", role:"provider", desc:"Provider dashboard" },
  { path:"/provider-dashboard/inventory", role:"provider", desc:"Provider inventory" },
  { path:"/provider-dashboard/orders", role:"provider", desc:"Provider orders" },
  { path:"/driver-dashboard", role:"driver", desc:"Driver dashboard" },
  { path:"/driver-dashboard/deliveries", role:"driver", desc:"Driver deliveries" },
]

export default function AdminSystemDiagnostics() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const isMobile = useIsMobile()
  const [running, setRunning] = useState(false)
  const [results, setResults] = useState(null)
  const [errorLogs, setErrorLogs] = useState([])
  const [loadingLogs, setLoadingLogs] = useState(false)
  const [tab, setTab] = useState("diagnostics")

  useEffect(() => { loadErrorLogs() }, [])

  async function loadErrorLogs() {
    setLoadingLogs(true)
    const { data } = await supabase.from("error_logs").select("*").order("created_at",{ascending:false}).limit(50)
    setErrorLogs(data||[])
    setLoadingLogs(false)
  }

  async function clearLogs() {
    await supabase.from("error_logs").delete().neq("id","00000000-0000-0000-0000-000000000000")
    setErrorLogs([])
    toast.success("Logs cleared")
  }

  async function runDiagnostics() {
    setRunning(true)
    const r = { tables:{}, policies:{}, queries:{}, users:{}, fixes:[] }

    // 1. Check all tables exist
    for (const table of TABLES) {
      try {
        const { error } = await supabase.from(table).select("id").limit(1)
        r.tables[table] = error ? { ok:false, error:error.message, code:error.code } : { ok:true }
        if (error) r.fixes.push({ severity:"≡ƒö┤", issue:`Table ${table}: ${error.message}`, fix:`Check if table exists in Supabase dashboard` })
      } catch(e) { r.tables[table] = { ok:false, error:e.message } }
    }

    // 2. Check profiles query (most critical)
    try {
      const { data:{ session } } = await supabase.auth.getSession()
      if (session?.user) {
        const { data, error } = await supabase.from("profiles").select("*").eq("id",session.user.id).maybeSingle()
        r.queries.profileFetch = { ok:!error, data:data?{role:data.role,type:data.provider_type}:null, error:error?.message }
        if (error) r.fixes.push({ severity:"≡ƒö┤", issue:`Profile fetch failed: ${error.message}`, fix:`Check profiles RLS policies` })
        if (!data) r.fixes.push({ severity:"≡ƒö┤", issue:"Profile not found for current user", fix:`Run: insert into profiles (id,role) values ('${session.user.id}','admin')` })
      } else {
        r.queries.profileFetch = { ok:false, error:"No session" }
      }
    } catch(e) { r.queries.profileFetch = { ok:false, error:e.message } }

    // 3. Check inventory RLS
    try {
      const { error } = await supabase.from("inventory").select("id").limit(1)
      r.queries.inventorySelect = { ok:!error, error:error?.message }
      if (error) r.fixes.push({ severity:"≡ƒö┤", issue:`Inventory select failed: ${error.message}`, fix:`Run: create policy "inventory_select_all" on public.inventory for select to authenticated using (true)` })
    } catch(e) { r.queries.inventorySelect = { ok:false, error:e.message } }

    // 4. Check orders RLS
    try {
      const { error } = await supabase.from("orders").select("id").limit(1)
      r.queries.ordersSelect = { ok:!error, error:error?.message }
      if (error) r.fixes.push({ severity:"≡ƒö┤", issue:`Orders select failed: ${error.message}`, fix:`Run: create policy "orders_select_all" on public.orders for select to authenticated using (customer_id=auth.uid() or provider_id=auth.uid() or public.is_admin())` })
    } catch(e) { r.queries.ordersSelect = { ok:false, error:e.message } }

    // 5. Check user counts
    try {
      const [{ count:customers },{ count:providers },{ count:drivers },{ count:admins }] = await Promise.all([
        supabase.from("profiles").select("id",{count:"exact",head:true}).eq("role","customer"),
        supabase.from("profiles").select("id",{count:"exact",head:true}).eq("role","provider"),
        supabase.from("profiles").select("id",{count:"exact",head:true}).eq("role","driver"),
        supabase.from("profiles").select("id",{count:"exact",head:true}).eq("role","admin"),
      ])
      r.users = { customers:customers||0, providers:providers||0, drivers:drivers||0, admins:admins||0 }
    } catch(e) { r.users = { error:e.message } }

    // 6. Check provider types
    try {
      const { data } = await supabase.from("profiles").select("provider_type").eq("role","provider")
      const types = (data||[]).reduce((acc,p)=>{ acc[p.provider_type||"garage"]=(acc[p.provider_type||"garage"]||0)+1; return acc },{})
      r.providerTypes = types
    } catch(e) { r.providerTypes = {} }

    // 7. Check storage buckets
    try {
      const { data, error } = await supabase.storage.listBuckets()
      r.storage = { ok:!error, buckets:(data||[]).map(b=>b.name) }
      const requiredBuckets = ["provider-photos","driver-documents","vehicle-images","inventory-photos"]
      requiredBuckets.forEach(b => {
        if (!r.storage.buckets?.includes(b)) {
          r.fixes.push({ severity:"≡ƒƒí", issue:`Storage bucket missing: ${b}`, fix:`Create bucket "${b}" in Supabase Storage` })
        }
      })
    } catch(e) { r.storage = { ok:false, error:e.message } }

    if (r.fixes.length===0) r.fixes.push({ severity:"Γ£à", issue:"No issues found!", fix:"Platform looks healthy" })

    setResults(r)
    setRunning(false)
  }

  const SC = { "≡ƒö┤":"#e24b4a", "≡ƒƒí":"#e6821e", "Γ£à":"#1d9e75" }

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:"#000000", marginBottom:4 }}>System Diagnostics</div>
      <div style={{ fontSize:12, color:"#888", marginBottom:"1.5rem" }}>Full platform health check and error tracking</div>

      <div style={{ display:"flex", gap:6, marginBottom:"1.5rem" }}>
        {[{k:"diagnostics",l:"Diagnostics"},{k:"errors",l:`Error Log (${errorLogs.length})`},{k:"fixes",l:"Auto-fixes"}].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{ padding:"7px 14px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#8b5cf6":"#f8f8f8", color:tab===t.k?"#fff":"#666", fontWeight:tab===t.k?700:400 }}>
            {t.l}
          </button>
        ))}
      </div>

      {tab==="diagnostics"&&(
        <div>
          <button onClick={runDiagnostics} disabled={running}
            style={{ background:running?"#e0e0e0":"#8b5cf6", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700, padding:"12px 28px", cursor:running?"not-allowed":"pointer", marginBottom:"1.5rem", width:"100%" }}>
            {running?"≡ƒöì Running diagnostics...":"≡ƒöì Run full diagnostics"}
          </button>

          {results&&(
            <div>
              {/* User counts */}
              <div style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:12, padding:"1rem", marginBottom:"1rem" }}>
                <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#000000", marginBottom:8 }}>≡ƒæÑ Users</div>
                <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:8 }}>
                  {Object.entries(results.users||{}).filter(([k])=>k!=="error").map(([k,v])=>(
                    <div key={k} style={{ background:"#ffffff", borderRadius:8, padding:"0.5rem", textAlign:"center" }}>
                      <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, color:"#e6821e" }}>{v}</div>
                      <div style={{ fontSize:9, color:"#888" }}>{k}</div>
                    </div>
                  ))}
                </div>
                {results.providerTypes&&Object.keys(results.providerTypes).length>0&&(
                  <div style={{ marginTop:8, fontSize:11, color:"#888" }}>
                    Provider types: {Object.entries(results.providerTypes).map(([k,v])=>`${k}(${v})`).join(", ")}
                  </div>
                )}
              </div>

              {/* Table status */}
              <div style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:12, padding:"1rem", marginBottom:"1rem" }}>
                <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#000000", marginBottom:8 }}>≡ƒùä∩╕Å Tables</div>
                <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(140px,1fr))", gap:6 }}>
                  {Object.entries(results.tables||{}).map(([table,status])=>(
                    <div key={table} style={{ background:"#ffffff", borderRadius:8, padding:"6px 8px", display:"flex", alignItems:"center", gap:6 }}>
                      <span style={{ fontSize:10 }}>{status.ok?"Γ£à":"Γ¥î"}</span>
                      <span style={{ fontSize:11, color:status.ok?"#888":"#e24b4a" }}>{table}</span>
                    </div>
                  ))}
                </div>
              </div>

              {/* Query tests */}
              <div style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:12, padding:"1rem", marginBottom:"1rem" }}>
                <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#000000", marginBottom:8 }}>≡ƒöî Query Tests</div>
                {Object.entries(results.queries||{}).map(([query,status])=>(
                  <div key={query} style={{ display:"flex", justifyContent:"space-between", padding:"6px 0", borderBottom:"1px solid #f5f5f5" }}>
                    <span style={{ fontSize:12, color:"#888" }}>{query}</span>
                    <div style={{ textAlign:"right" }}>
                      <span style={{ fontSize:10, color:status.ok?"#1d9e75":"#e24b4a", fontWeight:600 }}>{status.ok?"Γ£à OK":"Γ¥î FAIL"}</span>
                      {!status.ok&&<div style={{ fontSize:10, color:"#e24b4a" }}>{status.error}</div>}
                      {status.data&&<div style={{ fontSize:10, color:"#888" }}>{JSON.stringify(status.data)}</div>}
                    </div>
                  </div>
                ))}
              </div>

              {/* Storage */}
              <div style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:12, padding:"1rem" }}>
                <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#000000", marginBottom:8 }}>≡ƒôª Storage Buckets</div>
                <div style={{ fontSize:12, color:results.storage?.ok?"#1d9e75":"#e24b4a" }}>
                  {results.storage?.buckets?.join(", ")||results.storage?.error}
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {tab==="errors"&&(
        <div>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1rem" }}>
            <div style={{ fontSize:12, color:"#888" }}>{errorLogs.length} errors logged</div>
            <div style={{ display:"flex", gap:8 }}>
              <button onClick={loadErrorLogs} style={{ background:"#f8f8f8", border:"1px solid #dddddd", borderRadius:7, color:"#888", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>Refresh</button>
              {errorLogs.length>0&&<button onClick={clearLogs} style={{ background:"#fff5f5", border:"1px solid #e24b4a30", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>Clear all</button>}
            </div>
          </div>
          {errorLogs.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No errors logged yet</div>}
          {errorLogs.map((e,i)=>(
            <div key={e.id||i} style={{ background:"#f8f8f8", border:"1px solid #e24b4a20", borderRadius:10, padding:"0.75rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", marginBottom:4, flexWrap:"wrap", gap:4 }}>
                <span style={{ fontSize:11, color:"#e24b4a", fontWeight:600 }}>
                  {e.user_role||"unknown"} {e.provider_type?"("+e.provider_type+")":""} ┬╖ {e.page_url}
                </span>
                <span style={{ fontSize:10, color:"#888" }}>{new Date(e.created_at).toLocaleString()}</span>
              </div>
              <div style={{ fontSize:12, color:"#000000", marginBottom:4, fontFamily:"monospace", wordBreak:"break-all" }}>{e.error_message}</div>
              <div style={{ fontSize:10, color:"#888" }}>{e.error_source} ┬╖ line {e.error_line}:{e.error_col}</div>
            </div>
          ))}
        </div>
      )}

      {tab==="fixes"&&(
        <div>
          <div style={{ fontSize:12, color:"#888", marginBottom:"1rem" }}>
            {results ? `${results.fixes?.length||0} issues found` : "Run diagnostics first to see fixes"}
          </div>
          {!results&&<button onClick={runDiagnostics} style={{ background:"#8b5cf6", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne", fontSize:13, fontWeight:700, padding:"10px 24px", cursor:"pointer" }}>Run diagnostics first</button>}
          {results?.fixes?.map((fix,i)=>(
            <div key={i} style={{ background:"#f8f8f8", border:`1px solid ${SC[fix.severity]||"#eeeeee"}30`, borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ fontSize:13, fontWeight:600, color:SC[fix.severity]||"#888", marginBottom:6 }}>{fix.severity} {fix.issue}</div>
              <div style={{ fontSize:12, color:"#888", fontFamily:"monospace", background:"#ffffff", padding:"8px", borderRadius:6, wordBreak:"break-all" }}>{fix.fix}</div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}
import { useAuth } from "../../contexts/AuthContext"

import { VehicleIcon, LocationIcon, TripReportIcon } from "../../lib/cccIcons"
import { useEffect, useState } from "react"
import { useAuth } from "../../contexts/AuthContext"
import { supabase } from "../../lib/supabase"

export default function AdminTripReports() {
  const { user, profile } = useAuth()
  if (!user || profile?.role !== "admin") return null
  const [bookings, setBookings] = useState([])
  const [selected, setSelected] = useState(null)
  const [logs, setLogs] = useState([])
  const [loading, setLoading] = useState(true)
  const [loadingLogs, setLoadingLogs] = useState(false)
  const [search, setSearch] = useState("")

  useEffect(() => { load() }, [])

  async function load() {
    const { data } = await supabase.from("bookings")
      .select("*, customer:profiles!bookings_customer_id_fkey(first_name,last_name), driver:profiles!bookings_driver_id_fkey(first_name,last_name,driver_vehicle_type,driver_category), vehicles(make,model,license_plate)")
      .not("driver_id","is",null)
      .order("created_at",{ascending:false})
      .limit(50)
    setBookings(data||[])
    setLoading(false)
  }

  async function loadLogs(booking) {
    setSelected(booking)
    setLoadingLogs(true)
    const { data } = await supabase.from("booking_location_logs")
      .select("*").eq("booking_id", booking.id)
      .order("recorded_at",{ascending:true})
    setLogs(data||[])
    setLoadingLogs(false)
  }

  function calcDistance(logs) {
    if (logs.length < 2) return 0
    let total = 0
    for (let i=1;i<logs.length;i++) {
      const R=6371,dLat=(logs[i].lat-logs[i-1].lat)*Math.PI/180,dLng=(logs[i].lng-logs[i-1].lng)*Math.PI/180
      const a=Math.sin(dLat/2)**2+Math.cos(logs[i-1].lat*Math.PI/180)*Math.cos(logs[i].lat*Math.PI/180)*Math.sin(dLng/2)**2
      total+=R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))
    }
    return total.toFixed(1)
  }

  function calcDuration(logs) {
    if (logs.length<2) return "ΓÇö"
    const mins=Math.round((new Date(logs[logs.length-1].recorded_at)-new Date(logs[0].recorded_at))/60000)
    return mins<60?mins+"min":Math.floor(mins/60)+"h "+(mins%60)+"min"
  }

  const filtered = bookings.filter(b=>`${b.customer?.first_name} ${b.customer?.last_name} ${b.driver?.first_name} ${b.driver?.last_name} ${b.booking_number} ${b.service_name}`.toLowerCase().includes(search.toLowerCase()))
  const SC = { pending:"#e6821e", confirmed:"#378add", "in-progress":"#8b5cf6", completed:"#1d9e75", cancelled:"#e24b4a" }

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:"#000", marginBottom:"1rem" }}>≡ƒôì Admin Trip Reports</div>
      {selected ? (
        <div>
          <button onClick={()=>{ setSelected(null); setLogs([]) }} style={{ background:"none", border:"none", color:"#e6821e", cursor:"pointer", fontSize:13, marginBottom:"1rem", padding:0 }}>ΓåÉ Back</button>
          <div style={{ background:"#f8f8f8", borderRadius:12, padding:"1rem", marginBottom:"1rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800 }}>{selected.service_name}</div>
            <div style={{ fontSize:11, color:"#888" }}>#{selected.booking_number} ┬╖ {selected.booking_date}</div>
            <div style={{ fontSize:11, color:"#888" }}>Customer: {selected.customer?.first_name} {selected.customer?.last_name}</div>
            <div style={{ fontSize:11, color:"#378add" }}>Driver: {selected.driver?.first_name} {selected.driver?.last_name} ┬╖ {selected.driver?.driver_category==="concierge"?"≡ƒºæΓÇìΓ£ê∩╕Å":"≡ƒÜù"}</div>
            {selected.vehicles&&<div style={{ fontSize:11, color:"#888", display:"flex", alignItems:"center", gap:3 }}><VehicleIcon size={11} color="#888"/> {selected.vehicles.make} {selected.vehicles.model} ┬╖ {selected.vehicles.license_plate}</div>}
          </div>
          {loadingLogs?(
            <div style={{ color:"#888", fontSize:13, padding:"2rem", textAlign:"center" }}>Loading GPS data...</div>
          ):logs.length===0?(
            <div style={{ color:"#888", fontSize:13, padding:"2rem", textAlign:"center" }}>≡ƒôì No GPS data for this booking</div>
          ):(
            <div>
              <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:8, marginBottom:"1rem" }}>
                {[{label:"Distance",value:calcDistance(logs)+" km"},{label:"Duration",value:calcDuration(logs)},{label:"GPS points",value:logs.length}].map(s=>(
                  <div key={s.label} style={{ background:"#fff", border:"1px solid #eee", borderRadius:10, padding:"0.75rem", textAlign:"center" }}>
