import { useAuth } from "../../contexts/AuthContext"

import { ProfileIcon, CheckIcon } from "../../lib/cccIcons"
import useIsMobile from "../../lib/useIsMobile"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { auditLog, AUDIT_ACTIONS } from "../../lib/auditLog"
import { useAuth } from "../../contexts/AuthContext"
import AdminUserDetail from "./AdminUserDetail"
import toast from "react-hot-toast"

export default function AdminUsers() {
  const isMobile = useIsMobile()
  const [users, setUsers] = useState([])
  const [filter, setFilter] = useState("all")
  const [search, setSearch] = useState("")
  const [loading, setLoading] = useState(true)
  const [selected, setSelected] = useState(null)
  const [viewingUser, setViewingUser] = useState(null)

  useEffect(() => { load() }, [])

  async function load() {
    const { data } = await supabase.from("profiles")
      .select("*").order("created_at",{ascending:false})
    if (data?.length) {
      const { data: sensitive } = await supabase.from("profile_sensitive")
        .select("id,email,phone").in("id", data.map(u=>u.id))
      const merged = data.map(u => ({
        ...u,
        email: sensitive?.find(s=>s.id===u.id)?.email || "",
        phone: sensitive?.find(s=>s.id===u.id)?.phone || ""
      }))
      setUsers(merged)
    } else {
      setUsers([])
    }
    setLoading(false)
  }

  async function toggleActive(id, is_active) {
    await supabase.from("profiles").update({ is_active:!is_active }).eq("id",id)
    await supabase.from("notifications").insert({
      user_id: id,
      title: is_active ? "Account suspended ΓÜá∩╕Å" : "Account reactivated Γ£à",
      message: is_active
        ? "Your Car Care Connect account has been suspended by admin. Contact support if you believe this is an error."
        : "Your Car Care Connect account has been reactivated. You can now sign in normally.",
      type: is_active ? "error" : "success"
    })
    toast.success(is_active ? "User suspended ΓÇö notified" : "User activated ΓÇö notified")
    load()
  }

  async function toggleVerified(id, is_verified) {
    await supabase.from("profiles").update({ is_verified:!is_verified, documents_verified:!is_verified }).eq("id",id)
    toast.success(is_verified?"Verification removed":"User verified")
    load()
  }

  async function deleteUser(id, name, email) {
    if (!confirm(`Delete ${name}? This will anonymize their profile and permanently disable their login - it will NOT remove their bookings, orders, payments, or reviews, which are kept for financial/record-keeping reasons.`)) return
    if (!confirm(`Are you absolutely sure you want to delete ${name}? This cannot be undone.`)) return
    try {
      // Notify user before deletion
      await supabase.from("notifications").insert({
        user_id: id,
        title: "Account deleted",
        message: "Your Car Care Connect account has been permanently deleted by admin. Contact carcareconnect254@gmail.com if you have questions.",
        type: "error"
      })
      // Anonymizes the profile and disables the login - does not hard-delete,
      // since dozens of tables (bookings, orders, payments, reviews) require this
      // profile's related history to remain intact.
      const { error } = await supabase.rpc("delete_user_account", { user_id: id })
      if (error) throw error
      toast.success(`${name} deleted`)
      setSelected(null)
      load()
    } catch(err) {
      toast.error(err.message)
    }
  }

  async function resetPassword(email) {
    const { error } = await supabase.auth.resetPasswordForEmail(email, {
      redirectTo: `${window.location.origin}/auth`
    })
    if (error) return toast.error(error.message)
    toast.success(`Password reset email sent to ${email}`)
  }

