                style={{ background:"none", border:"1px solid #e24b4a40", borderRadius:7, color:"#e24b4a", fontSize:12, padding:"6px 12px", cursor:"pointer" }}>
                Delete user
              </button>
            </div>
          )}
        </div>
      ))}
    </div>
  )
}

