const LoginSheet = memo(function LoginSheet({ isMobile, onClose }) {
  const { signIn } = useAuth()
  const navigate = useNavigate()
  const [form, setForm] = useState({ email:"", password:"" })
  const [loading, setLoading] = useState(false)
  const [showPassword, setShowPassword] = useState(false)

  async function handleSubmit(e) {
    e.preventDefault()
    setLoading(true)
    try {
      await signIn({ email: form.email, password: form.password })
      await new Promise(r => setTimeout(r, 1000))
      let { data: { user } } = await supabase.auth.getUser()
      if (!user) {
        await new Promise(r => setTimeout(r, 1000))
        const retry = await supabase.auth.getUser()
        user = retry.data.user
      }
      if (!user) { toast.error("Session error ΓÇö try again"); setLoading(false); return }
      const { data: profile } = await supabase.from("profiles").select("role").eq("id", user.id).maybeSingle()
      if (profile?.role !== "admin") {
        await supabase.auth.signOut()
        toast.error("Access denied ΓÇö not an admin account")
        setLoading(false)
        return
      }
      window.location.href = "/admin-dashboard"
    } catch(err) {
      toast.error(err.message || "Invalid credentials")
    } finally {
      setLoading(false)
    }
  }

  const inp = (extra={}) => ({
    width:"100%", background:"#555555", border:"1px solid #eeeeee", borderRadius:10,
