          {!isMobile&&(
            <button onClick={onClose} style={{ background:"#ffffff", border:"none", borderRadius:"50%", width:32, height:32, color:"#666", cursor:"pointer", fontSize:18, display:"flex", alignItems:"center", justifyContent:"center" }}>├ù</button>
          )}
