import { GOServiceIcon, ServicesIcon, DiscoverIcon, MarketplaceIcon, LocationIcon, ShieldIcon, ShareIcon, PaymentsIcon, DeleteIcon, VehicleIcon, ChatIcon, DownloadIcon, DeliveryIcon, WarningIcon } from "../../lib/cccIcons"


import { downloadInvoice, downloadBookingsCSV } from "../../lib/invoice"
import ChatWindow from "../shared/ChatWindow"

const SC = { pending:"#e6821e", confirmed:"#378add", "in-progress":"#8b5cf6", completed:"#1d9e75", cancelled:"#e24b4a" }
const SB = { pending:"#fff8f0", confirmed:"#eff6ff", "in-progress":"#faf5ff", completed:"#f0fdf4", cancelled:"#fff5f5" }

export default function CustomerBookings() {
  const { user } = useAuth()
  const navigate = useNavigate()
  const { t } = useLanguage()
  const isMobile = useIsMobile()
  const [bookings, setBookings] = useState([])
  const [openClaimBookingIds, setOpenClaimBookingIds] = useState(new Set())
  const [filter, setFilter] = useState("all")
  const [loading, setLoading] = useState(true)
  const [expanded, setExpanded] = useState(null)
  const [rebooking, setRebooking] = useState(null)
  const [serviceFeeBooking, setServiceFeeBooking] = useState(null)
  const [search, setSearch] = useState("")
  const [invoiceLoading, setInvoiceLoading] = useState(null)
  const [driverInfo, setDriverInfo] = useState({})
  const [providerPhones, setProviderPhones] = useState({})
  const [chatBooking, setChatBooking] = useState(null)

  async function loadProviderPhone(providerId, bookingId) {
    if (!providerId || providerPhones[bookingId]) return
    const [{ data: sens }, { data: prof }] = await Promise.all([
      supabase.from("profile_sensitive").select("phone").eq("id", providerId).single(),
      supabase.from("profiles").select("first_name,last_name,business_name").eq("id", providerId).single(),
    ])
    setProviderPhones(prev=>({...prev,[bookingId]:{ phone:sens?.phone, name:prof?.business_name||(prof?.first_name+" "+prof?.last_name) }}))
  }

  async function loadDriverInfo(driverId, bookingId) {
    if (!driverId || driverInfo[bookingId]) return
    const [{ data: driver }, { data: status }] = await Promise.all([
      supabase.from("profiles").select("first_name,last_name").eq("id",driverId).single(),
      supabase.from("driver_status").select("is_online,current_booking_id").eq("driver_id",driverId).maybeSingle(),
    ])
    if (driver) setDriverInfo(prev=>({...prev,[bookingId]:{...driver,...status}}))
  }

  async function downloadBookingInvoice(booking) {
    setInvoiceLoading(booking.id)
    try {
      const [{ data: provider }, { data: customer }, { data: mechanic }] = await Promise.all([
        supabase.from("profiles").select("*").eq("id", booking.provider_id).single(),
        supabase.from("profiles").select("*").eq("id", booking.customer_id).single(),
        booking.assigned_mechanic_id ? supabase.from("mechanics").select("*").eq("id", booking.assigned_mechanic_id).single() : Promise.resolve({ data:null }),
      ])
      downloadInvoice(booking, provider, customer, mechanic, null)
      toast.success("Invoice downloaded")
    } catch(err) {
      toast.error("Could not generate invoice")
    } finally {
      setInvoiceLoading(null)
    }
  }

  const [rebookForm, setRebookForm] = useState({ date:"", time:"" })

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("customer-bookings-"+user.id)
      .on("postgres_changes", { event:"UPDATE", schema:"public", table:"bookings", filter:`customer_id=eq.${user.id}` }, () => load())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function load() {
    const { data } = await supabase.from("bookings").select("*,profiles!bookings_driver_id_fkey(first_name,last_name)").eq("customer_id", user.id).eq("hidden_from_customer", false).order("created_at",{ascending:false})
    setBookings(data||[])
    const { data: claims } = await supabase.from("service_claims").select("booking_id").eq("customer_id", user.id).in("status", ["pending","under_review"])
    setOpenClaimBookingIds(new Set((claims||[]).map(c=>c.booking_id).filter(Boolean)))
    setLoading(false)
  }

  async function approveParts(booking) {
    const { error } = await supabase.from("bookings").update({ parts_approved:true }).eq("id",booking.id).eq("customer_id",user.id)
    if (error) return toast.error(error.message)
    await supabase.from("notifications").insert({
      user_id: booking.provider_id,
      title: "Parts approved by customer Γ£à",
      message: `Customer has approved the parts for booking ${booking.booking_number}. Total: KES ${Number(booking.updated_total||booking.total_amount).toLocaleString()}`,
      type: "success",
    })
    toast.success("Parts approved ΓÇö provider notified")
    load()
  }

  async function confirmPayment(booking) {
    if(!confirm("Confirm you are satisfied with the service and release payment to the provider?")) return
    try {
      const resp = await fetch("https://gcnefnqtjxtqbhynyoxe.supabase.co/functions/v1/release-payment", {
        method:"POST",
        headers:{"Content-Type":"application/json","Authorization":"Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdjbmVmbnF0anh0cWJoeW55b3hlIiwicm9sZSI6ImFub24iLCJpYXQiOjE3Nzk2MDg0MzIsImV4cCI6MjA5NTE4NDQzMn0.Ybyce3psBj2I-hdoF95H5UAklr6hsgQi-mciI9uMIgc"},
        body:JSON.stringify({ booking_id:booking.id, confirmed_by:"customer" })
      })
      const data = await resp.json()
      if(data.error) throw new Error(data.error)
      if (data.partial) {
        toast(data.note || "Part of the payment was released; the rest is on hold.", { icon: "ΓÅ│" })
      } else {
        toast.success("Payment released! Thank you for confirming. Γ£à")
      }
      load()
    } catch(err) { toast.error(err.message) }
  }
  async function hideBooking(id) {
    if (!confirm("Remove this booking from your list?")) return
    const { error } = await supabase.from("bookings").update({ hidden_from_customer:true }).eq("id",id).eq("customer_id",user.id)
    if (error) return toast.error(error.message)
    toast.success("Booking removed from your list")
    load()
  }

  async function cancelBooking(id) {
    if (!confirm("Are you sure you want to cancel this booking?")) return
    const { error } = await supabase.from("bookings").update({ status:"cancelled" }).eq("id",id).eq("customer_id",user.id)
    if (error) return toast.error(error.message)
    // Notify provider
    const cancelled = bookings.find(b=>b.id===id)
    if (cancelled?.provider_id) {
      await supabase.from("notifications").insert({ user_id: cancelled.provider_id, title: "Booking cancelled", message: "Customer cancelled " + cancelled.service_name + " #" + (cancelled.booking_number||"") + " on " + cancelled.booking_date, type: "error" })
    }
    toast.success("Booking cancelled")
    const remove = confirm("Remove this booking from your list? It will still be kept in our records.")
    if (remove) {
      await supabase.from("bookings").update({ hidden_from_customer:true }).eq("id",id).eq("customer_id",user.id)
    }
    load()
  }

  async function rebook(e) {
    e.preventDefault()
    const b = bookings.find(b=>b.id===rebooking)
    if (!b) return
    const { error } = await supabase.from("bookings").insert({
      customer_id: user.id,
      provider_id: b.provider_id,
      service_id: b.service_id,
      service_name: b.service_name,
      booking_date: rebookForm.date,
      booking_time: rebookForm.time,
      total_amount: b.total_amount,
      payment_method: b.payment_method,
      status: "pending",
      payment_status: "pending"
    })
    if (error) return toast.error(error.message)
    await supabase.from("notifications").insert({ user_id: b.provider_id, title: "New booking!", message: b.service_name + " rebooked for " + rebookForm.date + " at " + rebookForm.time, type: "success" })
    await supabase.from("notifications").insert({ user_id: user.id, title: "Booking confirmed Γ£à", message: "Your "+b.service_name+" has been rebooked for "+rebookForm.date+" at "+rebookForm.time, type: "success" })
    toast.success("Booking created!")
    setRebooking(null)
    load()
  }

  const filtered = bookings.filter(b => {
    const matchFilter = filter==="all" || b.status===filter
    const matchSearch = !search || (b.service_name+b.booking_number+(b.notes||"")).toLowerCase().includes(search.toLowerCase())
    return matchFilter && matchSearch
  })
  const inp = { width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"10px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif" }

  return (
    <div>
      {/* Stats bar */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:8, marginBottom:"1rem" }}>
        {[
          { label:"Total", value:bookings.length, color:"#000" },
          { label:"Active", value:bookings.filter(b=>["pending","confirmed","in-progress"].includes(b.status)).length, color:"#378add" },
          { label:"Completed", value:bookings.filter(b=>b.status==="completed").length, color:"#1d9e75" },
          { label:"Cancelled", value:bookings.filter(b=>b.status==="cancelled").length, color:"#e24b4a" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.6rem", textAlign:"center", border:"1px solid #eee" }}>
            <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>
      {/* Search */}
      <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search by service name or booking number..."
        style={{ width:"100%", background:"#f8f8f8", border:"1px solid #eee", borderRadius:8, padding:"9px 12px", fontSize:13, outline:"none", marginBottom:"0.75rem", boxSizing:"border-box" }}/>
      <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap" }}>
        {["all","pending","confirmed","in-progress","completed","cancelled"].map(s=>(
          <button key={s} onClick={()=>setFilter(s)}
            style={{ padding:isMobile?"5px 10px":"6px 14px", borderRadius:6, border:"none", fontSize:isMobile?11:12, cursor:"pointer", background:filter===s?"#e6821e":"#f0f0f0", color:filter===s?"#fff":"#555", fontFamily:"'DM Sans',sans-serif" }}>
            {s==="all"?"All":s.charAt(0).toUpperCase()+s.slice(1)}
          </button>
        ))}
      </div>
      {bookings.length>0&&(
        <button onClick={()=>downloadBookingsCSV(bookings.map(b=>({...b,provider_name:b.providers?.business_name||b.providers?.first_name||"",vehicle_plate:b.vehicles?.license_plate||""})))}
          style={{ marginBottom:8, background:"#f8f8f8", border:"1px solid #ddd", borderRadius:8, color:"#555", fontSize:11, padding:"6px 14px", cursor:"pointer", display:"block", marginLeft:"auto" }}>
          <DownloadIcon size={14} color="#378add" /> Export CSV
        </button>
      )}

      {loading&&<div style={{ color:"#777777", fontSize:13 }}>{t("loading")}</div>}
      {!loading&&filtered.length===0&&<div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"2rem" }}>{t("noBookingsFound")}</div>}

      {filtered.map(b=>(
        <div key={b.id} style={{ background:"#ffffff", border:"1px solid #eee", borderLeft:`4px solid ${SC[b.status]||"#eee"}`, borderRadius:10, padding:isMobile?"0.75rem":"1rem", marginBottom:8 }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
            <div style={{ flex:1, minWidth:0, marginRight:8 }}>
              <div style={{ fontSize:isMobile?13:14, fontWeight:500, color:"#000000", marginBottom:2, display:"flex", alignItems:"center", gap:6 }}>
                <span style={{ fontSize:16 }}>
                  {b.service_category==="go_service"?<GOServiceIcon size={16} color="#e24b4a"/>:b.service_category==="shop_premium"?<ServicesIcon size={16} color="#e6821e"/>:b.service_category==="car_wash"||b.service_category==="basic_wash"||b.service_category==="standard_wash"||b.service_category==="premium_detail"?<DiscoverIcon size={16} color="#1d9e75"/>:<MarketplaceIcon size={16} color="#378add"/>}
                </span>
                {b.service_name}
              </div>
              <div style={{ fontSize:11, color:"#777777" }}>{b.booking_date} ┬╖ {b.booking_time?.slice(0,5)}</div>
              {b.booking_number&&<div style={{ fontSize:10, color:"#888888", marginTop:2 }}>#{b.booking_number}</div>}
            </div>
            <div style={{ textAlign:"right", flexShrink:0 }}>
              <span style={{ fontSize:10, fontWeight:500, padding:"2px 8px", borderRadius:20, background:SB[b.status]||"#f5f5f5", color:SC[b.status]||"#888", border:`1px solid ${SC[b.status]||"#888"}40`, display:"inline-block" }}>{b.status}</span>
              <div style={{ fontFamily:"Syne", fontSize:isMobile?13:14, fontWeight:700, color:"#e6821e", marginTop:4 }}>KES {Number(b.total_amount).toLocaleString()}</div>
            </div>
          </div>

          <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
            {["confirmed","in-progress"].includes(b.status)&&(
              <button onClick={()=>navigate("/dashboard/tracking")}
                style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                <LocationIcon size={13} color="#378add" /> Track
              </button>
            )}
            {["pending","confirmed"].includes(b.status)&&(
              <button onClick={()=>cancelBooking(b.id)}
                style={{ background:"none", border:"1px solid #e24b4a40", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                {t("cancelBooking")}
              </button>
            )}
            {b.payment_held&&!b.payment_released&&["in-progress","completed"].includes(b.status)&&(
              <button onClick={()=>confirmPayment(b)}
                style={{ background:"#1d9e75", border:"none", borderRadius:7, color:"#fff", fontSize:11, fontWeight:700, padding:"5px 12px", cursor:"pointer" }}>
                Γ£à Confirm & Release Payment
              </button>
            )}
            {b.payment_held&&!b.payment_released&&["in-progress","completed"].includes(b.status)&&(
              <div style={{ fontSize:10, color:"#888", padding:"4px 8px", background:"#f8f8f8", borderRadius:6 }}>≡ƒÆ░ Payment held ┬╖ auto-releases in 24hrs</div>
            )}
            {b.status==="completed"&&(
              <>
                <button onClick={()=>navigate("/dashboard/reviews?booking="+b.id)}
                  style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:7, color:"#e6821e", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                  Γ¡É Review
                </button>
                <button onClick={()=>navigate(`/dashboard/claims?booking=${b.id}`)}
                  style={{ background:"#fff5f5", border:"1px solid #e24b4a30", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                  <ShieldIcon size={13} color="#1d9e75" /> Service guarantee
                </button>
                <button onClick={()=>downloadBookingInvoice(b)} disabled={invoiceLoading===b.id}
                  style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                  {invoiceLoading===b.id?"...":"Γ¼ç Invoice"}
                </button>
                <button onClick={()=>{
                  const msg = encodeURIComponent(`Just got my ${b.service_name} done via Car Care Connect! Book your service too: https://carcareconnect.care`)
                  openExternal(`https://wa.me/?text=${msg}`)
                }}
                  style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                  <ShareIcon size={13} color="#64748B" /> Share
                </button>
                <button onClick={()=>{ setRebooking(b.id); setRebookForm({ date:"", time:"" }) }}
                style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:7, color:"#e6821e", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                {t("rebookService")}
                </button>
              </>
              )}
              {b.service_category==="go_service"&&b.status==="completed"&&!b.service_fee_paid&&(
                <button onClick={()=>setServiceFeeBooking(b)}
                  style={{ background:"#e6821e", border:"none", borderRadius:7, color:"#fff", fontSize:11, fontWeight:700, padding:"5px 10px", cursor:"pointer" }}>
                  <PaymentsIcon size={13} color="#e6821e" /> Pay Service Fee
                </button>
              )}
              {(b.status==="completed"||b.status==="cancelled")&&(
                <button onClick={()=>hideBooking(b.id)}
                  style={{ background:"none", border:"1px solid #55540", borderRadius:7, color:"#777777", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                  <DeleteIcon size={13} color="#e24b4a" /> Hide
                </button>
              )}
            <button onClick={()=>setExpanded(expanded===b.id?null:b.id)}
              style={{ background:"none", border:"1px solid #dddddd", borderRadius:7, color:"#666", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
              {expanded===b.id?t("less"):t("details")}
            </button>
          </div>

          {b.is_concierge&&b.driver_id&&(
            <div style={{ marginTop:10, background:"#eff6ff", border:"1px solid #378add30", borderRadius:10, padding:"0.9rem" }}>
              <div style={{ fontFamily:"Syne", fontSize:12, fontWeight:700, color:"#378add", marginBottom:8, display:"flex", alignItems:"center", gap:4 }}><VehicleIcon size={14} color="#378add" /> Concierge delivery</div>
              {/* Driver info */}
              {b.driver_id&&(
                <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:10 }}
                  ref={el=>{ if(el&&!driverInfo[b.id]) loadDriverInfo(b.driver_id,b.id) }}>
                  <div style={{ width:32, height:32, borderRadius:"50%", background:"#f0fdf4", border:"1px solid #1d9e7540", display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontSize:12, fontWeight:800, color:"#1d9e75", flexShrink:0 }}>
                    {driverInfo[b.id]?.first_name?.[0]}{driverInfo[b.id]?.last_name?.[0]}
                  </div>
                  <div>
                    <div style={{ fontSize:12, color:"#000000" }}>Driver: {driverInfo[b.id]?.first_name} {driverInfo[b.id]?.last_name}</div>
                    <div style={{ fontSize:10, color:"#777777" }}>Concierge driver assigned</div>
                  </div>
                </div>
              )}
              {/* Concierge progress */}
              <div style={{ display:"flex", gap:4, flexWrap:"wrap" }}>
                {[
                  { k:"accepted", l:"Assigned" },
                  { k:"pickup", l:"At pickup" },
                  { k:"in_transit", l:"To provider" },
                  { k:"at_provider", l:"At provider" },
                  { k:"return_transit", l:"Returning" },
                  { k:"dropoff", l:"At dropoff" },
                  { k:"completed", l:"Done" },
                ].map((step,i)=>{
                  const steps = ["accepted","pickup","in_transit","at_provider","return_transit","dropoff","completed"]
                  const currentIdx = steps.indexOf(b.concierge_status)
                  const isDone = i<=currentIdx
                  return (
                    <div key={step.k} style={{ fontSize:9, padding:"2px 7px", borderRadius:6, background:isDone?"#f0fdf4":"#ffffff", color:isDone?"#1d9e75":"#555555", border:`1px solid ${isDone?"#1d9e7530":"#f5f5f5"}` }}>
                      {isDone?"Γ£ô ":""}{step.l}
                    </div>
                  )
                })}
              </div>
              {/* Transport allowance */}
              {b.transport_allowance>0&&(
                <div style={{ fontSize:11, color:"#777777", marginTop:8 }}>
                  <><DeliveryIcon size={13} color="#378add"/> Transport allowance: KES {Number(b.transport_allowance).toLocaleString()} included</>
                </div>
              )}
            </div>
          )}

          {b.parts_details?.length>0&&!b.parts_approved&&(
            <div style={{ marginTop:10, background:"#eff6ff", border:"1px solid #378add40", borderRadius:10, padding:"0.9rem" }}>
              <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#378add", marginBottom:8, display:"flex", alignItems:"center", gap:4 }}><ServicesIcon size={14} color="#378add" /> Parts added by provider</div>
              {b.parts_details.map((p,i)=>(
                <div key={i} style={{ display:"flex", justifyContent:"space-between", fontSize:12, padding:"4px 0", borderBottom:"1px solid #eeeeee" }}>
                  <span style={{ color:"#555555" }}>{p.name} ├ù {p.quantity}</span>
                  <span style={{ color:"#000000" }}>KES {p.total?.toLocaleString()}</span>
                </div>
              ))}
              <div style={{ display:"flex", justifyContent:"space-between", fontSize:13, fontWeight:700, color:"#e6821e", marginTop:8 }}>
                <span>New total</span><span>KES {Number(b.updated_total||b.total_amount).toLocaleString()}</span>
              </div>
              <div style={{ display:"flex", gap:8, marginTop:10 }}>
                <button onClick={()=>approveParts(b)}
                  style={{ background:"#1d9e75", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"8px 16px", cursor:"pointer" }}>
                  Γ£ô Approve parts
                </button>
                <button onClick={()=>cancelBooking(b.id)}
                  style={{ background:"none", border:"1px solid #e24b4a40", borderRadius:8, color:"#e24b4a", fontSize:12, padding:"8px 14px", cursor:"pointer" }}>
                  Decline & cancel
                </button>
              </div>
            </div>
          )}

          {expanded===b.id&&(
            <div style={{ marginBottom:10 }}>
              <button onClick={()=>setChatBooking(chatBooking===b.id?null:b.id)}
                style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:11, padding:"5px 12px", cursor:"pointer", width:"100%" }}>
                <><ChatIcon size={13} color="#8b5cf6" /> {chatBooking===b.id?"Close chat":"Message provider"}</>
              </button>
              {chatBooking===b.id&&(
                <div style={{ height:320, marginTop:8 }}>
                  <ChatWindow
                    bookingId={b.id}
                    otherUserId={b.provider_id}
                    otherUserName={providerPhones[b.id]?.name||"Provider"}
                    onClose={()=>setChatBooking(null)}
                  />
                </div>
              )}
              {b.driver_id&&(
                <button onClick={()=>setChatBooking(chatBooking===b.id+"driver"?null:b.id+"driver")}
                  style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"5px 12px", cursor:"pointer", width:"100%", marginTop:6 }}>
                  <><ChatIcon size={13} color="#8b5cf6" /> {chatBooking===b.id+"driver"?"Close chat":"Message driver"}</>
                </button>
              )}
              {chatBooking===b.id+"driver"&&b.driver_id&&(
                <div style={{ height:320, marginTop:8 }}>
                  <ChatWindow
                    bookingId={b.id}
                    otherUserId={b.driver_id}
                    otherUserName="Driver"
                    onClose={()=>setChatBooking(null)}
                  />
                </div>
              )}
            </div>
          )}
          {expanded===b.id&&(
            <div style={{ marginTop:10, paddingTop:10, borderTop:"1px solid #eeeeee" }}>
              <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr 1fr":"repeat(3,1fr)", gap:8 }}>
                {[
                  { l:t("paymentStatus"), v:b.payment_status },
                  { l:"Payment method", v:b.payment_method },
                  { l:b.is_concierge?"Concierge":"Service type", v:b.is_concierge?"Yes":"Standard" },
                ].map(f=>(
                  <div key={f.l}>
                    <div style={{ fontSize:10, color:"#777777", textTransform:"uppercase", marginBottom:2 }}>{f.l}</div>
                    <div style={{ fontSize:12, color:"#000000" }}>{f.v||"ΓÇö"}</div>
                  </div>
                ))}
              </div>
              {b.notes&&<div style={{ fontSize:11, color:"#666", fontStyle:"italic", marginTop:8 }}>Note: &quot;{b.notes}&quot;</div>}
            </div>
          )}

          {rebooking===b.id&&(
            <div style={{ marginTop:10, background:"#ffffff", borderRadius:8, padding:"1rem", border:"1px solid #e5e5e5" }}>
              <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, marginBottom:10, color:"#000000" }}>{t("rebookService")}</div>
              <form onSubmit={rebook}>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10, marginBottom:10 }}>
                  <div>
                    <label style={{ fontSize:11, color:"#666", display:"block", marginBottom:4 }}>Date</label>
                    <input type="date" value={rebookForm.date} onChange={e=>setRebookForm(f=>({...f,date:e.target.value}))} required min={new Date().toISOString().split("T")[0]} style={inp}/>
                  </div>
                  <div>
                    <label style={{ fontSize:11, color:"#666", display:"block", marginBottom:4 }}>Time</label>
                    <select value={rebookForm.time} onChange={e=>setRebookForm(f=>({...f,time:e.target.value}))} required style={inp}>
                      <option value="">Select time</option>
                      {["07:00","08:00","09:00","10:00","11:00","12:00","13:00","14:00","15:00","16:00","17:00","18:00"].map(t2=><option key={t2} value={t2}>{t2}</option>)}
                    </select>
                  </div>
                </div>
                <div style={{ display:"flex", gap:8 }}>
                  <button type="submit" style={{ background:"#e6821e", border:"none", borderRadius:7, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"8px 16px", cursor:"pointer" }}>{t("confirmBooking")}</button>
                  <button type="button" onClick={()=>setRebooking(null)} style={{ background:"none", border:"1px solid #dddddd", borderRadius:7, color:"#555555", fontSize:12, padding:"8px 16px", cursor:"pointer" }}>{t("cancel")}</button>
                </div>
              </form>
            </div>
          )}
        </div>
      ))}
    {serviceFeeBooking&&(
      <DarajaPayment
        amount={Number(serviceFeeBooking.total_amount||0)}
        bookingId={serviceFeeBooking.id}
        providerId={serviceFeeBooking.provider_id}
        description={`Service fee - ${serviceFeeBooking.service_name}`}
        onSuccess={async()=>{ await supabase.from("bookings").update({service_fee_paid:true,service_fee_paid_at:new Date().toISOString()}).eq("id",serviceFeeBooking.id); setServiceFeeBooking(null); load(); toast.success("Service fee paid! Thank you.") }}
        onClose={()=>setServiceFeeBooking(null)}
      />
    )}
    </div>
  )
}

import { useEffect, useState, useRef } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import { useLanguage } from "../../contexts/LanguageContext"
import useIsMobile from "../../lib/useIsMobile"
import ChatWindow from "../shared/ChatWindow"
import { useSearchParams } from "react-router-dom"

export default function CustomerChat() {
  const { user } = useAuth()
  const { t } = useLanguage()
  const isMobile = useIsMobile()
  const [conversations, setConversations] = useState([])
  const [menuFor, setMenuFor] = useState(null)
  const [selected, setSelected] = useState(null)
  const [hidden, setHidden] = useState([])
  const longPressRef = useRef(null)
  function startLongPress(key) {
    longPressRef.current = setTimeout(() => setMenuFor(key), 500)
  }
  function cancelLongPress() { clearTimeout(longPressRef.current) }
  async function deleteConversation(c) {
    try {
    const col = c.bookingId ? "booking_id" : c.listingId ? "listing_id" : "inventory_id"
    const val = c.bookingId || c.listingId || c.inventoryId
    // Hide instantly from UI
    setConversations(prev => prev.filter(x => (x.bookingId||x.listingId||x.inventoryId) !== val))
    setHidden(prev => [...prev, val])
    setMenuFor(null)
    // Delete from DB in background
    supabase.from("chat_messages").delete().eq(col, val).then(({error}) => { if(error) console.error("Delete failed:", error.message) })
    const hidePayload = { user_id: user.id }
    hidePayload[col] = val
    } catch(e) { toast.error("Failed: "+e.message) }
    supabase.from("hidden_conversations").upsert(hidePayload, { onConflict: "user_id,"+col }).then(({error}) => { if(error) console.error("Hide failed:", error.message) })
  }

  async function markAllRead(c) {
    const col = c.bookingId ? "booking_id" : c.listingId ? "listing_id" : "inventory_id"
    const val = c.bookingId || c.listingId || c.inventoryId
    await supabase.from("chat_messages").update({ is_read:true })
      .eq(col, val).eq("receiver_id", user.id)
    setConversations(prev => prev.map(x => (x.bookingId||x.listingId||x.inventoryId)===val ? {...x, unread:0} : x))
    setMenuFor(null)
  }
  const [loading, setLoading] = useState(true)
  const [searchParams] = useSearchParams()

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("customer-chat-list")
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"chat_messages", filter:`receiver_id=eq.${user.id}` }, () => load())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function load() {
    const { data: hiddenData } = await supabase.from("hidden_conversations").select("booking_id,inventory_id,listing_id").eq("user_id", user.id)
    const hiddenKeys = (hiddenData||[]).map(h => h.booking_id || h.inventory_id || h.listing_id)
    setHidden(hiddenKeys)
    const { data: bookings } = await supabase.from("bookings")
      .select("id,service_name,provider_id,assigned_mechanic_id,driver_id,status,booking_date")
      .eq("customer_id", user.id)
      .order("created_at", { ascending:false })

    // Continue even if no bookings - need to load listing messages too

    const providerIds = [...new Set(bookings.map(b=>b.provider_id))]
    const { data: profs } = await supabase.from("profiles")
      .select("id,first_name,last_name,business_name").in("id", providerIds)

    const mechanicIds = [...new Set(bookings.map(b=>b.assigned_mechanic_id).filter(Boolean))]
    const { data: mechs } = mechanicIds.length>0 ? await supabase.from("mechanics")
      .select("id,user_id,first_name,last_name").in("id", mechanicIds) : { data: [] }
    const driverIds = [...new Set(bookings.map(b=>b.driver_id).filter(Boolean))]
    const { data: drivers } = driverIds.length>0 ? await supabase.from("profiles")
      .select("id,first_name,last_name").in("id", driverIds) : { data: [] }

    const { data: lastMessages } = await supabase.from("chat_messages")
      .select("booking_id,message,created_at,sender_id,is_read,receiver_id")
      .in("booking_id", bookings.map(b=>b.id))
      .order("created_at", { ascending:false })

    const convs = bookings.map(b => {
      const provider = profs?.find(p=>p.id===b.provider_id)
      const mechanic = mechs?.find(mc=>mc.id===b.assigned_mechanic_id)
      const msgs = lastMessages?.filter(m=>m.booking_id===b.id)||[]
      const last = msgs[0]
      const unread = msgs.filter(m=>m.receiver_id===user.id&&!m.is_read).length
      // If the mechanic has actually sent/received a message on this booking, show their identity instead of the provider's
      const mechanicIsParty = mechanic?.user_id && msgs.some(m=>m.sender_id===mechanic.user_id||m.receiver_id===mechanic.user_id)
      const driver = drivers?.find(d=>d.id===b.driver_id)
      const driverIsParty = driver && msgs.some(m=>m.sender_id===driver.id||m.receiver_id===driver.id)
      const otherUserId = mechanicIsParty ? mechanic.user_id : driverIsParty ? driver.id : b.provider_id
      const otherUserName = mechanicIsParty
        ? `${mechanic.first_name||""} ${mechanic.last_name||""}`.trim()||"Mechanic"
        : driverIsParty
        ? `${driver.first_name||""} ${driver.last_name||""}`.trim()||"Driver"
        : provider?.business_name||`${provider?.first_name||""} ${provider?.last_name||""}`.trim()||"Provider"
      return {
        bookingId: b.id,
        serviceName: b.service_name,
        _hasMessages: msgs.length>0,
        bookingDate: b.booking_date,
        status: b.status,
        otherUserId,
        otherUserName,
        lastMessage: last?.message||"No messages yet",
        lastTime: last?.created_at,
        unread,
      }
    })
    const filtered = convs // Show all bookings including those without messages yet
    // Load listing messages
    const { data: listingMsgs } = await supabase.from("chat_messages")
      .select("id,listing_id,sender_id,receiver_id,message,created_at,is_read")
      .eq("receiver_id", user.id)
      .not("listing_id","is",null)
      .order("created_at", { ascending:false })
    const listingConvs = []
    if (listingMsgs?.length > 0) {
      const senderIds = [...new Set(listingMsgs.map(m=>m.sender_id))]
      const listingIds = [...new Set(listingMsgs.map(m=>m.listing_id))]
      const [{ data: senderProfs }, { data: listings }] = await Promise.all([
        supabase.from("profiles").select("id,first_name,last_name,business_name").in("id", senderIds),
        supabase.from("marketplace_listings").select("id,title").in("id", listingIds)
      ])
      const grouped = {}
      listingMsgs.forEach(m => {
        const key = `${m.sender_id}-${m.listing_id}`
        if (!grouped[key]) grouped[key] = []
        grouped[key].push(m)
      })
      Object.entries(grouped).forEach(([key, msgs]) => {
        const last = msgs[0]
        const sender = senderProfs?.find(p=>p.id===last.sender_id)
        const listing = listings?.find(l=>l.id===last.listing_id)
        listingConvs.push({
          listingId: last.listing_id,
          serviceName: listing?.title||"Marketplace item",
          otherUserId: last.sender_id,
          otherUserName: sender?.business_name||`${sender?.first_name||""} ${sender?.last_name||""}`.trim()||"Buyer",
          lastMessage: last.message||"",
          lastTime: last.created_at,
          unread: msgs.filter(m=>!m.is_read).length,
          type: "listing"
        })
      })
    }
    const allConvs = [...filtered, ...listingConvs].sort((a,b)=>new Date(b.lastTime||0)-new Date(a.lastTime||0))
    setConversations(allConvs.filter(c => !hiddenKeys.includes(c.bookingId||c.listingId||c.inventoryId)))
    setLoading(false)
    // Auto-open from notification redirect
    const bookingId = searchParams.get("booking")
    if (bookingId) {
      const conv = filtered.find(c=>c.bookingId===bookingId)
      if (conv) setSelected(conv)
    }
  }

  const SC = { pending:"#e6821e", confirmed:"#378add", "in-progress":"#8b5cf6", completed:"#1d9e75", cancelled:"#e24b4a" }

  return (
    <>
      {/* Mobile chat popup modal */}
      {isMobile && selected && (
        <div style={{ position:"fixed", inset:0, zIndex:1000, display:"flex", flexDirection:"column", background:"rgba(0,0,0,0.7)" }}
          onClick={e=>{ if(e.target===e.currentTarget) setSelected(null) }}>
          <div style={{ marginTop:"auto", background:"#ffffff", borderRadius:"16px 16px 0 0", height:"80vh", display:"flex", flexDirection:"column", overflow:"hidden" }}>
            <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"1rem", borderBottom:"1px solid #eeeeee", flexShrink:0 }}>
              <div>
                <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#000000" }}>{selected.otherUserName}</div>
                <div style={{ fontSize:11, color:"#777777" }}>{selected.serviceName}</div>
              </div>
              <button onClick={()=>setSelected(null)}
                style={{ background:"#f5f5f5", border:"none", borderRadius:"50%", width:32, height:32, color:"#555555", cursor:"pointer", fontSize:18, display:"flex", alignItems:"center", justifyContent:"center" }}>
                ├ù
              </button>
            </div>
            <div style={{ flex:1, minHeight:0 }}>
              <ChatWindow
                bookingId={selected.bookingId||null}
                listingId={selected.listingId||null}
                otherUserId={selected.otherUserId}
                otherUserName={selected.otherUserName}
                onClose={()=>setSelected(null)}
              />
            </div>
          </div>
        </div>
      )}

      {/* Desktop chat popup modal */}
      {!isMobile && selected && (
        <div style={{ position:"fixed", inset:0, zIndex:1000, display:"flex", alignItems:"center", justifyContent:"center", background:"rgba(0,0,0,0.7)" }}
          onClick={e=>{ if(e.target===e.currentTarget) setSelected(null) }}>
          <div style={{ width:520, height:600, background:"#ffffff", borderRadius:16, border:"1px solid #eeeeee", display:"flex", flexDirection:"column", overflow:"hidden" }}>
            <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"1rem", borderBottom:"1px solid #eeeeee", flexShrink:0 }}>
              <div>
                <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#000000" }}>{selected.otherUserName}</div>
                <div style={{ fontSize:11, color:"#777777" }}>{selected.serviceName}</div>
              </div>
              <button onClick={()=>setSelected(null)}
                style={{ background:"#f5f5f5", border:"none", borderRadius:"50%", width:32, height:32, color:"#555555", cursor:"pointer", fontSize:18, display:"flex", alignItems:"center", justifyContent:"center" }}>
                ├ù
              </button>
            </div>
            <div style={{ flex:1, minHeight:0 }}>
              <ChatWindow
                bookingId={selected.bookingId||null}
                listingId={selected.listingId||null}
                otherUserId={selected.otherUserId}
                otherUserName={selected.otherUserName}
                onClose={()=>setSelected(null)}
              />
            </div>
          </div>
        </div>
      )}

      {/* Context menu overlay */}
      {menuFor&&(
        <div style={{ position:"fixed", inset:0, zIndex:200, background:"rgba(0,0,0,0.5)" }} onClick={()=>setMenuFor(null)}>
          <div style={{ position:"absolute", bottom:0, left:0, right:0, background:"#fff", borderRadius:"20px 20px 0 0", padding:"1.25rem", boxShadow:"0 -4px 24px rgba(0,0,0,0.15)" }}
            onClick={e=>e.stopPropagation()}>
            <div style={{ width:36, height:4, background:"#e0e0e0", borderRadius:2, margin:"0 auto 1.25rem" }}/>
            <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#000", marginBottom:"1rem", textAlign:"center" }}>
              {conversations.find(c=>(c.bookingId||c.listingId||c.inventoryId)===menuFor)?.otherUserName}
            </div>
            {[
              { icon:"Γ£ô", label:"Mark all as read", color:"#1d9e75", action:()=>{ const c=conversations.find(x=>(x.bookingId||x.listingId||x.inventoryId)===menuFor); if(c) markAllRead(c) } },
              { icon:"≡ƒÆ¼", label:"Open chat", color:"#e6821e", action:()=>{ const c=conversations.find(x=>(x.bookingId||x.listingId||x.inventoryId)===menuFor); if(c){ setSelected(c); setMenuFor(null) } } },
              { icon:"≡ƒùæ", label:"Delete conversation", color:"#e24b4a", action:()=>{ const c=conversations.find(x=>(x.bookingId||x.listingId||x.inventoryId)===menuFor); if(c) deleteConversation(c) } },
            ].map(item=>(
              <div key={item.label} onClick={item.action}
                style={{ display:"flex", alignItems:"center", gap:14, padding:"1rem", borderRadius:12, cursor:"pointer", marginBottom:6, background:"#f8f8f8" }}>
                <span style={{ fontSize:20 }}>{item.icon}</span>
                <span style={{ fontSize:14, fontWeight:600, color:item.color }}>{item.label}</span>
              </div>
            ))}
            <div onClick={()=>setMenuFor(null)}
              style={{ display:"flex", alignItems:"center", justifyContent:"center", padding:"1rem", borderRadius:12, cursor:"pointer", background:"#f0f0f0", marginTop:4 }}>
              <span style={{ fontSize:14, fontWeight:600, color:"#555" }}>Cancel</span>
            </div>
          </div>
        </div>
      )}
      {/* Conversation list */}
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:18, fontWeight:800, color:"#000000", marginBottom:4 }}>Messages</div>
      <div style={{ fontSize:11, color:"#777777", marginBottom:"1rem" }}>{conversations.length} active booking{conversations.length!==1?"s":""}</div>

      {loading&&<div style={{ color:"#777777", fontSize:13 }}>Loading...</div>}
      {!loading&&conversations.length===0&&(
        <div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"3rem" }}>
          <div style={{ fontSize:32, marginBottom:10 }}>≡ƒÆ¼</div>
          No conversations yet. Book a service to start chatting with providers.
        </div>
      )}

      {conversations.filter(c=>!hidden.includes(c.bookingId||c.listingId||c.inventoryId)).map(c=>{
        const key = c.bookingId||c.listingId||c.inventoryId
        const isMenuOpen = menuFor===key
        return (
        <div key={key}
          onClick={()=>{ if(!menuFor) setSelected(c) }}
          onTouchStart={()=>startLongPress(key)}
          onTouchEnd={cancelLongPress}
          onTouchMove={cancelLongPress}
          onContextMenu={e=>{ e.preventDefault(); setMenuFor(key) }}
          style={{ background:isMenuOpen?"#fff8f0":"#ffffff", border:`1px solid ${selected?.bookingId===c.bookingId?"#e6821e":isMenuOpen?"#e6821e30":"#eeeeee"}`, borderRadius:10, padding:"0.9rem", marginBottom:8, cursor:"pointer", userSelect:"none" }}>
          <div style={{ display:"flex", alignItems:"flex-start", gap:10 }}>
            <div style={{ width:44, height:44, borderRadius:"50%", background:"#fff8f0", border:"1px solid #e6821e40", display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontSize:16, fontWeight:800, color:"#e6821e", flexShrink:0 }}>
              {c.otherUserName[0]?.toUpperCase()}
            </div>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:2 }}>
                <div style={{ fontSize:13, fontWeight:c.unread>0?700:500, color:"#000000", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{c.otherUserName}</div>
                <div style={{ display:"flex", alignItems:"center", gap:6 }}>
                  {c.unread>0&&<div style={{ width:20, height:20, borderRadius:"50%", background:"#e6821e", color:"#fff", fontSize:10, fontWeight:700, display:"flex", alignItems:"center", justifyContent:"center" }}>{c.unread}</div>}
                  <span style={{ fontSize:10, color:"#888888" }}>{c.lastTime?new Date(c.lastTime).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}):""}</span>
                </div>
              </div>
              <div style={{ fontSize:11, color:"#666", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", marginBottom:4 }}>{c.lastMessage}</div>
              <div style={{ display:"flex", gap:6, alignItems:"center" }}>
                <span style={{ fontSize:10, color:SC[c.status]||"#555" }}>ΓùÅ {c.status}</span>
                <span style={{ fontSize:10, color:"#888888" }}>┬╖ {c.serviceName} ┬╖ {c.bookingDate}</span>
              </div>
            </div>
            <div style={{ fontSize:11, color:"#e6821e", flexShrink:0, marginTop:2 }}>≡ƒÆ¼ Chat</div>
          </div>
        </div>
        )
      })}
    </>
  )
}

import { useEffect, useState, useRef } from "react"
import { supabase } from "../../lib/supabase"
import { validateFile, sanitizeFilePath } from "../../lib/uploadValidation"
import { useAuth } from "../../contexts/AuthContext"
import ClaimChat from "../shared/ClaimChat"
import { useLocation } from "react-router-dom"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const CLAIM_REASONS = [
  "Service not completed properly",
  "Mechanic was unprofessional",
  "Vehicle was damaged during service",
  "Service took much longer than promised",
  "Wrong service was performed",
  "Parts used were substandard",
  "Provider did not show up",
  "Other",
]

export default function CustomerClaims() {
  const { user, profile } = useAuth()
  const isMobile = useIsMobile()
  const location = useLocation()
  const preselectedBooking = new URLSearchParams(location.search).get("booking")
  const [claims, setClaims] = useState([])
  const [claimsAgainstMe, setClaimsAgainstMe] = useState([])
  const [vouchers, setVouchers] = useState([])
  const [bookings, setBookings] = useState([])
  const [orders, setOrders] = useState([])
  const [claimType, setClaimType] = useState("booking")
  const [loading, setLoading] = useState(true)
  const [adminId, setAdminId] = useState(null)
  const [showForm, setShowForm] = useState(!!preselectedBooking)
  const [form, setForm] = useState({ booking_id:preselectedBooking||"", order_id:"", reason:"", description:"", refund_preference:"voucher" })
  const [claimTarget, setClaimTarget] = useState("provider")
  const [submitting, setSubmitting] = useState(false)
  const [evidencePhotos, setEvidencePhotos] = useState([])
  const [uploadingEvidence, setUploadingEvidence] = useState(false)
  const evidenceInputRef = useRef(null)
  const [showHowItWorks, setShowHowItWorks] = useState(false)
  const [tab, setTab] = useState("claims")
  const [chatClaim, setChatClaim] = useState(null)

  useEffect(() => {
    if (user) {
      load()
      supabase.from("profiles").select("id").eq("role","admin").limit(1)
        .then(({ data }) => { if (data?.length) setAdminId(data[0].id) })
    }
  }, [user])

  // Real-time claim status updates
  useEffect(() => {
    if (!user) return
    const sub = supabase.channel("customer-claims-"+user.id)
      .on("postgres_changes", { event:"UPDATE", schema:"public", table:"service_claims", filter:"customer_id=eq."+user.id }, () => load())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function load() {
    const [{ data: cls }, { data: vchs }, { data: bks }, { data: ords }, { data: against }] = await Promise.all([
      supabase.from("service_claims")
        .select("*, bookings(service_name,booking_number,booking_date,total_amount)")
        .eq("customer_id", user.id).order("created_at", { ascending:false }),
      supabase.from("service_vouchers")
        .select("*").eq("customer_id", user.id).order("created_at", { ascending:false }),
      supabase.from("bookings")
        .select("id,service_name,booking_number,booking_date,total_amount,status,provider_id")
        .eq("customer_id", user.id).eq("status","completed")
        .order("created_at", { ascending:false }).limit(20),
      supabase.from("orders")
        .select("id,order_number,status,subtotal,provider_id,created_at")
        .eq("customer_id", user.id).eq("status","delivered")
        .order("created_at", { ascending:false }).limit(20),
      supabase.from("service_claims")
        .select("*, bookings(service_name,booking_number,booking_date), claimant:profiles!service_claims_claimant_id_fkey(first_name,last_name,role)")
        .eq("against_id", user.id).eq("against_type","customer")
        .order("created_at", { ascending:false }),
    ])
    setClaims(cls||[])
    setVouchers(vchs||[])
    setBookings(bks||[])
    setOrders(ords||[])
    setClaimsAgainstMe(against||[])
    setLoading(false)
  }

  async function uploadEvidencePhoto(file) {
    const _v = validateFile(file, "image")
    if (!_v.valid) { toast.error(_v.error); return }

    const ext = file.name.split(".").pop()
    const path = `claims/${Date.now()}_${Math.random().toString(36).slice(2)}.${ext}`
    const { error } = await supabase.storage.from("claim-evidence").upload(path, file)
    if (error) throw error
    const { data } = supabase.storage.from("claim-evidence").getPublicUrl(path)
    return data.publicUrl
  }

  async function handleEvidenceSelect(e) {
    const files = Array.from(e.target.files).slice(0, 3)
    setUploadingEvidence(true)
    try {
      const urls = await Promise.all(files.map(uploadEvidencePhoto))
      setEvidencePhotos(prev => [...prev, ...urls].slice(0, 3))
    } catch(err) { toast.error("Photo upload failed: "+err.message) }
    setUploadingEvidence(false)
  }

  async function submitClaim(e) {
    e.preventDefault()
    if (claimType==="booking" && !form.booking_id) return toast.error("Please select a booking")
    if (claimType==="order" && !form.order_id) return toast.error("Please select an order")
    if (!form.reason) return toast.error("Please select a reason")
    if (!form.description) return toast.error("Please describe the issue")
    setSubmitting(true)
    try {
      const booking = bookings.find(b=>b.id===form.booking_id)
      const order = orders.find(o=>o.id===form.order_id)
      // Check for existing active claim
      const checkId = claimType==="booking" ? form.booking_id : form.order_id
      const checkCol = claimType==="booking" ? "booking_id" : "order_id"
      const { data: existing } = await supabase.from("service_claims")
        .select("id,status").eq(checkCol, checkId).eq("customer_id", user.id)
        .not("status","eq","rejected").maybeSingle()
      if(existing) {
        toast.error("You already have an active claim for this "+(claimType==="booking"?"booking":"order")+". Status: "+existing.status)
        setSubmitting(false)
        return
      }
      const { error } = await supabase.from("service_claims").insert({
        booking_id: claimType==="booking" ? form.booking_id : null,
        order_id: claimType==="order" ? form.order_id : null,
        customer_id: user.id,
        provider_id: claimType==="booking" ? booking?.provider_id : order?.provider_id,
        claimant_type: "customer",
        claimant_id: user.id,
        against_type: (claimType==="booking" && claimTarget==="driver" && booking?.driver_id) ? "driver" : "provider",
        against_id: (claimType==="booking" && claimTarget==="driver" && booking?.driver_id) ? booking.driver_id : (claimType==="booking" ? booking?.provider_id : order?.provider_id),
        driver_id_claim: (claimType==="booking" && claimTarget==="driver" && booking?.driver_id) ? booking.driver_id : null,
        reason: form.reason,
        description: form.description,
        status: "pending",
        refund_preference: form.refund_preference||"voucher",
        evidence_urls: evidencePhotos,
      })
      if (error) throw error
      await supabase.from("notifications").insert({
        user_id: user.id,
        title: "Claim submitted Γ£à",
        message: "Your service claim has been submitted. Our team will review it within 24 hours.",
        type: "success",
      })
      // Notify all admins
      const { data: admins } = await supabase.from("profiles").select("id").eq("role","admin")
      for (const admin of (admins||[])) {
        await supabase.from("notifications").insert({
          user_id: admin.id,
          title: "New service claim ≡ƒ¢í∩╕Å",
          message: (profile?.first_name||"Customer")+" "+(profile?.last_name||"")+" submitted a claim: "+form.reason,
          type: "warning"
        })
      }
      toast.success("Claim submitted ΓÇö we will review within 24 hours")
      setShowForm(false)
      setForm({ booking_id:"", order_id:"", reason:"", description:"", refund_preference:"voucher" })
      setEvidencePhotos([])
      load()
    } catch(err) { toast.error(err.message) }
    finally { setSubmitting(false) }
  }

  const activeVouchers = vouchers.filter(v=>!v.is_used&&new Date(v.expires_at)>new Date())
  const usedVouchers = vouchers.filter(v=>v.is_used)
  const expiredVouchers = vouchers.filter(v=>!v.is_used&&new Date(v.expires_at)<=new Date())

  const inp = { width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"11px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif", marginBottom:12 }
  const lbl = { fontSize:11, color:"#666", textTransform:"uppercase", letterSpacing:"0.05em", display:"block", marginBottom:4 }
  const SC = { pending:"#e6821e", under_review:"#8b5cf6", approved:"#1d9e75", rejected:"#e24b4a" }

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:18, fontWeight:800, color:"#000000", marginBottom:4 }}>Service Guarantee</div>
      <div style={{ fontSize:12, color:"#777777", marginBottom:"1.25rem" }}>Not happy with a service? We will make it right.</div>
      {/* Stats bar */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:8, marginBottom:"1rem" }}>
        {[
          { label:"Pending", value:claims.filter(c=>c.status==="pending").length, color:"#e6821e" },
          { label:"Under review", value:claims.filter(c=>c.status==="under_review").length, color:"#8b5cf6" },
          { label:"Approved", value:claims.filter(c=>c.status==="approved").length, color:"#1d9e75" },
          { label:"Vouchers", value:activeVouchers.length, color:"#378add" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.75rem 0.5rem", textAlign:"center", border:"1px solid #eee" }}>
            <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>

      {/* Active vouchers banner */}
      {activeVouchers.length>0&&(
        <div style={{ background:"#f0fdf4", border:"2px solid #1d9e75", borderRadius:12, padding:"1.25rem", marginBottom:"1.5rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#1d9e75", marginBottom:8 }}>
            ≡ƒÄƒ∩╕Å You have {activeVouchers.length} active voucher{activeVouchers.length>1?"s":""}
          </div>
          {activeVouchers.map(v=>(
            <div key={v.id} style={{ background:"#ffffff", borderRadius:10, padding:"1rem", marginBottom:8, border:"1px solid #1d9e7530" }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", flexWrap:"wrap", gap:8 }}>
                <div>
                  <div style={{ fontFamily:"Syne", fontSize:20, fontWeight:800, color:"#1d9e75", letterSpacing:2 }}>{v.voucher_code}</div>
                  <div style={{ fontSize:12, color:"#555555", marginTop:2 }}>Worth KES {Number(v.amount).toLocaleString()}</div>
                  <div style={{ fontSize:11, color:"#777777", marginTop:2 }}>Expires: {new Date(v.expires_at).toLocaleDateString()}</div>
                  <div style={{ fontSize:11, color:"#1d9e75", marginTop:4 }}>Γ£ô Valid for any service from a different provider</div>
                </div>
                <div style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:8, padding:"0.5rem 1rem", textAlign:"center" }}>
                  <div style={{ fontSize:10, color:"#777777", marginBottom:2 }}>Value</div>
                  <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:"#1d9e75" }}>KES {Number(v.amount).toLocaleString()}</div>
                </div>
              </div>
              <div style={{ fontSize:11, color:"#777777", marginTop:8, padding:"0.5rem", background:"#ffffff", borderRadius:6 }}>
                ≡ƒÆí Use this code when booking any service ΓÇö the amount will be deducted from your total
              </div>
            </div>
          ))}
        </div>
      )}

      {/* How it works */}
      <div style={{ background:"#f8f8f8", border:"1px solid #eee", borderRadius:12, padding:"1rem", marginBottom:"1rem" }}>
        <button onClick={()=>setShowHowItWorks(!showHowItWorks)} style={{ width:"100%", background:"none", border:"none", display:"flex", justifyContent:"space-between", alignItems:"center", cursor:"pointer", padding:0 }}>
          <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#000" }}>How our Service Guarantee works</div>
          <span style={{ color:"#e6821e", fontSize:16 }}>{showHowItWorks?"ΓêÆ":"+"}</span>
        </button>
        {showHowItWorks&&(
          <div style={{ marginTop:10 }}>
            {[
              { icon:"1∩╕ÅΓâú", title:"Submit a claim", desc:"Tell us what went wrong within 7 days of completion" },
              { icon:"2∩╕ÅΓâú", title:"We review", desc:"Our team reviews your claim within 24 hours" },
              { icon:"3∩╕ÅΓâú", title:"Get a voucher", desc:"If approved, receive a service voucher worth the full amount" },
              { icon:"4∩╕ÅΓâú", title:"Rebook for free", desc:"Use your voucher to book with any other provider" },
              { icon:"5∩╕ÅΓâú", title:"Provider accountability", desc:"The original provider is penalized and amount deducted from their earnings" },
            ].map(step=>(
              <div key={step.icon} style={{ display:"flex", gap:10, alignItems:"flex-start", marginBottom:8 }}>
                <span style={{ fontSize:16, flexShrink:0 }}>{step.icon}</span>
                <div>
                  <div style={{ fontSize:12, color:"#000", fontWeight:600 }}>{step.title}</div>
                  <div style={{ fontSize:11, color:"#777", lineHeight:1.5 }}>{step.desc}</div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
      {/* Tabs */}
      <div style={{ display:"flex", gap:6, marginBottom:"1.25rem", flexWrap:"wrap" }}>
        {[
          { k:"claims", l:"My claims ("+claims.length+")" },
          { k:"against", l:"Against me ("+claimsAgainstMe.length+")" },
          { k:"vouchers", l:"Vouchers ("+vouchers.length+")" },
        ].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{ padding:"8px 16px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#e6821e":"#555555", color:tab===t.k?"#fff":"#666", fontWeight:tab===t.k?700:400 }}>
            {t.l}
          </button>
        ))}
        <button onClick={()=>setShowForm(true)}
          style={{ marginLeft:"auto", background:"#e6821e", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"8px 16px", cursor:"pointer" }}>
          + New claim
        </button>
      </div>

      {/* Claim form */}
      {showForm&&(
        <div style={{ background:"#ffffff", border:"1px solid #e6821e30", borderRadius:12, padding:"1.25rem", marginBottom:"1.5rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#000000", marginBottom:"1rem" }}>Submit a service claim</div>
          <form onSubmit={submitClaim}>
            <div style={{ display:"flex", gap:8, marginBottom:12 }}>
              <button type="button" onClick={()=>setClaimType("booking")} style={{ flex:1, padding:"8px", borderRadius:8, border:"1px solid "+(claimType==="booking"?"#e6821e":"#e0e0e0"), background:claimType==="booking"?"#fff8f0":"#f8f8f8", color:claimType==="booking"?"#e6821e":"#555", fontSize:12, fontWeight:claimType==="booking"?700:400, cursor:"pointer" }}>≡ƒôà A service booking</button>
              <button type="button" onClick={()=>setClaimType("order")} style={{ flex:1, padding:"8px", borderRadius:8, border:"1px solid "+(claimType==="order"?"#e6821e":"#e0e0e0"), background:claimType==="order"?"#fff8f0":"#f8f8f8", color:claimType==="order"?"#e6821e":"#555", fontSize:12, fontWeight:claimType==="order"?700:400, cursor:"pointer" }}>≡ƒôª A parts order</button>
            </div>
            {claimType==="booking"&&(
              <><label style={lbl}>Select booking *</label>
              <select style={inp} value={form.booking_id} onChange={e=>setForm(f=>({...f,booking_id:e.target.value}))}>
                <option value="">Select a completed booking</option>
                {bookings.map(b=>(
                  <option key={b.id} value={b.id}>{b.service_name} ΓÇö #{b.booking_number} ┬╖ {b.booking_date} ┬╖ KES {Number(b.total_amount).toLocaleString()}</option>
                ))}
              </select></>
            )}
            {claimType==="order"&&(
              <><label style={lbl}>Select order *</label>
              <select style={inp} value={form.order_id} onChange={e=>setForm(f=>({...f,order_id:e.target.value}))}>
                <option value="">Select a delivered order</option>
                {orders.map(o=>(
                  <option key={o.id} value={o.id}>Order #{o.order_number} ┬╖ KES {Number(o.subtotal||0).toLocaleString()} ┬╖ {new Date(o.created_at).toLocaleDateString()}</option>
                ))}
              </select></>
            )}
            {claimType==="booking"&&bookings.find(b=>b.id===form.booking_id)?.is_concierge&&bookings.find(b=>b.id===form.booking_id)?.driver_id&&(
              <>
                <label style={lbl}>Who is this claim about? *</label>
                <div style={{ display:"flex", gap:8, marginBottom:12 }}>
                  <button type="button" onClick={()=>setClaimTarget("provider")}
                    style={{ flex:1, padding:"10px", borderRadius:8, border:claimTarget==="provider"?"2px solid #e6821e":"1px solid #ddd", background:claimTarget==="provider"?"#fff8f0":"#fff", color:claimTarget==="provider"?"#e6821e":"#666", fontSize:13, fontWeight:600, cursor:"pointer" }}>
                    The Provider (service quality)
                  </button>
                  <button type="button" onClick={()=>setClaimTarget("driver")}
                    style={{ flex:1, padding:"10px", borderRadius:8, border:claimTarget==="driver"?"2px solid #e6821e":"1px solid #ddd", background:claimTarget==="driver"?"#fff8f0":"#fff", color:claimTarget==="driver"?"#e6821e":"#666", fontSize:13, fontWeight:600, cursor:"pointer" }}>
                    The Driver (pickup/drop-off)
                  </button>
                </div>
              </>
            )}
            <label style={lbl}>Reason *</label>
            <select style={inp} value={form.reason} onChange={e=>setForm(f=>({...f,reason:e.target.value}))} required>
              <option value="">Select reason</option>
              {CLAIM_REASONS.map(r=><option key={r} value={r}>{r}</option>)}
            </select>
            <label style={lbl}>Describe what went wrong *</label>
            <textarea style={{ ...inp, resize:"vertical", minHeight:100 }}
              placeholder="Please provide as much detail as possible."
              value={form.description} onChange={e=>setForm(f=>({...f,description:e.target.value}))} required/>
            <div style={{ background:"#ffffff", borderRadius:8, padding:"0.75rem", marginBottom:12, fontSize:11, color:"#666", lineHeight:1.6 }}>
              ΓÜá∩╕Å Claims must be submitted within 7 days of service completion. False claims may result in account suspension.
            {/* Evidence photos */}
            <div style={{ marginBottom:12 }}>
              <div style={{ fontSize:11, color:"#666", fontWeight:600, marginBottom:6 }}>≡ƒô╕ Attach evidence photos (optional, max 3)</div>
              <input ref={evidenceInputRef} type="file" accept="image/*" multiple style={{ display:"none" }} onChange={handleEvidenceSelect}/>
              <div style={{ display:"flex", gap:6, flexWrap:"wrap", alignItems:"center" }}>
                {evidencePhotos.map((url,i)=>(
                  <div key={i} style={{ position:"relative" }}>
                    <img src={url} alt="Evidence" style={{ width:60, height:60, objectFit:"cover", borderRadius:8, border:"1px solid #eee" }}/>
                    <button type="button" onClick={()=>setEvidencePhotos(p=>p.filter((_,j)=>j!==i))}
                      style={{ position:"absolute", top:-4, right:-4, background:"#e24b4a", border:"none", borderRadius:"50%", width:16, height:16, color:"#fff", fontSize:10, cursor:"pointer" }}>├ù</button>
                  </div>
                ))}
                {evidencePhotos.length<3&&(
                  <button type="button" onClick={()=>evidenceInputRef.current?.click()} disabled={uploadingEvidence}
                    style={{ width:60, height:60, background:"#f8f8f8", border:"2px dashed #ddd", borderRadius:8, cursor:"pointer", fontSize:20, color:"#aaa" }}>
                    {uploadingEvidence?"ΓÅ│":"≡ƒô╖"}
                  </button>
                )}
              </div>
            </div>
            </div>
            <div style={{ display:"flex", gap:8 }}>
              <div style={{ marginBottom:12 }}>
                <label style={lbl}>Preferred Resolution *</label>
                <select style={inp} value={form.refund_preference} onChange={e=>setForm(f=>({...f,refund_preference:e.target.value}))}>
                  <option value="voucher">≡ƒÄƒ∩╕Å Service Voucher (rebook with any provider)</option>
                  <option value="cash">≡ƒÆ░ Cash Refund (M-Pesa)</option>
                  <option value="redo">≡ƒöº Redo the service (same provider)</option>
                </select>
              </div>
              <button type="submit" disabled={submitting}
                style={{ width:"100%", marginBottom:8, background:submitting?"#555555":"#e6821e", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px 24px", cursor:submitting?"not-allowed":"pointer" }}>
                {submitting?"Submitting...":"Submit claim"}
              </button>
              <button type="button" onClick={()=>{ setShowForm(false); setForm({ booking_id:"", order_id:"", reason:"", description:"", refund_preference:"voucher" }) }}
                style={{ width:"100%", background:"none", border:"1px solid #dddddd", borderRadius:9, color:"#666", fontSize:13, padding:"11px 16px", cursor:"pointer" }}>
                Cancel
              </button>
            </div>
          </form>
        </div>
      )}

      {loading&&<div style={{ color:"#777777", fontSize:13 }}>Loading...</div>}

      {/* Claims tab */}
      {tab==="claims"&&(
        <div>
          {!loading&&claims.length===0&&(
            <div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"2rem" }}>
              <div style={{ fontSize:32, marginBottom:10 }}>Γ£à</div>
              No claims yet ΓÇö we hope all your services have been great!
            </div>
          )}
          {claims.map(c=>(
            <div key={c.id} style={{ background:"#f8f8f8", border:"1px solid #eee", borderLeft:`4px solid ${SC[c.status]||"#eee"}`, borderRadius:10, padding:"1rem", marginBottom:8, cursor:"default" }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4, flexWrap:"wrap" }}>
                    <div style={{ fontSize:13, fontWeight:600, color:"#000000" }}>{c.bookings?.service_name}</div>
                    <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:`${SC[c.status]||"#888"}20`, color:SC[c.status]||"#888" }}>{c.status?.replace("_"," ")}</span>
                  </div>
                  <div style={{ fontSize:11, color:"#777777", marginBottom:2 }}>#{c.bookings?.booking_number} ┬╖ {c.bookings?.booking_date}</div>
                  <div style={{ fontSize:12, color:"#555555", marginBottom:2 }}>Reason: {c.reason}</div>
                  <div style={{ fontSize:11, color:"#666", fontStyle:"italic" }}>&quot;{c.description}&quot;</div>
                  {c.admin_notes&&<div style={{ fontSize:11, color:"#378add", marginTop:4 }}>Admin: &quot;{c.admin_notes}&quot;</div>}
                  <div style={{ fontSize:10, color:"#888888", marginTop:4 }}>{new Date(c.created_at).toLocaleString()}</div>
                </div>
                <div style={{ textAlign:"right", flexShrink:0 }}>
                  <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#e6821e" }}>KES {Number(c.bookings?.total_amount||0).toLocaleString()}</div>
                </div>
              </div>
              <div style={{ marginTop:8 }}>
                <button onClick={()=>setChatClaim(chatClaim===c.id?null:c.id)}
                  style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>
                  ≡ƒÆ¼ {chatClaim===c.id?"Close":(c.status==="pending"||c.status==="under_review")?"Add evidence / message admin":"View conversation with admin"}
                </button>
                {chatClaim===c.id&&(
                  <div style={{ marginTop:8 }}>
                    <ClaimChat claimId={c.id} claim={c} onClose={()=>setChatClaim(null)}/>
                  </div>
                )}
              </div>
            {c.status==="approved"&&(
                <div style={{ marginTop:8, padding:"0.6rem", background:"#f0fdf4", borderRadius:7, fontSize:12, color:"#1d9e75" }}>
                  Γ£à Claim approved ΓÇö check your vouchers tab
                </div>
              )}
              {c.status==="rejected"&&c.admin_notes&&(
                <div style={{ marginTop:8, padding:"0.6rem", background:"#fff5f5", borderRadius:7, fontSize:12, color:"#e24b4a" }}>
                  Γ¥î Claim rejected: {c.admin_notes}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
      {/* Against me tab */}
      {tab==="against"&&(
        <div>
          {claimsAgainstMe.length===0&&(
            <div style={{ textAlign:"center", padding:"2rem", color:"#888" }}>
              <div style={{ fontSize:32, marginBottom:10 }}>Γ£à</div>
              No claims have been filed against you
            </div>
          )}
          {claimsAgainstMe.map(c=>(
            <div key={c.id} style={{ background:"#f8f8f8", border:"1px solid #eee", borderLeft:`4px solid ${SC[c.status]||"#eee"}`, borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div style={{ flex:1 }}>
                  <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, marginBottom:2 }}>{c.bookings?.service_name}</div>
                  <div style={{ fontSize:11, color:"#888" }}>Filed by: {c.claimant?.first_name} {c.claimant?.last_name} ({c.claimant?.role})</div>
                  <div style={{ fontSize:12, color:"#e6821e", marginTop:4 }}>Reason: {c.reason}</div>
                  <div style={{ fontSize:11, color:"#666", fontStyle:"italic", marginTop:2 }}>"{c.description}"</div>
                  {c.admin_notes&&<div style={{ fontSize:11, color:"#378add", marginTop:4 }}>Admin decision: "{c.admin_notes}"</div>}
                  <div style={{ fontSize:10, color:"#aaa", marginTop:4 }}>{new Date(c.created_at).toLocaleDateString()}</div>
                </div>
                <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:(SC[c.status]||"#888")+"20", color:SC[c.status]||"#888", fontWeight:600 }}>{c.status?.replace("_"," ")}</span>
              </div>
              {(c.status==="pending"||c.status==="under_review")&&(
                <div style={{ marginTop:8 }}>
                  <div style={{ background:"#fff8f0", border:"1px solid #e6821e30", borderRadius:8, padding:"0.6rem", fontSize:11, color:"#666", marginBottom:6 }}>
                    ΓÜá∩╕Å A claim has been filed against you. You can submit your response and evidence below.
                  </div>
                  <button onClick={()=>setChatClaim(chatClaim===c.id?null:c.id)}
                    style={{ background:"#f5f3ff", border:"1px solid #8b5cf640", borderRadius:7, color:"#8b5cf6", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>
                    ≡ƒÆ¼ {chatClaim===c.id?"Close":"Submit my response / evidence"}
                  </button>
                  {chatClaim===c.id&&(
                    <div style={{ marginTop:8 }}>
                      <ClaimChat claimId={c.id} claim={c} onClose={()=>setChatClaim(null)}/>
                    </div>
                  )}
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {/* Vouchers tab */}
      {tab==="vouchers"&&(
        <div>
          {activeVouchers.length>0&&(
            <div style={{ marginBottom:"1.5rem" }}>
              <div style={{ fontSize:11, color:"#1d9e75", fontWeight:700, textTransform:"uppercase", marginBottom:8 }}>Active vouchers</div>
              {activeVouchers.map(v=>(
                <div key={v.id} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:10, padding:"1rem", marginBottom:8 }}>
                  <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:"#1d9e75", letterSpacing:2, marginBottom:4 }}>{v.voucher_code}</div>
                  <div style={{ fontSize:12, color:"#555555" }}>Worth KES {Number(v.amount).toLocaleString()} ┬╖ Expires {new Date(v.expires_at).toLocaleDateString()}</div>
                  <div style={{ fontSize:11, color:"#777777", marginTop:4 }}>Use this code when booking any service</div>
                </div>
              ))}
            </div>
          )}
          {usedVouchers.length>0&&(
            <div style={{ marginBottom:"1.5rem" }}>
              <div style={{ fontSize:11, color:"#777777", fontWeight:700, textTransform:"uppercase", marginBottom:8 }}>Used vouchers</div>
              {usedVouchers.map(v=>(
                <div key={v.id} style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:8, opacity:0.6 }}>
                  <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#777777", letterSpacing:2, marginBottom:4 }}>{v.voucher_code}</div>
                  <div style={{ fontSize:11, color:"#888888" }}>KES {Number(v.amount).toLocaleString()} ┬╖ Used</div>
                </div>
              ))}
            </div>
          )}
          {expiredVouchers.length>0&&(
            <div>
              <div style={{ fontSize:11, color:"#888888", fontWeight:700, textTransform:"uppercase", marginBottom:8 }}>Expired vouchers</div>
              {expiredVouchers.map(v=>(
                <div key={v.id} style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:8, opacity:0.4 }}>
                  <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#888888", letterSpacing:2, marginBottom:4 }}>{v.voucher_code}</div>
                  <div style={{ fontSize:11, color:"#555555" }}>KES {Number(v.amount).toLocaleString()} ┬╖ Expired {new Date(v.expires_at).toLocaleDateString()}</div>
                </div>
              ))}
            </div>
          )}
          {vouchers.length===0&&(
            <div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"2rem" }}>
              <div style={{ fontSize:32, marginBottom:10 }}>≡ƒÄƒ∩╕Å</div>
              No vouchers yet
            </div>
          )}
        </div>
      )}
    </div>
  )
}

import useIsMobile from "../../lib/useIsMobile"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { SearchIcon, ServicesIcon, PartsIcon, MarketplaceIcon, VehicleIcon, PowerIcon, DiscoverIcon, MechanicIcon, ShieldIcon, LocationIcon, ClockIcon, ChatIcon } from "../../lib/cccIcons"
import { useSearchParams } from "react-router-dom"
import { getCurrentPosition } from "../../lib/geolocation"
import { useAuth } from "../../contexts/AuthContext"
import { useLanguage } from "../../contexts/LanguageContext"
import { useNavigate } from "react-router-dom"
import toast from "react-hot-toast"
import ProviderStorefront from "./ProviderStorefront"

const DAYS_EN = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"]
const DAYS_SW = ["Jumapili","Jumatatu","Jumanne","Jumatano","Alhamisi","Ijumaa","Jumamosi"]

export default function CustomerDiscover() {
  const isMobile = useIsMobile()
  const { user } = useAuth()
  const { t, language } = useLanguage()
  const navigate = useNavigate()
  const [searchParams] = useSearchParams()
  const [providers, setProviders] = useState([])
  const [ratings, setRatings] = useState({})
  const [bundles, setBundles] = useState([])
  const [drivers, setDrivers] = useState([])
  const [services, setServices] = useState([])
  const [businessHours, setBusinessHours] = useState({})
  const [closures, setClosures] = useState({})
  const [favorites, setFavorites] = useState([])
  const [tab, setTab] = useState("providers")
  const [search, setSearch] = useState("")
  const [selectedProvider, setSelectedProvider] = useState(null)
  const [loading, setLoading] = useState(true)
  const [userLocation, setUserLocation] = useState(null)
  const [locating, setLocating] = useState(false)
  const [sortBy, setSortBy] = useState("default")
  const [providerTypeFilter, setProviderTypeFilter] = useState("all")
  const [partsSearch, setPartsSearch] = useState("")
  const [partResults, setPartResults] = useState([])
  const [searchingParts, setSearchingParts] = useState(false)
  const [carModel, setCarModel] = useState("")
  const [maxDistance, setMaxDistance] = useState(null)
  const [showFilters, setShowFilters] = useState(false)
  const [priceRange, setPriceRange] = useState({ min:"", max:"" })
  const [onlyOpen, setOnlyOpen] = useState(false)
  const [onlyVerified, setOnlyVerified] = useState(false)

  const DAYS = language === "sw" ? DAYS_SW : DAYS_EN

  useEffect(() => {
    load()
    if (user) loadFavorites()
    const sub = supabase.channel("discover-live")
      .on("postgres_changes", { event:"*", schema:"public", table:"driver_status" }, () => loadDrivers())
      .on("postgres_changes", { event:"*", schema:"public", table:"profiles" }, () => load())
      .on("postgres_changes", { event:"*", schema:"public", table:"services" }, () => loadServices())
      .on("postgres_changes", { event:"*", schema:"public", table:"business_hours" }, () => loadBusinessHours())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  useEffect(() => {
    const providerId = searchParams.get("provider")
    if (!providerId || providers.length === 0) return
    const found = providers.find(p => p.id === providerId)
    if (found) setSelectedProvider(found)
    else {
      supabase.from("profiles").select("*").eq("id", providerId).single()
        .then(({ data }) => { if (data) setSelectedProvider(data) })
    }
  }, [searchParams, providers])

  async function load() {
    await Promise.all([loadProviders(), loadDrivers(), loadServices(), loadBundles(), loadBusinessHours(), loadClosures()])
    setLoading(false)
  }

  async function loadProviders() {
    const { data } = await supabase.from("verified_providers")
      .select("*")
      .not("first_name","ilike","%test%")
    setProviders(data||[])
    if (data?.length) {
      const { data: reviews } = await supabase.from("reviews")
        .select("provider_id,provider_rating").in("provider_id", data.map(p=>p.id))
      if (reviews?.length) {
        const rMap = {}
        reviews.forEach(r => {
          if (!rMap[r.provider_id]) rMap[r.provider_id] = []
          rMap[r.provider_id].push(r.provider_rating)
        })
        const avgMap = {}
        Object.keys(rMap).forEach(id => {
          const arr = rMap[id]
          avgMap[id] = (arr.reduce((s,r)=>s+r,0)/arr.length).toFixed(1)
        })
        setRatings(avgMap)
      }
    }
  }

  async function loadDrivers() {
    const { data } = await supabase.from("profile_public").select("*").eq("role","driver").eq("is_active",true)
    setDrivers(data||[])
  }

  async function loadServices() {
    const { data } = await supabase.from("services")
      .select("*, profile_public!inner(id,first_name,last_name,business_name,is_verified)")
      .eq("is_active",true).eq("profile_public.is_verified",true).neq("category","go_service").order("created_at",{ascending:false})
    setServices(data||[])
  }
  async function loadBundles() {
    const { data } = await supabase.from("service_bundles")
      .select("*, profile_public:profiles!service_bundles_provider_id_fkey!inner(id,first_name,last_name,business_name,documents_verified)")
      .eq("is_active",true).eq("profile_public.documents_verified",true).order("created_at",{ascending:false})
    setBundles(data||[])
  }

  async function loadBusinessHours() {
    const { data } = await supabase.from("business_hours").select("*")
    if (data) {
      const map = {}
      data.forEach(h => {
        if (!map[h.provider_id]) map[h.provider_id] = {}
        map[h.provider_id][h.day_of_week] = h
      })
      setBusinessHours(map)
    }
  }

  async function loadClosures() {
    const today = new Date().toISOString().split("T")[0]
    const { data } = await supabase.from("business_closures").select("*").gte("closure_date", today)
    if (data) {
      const map = {}
      data.forEach(c => {
        if (!map[c.provider_id]) map[c.provider_id] = []
        map[c.provider_id].push(c)
      })
      setClosures(map)
    }
  }

  async function searchParts(query, car) {
    if (!query && !car) { setPartResults([]); return }
    setSearchingParts(true)
    try {
      let q = supabase.from("inventory").select("*, profiles!inventory_provider_id_fkey(business_name,first_name,last_name,city,is_verified)").eq("is_active",true).gt("stock_quantity",0)
      if (query) q = q.ilike("name", `%${query}%`)
      if (car) q = q.contains("compatible_cars", [car])
      const { data } = await q.limit(20)
      setPartResults(data||[])
    } catch(e) { console.error(e) }
    finally { setSearchingParts(false) }
  }

  async function loadFavorites() {
    const { data } = await supabase.from("favorites").select("provider_id").eq("customer_id", user.id)
    setFavorites((data||[]).map(f=>f.provider_id))
  }

  async function toggleFavorite(e, providerId) {
    e.stopPropagation()
    if (!user) return toast.error(t("signIn"))
    if (favorites.includes(providerId)) {
      await supabase.from("favorites").delete().eq("customer_id", user.id).eq("provider_id", providerId)
      setFavorites(f=>f.filter(id=>id!==providerId))
      toast.success(language==="sw"?"Imeondolewa kwenye vipendwa":"Removed from favorites")
    } else {
      await supabase.from("favorites").insert({ customer_id:user.id, provider_id:providerId })
      setFavorites(f=>[...f, providerId])
      toast.success(language==="sw"?"Imehifadhiwa kwenye vipendwa Γ¥ñ∩╕Å":"Saved to favorites Γ¥ñ∩╕Å")
    }
  }

  function detectLocation() {
    setLocating(true)
    getCurrentPosition().then(pos => {
        setUserLocation({ lat:pos.latitude, lng:pos.longitude })
        setSortBy("distance")
        setLocating(false)
        toast.success(language==="sw"?"Mahali pamegunduliwa":"Location detected")
      }).catch(err => { toast.error(err.message||t("error")); setLocating(false) })}

  function getDistance(p) {
    if (!userLocation||!p.latitude||!p.longitude) return null
    const R = 6371
    const dLat = (p.latitude-userLocation.lat)*Math.PI/180
    const dLng = (p.longitude-userLocation.lng)*Math.PI/180
    const a = Math.sin(dLat/2)**2+Math.cos(userLocation.lat*Math.PI/180)*Math.cos(p.latitude*Math.PI/180)*Math.sin(dLng/2)**2
    return R*2*Math.asin(Math.sqrt(a))
  }

  function getDisplayName(p) {
    if (p.business_name?.trim()) return p.business_name.trim()
    return `${p.first_name||""} ${p.last_name||""}`.trim()||"Provider"
  }

  function getProviderStatus(providerId) {
    const today = new Date()
    const dayOfWeek = today.getDay()
    const todayStr = today.toISOString().split("T")[0]
    const todayClosure = closures[providerId]?.find(c=>c.closure_date===todayStr)
    if (todayClosure) return { open:false, label:`${t("closed")} ΓÇö ${todayClosure.reason||""}`, color:"#e24b4a" }
    const provHours = businessHours[providerId]
    if (!provHours||Object.keys(provHours).length===0) return null
    const hours = provHours[dayOfWeek]
    if (!hours||!hours.is_open) return { open:false, label:t("closedToday"), color:"#e24b4a" }
    const now = today.getHours()*60+today.getMinutes()
    const openStr = hours.open_time?.slice(0,5)||"08:00"
    const closeStr = hours.close_time?.slice(0,5)||"18:00"
    const open = parseInt(openStr.split(":")[0])*60+parseInt(openStr.split(":")[1])
    const close = parseInt(closeStr.split(":")[0])*60+parseInt(closeStr.split(":")[1])
    if (now>=open&&now<=close) return { open:true, label:`${t("open")} ┬╖ ${language==="sw"?"Inafunga":"Closes"} ${closeStr}`, color:"#1d9e75" }
    if (now<open) return { open:false, label:`${language==="sw"?"Inafungua":"Opens at"} ${openStr}`, color:"#e6821e" }
    return { open:false, label:t("closedNow"), color:"#e24b4a" }
  }

  function getWeekHours(providerId) {
    const hours = businessHours[providerId]
    if (!hours||Object.keys(hours).length===0) return null
    return DAYS.map((day,i)=>({
      day, dayIndex:i,
      is_open: hours[i]?.is_open??false,
      open_time: hours[i]?.open_time?.slice(0,5)||"08:00",
      close_time: hours[i]?.close_time?.slice(0,5)||"18:00",
    }))
  }

  function providerServices(providerId) {
    return services.filter(s=>s.provider_id===providerId)
  }

  function formatPrice(s) {
    return Number(s.discounted_price||s.price||0).toFixed(2)
  }

  let filteredProviders = providers.filter(p=>{
    const matchSearch = `${getDisplayName(p)} ${p.first_name||""} ${p.last_name||""} ${p.city||""}`.toLowerCase().includes(search.toLowerCase())
    const matchVerified = !onlyVerified||p.is_verified
    const status = getProviderStatus(p.id)
    const matchOpen = !onlyOpen||status?.open===true
    const dist = getDistance(p)
    const matchDist = !maxDistance||dist===null||dist<=maxDistance
    const matchType = providerTypeFilter==="all"||p.provider_type===providerTypeFilter
    return matchSearch&&matchVerified&&matchOpen&&matchDist&&matchType
  })

  if (sortBy==="distance"&&userLocation) {
    filteredProviders = [...filteredProviders].sort((a,b)=>(getDistance(a)??9999)-(getDistance(b)??9999))
  } else if (sortBy==="name") {
    filteredProviders = [...filteredProviders].sort((a,b)=>getDisplayName(a).localeCompare(getDisplayName(b)))
  }

  let filteredServices = services.filter(s=>{
    const matchSearch = `${s.name} ${s.category}`.toLowerCase().includes(search.toLowerCase())
    const price = Number(s.discounted_price||s.price||0)
    const matchMin = !priceRange.min||price>=Number(priceRange.min)
    const matchMax = !priceRange.max||price<=Number(priceRange.max)
    return matchSearch&&matchMin&&matchMax
  })

  const filteredDrivers = drivers.filter(d=>
    `${d.first_name} ${d.last_name}`.toLowerCase().includes(search.toLowerCase())
  )

  const inp = { width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"10px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif" }

  return (
    <div>
      <div style={{ marginBottom:"1.25rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:20, fontWeight:800, color:"#000000", marginBottom:4 }}>
          {t("discoverServices")}
        </div>
        <div style={{ fontSize:12, color:"#777777" }}>
          {providers.length} {t("providers").toLowerCase()} ┬╖ {drivers.filter(d=>d.is_online).length} {t("drivers").toLowerCase()} {t("online").toLowerCase()} ┬╖ {services.length} {t("services").toLowerCase()}
        </div>
      </div>

      <div style={{ display:"flex", gap:8, marginBottom:"1rem", flexWrap:"wrap" }}>
        <input value={search} onChange={e=>setSearch(e.target.value)}
          placeholder={t("searchGarages")}
          style={{ ...inp, flex:1, minWidth:180 }}/>
        <button onClick={detectLocation} disabled={locating}
          style={{ background:userLocation?"#f0fdf4":"#f5f5f5", border:`1px solid ${userLocation?"#1d9e7540":"#e0e0e0"}`, borderRadius:8, color:userLocation?"#1d9e75":"#555", fontSize:12, padding:"0 14px", cursor:"pointer", whiteSpace:"nowrap", fontFamily:"'DM Sans',sans-serif" }}>
          {locating?t("detecting"):<><LocationIcon size={14} color="#e6821e" /> {t("nearMe")}</>}
        </button>
        <button onClick={()=>setShowFilters(f=>!f)}
          style={{ background:showFilters?"#fff8f0":"#f5f5f5", border:`1px solid ${showFilters?"#e6821e40":"#e0e0e0"}`, borderRadius:8, color:showFilters?"#e6821e":"#555", fontSize:12, padding:"0 14px", cursor:"pointer", fontFamily:"'DM Sans',sans-serif" }}>
          {t("filters")} {showFilters?"Γû▓":"Γû╝"}
        </button>
      </div>

      {/* Provider type filter */}
      <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap" }}>
        {[
          { key:"all", label:"All", icon:"search" },
          { key:"garage", label:"Garage", icon:"services" },
          { key:"parts_dealer", label:"Parts", icon:"parts" },
          { key:"accessories_shop", label:"Accessories", icon:"marketplace" },
          { key:"tyre_shop", label:"Tyres", icon:"vehicle" },
          { key:"auto_electrician", label:"Electrician", icon:"power" },
          { key:"car_wash", label:"Car Wash", icon:"discover" },
          { key:"panel_beater", label:"Panel Beater", icon:"mechanic" },
          { key:"auto_glass", label:"Auto Glass", icon:"shield" },
        ].map(tp=>(
          <button key={tp.key} onClick={()=>setProviderTypeFilter(tp.key)}
            style={{ padding:"6px 12px", borderRadius:8, border:"none", fontSize:11, cursor:"pointer", background:providerTypeFilter===tp.key?"#e6821e":"#f0f0f0", color:providerTypeFilter===tp.key?"#fff":"#555", fontFamily:"DM Sans,sans-serif", whiteSpace:"nowrap" }}>
            {tp.icon==="search"?<SearchIcon size={14} color={providerTypeFilter===tp.key?"#fff":"#555"}/>:
    tp.icon==="services"?<ServicesIcon size={14} color={providerTypeFilter===tp.key?"#fff":"#555"}/>:
    tp.icon==="parts"?<PartsIcon size={14} color={providerTypeFilter===tp.key?"#fff":"#555"}/>:
    tp.icon==="marketplace"?<MarketplaceIcon size={14} color={providerTypeFilter===tp.key?"#fff":"#555"}/>:
    tp.icon==="vehicle"?<VehicleIcon size={14} color={providerTypeFilter===tp.key?"#fff":"#555"}/>:
    tp.icon==="power"?<PowerIcon size={14} color={providerTypeFilter===tp.key?"#fff":"#555"}/>:
    tp.icon==="discover"?<DiscoverIcon size={14} color={providerTypeFilter===tp.key?"#fff":"#555"}/>:
    tp.icon==="mechanic"?<MechanicIcon size={14} color={providerTypeFilter===tp.key?"#fff":"#555"}/>:
    tp.icon==="shield"?<ShieldIcon size={14} color={providerTypeFilter===tp.key?"#fff":"#555"}/>:
    null} {tp.label}
          </button>
        ))}
      </div>

      {showFilters&&(
        <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:"1rem", display:"grid", gridTemplateColumns:isMobile?"1fr":"repeat(auto-fill,minmax(180px,1fr))", gap:12 }}>
          <div>
            <div style={{ fontSize:11, color:"#777777", textTransform:"uppercase", marginBottom:6 }}>{t("sortBy")}</div>
            <select value={sortBy} onChange={e=>setSortBy(e.target.value)} style={{ ...inp, padding:"7px 10px" }}>
              <option value="default">{t("defaultSort")}</option>
              <option value="distance">{t("nearest")}</option>
              <option value="name">{t("nameAZ")}</option>
            </select>
          </div>
          {userLocation&&(
            <div>
              <div style={{ fontSize:11, color:"#777777", textTransform:"uppercase", marginBottom:6 }}>{t("maxDistance")}</div>
              <select value={maxDistance||""} onChange={e=>setMaxDistance(e.target.value?Number(e.target.value):null)} style={{ ...inp, padding:"7px 10px" }}>
                <option value="">{t("anyDistance")}</option>
                <option value="5">5 km</option>
                <option value="10">10 km</option>
                <option value="25">25 km</option>
                <option value="50">50 km</option>
              </select>
            </div>
          )}
          <div>
            <div style={{ fontSize:11, color:"#777777", textTransform:"uppercase", marginBottom:6 }}>{t("priceRange")}</div>
            <div style={{ display:"flex", gap:6 }}>
              <input type="number" placeholder="Min" value={priceRange.min} onChange={e=>setPriceRange(p=>({...p,min:e.target.value}))} style={{ ...inp, padding:"7px 10px" }}/>
              <input type="number" placeholder="Max" value={priceRange.max} onChange={e=>setPriceRange(p=>({...p,max:e.target.value}))} style={{ ...inp, padding:"7px 10px" }}/>
            </div>
          </div>
          <div style={{ display:"flex", flexDirection:"column", gap:8, justifyContent:"flex-end" }}>
            <label style={{ display:"flex", alignItems:"center", gap:8, cursor:"pointer", fontSize:12, color:"#555555" }}>
              <input type="checkbox" checked={onlyOpen} onChange={e=>setOnlyOpen(e.target.checked)}/>
              {t("openNow")}
            </label>
            <label style={{ display:"flex", alignItems:"center", gap:8, cursor:"pointer", fontSize:12, color:"#555555" }}>
              <input type="checkbox" checked={onlyVerified} onChange={e=>setOnlyVerified(e.target.checked)}/>
              {t("verifiedOnly")}
            </label>
          </div>
          <div style={{ display:"flex", alignItems:"flex-end" }}>
            <button onClick={()=>{ setSortBy("default"); setMaxDistance(null); setPriceRange({min:"",max:""}); setOnlyOpen(false); setOnlyVerified(false); setUserLocation(null) }}
              style={{ background:"none", border:"1px solid #dddddd", borderRadius:7, color:"#666", fontSize:11, padding:"7px 12px", cursor:"pointer" }}>
              {t("clearFilters")}
            </button>
          </div>
        </div>
      )}

      <div style={{ display:"flex", gap:6, marginBottom:"1.25rem" }}>
        {[
          { key:"providers", label:`${t("providers")} (${filteredProviders.length})` },
          { key:"services", label:`${t("services")} (${filteredServices.length})` },
          { key:"drivers", label:`${t("drivers")} (${filteredDrivers.filter(d=>d.is_online).length} ${t("online").toLowerCase()})` },
        ].map(tab2=>(
          <button key={tab2.key} onClick={()=>{ setTab(tab2.key); setSearch(""); setSelectedProvider(null) }}
            style={{ padding:"8px 16px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", fontFamily:"'DM Sans',sans-serif", background:tab===tab2.key?"#e6821e":"#555555", color:tab===tab2.key?"#fff":"#666", fontWeight:tab===tab2.key?700:400 }}>
            {tab2.label}
          </button>
        ))}
      </div>

      {loading&&<div style={{ color:"#777777", fontSize:13 }}>{t("loading")}</div>}

      {tab==="providers"&&!selectedProvider&&(
        <div style={{ display:"grid", gap:10 }}>
          {filteredProviders.length===0&&!loading&&<div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"2rem" }}>{t("noProvidersFound")}</div>}
          {filteredProviders.map(p=>{
            const ps = providerServices(p.id)
            const status = getProviderStatus(p.id)
            const dist = getDistance(p)
            const isFav = favorites.includes(p.id)
            return (
              <div key={p.id}
                style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem", cursor:"pointer", transition:"border-color 0.12s" }}
                onMouseEnter={e=>e.currentTarget.style.borderColor="#e6821e40"}
                onMouseLeave={e=>e.currentTarget.style.borderColor="#eeeeee"}
                onClick={()=>setSelectedProvider(p)}>
                <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:10 }}>
                  <div style={{ width:48, height:48, borderRadius:12, background:"#fff8f0", border:"1px solid #e6821e30", display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontSize:20, fontWeight:800, color:"#e6821e", flexShrink:0 }}>
                    {getDisplayName(p)[0]?.toUpperCase()}
                  </div>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:2, flexWrap:"wrap" }}>
                      <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#000000" }}>{getDisplayName(p)}</div>
                      {p.is_verified&&<span style={{ fontSize:10, color:"#1d9e75", background:"#f0fdf4", padding:"1px 6px", borderRadius:10 }}>Γ£ô {t("verified")}</span>}
                      {p.provider_type&&p.provider_type!=="garage"&&<span style={{ fontSize:10, color:"#8b5cf6", background:"#faf5ff", padding:"1px 6px", borderRadius:10 }}>{p.provider_type.replace(/_/g," ")}</span>}
                    </div>
