                <div style={{ width:52, height:52, borderRadius:12, background:"#fff8f0", border:"1px solid #e6821e30", display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontSize:20, fontWeight:800, color:"#e6821e", flexShrink:0 }}>
                  {displayName[0]?.toUpperCase()}
                </div>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:2, flexWrap:"wrap" }}>
                    <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#000000" }}>{displayName}</div>
                    {p?.is_verified&&<span style={{ fontSize:10, color:"#1d9e75", background:"#f0fdf4", padding:"1px 6px", borderRadius:10 }}>Γ£ô Verified</span>}
                    <span style={{ fontSize:10, padding:"1px 6px", borderRadius:10, background:p?.is_online?"#f0fdf4":"#ffffff", color:p?.is_online?"#1d9e75":"#555" }}>
                      {p?.is_online?"ΓùÅ Online":"Γùï Offline"}
                    </span>
                  </div>
                  {p?.city&&<div style={{ fontSize:11, color:"#777777", display:"flex", alignItems:"center", gap:3 }}><LocationIcon size={11} color="#777777"/> {p.city}</div>}
                </div>
                <button onClick={()=>removeFavorite(f.provider_id)}
                  style={{ background:"#fff5f5", border:"1px solid #e24b4a40", borderRadius:8, color:"#e24b4a", fontSize:11, padding:"6px 10px", cursor:"pointer", flexShrink:0 }}>
                  <HeartIcon size={13} color="#e24b4a" /> Remove
                </button>
              </div>

              {provServices.length>0&&(
                <div style={{ marginBottom:12 }}>
                  <div style={{ fontSize:11, color:"#777777", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:8 }}>Services</div>
                  <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                    {provServices.slice(0,4).map(s=>(
                      <span key={s.id} style={{ fontSize:11, padding:"4px 10px", borderRadius:6, background:"#f5f5f5", color:"#555555", border:"1px solid #e5e5e5" }}>
                        {s.name} ┬╖ KES {Number(s.discounted_price||s.price).toLocaleString()}
                      </span>
                    ))}
                    {provServices.length>4&&<span style={{ fontSize:11, padding:"4px 10px", borderRadius:6, background:"#f5f5f5", color:"#777777" }}>+{provServices.length-4} more</span>}
                  </div>
                </div>
              )}

              <div style={{ display:"flex", gap:8 }}>
                <button onClick={()=>navigate("/dashboard/services")}
                  style={{ background:"#e6821e", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"8px 16px", cursor:"pointer" }}>
                  Book now
                </button>
                <button onClick={()=>navigate("/dashboard/discover")}
                  style={{ background:"none", border:"1px solid #dddddd", borderRadius:8, color:"#555555", fontSize:12, padding:"8px 16px", cursor:"pointer" }}>
                  View profile
                </button>
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

import { useState, useEffect } from "react"
import { useNavigate } from "react-router-dom"
import { supabase } from "../../lib/supabase"
import * as Sentry from "@sentry/react"
import { PartsIcon, BatteryIcon, FuelIcon, KeyIcon, OverheatIcon, TowingIcon, GOServiceIcon, LocationIcon, VehicleIcon, SearchIcon, WarningIcon, PhoneCallIcon, SignalIcon, CheckIcon, CloseIcon } from "../../lib/cccIcons"
import DarajaPayment from "../shared/DarajaPayment"
import { applyRateLimit, RATE_LIMITS } from "../../lib/rateLimit"
import { sanitizeAmount } from "../../lib/sanitize"
import { getCurrentPosition } from "../../lib/geolocation"
import PhotoManager from "../shared/PhotoManager"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const EMERGENCY_SERVICE_MAP = {
  flat_tire: ["tyre","tire","puncture","wheel","flat","rim","valve"],
  dead_battery: ["battery","jump","start","electrical","charge","alternator"],
  out_of_fuel: ["fuel","petrol","diesel","gas","empty tank"],
  car_wont_start: ["battery","electrical","ignition","start","mechanical","starter","spark"],
  overheating: ["cooling","overheat","radiator","water","temperature","diagnosis","coolant"],
  towing: ["tow","towing","recovery","transport","haul"],
  locked_out: ["lock","key","locked","locksmith","door"],
  accident: ["accident","collision","crash","dent","body","panel"],
  brake_failure: ["brake","braking","pad","disc","rotor"],
  warning_light: ["diagnostic","diagnosis","scan","warning","light","check engine","computer"],
  windshield_damage: ["windshield","windscreen","glass","crack","chip"],
  other: []
}

const EMERGENCY_TYPES = [
  { key:"flat_tire", label:"Flat tire", icon:"parts" },
  { key:"dead_battery", label:"Dead battery", icon:"battery" },
  { key:"out_of_fuel", label:"Out of fuel", icon:"fuel" },
  { key:"car_wont_start", label:"Car won't start", icon:"key" },
  { key:"overheating", label:"Overheating", icon:"overheat" },
  { key:"towing", label:"Need towing", icon:"towing" },
  { key:"locked_out", label:"Locked out", icon:"key" },
  { key:"accident", label:"Accident/collision", icon:"emergency" },
  { key:"brake_failure", label:"Brake failure", icon:"emergency" },
  { key:"warning_light", label:"Warning light on", icon:"overheat" },
  { key:"windshield_damage", label:"Windshield damage", icon:"parts" },
  { key:"other", label:"Other emergency", icon:"emergency" },
]

export default function CustomerGoService() {
  const { user, profile } = useAuth()
  const navigate = useNavigate()
  const isMobile = useIsMobile()
  const [step, setStep] = useState("select")
  const [emergencyType, setEmergencyType] = useState("")
  const [location, setLocation] = useState({ lat:null, lng:null, address:"" })
  const [assignedMechanic, setAssignedMechanic] = useState(null)
  const [mechanicETA, setMechanicETA] = useState(null)
  const [details, setDetails] = useState("")
  const [vehicle, setVehicle] = useState("")
  const [vehicles, setVehicles] = useState([])
  const [locating, setLocating] = useState(false)
  const [sharingLive, setSharingLive] = useState(false)
  const [liveInterval, setLiveInterval] = useState(null)
  const [submitting, setSubmitting] = useState(false)
  const [booking, setBooking] = useState(null)
  const [goRequest, setGoRequest] = useState(null)
  const [attemptNumber, setAttemptNumber] = useState(1)
  const [timeLeft, setTimeLeft] = useState(null)
  const [activeGoBookings, setActiveGoBookings] = useState([])
  const [goServices, setGoServices] = useState([])
  const [searchText, setSearchText] = useState("")
  const searchWords = searchText.trim().toLowerCase().split(/\s+/).filter(Boolean)
  const emergencyKeywords = emergencyType ? (EMERGENCY_SERVICE_MAP[emergencyType]||[]) : []
  const allKeywords = [...emergencyKeywords, ...searchWords]
  const matchesService = (s) => allKeywords.some(k=>s.name?.toLowerCase().includes(k)||s.description?.toLowerCase().includes(k))
  const filteredGoServices = allKeywords.length
    ? goServices.filter(matchesService).concat(goServices.filter(s=>!matchesService(s)).map(s=>({...s,_dimmed:true})))
    : goServices
  const [selectedService, setSelectedService] = useState(null)
  // Auto-select the nearest matching GO service behind the scenes - the customer no longer
  // manually picks a provider; the system dispatches automatically via assign-go-provider
  useEffect(() => {
    if (!selectedService && filteredGoServices.length > 0) setSelectedService(filteredGoServices[0])
  }, [filteredGoServices])

  const [showDepositPayment, setShowDepositPayment] = useState(false)
  const [pendingGoBooking, setPendingGoBooking] = useState(null)
  const [showServiceFeePayment, setShowServiceFeePayment] = useState(false)
  const [payingCallout, setPayingCallout] = useState(false)
  const [calloutFee, setCalloutFee] = useState(500)
  const [calloutProviderRate, setCalloutProviderRate] = useState(0.70)
  const [serviceProviderRate, setServiceProviderRate] = useState(0.85)
  const [goPartsRequests, setGoPartsRequests] = useState([])
  useEffect(() => {
    if (user) {
      loadVehicles()
      loadActiveGoBookings()
      loadGoServices()
      // Load GO commission rates
      supabase.from("app_settings").select("key,value").in("key",["go_callout_fee","go_callout_provider_rate","go_service_provider_rate"]).then(({data})=>{
        data?.forEach(s=>{ if(s.key==="go_callout_fee") setCalloutFee(Number(s.value)); if(s.key==="go_callout_provider_rate") setCalloutProviderRate(Number(s.value)/100); if(s.key==="go_service_provider_rate") setServiceProviderRate(Number(s.value)/100) })
      })
    }
  }, [user])

  useEffect(() => {
    if (!booking) return
    supabase.from("go_parts_requests").select("*, inventory(name,price)").eq("booking_id", booking.id).then(({data})=>{ setGoPartsRequests(data||[]) }).catch(()=>{})
    const sub = supabase.channel(`go-booking-${booking.id}`)
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"go_parts_requests", filter:`booking_id=eq.${booking.id}` },
        payload => {
          setGoPartsRequests(prev=>[...prev, payload.new])
          toast("≡ƒöº Mechanic has requested a part", { icon:"≡ƒöº" })
        })
      .on("postgres_changes", { event:"UPDATE", schema:"public", table:"go_parts_requests", filter:`booking_id=eq.${booking.id}` },
        payload => { setGoPartsRequests(prev=>prev.map(r=>r.id===payload.new.id?{...r,...payload.new}:r)) })
      .on("postgres_changes", { event:"UPDATE", schema:"public", table:"bookings", filter:`id=eq.${booking.id}` },
        payload => {
          setBooking(b=>({...b,...payload.new}))
          if (payload.new.status==="completed") {
            setShowServiceFeePayment(true)
            toast.success("Service complete! Please pay the service fee ≡ƒÆ│")
          }
          if (payload.new.status==="confirmed"||payload.new.status==="in-progress") {
            setStep("accepted")
            setTimeLeft(null) // Stop the countdown timer
            toast.success("Provider found! Help is on the way ≡ƒÜ¿")
            // Load mechanic details
            if(payload.new.assigned_mechanic_id) fetchMechanicAndETA(payload.new.id||booking?.id)
          }
        })
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"go_service_requests", filter:`booking_id=eq.${booking.id}` },
        payload => {
          setGoRequest(payload.new)
          setAttemptNumber(payload.new.attempt_number)
          startCountdown(15 * 60)
        })
      .on("postgres_changes", { event:"UPDATE", schema:"public", table:"go_service_requests", filter:`booking_id=eq.${booking.id}` },
        payload => {
          setGoRequest(payload.new)
          if (payload.new.status==="timeout") {
            setAttemptNumber(n=>n+1)
            if (attemptNumber >= 5) {
              setStep("no_providers")
              toast.error("No providers available at this time")
            } else {
              toast("Looking for next provider...", { icon:"≡ƒöì" })
              startCountdown(15 * 60) // Reset timer for next provider
              startCountdown(15 * 60)
            }
          }
        })
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [booking?.id, attemptNumber])

  useEffect(() => {
    if (timeLeft === null) return
    if (timeLeft <= 0) return
    const timer = setTimeout(() => setTimeLeft(t=>t-1), 1000)
    return () => clearTimeout(timer)
  }, [timeLeft])

  function startCountdown(seconds) { setTimeLeft(seconds) }

  async function loadVehicles() {
    const { data } = await supabase.from("vehicles").select("*").eq("user_id", user.id)
    setVehicles(data||[])
  }

  async function loadActiveGoBookings() {
    const { data } = await supabase.from("bookings")
      .select("*")
      .eq("customer_id", user.id)
      .eq("is_emergency", true)
      .not("status", "in", "(completed,cancelled)")
      .order("created_at", { ascending:false })
    setActiveGoBookings(data||[])
    if (data && data.length > 0 && data[0].go_callout_paid) {
      const active = data[0]
      const elapsed = Math.floor((Date.now() - new Date(active.created_at).getTime()) / 1000)
      const remaining = Math.max(0, 15*60 - elapsed)
      if (remaining > 0 && active.status === "pending") {
        setBooking(active)
        setStep("waiting")
        setTimeLeft(remaining)
      }
    }
  }
  function distanceKm(lat1, lon1, lat2, lon2) {
    const R = 6371
    const dLat = (lat2-lat1) * Math.PI/180
    const dLon = (lon2-lon1) * Math.PI/180
    const a = Math.sin(dLat/2)*Math.sin(dLat/2) + Math.cos(lat1*Math.PI/180)*Math.cos(lat2*Math.PI/180)*Math.sin(dLon/2)*Math.sin(dLon/2)
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a))
  }
  async function loadGoServices() {
    const { data } = await supabase.from("services")
      .select("*, profiles(business_name,first_name,last_name,city,latitude,longitude,go_service_radius_km,marketplace_rating,marketplace_review_count,is_online,carries_parts_for_go,go_parts_carried)")
      .eq("category", "go_service")
      .eq("is_active", true).eq("profiles.is_active", true)
    let services = data||[]
    if (location.lat && location.lng) {
      services = services.map(s => {
        const p = s.profiles
        const dist = (p?.latitude && p?.longitude) ? distanceKm(location.lat, location.lng, p.latitude, p.longitude) : null
        return { ...s, _distance: dist }
      }).filter(s => {
        if (s._distance === null) return true
        const radius = s.profiles?.go_service_radius_km || 15
        return s._distance <= radius
      }).sort((a,b) => (a._distance ?? 999) - (b._distance ?? 999))
    }
    setGoServices(services)
  }

  async function fetchMechanicAndETA(bookingId) {
    try {
      const { data: booking } = await supabase.from("bookings")
        .select("assigned_mechanic_id")
        .eq("id", bookingId).single()
      if (!booking?.assigned_mechanic_id) return
      const { data: mech } = await supabase.from("mechanics")
        .select("*, profiles!mechanics_provider_id_fkey(business_name)")
        .eq("id", booking.assigned_mechanic_id).single()
      if (mech) {
        setAssignedMechanic(mech)
        // Calculate ETA if mechanic has location
        if (mech.current_latitude && mech.current_longitude && location.lat && location.lng) {
          const R = 6371
          const dLat = (mech.current_latitude - location.lat) * Math.PI/180
          const dLng = (mech.current_longitude - location.lng) * Math.PI/180
          const a = Math.sin(dLat/2)*Math.sin(dLat/2) + Math.cos(location.lat*Math.PI/180)*Math.cos(mech.current_latitude*Math.PI/180)*Math.sin(dLng/2)*Math.sin(dLng/2)
          const dist = R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a))
          const etaMins = Math.round(dist / 30 * 60) // avg 30km/h in Nairobi traffic
          setMechanicETA(etaMins)
        }
      }
    } catch(e) { console.warn("ETA error:", e.message) }
  }

  async function detectLocation() {
    setLocating(true)
    try {
      const pos = await getCurrentPosition()
      const lat = pos.latitude
      const lng = pos.longitude
      setLocation(l=>({...l, lat, lng}))
      try {
        const res = await fetch(`https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lng}&format=json`)
        const data = await res.json()
        setLocation({ lat, lng, address:data.display_name||`${lat.toFixed(4)}, ${lng.toFixed(4)}` })
      } catch { setLocation(l=>({...l, address:`${lat.toFixed(4)}, ${lng.toFixed(4)}`})) }
    } catch(err) {
      toast.error(err.message || "Could not get location ΓÇö please enter manually")
    } finally {
      setLocating(false)
    }
  }

  function startLiveSharing(bookingId) {
    if (liveInterval) return
    setSharingLive(true)
    const interval = setInterval(async () => {
      try {
        const pos = await getCurrentPosition()
        await supabase.from("booking_location_logs").insert({
          booking_id: bookingId,
          driver_id: null,
          lat: pos.latitude,
          lng: pos.longitude,
          source: "customer",
        })
      } catch(e) { console.warn("Live share error:", e.message) }
    }, 15000)
    setLiveInterval(interval)
  }
  function stopLiveSharing() {
    if (liveInterval) { clearInterval(liveInterval); setLiveInterval(null) }
    setSharingLive(false)
  }
  useEffect(() => {
    return () => { if (liveInterval) clearInterval(liveInterval) }
  }, [liveInterval])
  async function checkRateLimit() {
    const today = new Date().toISOString().split("T")[0]
    const { count } = await supabase.from("bookings").select("id",{count:"exact"}).eq("customer_id",user.id).eq("is_emergency",true).gte("created_at",today+"T00:00:00")
    return count||0
  }

  async function testBypassPayment() {
    if (!emergencyType) return toast.error("Please select emergency type")
    if (!location.lat) return toast.error("Please share your location")
    if (!selectedService) return toast.error("Please select a GO service")
    try {
      const { data: bk, error } = await supabase.from("bookings").insert({
        customer_id: user.id, provider_id: selectedService.provider_id,
        service_id: selectedService.id, service_name: selectedService.name,
        service_category: "go_service", is_emergency: true,
        emergency_type: emergencyType,
        emergency_location_lat: location.lat, emergency_location_lng: location.lng,
        emergency_location_address: location.address,
        booking_date: new Date().toISOString().split("T")[0],
        booking_time: new Date().toTimeString().slice(0,5),
        total_amount: calloutFee, go_callout_fee: calloutFee,
        go_callout_paid: true, payment_status: "paid", status: "pending",
        platform_commission: Number(selectedService.price)*(1-serviceProviderRate),
        provider_earnings: Number(selectedService.price)*serviceProviderRate,
        platform_commission_rate: (1-serviceProviderRate), provider_commission_rate: serviceProviderRate,
        payment_method: "test", notes: details, vehicle_id: vehicle||null, go_attempt_number: 1,
      }).select().single()
      if(error) throw error
      // Create go_service_request
      await supabase.from("go_service_requests").insert({ booking_id: bk.id, provider_id: selectedService.provider_id, status: "pending", attempt_number: 1 })
      await supabase.from("notifications").insert({ user_id: selectedService.provider_id, title: "≡ƒÜ¿ Emergency GO Service request!", message: "Test request: "+emergencyType.replace(/_/g," ")+" at "+location.address.slice(0,60), type: "error" })
      setBooking(bk); setStep("waiting"); startCountdown(15*60)
      toast.success("Test booking created! (No payment charged)")
    } catch(e) { toast.error(e.message) }
  }
  async function initiateCalloutPayment() {
    if (!emergencyType) return toast.error("Please select emergency type")
    if (!location.lat) return toast.error("Please share your location")
    if (!selectedService) return toast.error("Please select a GO service")
    const todayCount = await checkRateLimit()
    if (todayCount >= 2) return toast.error("Maximum 2 emergency requests per day.")
    setShowDepositPayment(true)
  }

  async function payCalloutFee() {
    setPayingCallout(true)
    try {
      Sentry.captureMessage("GO_CREATE_PROOF: about to insert booking with status=pending, no provider_id", { level: "info" })
      console.log("GO CREATE PATH - PROOF-2026-08-17-02: about to insert with status=pending")
      const { data: bk, error } = await supabase.from("bookings").insert({
        customer_id: user.id,
        // provider_id intentionally left unset - assign-go-provider picks the nearest available
        // provider automatically after this booking is created, matching the intended dispatch model
        service_id: selectedService.id,
        service_name: selectedService.name,
        service_category: "go_service",
        is_emergency: true,
        emergency_type: emergencyType,
        emergency_location_lat: location.lat,
        emergency_location_lng: location.lng,
        emergency_location_address: location.address,
        booking_date: new Date().toISOString().split("T")[0],
        booking_time: new Date().toTimeString().slice(0,5),
        total_amount: calloutFee,
        go_callout_fee: calloutFee,
        go_callout_paid: false,
        go_service_fee: Number(selectedService.price),
        go_service_fee_paid: false,
        // These reflect the callout fee only - that's the only amount actually collected at this
        // point. The service fee's own commission split happens separately when it's paid later.
        platform_commission: Math.round(calloutFee*(1-calloutProviderRate)),
        provider_earnings: Math.round(calloutFee*calloutProviderRate),
        platform_commission_rate: (1-calloutProviderRate),
        provider_commission_rate: calloutProviderRate,
        payment_method: "mpesa",
        payment_status: "pending",
        status: "pending",
        notes: details,
        vehicle_id: vehicle||null,
        go_attempt_number: 1,
      }).select().single()
      if (error) throw error
      Sentry.captureMessage("GO_CREATE_PROOF: booking created", { level: "info", extra: { bookingId: bk?.id, bookingNumber: bk?.booking_number, actualStatus: bk?.status, actualProviderId: bk?.provider_id } })
      console.log("GO CREATE PROOF - booking returned from DB:", { id: bk?.id, status: bk?.status, provider_id: bk?.provider_id })
      // Provider matching now happens ONLY after the callout fee payment genuinely confirms
      // (triggered from daraja-callback), not here - dispatching before payment even completes
      // meant a provider could be notified for a request the customer might never actually pay for.
      // Show Daraja payment modal
      setPendingGoBooking({ id: bk.id, amount: calloutFee })
      setShowDepositPayment(false)
    } catch(e) { toast.error(e.message||"Failed to create booking") }
    finally { setPayingCallout(false) }
  }
  // payServiceFee removed - payment now triggers automatically via go-request-service-payment
  // when the mechanic marks the job complete, and releases via daraja-callback on real confirmation
  async function submitEmergency() {
    if (!emergencyType) return toast.error("Please select emergency type")
    if (!location.lat) return toast.error("Please share your location")
    if (!selectedService) return toast.error("Please select a GO service")
    setSubmitting(true)
    try {
      const { data: bk, error } = await supabase.from("bookings").insert({
        customer_id: user.id,
        provider_id: selectedService.provider_id,
        service_id: selectedService.id,
        service_name: selectedService.name,
        service_category: "go_service",
        is_emergency: true,
        emergency_type: emergencyType,
        emergency_location_lat: location.lat,
        emergency_location_lng: location.lng,
        emergency_location_address: location.address,
        booking_date: new Date().toISOString().split("T")[0],
        booking_time: new Date().toTimeString().slice(0,5),
        total_amount: selectedService.price,
        platform_commission: Number(selectedService.price)*(1-serviceProviderRate),
        provider_earnings: Number(selectedService.price)*serviceProviderRate,
        platform_commission_rate: (1-serviceProviderRate),
        provider_commission_rate: serviceProviderRate,
        payment_method: "mpesa",
        payment_status: "pending",
        status: "pending",
        notes: details,
        vehicle_id: vehicle||null,
        go_attempt_number: 1,
      }).select().single()
      if (error) throw error
      // Create go_service_request so providers can see it
      const { error: reqError } = await supabase.from("go_service_requests").insert({
        booking_id: bk.id,
        provider_id: selectedService.provider_id,
        status: "pending",
        attempt_number: 1,
      })
      if (reqError) {
        console.error("Failed to create go_service_request:", reqError.message)
        toast.error("Dispatch issue: " + reqError.message)
      }
      // Notify provider
      await supabase.from("notifications").insert({
        user_id: selectedService.provider_id,
        title: "≡ƒÜ¿ Emergency GO Service request!",
