  )
}

import { LoyaltyIcon, TrophyIcon, StarIcon, SuccessIcon } from "../../lib/cccIcons";
import useIsMobile from "../../lib/useIsMobile"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import toast from "react-hot-toast"
import { useLanguage } from "../../contexts/LanguageContext"

function generateVoucherCode() {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
  const segments = [4,4,4].map(len=>Array.from({length:len},()=>chars[Math.floor(Math.random()*chars.length)]).join(""))
  return "CCC-" + segments.join("-")
}

export default function CustomerLoyalty() {
  const isMobile = useIsMobile()
  const { user } = useAuth()
  const { t } = useLanguage()
  const [loyalty, setLoyalty] = useState(null)
  const [bookings, setBookings] = useState([])
  const [loading, setLoading] = useState(true)
  const [redeeming, setRedeeming] = useState(false)
  const [redeemAmount, setRedeemAmount] = useState("")

  useEffect(() => { if (user) load() }, [user])

  async function load() {
    const [{ data: lp }, { data: bks }] = await Promise.all([
      supabase.from("loyalty_points").select("*").eq("user_id", user.id).maybeSingle(),
      supabase.from("bookings").select("service_name,total_amount,booking_date,status,created_at").eq("customer_id", user.id).eq("status", "completed").order("created_at", { ascending:false })
    ])
    setLoyalty(lp)
    setBookings(bks||[])
    setLoading(false)
  }

  const points = loyalty?.points || 0
  const lifetime = loyalty?.lifetime_points || 0
  const tier = points<1000?"Bronze":points<5000?"Silver":points<10000?"Gold":"Platinum"
  const tierColor = { Bronze:"#cd7f32", Silver:"#aaa", Gold:"#e6821e", Platinum:"#d4537e" }[tier]
  const tierNext = { Bronze:1000, Silver:5000, Gold:10000, Platinum:10000 }[tier]
  const tierBase = { Bronze:0, Silver:1000, Gold:5000, Platinum:10000 }[tier]
  const progress = tier==="Platinum"?100:Math.min(100,((points-tierBase)/(tierNext-tierBase))*100)

  // Redemption rate per tier: Bronze 100pts=KES 1, Silver 90pts=KES 1, Gold 80pts=KES 1, Platinum 70pts=KES 1
  const redemptionRate = { Bronze:100, Silver:90, Gold:80, Platinum:70 }[tier]
  const maxRedeemPoints = points
  const maxRedeemValue = (points / redemptionRate).toFixed(2)

  async function redeemPoints(e) {
    e.preventDefault()
    const pts = parseInt(redeemAmount)
    if (!pts || pts <= 0) return toast.error("Enter a valid amount")
    if (pts > points) return toast.error(`You only have ${points} points`)
    if (pts < redemptionRate) return toast.error(`Minimum redemption is ${redemptionRate} points (KES 1)`)
    const value = Math.floor(pts / redemptionRate)
    setRedeeming(true)
    try {
      const voucherCode = generateVoucherCode()
      const expires = new Date(Date.now()+90*24*60*60*1000).toISOString()

      await supabase.from("loyalty_points")
        .update({ points: points - pts })
        .eq("user_id", user.id)

      await supabase.from("service_vouchers").insert({
        voucher_code: voucherCode,
        customer_id: user.id,
        amount: value,
        expires_at: expires,
      })

      toast.success(`Redeemed ${pts} points for a KES ${value.toLocaleString()} voucher! Code: ${voucherCode} (valid 90 days)`)
      setRedeemAmount("")
      load()
    } catch(err) { toast.error(err.message) }
    finally { setRedeeming(false) }
  }

  const TIERS = [
    { name:"Bronze", min:0, max:999, rate:100, color:"#cd7f32" },
    { name:"Silver", min:1000, max:4999, rate:90, color:"#666666" },
    { name:"Gold", min:5000, max:9999, rate:80, color:"#e6821e" },
    { name:"Platinum", min:10000, max:null, rate:70, color:"#d4537e" },
  ]

  if (loading) return <div style={{ color:"#777777", fontSize:13 }}>Loading...</div>

  return (
    <div>
      <div style={{ background:"#ffffff", border:`1px solid ${tierColor}40`, borderRadius:12, padding:"1.25rem", marginBottom:"1.25rem" }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:12 }}>
          <div>
            <div style={{ fontSize:11, color:"#666", marginBottom:4 }}>Your points balance</div>
            <div style={{ fontFamily:"Syne", fontSize:36, fontWeight:800, color:tierColor, lineHeight:1 }}>{points.toLocaleString()}</div>
            <div style={{ fontSize:11, color:"#777777", marginTop:4 }}>Lifetime earned: {lifetime.toLocaleString()} pts</div>
          </div>
          <div style={{ textAlign:"right" }}>
            <span style={{ background:tierColor+"15", border:`1px solid ${tierColor}40`, color:tierColor, fontSize:12, padding:"4px 12px", borderRadius:20, fontWeight:600 }}>{tier}</span>
            <div style={{ fontSize:11, color:"#777777", marginTop:6 }}>
              {tier !== "Platinum" ? `${(tierNext-points).toLocaleString()} pts to ${TIERS[TIERS.findIndex(t=>t.name===tier)+1]?.name}` : "Max tier reached"}
            </div>
          </div>
        </div>
        <div style={{ height:6, background:"#f0f0f0", borderRadius:3, overflow:"hidden", marginBottom:6 }}>
          <div style={{ height:"100%", background:tierColor, borderRadius:3, width:progress+"%", transition:"width 0.5s" }}/>
        </div>
        <div style={{ display:"flex", justifyContent:"space-between", fontSize:10, color:"#888888" }}>
          <span>{tier} {tierBase.toLocaleString()}</span>
          {tier !== "Platinum" && <span>{tierNext.toLocaleString()} pts</span>}
        </div>
      </div>

      <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"repeat(3,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:t("pointsBalance"), value:points.toLocaleString(), color:tierColor },
          { label:t("cashValue"), value:"KES " + Math.floor(points/redemptionRate).toLocaleString() },
          { label:t("redemptionRate"), value:redemptionRate + " pts = KES 1" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#ffffff", borderRadius:10, padding:"1rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontSize:11, color:"#777777", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:6 }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:s.color||"#000000" }}>{s.value}</div>
          </div>
        ))}
      </div>

      <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem", marginBottom:"1.5rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:12, color:"#000000" }}>Tier benefits</div>
        <div style={{ display:"grid", gridTemplateColumns:"repeat(2,1fr)", gap:8 }}>
          {TIERS.map(t=>(
            <div key={t.name} style={{ background: tier===t.name?t.color+"15":"#f5f5f5", border:`1px solid ${tier===t.name?t.color:"#eeeeee"}`, borderRadius:10, padding:"0.9rem", textAlign:"center" }}>
              <div style={{ fontSize:13, fontWeight:700, color:t.color, marginBottom:4 }}>{t.name}</div>
              <div style={{ fontSize:10, color:"#555555", marginBottom:6 }}>
                {t.max ? `${t.min.toLocaleString()} ΓÇô ${t.max.toLocaleString()} pts` : `${t.min.toLocaleString()}+ pts`}
              </div>
              <div style={{ fontFamily:"Syne", fontSize:12, fontWeight:700, color: tier===t.name?t.color:"#555555" }}>{t.rate} pts = KES 1</div>
              {tier===t.name&&<div style={{ fontSize:9, color:t.color, marginTop:4 }}>Your tier</div>}
            </div>
          ))}
        </div>
      </div>

      {points >= redemptionRate && (
        <div style={{ background:"#ffffff", border:`1px solid ${tierColor}30`, borderRadius:12, padding:"1.25rem", marginBottom:"1.5rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:4, color:"#000000" }}>Redeem points</div>
          <div style={{ fontSize:12, color:"#777777", marginBottom:"1rem" }}>
            You can redeem up to {points.toLocaleString()} points for KES {maxRedeemValue} off your next booking
          </div>
          <form onSubmit={redeemPoints}>
            <div style={{ display:"flex", gap:10, alignItems:"flex-end" }}>
              <div style={{ flex:1 }}>
                <div style={{ fontSize:11, color:"#666", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:6 }}>Points to redeem</div>
                <input
                  type="number"
                  min={redemptionRate}
                  max={points}
                  step={redemptionRate}
                  value={redeemAmount}
                  onChange={e=>setRedeemAmount(e.target.value)}
                  placeholder={`Min ${redemptionRate} points`}
                  style={{ width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"10px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif" }}
                />
              </div>
              <div style={{ textAlign:"right", flexShrink:0 }}>
                <div style={{ fontSize:11, color:"#555555", marginBottom:6 }}>Value</div>
                <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:tierColor }}>
                  KES {redeemAmount ? Math.floor(parseInt(redeemAmount||0)/redemptionRate).toLocaleString() : "0"}
                </div>
              </div>
            </div>
            <button type="submit" disabled={redeeming||!redeemAmount||parseInt(redeemAmount)<redemptionRate}
              style={{ width:"100%", marginTop:12, background: redeemAmount&&parseInt(redeemAmount)>=redemptionRate?"#e6821e":"#555555", border:"none", borderRadius:9, color: redeemAmount&&parseInt(redeemAmount)>=redemptionRate?"#fff":"#666", fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700, padding:"12px", cursor: redeemAmount&&parseInt(redeemAmount)>=redemptionRate?"pointer":"not-allowed" }}>
              {redeeming ? "Redeeming..." : `Redeem ${redeemAmount||0} points for KES ${Math.floor(parseInt(redeemAmount||0)/redemptionRate).toLocaleString()}`}
            </button>
          </form>
        </div>
      )}

      {points < redemptionRate && points > 0 && (
        <div style={{ background:"#fff8f0", border:"1px solid #e6821e20", borderRadius:10, padding:"1rem", marginBottom:"1.5rem", fontSize:13, color:"#555555" }}>
          You need {redemptionRate - points} more points to start redeeming. Keep booking to earn more!
        </div>
      )}

      <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:10, color:"#000000" }}>Points earned from bookings</div>
      {bookings.length===0&&<div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"1.5rem" }}>No completed bookings yet</div>}
      {bookings.map((b,i)=>(
        <div key={i} style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:10, padding:"0.9rem", marginBottom:8, display:"flex", alignItems:"center", gap:12 }}>
          <div style={{ width:36, height:36, background:"#f0fdf4", borderRadius:8, display:"flex", alignItems:"center", justifyContent:"center" }}><SuccessIcon size={20} color="#1d9e75"/></div>
          
          <div style={{ flex:1 }}>
            <div style={{ fontSize:13, fontWeight:500, color:"#000000" }}>{b.service_name}</div>
            <div style={{ fontSize:11, color:"#777777", marginTop:2 }}>{b.booking_date}</div>
          </div>
          <div style={{ textAlign:"right" }}>
            <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#1d9e75" }}>+{Math.floor(Number(b.total_amount)*10).toLocaleString()} pts</div>
            <div style={{ fontSize:10, color:"#777777" }}>KES {Number(b.total_amount).toFixed(2)} spent</div>
          </div>
        </div>
      ))}
    </div>
  )
}

import { NotificationsIcon, SuccessIcon, WarningIcon, ErrorIcon, ChatIcon } from "../../lib/cccIcons";
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useNavigate } from "react-router-dom"
import { useAuth } from "../../contexts/AuthContext"
import { useLanguage } from "../../contexts/LanguageContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

export default function CustomerNotifications() {
  const { user } = useAuth()
  const navigate = useNavigate()
  const { t } = useLanguage()
  const isMobile = useIsMobile()
  const [notifications, setNotifications] = useState([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("customer-notifs")
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"notifications", filter:`user_id=eq.${user.id}` }, payload => {
        setNotifications(prev=>[payload.new,...prev])
        toast(payload.new.title, { icon: payload.new.type==="success"?"Γ£à":payload.new.type==="error"?"Γ¥î":payload.new.type==="warning"?"ΓÜá∩╕Å":"≡ƒöö", duration:5000 })
      })
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function load() {
    const { data } = await supabase.from("notifications")
      .select("*").eq("user_id", user.id).order("created_at", { ascending:false })
    setNotifications(data||[])
    setLoading(false)
  }

  async function markRead(id) {
    await supabase.from("notifications").update({ is_read:true }).eq("id", id).eq("user_id", user.id)
    setNotifications(n => n.map(x => x.id===id ? {...x, is_read:true} : x))
  }

  async function deleteNotification(id) {
    await supabase.from("notifications").delete().eq("id", id).eq("user_id", user.id)
    setNotifications(n => n.filter(x => x.id!==id))
    toast.success("Notification deleted")
  }
  async function clearAll() {
    if (!confirm("Clear all notifications?")) return
    await supabase.from("notifications").delete().eq("user_id", user.id)
    setNotifications([])
    toast.success("All notifications cleared")
  }
  async function markAllRead() {
    await supabase.from("notifications").update({ is_read:true }).eq("user_id", user.id).eq("is_read", false)
    setNotifications(n => n.map(x => ({...x, is_read:true})))
    toast.success("All marked as read")
  }

  async function deleteNotif(id) {
    await supabase.from("notifications").delete().eq("id", id).eq("user_id", user.id)
    setNotifications(n => n.filter(x => x.id!==id))
  }

  const unread = notifications.filter(n=>!n.is_read).length
  const typeIcon = { info:<NotificationsIcon size={18} color="#378add"/>, success:<SuccessIcon size={18} color="#1d9e75"/>, warning:<WarningIcon size={18} color="#e6821e"/>, error:<ErrorIcon size={18} color="#e24b4a"/> }
  const typeColor = { info:"#378add", success:"#1d9e75", warning:"#e6821e", error:"#e24b4a" }
  const typeBg = { info:"#eff6ff", success:"#f0fdf4", warning:"#fff8f0", error:"#fff5f5" }

  return (
    <div>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1.25rem" }}>
        <div>
          <div style={{ fontFamily:"Syne", fontSize:isMobile?16:18, fontWeight:800, color:"#000000" }}>{t("notifications")}</div>
          {unread>0&&<div style={{ fontSize:12, color:"#e6821e", marginTop:2 }}>{unread} unread</div>}
        </div>
        <div style={{ display:"flex", gap:6 }}>
          {unread>0&&<button onClick={markAllRead} style={{ background:"none", border:"1px solid #dddddd", borderRadius:7, color:"#555555", fontSize:12, padding:"6px 12px", cursor:"pointer" }}>Mark all read</button>}
          {notifications.length>0&&<button onClick={clearAll} style={{ background:"none", border:"1px solid #e24b4a30", borderRadius:7, color:"#e24b4a", fontSize:12, padding:"6px 12px", cursor:"pointer" }}>Clear all</button>}
        </div>
      </div>
      {loading&&<div style={{ color:"#777777", fontSize:13 }}>Loading...</div>}
      {!loading&&notifications.length===0&&(
        <div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"3rem" }}>
          <div style={{ marginBottom:10, display:"flex", justifyContent:"center" }}><NotificationsIcon size={32} color="#e6821e" /></div>
          No notifications yet
        </div>
      )}
      {notifications.map(n=>(
        <div key={n.id} onClick={()=>{ 
    if(!n.is_read) markRead(n.id)
    if(n.type==="message"||n.title?.toLowerCase().includes("message")||n.title?.includes("≡ƒÆ¼")) {
      try {
        const meta = n.metadata ? JSON.parse(n.metadata) : {}
        if(meta.booking_id) navigate(`/dashboard/chat?booking=${meta.booking_id}`)
        else if(meta.listing_id) navigate(`/dashboard/chat?listing=${meta.listing_id}`)
        else navigate("/dashboard/chat")
      } catch(_) { navigate("/dashboard/chat") }
    }
  }}
          style={{ background:n.is_read?"#f8f8f8":"#ffffff", border:`1px solid ${n.is_read?"#eeeeee":typeColor[n.type]||"#e6821e"}50`, borderRadius:10, padding:"1rem", marginBottom:8, cursor:n.is_read?"default":"pointer", display:"flex", alignItems:"flex-start", gap:12 }}>
          <div style={{ width:38, height:38, borderRadius:9, background:typeBg[n.type]||"#fff8f0", display:"flex", alignItems:"center", justifyContent:"center", fontSize:18, flexShrink:0 }}>
            {n.type==="success"?<SuccessIcon size={18} color="#1d9e75"/>:n.type==="error"?<ErrorIcon size={18} color="#e24b4a"/>:n.type==="warning"?<WarningIcon size={18} color="#e6821e"/>:n.type==="message"?<ChatIcon size={18} color="#8b5cf6"/>:<NotificationsIcon size={18} color="#378add"/>}
          </div>
          <div style={{ flex:1, minWidth:0 }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", gap:8 }}>
              <div style={{ fontSize:13, fontWeight:n.is_read?400:600, color:n.is_read?"#888888":"#000000" }}>{n.title}</div>
              {!n.is_read&&<div style={{ width:8, height:8, borderRadius:"50%", background:"#e6821e", flexShrink:0, marginTop:4 }}/>}
            </div>
            <div style={{ fontSize:12, color:"#666", marginTop:3, lineHeight:1.5 }}>{n.message}</div>
            <div style={{ fontSize:10, color:"#888888", marginTop:5 }}>{new Date(n.created_at).toLocaleString()}</div>
          </div>
          <button onClick={e=>{ e.stopPropagation(); deleteNotif(n.id) }} style={{ background:"none", border:"none", color:"#555555", cursor:"pointer", fontSize:16, lineHeight:1, flexShrink:0 }}>├ù</button>
        </div>
      ))}
    </div>
  )
}

import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useSearchParams } from "react-router-dom"
import { getCurrentPosition } from "../../lib/geolocation"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"
import ChatWindow from "../shared/ChatWindow"
import { downloadOrderReceipt, downloadOrdersCSV } from "../../lib/invoice"
import PhotoLightbox from "../shared/PhotoLightbox"

const CATEGORIES = [
  { key:"all", label:"All", icon:"≡ƒöì" },
  { key:"parts", label:"Parts", icon:"ΓÜÖ∩╕Å" },
  { key:"accessories", label:"Accessories", icon:"Γ£¿" },
  { key:"tyres", label:"Tyres", icon:"≡ƒ¢₧" },
  { key:"oils", label:"Oils & Fluids", icon:"≡ƒ¢ó∩╕Å" },
  { key:"electrical", label:"Electrical", icon:"ΓÜí" },
  { key:"body", label:"Body Parts", icon:"≡ƒÜù" },
  { key:"tools", label:"Tools", icon:"≡ƒöº" },
  { key:"other", label:"Other", icon:"≡ƒôª" },
]

const SC = { pending:"#e6821e", confirmed:"#378add", processing:"#8b5cf6", ready:"#1d9e75", delivered:"#1d9e75", cancelled:"#e24b4a" }

export default function CustomerPartsMarketplace() {
  const { user, profile } = useAuth()
  const isMobile = useIsMobile()
  const [searchParams] = useSearchParams()
  const [items, setItems] = useState([])
  const [providers, setProviders] = useState({})
  const [zones, setZones] = useState([])
  const [loading, setLoading] = useState(true)
  const [category, setCategory] = useState("all")
  const [search, setSearch] = useState("")
  const [cart, setCart] = useState([])
  const [showCart, setShowCart] = useState(false)
  const [selectedItem, setSelectedItem] = useState(null)
  const [fulfillment, setFulfillment] = useState("pickup")
  const [selectedZone, setSelectedZone] = useState("")
  const [deliveryAddress, setDeliveryAddress] = useState("")
  const [deliveryLat, setDeliveryLat] = useState(null)
  const [deliveryLng, setDeliveryLng] = useState(null)
  const [detectingLocation, setDetectingLocation] = useState(false)
  const [ordering, setOrdering] = useState(false)
  const [feeMultipliers, setFeeMultipliers] = useState({ motorcycle:1, tuktuk:1.5, van:3, car:1.5 })
  const [platformFeeRateDisplay, setPlatformFeeRateDisplay] = useState({ rate:0.02, cap:200 })
  const [orders, setOrders] = useState([])
  const [tab, setTab] = useState("browse")
  const [chatItem, setChatItem] = useState(null)
  const [pendingOrder, setPendingOrder] = useState(null)
  const [showOrderPayment, setShowOrderPayment] = useState(false)
  const [paying, setPaying] = useState(false)
  const [reviewOrder, setReviewOrder] = useState(null)
  const [reviewRating, setReviewRating] = useState(5)
  const [reviewText, setReviewText] = useState("")
  const [submittingReview, setSubmittingReview] = useState(false)
  const [myReviews, setMyReviews] = useState({})
  const [checkoutStep, setCheckoutStep] = useState("cart") // cart, details, payment
  const [customerDetails, setCustomerDetails] = useState({ name:"", phone:"", email:"" })
  const [paymentMethod, setPaymentMethod] = useState("mpesa")
  const [lightbox, setLightbox] = useState({ open:false, photos:[], index:0 })
  const [favourites, setFavourites] = useState(new Set())

  useEffect(() => {
    if (!user) return
    load()
    loadOrders()
    loadFavourites()
    loadMyReviews()
    // Real-time inventory updates
    const sub = supabase.channel("marketplace-inventory")
      .on("postgres_changes", { event:"*", schema:"public", table:"inventory" }, () => load())
      .on("postgres_changes", { event:"*", schema:"public", table:"orders", filter:`customer_id=eq.${user.id}` }, () => loadOrders())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  useEffect(() => {
    const itemId = searchParams.get("item")
    if (!itemId || items.length === 0) return
    // "Add to Cart" from the unified Marketplace browse screen navigates here with this flag,
    // since that screen has no cart state of its own to add into directly - this skips the
    // second, redundant manual "Add to Cart" tap the customer would otherwise need on arrival.
    const shouldAutoAdd = searchParams.get("autoadd") === "1"
    const found = items.find(i => i.id === itemId)
    if (found) {
      setSelectedItem(found)
      if (shouldAutoAdd) addToCart(found)
    } else {
      supabase.from("inventory").select("*").eq("id", itemId).single()
        .then(({ data }) => {
          if (data) {
            setSelectedItem(data)
            if (shouldAutoAdd) addToCart(data)
          }
        })
    }
  }, [searchParams, items])

  async function loadFavourites() {
    const { data } = await supabase.from("marketplace_likes").select("listing_id").eq("user_id", user.id)
    setFavourites(new Set((data||[]).map(d=>d.listing_id)))
  }

  async function toggleFavourite(itemId) {
    if(!user) return toast.error("Sign in to save items")
    if(favourites.has(itemId)) {
      await supabase.from("marketplace_likes").delete().eq("user_id",user.id).eq("listing_id",itemId)
      setFavourites(prev => { const n=new Set(prev); n.delete(itemId); return n })
    } else {
      await supabase.from("marketplace_likes").insert({ user_id:user.id, listing_id:itemId })
      setFavourites(prev => new Set([...prev, itemId]))
    }
  }

  async function load() {
    // Delivery fee varies by predicted vehicle type - a large order needing a van genuinely
    // costs more to fulfill than a small one a bike can handle, matching real platforms like
    // Lalamove where vans charge roughly 3-4x a motorcycle's base fare for the same route.
    const { data: multRows } = await supabase.from("app_settings").select("key,value").in("key", [
      "marketplace_delivery_fee_multiplier_motorcycle",
      "marketplace_delivery_fee_multiplier_tuktuk",
      "marketplace_delivery_fee_multiplier_van",
      "marketplace_delivery_fee_multiplier_car",
    ])
    if (multRows?.length) {
      const m = {}
      multRows.forEach(r => { m[r.key.replace("marketplace_delivery_fee_multiplier_","")] = Number(r.value) })
      setFeeMultipliers(prev => ({ ...prev, ...m }))
    }
    // Fetch the real platform fee rate for display so it always matches what placeOrder()
    // actually charges - previously hardcoded to 0.02/200 separately from the real rate.
    const { data: rateRow } = await supabase.from("commission_rates").select("platform_fee_rate,platform_fee_cap").eq("provider_type","parts_dealer").maybeSingle()
    if (rateRow) setPlatformFeeRateDisplay({ rate: Number(rateRow.platform_fee_rate), cap: Number(rateRow.platform_fee_cap) })
    const { data: inv } = await supabase.from("inventory")
      .select("*, profiles!inventory_provider_id_fkey(id,business_name,first_name,last_name,city,provider_type,is_verified)")
      .eq("is_active", true)
      .gt("stock_quantity", 0)
      .order("created_at", { ascending:false })
    const { data: zns } = await supabase.from("delivery_zones").select("*").eq("is_active", true)
    setItems(inv||[])
    setZones(zns||[])
    setLoading(false)
  }

  async function loadMyReviews() {
    const { data } = await supabase.from("reviews").select("order_id,provider_rating").eq("customer_id", user.id).not("order_id","is",null)
    const map = {}
    ;(data||[]).forEach(r => { map[r.order_id] = r.provider_rating })
    setMyReviews(map)
  }

  async function submitOrderReview() {
    if (!reviewOrder) return
    setSubmittingReview(true)
    try {
      await supabase.from("reviews").insert({
        order_id: reviewOrder.id,
        customer_id: user.id,
        provider_id: reviewOrder.provider_id,
        provider_rating: reviewRating,
        provider_review: reviewText||null
      })
      await supabase.from("notifications").insert({
        user_id: reviewOrder.provider_id,
        title: "New review received! Γ¡É",
        message: reviewRating+" star review for order #"+reviewOrder.order_number+(reviewText?": \""+reviewText+"\"":""),
        type: "info"
      })
      // Send push notification to provider
      try {
        await fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/send-push`, {
          method:"POST",
          headers:{"Content-Type":"application/json","Authorization":`Bearer ${import.meta.env.VITE_SUPABASE_ANON_KEY}`},
          body:JSON.stringify({ user_id:reviewOrder.provider_id, title:"New Order Review! Γ¡É", message:`${reviewRating} star review for order #${reviewOrder.order_number}` })
        })
      } catch(e) { console.log("Push failed:",e.message) }
      toast.success("Thank you for your review!")
      setReviewOrder(null)
      setReviewRating(5)
      setReviewText("")
      loadMyReviews()
    } catch(e) { toast.error(e.message) }
    finally { setSubmittingReview(false) }
  }

  async function loadOrders() {
    const { data } = await supabase.from("orders")
      .select("*, order_items(*, inventory(name,unit)), profiles!orders_provider_id_fkey(business_name,first_name,last_name)")
      .eq("customer_id", user.id)
      .order("created_at", { ascending:false })
    setOrders(data||[])
  }

  function addToCart(item) {
    setCart(prev => {
      const existing = prev.find(c=>c.id===item.id)
      if (existing) return prev.map(c=>c.id===item.id?{...c,qty:c.qty+1}:c)
      return [...prev, {...item, qty:1}]
    })
    toast.success(item.name+" added to cart")
  }

  function removeFromCart(id) { setCart(prev=>prev.filter(c=>c.id!==id)) }
  function updateQty(id, qty) {
    if (qty<=0) return removeFromCart(id)
    setCart(prev=>prev.map(c=>c.id===id?{...c,qty}:c))
  }
  const cartTotal = cart.reduce((s,c)=>s+Number(c.price)*c.qty, 0)
  const platformFeeDisplay = Math.min(Math.round(cartTotal * platformFeeRateDisplay.rate), platformFeeRateDisplay.cap)
  const predictedVehicleType = (() => { const n = cart.reduce((s,i)=>s+i.qty,0); return n<=3?"motorcycle":n<=6?"tuktuk":"van" })()
  const deliveryFee = selectedZone && zones.length > 0 ? Math.round(Number(zones.find(z=>z.id===selectedZone)?.base_fee||0) * (feeMultipliers[predictedVehicleType]||1)) : 0
  const orderTotal = cartTotal + (fulfillment==="delivery"?deliveryFee:0) + platformFeeDisplay
  // Group cart by provider
  const cartByProvider = cart.reduce((acc,item)=>{
    const pid = item.provider_id
    if (!acc[pid]) acc[pid] = []
    acc[pid].push(item)
    return acc
  }, {})

  

  async function placeOrder() {
    if (cart.length === 0) return toast.error("Cart is empty")
    if (checkoutStep === "cart") { setCheckoutStep("details"); return }
    if (checkoutStep === "details") {
      if (!customerDetails.name) return toast.error("Please enter your name")
      if (!customerDetails.phone) return toast.error("Please enter your phone")
      if (fulfillment === "delivery" && !selectedZone) return toast.error("Please select a delivery zone")
      if (fulfillment === "delivery" && !deliveryAddress) return toast.error("Please enter delivery address")
      setCheckoutStep("payment"); return
    }
    setOrdering(true)
    try {
      const zone = zones.find(z => z.id === selectedZone)
      const cartItemCount = cart.reduce((s,i)=>s+i.qty,0)
      const predictedVehicleType = cartItemCount<=3?"motorcycle":cartItemCount<=6?"tuktuk":"van"
      const deliveryFee = fulfillment === "delivery" && zone ? Math.round(Number(zone.base_fee) * (feeMultipliers[predictedVehicleType]||1)) : 0
      const { data: rateRow } = await supabase.from("commission_rates").select("platform_rate,platform_fee_rate,platform_fee_cap").eq("provider_type","parts_dealer").maybeSingle()
      const commissionRate = rateRow ? Number(rateRow.platform_rate) : 0.05
      const platformFeeRate = rateRow ? Number(rateRow.platform_fee_rate) : 0.02

      const byProvider = {}
      cart.forEach(item => {
        if (!byProvider[item.provider_id]) byProvider[item.provider_id] = []
        byProvider[item.provider_id].push(item)
      })

      let firstOrderId = null
      let firstOrderTotal = 0

      for (const [providerId, items] of Object.entries(byProvider)) {
        const subtotal = items.reduce((s, i) => s + Number(i.price) * i.qty, 0)
        const commission = subtotal * commissionRate
        const platformFee = Math.min(Math.round(subtotal * platformFeeRate), platformFeeCap)
        const providerEarnings = subtotal - commission
        const orderDeliveryFee = Object.keys(byProvider).length === 1 ? deliveryFee : 0

        const { data: order, error } = await supabase.from("orders").insert({
          customer_id: user.id,
          provider_id: providerId,
          subtotal,
          delivery_fee: orderDeliveryFee,
          platform_commission: commission,
          // No platform_fee column exists on orders.
          provider_earnings: providerEarnings,
          fulfillment_type: fulfillment,
          delivery_zone: zone?.name || null,
          delivery_address: deliveryAddress || null,
        delivery_latitude: deliveryLat || null,
        delivery_longitude: deliveryLng || null,
          customer_name: customerDetails.name,
          customer_phone: customerDetails.phone,
          payment_method: paymentMethod,
          payment_status: "awaiting_payment",
          status: "pending_payment",
        }).select("id").single()
        if (error) throw error

        for (const item of items) {
          await supabase.from("order_items").insert({
            order_id: order.id,
            inventory_id: item.id,
            name: item.name,
            quantity: item.qty,
            unit_price: Number(item.price),
          })
          // Decrement stock immediately to prevent overselling
          await supabase.from("inventory").update({ stock_quantity: item.stock_quantity - item.qty }).eq("id", item.id)
        }

        await supabase.from("notifications").insert({
          user_id: providerId,
          title: "New order received! ≡ƒôª",
          message: `${customerDetails.name} ordered ${items.length} item(s) ΓÇö KES ${subtotal.toLocaleString()} (Paid online via M-Pesa)`,
          type: "success",
        })



        if (!firstOrderId) {
          firstOrderId = order.id
        firstOrderTotal = subtotal + orderDeliveryFee + platformFee
        }
      }

      setCart([])
      setShowCart(false)
      setCheckoutStep("cart")
      setCustomerDetails({ name: "", phone: "", email: "" })
      setDeliveryAddress("")
      setDeliveryLat(null)
      setDeliveryLng(null)
      setSelectedZone("")

      setPendingOrder({ id: firstOrderId, amount: firstOrderTotal })
      setShowOrderPayment(true)
    } catch(err) { toast.error(err.message) }
    finally { setOrdering(false) }
  }


  const filtered = items.filter(item => {
    if (!item.is_active) return false
    if (category !== "all" && item.category !== category) return false
    if (search) {
      const q = search.toLowerCase()
      const matchName = item.name?.toLowerCase().includes(q)
      const matchBrand = item.brand?.toLowerCase().includes(q)
      const matchDesc = item.description?.toLowerCase().includes(q)
      if (!matchName && !matchBrand && !matchDesc) return false
    }
    return true
  })

  return (
    <div>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1.25rem", flexWrap:"wrap", gap:10 }}>
        <div>
          <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:"#000000" }}>Parts & Accessories</div>
          <div style={{ fontSize:12, color:"#777777" }}>Order from verified CCC shops</div>
        </div>
        <button onClick={()=>setShowCart(true)} style={{ background:cart.length>0?"#e6821e":"#f5f5f5", border:"1px solid #e0e0e0", borderRadius:9, color:cart.length>0?"#fff":"#666", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"9px 16px", cursor:"pointer", position:"relative" }}>
          ≡ƒ¢Æ Cart {cart.length>0&&`(${cart.length})`}
          {cart.length>0&&<span style={{ position:"absolute", top:-6, right:-6, width:16, height:16, borderRadius:"50%", background:"#e24b4a", fontSize:9, color:"#fff", display:"flex", alignItems:"center", justifyContent:"center", fontWeight:800 }}>{cart.reduce((s,c)=>s+c.qty,0)}</span>}
        </button>
      </div>

      <div style={{ display:"flex", gap:6, marginBottom:"1rem" }}>
        {[{k:"browse",l:"Browse"},{k:"orders",l:"My Orders"}].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{ padding:"7px 16px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#e6821e":"#f0f0f0", color:tab===t.k?"#fff":"#555", fontWeight:tab===t.k?700:400 }}>
            {t.l} {t.k==="orders"&&orders.length>0&&`(${orders.length})`}
          </button>
        ))}
      {tab==="orders"&&orders.length>0&&(
        <button onClick={()=>downloadOrdersCSV(orders)}
          style={{ marginBottom:8, background:"#f8f8f8", border:"1px solid #ddd", borderRadius:8, color:"#555", fontSize:11, padding:"6px 14px", cursor:"pointer", display:"block", marginLeft:"auto" }}>
          ≡ƒôÑ Export CSV
        </button>
      )}
      </div>

      {tab==="browse"&&(
        <>
          <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search parts, accessories, brand, car model..."
            style={{ width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"9px 12px", color:"#000000", fontSize:12, outline:"none", marginBottom:"1rem" }}/>
          <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap" }}>
            {CATEGORIES.map(c=>(
              <button key={c.key} onClick={()=>setCategory(c.key)}
                style={{ padding:"5px 10px", borderRadius:7, border:"none", fontSize:11, cursor:"pointer", background:category===c.key?"#e6821e":"#f0f0f0", color:category===c.key?"#fff":"#555" }}>
                {c.icon} {c.label}
              </button>
            ))}
          </div>

          {!loading&&filtered.length>0&&<div style={{ fontSize:11, color:"#888", marginBottom:"0.75rem" }}>{filtered.length} item{filtered.length!==1?"s":""} found</div>}
          {loading&&<div style={{ color:"#777777", fontSize:13 }}>Loading...</div>}
          {!loading&&filtered.length===0&&(
            <div style={{ textAlign:"center", padding:"3rem", color:"#888" }}>
              <div style={{ fontSize:40, marginBottom:10 }}>≡ƒöì</div>
              <div style={{ fontSize:14, fontWeight:600, color:"#555", marginBottom:6 }}>No items found</div>
              <div style={{ fontSize:12 }}>Try a different search or category</div>
            </div>
          )}

          {/* Category rows when browsing all, grid when filtered */}
          {category === "all" ? (
            <div>
              {CATEGORIES.filter(cat => cat.key !== "all" && filtered.some(i => i.category === cat.key)).map(cat => (
                <div key={cat.key} style={{ marginBottom:"1.5rem" }}>
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:10 }}>
                    <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#000" }}>{cat.icon} {cat.label}</div>
                    <button onClick={()=>setCategory(cat.key)} style={{ fontSize:11, color:"#e6821e", background:"none", border:"none", cursor:"pointer", fontWeight:600 }}>See all ΓåÆ</button>
                  </div>
                  <div style={{ display:"flex", gap:10, overflowX:"auto", paddingBottom:8, scrollbarWidth:"none", WebkitOverflowScrolling:"touch" }}>
                    {filtered.filter(i => i.category === cat.key).map(item=>(
                      <div key={item.id} style={{ flexShrink:0, width:160, background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, overflow:"hidden", boxShadow:"0 1px 4px rgba(0,0,0,0.05)" }}>
                        {item.photos?.[0] ? (
                          <img src={item.photos[0]} alt={item.name} style={{ width:"100%", height:110, objectFit:"cover", cursor:"zoom-in" }} onClick={()=>setLightbox({ open:true, photos:item.photos, index:0 })}/>
                        ):(
                          <div style={{ width:"100%", height:110, background:"linear-gradient(135deg,#f8f8f8,#f0f0f0)", display:"flex", alignItems:"center", justifyContent:"center", fontSize:32 }}>{cat.icon}</div>
                        )}
                        <div style={{ padding:"0.65rem" }}>
                          <div style={{ fontSize:12, fontWeight:600, color:"#000", marginBottom:2, lineHeight:1.3 }}>{item.name.length>28?item.name.substring(0,28)+"...":item.name}</div>
                          {item.brand&&<div style={{ fontSize:10, color:"#888", marginBottom:3 }}>{item.brand}</div>}
                          <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:800, color:"#e6821e", marginBottom:6 }}>KES {Number(item.price).toLocaleString()}</div>
                          <div style={{ display:"flex", gap:5 }}>
