  useEffect(() => { if (user) load() }, [user])

  async function load() {
    const [{ data: bks }, { data: rfs }, { data: txns }] = await Promise.all([
      supabase.from("bookings").select("*, provider:profiles!bookings_provider_id_fkey(first_name,last_name,business_name,city,address)").eq("customer_id", user.id).order("created_at", { ascending:false }),
      supabase.from("refunds").select("*").eq("customer_id", user.id).order("created_at", { ascending:false }),
      supabase.from("payment_transactions").select("*, bookings(service_name,booking_number,status)").eq("customer_id", user.id).order("created_at", { ascending:false })
    ])
    setBookings(bks||[]); setRefunds(rfs||[]); setTransactions(txns||[]); setLoading(false)
  }

  async function submitRefund(e) {
    e.preventDefault()
    if (!refundForm.bookingId) return toast.error("Select a booking")
    setSubmitting(true)
    const booking = bookings.find(b=>b.id===refundForm.bookingId)
    const { error } = await supabase.from("refunds").insert({
      booking_id: refundForm.bookingId,
      customer_id: user.id,
      amount: Number(booking.total_amount),
      reason: refundForm.reason,
      status: "pending"
    })
    if (error) { toast.error(error.message); setSubmitting(false); return }
    toast.success("Refund request submitted")
    setRefundForm({ bookingId:"", reason:"" }); setSubmitting(false); load()
  }

  const paid = bookings.filter(b=>b.payment_status==="paid")
  const totalSpent = paid.reduce((s,b)=>s+Number(b.total_amount),0)
  const totalRefunded = refunds.filter(r=>r.status==="approved").reduce((s,r)=>s+Number(r.amount),0)
  const refundable = bookings.filter(b=>b.status==="completed")
  const SC = { pending:"#e6821e", confirmed:"#378add", "in-progress":"#8b5cf6", completed:"#1d9e75", cancelled:"#e24b4a" }
  const RC = { pending:"#e6821e", approved:"#1d9e75", rejected:"#e24b4a" }
  const inp = { width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"10px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif" }

  return (
    <div>
      <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"repeat(3,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Total spent", value:`KES ${totalSpent.toFixed(2)}` },
          { label:"Transactions", value:paid.length },
          { label:"Refunded", value:`KES ${totalRefunded.toLocaleString()}`, color:"#1d9e75" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#ffffff", borderRadius:10, padding:"1rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontSize:11, color:"#777777", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:6 }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:22, fontWeight:800, color:s.color||"#000000" }}>{s.value}</div>
          </div>
        ))}
      </div>

      <div style={{ overflowX:"auto", marginBottom:"1.25rem", paddingBottom:4, WebkitOverflowScrolling:"touch" }}>
        <div style={{ display:"flex", gap:6, minWidth:"max-content" }}>
          {[{k:"history",l:"History",icon:"payments"},{k:"transactions",l:"M-Pesa",icon:"qr"},{k:"refunds",l:"Refunds",icon:"refresh"},{k:"vouchers",l:"Vouchers",icon:"voucher"}].map(t=>(
            <button key={t.k} onClick={()=>setTab(t.k)} style={{ padding:"8px 14px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#e6821e":"#f0f0f0", color:tab===t.k?"#fff":"#555", whiteSpace:"nowrap", fontWeight:tab===t.k?700:400 }}>
              {t.l}
            </button>
          ))}
        </div>
      </div>
      {tab==="history"&&bookings.length>0&&(
        <button onClick={()=>downloadPaymentsCSV(bookings.map(b=>({...b,type:"Service",description:b.service_name,amount:b.total_amount})))}
          style={{ marginBottom:8, background:"#f8f8f8", border:"1px solid #ddd", borderRadius:8, color:"#555", fontSize:11, padding:"6px 14px", cursor:"pointer", display:"block", marginLeft:"auto" }}>
          <DownloadIcon size={14} color="#378add" /> Export CSV
        </button>
      )}
      {tab==="history"&&(
        <div>
          {!loading&&bookings.length===0&&<div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"2rem" }}>No payments yet</div>}
          {bookings.map(b=>(
            <div key={b.id} style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
                <div>
                  <div style={{ fontSize:14, fontWeight:500, color:"#000000" }}>{b.service_name}</div>
                  <div style={{ fontSize:10, color:"#888888", marginTop:2 }}>#{b.booking_number} ┬╖ {b.booking_date}</div>
                </div>
                <div style={{ textAlign:"right" }}>
                  <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#e6821e" }}>KES {Number(b.total_amount).toLocaleString()}</div>
                  <span style={{ fontSize:10, padding:"2px 8px", borderRadius:20, background:b.payment_status==="paid"?"#f0fdf4":"#fff8f0", color:b.payment_status==="paid"?"#1d9e75":"#e6821e" }}>
                    {b.payment_status}
                  </span>
                </div>
              </div>
              <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:8, marginBottom:10 }}>
                {[
                  { l:"Status", v:b.status },
                  { l:"Paid", v:`KES ${Number(b.total_amount||0).toLocaleString()}` },
                    { l:"Provider earned", v:"KES " + Number(b.provider_earnings||0).toLocaleString() },
                    { l:"Driver earned", v:Number(b.driver_earnings||0)>0?"KES "+Number(b.driver_earnings).toLocaleString():"N/A" },
                ].map(f=>(
                  <div key={f.l}>
                    <div style={{ fontSize:10, color:"#777777", textTransform:"uppercase" }}>{f.l}</div>
                    <div style={{ fontSize:12, color:f.l==="Status"?(SC[f.v]||"#888"):"#000000", marginTop:2 }}>{f.v}</div>
                  </div>
                ))}
              </div>
              <button onClick={()=>downloadInvoice(b, b.provider, profile)}
                style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:11, padding:"5px 12px", cursor:"pointer", fontFamily:"'DM Sans',sans-serif" }}>
                Download Invoice
              </button>
            </div>
          ))}
        </div>
      )}

      {tab==="transactions"&&(
        <div>
          {transactions.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No M-Pesa transactions yet</div>}
          {transactions.map(t=>(
            <div key={t.id} style={{ background:"#fff", border:"1px solid #eee", borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:600 }}>{t.bookings?.service_name||"GO Service Callout"}</div>
                  <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{t.bookings?.booking_number||"ΓÇö"} ┬╖ {new Date(t.created_at).toLocaleDateString()}</div>
                  <div style={{ fontSize:10, color:"#888" }}>M-Pesa Ref: {t.daraja_invoice_id||"ΓÇö"}</div>
                </div>
                <div style={{ textAlign:"right" }}>
                  <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#e6821e" }}>KES {Number(t.total_amount||t.amount).toLocaleString()}</div>
                  <span style={{ fontSize:10, padding:"2px 8px", borderRadius:20, background:t.status==="completed"?"#f0fdf4":t.status==="failed"?"#fff5f5":"#fff8f0", color:t.status==="completed"?"#1d9e75":t.status==="failed"?"#e24b4a":"#e6821e" }}>{t.status}</span>
                </div>
              </div>
              <div style={{ display:"flex", gap:12, marginTop:8 }}>
                <div><div style={{ fontSize:9, color:"#888", textTransform:"uppercase" }}>Service amount</div><div style={{ fontSize:12 }}>KES {Number(t.amount).toLocaleString()}</div></div>
                <div><div style={{ fontSize:9, color:"#888", textTransform:"uppercase" }}>Processing fee</div><div style={{ fontSize:12 }}>KES {Number(t.processing_fee||0).toLocaleString()}</div></div>
                <div><div style={{ fontSize:9, color:"#888", textTransform:"uppercase" }}>Total paid</div><div style={{ fontSize:12, fontWeight:700 }}>KES {Number(t.total_amount||t.amount).toLocaleString()}</div></div>
              </div>
            </div>
          ))}
        </div>
      )}
      {tab==="vouchers"&&(
        <div>
          {vouchers.length===0&&<div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"2rem" }}>No vouchers yet</div>}
          {vouchers.map(v=>(
            <div key={v.id} style={{ background:"#ffffff", border:`1px solid ${v.is_used?"#eeeeee":new Date(v.expires_at)<new Date()?"#fff5f5":"#1d9e7540"}`, borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
                <div>
                  <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, color:v.is_used?"#555":new Date(v.expires_at)<new Date()?"#e24b4a":"#1d9e75", letterSpacing:2 }}>{v.code}</div>
                  <div style={{ fontSize:11, color:"#777777", marginTop:2 }}>Value: KES {Number(v.value).toLocaleString()}</div>
                  <div style={{ fontSize:10, color:"#888888", marginTop:2 }}>Expires: {new Date(v.expires_at).toLocaleDateString()}</div>
                </div>
                <span style={{ fontSize:11, padding:"3px 10px", borderRadius:20, background:v.is_used?"#555555":new Date(v.expires_at)<new Date()?"#fff5f5":"#f0fdf4", color:v.is_used?"#555":new Date(v.expires_at)<new Date()?"#e24b4a":"#1d9e75", fontWeight:600 }}>
                  {v.is_used?"Used":new Date(v.expires_at)<new Date()?"Expired":"Active"}
                </span>
              </div>
              {!v.is_used&&new Date(v.expires_at)>new Date()&&(
                <div style={{ fontSize:11, color:"#555555", background:"#ffffff", borderRadius:6, padding:"6px 10px" }}>
                  Use this code when booking a service to get KES {Number(v.value).toLocaleString()} off
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {tab==="refunds"&&(
        <div>
          {refunds.length>0&&(
            <div style={{ marginBottom:"1.5rem" }}>
              <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, marginBottom:10 }}>Your refund requests</div>
              {refunds.map(r=>(
                <div key={r.id} style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:8 }}>
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                    <div>
                      <div style={{ fontSize:13, fontWeight:500 }}>KES {Number(r.amount).toLocaleString()} refund</div>
                      <div style={{ fontSize:11, color:"#777777", marginTop:2 }}>{r.reason}</div>
                      <div style={{ fontSize:10, color:"#888888", marginTop:2 }}>{new Date(r.created_at).toLocaleDateString()}</div>
                    </div>
                    <span style={{ fontSize:11, padding:"3px 9px", borderRadius:20, background:r.status==="approved"?"#f0fdf4":r.status==="rejected"?"#fff5f5":"#fff8f0", color:RC[r.status]||"#888" }}>
                      {r.status}
                    </span>
                  </div>
                  {r.admin_notes&&<div style={{ fontSize:11, color:"#666", marginTop:8, fontStyle:"italic" }}>Admin: &quot;{r.admin_notes}&quot;</div>}
                </div>
              ))}
            </div>
          )}
          <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:10, padding:"1.25rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, marginBottom:"1rem" }}>Request a refund</div>
            {refundable.length===0?(
              <div style={{ fontSize:13, color:"#777777" }}>No completed bookings eligible for refund</div>
            ):(
              <form onSubmit={submitRefund}>
                <div style={{ marginBottom:10 }}>
                  <label style={{ fontSize:11, color:"#666", textTransform:"uppercase", letterSpacing:"0.05em", display:"block", marginBottom:4 }}>Select booking</label>
                  <select value={refundForm.bookingId} onChange={e=>setRefundForm(f=>({...f,bookingId:e.target.value}))} style={inp} required>
                    <option value="">Choose a booking...</option>
                    {refundable.map(b=><option key={b.id} value={b.id}>{b.service_name} ΓÇö KES {Number(b.total_amount).toLocaleString()} ┬╖ {b.booking_date}</option>)}
                  </select>
                </div>
                <div style={{ marginBottom:12 }}>
                  <label style={{ fontSize:11, color:"#666", textTransform:"uppercase", letterSpacing:"0.05em", display:"block", marginBottom:4 }}>Reason</label>
                  <textarea value={refundForm.reason} onChange={e=>setRefundForm(f=>({...f,reason:e.target.value}))} rows={3} placeholder="Explain why you are requesting a refund..." style={{...inp,resize:"vertical"}} required/>
                </div>
                <button type="submit" disabled={submitting} style={{ background:submitting?"#555555":"#e6821e", border:"none", borderRadius:8, color:submitting?"#666":"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"10px 20px", cursor:submitting?"not-allowed":"pointer" }}>
                  {submitting?t("loading"):t("submit")}
                </button>
              </form>
            )}
          </div>
        </div>
      )}
    </div>
  )
}

import useIsMobile from "../../lib/useIsMobile"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { OrdersIcon, BookingsIcon, PaymentsIcon, VehicleIcon, StarIcon, ReferEarnIcon, ShieldIcon, AnalyticsIcon, DocumentIcon, RefreshIcon, DataIcon } from "../../lib/cccIcons"
import { pushNotify } from "../../lib/pushNotify"
import { validatePassword } from "../../lib/passwordValidation"
import { sanitizeName, sanitizePhone, sanitizeFreeText } from "../../lib/sanitize"
import { useAuth } from "../../contexts/AuthContext"
import { useLanguage } from "../../contexts/LanguageContext"
import { exportUserData, downloadJSON, downloadCSV, downloadPDF } from "../../lib/dataExport"
import toast from "react-hot-toast"
import { validateFile } from "../../lib/uploadValidation"

export default function CustomerProfile() {
  const isMobile = useIsMobile()
  const { profile, updateProfile, user } = useAuth()
  const { t } = useLanguage()
  const [form, setForm] = useState({ first_name:"", last_name:"", city:"" })
  const [sensitive, setSensitive] = useState({ phone:"", email:"" })
  const [saving, setSaving] = useState(false)
  const [tab, setTab] = useState("profile")
  const [exporting, setExporting] = useState(false)
  const [deletingAccount, setDeletingAccount] = useState(false)
  const [pendingDeletion, setPendingDeletion] = useState(null)
  const [exportData, setExportData] = useState(null)

  useEffect(() => {
    if (profile) setForm({ first_name:profile?.first_name||"", last_name:profile?.last_name||"", city:profile?.city||"" })
    if (user) loadSensitive()
  }, [profile, user])

  async function loadSensitive() {
    const { data } = await supabase.from("profile_sensitive").select("phone,email").eq("id", user.id).single()
    if (data) setSensitive({ phone:data.phone||"", email:data.email||"" })
  }

  async function saveProfile(e) {
    e.preventDefault()
    setSaving(true)
    try { await updateProfile(form); toast.success(t("saveChanges")) }
    catch(err) { toast.error(err.message) }
    finally { setSaving(false) }
  }

  async function saveContact(e) {
    e.preventDefault()
    setSaving(true)
    try {
      await supabase.from("profile_sensitive").update({ phone:sensitive.phone }).eq("id", user.id)
      toast.success(t("saveChanges"))
    } catch(err) { toast.error(err.message) }
    finally { setSaving(false) }
  }

  async function changePassword(e) {
    e.preventDefault()
    const pw = e.target.password.value
    const confirm = e.target.confirm.value
    if (pw !== confirm) return toast.error("Passwords do not match")
    const pwError = validatePassword(pw); if (pwError) return toast.error(pwError)
    const { error } = await supabase.auth.updateUser({ password: pw })
    if (error) return toast.error(error.message)
    toast.success("Password changed")
    e.target.reset()
  }

  async function loadExportData() {
    setExporting(true)
    try {
      const data = await exportUserData(user.id)
      setExportData(data)
    } catch(err) { toast.error(err.message) }
    finally { setExporting(false) }
  }

  async function handleDeleteAccount() {
    setDeletingAccount(true)
    try {
      const { data: check, error: checkError } = await supabase.rpc("check_account_deletable", { p_user_id: user.id })
      if (checkError || !check) { toast.error("Could not verify account status. Please try again."); setDeletingAccount(false); return }
      if (!check.can_delete) {
        let blockers = []
        if (check.active_bookings > 0) blockers.push(check.active_bookings + " active booking(s)")
        if (check.pending_payments > 0) blockers.push(check.pending_payments + " pending payment(s)")
        if (check.open_claims > 0) blockers.push(check.open_claims + " open claim(s)")
        if (check.active_orders > 0) blockers.push(check.active_orders + " active order(s)")
        if (check.pending_payouts > 0) blockers.push(check.pending_payouts + " pending payout(s)")
        toast.error("Cannot delete account: " + blockers.join(", "), { duration:6000 })
        setDeletingAccount(false); return
      }
      const { data: existing } = await supabase.from("deletion_requests")
        .select("*").eq("user_id", user.id).eq("status","pending").maybeSingle()
      if (existing) {
        const hoursLeft = Math.ceil((new Date(existing.scheduled_for) - new Date()) / 3600000)
        toast("Deletion already scheduled in " + hoursLeft + " hour(s). Log in to cancel.", { duration:6000 })
        setDeletingAccount(false); return
      }
      if (!window.confirm("Delete your account?\\n\\nYour account will be permanently deleted in 24 hours.\\nYou can cancel by logging in within 24 hours.")) {
        setDeletingAccount(false); return
      }
      await supabase.from("deletion_requests").insert({
        user_id: user.id,
        scheduled_for: new Date(Date.now() + 24*60*60*1000).toISOString(),
        status: "pending"
      })
      await supabase.from("notifications").insert({
        user_id: user.id, title: "Account deletion scheduled ΓÜá∩╕Å",
        message: "Your account will be deleted in 24 hours. Log in to your profile to cancel.", type: "error"
      })
      toast.success("Account deletion scheduled. You have 24 hours to cancel by logging in.", { duration:8000 })
      setPendingDeletion({ scheduled_for: new Date(Date.now() + 24*60*60*1000).toISOString() })
      // Notify admin
      const { data: admins } = await supabase.from("profiles").select("id").eq("role","admin")
      if(admins?.length > 0) {
        await supabase.from("notifications").insert(admins.map(a=>({
          user_id: a.id,
          type: "account_deletion",
          title: "Account deletion request",
          message: (profile?.first_name||"A user")+" ("+user.id.slice(0,8)+") requested deletion. Scheduled in 24 hours.",
          data: { user_id: user.id }
        })))
        admins.forEach(a => pushNotify.accountDeletionRequest(a.id, profile?.first_name||"A user", user.id))
      }
    } catch(err) { toast.error(err.message) }
    setDeletingAccount(false)
  }

  const initials = `${profile?.first_name?.[0]||""}${profile?.last_name?.[0]||""}`.toUpperCase()
  const inp = { width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"11px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif", marginBottom:12 }
  const lbl = { fontSize:11, color:"#666", textTransform:"uppercase", letterSpacing:"0.05em", display:"block", marginBottom:4 }
  async function requestDeleteAccount() {
    const { data: activeBookings } = await supabase.from("bookings")
      .select("id").eq("customer_id", user.id).in("status",["pending","confirmed","in-progress"])
    if(activeBookings?.length > 0) return toast.error("You have active bookings. Resolve them before deleting your account.")
    const { data: activeTxns } = await supabase.from("marketplace_transactions")
      .select("id").eq("buyer_id", user.id).eq("buyer_confirmed", false).in("payment_status",["paid","processing"])
    if(activeTxns?.length > 0) return toast.error("You have pending marketplace transactions. Complete them first.")
    if(!window.confirm("Delete your account? All data will be permanently removed within 24 hours. This cannot be undone.")) return
    setDeletingAccount(true)
    try {
      const { data: existing } = await supabase.from("deletion_requests").select("*").eq("user_id", user.id).eq("status","pending").maybeSingle()
      if(existing) { toast("Deletion already scheduled.", { duration:5000 }); setDeletingAccount(false); return }
      await supabase.from("deletion_requests").insert({ user_id:user.id, scheduled_for:new Date(Date.now()+24*60*60*1000).toISOString(), status:"pending", reason:"User requested deletion from app" })
      await supabase.from("notifications").insert({ user_id:user.id, type:"account_deletion", title:"Account deletion scheduled ΓÜá∩╕Å", message:"Your account will be deleted in 24 hours. Log in to cancel." })
      const { data: admins } = await supabase.from("profiles").select("id").eq("role","admin")
      if(admins?.length > 0) {
        await supabase.from("notifications").insert(admins.map(a=>({
          user_id:a.id, type:"account_deletion", title:"Account deletion request ΓÜá∩╕Å",
          message:(profile?.first_name||"A user")+" ("+user.id.slice(0,8)+") requested account deletion. Scheduled in 24 hours.",
          data:{ user_id:user.id }
        })))
      }
        admins.forEach(a => pushNotify.accountDeletionRequest(a.id, profile?.first_name||"A user", user.id))
      toast.success("Deletion scheduled. Your account will be removed in 24 hours.")
      setTimeout(() => supabase.auth.signOut(), 3000)
    } catch(e) { toast.error(e.message) }
    finally { setDeletingAccount(false) }
  }

  return (
    <div style={{ maxWidth:isMobile?"100%":520 }}>
      <div style={{ display:"flex", alignItems:"center", gap:16, marginBottom:"1.5rem" }}>
        <div style={{ width:60, height:60, borderRadius:14, background:"#fff8f0", border:"2px solid #e6821e40", display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontSize:22, fontWeight:800, color:"#e6821e" }}>
          {initials}
        </div>
        <div>
          <div style={{ fontFamily:"Syne", fontSize:17, fontWeight:800, color:"#000000" }}>{profile?.first_name} {profile?.last_name}</div>
          <div style={{ fontSize:12, color:"#777777", marginTop:2 }}>Customer ┬╖ {profile?.city||"Location not set"}</div>
        </div>
      </div>

      <div style={{ display:"flex", gap:6, marginBottom:"1.5rem", flexWrap:"wrap" }}>
        {[
          {k:"profile",l:t("profile")},
          {k:"contact",l:t("contactDetails")},
          {k:"security",l:t("security")},
          {k:"data",l:"My Data"},
          {k:"account",l:"Account"},
        ].map(tab2=>(
          <button key={tab2.k} onClick={()=>{ setTab(tab2.k); if(tab2.k==="data"&&!exportData) loadExportData() }}
            style={{ padding:"8px 14px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===tab2.k?"#e6821e":"#555555", color:tab===tab2.k?"#fff":"#666", fontFamily:"'DM Sans',sans-serif", fontWeight:tab===tab2.k?700:400 }}>
            {tab2.l}
          </button>
        ))}
      </div>

      {tab==="profile"&&(
        <form onSubmit={saveProfile}>
          <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:"1rem", color:"#000000" }}>{t("profile")}</div>
            <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"1fr 1fr", gap:10 }}>
              <div><label style={lbl}>Profile photo</label>
            <div style={{ marginBottom:12 }}>
              {profile?.profile_photo_url&&<img src={profile.profile_photo_url} alt="Profile" style={{ width:80, height:80, borderRadius:"50%", objectFit:"cover", marginBottom:8, border:"2px solid #e6821e" }}/>}
              <input type="file" accept="image/*" onChange={async(e)=>{
                const file = e.target.files[0]
                if (!file) return
                const ext = file.name.split(".").pop()
                const path = `${user.id}/profile-${Date.now()}.${ext}`
                const { error } = await supabase.storage.from("provider-photos").upload(path, file, { upsert:true })
                if (error) return toast.error(error.message)
                const { data } = supabase.storage.from("provider-photos").getPublicUrl(path)
                await updateProfile({ profile_photo_url: data.publicUrl })
                toast.success("Photo updated!")
              }} style={{ width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"8px", color:"#555555", fontSize:12, marginBottom:8 }}/>
            </div>
            <label style={lbl}>{t("firstName")}</label><input style={inp} value={form.first_name} onChange={e=>setForm(f=>({...f,first_name:e.target.value}))} required/></div>
              <div><label style={lbl}>{t("lastName")}</label><input style={inp} value={form.last_name} onChange={e=>setForm(f=>({...f,last_name:e.target.value}))} required/></div>
            </div>
            <label style={lbl}>{t("city")}</label>
            <input style={inp} placeholder="e.g. Nairobi" value={form.city} onChange={e=>setForm(f=>({...f,city:e.target.value}))}/>
            <button type="submit" disabled={saving}
              style={{ background:saving?"#555555":"#e6821e", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px 24px", cursor:saving?"not-allowed":"pointer" }}>
              {saving?t("saving"):t("saveChanges")}
            </button>
          </div>
        </form>
      )}

      {tab==="contact"&&(
        <form onSubmit={saveContact}>
          <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:"1rem", color:"#000000" }}>{t("contactDetails")}</div>
            <label style={lbl}>{t("email")}</label>
            <input style={{ ...inp, color:"#777777", cursor:"not-allowed" }} value={sensitive.email} readOnly/>
            <label style={lbl}>{t("phone")}</label>
            <input style={inp} placeholder="+254 700 000 000" value={sensitive.phone} onChange={e=>setSensitive(s=>({...s,phone:e.target.value}))}/>
            <button type="submit" disabled={saving}
              style={{ background:saving?"#555555":"#e6821e", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px 24px", cursor:saving?"not-allowed":"pointer" }}>
              {saving?t("saving"):t("saveChanges")}
            </button>
          </div>
        </form>
      )}

      {tab==="security"&&(
        <form onSubmit={changePassword}>
          <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:"1rem", color:"#000000" }}>{t("changePassword")}</div>
            <label style={lbl}>{t("newPassword")}</label>
            <input style={inp} type="password" name="password" placeholder="Min 8 characters, 1 number" required/>
            <label style={lbl}>{t("confirmPassword")}</label>
            <input style={inp} type="password" name="confirm" placeholder="Repeat password" required/>
            <button type="submit"
              style={{ background:"#e6821e", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px 24px", cursor:"pointer" }}>
              {t("changePassword")}
            </button>
          </div>
        </form>
      )}

        {tab==="data"&&(
          <div>
            {/* Header */}
            <div style={{ background:"linear-gradient(135deg,#fff8f0,#fff)", border:"1px solid #e6821e20", borderRadius:12, padding:"1rem", marginBottom:"1rem" }}>
              <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#000", marginBottom:4, display:"flex", alignItems:"center", gap:6 }}><DataIcon size={16} color="#e6821e"/> My Personal Data</div>
              <div style={{ fontSize:12, color:"#666", lineHeight:1.7 }}>Under Kenya Data Protection Act, you have the right to download or delete all your personal data stored on Car Care Connect.</div>
            </div>
            {exporting&&(
              <div style={{ textAlign:"center", padding:"2rem", color:"#888", fontSize:13 }}>
                <div style={{ fontSize:32, marginBottom:8 }}>ΓÅ│</div>
                Loading your data...
              </div>
            )}
            {!exporting&&!exportData&&(
              <div>
                <button onClick={loadExportData} style={{ width:"100%", background:"#e6821e", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700, padding:"14px", cursor:"pointer", marginBottom:"0.75rem" }}>
                  <><DataIcon size={14} color="currentColor"/> Load my data</>
                </button>
                <div style={{ fontSize:11, color:"#aaa", textAlign:"center" }}>We will compile all your data. This may take a few seconds.</div>
              </div>
            )}
            {exportData&&(
              <div>
                <div style={{ fontFamily:"Syne", fontSize:12, fontWeight:700, color:"#555", marginBottom:8, textTransform:"uppercase", letterSpacing:"0.05em" }}>Your data summary</div>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:8, marginBottom:"1.25rem" }}>
                  {[
                    { label:"Bookings", value:exportData.bookings?.length||0, icon:"bookings", color:"#378add" },
                    { label:"Payments", value:exportData.payments?.length||0, icon:"payments", color:"#1d9e75" },
                    { label:"Vehicles", value:exportData.vehicles?.length||0, icon:"vehicle", color:"#e6821e" },
                    { label:"Reviews", value:exportData.reviews?.length||0, icon:"star", color:"#f59e0b" },
                    { label:"Points", value:exportData.loyaltyPoints||0, icon:"referral", color:"#8b5cf6" },
                    { label:"Claims", value:exportData.claims?.length||0, icon:"shield", color:"#e24b4a" },
                  ].map(item=>(
                    <div key={item.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.75rem 0.5rem", textAlign:"center", border:"1px solid #eee" }}>
                      <div style={{ marginBottom:4, display:"flex", justifyContent:"center" }}>
                        {item.icon==="bookings"?<BookingsIcon size={20} color={item.color}/>:
                         item.icon==="payments"?<PaymentsIcon size={20} color={item.color}/>:
                         item.icon==="vehicle"?<VehicleIcon size={20} color={item.color}/>:
                         item.icon==="star"?<StarIcon size={20} color={item.color}/>:
                         item.icon==="referral"?<ReferEarnIcon size={20} color={item.color}/>:
                         <ShieldIcon size={20} color={item.color}/>}
                      </div>
                      <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, color:item.color }}>{item.value}</div>
                      <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{item.label}</div>
                    </div>
                  ))}
                </div>
                <div style={{ fontFamily:"Syne", fontSize:12, fontWeight:700, color:"#555", marginBottom:8, textTransform:"uppercase", letterSpacing:"0.05em" }}>Download formats</div>
                <div style={{ display:"grid", gridTemplateColumns:"1fr", gap:8, marginBottom:"1rem" }}>
                  <button onClick={()=>downloadJSON(exportData, "ccc-my-data-"+new Date().toLocaleDateString()+".json")} style={{ background:"#fff", border:"1px solid #378add", borderRadius:10, color:"#378add", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"12px", cursor:"pointer", display:"flex", alignItems:"center", gap:8 }}>
                    <span><OrdersIcon size={16} color="#e6821e"/></span><span>Download as JSON</span><span style={{ marginLeft:"auto", fontSize:10, color:"#aaa" }}>Full data export</span>
                  </button>
                  <button onClick={()=>downloadCSV(exportData.bookings||[], "ccc-bookings-"+new Date().toLocaleDateString()+".csv")} style={{ background:"#fff", border:"1px solid #1d9e75", borderRadius:10, color:"#1d9e75", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"12px", cursor:"pointer", display:"flex", alignItems:"center", gap:8 }}>
                    <span><AnalyticsIcon size={16} color="#1d9e75"/></span><span>Download as CSV</span><span style={{ marginLeft:"auto", fontSize:10, color:"#aaa" }}>Spreadsheet format</span>
                  </button>
                  <button onClick={()=>downloadPDF(exportData, "ccc-my-data-"+new Date().toLocaleDateString()+".pdf")} style={{ background:"#fff", border:"1px solid #e6821e", borderRadius:10, color:"#e6821e", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"12px", cursor:"pointer", display:"flex", alignItems:"center", gap:8 }}>
                    <span><DocumentIcon size={16} color="#378add"/></span><span>Download as PDF</span><span style={{ marginLeft:"auto", fontSize:10, color:"#aaa" }}>Printable report</span>
                  </button>
                </div>
                <button onClick={()=>setExportData(null)} style={{ width:"100%", background:"none", border:"1px solid #eee", borderRadius:8, color:"#888", fontSize:12, padding:"8px", cursor:"pointer" }}>
                  <><RefreshIcon size={14} color="#e6821e"/> Reload data</>
                </button>
              </div>
            )}
          </div>
      )}
      {tab==="account"&&(
        <div>
          <div style={{ background:"#fff", border:"1px solid #eee", borderRadius:12, padding:"1.25rem", marginBottom:12 }}>
            <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:700, marginBottom:4 }}>Account information</div>
            <div style={{ fontSize:13, color:"#888" }}>Account ID: {user?.id?.slice(0,8)}...</div>
          </div>
          <div style={{ background:"#fff5f5", border:"1px solid #e24b4a30", borderRadius:12, padding:"1.25rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:700, color:"#e24b4a", marginBottom:6 }}>Danger Zone</div>
            <div style={{ fontSize:13, color:"#666", marginBottom:12, lineHeight:1.6 }}>
              Deleting your account permanently removes all your personal data within 7 days. Active bookings must be resolved first.
            </div>
            <button onClick={handleDeleteAccount} disabled={deletingAccount}
              style={{ background:"#fff", border:"1px solid #e24b4a", borderRadius:8, color:"#e24b4a", fontSize:13, fontWeight:600, padding:"10px 20px", cursor:"pointer" }}>
              {deletingAccount?"Processing...":"Request Account Deletion"}
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

import { ReferEarnIcon, LinkIcon, ShareIcon, ProfileIcon, CheckIcon, SuccessIcon, TrophyIcon, WhatsAppIcon, EmailIcon } from "../../lib/cccIcons";
import useIsMobile from "../../lib/useIsMobile"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import toast from "react-hot-toast"
import { openExternal } from "../../lib/openExternal"

const REFERRAL_POINTS = 500
const REFERRED_POINTS = 200

export default function CustomerReferral() {
  const isMobile = useIsMobile()
  const { user, profile } = useAuth()
  const [referrals, setReferrals] = useState([])
  const [stats, setStats] = useState({ total:0, completed:0, pending:0, pointsEarned:0 })
  const [loading, setLoading] = useState(true)
  const [copied, setCopied] = useState(false)
  const [leaderboard, setLeaderboard] = useState([])

  useEffect(() => { if (user) load() }, [user])

  async function load() {
    const [{ data }, { data: lb }] = await Promise.all([
      supabase.from("referrals")
        .select("*, profiles!referrals_referred_id_fkey(first_name,last_name,created_at)")
        .eq("referrer_id", user.id)
        .order("created_at", { ascending:false }),
      supabase.rpc("get_referral_leaderboard", { limit_count: 10 })
    ])
    const refs = data||[]
    setReferrals(refs)
    setLeaderboard(lb||[])
    setStats({
      total: refs.length,
      completed: refs.filter(r=>r.status==="completed"||r.status==="rewarded").length,
      pending: refs.filter(r=>r.status==="pending").length,
      pointsEarned: refs.filter(r=>r.status==="rewarded").reduce((s,r)=>s+r.points_awarded,0)
    })
    setLoading(false)
  }

  function getReferralLink() {
    return `${window.location.origin}/auth?ref=${profile?.referral_code}`
  }

  async function copyLink() {
    await navigator.clipboard.writeText(getReferralLink())
    setCopied(true)
    toast.success("Referral link copied!")
    setTimeout(() => setCopied(false), 2000)
  }

  function shareWhatsApp() {
    const msg = encodeURIComponent(`Join Car Care Connect and get your car serviced easily! Use my referral link to sign up and earn ${REFERRED_POINTS} bonus points: ${getReferralLink()}`)
    openExternal(`https://wa.me/?text=${msg}`)
  }

  function shareEmail() {
    const subject = encodeURIComponent("Join Car Care Connect")
    const body = encodeURIComponent(`Hi!\n\nI've been using Car Care Connect for my car service needs and it's amazing.\n\nSign up using my referral link and get ${REFERRED_POINTS} bonus loyalty points:\n${getReferralLink()}\n\nSee you there!`)
    window.open(`mailto:?subject=${subject}&body=${body}`, "_blank")
  }

  const RC = { pending:"#e6821e", completed:"#378add", rewarded:"#1d9e75" }

  return (
    <div>
      <div style={{ marginBottom:"1.5rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:20, fontWeight:800, color:"#000000" }}>
          Refer & <span style={{ color:"#e6821e" }}>Earn</span>
        </div>
        <div style={{ fontSize:12, color:"#777777", marginTop:2 }}>
          Earn {REFERRAL_POINTS} points for every friend who joins
        </div>
      </div>

      <div style={{ background:"linear-gradient(135deg, #fff8f0 0%, #ffffff 100%)", border:"1px solid #e6821e30", borderRadius:16, padding:"1.5rem", marginBottom:"1.5rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, color:"#000000", marginBottom:4 }}>Your referral code</div>
        <div style={{ fontSize:12, color:"#555555", marginBottom:"1.25rem" }}>
          Share this code or link with friends. You earn <span style={{ color:"#e6821e", fontWeight:600 }}>{REFERRAL_POINTS} points</span> when they sign up and make their first booking. They get <span style={{ color:"#1d9e75", fontWeight:600 }}>{REFERRED_POINTS} bonus points</span> too!
        </div>

        <div style={{ background:"#ffffff", borderRadius:10, padding:"1rem", marginBottom:"1rem", display:"flex", alignItems:"center", justifyContent:"space-between", gap:10 }}>
          <div>
            <div style={{ fontSize:10, color:"#777777", textTransform:"uppercase", marginBottom:4 }}>Your code</div>
            <div style={{ fontFamily:"Syne", fontSize:28, fontWeight:800, color:"#e6821e", letterSpacing:4 }}>
              {profile?.referral_code || "..."}
            </div>
          </div>
          <button onClick={copyLink}
            style={{ background:copied?"#f0fdf4":"#e6821e", border:`1px solid ${copied?"#1d9e7540":"transparent"}`, borderRadius:9, color:copied?"#1d9e75":"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"10px 18px", cursor:"pointer", flexShrink:0, transition:"all 0.2s" }}>
            {copied?"Γ£ô Copied!":"Copy code"}
          </button>
        </div>

        <div style={{ background:"#ffffff", borderRadius:10, padding:"0.9rem", marginBottom:"1rem" }}>
          <div style={{ fontSize:10, color:"#777777", textTransform:"uppercase", marginBottom:4 }}>Referral link</div>
          <div style={{ fontSize:11, color:"#666", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{getReferralLink()}</div>
        </div>

        <div style={{ display:"flex", gap:8 }}>
          <button onClick={shareWhatsApp}
            style={{ flex:1, background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:9, color:"#1d9e75", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px", cursor:"pointer" }}>
            <WhatsAppIcon size={15} color="#1d9e75"/> Share on WhatsApp
          </button>
          <button onClick={shareEmail}
            style={{ flex:1, background:"#eff6ff", border:"1px solid #378add40", borderRadius:9, color:"#378add", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px", cursor:"pointer" }}>
            <EmailIcon size={15} color="#378add"/> Share via Email
          </button>
          <button onClick={copyLink}
            style={{ background:"#f5f5f5", border:"1px solid #dddddd", borderRadius:9, color:"#555555", fontSize:13, padding:"11px 16px", cursor:"pointer" }}>
            <LinkIcon size={16} color="#378add" />
          </button>
        </div>
      </div>

      <div style={{ display:"grid", gridTemplateColumns:isMobile?"repeat(2,1fr)":"repeat(4,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Total referrals", value:stats.total },
          { label:"Completed", value:stats.completed, color:"#1d9e75" },
          { label:"Pending", value:stats.pending, color:stats.pending>0?"#e6821e":undefined },
          { label:"Points earned", value:stats.pointsEarned.toLocaleString(), color:"#e6821e" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#ffffff", borderRadius:10, padding:"1rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontSize:11, color:"#777777", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:6 }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:20, fontWeight:800, color:s.color||"#000000" }}>{s.value}</div>
          </div>
        ))}
      </div>

      <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem", marginBottom:"1.5rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:"1rem", color:"#000000" }}>How it works</div>
        {[
          { step:"1", icon:"ShareIcon", title:"Share your code", desc:`Send your unique referral code or link to friends` },
          { step:"2", icon:"ProfileIcon", title:"Friend signs up", desc:"They register using your referral link" },
          { step:"3", title:"First booking made", desc:"They complete their first service booking", icon:"CheckIcon" },
          { step:"4", title:"Both earn points", desc:`You get ${REFERRAL_POINTS} pts ┬╖ They get ${REFERRED_POINTS} pts`, icon:"TrophyIcon" },
        ].map((s,i)=>(
          <div key={s.step} style={{ display:"flex", gap:12, marginBottom:i<3?12:0 }}>
            <div style={{ width:40, height:40, borderRadius:10, background:"#fff8f0", border:"1px solid #e6821e30", display:"flex", alignItems:"center", justifyContent:"center", fontSize:20, flexShrink:0 }}>
              {s.icon==="ShareIcon"?<ReferEarnIcon size={24} color="#e6821e"/>:
   s.icon==="ProfileIcon"?<ProfileIcon size={24} color="#378add"/>:
   s.icon==="CheckIcon"?<CheckIcon size={24} color="#1d9e75"/>:
   s.icon==="TrophyIcon"?<TrophyIcon size={24} color="#8b5cf6"/>:
   <SuccessIcon size={24} color="#1d9e75"/>}
            </div>
            <div style={{ flex:1 }}>
              <div style={{ fontSize:13, fontWeight:600, color:"#000000", marginBottom:2 }}>{s.title}</div>
              <div style={{ fontSize:11, color:"#666" }}>{s.desc}</div>
            </div>
          </div>
        ))}
      </div>

      {leaderboard.length>0&&(
        <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem", marginBottom:"1.5rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:"1rem", color:"#000000" }}>≡ƒÅå Referral Leaderboard</div>
          {leaderboard.map((row,i)=>(
            <div key={row.user_id} style={{ display:"flex", alignItems:"center", gap:10, padding:"8px 0", borderBottom: i<leaderboard.length-1?"1px solid #eeeeee":"none", background:row.user_id===user.id?"#fff8f0":"transparent" }}>
              <div style={{ width:24, textAlign:"center", fontFamily:"Syne", fontSize:13, fontWeight:800, color:i===0?"#e6821e":i===1?"#888":i===2?"#a0703a":"#bbb" }}>
                {i===0?"≡ƒÑç":i===1?"≡ƒÑê":i===2?"≡ƒÑë":i+1}
              </div>
              <div style={{ flex:1, fontSize:13, color:"#000000" }}>
                {row.first_name} {row.last_name?.[0]||""}.{row.user_id===user.id?" (You)":""}
              </div>
              <div style={{ fontSize:11, color:"#777777" }}>{row.total_referrals} referral{row.total_referrals!==1?"s":""}</div>
              <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#e6821e", minWidth:60, textAlign:"right" }}>{row.total_points.toLocaleString()} pts</div>
            </div>
          ))}
        </div>
      )}

      <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:10, color:"#000000" }}>
        Your referrals ({referrals.length})
      </div>
      {loading&&<div style={{ color:"#777777", fontSize:13 }}>Loading...</div>}
      {!loading&&referrals.length===0&&(
        <div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"2rem", background:"#ffffff", borderRadius:10, border:"1px solid #eeeeee" }}>
          No referrals yet. Share your code to get started!
        </div>
      )}
      {referrals.map(r=>(
        <div key={r.id} style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:8, display:"flex", alignItems:"center", gap:12 }}>
          <div style={{ width:40, height:40, borderRadius:"50%", background:"#fff8f0", border:"1px solid #e6821e30", display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#e6821e", flexShrink:0 }}>
            {r.profiles?.first_name?.[0]||"?"}
          </div>
          <div style={{ flex:1, minWidth:0 }}>
            <div style={{ fontSize:13, fontWeight:500, color:"#000000" }}>
              {r.profiles?.first_name&&r.profiles?.last_name ? `${r.profiles.first_name} ${r.profiles.last_name}` : "Pending signup"}
            </div>
            <div style={{ fontSize:11, color:"#777777", marginTop:2 }}>
              {r.status==="rewarded" ? `+${r.points_awarded} points earned` : r.status==="completed" ? "Booking completed ΓÇö points pending" : "Waiting for first booking"}
            </div>
            <div style={{ fontSize:10, color:"#888888", marginTop:2 }}>{new Date(r.created_at).toLocaleDateString()}</div>
          </div>
          <span style={{ fontSize:11, padding:"3px 9px", borderRadius:20, background:`${RC[r.status]||"#888"}20`, color:RC[r.status]||"#888", border:`1px solid ${RC[r.status]||"#888"}40`, flexShrink:0 }}>
            {r.status}
          </span>
        </div>
      ))}
    </div>
  )
}

import { useEffect, useState } from "react"
import { StarRatingIcon, CameraIcon, ChatIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import { useLanguage } from "../../contexts/LanguageContext"
import toast from "react-hot-toast"
import { filterReviewContent } from "../../lib/reviewFilter"
import { useLocation } from "react-router-dom"

function StarRating({ value, onChange, label }) {
  return (
    <div style={{ marginBottom:"1rem" }}>
      <div style={{ fontSize:11, color:"#666", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:8 }}>{label}</div>
      <div style={{ display:"flex", gap:6 }}>
        {[1,2,3,4,5].map(star=>(
          <button key={star} type="button" onClick={()=>onChange(star)}
            style={{ background:"none", border:"none", cursor:"pointer", fontSize:28, color:star<=value?"#e6821e":"#555555", padding:"2px" }}>Γÿà</button>
        ))}
      </div>
      {value>0&&<div style={{ fontSize:11, color:"#e6821e", marginTop:4 }}>{["","Poor","Fair","Good","Very good","Excellent"][value]}</div>}
    </div>
  )
}

export default function CustomerReviews() {
  const { user } = useAuth()
  const { t } = useLanguage()
  const [completedBookings, setCompletedBookings] = useState([])
  const [myReviews, setMyReviews] = useState([])
  const [receivedReviews, setReceivedReviews] = useState([])
  const [respondingTo, setRespondingTo] = useState(null)
  const [responseText, setResponseText] = useState("")
  const [submittingResponse, setSubmittingResponse] = useState(false)
  const [tab, setTab] = useState("pending")
  const [loading, setLoading] = useState(true)
  const [reviewing, setReviewing] = useState(null)
  const [form, setForm] = useState({ provider_rating:0, provider_review:"", driver_rating:0, driver_review:"", mechanic_rating:0, mechanic_review:"" })
  const [submitting, setSubmitting] = useState(false)
  const [photos, setPhotos] = useState([])
  const [uploading, setUploading] = useState(false)

  const location = useLocation()
  const preselectedBooking = new URLSearchParams(location.search).get("booking")
  useEffect(() => { if (user) load() }, [user])
  useEffect(() => {
    if (preselectedBooking && completedBookings.length > 0) {
      const b = completedBookings.find(b=>b.id===preselectedBooking)
      if(b) { setReviewing(b); setTab("pending") }
    }
  }, [preselectedBooking, completedBookings])

  async function load() {
    const [{ data: bookings }, { data: reviews }, { data: received }] = await Promise.all([
      supabase.from("bookings").select("*").eq("customer_id",user.id).eq("status","completed").order("created_at",{ascending:false}),
      supabase.from("reviews").select("*, profile_public!reviews_provider_id_fkey(first_name,last_name,business_name)").eq("customer_id",user.id).order("created_at",{ascending:false}),
      supabase.from("reviews").select("*, provider:profile_public!reviews_provider_id_fkey(first_name,last_name,business_name)").eq("customer_id",user.id).not("customer_rating","is",null).order("created_at",{ascending:false})
    ])
    setCompletedBookings(bookings||[])
    setMyReviews(reviews||[])
    setReceivedReviews(received||[])
    setLoading(false)
  }

  const reviewedBookingIds = new Set(myReviews.map(r=>r.booking_id))
  const pendingReview = completedBookings.filter(b=>!reviewedBookingIds.has(b.id))

  async function submitResponse(reviewId) {
    if(!responseText.trim()) return toast.error("Please write a response")
    const check = filterReviewContent(responseText)
    if(check.hasContactInfo || check.hasBadWords) return toast.error("Please keep your response professional")
    setSubmittingResponse(true)
    await supabase.from("reviews").update({ customer_response: responseText }).eq("id", reviewId).eq("customer_id", user.id)
    toast.success("Response submitted!")
    setRespondingTo(null); setResponseText(""); setSubmittingResponse(false); load()
  }
  async function uploadPhoto(file) {
    const ext = file.name.split(".").pop()
    const path = "reviews/"+user.id+"/"+Date.now()+"."+ext
    const { error } = await supabase.storage.from("review-photos").upload(path, file)
    if (error) throw error
    const { data } = supabase.storage.from("review-photos").getPublicUrl(path)
    return data.publicUrl
  }
  async function handlePhotoSelect(e) {
    const files = Array.from(e.target.files).slice(0,3)
    setUploading(true)
    try {
      const urls = await Promise.all(files.map(uploadPhoto))
      setPhotos(prev=>[...prev,...urls].slice(0,3))
    } catch(err) { toast.error("Photo upload failed: "+err.message) }
    setUploading(false)
  }
  async function submitReview(e) {
    e.preventDefault()
    if (form.provider_rating===0) return toast.error(t("error"))
    // Filter review content
    const reviewCheck = filterReviewContent(form.provider_review)
    if (reviewCheck.hasContactInfo) return toast.error("Reviews cannot contain contact details (phone/email). Please keep all communication on the platform.")
    if (reviewCheck.hasBadWords) return toast.error("Your review contains inappropriate language. Please keep it professional.")
    const driverCheck = filterReviewContent(form.driver_review)
    if (driverCheck.hasContactInfo || driverCheck.hasBadWords) return toast.error("Driver review contains inappropriate content. Please keep it professional.")
    setSubmitting(true)
    try {
      const { error } = await supabase.from("reviews").insert({
        booking_id:reviewing.id, customer_id:user.id, provider_id:reviewing.provider_id,
        driver_id:reviewing.driver_id||null, provider_rating:form.provider_rating,
        mechanic_id:reviewing.assigned_mechanic_id||null,
        mechanic_rating:reviewing.assigned_mechanic_id?form.mechanic_rating||null:null,
        mechanic_review:reviewing.assigned_mechanic_id&&form.mechanic_review?form.mechanic_review:null,
        provider_review:form.provider_review||null,
        driver_rating:reviewing.is_concierge&&form.driver_rating>0?form.driver_rating:null,
        driver_review:reviewing.is_concierge&&form.driver_review?form.driver_review:null,
        photo_urls: photos.length>0 ? photos : null,
      })
      if (error) throw error

      // Send push notification to provider
      try {
        await fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/send-push`, {
          method: "POST",
          headers: { "Content-Type": "application/json", "Authorization": `Bearer ${import.meta.env.VITE_SUPABASE_ANON_KEY}` },
          body: JSON.stringify({
            user_id: reviewing.provider_id,
            title: "New Review Received! Γ¡É",
            message: `${form.provider_rating} star review: ${form.provider_review||"No comment"}`.substring(0,100)
          })
        })
        // Also notify driver if rated
        if(reviewing.driver_id && form.driver_rating>0) {
          await fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/send-push`, {
            method: "POST",
            headers: { "Content-Type": "application/json", "Authorization": `Bearer ${import.meta.env.VITE_SUPABASE_ANON_KEY}` },
            body: JSON.stringify({
              user_id: reviewing.driver_id,
              title: "New Driver Review! Γ¡É",
              message: `${form.driver_rating} star rating: ${form.driver_review||"No comment"}`.substring(0,100)
            })
          })
        }
      } catch(pushErr) { console.log("Push notification failed:", pushErr.message) }
      // Award 50 bonus points for leaving a review (loyalty_points is the real table CustomerLoyalty.jsx reads from)
      const { data: lp } = await supabase.from("loyalty_points").select("points,lifetime_points").eq("user_id", user.id).maybeSingle()
      await supabase.from("loyalty_points").upsert({
        user_id: user.id,
        points: (lp?.points||0) + 50,
        lifetime_points: (lp?.lifetime_points||0) + 50,
      }, { onConflict: "user_id" })
      await supabase.from("notifications").insert({
        user_id: user.id,
        title: "Review Bonus!",
        message: "Thanks for your review! You earned 50 bonus points.",
        type: "success",
      })

      // Save mechanic rating to booking and update mechanic's average rating
      if (reviewing.assigned_mechanic_id && form.mechanic_rating > 0) {
        await supabase.from("bookings").update({
          mechanic_rating: form.mechanic_rating,
          mechanic_rating_comment: form.mechanic_review
        }).eq("id", reviewing.id)

        const { data: mechRatings } = await supabase.from("bookings")
          .select("mechanic_rating")
          .eq("assigned_mechanic_id", reviewing.assigned_mechanic_id)
          .not("mechanic_rating", "is", null)
        if (mechRatings?.length) {
          const avg = mechRatings.reduce((s,r)=>s+r.mechanic_rating,0)/mechRatings.length
          await supabase.from("mechanics").update({
            rating: Math.round(avg*10)/10,
            total_reviews: mechRatings.length
          }).eq("id", reviewing.assigned_mechanic_id)
        }
      }

      toast.success(t("success") + " +50 points!")
      setReviewing(null)
      setPhotos([])
      setForm({ provider_rating:0, provider_review:"", driver_rating:0, driver_review:"", mechanic_rating:0, mechanic_review:"" })
      load()
    } catch(err) {
      toast.error(err.message)
    } finally {
      setSubmitting(false)
    }
  }

  const pendingLabel = t("language")==="sw" ? "Zinazosubiri" : "Pending reviews"
  const submittedLabel = t("language")==="sw" ? "Maoni yangu" : "My reviews"
  const inp = { width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"10px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif", resize:"vertical" }

  return (
    <div>
      <div style={{ display:"flex", gap:6, marginBottom:"1.25rem" }}>
        {[
          { k:"pending", l:`${pendingLabel} (${pendingReview.length})` },
          { k:"submitted", l:`${submittedLabel} (${myReviews.length})` },
          { k:"received", l:`Reviews about me (${receivedReviews.length})` },
        ].map(t2=>(
          <button key={t2.k} onClick={()=>setTab(t2.k)}
            style={{ padding:"8px 16px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t2.k?"#e6821e":"#555555", color:tab===t2.k?"#fff":"#666", fontFamily:"'DM Sans',sans-serif", fontWeight:tab===t2.k?700:400 }}>
            {t2.l}
          </button>
        ))}
      </div>

      {loading&&<div style={{ color:"#777777", fontSize:13 }}>{t("loading")}</div>}

      {tab==="pending"&&!reviewing&&(
        <div>
          {pendingReview.length===0&&!loading&&<div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"2rem" }}>{t("noDataYet")}</div>}
          {pendingReview.map(b=>(
            <div key={b.id} style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:8, display:"flex", alignItems:"center", gap:12 }}>
              <div style={{ width:42, height:42, background:"#fff8f0", borderRadius:9, display:"flex", alignItems:"center", justifyContent:"center", fontSize:20, flexShrink:0 }}>≡ƒöº</div>
              <div style={{ flex:1 }}>
                <div style={{ fontSize:14, fontWeight:500, color:"#000000" }}>{b.service_name}</div>
                <div style={{ fontSize:11, color:"#777777", marginTop:2 }}>{b.booking_date} ┬╖ KES {Number(b.total_amount).toLocaleString()}</div>
              </div>
              <button onClick={()=>{ setReviewing(b); setForm({ provider_rating:0, provider_review:"", driver_rating:0, driver_review:"" }) }}
                style={{ background:"#e6821e", border:"none", borderRadius:8, color:"#fff", fontSize:12, fontWeight:700, padding:"8px 14px", cursor:"pointer", fontFamily:"Syne,sans-serif", flexShrink:0 }}>
                {t("language")==="sw"?"Kadiria":"Rate"}
              </button>
            </div>
          ))}
        </div>
      )}

      {tab==="pending"&&reviewing&&(
        <div>
          <button onClick={()=>setReviewing(null)} style={{ background:"none", border:"none", color:"#666", cursor:"pointer", fontSize:13, marginBottom:"1rem", fontFamily:"'DM Sans',sans-serif", padding:0 }}>
            ΓåÉ {t("back")}
          </button>
          <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#000000", marginBottom:2 }}>{reviewing.service_name}</div>
            <div style={{ fontSize:11, color:"#777777", marginBottom:"1.5rem" }}>{reviewing.booking_date}</div>
            <form onSubmit={submitReview}>
              <StarRating value={form.provider_rating} onChange={v=>setForm(f=>({...f,provider_rating:v}))} label={t("language")==="sw"?"Kadiria mtoa huduma":"Rate the service provider"}/>
              <div style={{ marginBottom:"1rem" }}>
                <div style={{ fontSize:11, color:"#666", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:6 }}>{t("language")==="sw"?"Maoni (hiari)":"Review (optional)"}</div>
                <textarea value={form.provider_review} onChange={e=>setForm(f=>({...f,provider_review:e.target.value}))} rows={3} placeholder={t("language")==="sw"?"Shiriki uzoefu wako...":"Share your experience..."} style={inp}/>
              </div>
              {reviewing.is_concierge&&(
                <>
                  <div style={{ height:1, background:"#f0f0f0", margin:"1rem 0" }}/>
                  <StarRating value={form.driver_rating} onChange={v=>setForm(f=>({...f,driver_rating:v}))} label={t("language")==="sw"?"Kadiria dereva (hiari)":"Rate the driver (optional)"}/>
                </>
              )}
              {/* Mechanic rating - shown if mechanic was assigned */}
              {reviewing.assigned_mechanic_id&&(
                <>
                  <hr style={{ border:"none", borderTop:"1px solid #f0f0f0", margin:"1rem 0" }}/>
                  <StarRating value={form.mechanic_rating} onChange={v=>setForm(f=>({...f,mechanic_rating:v}))} label="Rate the mechanic (optional)"/>
                  {form.mechanic_rating>0&&(
                    <textarea value={form.mechanic_review} onChange={e=>setForm(f=>({...f,mechanic_review:e.target.value}))}
                      placeholder="Comment about the mechanic's work..."
                      rows={2} style={{ width:"100%", background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:8, padding:"10px 12px", fontSize:12, color:"#000", outline:"none", resize:"none", marginTop:8, boxSizing:"border-box" }}/>
                  )}
                </>
              )}
              {/* Photo upload */}
              <div style={{ marginBottom:"1rem" }}>
                <div style={{ fontSize:11, color:"#666", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:6 }}>Add photos (optional)</div>
                <input type="file" accept="image/*" multiple onChange={handlePhotoSelect} style={{ display:"none" }} id="review-photos"/>
                <label htmlFor="review-photos" style={{ display:"inline-block", background:"#f8f8f8", border:"1px solid #eee", borderRadius:8, padding:"8px 14px", fontSize:12, cursor:"pointer", color:"#555" }}>
                  {uploading?"Uploading...":<><CameraIcon size={14} color="currentColor"/> Add photos</>}
                </label>
                {photos.length>0&&(
                  <div style={{ display:"flex", gap:6, marginTop:8, flexWrap:"wrap" }}>
                    {photos.map((url,i)=>(
                      <div key={i} style={{ position:"relative" }}>
                        <img src={url} alt="" style={{ width:60, height:60, objectFit:"cover", borderRadius:8, border:"1px solid #eee" }}/>
                        <button type="button" onClick={()=>setPhotos(p=>p.filter((_,j)=>j!==i))} style={{ position:"absolute", top:-4, right:-4, background:"#e24b4a", border:"none", borderRadius:"50%", width:16, height:16, color:"#fff", fontSize:10, cursor:"pointer" }}>├ù</button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
              <button type="submit" disabled={submitting||form.provider_rating===0||uploading}
                style={{ width:"100%", background:form.provider_rating>0?"#e6821e":"#555555", border:"none", borderRadius:9, color:form.provider_rating>0?"#fff":"#666", fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700, padding:"13px", cursor:form.provider_rating>0?"pointer":"not-allowed" }}>
                {submitting?t("loading"):t("submit")}
              </button>
            </form>
          </div>
        </div>
      )}

      {tab==="received"&&(
        <div>
          {receivedReviews.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No reviews about you yet</div>}
          {receivedReviews.map(r=>(
            <div key={r.id} style={{ background:"#fff", border:"1px solid #eee", borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:600 }}>{r.provider?.business_name||r.provider?.first_name} {r.provider?.last_name}</div>
                  <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{new Date(r.created_at).toLocaleDateString()}</div>
                </div>
                <div style={{ display:"flex", gap:1 }}>{[1,2,3,4,5].map(s=><span key={s} style={{ color:s<=r.customer_rating?"#378add":"#ddd", fontSize:16 }}>Γÿà</span>)}</div>
              </div>
              {r.customer_review&&<div style={{ fontSize:12, color:"#555", fontStyle:"italic", marginBottom:8 }}>"{"}{"}r.customer_review{"}"}"</div>}
              {r.customer_response?(
                <div style={{ background:"#f0fdf4", border:"1px solid #1d9e7520", borderRadius:8, padding:"0.5rem 0.75rem" }}>
                  <div style={{ fontSize:10, color:"#1d9e75", fontWeight:600, marginBottom:2 }}>Your response</div>
                  <div style={{ fontSize:12, color:"#333" }}>{r.customer_response}</div>
                </div>
              ):respondingTo===r.id?(
                <div>
                  <textarea value={responseText} onChange={e=>setResponseText(e.target.value)} rows={3} placeholder="Write a professional response..."
                    style={{ width:"100%", background:"#f8f8f8", border:"1px solid #ddd", borderRadius:8, padding:"10px 12px", fontSize:12, outline:"none", resize:"none", boxSizing:"border-box" }}/>
                  <div style={{ display:"flex", gap:8, marginTop:6 }}>
                    <button onClick={()=>submitResponse(r.id)} disabled={submittingResponse} style={{ background:"#378add", border:"none", borderRadius:7, color:"#fff", fontSize:12, fontWeight:700, padding:"8px 16px", cursor:"pointer" }}>{submittingResponse?"Posting...":"Post Response"}</button>
                    <button onClick={()=>{ setRespondingTo(null); setResponseText("") }} style={{ background:"#f0f0f0", border:"none", borderRadius:7, color:"#555", fontSize:12, padding:"8px 14px", cursor:"pointer" }}>Cancel</button>
                  </div>
                </div>
              ):(
                <button onClick={()=>{ setRespondingTo(r.id); setResponseText("") }} style={{ background:"#eff6ff", border:"1px solid #378add30", borderRadius:7, color:"#378add", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>≡ƒÆ¼ Respond</button>
              )}
            </div>
          ))}
        </div>
      )}
      {tab==="submitted"&&(
        <div>
          {myReviews.length===0&&<div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"2rem" }}>{t("noDataYet")}</div>}
          {myReviews.map(r=>(
            <div key={r.id} style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:500, color:"#000000" }}>
                    {r.profile_public?.business_name||`${r.profile_public?.first_name||""} ${r.profile_public?.last_name||""}`}
                  </div>
                  <div style={{ fontSize:10, color:"#888888", marginTop:2 }}>{new Date(r.created_at).toLocaleDateString()}</div>
                </div>
                <div style={{ display:"flex", gap:1 }}>
                  {[1,2,3,4,5].map(s=><span key={s} style={{ color:s<=r.provider_rating?"#e6821e":"#555555", fontSize:16 }}>Γÿà</span>)}
                </div>
              </div>
              {r.provider_review&&<div style={{ fontSize:12, color:"#555555", lineHeight:1.5, marginBottom:8 }}>&quot;{r.provider_review}&quot;</div>}
              {r.photo_urls?.length>0&&(
                <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginBottom:8 }}>
                  {r.photo_urls.map((url,i)=>(
                    <img key={i} src={url} alt="" onClick={()=>window.open(url,"_blank")}
                      style={{ width:70, height:70, objectFit:"cover", borderRadius:8, cursor:"pointer", border:"1px solid #eee" }}/>
                  ))}
                </div>
              )}
              {r.provider_response&&(
                <div style={{ background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"0.75rem", marginTop:8 }}>
                  <div style={{ fontSize:10, color:"#777777", marginBottom:4 }}>{t("language")==="sw"?"Jibu la mtoa huduma":"Provider reply"}</div>
                  <div style={{ fontSize:12, color:"#666666", lineHeight:1.5 }}>{r.provider_response}</div>
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { MarketplaceIcon, HomeIcon, GOServiceIcon, LocationIcon, ServicesIcon } from "../../lib/cccIcons"
import { pushNotify } from "../../lib/pushNotify"
import { sanitizeAmount } from "../../lib/sanitize"
import { useSearchParams } from "react-router-dom"
import { useAuth } from "../../contexts/AuthContext"
import { useLanguage } from "../../contexts/LanguageContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"
import DarajaPayment from "../shared/DarajaPayment"

const CATEGORIES = [
  { key:"shop_standard", label:"Shop Standard", icon:"marketplace", desc:"You bring your car to the shop", color:"#378add", bg:"#eff6ff", border:"#bfdbfe" },
  { key:"shop_premium", label:"Shop Premium", icon:"home", desc:"Mechanic comes to your home", color:"#8b5cf6", bg:"#faf5ff", border:"#e9d5ff" },
]

export default function CustomerServices() {
  const isMobile = useIsMobile()
  const [searchParams] = useSearchParams()
  const { user, profile } = useAuth()
  const { t } = useLanguage()
  const [services, setServices] = useState([])
  const [bundles, setBundles] = useState([])
  const [providers, setProviders] = useState([])
  const [loading, setLoading] = useState(true)
  const [activeCategory, setActiveCategory] = useState("all")
  const [search, setSearch] = useState("")
  const [booking, setBooking] = useState(null)
  const [dateAvailability, setDateAvailability] = useState(null)
    const [bookForm, setBookForm] = useState({ date:"", time:"", notes:"", payment_method:"mpesa", is_concierge:false, concierge_location:"", problem_description:"", parts_needed:false, parts_description:"" })
  const [bookingLoading, setBookingLoading] = useState(false)
  const [customerLocation, setCustomerLocation] = useState({ lat:null, lng:null, address:"" })
  const [detectingLocation, setDetectingLocation] = useState(false)
  const [pendingBooking, setPendingBooking] = useState(null)
  const [showPayment, setShowPayment] = useState(false)
  const [voucherCode, setVoucherCode] = useState("")
  const [voucherData, setVoucherData] = useState(null)
  const [voucherLoading, setVoucherLoading] = useState(false)
  const [promoCode, setPromoCode] = useState("")
  const [promoData, setPromoData] = useState(null)
  const [promoLoading, setPromoLoading] = useState(false)
  const [vehicles, setVehicles] = useState([])
  const [selectedVehicle, setSelectedVehicle] = useState("")
  const [bulkMode, setBulkMode] = useState(false)
  const [bulkVehicles, setBulkVehicles] = useState([])
  const [conciergeMultiplier, setConciergeMultiplier] = useState(1.15)
  const [transportAllowance, setTransportAllowance] = useState(200)
  const [goServicePlatformRate, setGoServicePlatformRate] = useState(0.15)

  useEffect(() => { if (user) load() }, [user])
  useEffect(() => {
    supabase.from("app_settings").select("value").eq("key","concierge_surcharge_rate").maybeSingle()
      .then(({ data }) => { if (data?.value) setConciergeMultiplier(1 + Number(data.value)/100) })
    supabase.from("app_settings").select("value").eq("key","driver_transport_allowance").maybeSingle()
      .then(({ data }) => { if (data?.value) setTransportAllowance(Number(data.value)) })
    supabase.from("app_settings").select("value").eq("key","go_service_provider_rate").maybeSingle()
      .then(({ data }) => { if (data?.value) setGoServicePlatformRate(1 - Number(data.value)/100) })
  }, [])

  useEffect(() => {
    const serviceId = searchParams.get("service")
    if (!serviceId || services.length === 0) return
    const found = services.find(s => s.id === serviceId)
    if (found) {
      setBooking(found)
