                        <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, color:"#555555", marginBottom:2 }}>
                          <span>{b.name}</span><span>KES {Number(b.bundle_price).toLocaleString()}</span>
                        </div>
                        <div style={{ height:1, background:"#f0f0f0", margin:"6px 0" }}/>
                        {voucherData&&(
                          <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, color:"#1d9e75", marginBottom:2 }}>
                            <span>Voucher discount</span><span>- KES {Number(voucherData.value).toLocaleString()}</span>
                          </div>
                        )}
                        {promoData&&(
                          <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, color:"#e6821e", marginBottom:2 }}>
                            <span>Promo discount</span><span>- KES {Number(promoData.discount).toLocaleString()}</span>
                          </div>
                        )}
                        <div style={{ display:"flex", justifyContent:"space-between", fontSize:13, color:"#e6821e", fontWeight:700 }}>
                          <span>Total</span>
                          <span>KES {Math.max(0,Number(b.bundle_price)-(voucherData?Number(voucherData.value):0)-(promoData?Number(promoData.discount):0)).toFixed(0)}</span>
                        </div>
                      </div>

                      <div style={{ display:"flex", gap:8 }}>
                        <button type="submit" disabled={bookingLoading}
                          style={{ background:bookingLoading?"#ccc":"#e6821e", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px 24px", cursor:bookingLoading?"not-allowed":"pointer" }}>
                          {bookingLoading?"Booking...":"Confirm booking"}
                        </button>
                        <button type="button" onClick={()=>setBooking(null)}
                          style={{ background:"none", border:"1px solid #dddddd", borderRadius:9, color:"#666", fontSize:13, padding:"11px 16px", cursor:"pointer", fontFamily:"'DM Sans',sans-serif" }}>
                          Cancel
                        </button>
                      </div>
                    </form>
                  </div>
                )}
              </div>
            )
          })}
        </div>
      )}

      {loading&&<div style={{ color:"#777777", fontSize:13 }}>Loading services...</div>}
      {!loading&&filtered.length===0&&<div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"2rem" }}>No services found</div>}

      {filtered.map(s=>{
        const cat = CATEGORIES.find(c=>c.key===s.category)||CATEGORIES[0]
        const provider = providers.find(p=>p.id===s.provider_id)
        return (
          <div key={s.id} style={{ background:"#ffffff", border:`1px solid ${cat.border}`, borderRadius:12, padding:isMobile?"0.9rem":"1.1rem", marginBottom:10 }}>
            {s.photos?.length>0 ? (
              <div style={{ marginBottom:"0.875rem", borderRadius:10, overflow:"hidden", position:"relative" }}>
                <img src={s.photos[0]} alt={s.name} style={{ width:"100%", height:160, objectFit:"cover", display:"block" }}/>
                {s.photos.length>1&&<div style={{ position:"absolute", bottom:6, right:6, background:"rgba(0,0,0,0.55)", borderRadius:8, padding:"2px 8px", fontSize:10, color:"#fff" }}>≡ƒô╖ {s.photos.length}</div>}
              </div>
            ) : (
              <div style={{ marginBottom:"0.875rem", borderRadius:10, height:80, background:cat.bg, display:"flex", alignItems:"center", justifyContent:"center" }}>
                {cat.icon==="marketplace"?<MarketplaceIcon size={36} color={cat.color}/>:
                 cat.icon==="home"?<HomeIcon size={36} color={cat.color}/>:
                 cat.icon==="emergency"?<GOServiceIcon size={36} color="#e24b4a"/>:
                 cat.icon==="discover"?<DiscoverIcon size={36} color={cat.color}/>:
                 <ServicesIcon size={36} color={cat.color}/>}
              </div>
            )}
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", gap:10 }}>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:6, flexWrap:"wrap" }}>
                  <span style={{ display:"flex" }}>
              {cat.icon==="marketplace"?<MarketplaceIcon size={18} color="currentColor"/>:
               cat.icon==="home"?<HomeIcon size={18} color="currentColor"/>:
               cat.icon==="emergency"?<GOServiceIcon size={18} color="currentColor"/>:
               <ServicesIcon size={18} color="currentColor"/>}
            </span>
                  <div style={{ fontFamily:"Syne", fontSize:isMobile?14:15, fontWeight:800, color:"#000000" }}>{s.name}</div>
                  <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:cat.bg, color:cat.color, border:`1px solid ${cat.border}` }}>{cat.label}</span>
                </div>
                {s.description&&<div style={{ fontSize:12, color:"#666", marginBottom:6, lineHeight:1.5 }}>{s.description.length>120?s.description.slice(0,120)+"...":s.description}</div>}
                <div style={{ display:"flex", gap:12, flexWrap:"wrap", alignItems:"center" }}>
                  <span style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#e6821e" }}>KES {Number(s.price)>=1?Number(s.price).toLocaleString():Number(s.price*100).toLocaleString()}</span>
                  <span style={{ fontSize:11, color:"#777777" }}>ΓÅ▒ {s.duration_minutes||60} min</span>
                  {provider&&<span style={{ fontSize:11, color:"#777777", display:"flex", alignItems:"center", gap:3 }}><MarketplaceIcon size={11} color="#777777"/> {provider.business_name||`${provider.first_name} ${provider.last_name}`}{provider.city?` ┬╖ ${provider.city}`:""}</span>}
                  {provider?.is_verified&&<span style={{ fontSize:10, color:"#1d9e75" }}>Γ£ô Verified</span>}
                </div>
              </div>
              <button onClick={()=>{ if (s.category==="go_service") { window.location.href = "/dashboard/emergency"; return } setBooking(s); setBookForm({ date:"", time:"", notes:"", payment_method:"mpesa", is_concierge:false }) }}
                style={{ background:"#e6821e", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"9px 16px", cursor:"pointer", flexShrink:0 }}>
                Book
              </button>
            </div>

            {booking?.id===s.id&&(
              <div style={{ marginTop:"1rem", paddingTop:"1rem", borderTop:`1px solid ${cat.border}` }}>
                <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, marginBottom:"0.75rem", color:"#000000" }}>Book ΓÇö {s.name}</div>

                {s.category==="go_service"&&(
                  <div style={{ background:"#fff5f5", border:"1px solid #ffd5d5", borderRadius:8, padding:"0.75rem", marginBottom:12 }}>
                    <div style={{ fontSize:12, color:"#e24b4a", fontWeight:600, marginBottom:2, display:"flex", alignItems:"center", gap:4 }}><GOServiceIcon size={12} color="#e24b4a"/> Emergency GO Service</div>
                    <div style={{ fontSize:11, color:"#666" }}>A mechanic will be dispatched to your location. Online payment required. Provider has 15 minutes to accept.</div>
                  </div>
                )}

                {s.category==="shop_premium"&&(
                  <div style={{ background:"#faf5ff", border:"1px solid #e9d5ff", borderRadius:8, padding:"0.75rem", marginBottom:12 }}>
                    <div style={{ fontSize:12, color:"#8b5cf6", fontWeight:600, marginBottom:2, display:"flex", alignItems:"center", gap:4 }}><HomeIcon size={12} color="#8b5cf6"/> Premium Home Service</div>
                    <div style={{ fontSize:11, color:"#666" }}>A mechanic will come to your home or office. Please provide your address in the notes.</div>
                  </div>
                )}

                <form onSubmit={bookService}>
                  <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"1fr 1fr", gap:10, marginBottom:10 }}>
                    <div>
                      <label style={lbl}>Date</label>
                      <input type="date" value={bookForm.date} onChange={e=>{ setBookForm(f=>({...f,date:e.target.value})); setDateAvailability(null); if(e.target.value) checkDateAvailability(e.target.value, booking?.provider_id) }} required min={new Date().toISOString().split("T")[0]} style={inp}/>
                    {dateAvailability&&<div style={{ fontSize:11, marginTop:4, color:dateAvailability.available?"#1d9e75":"#e24b4a" }}>{dateAvailability.available?"Γ£ô ":"Γ£ù "}{dateAvailability.message}</div>}
                    </div>
                    <div>
                      <label style={lbl}>Time</label>
                      <select value={bookForm.time} onChange={e=>setBookForm(f=>({...f,time:e.target.value}))} required style={inp}>
                        <option value="">Select time</option>
                        {["07:00","08:00","09:00","10:00","11:00","12:00","13:00","14:00","15:00","16:00","17:00","18:00"].map(t=><option key={t} value={t}>{t}</option>)}
                      </select>
                    </div>
                  </div>

                  {vehicles.length>0&&(
                    <div style={{ marginBottom:10 }}>
                      <label style={lbl}>Select vehicle (optional)</label>
                      {vehicles.length>1&&(
                        <label style={{ display:"flex", alignItems:"center", gap:8, marginBottom:8, cursor:"pointer" }}>
                          <input type="checkbox" checked={bulkMode} onChange={e=>{ setBulkMode(e.target.checked); setBulkVehicles([]); setSelectedVehicle("") }} style={{ accentColor:"#e6821e" }}/>
                          <span style={{ fontSize:12, color:"#666" }}>Book this service for multiple vehicles</span>
                        </label>
                      )}
                      {!bulkMode&&(
                        <select value={selectedVehicle} onChange={e=>setSelectedVehicle(e.target.value)} style={inp}>
                          <option value="">Select a vehicle</option>
                          {vehicles.map(v=><option key={v.id} value={v.id}>{v.make} {v.model} {v.year} ΓÇö {v.license_plate}</option>)}
                        </select>
                      )}
                      {bulkMode&&(
                        <div style={{ marginBottom:10 }}>
                          {vehicles.map(v=>(
                            <label key={v.id} style={{ display:"flex", alignItems:"center", gap:8, padding:"6px 0", cursor:"pointer", fontSize:13 }}>
                              <input type="checkbox" checked={bulkVehicles.includes(v.id)} onChange={()=>{
                                setBulkVehicles(prev => prev.includes(v.id) ? prev.filter(id=>id!==v.id) : [...prev, v.id])
                              }} style={{ accentColor:"#e6821e" }}/>
                              <span>{v.make} {v.model} {v.year} ΓÇö {v.license_plate}</span>
                            </label>
                          ))}
                          {bulkVehicles.length>0&&(
                            <div style={{ marginTop:6, fontSize:11, color:"#1d9e75" }}>
                              {bulkVehicles.length} vehicle{bulkVehicles.length!==1?"s":""} selected ΓÇö {bulkVehicles.length} separate booking{bulkVehicles.length!==1?"s":""} will be created
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                  )}

                  <div style={{ marginBottom:10 }}>
                    <label style={lbl}>Payment method</label>
                    <select value={bookForm.payment_method} onChange={e=>setBookForm(f=>({...f,payment_method:e.target.value}))} style={inp}>
                      <option value="mpesa">M-Pesa</option>
                      
                    </select>
                  </div>

                  <div style={{ marginBottom:14 }}>
                    <div style={{ marginBottom:10 }}>
                    <label style={lbl}>Describe your problem <span style={{ color:"#e24b4a" }}>*</span></label>
                    <textarea value={bookForm.problem_description} onChange={e=>setBookForm(f=>({...f,problem_description:e.target.value}))}
                      placeholder="e.g. My car makes a grinding noise when braking, brake pads may need replacing..."
                      style={{ ...inp, resize:"vertical", minHeight:70 }} required/>
                  </div>
                  {(s.category==="shop_premium"||s.category==="go_service")&&(
                    <label style={{ display:"flex", alignItems:"center", gap:8, marginBottom:10, cursor:"pointer" }}>
                      <input type="checkbox" checked={bookForm.parts_needed} onChange={e=>setBookForm(f=>({...f,parts_needed:e.target.checked}))} style={{ accentColor:"#e6821e" }}/>
                      <span style={{ fontSize:12, color:"#666" }}>I think parts/materials may be needed</span>
                    </label>
                  )}
                  {bookForm.parts_needed&&(
                    <div style={{ marginBottom:10 }}>
                      <label style={lbl}>What parts might be needed?</label>
                      <input style={inp} placeholder="e.g. brake pads, battery, oil filter..." value={bookForm.parts_description} onChange={e=>setBookForm(f=>({...f,parts_description:e.target.value}))}/>
                    </div>
                  )}
                  <label style={lbl}>Additional notes {s.category==="shop_premium"?"(include your address)":""}</label>
                    <textarea value={bookForm.notes} onChange={e=>setBookForm(f=>({...f,notes:e.target.value}))} placeholder={s.category==="shop_premium"?"Your home/office address...":s.category==="go_service"?"Your exact location and emergency details...":"Any special instructions..."} style={{ ...inp, resize:"vertical", minHeight:60 }}/>
                  </div>

                  {s.category!=="go_service"&&(<>
                    <label style={{ display:"flex", alignItems:"center", gap:8, marginBottom:14, cursor:"pointer" }}>
                      <input type="checkbox" checked={bookForm.is_concierge} onChange={e=>setBookForm(f=>({...f,is_concierge:e.target.checked}))} style={{ accentColor:"#e6821e" }}/>
                      <span style={{ fontSize:12, color:"#666" }}>Add concierge driver (pick up & drop off my car) ΓÇö extra {Math.round((conciergeMultiplier-1)*100)}%</span>
                    </label>
                    {bookForm.is_concierge&&(
                      <div style={{ marginBottom:8 }}>
                        <label style={lbl}>Pickup location (your home/office address) <span style={{ color:"#e24b4a" }}>*</span></label>
                        <div style={{ display:"flex", gap:6 }}>
                          <input value={bookForm.concierge_location} onChange={e=>setBookForm(f=>({...f,concierge_location:e.target.value}))}
                            placeholder="Enter your home or office address..."
                            style={{ ...inp, flex:1, marginBottom:0 }} required/>
                          <button type="button" onClick={async()=>{
                            try {
                              const { getCurrentPosition } = await import("../../lib/geolocation")
                              const pos = await getCurrentPosition()
                              const res = await fetch(`https://nominatim.openstreetmap.org/reverse?lat=${pos.latitude}&lon=${pos.longitude}&format=json`)
                              const data = await res.json()
                              setBookForm(f=>({...f, concierge_location:data.display_name||"Location detected"})); setCustomerLocation({ lat:pos.latitude, lng:pos.longitude, address:data.display_name||"" })
                            } catch(err) { toast.error("Could not detect location") }
                          }} style={{ background:"#e6821e", border:"none", borderRadius:8, color:"#fff", fontSize:11, padding:"0 12px", cursor:"pointer", flexShrink:0 }}>
                            <LocationIcon size={13} color="currentColor"/> Detect
                          </button>
                        </div>
                      </div>
                    )}
                  </>)}

                  <div style={{ marginBottom:14 }}>
                    <label style={lbl}>Voucher code (optional)</label>
                    <div style={{ display:"flex", gap:6 }}>
                      <input value={voucherCode} onChange={e=>setVoucherCode(e.target.value.toUpperCase())}
                        placeholder="CCC-XXXX-XXXX-XXXX"
                        style={{ ...inp, flex:1, marginBottom:0 }}/>
                      <button type="button" onClick={validateVoucher} disabled={voucherLoading||!voucherCode.trim()}
                        style={{ background:"#1d9e75", border:"none", borderRadius:8, color:"#fff", fontSize:12, padding:"0 14px", cursor:"pointer", flexShrink:0 }}>
                        {voucherLoading?"...":"Apply"}
                      </button>
                    </div>
                    {voucherData&&(
                      <div style={{ marginTop:6, background:"#f0fff8", border:"1px solid #bbf7d0", borderRadius:8, padding:"0.5rem 0.75rem", display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                        <div style={{ fontSize:11, color:"#1d9e75" }}>Γ£à Voucher applied ΓÇö KES {Number(voucherData.value).toLocaleString()} off</div>
                        <button type="button" onClick={()=>{ setVoucherData(null); setVoucherCode("") }} style={{ background:"none", border:"none", color:"#e24b4a", cursor:"pointer", fontSize:12 }}>├ù</button>
                      </div>
                    )}
                  </div>
                  <div style={{ marginBottom:14 }}>
                    <label style={lbl}>Promo code (optional)</label>
                    <div style={{ display:"flex", gap:6 }}>
                      <input value={promoCode} onChange={e=>setPromoCode(e.target.value.toUpperCase())}
                        placeholder="SAVE10"
                        style={{ ...inp, flex:1, marginBottom:0 }}/>
                      <button type="button" onClick={()=>validatePromo(Number(s.price)*(bookForm.is_concierge?conciergeMultiplier:1))} disabled={promoLoading||!promoCode.trim()}
                        style={{ background:"#e6821e", border:"none", borderRadius:8, color:"#fff", fontSize:12, padding:"0 14px", cursor:"pointer", flexShrink:0 }}>
                        {promoLoading?"...":"Apply"}
                      </button>
                    </div>
                    {promoData&&(
                      <div style={{ marginTop:6, background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:8, padding:"0.5rem 0.75rem", display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                        <div style={{ fontSize:11, color:"#e6821e" }}>Γ£à Promo {promoData.code} applied ΓÇö KES {Number(promoData.discount).toLocaleString()} off</div>
                        <button type="button" onClick={()=>{ setPromoData(null); setPromoCode("") }} style={{ background:"none", border:"none", color:"#e24b4a", cursor:"pointer", fontSize:12 }}>├ù</button>
                      </div>
                    )}
                  </div>

                  <div style={{ background:"#ffffff", borderRadius:8, padding:"0.75rem", marginBottom:14 }}>
                    <div style={{ fontSize:11, color:"#777777", marginBottom:4 }}>Booking summary</div>
                    <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, color:"#555555", marginBottom:2 }}>
                      <span>{s.name}</span><span>KES {Number(s.price).toLocaleString()}</span>
                    </div>
                    {bookForm.is_concierge&&(
                      <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, color:"#555555", marginBottom:2 }}>
                        <span>Concierge fee</span><span>KES {(Number(s.price)*(conciergeMultiplier-1)).toFixed(0)}</span>
                      </div>
                    )}
                    <div style={{ height:1, background:"#f0f0f0", margin:"6px 0" }}/>
                    {voucherData&&(
                      <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, color:"#1d9e75", marginBottom:2 }}>
                        <span>Voucher discount</span><span>- KES {Number(voucherData.value).toLocaleString()}</span>
                      </div>
                    )}
                    {promoData&&(
                      <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, color:"#e6821e", marginBottom:2 }}>
                        <span>Promo discount</span><span>- KES {Number(promoData.discount).toLocaleString()}</span>
                      </div>
                    )}
                    <div style={{ display:"flex", justifyContent:"space-between", fontSize:13, color:"#e6821e", fontWeight:700 }}>
                      <span>Total</span>
                      <span>KES {Math.max(0,(Number(s.price)*(bookForm.is_concierge?conciergeMultiplier:1))-(voucherData?Number(voucherData.value):0)-(promoData?Number(promoData.discount):0)).toFixed(0)}</span>
                    </div>
                  </div>

                                        {/* Share my location - Fix #20 */}
                      {!bookForm.is_concierge&&(
                        <div style={{ marginBottom:12, background:"#f8f8f8", borderRadius:10, padding:"0.75rem" }}>
                          <div style={{ fontSize:12, fontWeight:700, color:"#555", marginBottom:6, display:"flex", alignItems:"center", gap:4 }}><LocationIcon size={12} color="#555"/> Your location (optional)</div>
                          {customerLocation.lat?(
                            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                              <div style={{ fontSize:11, color:"#1d9e75", flex:1, marginRight:8 }}>Γ£ô {customerLocation.address?.substring(0,60)}...</div>
                              <button type="button" onClick={()=>setCustomerLocation({lat:null,lng:null,address:""})}
                                style={{ background:"none", border:"none", color:"#e24b4a", fontSize:11, cursor:"pointer" }}>Clear</button>
                            </div>
                          ):(
                            <button type="button" onClick={detectCustomerLocation} disabled={detectingLocation}
                              style={{ width:"100%", background:detectingLocation?"#888":"#1d9e75", border:"none", borderRadius:8, color:"#fff", fontSize:12, fontWeight:700, padding:"8px", cursor:"pointer" }}>
                              {detectingLocation?"Detecting...":<><LocationIcon size={13} color="currentColor"/> Share my location with provider</>}
                            </button>
                          )}
                        </div>
                      )}

                      <div style={{ display:"flex", gap:8 }}>
                    <button type="submit" disabled={bookingLoading}
                      style={{ background:bookingLoading?"#ccc":"#e6821e", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px 24px", cursor:bookingLoading?"not-allowed":"pointer" }}>
                      {bookingLoading?"Booking...":"Confirm booking"}
                    </button>
                    <button type="button" onClick={()=>setBooking(null)}
                      style={{ background:"none", border:"1px solid #dddddd", borderRadius:9, color:"#666", fontSize:13, padding:"11px 16px", cursor:"pointer", fontFamily:"'DM Sans',sans-serif" }}>
                      Cancel
                    </button>
                  </div>
                </form>
              </div>
            )}
          </div>
        )
      })}

      {/* M-Pesa Payment Modal */}
      {showPayment&&pendingBooking&&(
        <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.8)", zIndex:200, display:"flex", alignItems:"center", justifyContent:"center", padding:"1rem" }}>
          <div style={{ width:"100%", maxWidth:420 }}>
            <DarajaPayment
              amount={pendingBooking.amount}
              bookingId={pendingBooking.id}
              customerEmail={user?.email}
              customerPhone={profile?.phone}
              customerName={profile?.first_name+" "+profile?.last_name}
              onSuccess={async ()=>{
              try {
                if (pendingBooking?.id) {
                  // Update booking payment status
                  await supabase.from("bookings").update({
                    payment_status: "paid",
                    status: "confirmed"
                  }).eq("id", pendingBooking.id)

                  // Fetch booking to get provider_id
                  const { data: bk } = await supabase.from("bookings")
                    .select("provider_id, service_name, booking_number")
                    .eq("id", pendingBooking.id).single()

                  // Notify provider
                  if (bk?.provider_id) {
                    await supabase.from("notifications").insert({
                      user_id: bk.provider_id,
                      type: "booking",
                      title: "New booking received! ≡ƒÄë",
                      message: `A customer has booked ${bk.service_name} (#${bk.booking_number}). Payment confirmed.`,
                      data: { booking_id: pendingBooking.id }
                    })
                  }

                  // Notify customer
                  await supabase.from("notifications").insert({
                    user_id: user.id,
                    type: "booking",
                    title: "Booking confirmed! Γ£à",
                    message: `Your booking #${bk?.booking_number} has been confirmed. The provider will be in touch shortly.`,
                    data: { booking_id: pendingBooking.id }
                  })
                }
                toast.success("Payment successful! Booking confirmed ≡ƒÄë")
        // Send push notifications
        if(bk?.provider_id) pushNotify.newBooking(bk.provider_id, profile?.first_name||"Customer", bk.service_name)
        pushNotify.bookingConfirmed(user.id, bk?.booking_number, bk?.service_name)
              } catch(e) {
                console.error("onSuccess error:", e)
                toast.success("Payment received! Your booking is being confirmed.")
              }
              setShowPayment(false); setPendingBooking(null)
            }}
              onCancel={async ()=>{ 
              if (pendingBooking?.id) {
                await supabase.from("bookings").delete().eq("id", pendingBooking.id).eq("payment_status","pending")
                toast("Booking cancelled", { icon:"Γä╣∩╕Å" })
              }
              setShowPayment(false); setPendingBooking(null) }}
            />
          </div>
        </div>
      )}
    </div>
  )
}

import { useEffect, useState, useRef } from "react"
import { supabase } from "../../lib/supabase"
import { BookingsIcon, PaymentsIcon, VehicleIcon, OrdersIcon, ProfileIcon, ServicesIcon, SettingsIcon, ChatIcon, TicketIcon, NoteIcon, PenIcon, QuestionIcon } from "../../lib/cccIcons"

import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const CATEGORIES = [
  { k:"booking", l:"Service Booking", icon:"bookings" },
  { k:"payment", l:"Payment Issue", icon:"payments" },
  { k:"driver", l:"Driver Complaint", icon:"vehicle" },
  { k:"parts", l:"Parts Order", icon:"orders" },
  { k:"account", l:"Account Issue", icon:"profile" },
  { k:"provider", l:"Provider Issue", icon:"services" },
  { k:"technical", l:"Technical Problem", icon:"settings" },
  { k:"other", l:"Other", icon:"chat" },
]

const PRIORITIES = [
  { k:"low", l:"Low", color:"#1d9e75" },
  { k:"medium", l:"Medium", color:"#e6821e" },
  { k:"high", l:"High", color:"#e24b4a" },
]

const STATUS_COLOR = { open:"#e6821e", in_progress:"#378add", resolved:"#1d9e75", closed:"#888" }

const FAQ = [
  { q:"How do I cancel a booking?", a:"Go to My Bookings ΓåÆ tap the booking ΓåÆ tap Cancel. Cancellations within 24hrs of the appointment may incur a fee." },
  { q:"When will I get my refund?", a:"Approved refunds are processed within 7 business days to your original payment method." },
  { q:"How do I track my parts order?", a:"Go to Marketplace ΓåÆ My Orders ΓåÆ tap your order to see delivery status and driver location." },
  { q:"My driver did not show up ΓÇö what do I do?", a:"Tap Rate & Review on the booking and select Driver no-show. Our team will investigate and issue a service voucher." },
  { q:"How do I update my vehicle details?", a:"Go to Profile ΓåÆ My Vehicles ΓåÆ tap Edit on the vehicle you want to update." },
  { q:"How do I link a vehicle tracker?", a:"Go to Profile ΓåÆ My Vehicles ΓåÆ tap Link Tracker on the vehicle. Enter your tracker provider API key." },
]

export default function CustomerSupport() {
  const { user, profile } = useAuth()
  const isMobile = useIsMobile()
  const [tickets, setTickets] = useState([])
  const [selected, setSelected] = useState(null)
  const [messages, setMessages] = useState([])
  const [newMessage, setNewMessage] = useState("")
  const [loading, setLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const [sending, setSending] = useState(false)
  const [tab, setTab] = useState("faq")
  const [expandedFaq, setExpandedFaq] = useState(null)
  const [form, setForm] = useState({ subject:"", category:"booking", priority:"medium", message:"" })
  const messagesEndRef = useRef(null)

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("customer-support-"+user.id)
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"support_messages" },
        payload => {
          if (selected && payload.new.ticket_id === selected.id) {
            setMessages(m => [...m, payload.new])
            setTimeout(() => messagesEndRef.current?.scrollIntoView({ behavior:"smooth" }), 100)
          }
          load()
        })
      .on("postgres_changes", { event:"UPDATE", schema:"public", table:"support_tickets", filter:`customer_id=eq.${user.id}` },
        payload => {
          setTickets(t => t.map(tk => tk.id === payload.new.id ? {...tk,...payload.new} : tk))
          if (selected?.id === payload.new.id) setSelected(s => ({...s,...payload.new}))
        })
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user, selected?.id])

  useEffect(() => { if (selected) loadMessages(selected.id) }, [selected?.id])

  async function load() {
    const { data } = await supabase.from("support_tickets")
      .select("*").eq("customer_id", user.id)
      .order("updated_at", { ascending:false })
    setTickets(data||[])
    setLoading(false)
  }

  async function loadMessages(ticketId) {
    const { data } = await supabase.from("support_messages")
      .select("*, profiles!support_messages_sender_id_fkey(first_name,last_name,role)")
      .eq("ticket_id", ticketId).order("created_at", { ascending:true })
    setMessages(data||[])
    setTimeout(() => messagesEndRef.current?.scrollIntoView({ behavior:"smooth" }), 100)
  }

  async function submitTicket(e) {
    e.preventDefault()
    if (!form.subject.trim() || !form.message.trim()) return toast.error("Please fill all fields")
    setSubmitting(true)
    try {
      const { data: ticket, error } = await supabase.from("support_tickets").insert({
        customer_id: user.id, subject: form.subject, category: form.category, priority: form.priority,
      }).select().single()
      if (error) throw error
      await supabase.from("support_messages").insert({ ticket_id: ticket.id, sender_id: user.id, message: form.message, is_staff: false })
      await supabase.from("notifications").insert({ user_id: user.id, title: "Support ticket created Γ£à", message: "Ticket "+ticket.ticket_number+" submitted. We will respond within 24 hours.", type: "info" })
      const { data: admins } = await supabase.from("profiles").select("id").eq("role","admin")
      for (const admin of (admins||[])) {
        await supabase.from("notifications").insert({ user_id: admin.id, title: "New support ticket ≡ƒÄ½"+(form.priority==="high"?" ≡ƒö┤ HIGH":""), message: (profile?.first_name||"")+" "+(profile?.last_name||"")+" ΓÇö "+form.subject+" ["+form.category+"]", type: form.priority==="high"?"error":"info" })
      }
      toast.success("Ticket "+ticket.ticket_number+" created! We will respond within 24 hours.")
      setForm({ subject:"", category:"booking", priority:"medium", message:"" })
      setTab("tickets"); load()
    } catch(err) { toast.error(err.message) }
    finally { setSubmitting(false) }
  }

  async function sendMessage(e) {
    e.preventDefault()
    if (!newMessage.trim() || !selected) return
    setSending(true)
    const { error } = await supabase.from("support_messages").insert({ ticket_id: selected.id, sender_id: user.id, message: newMessage.trim(), is_staff: false })
    if (!error) {
      const { data: admins } = await supabase.from("profiles").select("id").eq("role","admin")
      for (const admin of (admins||[])) {
        await supabase.from("notifications").insert({ user_id: admin.id, title: "Support reply from customer ≡ƒÆ¼", message: (profile?.first_name||"Customer")+" replied on ticket #"+selected.ticket_number, type:"info" })
      }
    }
    if (error) { toast.error(error.message); setSending(false); return }
    setNewMessage(""); setSending(false)
  }

  async function closeTicket(id) {
    await supabase.from("support_tickets").update({ status:"closed", updated_at:new Date().toISOString() }).eq("id", id)
    toast.success("Ticket closed"); setSelected(null); load()
  }

  async function reopenTicket(id) {
    await supabase.from("support_tickets").update({ status:"open", updated_at:new Date().toISOString() }).eq("id", id)
    toast.success("Ticket reopened"); load()
  }

  const openCount = tickets.filter(t=>t.status==="open"||t.status==="in_progress").length

  if (selected) return (
    <div style={{ display:"flex", flexDirection:"column", height:isMobile?"calc(100vh - 120px)":"calc(100vh - 140px)" }}>
      <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:"1rem", flexShrink:0 }}>
        <button onClick={()=>setSelected(null)} style={{ background:"none", border:"none", color:"#e6821e", cursor:"pointer", fontSize:13, padding:0 }}>ΓåÉ Back</button>
        <div style={{ flex:1 }}>
          <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:800, color:"#000" }}>{selected.subject}</div>
          <div style={{ display:"flex", gap:6, alignItems:"center", marginTop:2 }}>
            <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:(STATUS_COLOR[selected.status]||"#888")+"20", color:STATUS_COLOR[selected.status]||"#888", fontWeight:600 }}>{selected.status?.replace("_"," ").toUpperCase()}</span>
            <span style={{ fontSize:10, color:"#888" }}>#{selected.ticket_number}</span>
          </div>
        </div>
        {(selected.status==="open"||selected.status==="in_progress")&&(
          <button onClick={()=>closeTicket(selected.id)} style={{ background:"#f5f5f5", border:"none", borderRadius:7, color:"#555", fontSize:11, padding:"6px 10px", cursor:"pointer" }}>Close</button>
        )}
        {(selected.status==="closed"||selected.status==="resolved")&&(
          <button onClick={()=>reopenTicket(selected.id)} style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:7, color:"#e6821e", fontSize:11, padding:"6px 10px", cursor:"pointer" }}>Reopen</button>
        )}
      </div>
      <div style={{ flex:1, overflowY:"auto", paddingBottom:"0.5rem", marginBottom:"0.5rem" }}>
        {messages.map(m => {
          const isMe = m.sender_id === user.id
          const isStaff = m.is_staff
          return (
            <div key={m.id} style={{ display:"flex", justifyContent:isMe?"flex-end":"flex-start", marginBottom:8 }}>
              <div style={{ maxWidth:"80%", background:isMe?"#e6821e":isStaff?"#eff6ff":"#f5f5f5", borderRadius:isMe?"12px 12px 4px 12px":"12px 12px 12px 4px", padding:"10px 14px" }}>
                {isStaff&&<div style={{ fontSize:10, color:"#378add", fontWeight:600, marginBottom:4 }}>≡ƒÄ½ CCC Support</div>}
                <div style={{ fontSize:13, color:isMe?"#fff":"#000", lineHeight:1.5 }}>{m.message}</div>
                <div style={{ fontSize:10, color:isMe?"rgba(255,255,255,0.7)":"#aaa", marginTop:4, textAlign:"right" }}>{new Date(m.created_at).toLocaleTimeString()}</div>
              </div>
            </div>
          )
        })}
        <div ref={messagesEndRef}/>
      </div>
      {(selected.status==="open"||selected.status==="in_progress") ? (
        <form onSubmit={sendMessage} style={{ display:"flex", gap:8, flexShrink:0 }}>
          <input value={newMessage} onChange={e=>setNewMessage(e.target.value)} placeholder="Type your message..."
            style={{ flex:1, background:"#f5f5f5", border:"1px solid #e0e0e0", borderRadius:10, padding:"10px 14px", fontSize:13, outline:"none" }}/>
          <button type="submit" disabled={sending||!newMessage.trim()} style={{ background:"#e6821e", border:"none", borderRadius:10, color:"#fff", padding:"10px 16px", cursor:"pointer", fontSize:13, fontWeight:700 }}>
            {sending?"...":"Send"}
          </button>
        </form>
      ) : (
        <div style={{ textAlign:"center", fontSize:12, color:"#888", padding:"0.75rem", background:"#f5f5f5", borderRadius:10 }}>
          This ticket is {selected.status}. Reopen to send more messages.
        </div>
      )}
    </div>
  )

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:"#000", marginBottom:"1rem" }}><><TicketIcon size={18} color="#e6821e"/> Support Center</></div>
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:8, marginBottom:"1rem" }}>
        {[
          { label:"Open tickets", value:openCount, color:"#e6821e" },
          { label:"Total tickets", value:tickets.length, color:"#378add" },
          { label:"Response time", value:"< 24h", color:"#1d9e75" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.75rem 0.5rem", textAlign:"center", border:"1px solid #eee" }}>
            <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>
      <div style={{ display:"flex", gap:6, marginBottom:"1rem" }}>
        {[{ k:"faq", l:"FAQ" },{ k:"new", l:"New ticket" },{ k:"tickets", l:"My tickets"+(openCount>0?" ("+openCount+")":"") }].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{ flex:1, padding:"8px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#e6821e":"#f0f0f0", color:tab===t.k?"#fff":"#555", fontWeight:tab===t.k?700:400 }}>
            {t.k==="faq"?<><QuestionIcon size={14} color="currentColor"/> {t.l}</>:t.k==="new"?<><PenIcon size={14} color="currentColor"/> {t.l}</>:<><NoteIcon size={14} color="currentColor"/> {t.l}</>}
          </button>
        ))}
      </div>
      {tab==="faq"&&(
        <div>
          <div style={{ fontSize:12, color:"#888", marginBottom:"1rem" }}>Common questions ΓÇö tap to expand</div>
          {FAQ.map((f,i)=>(
            <div key={i} style={{ background:"#f8f8f8", borderRadius:10, marginBottom:8, overflow:"hidden", border:"1px solid #eee" }}>
              <button onClick={()=>setExpandedFaq(expandedFaq===i?null:i)}
                style={{ width:"100%", background:"none", border:"none", padding:"12px", textAlign:"left", cursor:"pointer", display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                <span style={{ fontSize:13, fontWeight:600, color:"#000" }}>{f.q}</span>
                <span style={{ color:"#e6821e", fontSize:16 }}>{expandedFaq===i?"ΓêÆ":"+"}</span>
              </button>
              {expandedFaq===i&&(
                <div style={{ padding:"0 12px 12px", fontSize:12, color:"#555", lineHeight:1.7, borderTop:"1px solid #eee" }}>{f.a}</div>
              )}
            </div>
          ))}
          <div style={{ marginTop:"1rem", textAlign:"center" }}>
            <div style={{ fontSize:12, color:"#888", marginBottom:8 }}>Didnt find your answer?</div>
            <button onClick={()=>setTab("new")} style={{ background:"#e6821e", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"12px 24px", cursor:"pointer" }}>
              <><PenIcon size={14} color="#e6821e"/> Create a support ticket</>
            </button>
          </div>
        </div>
      )}
      {tab==="new"&&(
        <form onSubmit={submitTicket}>
          <label style={{ fontSize:11, color:"#666", display:"block", marginBottom:4, fontWeight:600 }}>Category</label>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6, marginBottom:12 }}>
            {CATEGORIES.map(c=>(
              <button type="button" key={c.k} onClick={()=>setForm(f=>({...f,category:c.k}))}
                style={{ padding:"8px", borderRadius:8, border:"1px solid "+(form.category===c.k?"#e6821e":"#e0e0e0"), background:form.category===c.k?"#fff8f0":"#f8f8f8", color:form.category===c.k?"#e6821e":"#555", fontSize:12, cursor:"pointer", display:"flex", alignItems:"center", gap:6 }}>
                <span>{c.icon}</span><span style={{ fontWeight:form.category===c.k?700:400 }}>{c.l}</span>
              </button>
            ))}
          </div>
          <label style={{ fontSize:11, color:"#666", display:"block", marginBottom:4, fontWeight:600 }}>Priority</label>
          <div style={{ display:"flex", gap:6, marginBottom:12 }}>
            {PRIORITIES.map(p=>(
              <button type="button" key={p.k} onClick={()=>setForm(f=>({...f,priority:p.k}))}
                style={{ flex:1, padding:"8px", borderRadius:8, border:"1px solid "+(form.priority===p.k?p.color:"#e0e0e0"), background:form.priority===p.k?p.color+"15":"#f8f8f8", color:form.priority===p.k?p.color:"#555", fontSize:12, cursor:"pointer", fontWeight:form.priority===p.k?700:400 }}>
                {p.l}
              </button>
            ))}
          </div>
          <label style={{ fontSize:11, color:"#666", display:"block", marginBottom:4, fontWeight:600 }}>Subject *</label>
          <input value={form.subject} onChange={e=>setForm(f=>({...f,subject:e.target.value}))} placeholder="Brief description of your issue"
            style={{ width:"100%", background:"#f5f5f5", border:"1px solid #e0e0e0", borderRadius:8, padding:"10px 12px", fontSize:13, marginBottom:12, outline:"none", boxSizing:"border-box" }} required/>
          <label style={{ fontSize:11, color:"#666", display:"block", marginBottom:4, fontWeight:600 }}>Message *</label>
          <textarea value={form.message} onChange={e=>setForm(f=>({...f,message:e.target.value}))}
            placeholder="Describe your issue in detail. Include booking numbers, dates, or any relevant information." rows={5}
            style={{ width:"100%", background:"#f5f5f5", border:"1px solid #e0e0e0", borderRadius:8, padding:"10px 12px", fontSize:13, marginBottom:16, outline:"none", resize:"vertical", boxSizing:"border-box" }} required/>
          <div style={{ background:"#f0fdf4", border:"1px solid #1d9e7530", borderRadius:8, padding:"0.75rem", marginBottom:16, fontSize:12, color:"#555" }}>
            ΓÅ▒∩╕Å Our support team typically responds within 24 hours on business days.
          </div>
          <button type="submit" disabled={submitting}
            style={{ width:"100%", background:submitting?"#ccc":"#e6821e", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700, padding:"14px", cursor:submitting?"not-allowed":"pointer" }}>
            {submitting?"Submitting...":"≡ƒÄ½ Submit ticket"}
          </button>
        </form>
      )}
      {tab==="tickets"&&(
        <div>
          {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
          {!loading&&tickets.length===0&&(
            <div style={{ textAlign:"center", padding:"3rem", color:"#888" }}>
              <div style={{ fontSize:32, marginBottom:10 }}>≡ƒÄ½</div>
              No support tickets yet
              <div style={{ marginTop:"1rem" }}>
                <button onClick={()=>setTab("new")} style={{ background:"#e6821e", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"10px 20px", cursor:"pointer" }}>
                  Create your first ticket
                </button>
              </div>
            </div>
          )}
          {tickets.map(t=>(
            <div key={t.id} onClick={()=>setSelected(t)}
              style={{ background:"#f8f8f8", border:`1px solid ${STATUS_COLOR[t.status]||"#eee"}30`, borderRadius:10, padding:"1rem", marginBottom:8, cursor:"pointer" }}
              onMouseEnter={e=>e.currentTarget.style.background="#f0f0f0"}
              onMouseLeave={e=>e.currentTarget.style.background="#f8f8f8"}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div style={{ flex:1, minWidth:0, marginRight:8 }}>
                  <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#000", marginBottom:2 }}>{t.subject}</div>
                  <div style={{ fontSize:11, color:"#888" }}>#{t.ticket_number} ┬╖ {CATEGORIES.find(c=>c.k===t.category)?.icon} {t.category}</div>
                  <div style={{ fontSize:11, color:"#aaa", marginTop:2 }}>{new Date(t.updated_at||t.created_at).toLocaleDateString()}</div>
                </div>
                <div style={{ textAlign:"right", flexShrink:0 }}>
                  <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:(STATUS_COLOR[t.status]||"#888")+"20", color:STATUS_COLOR[t.status]||"#888", fontWeight:600, display:"block", marginBottom:4 }}>{t.status?.replace("_"," ")}</span>
                  <span style={{ fontSize:10, padding:"2px 6px", borderRadius:6, background:(PRIORITIES.find(p=>p.k===t.priority)?.color||"#888")+"20", color:PRIORITIES.find(p=>p.k===t.priority)?.color||"#888" }}>{t.priority}</span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { useEffect, useState, useRef } from "react"
import { supabase } from "../../lib/supabase"
import { getCurrentPosition } from "../../lib/geolocation"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const CONCIERGE_STEPS = [
  { key:"accepted", label:"Driver assigned", color:"#378add" },
  { key:"pickup", label:"Driver at pickup", color:"#e6821e" },
  { key:"in_transit", label:"En route to provider", color:"#8b5cf6" },
  { key:"at_provider", label:"At service provider", color:"#1d9e75" },
  { key:"return_transit", label:"Returning your car", color:"#8b5cf6" },
  { key:"dropoff", label:"Driver at dropoff", color:"#e6821e" },
  { key:"completed", label:"Delivered", color:"#1d9e75" },
]

export default function CustomerTracking() {
  const { user } = useAuth()
  const isMobile = useIsMobile()
  const [activeBookings, setActiveBookings] = useState([])
  const [activeOrders, setActiveOrders] = useState([])
  const [trackingType, setTrackingType] = useState("booking") // "booking" or "order"
  const [selected, setSelected] = useState(null)
  const [driver, setDriver] = useState(null)
  const [mechanic, setMechanic] = useState(null)
  const [loading, setLoading] = useState(true)
  const mapRef = useRef(null)
  const mapInstanceRef = useRef(null)
  const driverMarkerRef = useRef(null)
  const mechanicMarkerRef = useRef(null)
  const trackerMarkerRef = useRef(null)
  const [trackerLocation, setTrackerLocation] = useState(null)
  const [divergenceAlert, setDivergenceAlert] = useState(false)

  useEffect(() => {
    if (!user) return
    load()
    // Realtime order delivery updates
    const sub = supabase.channel("customer-delivery-updates")
      .on("postgres_changes", { event:"UPDATE", schema:"public", table:"orders", filter:`customer_id=eq.${user.id}` },
        payload => {
          const status = payload.new.delivery_status
          if (status==="picked_up") toast("≡ƒôª Driver picked up your order!", { icon:"≡ƒÜÜ", duration:8000 })
          if (status==="delivered") toast.success("Γ£à Order delivered! Please confirm receipt.")
          load()
        })
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  useEffect(() => {
    if (!selected) return
    if (selected.driver_id) loadDriver(selected)
    if (selected.delivery_driver_id) loadOrderDriver(selected)
    if (selected.assigned_mechanic_id) loadMechanic(selected)
    if (selected.vehicle_id) loadTracker(selected)
    // Live update every 10 seconds
    const interval = setInterval(() => {
      if (selected.driver_id) loadDriver(selected)
      if (selected.delivery_driver_id) loadOrderDriver(selected)
      if (selected.assigned_mechanic_id) loadMechanic(selected)
    }, 10000)

    const sub = supabase.channel(`tracking-${selected.id}`)
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"booking_location_logs", filter:`booking_id=eq.${selected.id}` },
        payload => {
          const lat = Number(payload.new.lat || payload.new.latitude)
          const lng = Number(payload.new.lng || payload.new.longitude)
          if (payload.new.source === "tracker") {
            setTrackerLocation(t => t ? {...t, last_lat:lat, last_lng:lng} : {last_lat:lat, last_lng:lng})
            if (trackerMarkerRef.current) trackerMarkerRef.current.setPosition({ lat, lng })
          } else {
            setDriver(d=>d?{...d,current_lat:lat,current_lng:lng}:d)
            if (driverMarkerRef.current) {
              driverMarkerRef.current.setPosition({ lat, lng })
              if (mapInstanceRef.current) mapInstanceRef.current.panTo({ lat, lng })
            }
          }
        })
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"mechanic_location_history", filter:`booking_id=eq.${selected.id}` },
        payload => {
          const { latitude, longitude } = payload.new
          setMechanic(m=>m?{...m,current_latitude:latitude,current_longitude:longitude}:m)
          if (mechanicMarkerRef.current) mechanicMarkerRef.current.setPosition({ lat: latitude, lng: longitude })
        })
      .on("postgres_changes", { event:"UPDATE", schema:"public", table:"bookings", filter:`id=eq.${selected.id}` },
        payload => setSelected(s=>({...s,...payload.new})))
      .subscribe()
    return () => { supabase.removeChannel(sub); clearInterval(interval) }
  }, [selected?.id])

  useEffect(() => {
    if (!selected || !mapRef.current) return
    if (mapInstanceRef.current) { mapInstanceRef.current.remove(); mapInstanceRef.current = null }

    function initGoogleMap() {
      if (!mapRef.current || !window.google?.maps?.Map) return
      const lat = driver?.current_lat || mechanic?.current_latitude || -1.2921
      const lng = driver?.current_lng || mechanic?.current_longitude || 36.8219
      const map = new window.google.maps.Map(mapRef.current, {
        center: { lat, lng },
        zoom: 15,
        mapTypeControl: true,
        streetViewControl: true,
        fullscreenControl: true,
        zoomControl: true,
        gestureHandling: "greedy",
        mapTypeId: "roadmap", mapId: "ccc_tracking_map"
      })

      if (mechanic?.current_latitude) {
        mechanicMarkerRef.current = new window.google.maps.Marker({
          position: { lat: mechanic.current_latitude, lng: mechanic.current_longitude },
          map,
          title: `Mechanic: ${mechanic.first_name} ${mechanic.last_name}`,
          icon: {
            url: "data:image/svg+xml;charset=UTF-8," + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 48 48"><circle cx="24" cy="24" r="22" fill="#1d9e75" stroke="white" stroke-width="3"/><text x="24" y="32" font-size="22" text-anchor="middle">≡ƒæ¿ΓÇì≡ƒöº</text></svg>'),
            scaledSize: new window.google.maps.Size(48, 48),
            anchor: new window.google.maps.Point(24, 24)
          }
        })
      }

      // Tracker/vehicle GPS marker
      if (trackerLocation?.last_lat) {
        trackerMarkerRef.current = new window.google.maps.Marker({
          position: { lat: Number(trackerLocation.last_lat), lng: Number(trackerLocation.last_lng) },
          map,
          title: "Vehicle tracker location",
          icon: {
            url: "data:image/svg+xml;charset=UTF-8," + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 48 48"><circle cx="24" cy="24" r="22" fill="#e6821e" stroke="white" stroke-width="3"/><text x="24" y="32" font-size="22" text-anchor="middle">≡ƒôí</text></svg>'),
            scaledSize: new window.google.maps.Size(48, 48),
            anchor: new window.google.maps.Point(24, 24)
          }
        })
      }

      // Provider/shop location marker
      const providerLat = selected?.provider?.latitude
      const providerLng = selected?.provider?.longitude
      if (providerLat && providerLng) {
        providerMarkerRef.current = new window.google.maps.Marker({
          position: { lat: Number(providerLat), lng: Number(providerLng) },
          map,
          title: selected?.provider?.business_name || "Service Provider",
          icon: {
            url: "data:image/svg+xml;charset=UTF-8," + encodeURIComponent('<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"48\" height=\"48\" viewBox=\"0 0 48 48\"><circle cx=\"24\" cy=\"24\" r=\"22\" fill=\"#1d9e75\" stroke=\"white\" stroke-width=\"3\"/><text x=\"24\" y=\"32\" font-size=\"22\" text-anchor=\"middle\">≡ƒöº</text></svg>'),
            scaledSize: new window.google.maps.Size(48, 48),
            anchor: new window.google.maps.Point(24, 24)
          }
        })
      }
      if (navigator.geolocation) {
        getCurrentPosition().then(pos => {
          new window.google.maps.Marker({
            position: { lat: pos.latitude, lng: pos.longitude },
            map,
            title: "Your location",
            icon: {
              url: "data:image/svg+xml;charset=UTF-8," + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="44" height="44" viewBox="0 0 44 44"><circle cx="22" cy="22" r="20" fill="#e6821e" stroke="white" stroke-width="3"/><text x="22" y="30" font-size="20" text-anchor="middle">≡ƒæñ</text></svg>'),
              scaledSize: new window.google.maps.Size(44, 44),
              anchor: new window.google.maps.Point(22, 22)
            }
          })
        })
      }
      mapInstanceRef.current = map
    }

    if (window.google?.maps) {
      initGoogleMap()
    } else {
      const existing = document.getElementById("google-maps-sdk")
      if (!existing) {
        const script = document.createElement("script")
        script.id = "google-maps-sdk"
        script.src = `https://maps.googleapis.com/maps/api/js?key=${import.meta.env.VITE_GOOGLE_MAPS_KEY}&libraries=marker,places&loading=async`
        script.onload = () => { setTimeout(initGoogleMap, 100) }
        document.head.appendChild(script)
      } else {
        setTimeout(initGoogleMap, 500)
      }
    }

    return () => { mapInstanceRef.current = null; driverMarkerRef.current = null; mechanicMarkerRef.current = null }
  }, [selected?.id])

  // Create/update the driver marker whenever driver location data changes - decoupled from
  // map creation itself, so a location that arrives after the map first builds still shows up
  useEffect(() => {
    if (!mapInstanceRef.current || !window.google?.maps?.Map || !driver?.current_lat) return
    const position = { lat: driver.current_lat, lng: driver.current_lng }
    if (driverMarkerRef.current) {
      driverMarkerRef.current.setPosition(position)
    } else {
      driverMarkerRef.current = new window.google.maps.Marker({
        position, map: mapInstanceRef.current,
        title: `Driver: ${driver.first_name} ${driver.last_name}`,
        icon: {
          url: "data:image/svg+xml;charset=UTF-8," + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 48 48"><circle cx="24" cy="24" r="22" fill="#378add" stroke="white" stroke-width="3"/><text x="24" y="32" font-size="22" text-anchor="middle">≡ƒÜù</text></svg>'),
          scaledSize: new window.google.maps.Size(48, 48),
          anchor: new window.google.maps.Point(24, 24)
        }
      })
      mapInstanceRef.current.panTo(position)
    }
  }, [driver?.current_lat, driver?.current_lng])

  async function load() {
    const [{ data: bks }, { data: ords }] = await Promise.all([
      supabase.from("bookings").select("*")
        .eq("customer_id", user.id)
        .not("status", "in", "(\"completed\",\"cancelled\")")
        .order("created_at", { ascending:false }),
      supabase.from("orders")
        .select("*, delivery_driver:profiles!orders_delivery_driver_id_fkey(first_name,last_name), provider:profiles!orders_provider_id_fkey(first_name,last_name,business_name,latitude,longitude,address,city)")
        .eq("customer_id", user.id)
        .not("status", "in", "(delivered,cancelled)")
        .not("delivery_driver_id", "is", null)
        .order("created_at", { ascending:false })
    ])
    setActiveBookings(bks||[])
    setActiveOrders(ords||[])
    setLoading(false)
  }

  async function loadDriver(booking) {
    if (!booking.driver_id) return
    const [{ data: prof }, { data: status }, { data: sensitive }] = await Promise.all([
      supabase.from("profiles").select("first_name,last_name").eq("id", booking.driver_id).single(),
      supabase.from("driver_status").select("current_lat,current_lng,is_online").eq("driver_id", booking.driver_id).maybeSingle(),
      supabase.from("profile_sensitive").select("phone").eq("id", booking.driver_id).maybeSingle(),
    ])
    setDriver({ ...prof, phone:sensitive?.phone, current_lat:status?.current_lat, current_lng:status?.current_lng, is_online:status?.is_online })
  }

  async function loadOrderDriver(order) {
    if (!order.delivery_driver_id) return
    const { data: status } = await supabase.from("driver_status").select("current_lat,current_lng,is_online").eq("driver_id", order.delivery_driver_id).maybeSingle()
    if (status) setDriver(d => d ? {...d, current_lat:status.current_lat, current_lng:status.current_lng} : d)
  }

  async function loadMechanic(booking) {
    if (!booking.assigned_mechanic_id) return
    const { data } = await supabase.from("mechanics").select("*").eq("id", booking.assigned_mechanic_id).single()
    setMechanic(data)
  }

  async function loadTracker(booking) {
    if (!booking.vehicle_id) return
    const { data } = await supabase.from("vehicle_trackers")
      .select("last_lat,last_lng,last_seen,provider,is_active")
      .eq("vehicle_id", booking.vehicle_id)
      .eq("is_active", true)
      .maybeSingle()
    if (data?.last_lat) {
      setTrackerLocation(data)
      // Check divergence vs driver
      if (driver?.current_lat && data.last_lat) {
        const R = 6371000
        const dLat = (data.last_lat - driver.current_lat) * Math.PI/180
        const dLng = (data.last_lng - driver.current_lng) * Math.PI/180
        const a = Math.sin(dLat/2)*Math.sin(dLat/2) + Math.cos(driver.current_lat*Math.PI/180)*Math.cos(data.last_lat*Math.PI/180)*Math.sin(dLng/2)*Math.sin(dLng/2)
        const dist = R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a))
        setDivergenceAlert(dist > 500)
      }
    }
  }

  const SC = { pending:"#e6821e", confirmed:"#378add", "in-progress":"#8b5cf6", completed:"#1d9e75", "driver-assigned":"#1d9e75" }

  if (selected) return (
    <div>
      <style>{`@keyframes ping { 0%{transform:scale(1);opacity:0.6} 100%{transform:scale(2.5);opacity:0} }`}</style>

      <button onClick={()=>{ mapInstanceRef.current = null; driverMarkerRef.current=null; mechanicMarkerRef.current=null; setSelected(null); setDriver(null); setMechanic(null); setTrackerLocation(null); setDivergenceAlert(false); trackerMarkerRef.current=null }}
        style={{ background:"none", border:"none", color:"#e6821e", cursor:"pointer", fontSize:13, marginBottom:"1rem", fontFamily:"'DM Sans',sans-serif", padding:0 }}>
        ΓåÉ Back to bookings
      </button>

      <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1rem", marginBottom:"1rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#000000", marginBottom:4 }}>{selected.service_name}</div>
        <div style={{ display:"flex", gap:10, flexWrap:"wrap", marginBottom:10 }}>
          <span style={{ fontSize:11, padding:"2px 8px", borderRadius:10, background:`${SC[selected.status]||"#888"}20`, color:SC[selected.status]||"#888" }}>{selected.status}</span>
          {selected.concierge_status&&selected.concierge_status!=="pending"&&<span style={{ fontSize:11, padding:"2px 8px", borderRadius:10, background:"#faf5ff", color:"#8b5cf6" }}>{selected.concierge_status?.replace(/_/g," ")}</span>}
          <span style={{ fontSize:11, color:"#777777" }}>#{selected.booking_number}</span>
        </div>

        {/* Concierge progress */}
        {(driver?.current_lat||mechanic?.current_latitude)&&(
          <div style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:8, padding:"0.75rem", marginBottom:10, display:"flex", justifyContent:"space-between", alignItems:"center" }}>
            <div style={{ display:"flex", alignItems:"center", gap:8 }}>
              <div style={{ width:8, height:8, borderRadius:"50%", background:"#1d9e75", boxShadow:"0 0 6px #1d9e75", animation:"ping 1.5s ease-out infinite" }}/>
              <span style={{ fontSize:12, color:"#1d9e75", fontWeight:600 }}>Live tracking active</span>
            </div>
            <span style={{ fontSize:11, color:"#777777" }}>Updates every 10s</span>
          </div>
        )}
        {divergenceAlert&&(
          <div style={{ background:"#fff5f5", border:"1px solid #e24b4a40", borderRadius:8, padding:"0.75rem", marginBottom:10, display:"flex", alignItems:"center", gap:8 }}>
            <span style={{ fontSize:18 }}>ΓÜá∩╕Å</span>
            <div>
              <div style={{ fontSize:12, color:"#e24b4a", fontWeight:700 }}>Vehicle location mismatch</div>
              <div style={{ fontSize:11, color:"#777777" }}>Driver and tracker GPS are more than 500m apart. Contact support if concerned.</div>
            </div>
          </div>
        )}
        {selected.is_concierge&&selected.concierge_status&&(
          <div style={{ marginBottom:12 }}>
            <div style={{ fontSize:11, color:"#777777", marginBottom:6 }}>Delivery progress</div>
            <div style={{ display:"flex", gap:4, flexWrap:"wrap" }}>
              {CONCIERGE_STEPS.map((step,i)=>{
                const currentIdx = CONCIERGE_STEPS.findIndex(s=>s.key===selected.concierge_status)
                const isDone = i <= currentIdx
                return (
                  <div key={step.key} style={{ fontSize:9, padding:"2px 6px", borderRadius:6, background:isDone?`${step.color}20`:"#ffffff", color:isDone?step.color:"#555555", border:`1px solid ${isDone?step.color+"30":"#f5f5f5"}` }}>
                    {step.label}
                  </div>
                )
              })}
            </div>
          </div>
        )}

        {/* Driver info */}
        {driver&&(
          <div style={{ background:"#ffffff", borderRadius:10, padding:"0.9rem", marginBottom:10 }}>
            <div style={{ fontSize:11, color:"#777777", marginBottom:6 }}>Your driver</div>
            <div style={{ display:"flex", alignItems:"center", gap:10 }}>
              <div style={{ width:40, height:40, borderRadius:"50%", background:"#eff6ff", border:"2px solid #378add40", display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#378add", flexShrink:0 }}>
                {driver.first_name?.[0]}{driver.last_name?.[0]}
              </div>
              <div>
                <div style={{ fontSize:13, fontWeight:600, color:"#000000" }}>{driver.first_name} {driver.last_name}</div>
                <div style={{ fontSize:11, color:"#777777" }}>Concierge Driver</div>
              </div>
              <div style={{ marginLeft:"auto", display:"flex", flexDirection:"column", alignItems:"flex-end", gap:6 }}>
                <div style={{ display:"flex", alignItems:"center", gap:5 }}>
                  <div style={{ width:7, height:7, borderRadius:"50%", background:driver.current_lat?"#378add":"#555", boxShadow:driver.current_lat?"0 0 6px #378add":"none" }}/>
                  <span style={{ fontSize:10, color:driver.current_lat?"#378add":"#555" }}>
                    {driver.current_lat?"Live":"No location"}
                  </span>
                </div>
                {driver.phone&&(
                  <a href={"tel:"+driver.phone} style={{ background:"#1d9e75", borderRadius:6, color:"#fff", fontSize:11, fontWeight:700, padding:"4px 10px", textDecoration:"none" }}>
                    ≡ƒô₧ Call
                  </a>
                )}
              </div>
            </div>
          </div>
        )}

        {/* Mechanic info */}
        {mechanic&&(
          <div style={{ background:"#ffffff", borderRadius:10, padding:"0.9rem", marginBottom:10 }}>
            <div style={{ fontSize:11, color:"#777777", marginBottom:6 }}>Your mechanic</div>
            <div style={{ display:"flex", alignItems:"center", gap:10 }}>
              <div style={{ width:40, height:40, borderRadius:"50%", background:"#f0fdf4", border:"2px solid #1d9e7540", display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#1d9e75", flexShrink:0 }}>
                {mechanic.first_name?.[0]}{mechanic.last_name?.[0]}
              </div>
              <div>
                <div style={{ fontSize:13, fontWeight:600, color:"#000000" }}>{mechanic.first_name} {mechanic.last_name}</div>
                <div style={{ fontSize:11, color:"#777777" }}>≡ƒöº {mechanic.specialization}</div>
                {mechanic.phone&&<div style={{ fontSize:11, color:"#777777" }}>≡ƒô₧ {mechanic.phone}</div>}
              </div>
              <div style={{ marginLeft:"auto" }}>
                <div style={{ display:"flex", alignItems:"center", gap:5 }}>
                  <div style={{ width:7, height:7, borderRadius:"50%", background:mechanic.current_latitude?"#1d9e75":"#555", boxShadow:mechanic.current_latitude?"0 0 6px #1d9e75":"none" }}/>
                  <span style={{ fontSize:10, color:mechanic.current_latitude?"#1d9e75":"#555" }}>
                    {mechanic.current_latitude?"Live":"No location"}
                  </span>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Map */}
        <div style={{ position:"relative", height:isMobile?260:350, borderRadius:10, overflow:"hidden", background:"#f5f5f5" }}>
          <div ref={mapRef} style={{ width:"100%", height:"100%" }}/>
          {!driver?.current_lat&&!mechanic?.current_latitude&&(
            <div style={{ position:"absolute", inset:0, display:"flex", alignItems:"center", justifyContent:"center", flexDirection:"column", gap:8, background:"#f5f5f5", pointerEvents:"none" }}>
              <div style={{ fontSize:32 }}>≡ƒù║∩╕Å</div>
              <div style={{ fontSize:12, color:"#777777" }}>Waiting for location...</div>
            </div>
          )}
        </div>

        {/* Map legend */}
        <div style={{ display:"flex", gap:12, marginTop:8, flexWrap:"wrap" }}>
          {driver&&<div style={{ display:"flex", alignItems:"center", gap:5 }}><span style={{ fontSize:14 }}>≡ƒÜù</span><span style={{ fontSize:10, color:"#777777" }}>Driver</span></div>}
          {mechanic&&<div style={{ display:"flex", alignItems:"center", gap:5 }}><span style={{ fontSize:14 }}>≡ƒæ¿ΓÇì≡ƒöº</span><span style={{ fontSize:10, color:"#777777" }}>Mechanic</span></div>}
          {trackerLocation&&<div style={{ display:"flex", alignItems:"center", gap:5 }}><span style={{ fontSize:14 }}>≡ƒôí</span><span style={{ fontSize:10, color:"#777777" }}>Tracker</span></div>}
          <div style={{ display:"flex", alignItems:"center", gap:5 }}><span style={{ fontSize:14 }}>≡ƒæñ</span><span style={{ fontSize:10, color:"#777777" }}>You</span></div>
        </div>
      </div>
    </div>
  )

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:18, fontWeight:800, color:"#000000", marginBottom:4 }}>Track your service</div>
      <div style={{ fontSize:12, color:"#777777", marginBottom:"1.25rem" }}>Live tracking for active bookings</div>

      {/* Tabs */}
      <div style={{ display:"flex", gap:6, marginBottom:"1rem" }}>
        <button onClick={()=>setTrackingType("booking")} style={{ flex:1, padding:"8px", borderRadius:8, border:"none", background:trackingType==="booking"?"#e6821e":"#f0f0f0", color:trackingType==="booking"?"#fff":"#555", fontSize:12, fontWeight:trackingType==="booking"?700:400, cursor:"pointer" }}>≡ƒôà Service bookings</button>
        <button onClick={()=>setTrackingType("order")} style={{ flex:1, padding:"8px", borderRadius:8, border:"none", background:trackingType==="order"?"#e6821e":"#f0f0f0", color:trackingType==="order"?"#fff":"#555", fontSize:12, fontWeight:trackingType==="order"?700:400, cursor:"pointer" }}>≡ƒôª Order deliveries</button>
      </div>

      {loading&&<div style={{ color:"#777777", fontSize:13 }}>Loading...</div>}

      {!loading&&trackingType==="order"&&activeOrders.length===0&&(
        <div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"3rem" }}>
          <div style={{ fontSize:32, marginBottom:10 }}>≡ƒôª</div>
          No active order deliveries to track
        </div>
      )}

      {trackingType==="order"&&activeOrders.map(o=>(
        <div key={o.id} onClick={()=>{ setSelected({...o, provider: o.provider, delivery_driver: o.delivery_driver}); setDriver(o.delivery_driver?{...o.delivery_driver}:null); setMechanic(null) }}
          style={{ background:"#ffffff", border:"1px solid #e6821e30", borderRadius:12, padding:isMobile?"0.9rem":"1.1rem", marginBottom:10, cursor:"pointer" }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
            <div>
              <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#000000", marginBottom:4 }}>Order #{o.order_number}</div>
              <div style={{ fontSize:11, color:"#777777", marginBottom:4 }}>≡ƒôª {o.provider?.business_name||o.provider?.first_name}</div>
              <div style={{ fontSize:11, color:"#378add" }}>≡ƒôì {o.delivery_address}</div>
              <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:"#e6821e20", color:"#e6821e", display:"inline-block", marginTop:4 }}>{o.delivery_status?.replace(/_/g," ")||"assigned"}</span>
            </div>
            <div style={{ textAlign:"right" }}>
              <div style={{ fontSize:12, color:"#e6821e", marginBottom:4 }}>KES {Number(o.subtotal||0).toLocaleString()}</div>
              <div style={{ fontSize:11, color:"#1d9e75" }}>≡ƒÜÜ {o.delivery_driver?.first_name} {o.delivery_driver?.last_name}</div>
              <div style={{ fontSize:11, color:"#378add", marginTop:4 }}>Track ΓåÆ</div>
            </div>
          </div>
        </div>
      ))}

      {!loading&&trackingType==="booking"&&activeBookings.length===0&&(
        <div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"3rem" }}>
          <div style={{ fontSize:32, marginBottom:10 }}>≡ƒôì</div>
          No active bookings to track
        </div>
      )}

      {trackingType==="booking"&&activeBookings.map(b=>(
        <div key={b.id} onClick={()=>{ setSelected(b); setDriver(null); setMechanic(null) }}
          style={{ background:"#ffffff", border:`1px solid ${SC[b.status]||"#eeeeee"}30`, borderRadius:12, padding:isMobile?"0.9rem":"1.1rem", marginBottom:10, cursor:"pointer" }}
          onMouseEnter={e=>e.currentTarget.style.background="#f8f8f8"}
          onMouseLeave={e=>e.currentTarget.style.background="#ffffff"}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
            <div>
              <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#000000", marginBottom:4 }}>{b.service_name}</div>
              <div style={{ fontSize:11, color:"#777777", marginBottom:4 }}>#{b.booking_number} ┬╖ {b.booking_date}</div>
              <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:`${SC[b.status]||"#888"}20`, color:SC[b.status]||"#888" }}>{b.status}</span>
                {b.is_concierge&&<span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:"#eff6ff", color:"#378add" }}>Concierge</span>}
                {b.is_emergency&&<span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:"#fff5f5", color:"#e24b4a" }}>≡ƒÜ¿ Emergency</span>}
              </div>
            </div>
            <div style={{ textAlign:"right" }}>
              <div style={{ fontSize:12, color:"#e6821e", marginBottom:4 }}>KES {Number(b.total_amount).toLocaleString()}</div>
              <div style={{ fontSize:11, color:"#777777" }}>
                {b.driver_id?"≡ƒÜù Driver assigned":b.assigned_mechanic_id?"≡ƒæ¿ΓÇì≡ƒöº Mechanic assigned":""}
              </div>
            </div>
          </div>
        </div>
      ))}
    </div>
  )
}

import { TripReportIcon, VehicleIcon, LocationIcon, SuccessIcon, ErrorIcon, MovingCarIcon } from "../../lib/cccIcons";
import { useEffect, useState, useRef } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"

export default function CustomerTripReports() {
  const { user } = useAuth()
  const isMobile = useIsMobile()
  const [bookings, setBookings] = useState([])
  const [selected, setSelected] = useState(null)
  const [logs, setLogs] = useState([])
  const [loading, setLoading] = useState(true)
  const [loadingLogs, setLoadingLogs] = useState(false)
  const [trackers, setTrackers] = useState([])

  useEffect(() => { if (user) loadTrackers() }, [user])

  async function loadTrackers() {
    const { data } = await supabase.from("vehicle_trackers").select("*").eq("customer_id", user.id)
    setTrackers(data||[])
  }

  useEffect(() => { if (user) load() }, [user])

  async function load() {
    const { data } = await supabase.from("bookings")
      .select("*, vehicles(make,model,license_plate), profiles!bookings_driver_id_fkey(first_name,last_name)")
      .eq("customer_id", user.id)
      .not("driver_id", "is", null)
      .order("created_at", { ascending:false })
      .limit(30)
    setBookings(data||[])
    setLoading(false)
  }

  async function loadTripReport(booking) {
    setSelected(booking)
    setLoadingLogs(true)
    const { data } = await supabase.from("booking_location_logs")
      .select("*")
      .eq("booking_id", booking.id)
      .order("recorded_at", { ascending:true })
    setLogs(data||[])
    setLoadingLogs(false)
  }

  function calcDistance(logs) {
    if (logs.length < 2) return 0
    let total = 0
    for (let i = 1; i < logs.length; i++) {
      const R = 6371
      const dLat = (logs[i].lat - logs[i-1].lat) * Math.PI/180
      const dLng = (logs[i].lng - logs[i-1].lng) * Math.PI/180
      const a = Math.sin(dLat/2)**2 + Math.cos(logs[i-1].lat*Math.PI/180)*Math.cos(logs[i].lat*Math.PI/180)*Math.sin(dLng/2)**2
      total += R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a))
    }
    return total.toFixed(1)
  }

  function calcDuration(logs) {
    if (logs.length < 2) return "ΓÇö"
    const start = new Date(logs[0].recorded_at)
    const end = new Date(logs[logs.length-1].recorded_at)
    const mins = Math.round((end-start)/60000)
    if (mins < 60) return mins+"min"
    return Math.floor(mins/60)+"h "+(mins%60)+"min"
  }

  const SC = { pending:"#e6821e", confirmed:"#378add", "in-progress":"#8b5cf6", completed:"#1d9e75", cancelled:"#e24b4a" }

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:"#000", marginBottom:"1.5rem" }}>
        <TripReportIcon size={20} color="#e6821e" /> Trip Reports
      </div>
      {selected ? (
        <div>
          <button onClick={()=>{ setSelected(null); setLogs([]) }}
            style={{ background:"none", border:"none", color:"#e6821e", cursor:"pointer", fontSize:13, marginBottom:"1rem", padding:0 }}>
            ΓåÉ Back to trips
          </button>
          <div style={{ background:"#f8f8f8", borderRadius:12, padding:"1rem", marginBottom:"1rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, marginBottom:4 }}>{selected.service_name}</div>
            <div style={{ fontSize:11, color:"#888" }}>#{selected.booking_number} ┬╖ {selected.booking_date}</div>
            <div style={{ fontSize:11, color:"#888" }}>Driver: {selected.profiles?.first_name} {selected.profiles?.last_name}</div>
            {selected.vehicles && <div style={{ fontSize:11, color:"#378add", marginTop:2, display:"flex", alignItems:"center", gap:3 }}><VehicleIcon size={11} color="#378add"/> {selected.vehicles.make} {selected.vehicles.model} ┬╖ {selected.vehicles.license_plate}</div>}
          </div>
          {loadingLogs ? (
            <div style={{ color:"#888", fontSize:13, padding:"2rem", textAlign:"center" }}>Loading trip data...</div>
          ) : logs.length === 0 ? (
            <div style={{ color:"#888", fontSize:13, padding:"2rem", textAlign:"center" }}>
              <div style={{ marginBottom:10, display:"flex", justifyContent:"center" }}><LocationIcon size={32} color="#e6821e" /></div>
              No GPS data recorded for this trip.
              <div style={{ fontSize:11, marginTop:8, color:"#aaa" }}>GPS logging is active when driver is online during your booking.</div>
            </div>
          ) : (
            <div>
              <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:8, marginBottom:"1rem" }}>
                {[
                  { label:"Distance", value:calcDistance(logs)+" km" },
                  { label:"Duration", value:calcDuration(logs) },
                  { label:"GPS points", value:logs.length },
                ].map(s=>(
                  <div key={s.label} style={{ background:"#fff", border:"1px solid #eee", borderRadius:10, padding:"0.75rem", textAlign:"center" }}>
                    <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:"#e6821e" }}>{s.value}</div>
                    <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{s.label}</div>
                  </div>
                ))}
              </div>
              <div style={{ background:"#f8f8f8", borderRadius:12, padding:"1rem", marginBottom:"1rem" }}>
                <div style={{ fontSize:12, fontWeight:600, color:"#000", marginBottom:8, display:"flex", alignItems:"center", gap:4 }}><LocationIcon size={14} color="#000"/> Journey Summary</div>
                <div style={{ fontSize:12, color:"#666", marginBottom:4 }}><SuccessIcon size={12} color="#1d9e75"/> Start: {new Date(logs[0].recorded_at).toLocaleTimeString()} ┬╖ {logs[0].lat?.toFixed(5)}, {logs[0].lng?.toFixed(5)}</div>
                <div style={{ fontSize:12, color:"#666" }}><ErrorIcon size={12} color="#e24b4a"/> End: {new Date(logs[logs.length-1].recorded_at).toLocaleTimeString()} ┬╖ {logs[logs.length-1].lat?.toFixed(5)}, {logs[logs.length-1].lng?.toFixed(5)}</div>
              </div>
              <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, marginBottom:8, display:"flex", alignItems:"center", gap:6 }}><LocationIcon size={14} color="#e6821e"/> GPS Timeline</div>
              <div style={{ maxHeight:250, overflowY:"auto", background:"#f8f8f8", borderRadius:10, padding:"0.5rem" }}>
                {logs.map((log, i) => (
                  <div key={log.id} style={{ display:"flex", gap:8, alignItems:"center", padding:"6px 8px", borderBottom:"1px solid #eeeeee", fontSize:11, color:"#666" }}>
                    <span style={{ color:"#e6821e", fontSize:10, minWidth:24, fontWeight:700 }}>{i+1}</span>
                    <span style={{ minWidth:60 }}>{new Date(log.recorded_at).toLocaleTimeString()}</span>
                    <span style={{ color:"#888", flex:1 }}>{log.lat?.toFixed(5)}, {log.lng?.toFixed(5)}</span>
                    <span style={{ background:log.source==="tracker"?"#e8f5e9":"#eff6ff", color:log.source==="tracker"?"#1d9e75":"#378add", borderRadius:4, padding:"1px 6px", fontSize:10, flexShrink:0 }}>
                      {log.source==="tracker"?<><SignalIcon size={12} color="#378add"/> Tracker</>:<><VehicleIcon size={12} color="#e6821e"/> Driver</>}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      ) : (
        <div>
          <div style={{ fontSize:12, color:"#888", marginBottom:"1rem" }}>Trip reports are generated for bookings where a concierge driver was assigned. GPS is logged every 30 seconds.</div>
          {loading && <div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
          {!loading && bookings.length === 0 && (
            <div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"3rem" }}>
              <div style={{ marginBottom:10, display:"flex", justifyContent:"center" }}><TripReportIcon size={32} color="#e6821e"/></div>
              No trips with drivers yet
            </div>
          )}
          {bookings.map(b => (
            <div key={b.id} onClick={()=>loadTripReport(b)}
              style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:8, cursor:"pointer" }}
              onMouseEnter={e=>e.currentTarget.style.background="#f0f0f0"}
              onMouseLeave={e=>e.currentTarget.style.background="#f8f8f8"}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div>
                  <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, marginBottom:4 }}>{b.service_name}</div>
                  <div style={{ fontSize:11, color:"#888" }}>#{b.booking_number} ┬╖ {b.booking_date}</div>
                  {b.profiles && <div style={{ fontSize:11, color:"#378add", marginTop:2, display:"flex", alignItems:"center", gap:3 }}><VehicleIcon size={11} color="#378add"/> {b.profiles.first_name} {b.profiles.last_name}</div>}
                  {b.vehicles && <div style={{ fontSize:11, color:"#888", marginTop:2, display:"flex", alignItems:"center", gap:3 }}><MovingCarIcon size={11} color="#888"/> {b.vehicles.make} {b.vehicles.model} ┬╖ {b.vehicles.license_plate}</div>}
                </div>
                <div style={{ textAlign:"right" }}>
                  <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:`${SC[b.status]||"#888"}20`, color:SC[b.status]||"#888" }}>{b.status}</span>
                  <div style={{ fontSize:11, color:"#e6821e", marginTop:6 }}>View trip ΓåÆ</div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const FUEL_LABELS = { empty:"Empty", quarter:"1/4", half:"1/2", three_quarter:"3/4", full:"Full" }

export default function CustomerVehicleReports() {
  const { user } = useAuth()
  const isMobile = useIsMobile()
  const [bookings, setBookings] = useState([])
  const [reports, setReports] = useState({})
  const [alerts, setAlerts] = useState([])
  const [disputes, setDisputes] = useState([])
  const [loading, setLoading] = useState(true)
  const [selected, setSelected] = useState(null)
  const [showDispute, setShowDispute] = useState(null)
  const [disputeForm, setDisputeForm] = useState({ type:"mileage", description:"" })
  const [submitting, setSubmitting] = useState(false)

  useEffect(() => { if (user) load() }, [user])

  async function load() {
    const { data: bks } = await supabase.from("bookings")
      .select("id,service_name,booking_date,booking_number,status,is_concierge,service_category,vehicles(make,model,license_plate)")
      .eq("customer_id", user.id)
      .order("created_at", { ascending:false })
      .limit(30)

    setBookings(bks||[])

    if (bks?.length) {
      const ids = bks.map(b=>b.id)
      const [{ data: reps }, { data: alts }, { data: disps }] = await Promise.all([
        supabase.from("vehicle_condition_reports").select("*").in("booking_id", ids),
        supabase.from("mileage_alerts").select("*").in("booking_id", ids),
        supabase.from("vehicle_disputes").select("*").eq("customer_id", user.id),
      ])

      const repMap = {}
      reps?.forEach(r => {
        if (!repMap[r.booking_id]) repMap[r.booking_id] = {}
        repMap[r.booking_id][r.report_type] = r
      })
      setReports(repMap)
      setAlerts(alts||[])
      setDisputes(disps||[])
    }
    setLoading(false)
  }

  async function submitDispute(e) {
    e.preventDefault()
    if (!disputeForm.description) return toast.error("Please describe the dispute")
    setSubmitting(true)
    try {
      const { error } = await supabase.from("vehicle_disputes").insert({
        booking_id: showDispute,
        customer_id: user.id,
        dispute_type: disputeForm.type,
        description: disputeForm.description,
        status: "open",
      })
      if (error) throw error
      toast.success("Dispute submitted ΓÇö admin will review within 24 hours")
      setShowDispute(null)
      setDisputeForm({ type:"mileage", description:"" })
      load()
    } catch(err) {
      toast.error(err.message)
    } finally {
      setSubmitting(false)
    }
  }

  function getAlert(bookingId) { return alerts.find(a=>a.booking_id===bookingId) }
  function getDispute(bookingId) { return disputes.find(d=>d.booking_id===bookingId) }
  function canDispute(bookingId) {
    const bk = bookings.find(b=>b.id===bookingId)
    if (!bk) return false
    const report = reports[bookingId]?.dropoff
    if (!report) return false
    const hours = (Date.now() - new Date(report.created_at).getTime()) / 3600000
    return hours <= 24 && !getDispute(bookingId)
  }

  const inp = { width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"11px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif" }
  const lbl = { fontSize:11, color:"#666", textTransform:"uppercase", letterSpacing:"0.05em", display:"block", marginBottom:4 }

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:18, fontWeight:800, color:"#000000", marginBottom:4 }}>Vehicle reports</div>
      <div style={{ fontSize:12, color:"#777777", marginBottom:"1.25rem" }}>Condition reports for your vehicles during service</div>

      {loading&&<div style={{ color:"#777777", fontSize:13 }}>Loading...</div>}
      {!loading&&bookings.length===0&&(
        <div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"3rem" }}>
          <div style={{ fontSize:32, marginBottom:10 }}>≡ƒÜù</div>
          No vehicle reports yet
        </div>
      )}

      {bookings.map(b=>{
        const bReports = reports[b.id]||{}
        const alert = getAlert(b.id)
        const dispute = getDispute(b.id)
        const pickup = bReports.pickup
        const dropoff = bReports.dropoff
        return (
          <div key={b.id} style={{ background:"#ffffff", border:`1px solid ${alert&&!dispute?"#e6821e40":"#eeeeee"}`, borderRadius:12, padding:isMobile?"0.9rem":"1.1rem", marginBottom:10 }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:10 }}>
              <div>
                <div style={{ fontSize:13, fontWeight:600, color:"#000000", marginBottom:2 }}>{b.service_name}</div>
                <div style={{ fontSize:11, color:"#777777" }}>#{b.booking_number} ┬╖ {b.booking_date}</div>
                {b.vehicles&&<div style={{ fontSize:11, color:"#378add", marginTop:2 }}>≡ƒÜù {b.vehicles.make} {b.vehicles.model} ΓÇö {b.vehicles.license_plate}</div>}
              </div>
              <button onClick={()=>setSelected(selected===b.id?null:b.id)}
                style={{ background:"none", border:"1px solid #dddddd", borderRadius:7, color:"#666", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                {selected===b.id?"Hide":"View reports"}
              </button>
            </div>

            {alert&&(
              <div style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:8, padding:"0.75rem", marginBottom:8 }}>
                <div style={{ fontSize:12, color:"#e6821e", fontWeight:600, marginBottom:2 }}>ΓÜá∩╕Å Mileage alert</div>
                <div style={{ fontSize:11, color:"#555555" }}>
                  Vehicle driven {alert.difference}km during service (pickup: {alert.pickup_odometer}km ΓåÆ dropoff: {alert.dropoff_odometer}km)
                </div>
                {dispute?(
                  <div style={{ fontSize:11, color:"#777777", marginTop:4 }}>
                    Dispute {dispute.status} ΓÇö {dispute.status==="resolved"?"Resolved":dispute.status==="dismissed"?"Dismissed":"Under review"}
                  </div>
                ):canDispute(b.id)&&(
                  <button onClick={()=>setShowDispute(b.id)}
                    style={{ background:"#e6821e", border:"none", borderRadius:7, color:"#fff", fontSize:11, fontWeight:600, padding:"5px 12px", cursor:"pointer", marginTop:6 }}>
                    Dispute this
                  </button>
                )}
              </div>
            )}

            {selected===b.id&&(
              <div style={{ borderTop:"1px solid #eeeeee", paddingTop:10 }}>
                <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"1fr 1fr", gap:10 }}>
                  {[{ report:pickup, type:"Pickup" }, { report:dropoff, type:"Dropoff" }].map(({ report, type })=>(
                    <div key={type} style={{ background:"#ffffff", borderRadius:10, padding:"0.9rem" }}>
                      <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:type==="Pickup"?"#378add":"#1d9e75", marginBottom:8 }}>{type} report</div>
                      {report?(
                        <div>
                          <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, marginBottom:4 }}>
                            <span style={{ color:"#777777" }}>Odometer</span>
                            <span style={{ color:"#000000", fontWeight:600 }}>{report.odometer_reading?.toLocaleString()} km</span>
                          </div>
                          <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, marginBottom:8 }}>
                            <span style={{ color:"#777777" }}>Fuel level</span>
                            <span style={{ color:"#000000" }}>{FUEL_LABELS[report.fuel_level]||report.fuel_level}</span>
                          </div>
                          <div style={{ fontSize:11, color:"#777777", marginBottom:4 }}>Condition:</div>
                          <div style={{ display:"flex", flexWrap:"wrap", gap:4, marginBottom:4 }}>
                            {["has_scratches","has_dents","has_broken_lights","has_missing_parts","dirty_interior","dirty_exterior"].filter(k=>report[k]).map(k=>(
                              <span key={k} style={{ fontSize:10, padding:"2px 7px", borderRadius:10, background:"#fff5f5", color:"#e24b4a" }}>
                                {k.replace("has_","").replace("_"," ")}
                              </span>
                            ))}
                            {!["has_scratches","has_dents","has_broken_lights","has_missing_parts","dirty_interior","dirty_exterior"].some(k=>report[k])&&(
                              <span style={{ fontSize:10, color:"#1d9e75" }}>Γ£ô No issues found</span>
                            )}
                          </div>
                          {report.condition_notes&&<div style={{ fontSize:11, color:"#777777", fontStyle:"italic" }}>&quot;{report.condition_notes}&quot;</div>}
                          <div style={{ fontSize:10, color:"#888888", marginTop:4 }}>{new Date(report.created_at).toLocaleString()}</div>
                        </div>
                      ):(
                        <div style={{ fontSize:12, color:"#888888", textAlign:"center", padding:"1rem" }}>No {type.toLowerCase()} report yet</div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            )}

            {showDispute===b.id&&(
              <div style={{ marginTop:10, background:"#fff8f0", border:"1px solid #e6821e30", borderRadius:10, padding:"1rem" }}>
                <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#e6821e", marginBottom:"1rem" }}>Raise a dispute</div>
                <form onSubmit={submitDispute}>
                  <div style={{ marginBottom:12 }}>
                    <label style={lbl}>Dispute type</label>
                    <select value={disputeForm.type} onChange={e=>setDisputeForm(f=>({...f,type:e.target.value}))} style={inp}>
                      <option value="mileage">Excessive mileage</option>
                      <option value="condition">Vehicle condition</option>
                      <option value="fuel">Fuel level discrepancy</option>
                      <option value="other">Other</option>
                    </select>
                  </div>
                  <div style={{ marginBottom:12 }}>
                    <label style={lbl}>Description</label>
                    <textarea value={disputeForm.description} onChange={e=>setDisputeForm(f=>({...f,description:e.target.value}))}
                      placeholder="Describe your concern in detail..."
                      style={{ ...inp, resize:"vertical", minHeight:80 }} required/>
                  </div>
                  <div style={{ display:"flex", gap:8 }}>
                    <button type="submit" disabled={submitting}
                      style={{ background:submitting?"#555555":"#e6821e", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"9px 18px", cursor:submitting?"not-allowed":"pointer" }}>
                      {submitting?"Submitting...":"Submit dispute"}
                    </button>
                    <button type="button" onClick={()=>setShowDispute(null)}
                      style={{ background:"none", border:"1px solid #dddddd", borderRadius:8, color:"#666", fontSize:12, padding:"9px 14px", cursor:"pointer" }}>
                      Cancel
                    </button>
                  </div>
                </form>
              </div>
            )}
          </div>
        )
      })}
    </div>
  )
}

import { VehicleIcon, LocationIcon, ServicesIcon, OilIcon, WarningIcon, ClockIcon, EditIcon, DeleteIcon, SignalIcon, LinkIcon, CameraIcon } from "../../lib/cccIcons";
import useIsMobile from "../../lib/useIsMobile"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import toast from "react-hot-toast"

export default function CustomerVehicles() {
  const isMobile = useIsMobile()
  const { user } = useAuth()
  const [vehicles, setVehicles] = useState([])
  const [form, setForm] = useState({make:"",model:"",year:"",color:"",license_plate:"",photo_url:"",current_mileage:"",last_service_date:"",last_oil_change_date:""})
  const [uploadingPhoto, setUploadingPhoto] = useState(false)
  const [editing, setEditing] = useState(null)
  const [loading, setLoading] = useState(true)
  const [trackers, setTrackers] = useState([])
  const [showTracker, setShowTracker] = useState(null)
  const [trackerForm, setTrackerForm] = useState({ provider:"cartrack", api_key:"", api_secret:"", vehicle_identifier:"" })
  const [savingTracker, setSavingTracker] = useState(false)

  useEffect(() => { if (user) load() }, [user])

  async function load() {
    const { data: trk } = await supabase.from("vehicle_trackers").select("*").eq("customer_id", user.id)
    setTrackers(trk||[])
    const { data } = await supabase.from("vehicles").select("*").eq("user_id", user.id).order("is_default",{ascending:false})
    setVehicles(data||[]); setLoading(false)
  }

  async function save(e) {
    e.preventDefault()
    const payload = {...form, year:parseInt(form.year), user_id:user.id, current_mileage: form.current_mileage?parseInt(form.current_mileage):null, last_service_date: form.last_service_date||null, last_oil_change_date: form.last_oil_change_date||null}
    if (editing) {
      const {error} = await supabase.from("vehicles").update(payload).eq("id",editing).eq("user_id",user.id)
      if (error) return toast.error(error.message)
      toast.success("Vehicle updated"); setEditing(null)
    } else {
      const {error} = await supabase.from("vehicles").insert(payload)
      if (error) return toast.error(error.message)
      toast.success("Vehicle added")
    }
    setForm({make:"",model:"",year:"",color:"",license_plate:""}); load()
  }

  async function remove(id) {
    if (!confirm("Remove this vehicle?")) return
    const { error } = await supabase.from("vehicles").delete().eq("id",id).eq("user_id",user.id)
    if (error) { toast.error(error.message); console.error("Delete error:", error); return }
    toast.success("Vehicle removed"); load()
  }

  async function setDefault(id) {
    await supabase.from("vehicles").update({is_default:false}).eq("user_id",user.id)
    await supabase.from("vehicles").update({is_default:true}).eq("id",id).eq("user_id",user.id)
    toast.success("Default vehicle set"); load()
  }

  function getMaintenanceStatus(v) {
    const alerts = []
    const today = new Date()
    if (v.last_service_date) {
      const monthsSince = (today - new Date(v.last_service_date)) / (1000*60*60*24*30)
      if (monthsSince >= 6) alerts.push({ type:"service", level:"overdue", text:"Full service overdue (6+ months)" })
      else if (monthsSince >= 5) alerts.push({ type:"service", level:"due-soon", text:"Full service due soon" })
    } else {
      alerts.push({ type:"service", level:"unknown", text:"No service history ΓÇö add last service date" })
    }
    if (v.last_oil_change_date) {
      const monthsSince = (today - new Date(v.last_oil_change_date)) / (1000*60*60*24*30)
      if (monthsSince >= 3) alerts.push({ type:"oil", level:"overdue", text:"Oil change overdue (3+ months)" })
      else if (monthsSince >= 2.5) alerts.push({ type:"oil", level:"due-soon", text:"Oil change due soon" })
    }
    if (v.current_mileage && v.last_service_mileage) {
      const kmSince = v.current_mileage - v.last_service_mileage
      if (kmSince >= 10000) alerts.push({ type:"service-km", level:"overdue", text:"Service overdue (10,000+ km since last service)" })
      else if (kmSince >= 8000) alerts.push({ type:"service-km", level:"due-soon", text:"Service due soon (approaching 10,000km)" })
    }
    if (v.current_mileage && v.last_oil_change_mileage) {
      const kmSince = v.current_mileage - v.last_oil_change_mileage
      if (kmSince >= 5000) alerts.push({ type:"oil-km", level:"overdue", text:"Oil change overdue (5,000+ km since last)" })
      else if (kmSince >= 4000) alerts.push({ type:"oil-km", level:"due-soon", text:"Oil change due soon (approaching 5,000km)" })
    }
    return alerts
  }
  const inp = {width:"100%",background:"#ffffff",border:"1px solid #e5e5e5",borderRadius:8,padding:"10px 12px",color:"#000000",fontSize:13,outline:"none",marginBottom:10,fontFamily:"'DM Sans',sans-serif"}
  const lbl = {fontSize:11,color:"#666",textTransform:"uppercase",letterSpacing:"0.05em",display:"block",marginBottom:4}

  async function saveTracker(e) {
    e.preventDefault()
    if (!trackerForm.api_key) return
    setSavingTracker(true)
    const existing = trackers.find(t=>t.vehicle_id===showTracker?.id)
    if (existing) {
      await supabase.from("vehicle_trackers").update({
        provider: trackerForm.provider,
        api_key: trackerForm.api_key, api_secret: trackerForm.api_secret,
        vehicle_identifier: trackerForm.vehicle_identifier,
        is_active: true
      }).eq("id", existing.id)
    } else {
      await supabase.from("vehicle_trackers").insert({
        customer_id: user.id,
        vehicle_id: showTracker.id,
        provider: trackerForm.provider,
        api_key: trackerForm.api_key, api_secret: trackerForm.api_secret,
        vehicle_identifier: trackerForm.vehicle_identifier,
        is_active: true
      })
    }
    const { data: trk } = await supabase.from("vehicle_trackers").select("*").eq("customer_id", user.id)
    setTrackers(trk||[])
    setShowTracker(null)
    setSavingTracker(false)
    toast.success("Tracker linked successfully!")
  }

  async function removeTracker(vehicleId) {
    await supabase.from("vehicle_trackers").delete().eq("vehicle_id", vehicleId).eq("customer_id", user.id)
    const { data: trk } = await supabase.from("vehicle_trackers").select("*").eq("customer_id", user.id)
    setTrackers(trk||[])
    toast.success("Tracker removed")
  }

  return (
    <div>
      {loading&&<div style={{color:"#777777",fontSize:13}}>Loading...</div>}
      {vehicles.map(v=>(
        <div key={v.id} style={{background:"#ffffff",border:`1px solid ${v.is_default?"#e6821e40":"#eeeeee"}`,borderRadius:12,padding:"1rem",marginBottom:10}}>
          {/* Top row: photo + name + badge */}
          <div style={{display:"flex",alignItems:"flex-start",gap:12,marginBottom:10}}>
            <div style={{width:64,height:64,background:"#fff8f0",borderRadius:10,display:"flex",alignItems:"center",justifyContent:"center",fontSize:28,overflow:"hidden",flexShrink:0,border:"1px solid #e6821e20"}}>
              {v.photo_url ? <img src={v.photo_url} alt="Vehicle" style={{width:"100%",height:"100%",objectFit:"cover"}}/> : "≡ƒÜù"}
            </div>
            <div style={{flex:1,minWidth:0}}>
              <div style={{display:"flex",alignItems:"center",gap:6,flexWrap:"wrap",marginBottom:2}}>
                <div style={{fontFamily:"Syne",fontSize:15,fontWeight:800,color:"#000"}}>{v.make} {v.model}</div>
                {v.is_default&&<span style={{fontSize:10,color:"#e6821e",background:"#fff8f0",padding:"2px 8px",borderRadius:10,border:"1px solid #e6821e30",flexShrink:0}}>Γ¡É Default</span>}
              </div>
              <div style={{fontSize:12,color:"#666",marginBottom:2}}>{v.year} ┬╖ {v.color||"No color"} ┬╖ {v.license_plate}</div>
              {v.current_mileage&&<div style={{fontSize:11,color:"#888",display:"flex",alignItems:"center",gap:3}}><LocationIcon size={11} color="#888"/> {Number(v.current_mileage).toLocaleString()} km</div>}
              {v.last_service_date&&<div style={{fontSize:11,color:"#888",display:"flex",alignItems:"center",gap:3}}><ServicesIcon size={11} color="#888"/> Last service: {new Date(v.last_service_date).toLocaleDateString()}</div>}
              {v.last_oil_change_date&&<div style={{fontSize:11,color:"#888",display:"flex",alignItems:"center",gap:3}}><OilIcon size={11} color="#888"/> Last oil change: {new Date(v.last_oil_change_date).toLocaleDateString()}</div>}
            </div>
          </div>
          {/* Maintenance alerts */}
          {getMaintenanceStatus(v).filter(a=>a.level!=="unknown").length>0&&(
            <div style={{display:"flex",flexWrap:"wrap",gap:4,marginBottom:10}}>
              {getMaintenanceStatus(v).filter(a=>a.level!=="unknown").map((a,i)=>(
                <div key={i} style={{fontSize:10,color:a.level==="overdue"?"#e24b4a":"#e6821e",background:a.level==="overdue"?"#fff5f5":"#fff8f0",padding:"3px 10px",borderRadius:20,border:`1px solid ${a.level==="overdue"?"#e24b4a30":"#e6821e30"}`}}>
                  {a.level==="overdue"?<WarningIcon size={12} color="#e24b4a"/>:<ClockIcon size={12} color="#e6821e"/>} {a.text}
                </div>
              ))}
            </div>
          )}
          {/* Action buttons */}
          <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
            {!v.is_default&&<button onClick={()=>setDefault(v.id)} style={{background:"#fff8f0",border:"1px solid #e6821e40",borderRadius:7,color:"#e6821e",fontSize:11,padding:"5px 10px",cursor:"pointer"}}>Γ¡É Set default</button>}
            <button onClick={()=>{setEditing(v.id);setForm({make:v.make,model:v.model,year:String(v.year),color:v.color||"",license_plate:v.license_plate,photo_url:v.photo_url||"",current_mileage:v.current_mileage?String(v.current_mileage):"",last_service_date:v.last_service_date||"",last_oil_change_date:v.last_oil_change_date||""})}} style={{background:"#eff6ff",border:"1px solid #378add40",borderRadius:7,color:"#378add",fontSize:11,padding:"5px 10px",cursor:"pointer"}}>Γ£Å∩╕Å Edit</button>
            <button onClick={()=>remove(v.id)} style={{background:"#fff5f5",border:"1px solid #e24b4a40",borderRadius:7,color:"#e24b4a",fontSize:11,padding:"5px 10px",cursor:"pointer"}}>≡ƒùæ∩╕Å Remove</button>
            {trackers.find(t=>t.vehicle_id===v.id)
              ? <button onClick={()=>setShowTracker(v)} style={{background:"#f0fdf4",border:"1px solid #1d9e7540",borderRadius:7,color:"#1d9e75",fontSize:11,padding:"5px 10px",cursor:"pointer"}}>≡ƒôí Tracker linked</button>
              : <button onClick={()=>setShowTracker(v)} style={{background:"#f8f8f8",border:"1px solid #ddd",borderRadius:7,color:"#555",fontSize:11,padding:"5px 10px",cursor:"pointer"}}>≡ƒöù Link tracker</button>
            }
          </div>
        </div>
      ))}
      <div style={{background:"#ffffff",border:"1px solid #eeeeee",borderRadius:10,padding:"1.25rem",marginTop:"1rem"}}>
        <div style={{fontFamily:"Syne",fontSize:14,fontWeight:700,marginBottom:"1rem"}}>{editing?"Edit vehicle":"Add a vehicle"}</div>
        <form onSubmit={save}>
          <div style={{display:"grid",gridTemplateColumns:isMobile?"1fr":"1fr 1fr",gap:10}}>
            <div><label style={lbl}>Make</label><input style={inp} placeholder="Toyota" value={form.make} onChange={e=>setForm(f=>({...f,make:e.target.value}))} required/></div>
            <div><label style={lbl}>Model</label><input style={inp} placeholder="Camry" value={form.model} onChange={e=>setForm(f=>({...f,model:e.target.value}))} required/></div>
            <div><label style={lbl}>Year</label><input style={inp} placeholder="2020" type="number" min="1990" max="2026" value={form.year} onChange={e=>setForm(f=>({...f,year:e.target.value}))} required/></div>
            <div><label style={lbl}>Color</label><input style={inp} placeholder="Silver" value={form.color} onChange={e=>setForm(f=>({...f,color:e.target.value}))}/></div>
          </div>
          <div><label style={lbl}>License plate</label><input style={inp} placeholder="KDA 123A" value={form.license_plate} onChange={e=>setForm(f=>({...f,license_plate:e.target.value}))} required/></div>
          <div style={{display:"grid",gridTemplateColumns:isMobile?"1fr":"1fr 1fr 1fr",gap:10}}>
            <div><label style={lbl}>Current mileage (km)</label><input style={inp} placeholder="45000" type="number" value={form.current_mileage} onChange={e=>setForm(f=>({...f,current_mileage:e.target.value}))}/></div>
            <div><label style={lbl}>Last full service</label><input style={inp} type="date" value={form.last_service_date} onChange={e=>setForm(f=>({...f,last_service_date:e.target.value}))}/></div>
            <div><label style={lbl}>Last oil change</label><input style={inp} type="date" value={form.last_oil_change_date} onChange={e=>setForm(f=>({...f,last_oil_change_date:e.target.value}))}/></div>
          </div>
          <label style={lbl}>Vehicle photo (optional)</label>
          <div style={{ marginBottom:10 }}>
            {form.photo_url&&<img src={form.photo_url} alt="Vehicle" style={{ width:"100%", maxHeight:150, objectFit:"cover", borderRadius:8, marginBottom:8 }}/>}
            <label style={{ display:"block", width:"100%", background:uploadingPhoto?"#f5f5f5":"#ffffff", border:"2px dashed #e5e5e5", borderRadius:8, padding:"12px", color:"#555555", fontSize:12, marginBottom:8, cursor:"pointer", textAlign:"center" }}>
              {uploadingPhoto ? "ΓÅ│ Uploading..." : form.photo_url ? "≡ƒô╖ Tap to change photo" : "≡ƒô╖ Tap to upload vehicle photo"}
              <input type="file" accept="image/*" style={{ display:"none" }} onChange={async(e)=>{
                const file = e.target.files[0]
                if (!file) return
                if (file.size > 5*1024*1024) return toast.error("Photo must be under 5MB")
                if (!file.type.startsWith("image/")) return toast.error("Please select an image file")
                setUploadingPhoto(true)
                try {
                  const ext = file.name.split(".").pop()
                  const path = `vehicles/${user.id}/vehicle-${Date.now()}.${ext}`
                  const { error } = await supabase.storage.from("marketplace").upload(path, file, { upsert:true })
                  if (error) throw error
                  const { data } = supabase.storage.from("marketplace").getPublicUrl(path)
                  setForm(f=>({...f, photo_url:data.publicUrl}))
                  toast.success("Photo uploaded!")
                } catch(err) {
                  toast.error("Upload failed: " + err.message)
                } finally {
                  setUploadingPhoto(false)
                }
              }}/>
            </label>
          </div>
          <div style={{display:"flex",gap:8}}>
            <button type="submit" style={{background:"#e6821e",border:"none",borderRadius:8,color:"#fff",fontFamily:"Syne,sans-serif",fontSize:13,fontWeight:700,padding:"10px 20px",cursor:"pointer"}}>{editing?"Update vehicle":"Add vehicle"}</button>
            {editing&&<button type="button" onClick={()=>{setEditing(null);setForm({make:"",model:"",year:"",color:"",license_plate:""})}} style={{background:"none",border:"1px solid #dddddd",borderRadius:8,color:"#555555",fontSize:13,padding:"10px 20px",cursor:"pointer"}}>Cancel</button>}
          </div>
        </form>
      </div>
      {showTracker&&(
        <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.7)", zIndex:200, display:"flex", alignItems:"flex-end", justifyContent:"center" }}
          onClick={e=>{ if(e.target===e.currentTarget) setShowTracker(null) }}>
          <div style={{ background:"#fff", borderRadius:"16px 16px 0 0", padding:"1.5rem", width:"100%", maxWidth:480 }}>
            <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, marginBottom:4 }}>≡ƒöù Link Tracker</div>
            <div style={{ fontSize:12, color:"#888", marginBottom:"1rem" }}>{showTracker?.make} {showTracker?.model} ┬╖ {showTracker?.license_plate}</div>
            <div style={{ background:"#f0fdf4", border:"1px solid #1d9e7530", borderRadius:8, padding:"0.75rem", marginBottom:"1rem", fontSize:12, color:"#555", lineHeight:1.6 }}>
              ≡ƒÆí Enter your tracker API key from your tracker provider dashboard. CCC uses your own credentials ΓÇö we never store location without your permission.
            </div>
            <form onSubmit={saveTracker}>
              <label style={{ fontSize:11, color:"#666", display:"block", marginBottom:4 }}>Tracker Provider</label>
              <select value={trackerForm.provider} onChange={e=>setTrackerForm(f=>({...f,provider:e.target.value}))}
                style={{ width:"100%", background:"#f5f5f5", border:"1px solid #e0e0e0", borderRadius:8, padding:"10px 12px", fontSize:13, marginBottom:10, outline:"none" }}>
                <option value="cartrack">Cartrack Kenya</option>
                <option value="itrack">iTrack (itrack.live)</option>
                <option value="itrace">iTrace Africa</option>
                <option value="other">Other (contact support)</option>
              </select>
              <label style={{ fontSize:11, color:"#666", display:"block", marginBottom:4 }}>API Key / Access Token *</label>
              <input value={trackerForm.api_key} onChange={e=>setTrackerForm(f=>({...f,api_key:e.target.value}))} placeholder="Enter your tracker API key / username"
                style={{ width:"100%", background:"#f5f5f5", border:"1px solid #e0e0e0", borderRadius:8, padding:"10px 12px", fontSize:13, marginBottom:10, outline:"none", boxSizing:"border-box" }} required/>
              {trackerForm.provider==="cartrack"&&(
                <><label style={{ fontSize:11, color:"#666", display:"block", marginBottom:4 }}>Password / API Secret *</label>
                <input value={trackerForm.api_secret||""} onChange={e=>setTrackerForm(f=>({...f,api_secret:e.target.value}))} placeholder="Your Cartrack password"
                  style={{ width:"100%", background:"#f5f5f5", border:"1px solid #e0e0e0", borderRadius:8, padding:"10px 12px", fontSize:13, marginBottom:10, outline:"none", boxSizing:"border-box" }}/></>
              )}
              <label style={{ fontSize:11, color:"#666", display:"block", marginBottom:4 }}>Vehicle ID (from tracker dashboard)</label>
              <input value={trackerForm.vehicle_identifier} onChange={e=>setTrackerForm(f=>({...f,vehicle_identifier:e.target.value}))} placeholder="e.g. VH-12345 or plate number"
                style={{ width:"100%", background:"#f5f5f5", border:"1px solid #e0e0e0", borderRadius:8, padding:"10px 12px", fontSize:13, marginBottom:16, outline:"none", boxSizing:"border-box" }}/>
              <div style={{ display:"flex", gap:8 }}>
                <button type="submit" disabled={savingTracker} style={{ flex:1, background:"#e6821e", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"12px", cursor:"pointer" }}>
                  {savingTracker?"Saving...":"Save tracker"}
                </button>
                {trackers.find(t=>t.vehicle_id===showTracker?.id)&&(
                  <button type="button" onClick={()=>removeTracker(showTracker.id)} style={{ background:"#fff5f5", border:"1px solid #e24b4a40", borderRadius:10, color:"#e24b4a", fontSize:13, padding:"12px 16px", cursor:"pointer" }}>Remove</button>
                )}
                <button type="button" onClick={()=>setShowTracker(null)} style={{ background:"#f5f5f5", border:"none", borderRadius:10, color:"#555", fontSize:13, padding:"12px 16px", cursor:"pointer" }}>Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}





    </div>
  )
}

import { useEffect, useState, useRef } from "react"
import { supabase } from "../../lib/supabase"
import { HomeIcon, VehicleIcon, PaymentsIcon, VideoIcon, CameraIcon, EyeIcon, ChatIcon, PhoneCallIcon, EmailIcon } from "../../lib/cccIcons"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const BODY_TYPES = ["sedan","suv","hatchback","pickup","van","crossover","coupe","convertible","minivan","wagon"]
const TRANSMISSIONS = ["automatic","manual","cvt","dct"]
const FUEL_TYPES = ["petrol","diesel","hybrid","electric","lpg"]
const DRIVE_TYPES = ["2wd","4wd","awd"]

const EMPTY = {
  brand:"", model:"", variant:"", year:new Date().getFullYear(), body_type:"sedan",
  engine_cc:"", transmission:"automatic", fuel_type:"petrol", drive_type:"2wd",
  color:"", interior_color:"", seats:5, doors:4,
  price:"", discount_price:"", price_negotiable:false,
  description:"", features:"", photos:[], video_url:"",
  showroom_name:"", showroom_location:"", showroom_phone:"", showroom_email:"",
  stock_count:1
}

export default function MyNewCarListings() {
  const { user, profile } = useAuth()
  const isMobile = useIsMobile()
  const [listings, setListings] = useState([])
  const [enquiries, setEnquiries] = useState([])
  const [loading, setLoading] = useState(true)
  const [showForm, setShowForm] = useState(false)
  const [editing, setEditing] = useState(null)
  const [form, setForm] = useState(EMPTY)
  const [saving, setSaving] = useState(false)
  const [tab, setTab] = useState("listings")
  const [uploadingPhoto, setUploadingPhoto] = useState(false)
  const [uploadingVideo, setUploadingVideo] = useState(false)
  const [videoUploadProgress, setVideoUploadProgress] = useState(0)
  const [fees, setFees] = useState({ listing_fee:2000, duration_days:30 })
  const [isDealer, setIsDealer] = useState(false)
  const [dealerStatus, setDealerStatus] = useState(null)
  const [showDealerForm, setShowDealerForm] = useState(false)
  const [dealerForm, setDealerForm] = useState({ showroom_name:"", showroom_location:"", showroom_phone:"", showroom_email:"", brands_sold:"", monthly_stock:"" })
  const [submittingDealer, setSubmittingDealer] = useState(false)
  const photoRef = useRef(null)

  useEffect(() => {
    if (!user) return
    load()
    // Load dealer status
    supabase.from("profiles").select("is_dealer").eq("id", user.id).single()
      .then(({data}) => setIsDealer(data?.is_dealer||false))
    supabase.from("dealer_applications").select("status").eq("user_id", user.id).maybeSingle()
      .then(({data}) => setDealerStatus(data?.status||null))
    supabase.from("app_settings").select("key,value").in("key",["new_car_listing_fee","new_car_listing_duration_days","new_car_lead_fee","new_car_featured_fee_day","new_car_featured_fee_week","new_car_featured_fee_month"])
      .then(({ data }) => {
        const map = {}
        data?.forEach(r => { map[r.key] = Number(r.value) })
        setFees({ listing_fee: map.new_car_listing_fee||2000, duration_days: map.new_car_listing_duration_days||30, lead_fee: map.new_car_lead_fee||500, featured_day: map.new_car_featured_fee_day||100, featured_week: map.new_car_featured_fee_week||500, featured_month: map.new_car_featured_fee_month||1500 })
      })
  }, [user])

  async function load() {
    const [{ data: lst }, { data: enq }] = await Promise.all([
      supabase.from("new_car_listings").select("*").eq("dealer_id", user.id).order("created_at",{ascending:false}),
      supabase.from("car_enquiries").select("*, new_car_listings(brand,model,year)").eq("dealer_id", user.id).order("created_at",{ascending:false})
    ])
    setListings(lst||[])
    setEnquiries(enq||[])
    setLoading(false)
  }

  async function uploadPhoto(file) {
    setUploadingPhoto(true)
    try {
      const ext = file.name.split(".").pop()
      const path = `new-cars/${user.id}/${Date.now()}.${ext}`
      const { error } = await supabase.storage.from("marketplace").upload(path, file, { upsert:true })
      if (error) throw error
      const { data } = supabase.storage.from("marketplace").getPublicUrl(path)
      setForm(f=>({...f, photos:[...f.photos, data.publicUrl]}))
      toast.success("Photo uploaded!")
    } catch(e) { toast.error(e.message) }
    finally { setUploadingPhoto(false) }
  }

  async function submitDealerApplication() {
    if(!dealerForm.showroom_name||!dealerForm.showroom_location||!dealerForm.showroom_phone) return toast.error("Please fill in all required fields")
    setSubmittingDealer(true)
    try {
      await supabase.from("dealer_applications").insert({
        user_id: user.id,
        showroom_name: dealerForm.showroom_name,
        showroom_location: dealerForm.showroom_location,
        showroom_phone: dealerForm.showroom_phone,
        showroom_email: dealerForm.showroom_email||null,
        brands_sold: dealerForm.brands_sold ? dealerForm.brands_sold.split(",").map(b=>b.trim()).filter(Boolean) : [],
        monthly_stock: dealerForm.monthly_stock ? Number(dealerForm.monthly_stock) : null,
        status: "pending"
      })
      const {data:admins} = await supabase.from("profiles").select("id").eq("role","admin")
      if(admins?.length>0) await supabase.from("notifications").insert(admins.map(a=>({
        user_id:a.id, type:"dealer_application", title:"New Dealer Application",
        message:dealerForm.showroom_name+" has applied to list cars on CCC."
      })))
      toast.success("Application submitted! We will contact you within 24 hours.")
      setDealerStatus("pending")
      setShowDealerForm(false)
    } catch(e) { toast.error(e.message) }
    finally { setSubmittingDealer(false) }
  }

  async function save(e) {
    e.preventDefault()
    if (!form.brand||!form.model||!form.price||!form.showroom_name||!form.showroom_location) {
      return toast.error("Brand, model, price and showroom details required")
    }
    setSaving(true)
    try {
      const payload = {
        dealer_id: user.id,
        brand: form.brand,
        model: form.model,
        variant: form.variant||null,
        year: Number(form.year),
        body_type: form.body_type,
        engine_cc: form.engine_cc?Number(form.engine_cc):null,
        transmission: form.transmission,
        fuel_type: form.fuel_type,
        drive_type: form.drive_type,
        color: form.color||null,
        interior_color: form.interior_color||null,
        seats: Number(form.seats)||5,
        doors: Number(form.doors)||4,
        price: Number(form.price),
        discount_price: form.discount_price?Number(form.discount_price):null,
        price_negotiable: form.price_negotiable,
        description: form.description||null,
        features: form.features ? form.features.split(",").map(f=>f.trim()).filter(Boolean) : [],
        photos: form.photos,
        video_url: form.video_url||null,
        showroom_name: form.showroom_name,
        showroom_location: form.showroom_location,
        showroom_phone: form.showroom_phone||null,
        showroom_email: form.showroom_email||null,
        stock_count: Number(form.stock_count)||1,
        listing_fee_amount: fees.listing_fee,
        updated_at: new Date().toISOString()
      }

      if (editing) {
        await supabase.from("new_car_listings").update(payload).eq("id",editing).eq("dealer_id",user.id)
        toast.success("Listing updated!")
      } else {
        await supabase.from("new_car_listings").insert(payload)
        toast.success("Listing created! Pay the listing fee to activate it.")
      }
      setShowForm(false); setEditing(null); setForm(EMPTY); load()
    } catch(e) { toast.error(e.message) }
    finally { setSaving(false) }
  }
  async function payListingFee(listing) {
    try {
      const { data, error } = await supabase.functions.invoke("daraja-stk-push", {
        body: {
          amount: fees.listing_fee,
          booking_id: listing.id,
          customer_id: user.id,
          phone: listing.showroom_phone||profile?.phone||"",
          service_name: `New car listing fee - ${listing.brand} ${listing.model}`
        }
      })
      if(error) throw error
      if(data?.success) toast.success("STK Push sent! Check your phone for M-Pesa prompt.")
      else toast.error("Payment initiation failed. Please try again.")
    } catch(e) { toast.error(e.message) }
  }
  async function payFeatureFee(listing, tier) {
    const tierAmounts = { day: fees.featured_day, week: fees.featured_week, month: fees.featured_month }
    const tierDays = { day: 1, week: 7, month: 30 }
    const amount = tierAmounts[tier]
    try {
      // Create the payment record FIRST and use ITS id as the payment reference, not the
      // listing's own id - the listing fee, feature fee, and lead fee all reference the same
      // listing otherwise, making it impossible for the payment callback to tell which one a
      // given confirmation is actually for. Also stopped marking is_featured true immediately
      // after merely sending the STK push - a customer could cancel or never enter their PIN
      // and still get the featured boost for free, since nothing had confirmed the money moved.
      const { data: payRecord, error: payRecErr } = await supabase.from("featured_payments").insert({
        listing_id: listing.id, seller_id: user.id, amount, weeks: tierDays[tier]/7, status: "pending"
      }).select("id").single()
      if (payRecErr) throw payRecErr
      const { data, error } = await supabase.functions.invoke("daraja-stk-push", {
        body: {
          amount,
          booking_id: payRecord.id,
          customer_id: user.id,
          phone: listing.showroom_phone||profile?.phone||"",
          service_name: `Feature listing (${tier}) - ${listing.brand} ${listing.model}`
        }
      })
      if(error) throw error
      if(data?.success) toast.success("STK Push sent! Check your phone for M-Pesa prompt.")
      else toast.error("Payment initiation failed. Please try again.")
    } catch(e) { toast.error(e.message) }
  }

  async function payLeadFee(enquiry) {
    try {
      const { data, error } = await supabase.functions.invoke("daraja-stk-push", {
        body: {
          booking_id: enquiry.id,
          amount: fees.lead_fee,
          phone: profile?.phone || "",
          account_ref: enquiry.id.substring(0,12),
          description: `Lead fee - ${enquiry.customer_name}`
        }
      })
      if(error) throw error
      // No longer marking lead_fee_paid here - only the real payment callback should do
      // that, once Safaricom genuinely confirms the money moved, not just because a prompt was sent.
      if(data?.success) toast.success("STK Push sent! Check your phone ≡ƒô▒")
      else toast.error("Payment failed. Try again.")
    } catch(e) { toast.error(e.message) }
  }
  async function deleteListing(id) {
    if (!confirm("Delete this listing?")) return
    await supabase.from("new_car_listings").delete().eq("id",id).eq("dealer_id",user.id)
    toast.success("Listing deleted")
    load()
  }

