                          Feature 1 day - KES {fees.featured_day.toLocaleString()}
                        </button>
                        <button onClick={()=>payFeatureFee(l,"week")} style={{ background:"#faf5ff", border:"1px solid #8b5cf640", borderRadius:7, color:"#8b5cf6", fontSize:11, fontWeight:700, padding:"5px 12px", cursor:"pointer" }}>
                          Feature 1 week - KES {fees.featured_week.toLocaleString()}
                        </button>
                        <button onClick={()=>payFeatureFee(l,"month")} style={{ background:"#faf5ff", border:"1px solid #8b5cf640", borderRadius:7, color:"#8b5cf6", fontSize:11, fontWeight:700, padding:"5px 12px", cursor:"pointer" }}>
                          Feature 1 month - KES {fees.featured_month.toLocaleString()}
                        </button>
                      </>
                    )}
                    <button onClick={()=>startEdit(l)} style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>Edit</button>
                    <button onClick={()=>deleteListing(l.id)} style={{ background:"none", border:"1px solid #e24b4a30", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>Delete</button>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Enquiries tab */}
      {tab==="enquiries"&&(
        <div>
          {enquiries.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No enquiries yet</div>}
          {enquiries.map(e=>(
            <div key={e.id} style={{ background:"#f8f8f8", border:`1px solid ${e.status==="new"?"#e24b4a20":"#eeeeee"}`, borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:600, color:"#000" }}>{e.customer_name}</div>
                  <div style={{ fontSize:11, color:"#888" }}>≡ƒô₧ {e.customer_phone} {e.customer_email?`┬╖ Γ£ë∩╕Å ${e.customer_email}`:""}</div>
                  <div style={{ fontSize:11, color:"#888", display:"flex", alignItems:"center", gap:3 }}><VehicleIcon size={11} color="#888"/> {e.new_car_listings?.year} {e.new_car_listings?.brand} {e.new_car_listings?.model}</div>
                  <div style={{ fontSize:10, color:"#888" }}>{e.enquiry_type?.replace(/_/g," ")} ┬╖ Prefers: {e.preferred_contact}</div>
                  {e.message&&<div style={{ fontSize:11, color:"#555", marginTop:4, fontStyle:"italic" }}>&quot;{e.message}&quot;</div>}
                  <div style={{ fontSize:10, color:"#aaa", marginTop:4 }}>{new Date(e.created_at).toLocaleString()}</div>
                </div>
                <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:e.status==="new"?"#fff5f5":e.status==="contacted"?"#eff6ff":e.status==="converted"?"#f0fdf4":"#f5f5f5", color:e.status==="new"?"#e24b4a":e.status==="contacted"?"#378add":e.status==="converted"?"#1d9e75":"#888", fontWeight:600 }}>
                  {e.status}
                </span>
              </div>
              <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                {e.status==="new"&&<button onClick={()=>updateEnquiryStatus(e.id,"contacted")} style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:11, padding:"4px 10px", cursor:"pointer" }}>Γ£ô Mark contacted</button>}
                {e.status==="contacted"&&<button onClick={()=>updateEnquiryStatus(e.id,"converted")} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"4px 10px", cursor:"pointer" }}>≡ƒÄë Mark sold</button>}
                {e.customer_phone&&<a href={`tel:${e.customer_phone}`} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"4px 10px", textDecoration:"none" }}>≡ƒô₧ Call</a>}
                {e.customer_phone&&<a href={`https://wa.me/254${e.customer_phone.replace(/^0/,"")}`} target="_blank" rel="noreferrer" style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"4px 10px", textDecoration:"none" }}>≡ƒÆÜ WhatsApp</a>}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { useEffect, useState, useRef } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const BODY_TYPES = [
  { key:"all", label:"All", icon:"≡ƒÜù" },
  { key:"sedan", label:"Sedan", icon:"≡ƒÜù" },
  { key:"suv", label:"SUV", icon:"≡ƒÜÖ" },
  { key:"hatchback", label:"Hatchback", icon:"≡ƒÜÿ" },
  { key:"pickup", label:"Pickup", icon:"≡ƒ¢╗" },
  { key:"van", label:"Van", icon:"≡ƒÜÉ" },
  { key:"crossover", label:"Crossover", icon:"≡ƒÜÖ" },
  { key:"coupe", label:"Coupe", icon:"≡ƒÅÄ∩╕Å" },
  { key:"convertible", label:"Convertible", icon:"≡ƒÜÿ" },
  { key:"minivan", label:"Minivan", icon:"≡ƒÜÉ" },
  { key:"wagon", label:"Wagon", icon:"≡ƒÜù" },
]

export default function NewCarMarketplace() {
  const { user, profile } = useAuth()
  const isMobile = useIsMobile()
  const [cars, setCars] = useState([])
  const [brands, setBrands] = useState([])
  const [loading, setLoading] = useState(true)
  const [bodyType, setBodyType] = useState("all")
  const [selectedBrand, setSelectedBrand] = useState("all")
  const [search, setSearch] = useState("")
  const [sortBy, setSortBy] = useState("featured")
  const [selected, setSelected] = useState(null)
  const [lightbox, setLightbox] = useState({ open:false, photos:[], index:0 })
  const [activePhoto, setActivePhoto] = useState(0)
  const [tab, setTab] = useState("browse") // browse, my_listings
  const [enquiryForm, setEnquiryForm] = useState({ name:"", phone:"", email:"", message:"", enquiry_type:"general", preferred_contact:"phone" })
  const [submittingEnquiry, setSubmittingEnquiry] = useState(false)
  const [showEnquiry, setShowEnquiry] = useState(false)
  const [showDealerReg, setShowDealerReg] = useState(false)
  const [dealerForm, setDealerForm] = useState({ showroom_name:"", showroom_location:"", showroom_phone:"", showroom_email:"", business_registration:"", brands_sold:"", monthly_stock:"", website_url:"" })
  const [submittingDealer, setSubmittingDealer] = useState(false)
  const featuredRef = useRef(null)

  useEffect(() => { load() }, [])

  async function load() {
    const [{ data: carData }, { data: brandData }] = await Promise.all([
      supabase.from("new_car_listings").select("*, dealer:profiles!new_car_listings_dealer_id_fkey(first_name,last_name,avatar_url)").eq("is_active", true).eq("listing_fee_paid", true).order("is_featured", { ascending:false }).order("created_at", { ascending:false }),
      supabase.from("car_brands").select("*").order("display_order")
    ])
    setCars(carData||[])
    setBrands(brandData||[])
    setLoading(false)
  }

  async function submitEnquiry() {
    if (!enquiryForm.name||!enquiryForm.phone) return toast.error("Name and phone required")
    if (!user) return toast.error("Please login to enquire")
    setSubmittingEnquiry(true)
    try {
      await supabase.from("car_enquiries").insert({
        listing_id: selected.id,
        customer_id: user.id,
        dealer_id: selected.dealer_id,
        customer_name: enquiryForm.name,
        customer_phone: enquiryForm.phone,
        customer_email: enquiryForm.email,
        message: enquiryForm.message,
        enquiry_type: enquiryForm.enquiry_type,
        preferred_contact: enquiryForm.preferred_contact,
      })
      // Notify dealer
      await supabase.from("notifications").insert({
        user_id: selected.dealer_id,
        title: "New car enquiry! ≡ƒÜù",
        message: `${enquiryForm.name} is interested in your ${selected.year} ${selected.brand} ${selected.model}. Phone: ${enquiryForm.phone}`,
        type: "success"
      })
      // Increment enquiry count
      await supabase.from("new_car_listings").update({ enquiries: (selected.enquiries||0)+1 }).eq("id", selected.id)
      toast.success("Enquiry sent! The dealer will contact you shortly.")
      setShowEnquiry(false)
      setEnquiryForm({ name:"", phone:"", email:"", message:"", enquiry_type:"general", preferred_contact:"phone" })
    } catch(e) { toast.error(e.message) }
    finally { setSubmittingEnquiry(false) }
  }

  async function submitDealerApplication() {
    if (!dealerForm.showroom_name||!dealerForm.showroom_location||!dealerForm.showroom_phone) return toast.error("Showroom name, location and phone required")
    if (!user) return toast.error("Please login to register as a dealer")
    setSubmittingDealer(true)
    try {
      await supabase.from("dealer_applications").insert({
        user_id: user.id,
        showroom_name: dealerForm.showroom_name,
        showroom_location: dealerForm.showroom_location,
        showroom_phone: dealerForm.showroom_phone,
        showroom_email: dealerForm.showroom_email||null,
        business_registration: dealerForm.business_registration||null,
        brands_sold: dealerForm.brands_sold ? dealerForm.brands_sold.split(",").map(b=>b.trim()).filter(Boolean) : [],
        monthly_stock: dealerForm.monthly_stock ? Number(dealerForm.monthly_stock) : null,
        website_url: dealerForm.website_url||null,
      })
      // Notify admin
      const { data: admins } = await supabase.from("profiles").select("id").eq("role","admin").limit(1)
      if (admins?.[0]) {
        await supabase.from("notifications").insert({
          user_id: admins[0].id,
          title: "New dealer application! ≡ƒÅó",
          message: `${dealerForm.showroom_name} from ${dealerForm.showroom_location} has applied to list cars on CCC. Phone: ${dealerForm.showroom_phone}`,
          type: "info"
        })
      }
      toast.success("Application submitted! We will contact you within 24 hours.")
      setShowDealerReg(false)
      setDealerForm({ showroom_name:"", showroom_location:"", showroom_phone:"", showroom_email:"", business_registration:"", brands_sold:"", monthly_stock:"", website_url:"" })
    } catch(e) { toast.error(e.message) }
    finally { setSubmittingDealer(false) }
  }

  async function incrementView(car) {
    setSelected(car)
    await supabase.from("new_car_listings").update({ views:(car.views||0)+1 }).eq("id", car.id)
  }

  const featured = cars.filter(c=>c.is_featured)
  const newArrivals = [...cars].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).slice(0,8)

  const filtered = cars.filter(c => {
    const matchBody = bodyType==="all" || c.body_type===bodyType
    const matchBrand = selectedBrand==="all" || c.brand===selectedBrand
    const matchSearch = !search || `${c.brand} ${c.model} ${c.variant||""} ${c.showroom_name}`.toLowerCase().includes(search.toLowerCase())
    return matchBody && matchBrand && matchSearch
  }).sort((a,b) => {
    if (sortBy==="price_asc") return Number(a.price)-Number(b.price)
    if (sortBy==="price_desc") return Number(b.price)-Number(a.price)
    if (sortBy==="newest") return new Date(b.created_at)-new Date(a.created_at)
    if (sortBy==="enquiries") return (b.enquiries||0)-(a.enquiries||0)
    return (b.is_featured?1:0)-(a.is_featured?1:0)
  })

  const inp = { width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"10px 12px", color:"#000", fontSize:13, outline:"none", fontFamily:"DM Sans,sans-serif", marginBottom:10 }
  const lbl = { fontSize:11, color:"#666", textTransform:"uppercase", display:"block", marginBottom:4 }

  if (selected) return (
    <div>
      <button onClick={()=>{ setSelected(null); setShowEnquiry(false) }} style={{ background:"none", border:"none", color:"#e6821e", cursor:"pointer", fontSize:13, marginBottom:"1rem", padding:0, fontFamily:"DM Sans,sans-serif" }}>
      {/* Lightbox */}
      {lightbox.open&&(
        <div onClick={()=>setLightbox({open:false,photos:[],index:0})}
          style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.95)", zIndex:1000, display:"flex", alignItems:"center", justifyContent:"center", flexDirection:"column" }}>
          <button onClick={()=>setLightbox({open:false,photos:[],index:0})}
            style={{ position:"absolute", top:16, right:16, background:"rgba(255,255,255,0.2)", border:"none", borderRadius:"50%", width:40, height:40, color:"#fff", fontSize:20, cursor:"pointer" }}>x</button>
          <img src={lightbox.photos[lightbox.index]} alt=""
            onClick={e=>e.stopPropagation()}
            style={{ maxWidth:"95vw", maxHeight:"80vh", objectFit:"contain", borderRadius:8 }}/>
          {lightbox.photos.length>1&&(
            <div style={{ display:"flex", gap:8, marginTop:12 }}>
              <button onClick={e=>{e.stopPropagation();setLightbox(l=>({...l,index:Math.max(0,l.index-1)}))}}
                style={{ background:"rgba(255,255,255,0.2)", border:"none", borderRadius:8, color:"#fff", padding:"8px 16px", cursor:"pointer", fontSize:18 }}>prev</button>
              <span style={{ color:"#fff", fontSize:13, alignSelf:"center" }}>{lightbox.index+1}/{lightbox.photos.length}</span>
              <button onClick={e=>{e.stopPropagation();setLightbox(l=>({...l,index:Math.min(l.photos.length-1,l.index+1)}))}}
                style={{ background:"rgba(255,255,255,0.2)", border:"none", borderRadius:8, color:"#fff", padding:"8px 16px", cursor:"pointer", fontSize:18 }}>next</button>
            </div>
          )}
          <div style={{ display:"flex", gap:6, marginTop:12, overflowX:"auto", maxWidth:"95vw" }}>
            {lightbox.photos.map((p,i)=>(
              <img key={i} src={p} alt="" onClick={e=>{e.stopPropagation();setLightbox(l=>({...l,index:i}))}}
                style={{ width:60, height:45, objectFit:"cover", borderRadius:6, cursor:"pointer", border:lightbox.index===i?"2px solid #e6821e":"2px solid transparent", flexShrink:0 }}/>
            ))}
          </div>
        </div>
