              { icon:"≡ƒöä", label:"Transmission", value:selected.transmission?.replace(/_/g," ")||"ΓÇö" },
              { icon:"Γ¢╜", label:"Fuel", value:selected.fuel_type||"ΓÇö" },
              { icon:"≡ƒÜù", label:"Drive", value:selected.drive_type?.toUpperCase()||"ΓÇö" },
