                {selected.features.map((f,i)=>(
                  <span key={i} style={{ fontSize:11, background:"#f0fdf4", color:"#1d9e75", padding:"4px 10px", borderRadius:20, border:"1px solid #1d9e7530" }}>Γ£ô {f}</span>
