          "Authorization": "Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdjbmVmbnF0anh0cWJoeW55b3hlIiwicm9sZSI6ImFub24iLCJpYXQiOjE3Nzk2MDg0MzIsImV4cCI6MjA5NTE4NDQzMn0.Ybyce3psBj2I-hdoF95H5UAklr6hsgQi-mciI9uMIgc"
        },
        body: JSON.stringify({ booking_id: job.id })
      }).catch(e => console.warn("Next driver assignment error:", e.message))

      toast.success("Job declined ΓÇö next driver will be notified")
      load()
    } catch(e) { toast.error(e.message) }
  }

    async function load() {
    if (profile?.driver_category !== "concierge") { setJobs([]); setLoading(false); return }
    const [{ data: jobs }, { data: status }] = await Promise.all([
      supabase.from("bookings")
        .select("*, vehicles(make,model,year,license_plate,color), profiles!bookings_customer_id_fkey(first_name,last_name,city,latitude,longitude), provider:profiles!bookings_provider_id_fkey(first_name,last_name,business_name,city,address), concierge_current_driver_id, concierge_attempt, concierge_attempt_expires_at, concierge_pickup_location, concierge_surcharge")
        .eq("is_concierge", true)
        .eq("status", "confirmed")
        .is("driver_id", null)
        .order("created_at", { ascending:false }),
      supabase.from("driver_status").select("*").eq("driver_id", user.id).maybeSingle(),
    ])
    setJobs(jobs||[])
    setDriverStatus(status)
    setLoading(false)
  }

  async function acceptJob(job) {
    if (!driverStatus?.is_online) return toast.error("You must be online to accept jobs. Go to Overview and toggle online.")
    if (!profile?.documents_verified) return toast.error("Your documents must be verified before accepting jobs.")
    setAccepting(job.id)
    try {
      const { data: check } = await supabase.from("bookings").select("driver_id").eq("id", job.id).single()
      if (check?.driver_id) {
        toast.error("This job was just taken by another driver")
        load()
        return
      }
      // Fetch concierge surcharge rate from app_settings
      const { data: surchargeRow } = await supabase.from("app_settings").select("value").eq("key","concierge_surcharge_rate").maybeSingle()
      const surchargeRate = surchargeRow ? Number(surchargeRow.value)/100 : 0.15
      const driverEarnings = Number(job.concierge_surcharge||0) // use the value already correctly calculated at booking creation, not a fresh recalculation

      const { error } = await supabase.from("bookings").update({
        driver_id: user.id,
        driver_accepted_at: new Date().toISOString(),
        concierge_status: "accepted",
        status: "driver-assigned",
        driver_earnings: driverEarnings,
      }).eq("id", job.id).is("driver_id", null)
      if (error) throw error

      await supabase.from("driver_status").update({ current_booking_id:job.id }).eq("driver_id", user.id)

      await supabase.from("notifications").insert([
        {
          user_id: job.customer_id,
          title: "Driver assigned! ≡ƒÜù",
          message: `A driver has been assigned to your booking: ${job.service_name}. They will contact you shortly.`,
          type: "success",
        },
        {
          user_id: job.provider_id,
          title: "Driver accepted concierge ≡ƒÜù",
          message: `A driver has accepted the concierge request for booking ${job.booking_number}.`,
          type: "info",
        }
      ])

      toast.success("Job accepted! Customer notified ≡ƒÜù")
      load()
    } catch(err) {
      toast.error(err.message)
    } finally {
      setAccepting(null)
    }
  }

  function formatCountdown(ms) {
    if (!ms || ms <= 0) return "Expired"
    const mins = Math.floor(ms / 60000)
    const secs = Math.floor((ms % 60000) / 1000)
    return `${mins}:${secs.toString().padStart(2,"0")}`
  }

  const isOnline = driverStatus?.is_online
  const isVerified = profile?.documents_verified

  return (
    <div>
      {/* Status banner */}
      {!isOnline&&(
        <div style={{ background:"#fff5f5", border:"1px solid #e24b4a30", borderRadius:10, padding:"0.9rem", marginBottom:"1.25rem" }}>
          <div style={{ fontSize:13, color:"#e24b4a", fontWeight:600, marginBottom:2, display:"flex", alignItems:"center", gap:4 }}><WarningIcon size={13} color="#e24b4a"/> You are offline</div>
          <div style={{ fontSize:11, color:"#666" }}>Go to Overview and toggle online to accept jobs.</div>
        </div>
      )}

      {!isVerified&&(
        <div style={{ background:"#fff8f0", border:"1px solid #e6821e30", borderRadius:10, padding:"0.9rem", marginBottom:"1.25rem" }}>
          <div style={{ fontSize:13, color:"#e6821e", fontWeight:600, marginBottom:2 }}>ΓÜá∩╕Å Documents not verified</div>
          <div style={{ fontSize:11, color:"#666" }}>Complete your credentials in Profile and wait for admin verification.</div>
        </div>
      )}

      {isOnline&&isVerified&&(
        <div style={{ background:"#f0fdf4", border:"1px solid #1d9e7530", borderRadius:10, padding:"0.9rem", marginBottom:"1.25rem" }}>
          <div style={{ display:"flex", alignItems:"center", gap:6 }}>
            <div style={{ width:7, height:7, borderRadius:"50%", background:"#1d9e75", boxShadow:"0 0 6px #1d9e75" }}/>
            <div style={{ fontSize:13, color:"#1d9e75", fontWeight:600 }}>Online ΓÇö {jobs.length} job{jobs.length!==1?"s":""} available</div>
          </div>
        </div>
      )}

      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:18, fontWeight:800, color:"#000000", marginBottom:4 }}>Available Jobs</div>
      <div style={{ fontSize:12, color:"#777777", marginBottom:"1.25rem" }}>Concierge pickup and delivery requests</div>

      {loading&&<div style={{ color:"#777777", fontSize:13 }}>Loading...</div>}
      {!loading&&jobs.length===0&&(
        <div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"3rem" }}>
          <div style={{ fontSize:32, marginBottom:10 }}>≡ƒÜù</div>
          <div style={{ marginBottom:6 }}>{profile?.driver_category!=="concierge"?"Concierge jobs are for concierge drivers only":"No available jobs right now"}</div>
          <div style={{ fontSize:11, color:"#555555" }}>{profile?.driver_category!=="concierge"?"Your account is registered for marketplace/delivery jobs":"New concierge requests will appear here automatically"}</div>
        </div>
      )}

      {jobs.map(job=>{
        const vehicle = job.vehicles
        const customer = job.profiles
        const earnings = Number(job.concierge_surcharge||0)
        return (
          <div key={job.id} style={{ background:"#ffffff", border:"1px solid #1d9e7520", borderRadius:12, padding:isMobile?"1rem":"1.25rem", marginBottom:12 }}>
            {/* Header */}
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:12 }}>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4 }}>
                  <span style={{ fontSize:18 }}>≡ƒÜù</span>
                  <div style={{ fontFamily:"Syne", fontSize:isMobile?14:15, fontWeight:800, color:"#000000" }}>{job.service_name}</div>
                </div>
                <div style={{ fontSize:11, color:"#777777" }}>#{job.booking_number} ┬╖ {job.booking_date} ┬╖ {job.booking_time?.slice(0,5)}</div>
              </div>
              <div style={{ textAlign:"right", flexShrink:0 }}>
                <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, color:"#1d9e75" }}>KES {earnings.toFixed(0)}</div>
                <div style={{ fontSize:10, color:"#777777" }}>your earnings</div>
              </div>
            </div>

            {/* Vehicle info */}
            {vehicle&&(
              <div style={{ background:"#ffffff", borderRadius:10, padding:"0.9rem", marginBottom:10, border:"1px solid #eeeeee" }}>
                <div style={{ fontSize:10, color:"#777777", textTransform:"uppercase", marginBottom:6 }}>Vehicle to transport</div>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
                  <div>
                    <div style={{ fontSize:12, color:"#000000", fontWeight:600 }}>{vehicle.make} {vehicle.model} {vehicle.year}</div>
                    <div style={{ fontSize:11, color:"#777777", marginTop:2 }}>Plate: {vehicle.license_plate}</div>
                  </div>
                  <div>
                    {vehicle.color&&<div style={{ fontSize:11, color:"#777777" }}>Color: {vehicle.color}</div>}
                  </div>
                </div>
              </div>
            )}

            {/* Customer & location info */}
            <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"1fr 1fr", gap:8, marginBottom:12 }}>
              <div style={{ background:"#ffffff", borderRadius:8, padding:"0.75rem", border:"1px solid #eeeeee" }}>
                <div style={{ fontSize:10, color:"#777777", marginBottom:4 }}>Customer</div>
                <div style={{ fontSize:12, color:"#000000" }}>{customer?.first_name} {customer?.last_name}</div>
                {customer?.city&&<div style={{ fontSize:11, color:"#777777", marginTop:2 }}>≡ƒôì {customer.city}</div>}
              </div>
              <div style={{ background:"#ffffff", borderRadius:8, padding:"0.75rem", border:"1px solid #eeeeee" }}>
                <div style={{ fontSize:10, color:"#777777", marginBottom:4 }}>Service total</div>
                <div style={{ fontSize:12, color:"#e6821e", fontWeight:600 }}>KES {Number(job.total_amount||0).toLocaleString()}</div>
                <div style={{ fontSize:10, color:"#777777", marginTop:2 }}>Payment: {job.payment_method||"ΓÇö"}</div>
              </div>
            </div>

            {/* Pickup & Dropoff locations */}
            <div style={{ display:"grid", gridTemplateColumns:"1fr", gap:8, marginBottom:12 }}>
              {job.concierge_pickup_location&&(
                <div style={{ background:"#fff8f0", border:"1px solid #e6821e30", borderRadius:8, padding:"0.75rem" }}>
                  <div style={{ fontSize:10, color:"#e6821e", fontWeight:600, marginBottom:4 }}>≡ƒôì PICKUP ΓÇö Go here first</div>
                  <div style={{ fontSize:12, color:"#000", fontWeight:600 }}>{job.concierge_pickup_location}</div>
                  {(job.customer_location_lat&&job.customer_location_lng)||(customer?.latitude&&customer?.longitude)?(
                    <a href={`https://www.google.com/maps/dir/?api=1&destination=${job.customer_location_lat||customer?.latitude},${job.customer_location_lng||customer?.longitude}`} target="_blank" rel="noreferrer"
                      style={{ fontSize:11, color:"#e6821e", textDecoration:"none", display:"block", marginTop:4 }}>
                      <LocationIcon size={11} color="#e6821e"/> Open in Google Maps
                    </a>
                  ):null}
                </div>
              )}
              {job.provider&&(
                <div style={{ background:"#eff6ff", border:"1px solid #378add30", borderRadius:8, padding:"0.75rem" }}>
                  <div style={{ fontSize:10, color:"#378add", fontWeight:600, marginBottom:4 }}>≡ƒöº DROPOFF ΓÇö Take car here</div>
                  <div style={{ fontSize:12, color:"#000", fontWeight:600 }}>{job.provider?.business_name||job.provider?.first_name}</div>
                  {job.provider?.address&&<div style={{ fontSize:11, color:"#555", marginTop:2 }}>≡ƒôì {job.provider.address}</div>}
                  {job.provider?.city&&<div style={{ fontSize:11, color:"#777", marginTop:2 }}>{job.provider.city}</div>}
                </div>
              )}
            </div>

            {/* Problem description */}
            {job.problem_description&&(
              <div style={{ background:"#ffffff", borderRadius:8, padding:"0.75rem", marginBottom:10, border:"1px solid #eeeeee" }}>
                <div style={{ fontSize:10, color:"#777777", marginBottom:4 }}>Problem description</div>
                <div style={{ fontSize:12, color:"#555555", fontStyle:"italic" }}>&quot;{job.problem_description}&quot;</div>
              </div>
            )}

            {/* Notes */}
            {job.notes&&(
              <div style={{ fontSize:11, color:"#666", fontStyle:"italic", marginBottom:10 }}>Note: &quot;{job.notes}&quot;</div>
            )}

            {/* Priority indicator - show when this driver is the current target */}
            {job.concierge_current_driver_id===user?.id&&(
              <div style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:8, padding:"0.6rem 0.75rem", marginBottom:10, display:"flex", alignItems:"center", justifyContent:"space-between" }}>
                <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                  <span style={{ fontSize:14 }}>ΓÅ░</span>
                  <div>
                    <div style={{ fontSize:12, color:"#e6821e", fontWeight:600 }}>You have been selected!</div>
                    <div style={{ fontSize:10, color:"#888" }}>Accept or decline within the time limit</div>
                  </div>
                </div>
                <div style={{ textAlign:"center", background:"#e6821e", borderRadius:8, padding:"6px 10px", minWidth:52 }}>
                  <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, color:"#fff" }}>{formatCountdown(countdowns[job.id])}</div>
                  <div style={{ fontSize:8, color:"rgba(255,255,255,0.8)", textTransform:"uppercase" }}>remaining</div>
                </div>
              </div>
            )}

            {/* Accept/Decline buttons */}
            <div style={{ display:"flex", gap:8 }}>
              <button
                onClick={()=>acceptJob(job)}
                disabled={accepting===job.id||!isOnline||!isVerified}
                style={{
                  flex:2,
                  background:accepting===job.id||!isOnline||!isVerified?"#ffffff":"#1d9e75",
                  border:`1px solid ${accepting===job.id||!isOnline||!isVerified?"#555555":"#1d9e75"}`,
                  borderRadius:10, color:accepting===job.id||!isOnline||!isVerified?"#444":"#fff",
                  fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700,
                  padding:"13px", cursor:accepting===job.id||!isOnline||!isVerified?"not-allowed":"pointer",
                  transition:"all 0.15s",
                }}>
                {accepting===job.id?"Accepting...":"Γ£ô Accept this job"}
              </button>
              {job.concierge_current_driver_id===user?.id&&(
                <button
                  onClick={()=>declineJob(job)}
                  style={{
                    flex:1, background:"none",
                    border:"1px solid #e24b4a40", borderRadius:10,
                    color:"#e24b4a", fontSize:13, fontWeight:600,
                    padding:"13px", cursor:"pointer"
                  }}>
                  Γ£ù Decline
                </button>
              )}
            </div>
          </div>
        )
      })}
    </div>
  )
}

import { useEffect, useState, useRef } from "react"
import { ChatIcon, MarketplaceIcon, VehicleIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import ChatWindow from "../shared/ChatWindow"

export default function DriverChat() {
  const { user, profile } = useAuth()
  const isConcierge = profile?.driver_category === "concierge"
  const isMobile = useIsMobile()
  const [conversations, setConversations] = useState([])
  const [selected, setSelected] = useState(null)
  const [menuFor, setMenuFor] = useState(null)
  const [hidden, setHidden] = useState([])
  const longPressRef = useRef(null)

  function startLongPress(key) {
    longPressRef.current = setTimeout(() => setMenuFor(key), 500)
  }
  function cancelLongPress() { clearTimeout(longPressRef.current) }

  async function markAllRead(c) {
    const col = c.bookingId ? "booking_id" : "listing_id"
    const val = c.bookingId || c.listingId
    if (!val) return
    await supabase.from("chat_messages").update({ is_read:true }).eq(col, val).eq("receiver_id", user.id)
    setConversations(prev => prev.map(x => x.id===c.id ? {...x, unread:0} : x))
    setMenuFor(null)
  }

  async function markAllRead(c) {
    const col = c.bookingId ? "booking_id" : "listing_id"
    const val = c.bookingId || c.listingId
    if (!val) return
    await supabase.from("chat_messages").update({ is_read:true }).eq(col, val).eq("receiver_id", user.id)
    setConversations(prev => prev.map(x => x.id===c.id ? {...x, unread:0} : x))
    setMenuFor(null)
  }

  async function deleteConversation(c) {
    const col = c.bookingId ? "booking_id" : "listing_id"
    const val = c.bookingId || c.listingId
    // Hide instantly from UI
    setConversations(prev => prev.filter(x => (x.bookingId||x.listingId) !== val))
    setHidden(prev => [...prev, val])
    setMenuFor(null)
    // Delete from DB in background
    supabase.from("chat_messages").delete().eq(col, val).then(({error}) => { if(error) console.error("Delete failed:", error.message) })
    const hidePayload = { user_id: user.id }
    hidePayload[col] = val
    supabase.from("hidden_conversations").upsert(hidePayload, { onConflict: "user_id,"+col }).then(({error}) => { if(error) console.error("Hide failed:", error.message) })
  }

  async function markAllRead(c) {
    const col = c.bookingId ? "booking_id" : "listing_id"
    const val = c.bookingId || c.listingId
    await supabase.from("chat_messages").update({ is_read:true })
      .eq(col, val).eq("receiver_id", user.id)
    setConversations(prev => prev.map(x => (x.bookingId||x.listingId)===val ? {...x, unread:0} : x))
    setMenuFor(null)
  }
  const [loading, setLoading] = useState(true)
  const [tab, setTab] = useState("all")

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("driver-chat-list")
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"chat_messages", filter:`receiver_id=eq.${user.id}` }, () => load())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function load() {
    const { data: hiddenData } = await supabase.from("hidden_conversations").select("booking_id,listing_id").eq("user_id", user.id)
    const hiddenKeys = (hiddenData||[]).map(h => h.booking_id || h.listing_id)
    setHidden(hiddenKeys)
    const convos = []

    // Booking conversations
    const { data: bookings } = await supabase.from("bookings")
      .select("id,service_name,customer_id,status,booking_date")
      .eq("driver_id", user.id)
      .order("created_at", { ascending:false })

    if (bookings?.length) {
      const customerIds = [...new Set(bookings.map(b=>b.customer_id))]
      const { data: profs } = await supabase.from("profiles")
        .select("id,first_name,last_name").in("id", customerIds)
      const { data: lastMessages } = await supabase.from("chat_messages")
        .select("booking_id,message,created_at,sender_id,is_read,receiver_id")
        .in("booking_id", bookings.map(b=>b.id))
        .order("created_at", { ascending:false })

      bookings.forEach(b=>{
        const profile = profs?.find(p=>p.id===b.customer_id)
        const msgs = lastMessages?.filter(m=>m.booking_id===b.id)||[]
        const last = msgs[0]
        const unread = msgs.filter(m=>m.receiver_id===user.id&&!m.is_read).length
        convos.push({
          id: b.id,
          type: "booking",
          bookingId: b.id,
          listingId: null,
          otherUserId: b.customer_id,
          name: profile ? `${profile?.first_name} ${profile?.last_name}` : "Customer",
          subtitle: b.service_name,
          status: b.status,
          lastMessage: last?.message||"",
          lastTime: last?.created_at||b.booking_date,
          unread,
        })
      })
    }

    // Marketplace conversations
    const { data: marketMsgs } = await supabase.from("chat_messages")
      .select("*, marketplace_listings(title,seller_id), profiles!chat_messages_sender_id_fkey(first_name,last_name)")
      .not("listing_id", "is", null)
      .or(`sender_id.eq.${user.id},receiver_id.eq.${user.id}`)
      .order("created_at", { ascending:false })

    if (marketMsgs?.length) {
      const listingIds = [...new Set(marketMsgs.map(m=>m.listing_id))]
      listingIds.forEach(lid=>{
        const msgs = marketMsgs.filter(m=>m.listing_id===lid)
        const last = msgs[0]
        const otherUserId = last.sender_id===user.id ? last.receiver_id : last.sender_id
        const otherProfile = last.profiles
        const unread = msgs.filter(m=>m.receiver_id===user.id&&!m.is_read).length
        const existing = convos.find(c=>c.listingId===lid)
        if (!existing) {
          convos.push({
            id: lid,
            type: "marketplace",
            bookingId: null,
            listingId: lid,
            otherUserId,
            name: otherProfile ? `${otherProfile.first_name} ${otherProfile.last_name}` : "User",
            subtitle: last.marketplace_listings?.title||"Marketplace listing",
            status: "active",
            lastMessage: last.message||"",
            lastTime: last.created_at,
            unread,
          })
        }
      })
    }

    // Sort by latest message
    convos.sort((a,b)=>new Date(b.lastTime)-new Date(a.lastTime))
    setConversations(convos.filter(c => !hiddenKeys.includes(c.bookingId||c.listingId)))
    setLoading(false)
  }

  const filtered = tab==="marketplace"
    ? conversations.filter(c=>c.type==="marketplace")
    : tab==="jobs"
    ? conversations.filter(c=>c.type==="booking")
    : conversations

  const totalUnread = conversations.reduce((s,c)=>s+c.unread,0)

  return (
    <div style={{ display:"flex", gap:"1rem", height:isMobile?"auto":"calc(100vh - 140px)" }}>
      {/* Conversation list */}
      {(!isMobile||!selected)&&(
        <div style={{ width:isMobile?"100%":280, flexShrink:0, display:"flex", flexDirection:"column", gap:8 }}>
          <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, color:"#000000", marginBottom:4 }}>
            Messages
            {totalUnread>0&&<span style={{ marginLeft:8, background:"#e24b4a", color:"#fff", borderRadius:20, fontSize:11, padding:"2px 7px" }}>{totalUnread}</span>}
          </div>

          {/* Tabs */}
          <div style={{ display:"flex", gap:6, marginBottom:4 }}>
          {(isConcierge ? [{k:"all",l:"All"},{k:"jobs",l:"Jobs"}] : [{k:"all",l:"All"},{k:"jobs",l:"Jobs"},{k:"marketplace",l:"Marketplace"}]).map(t=>(
              <button key={t.k} onClick={()=>setTab(t.k)}
                style={{ padding:"5px 12px", borderRadius:7, border:"none", fontSize:11, cursor:"pointer", background:tab===t.k?"#1d9e75":"#555555", color:tab===t.k?"#fff":"#666", fontFamily:"'DM Sans',sans-serif" }}>
                {t.l}
              </button>
            ))}
          </div>

          {loading&&<div style={{ color:"#777777", fontSize:12 }}>Loading...</div>}
          {!loading&&filtered.length===0&&(
            <div style={{ color:"#888888", fontSize:12, textAlign:"center", padding:"2rem" }}>
              <div style={{ marginBottom:8, display:"flex", justifyContent:"center" }}><ChatIcon size={28} color="#e6821e"/></div>
              No conversations yet
            </div>
          )}

          {filtered.map(c=>(
            <div key={c.id} onClick={()=>setSelected(c)}
              style={{ background:selected?.id===c.id?"#f0fdf4":"#555555", border:`1px solid ${selected?.id===c.id?"#1d9e75":"#eeeeee"}`, borderRadius:10, padding:"0.75rem", cursor:"pointer" }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:4 }}>
                <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                  <div style={{ width:34, height:34, borderRadius:"50%", background:c.type==="marketplace"?"#fff8f0":"#f0fdf4", border:`1px solid ${c.type==="marketplace"?"#e6821e40":"#1d9e7540"}`, display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontSize:12, fontWeight:800, color:c.type==="marketplace"?"#e6821e":"#1d9e75", flexShrink:0 }}>
                    {c.name?.[0]?.toUpperCase()||"?"}
                  </div>
                  <div style={{ minWidth:0 }}>
                    <div style={{ fontSize:12, fontWeight:c.unread>0?700:500, color:"#000000", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{c.name}</div>
                    <div style={{ fontSize:10, color:"#777777", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                      {c.type==="marketplace"?"≡ƒ¢Æ ":""}{c.subtitle}
                    </div>
                  </div>
                </div>
                <div style={{ textAlign:"right", flexShrink:0 }}>
                  {c.unread>0&&<div style={{ background:"#1d9e75", color:"#fff", borderRadius:"50%", fontSize:9, fontWeight:800, width:16, height:16, display:"flex", alignItems:"center", justifyContent:"center", marginBottom:2 }}>{c.unread}</div>}
                  <div style={{ fontSize:9, color:"#888888" }}>{c.lastTime?new Date(c.lastTime).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}):""}</div>
                </div>
              </div>
              {c.lastMessage&&<div style={{ fontSize:11, color:"#777777", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{c.lastMessage}</div>}
              <div style={{ display:"flex", gap:6, marginTop:4, flexWrap:"wrap" }}>
                <span style={{ fontSize:9, padding:"1px 6px", borderRadius:6, background:c.type==="marketplace"?"#fff8f0":"#f0fdf4", color:c.type==="marketplace"?"#e6821e":"#1d9e75" }}>
                  {c.type==="marketplace"?<><MarketplaceIcon size={12} color="currentColor"/> Marketplace</>:<><VehicleIcon size={12} color="currentColor"/> Job</>}
                </span>
                {c.status&&<span style={{ fontSize:9, color:"#888888" }}>{c.status}</span>}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Chat window */}
      {selected?(
        <div style={{ flex:1, display:"flex", flexDirection:"column", minHeight:isMobile?400:0 }}>
          {isMobile&&(
            <button onClick={()=>setSelected(null)} style={{ background:"none", border:"none", color:"#1d9e75", cursor:"pointer", fontSize:13, marginBottom:8, padding:0, fontFamily:"'DM Sans',sans-serif", textAlign:"left" }}>
              ΓåÉ Back
            </button>
          )}
          <ChatWindow
            bookingId={selected.bookingId}
            listingId={selected.listingId}
            otherUserId={selected.otherUserId}
            otherUserName={selected.name}
            onClose={isMobile?null:()=>setSelected(null)}
          />
        </div>
      ):(
        !isMobile&&(
          <div style={{ flex:1, display:"flex", alignItems:"center", justifyContent:"center", color:"#888888", fontSize:13 }}>
            <div style={{ textAlign:"center" }}>
              <div style={{ marginBottom:10, display:"flex", justifyContent:"center" }}><ChatIcon size={40} color="#ccc"/></div>
              Select a conversation
            </div>
          </div>
        )
      )}
    </div>
  )
}

import { useEffect, useState, useRef } from "react"
import { ShieldIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import { validateFile, sanitizeFilePath } from "../../lib/uploadValidation"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import ClaimChat from "../shared/ClaimChat"
import toast from "react-hot-toast"

const SC = { pending:"#e6821e", under_review:"#378add", approved:"#1d9e75", rejected:"#e24b4a" }

const CLAIM_REASONS = [
  "Customer vehicle was in undisclosed poor condition",
  "Customer provided wrong pickup location deliberately",
  "Customer was abusive or threatening",
  "Customer had undisclosed vehicle damage before pickup",
  "Customer no-show after driver arrived",
  "Customer made false damage claim against driver",
  "Other",
]

export default function DriverClaims() {
  const { user, profile } = useAuth()
  const isMobile = useIsMobile()
  const [claims, setClaims] = useState([])
  const [filedClaims, setFiledClaims] = useState([])
  const [bookings, setBookings] = useState([])
  const [loading, setLoading] = useState(true)
  const [chatClaim, setChatClaim] = useState(null)
  const [tab, setTab] = useState("against")
  const [showForm, setShowForm] = useState(false)
  const [submitting, setSubmitting] = useState(false)
  const [evidencePhotos, setEvidencePhotos] = useState([])
  const [uploadingEvidence, setUploadingEvidence] = useState(false)
  const evidenceInputRef = useRef(null)
  const [form, setForm] = useState({ booking_id:"", reason:"", description:"" })

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("driver-claims-"+user.id)
      .on("postgres_changes", { event:"UPDATE", schema:"public", table:"service_claims", filter:`driver_id=eq.${user.id}` }, () => load())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function load() {
    setLoading(true)
    const [{ data: cls }, { data: filed }, { data: bks }] = await Promise.all([
      supabase.from("service_claims")
        .select("*, bookings(service_name,booking_number,booking_date,total_amount), customer:profiles!service_claims_customer_id_fkey(first_name,last_name)")
        .eq("driver_id", user.id).order("created_at", { ascending:false }),
      supabase.from("service_claims")
        .select("*, bookings(service_name,booking_number,booking_date), against:profiles!service_claims_against_id_fkey(first_name,last_name)")
        .eq("claimant_id", user.id).eq("claimant_type","driver").order("created_at", { ascending:false }),
      supabase.from("bookings")
        .select("id,service_name,booking_number,booking_date,customer_id,profiles!bookings_customer_id_fkey(first_name,last_name)")
        .eq("driver_id", user.id).eq("status","completed").order("created_at", { ascending:false }).limit(20)
    ])
    setClaims(cls||[])
    setFiledClaims(filed||[])
    setBookings(bks||[])
    setLoading(false)
  }

  async function uploadEvidencePhoto(file) {
    const _v = validateFile(file, "image")
    if (!_v.valid) { toast.error(_v.error); return }

    const ext = file.name.split(".").pop()
    const path = `claims/${Date.now()}_${Math.random().toString(36).slice(2)}.${ext}`
    const { error } = await supabase.storage.from("claim-evidence").upload(path, file)
    if (error) throw error
    const { data } = supabase.storage.from("claim-evidence").getPublicUrl(path)
    return data.publicUrl
  }

  async function handleEvidenceSelect(e) {
    const files = Array.from(e.target.files).slice(0, 3)
    setUploadingEvidence(true)
    try {
      const urls = await Promise.all(files.map(uploadEvidencePhoto))
      setEvidencePhotos(prev => [...prev, ...urls].slice(0, 3))
    } catch(err) { console.error("Photo upload failed:", err.message) }
    setUploadingEvidence(false)
  }

  async function submitClaim(e) {
    e.preventDefault()
    if (!form.booking_id) return toast.error("Please select a booking")
    if (!form.reason) return toast.error("Please select a reason")
    if (!form.description) return toast.error("Please describe the issue")
    setSubmitting(true)
    try {
      const booking = bookings.find(b=>b.id===form.booking_id)
      const { error } = await supabase.from("service_claims").insert({
        claimant_id: user.id,
        claimant_type: "driver",
        against_id: booking?.customer_id,
        against_type: "customer",
        customer_id: booking?.customer_id,
        driver_id: user.id,
        booking_id: form.booking_id,
        reason: form.reason,
        description: form.description,
        status: "pending",
      })
      if (error) throw error
      const { data: admins } = await supabase.from("profiles").select("id").eq("role","admin")
      for (const admin of (admins||[])) {
        await supabase.from("notifications").insert({
          user_id: admin.id,
          title: "Driver filed claim against customer ≡ƒ¢í∩╕Å",
          message: (profile?.first_name||"Driver")+" "+(profile?.last_name||"")+" filed a claim: "+form.reason,
          type: "warning"
        })
      }
      if (booking?.customer_id) {
        await supabase.from("notifications").insert({
          user_id: booking.customer_id,
          title: "A claim has been filed against you ΓÜá∩╕Å",
          message: "A driver has filed a claim regarding booking "+booking.booking_number+". Our team will review within 24 hours.",
          type: "warning"
        })
      }
      toast.success("Claim submitted successfully")
      setShowForm(false)
      setForm({ booking_id:"", reason:"", description:"" })
      setEvidencePhotos([])
      load()
    } catch(err) { toast.error(err.message) }
    finally { setSubmitting(false) }
  }

  const inp = { width:"100%", background:"#f5f5f5", border:"1px solid #e0e0e0", borderRadius:8, padding:"10px 12px", fontSize:13, outline:"none", marginBottom:12, boxSizing:"border-box" }
  const lbl = { fontSize:11, color:"#666", display:"block", marginBottom:4, fontWeight:600 }

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:"#000", marginBottom:"1rem", display:"flex", alignItems:"center", gap:8 }}><ShieldIcon size={20} color="#e6821e"/> Claims Center</div>
      <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:8, marginBottom:"1rem" }}>
        {[
          { label:"Against you", value:claims.length, color:"#e24b4a" },
          { label:"Filed by you", value:filedClaims.length, color:"#8b5cf6" },
          { label:"Pending", value:claims.filter(c=>c.status==="pending").length, color:"#e6821e" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.75rem", textAlign:"center", border:"1px solid #eee" }}>
            <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>
      <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap" }}>
        {[
          { k:"against", l:"Against you ("+claims.length+")" },
          { k:"filed", l:"Filed by you ("+filedClaims.length+")" },
        ].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{ padding:"7px 14px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#e6821e":"#f0f0f0", color:tab===t.k?"#fff":"#555", fontWeight:tab===t.k?700:400 }}>
            {t.l}
          </button>
        ))}
        <button onClick={()=>setShowForm(!showForm)}
          style={{ marginLeft:"auto", background:"#8b5cf6", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"7px 14px", cursor:"pointer" }}>
          + File a claim
        </button>
      </div>
      {showForm&&(
        <div style={{ background:"#f8f8f8", border:"1px solid #8b5cf640", borderRadius:12, padding:"1.25rem", marginBottom:"1rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, marginBottom:"1rem" }}>File a Claim Against a Customer</div>
          <form onSubmit={submitClaim}>
            <label style={lbl}>Select booking *</label>
            <select style={inp} value={form.booking_id} onChange={e=>setForm(f=>({...f,booking_id:e.target.value}))} required>
              <option value="">Select a completed booking</option>
              {bookings.map(b=>(
                <option key={b.id} value={b.id}>{b.service_name} ΓÇö #{b.booking_number} ┬╖ {b.profiles?.first_name} {b.profiles?.last_name}</option>
              ))}
            </select>
            <label style={lbl}>Reason *</label>
            <select style={inp} value={form.reason} onChange={e=>setForm(f=>({...f,reason:e.target.value}))} required>
              <option value="">Select reason</option>
              {CLAIM_REASONS.map(r=><option key={r} value={r}>{r}</option>)}
            </select>
            <label style={lbl}>Description *</label>
            <textarea style={{ ...inp, resize:"vertical", minHeight:80 }}
              placeholder="Describe what happened..." rows={4}
              value={form.description} onChange={e=>setForm(f=>({...f,description:e.target.value}))} required/>
            <div style={{ background:"#fff8f0", border:"1px solid #e6821e30", borderRadius:8, padding:"0.75rem", marginBottom:12, fontSize:11, color:"#666" }}>
              ΓÜá∩╕Å Only file genuine claims. False claims may result in account suspension.
            </div>
              {/* Evidence photos */}
              <div style={{ marginBottom:12 }}>
                <div style={{ fontSize:11, color:"#666", fontWeight:600, marginBottom:6 }}>≡ƒô╕ Attach evidence photos (optional, max 3)</div>
                <input ref={evidenceInputRef} type="file" accept="image/*" multiple style={{ display:"none" }} onChange={handleEvidenceSelect}/>
                <div style={{ display:"flex", gap:6, flexWrap:"wrap", alignItems:"center" }}>
                  {evidencePhotos.map((url,i)=>(
                    <div key={i} style={{ position:"relative" }}>
                      <img src={url} alt="Evidence" style={{ width:60, height:60, objectFit:"cover", borderRadius:8, border:"1px solid #eee" }}/>
                      <button type="button" onClick={()=>setEvidencePhotos(p=>p.filter((_,j)=>j!==i))}
                        style={{ position:"absolute", top:-4, right:-4, background:"#e24b4a", border:"none", borderRadius:"50%", width:16, height:16, color:"#fff", fontSize:10, cursor:"pointer" }}>x</button>
                    </div>
                  ))}
                  {evidencePhotos.length<3&&(
                    <button type="button" onClick={()=>evidenceInputRef.current?.click()} disabled={uploadingEvidence}
                      style={{ width:60, height:60, background:"#f8f8f8", border:"2px dashed #ddd", borderRadius:8, cursor:"pointer", fontSize:20, color:"#aaa" }}>
                      {uploadingEvidence?"ΓÅ│":"≡ƒô╖"}
                    </button>
                  )}
                </div>
              </div>
            <div style={{ display:"flex", gap:8 }}>
              <button type="submit" disabled={submitting}
                style={{ background:submitting?"#ccc":"#8b5cf6", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px 24px", cursor:submitting?"not-allowed":"pointer" }}>
                {submitting?"Submitting...":"Submit claim"}
              </button>
              <button type="button" onClick={()=>setShowForm(false)}
                style={{ background:"none", border:"1px solid #ddd", borderRadius:9, color:"#666", fontSize:13, padding:"11px 16px", cursor:"pointer" }}>
                Cancel
              </button>
            </div>
          </form>
        </div>
      )}
      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
      {tab==="against"&&(
        <div>
          {!loading&&claims.length===0&&(
            <div style={{ textAlign:"center", padding:"2rem", color:"#888" }}>
              <div style={{ fontSize:32, marginBottom:10 }}>Γ£à</div>
              No claims against you ΓÇö great work!
            </div>
          )}
          {claims.map(c=>(
            <div key={c.id} style={{ background:"#f8f8f8", border:"1px solid #eee", borderLeft:`4px solid ${SC[c.status]||"#eee"}`, borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div style={{ flex:1 }}>
                  <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, marginBottom:2 }}>{c.bookings?.service_name}</div>
                  <div style={{ fontSize:11, color:"#888" }}>#{c.bookings?.booking_number} ┬╖ {c.bookings?.booking_date}</div>
                  <div style={{ fontSize:11, color:"#888" }}>Customer: {c.customer?.first_name} {c.customer?.last_name}</div>
                  <div style={{ fontSize:12, color:"#e6821e", marginTop:4 }}>Reason: {c.reason}</div>
                  {c.admin_notes&&<div style={{ fontSize:11, color:"#378add", marginTop:4 }}>Admin: "{c.admin_notes}"</div>}
                </div>
                <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:(SC[c.status]||"#888")+"20", color:SC[c.status]||"#888", fontWeight:600 }}>{c.status?.replace("_"," ")}</span>
              </div>
              {(c.status==="pending"||c.status==="under_review")&&(
                <div style={{ marginTop:8 }}>
                  <button onClick={()=>setChatClaim(chatClaim===c.id?null:c.id)}
                    style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>
                    ≡ƒÆ¼ {chatClaim===c.id?"Close":"Submit response / evidence"}
                  </button>
                  {chatClaim===c.id&&(
                    <div style={{ marginTop:8 }}>
                      <ClaimChat claimId={c.id} claim={c} onClose={()=>setChatClaim(null)}/>
                    </div>
                  )}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
      {tab==="filed"&&(
        <div>
          {!loading&&filedClaims.length===0&&(
            <div style={{ textAlign:"center", padding:"2rem", color:"#888" }}>
              <div style={{ fontSize:32, marginBottom:10 }}>≡ƒôï</div>
              No claims filed yet
            </div>
          )}
          {filedClaims.map(c=>(
            <div key={c.id} style={{ background:"#f8f8f8", border:"1px solid #eee", borderLeft:`4px solid ${SC[c.status]||"#eee"}`, borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div style={{ flex:1 }}>
                  <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, marginBottom:2 }}>{c.bookings?.service_name}</div>
                  <div style={{ fontSize:11, color:"#888" }}>Against: {c.against?.first_name} {c.against?.last_name} (Customer)</div>
                  <div style={{ fontSize:12, color:"#e6821e", marginTop:4 }}>Reason: {c.reason}</div>
                  {c.admin_notes&&<div style={{ fontSize:11, color:"#378add", marginTop:4 }}>Admin decision: "{c.admin_notes}"</div>}
                  <div style={{ fontSize:10, color:"#aaa", marginTop:4 }}>{new Date(c.created_at).toLocaleDateString()}</div>
                </div>
                <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:(SC[c.status]||"#888")+"20", color:SC[c.status]||"#888", fontWeight:600 }}>{c.status?.replace("_"," ")}</span>
              </div>
              <div style={{ marginTop:8 }}>
                <button onClick={()=>setChatClaim(chatClaim===c.id?null:c.id)}
                  style={{ background:"#f5f3ff", border:"1px solid #8b5cf640", borderRadius:7, color:"#8b5cf6", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>
                  ≡ƒÆ¼ {chatClaim===c.id?"Close":"View discussion"}
                </button>
                {chatClaim===c.id&&(
                  <div style={{ marginTop:8 }}>
                    <ClaimChat claimId={c.id} claim={c} onClose={()=>setChatClaim(null)}/>
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { useState, useEffect, useRef } from "react"
import { CheckIcon, LocationIcon, VehicleIcon, MovingCarIcon, SuccessIcon, WalletIcon, StarIcon, ClockIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import DriverOnboarding from "./DriverOnboarding"
import { useAuth } from "../../contexts/AuthContext"
import { openExternal, openMapsNavigation } from "../../lib/openExternal"
import toast from "react-hot-toast"

const DELIVERY_STEPS = [
  { status:"driver-assigned", label:"Accepted", icon:"check" },
  { status:"arrived-for-pickup", label:"Arrived for pickup", icon:"location" },
  { status:"in-progress", label:"Vehicle picked up", icon:"vehicle" },
  { status:"arrived-at-dropoff", label:"Arrived at dropoff", icon:"location2" },
  { status:"completed", label:"Delivered", icon:"Γ£à" },
]
const STATUS_NEXT = {
  "driver-assigned": { next:"arrived-for-pickup", label:"Mark arrived at pickup", color:"#378add" },
  "arrived-for-pickup": { next:"in-progress", label:"Mark vehicle picked up", color:"#8b5cf6" },
  "in-progress": { next:"arrived-at-dropoff", label:"Mark arrived at dropoff", color:"#e6821e" },
  "arrived-at-dropoff": { next:"completed", label:"Mark delivered", color:"#1d9e75" },
}

export default function DriverDashboard() {
  const { user, profile } = useAuth()
  const [isOnline, setIsOnline] = useState(false)
  const [jobs, setJobs] = useState([])
  const [myJobs, setMyJobs] = useState([])
  const [customers, setCustomers] = useState({})
  const [stats, setStats] = useState({ today:0, total:0, deliveries:0, hoursOnline:0 })
  const [showOnboarding, setShowOnboarding] = useState(false)
  const [loading, setLoading] = useState(true)
  const [tab, setTab] = useState("available")
  const [declining, setDeclining] = useState(null)
  const [declineReason, setDeclineReason] = useState("")
  const [shiftStart, setShiftStart] = useState(null)
  const watchRef = useRef(null)
  const inactivityRef = useRef(null)
  const onlineStartRef = useRef(null)

  useEffect(() => {
    if(profile && !profile.onboarding_complete) setShowOnboarding(true)
  }, [profile])

  useEffect(() => {
    if (!user) return
    initDriverStatus()
    load()
    const sub = supabase.channel("driver-jobs")
      .on("postgres_changes", { event:"*", schema:"public", table:"bookings" }, () => load())
      .subscribe()
    return () => {
      supabase.removeChannel(sub)
      if (watchRef.current) navigator.geolocation.clearWatch(watchRef.current)
      if (inactivityRef.current) clearTimeout(inactivityRef.current)
    }
  }, [user])

  async function initDriverStatus() {
    const { data } = await supabase.from("driver_status").select("*").eq("driver_id", user.id).single()
    if (data) { setIsOnline(data.is_online); if (data.is_online) startLocationTracking() }
    else { await supabase.from("driver_status").insert({ driver_id:user.id, is_online:false }) }
  }

  async function load() {
    const [{ data: available }, { data: mine }] = await Promise.all([
      supabase.from("bookings").select("*").eq("is_concierge",true).in("status",["confirmed"]).is("driver_id",null).order("booking_date",{ascending:true}),
      supabase.from("bookings").select("*").eq("driver_id",user.id).order("created_at",{ascending:false})
    ])
    setJobs(available||[]); setMyJobs(mine||[])
    const allBookings = [...(available||[]),...(mine||[])]
    if (allBookings.length > 0) {
      const ids = [...new Set(allBookings.map(b=>b.customer_id))]
      const [{ data:sens },{ data:profs }] = await Promise.all([
        supabase.from("profile_sensitive").select("id,phone,email").in("id",ids),
        supabase.from("profile_public").select("id,first_name,last_name").in("id",ids)
      ])
      const map = {}
      ids.forEach(id=>{ map[id]={...sens?.find(p=>p.id===id),...profs?.find(p=>p.id===id)} })
      setCustomers(map)
    }
    const today = new Date().toISOString().split("T")[0]
    const completed = (mine||[]).filter(d=>d.status==="completed")
    setStats({ deliveries:completed.length, total:completed.reduce((s,d)=>s+Number(d.driver_earnings||15),0), today:completed.filter(d=>d.booking_date===today).reduce((s,d)=>s+Number(d.driver_earnings||15),0), hoursOnline:shiftStart?Math.floor((Date.now()-shiftStart)/3600000):0 })
    setLoading(false)
  }

  function startLocationTracking() {
    if (!navigator.geolocation) return
    watchRef.current = navigator.geolocation.watchPosition(async (pos) => {
      await supabase.from("driver_status").upsert({ driver_id:user.id, is_online:true, current_lat:pos.coords.latitude, current_lng:pos.coords.longitude, last_location_update:new Date().toISOString(), updated_at:new Date().toISOString() })
      resetInactivityTimer()
    }, null, { enableHighAccuracy:true, maximumAge:10000, timeout:5000 })
  }

  function resetInactivityTimer() {
    if (inactivityRef.current) clearTimeout(inactivityRef.current)
    inactivityRef.current = setTimeout(async () => { await goOffline(); toast("You were set offline due to inactivity", { icon:"ΓÅ░" }) }, 30*60*1000)
  }

  async function goOffline() {
    if (watchRef.current) navigator.geolocation.clearWatch(watchRef.current)
    await supabase.from("driver_status").upsert({ driver_id:user.id, is_online:false, updated_at:new Date().toISOString() })
    setIsOnline(false)
  }

  async function toggleOnline() {
    const next = !isOnline
    const { error } = await supabase.from("driver_status").upsert({ driver_id:user.id, is_online:next, updated_at:new Date().toISOString() })
    if (error) return toast.error(error.message)
    setIsOnline(next)
    if (next) { startLocationTracking(); onlineStartRef.current = Date.now(); setShiftStart(Date.now()); toast.success("You are now online") }
    else { if (watchRef.current) navigator.geolocation.clearWatch(watchRef.current); if (inactivityRef.current) clearTimeout(inactivityRef.current); setShiftStart(null); toast.success("You are now offline") }
  }

  async function acceptJob(bookingId) {
    const { error } = await supabase.from("bookings").update({ driver_id:user.id, status:"driver-assigned" }).eq("id",bookingId).is("driver_id",null)
    if (error) return toast.error(error.message)
    const booking = jobs.find(j=>j.id===bookingId)
    if (booking) await supabase.from("notifications").insert({ user_id:booking.customer_id, title:"Driver assigned", message:`A driver is on their way for ${booking.service_name}`, type:"success" })
    toast.success("Job accepted!"); setTab("myjobs"); load()
  }

  async function updateDeliveryStatus(bookingId, newStatus) {
    const { error } = await supabase.from("bookings").update({ status:newStatus }).eq("id",bookingId).eq("driver_id",user.id)
    if (error) return toast.error(error.message)
    const booking = myJobs.find(j=>j.id===bookingId)
    const msgs = { "arrived-for-pickup":"Your driver has arrived at pickup location","in-progress":"Your vehicle has been picked up and is on the way","arrived-at-dropoff":"Your driver has arrived at the service center","completed":"Your vehicle has been delivered successfully" }
    if (booking && msgs[newStatus]) await supabase.from("notifications").insert({ user_id:booking.customer_id, title:DELIVERY_STEPS.find(s=>s.status===newStatus)?.label||newStatus, message:msgs[newStatus], type:"info" })
    toast.success(`Status updated: ${DELIVERY_STEPS.find(s=>s.status===newStatus)?.label||newStatus}`); load()
  }

  async function declineJob(bookingId) {
    if (!declineReason.trim()) return toast.error("Please provide a reason")
    await supabase.from("bookings").update({ driver_id:null }).eq("id",bookingId).eq("driver_id",user.id)
    toast.success("Job declined"); setDeclining(null); setDeclineReason(""); load()
  }

  function openNavigation(address) {
    if (!address) return toast.error("No address available")
    openExternal(`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(address)}`)
  }

  function openWhatsApp(phone, name, serviceName) {
    if (!phone) return toast.error("Customer phone not available")
    const msg = encodeURIComponent(`Hi ${name||"there"}, I am your driver for the ${serviceName} booking.`)
    window.open(`https://wa.me/${phone.replace(/\D/g,"")}?text=${msg}`, "_blank")
  }

  function calculateETA(bookingDate, bookingTime) {
    if (!bookingDate || !bookingTime) return "Unknown"
    const diff = new Date(`${bookingDate}T${bookingTime}`) - new Date()
    if (diff < 0) return "Now"
    const h = Math.floor(diff/3600000); const m = Math.floor((diff%3600000)/60000)
    return h > 0 ? `${h}h ${m}m` : `${m}m`
  }

  const activeJobs = myJobs.filter(j=>!["completed","cancelled"].includes(j.status))
  const completedJobs = myJobs.filter(j=>j.status==="completed")
  const SC = { "driver-assigned":"#378add","arrived-for-pickup":"#8b5cf6","in-progress":"#e6821e","arrived-at-dropoff":"#e6821e","completed":"#1d9e75","cancelled":"#e24b4a" }
  const shiftDuration = shiftStart ? `${Math.floor((Date.now()-shiftStart)/3600000)}h ${Math.floor(((Date.now()-shiftStart)%3600000)/60000)}m` : "0h 0m"

  return (
    <div style={{ margin:"-1rem", fontFamily:"DM Sans,sans-serif" }}>
      {showOnboarding && <DriverOnboarding onComplete={()=>{ setShowOnboarding(false); window.location.reload() }} />}
      {/* Green/dark header */}
      <div style={{ background:isOnline?"#1d9e75":"#000", padding:"1.25rem 1.25rem 2.5rem", transition:"background 0.3s" }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
          <div>
            <div style={{ fontSize:11, color:"rgba(255,255,255,0.7)", marginBottom:2 }}>
              {new Date().toLocaleDateString("en-KE",{weekday:"long",day:"numeric",month:"long"})}
            </div>
            <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:"#fff" }}>
              {profile?.first_name} {profile?.last_name}
            </div>
            <div style={{ fontSize:11, color:"rgba(255,255,255,0.8)", marginTop:2 }}>
              ≡ƒÜù {profile?.driver_vehicle_type==="motorcycle"?"Boda Boda":"Car"} Driver
            </div>
          </div>
          {/* Online toggle */}
          <button onClick={toggleOnline}
            style={{ background:isOnline?"rgba(255,255,255,0.2)":"#e6821e", border:"none", borderRadius:20, color:"#fff", fontSize:12, fontWeight:700, padding:"8px 16px", cursor:"pointer", fontFamily:"Syne,sans-serif" }}>
            {isOnline ? "ΓùÅ Online" : "Γùï Go Online"}
          </button>
        </div>
        {isOnline&&(
          <div style={{ marginTop:8, fontSize:10, color:"rgba(255,255,255,0.7)" }}>
            Shift: {shiftDuration} ┬╖ GPS active
          </div>
        )}
      </div>

      {/* Floating stats card */}
      <div style={{ margin:"-1.25rem 1rem 1rem", background:"#fff", borderRadius:16, padding:"1rem", boxShadow:"0 4px 20px rgba(0,0,0,0.08)", border:"1px solid #f0f0f0" }}>
        <div style={{ display:"grid", gridTemplateColumns:"repeat(2,1fr)", gap:8 }}>
          {[
            { label:"Today earnings", value:`KES ${stats.today.toFixed(0)}`, icon:"≡ƒÆ╡", color:"#e6821e" },
            { label:"Total earned", value:`KES ${stats.total.toFixed(0)}`, icon:"≡ƒÆ░", color:"#1d9e75" },
            { label:"Deliveries", value:stats.deliveries, icon:"≡ƒÜù", color:"#378add" },
            { label:"Active jobs", value:activeJobs.length, icon:"≡ƒôª", color:activeJobs.length>0?"#8b5cf6":"#888" },
          ].map(s=>(
            <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.75rem", display:"flex", alignItems:"center", gap:8 }}>
              <div style={{ fontSize:20 }}>{s.icon}</div>
              <div>
                <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, color:s.color }}>{s.value}</div>
                <div style={{ fontSize:10, color:"#888" }}>{s.label}</div>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div style={{ padding:"0 1rem" }}>
        {/* Tabs */}
        <div style={{ display:"flex", gap:6, marginBottom:"1rem" }}>
          {[
            { k:"available", l:`Available (${jobs.length})` },
            { k:"myjobs", l:`Active (${activeJobs.length})` },
            { k:"history", l:`History (${completedJobs.length})` },
          ].map(t=>(
            <button key={t.k} onClick={()=>setTab(t.k)}
              style={{ padding:"7px 14px", borderRadius:20, border:"none", fontSize:11, cursor:"pointer", background:tab===t.k?"#1d9e75":"#f0f0f0", color:tab===t.k?"#fff":"#555", fontFamily:"DM Sans,sans-serif", fontWeight:tab===t.k?700:400 }}>
              {t.l}
            </button>
          ))}
        </div>

        {/* AVAILABLE JOBS */}
        {tab==="available"&&(
          <div>
            {!isOnline&&(
              <div style={{ textAlign:"center", padding:"2rem", background:"#f8f8f8", borderRadius:12 }}>
                <div style={{ fontSize:36, marginBottom:8 }}>≡ƒÜù</div>
                <div style={{ fontSize:14, color:"#555", marginBottom:12 }}>You are offline</div>
                <button onClick={toggleOnline} style={{ background:"#1d9e75", border:"none", borderRadius:20, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"10px 24px", cursor:"pointer" }}>
                  Go Online
                </button>
              </div>
            )}
            {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
            {isOnline&&!loading&&jobs.length===0&&(
              <div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem", background:"#f8f8f8", borderRadius:12 }}>
                <div style={{ fontSize:36, marginBottom:8 }}>≡ƒô¡</div>
                No available jobs right now
              </div>
            )}
            {isOnline&&jobs.map(j=>{
              const customer = customers[j.customer_id]
              return (
                <div key={j.id} style={{ background:"#fff", border:"0.5px solid #eee", borderRadius:12, padding:"1rem", marginBottom:10 }}>
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
                    <div>
                      <div style={{ fontSize:14, fontWeight:500, color:"#000" }}>{j.service_name}</div>
                      <div style={{ fontSize:11, color:"#888", marginTop:2 }}>{customer?.first_name} {customer?.last_name}</div>
                    </div>
                    <div style={{ textAlign:"right" }}>
                      <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, color:"#1d9e75" }}>+KES 200</div>
                      <div style={{ fontSize:10, color:"#888" }}>ETA: {calculateETA(j.booking_date, j.booking_time)}</div>
                    </div>
                  </div>
                  <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8, marginBottom:10 }}>
                    <div style={{ background:"#f8f8f8", borderRadius:8, padding:"6px 8px" }}>
                      <div style={{ fontSize:9, color:"#888", marginBottom:2 }}>PICKUP</div>
                      <div style={{ fontSize:11, color:"#000" }}>{j.pickup_address||"Customer address"}</div>
                    </div>
                    <div style={{ background:"#f8f8f8", borderRadius:8, padding:"6px 8px" }}>
                      <div style={{ fontSize:9, color:"#888", marginBottom:2 }}>DATE & TIME</div>
                      <div style={{ fontSize:11, color:"#000" }}>{j.booking_date} {j.booking_time?.slice(0,5)}</div>
                    </div>
                  </div>
                  <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
                    <button onClick={()=>acceptJob(j.id)} style={{ background:"#1d9e75", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"9px 20px", cursor:"pointer" }}>Accept</button>
                    <button onClick={()=>openNavigation(j.pickup_address)} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>Maps</button>
                    <button onClick={()=>openWhatsApp(customer?.phone, customer?.first_name, j.service_name)} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>WhatsApp</button>
                    <button onClick={()=>setDeclining(j.id)} style={{ background:"none", border:"1px solid #e24b4a40", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>Decline</button>
                  </div>
                  {declining===j.id&&(
                    <div style={{ marginTop:10 }}>
                      <input placeholder="Reason for declining..." value={declineReason} onChange={e=>setDeclineReason(e.target.value)}
                        style={{ width:"100%", background:"#f8f8f8", border:"1px solid #eee", borderRadius:7, padding:"8px 10px", color:"#000", fontSize:12, outline:"none", marginBottom:8 }}/>
                      <div style={{ display:"flex", gap:8 }}>
                        <button onClick={()=>declineJob(j.id)} style={{ background:"#fff5f5", border:"1px solid #e24b4a40", borderRadius:7, color:"#e24b4a", fontSize:12, padding:"6px 14px", cursor:"pointer" }}>Confirm decline</button>
                        <button onClick={()=>{ setDeclining(null); setDeclineReason("") }} style={{ background:"none", border:"1px solid #ddd", borderRadius:7, color:"#666", fontSize:12, padding:"6px 14px", cursor:"pointer" }}>Cancel</button>
                      </div>
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        )}

        {/* MY JOBS */}
        {tab==="myjobs"&&(
          <div>
            {activeJobs.length===0&&(
              <div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem", background:"#f8f8f8", borderRadius:12 }}>
                <div style={{ fontSize:36, marginBottom:8 }}>≡ƒô¡</div>
                No active jobs
              </div>
            )}
            {activeJobs.map(j=>{
              const customer = customers[j.customer_id]
              const nextStep = STATUS_NEXT[j.status]
              const currentStepIndex = DELIVERY_STEPS.findIndex(s=>s.status===j.status)
              return (
                <div key={j.id} style={{ background:"#fff", border:`1px solid ${SC[j.status]||"#eee"}30`, borderRadius:12, padding:"1rem", marginBottom:10 }}>
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:12 }}>
                    <div>
                      <div style={{ fontSize:14, fontWeight:500, color:"#000" }}>{j.service_name}</div>
                      <div style={{ fontSize:11, color:"#888", marginTop:2 }}>{customer?.first_name} {customer?.last_name}</div>
                      <div style={{ fontSize:10, color:"#aaa" }}>{j.booking_date} ┬╖ {j.booking_time?.slice(0,5)}</div>
                    </div>
                    <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#1d9e75" }}>+KES 200</div>
                  </div>
                  {/* Progress steps */}
                  <div style={{ display:"flex", gap:4, marginBottom:12, overflowX:"auto" }}>
                    {DELIVERY_STEPS.map((step,i)=>(
                      <div key={step.status} style={{ display:"flex", alignItems:"center", gap:4, flexShrink:0 }}>
                        <div style={{ width:28, height:28, borderRadius:"50%", background:i<=currentStepIndex?"#1d9e75":"#f0f0f0", color:i<=currentStepIndex?"#fff":"#aaa", fontSize:11, fontWeight:700, display:"flex", alignItems:"center", justifyContent:"center" }}>
                          {i<currentStepIndex?"Γ£ô":i===currentStepIndex?step.icon:i+1}
                        </div>
                        {i<DELIVERY_STEPS.length-1&&<div style={{ width:20, height:2, background:i<currentStepIndex?"#1d9e75":"#f0f0f0" }}/>}
                      </div>
                    ))}
                  </div>
                  <div style={{ fontSize:11, color:"#1d9e75", fontWeight:600, marginBottom:10 }}>
                    {DELIVERY_STEPS[currentStepIndex]?.label||j.status}
                  </div>
                  {j.pickup_address&&<div style={{ fontSize:11, color:"#888", marginBottom:8 }}>≡ƒôì {j.pickup_address}</div>}
                  <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
                    {nextStep&&(
                      <button onClick={()=>updateDeliveryStatus(j.id, nextStep.next)}
                        style={{ background:nextStep.color+"15", border:`1px solid ${nextStep.color}40`, borderRadius:7, color:nextStep.color, fontSize:12, padding:"7px 14px", cursor:"pointer", fontWeight:600 }}>
                        {nextStep.label}
                      </button>
                    )}
                    <button onClick={()=>openNavigation(j.pickup_address||"")} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>Google Maps</button>
                    <button onClick={()=>window.open(`https://waze.com/ul?q=${encodeURIComponent(j.pickup_address||"")}`, "_blank")} style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>Waze</button>
                    <button onClick={()=>openWhatsApp(customer?.phone, customer?.first_name, j.service_name)} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>WhatsApp</button>
                  </div>
                </div>
              )
            })}
          </div>
        )}

        {/* HISTORY */}
        {tab==="history"&&(
          <div>
            {completedJobs.length===0&&(
              <div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem", background:"#f8f8f8", borderRadius:12 }}>
                <div style={{ fontSize:36, marginBottom:8 }}>≡ƒô¡</div>
                No completed deliveries yet
              </div>
            )}
            {completedJobs.map(j=>(
              <div key={j.id} style={{ background:"#fff", border:"0.5px solid #eee", borderRadius:12, padding:"0.85rem", marginBottom:8, display:"flex", alignItems:"center", gap:12 }}>
                <div style={{ width:36, height:36, background:"#f0fdf4", borderRadius:8, display:"flex", alignItems:"center", justifyContent:"center", fontSize:16 }}>Γ£à</div>
                <div style={{ flex:1 }}>
                  <div style={{ fontSize:13, fontWeight:500, color:"#000" }}>{j.service_name}</div>
                  <div style={{ fontSize:11, color:"#888", marginTop:2 }}>{j.booking_date} ┬╖ #{j.booking_number}</div>
                </div>
                <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#1d9e75" }}>+KES {Number(j.driver_earnings||200).toFixed(0)}</div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

import { OrdersIcon, LocationIcon, CheckIcon, CloseIcon, DeliveryIcon } from "../../lib/cccIcons"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import { openExternal, openMapsNavigation } from "../../lib/openExternal"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

export default function DriverDeliveries() {
  const { user, profile } = useAuth()
  const isMobile = useIsMobile()
  const [deliveries, setDeliveries] = useState([])
  const [available, setAvailable] = useState([])
  const [loading, setLoading] = useState(true)
  const [marketplaceRate, setMarketplaceRate] = useState(0.85)
  const [tab, setTab] = useState("available")
  const [now, setNow] = useState(Date.now())
  const [arrivedOrder, setArrivedOrder] = useState(null)
  const [otpInput, setOtpInput] = useState({})
  const [otpVerifying, setOtpVerifying] = useState(null)
  const [generatingOtp, setGeneratingOtp] = useState(null)

  useEffect(() => {
    const interval = setInterval(()=>setNow(Date.now()), 1000)
    return () => clearInterval(interval)
  }, [])

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("driver-deliveries")
      .on("postgres_changes", { event:"UPDATE", schema:"public", table:"orders", filter:`delivery_driver_id=eq.${user.id}` },
        () => load())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function load() {
    (async () => {
      const vt = profile?.driver_vehicle_type || "car"
      const { data: vtRate } = await supabase.from("app_settings").select("value").eq("key",`marketplace_driver_commission_rate_${vt}`).maybeSingle()
      if (vtRate) { setMarketplaceRate(Number(vtRate.value)/100); return }
      const { data: fallback } = await supabase.from("app_settings").select("value").eq("key","marketplace_driver_commission_rate").maybeSingle()
      if (fallback) setMarketplaceRate(Number(fallback.value)/100)
    })()
    const [{ data: mine }, { data: avail }] = await Promise.all([
      supabase.from("orders")
        .select("*, order_items(name,quantity), profiles!orders_customer_id_fkey(first_name,last_name,city,latitude,longitude), provider:profiles!orders_provider_id_fkey(first_name,last_name,business_name,city,address,latitude,longitude)")
        .eq("delivery_driver_id", user.id)
        .order("created_at", { ascending:false }),
      supabase.from("orders")
        .select("*, order_items(name,quantity), profiles!orders_customer_id_fkey(first_name,last_name,city,latitude,longitude), provider:profiles!orders_provider_id_fkey(first_name,last_name,business_name,city,address,latitude,longitude)")
        .eq("fulfillment_type","delivery")
        .eq("status","ready")
        .is("delivery_driver_id",null)
        .order("created_at", { ascending:false })
    ])
    setDeliveries(mine||[])
    setAvailable(avail||[])
    setLoading(false)
  }

  async function acceptDelivery(orderId) {
    try {
    // This delivery was broadcast to every eligible driver at once, not offered to one at a
    // time - the plain update below had no guard against two drivers tapping Accept within
    // moments of each other, letting the second silently overwrite the first with both seeing
    // a success toast. The .is() check makes this an atomic claim: only succeeds if nobody
    // else has already taken it.
    const { data: claimed, error: claimError } = await supabase.from("orders").update({
      delivery_driver_id: user.id,
      delivery_status: "driver_assigned"
    }).eq("id", orderId).is("delivery_driver_id", null).select().maybeSingle()
    if (claimError) { toast.error("Failed to accept delivery"); return }
    if (!claimed) { toast.error("Sorry, another driver already accepted this delivery"); load(); return }
    const order = available.find(o=>o.id===orderId)
    if (order?.customer_id) {
      await supabase.from("notifications").insert({
        user_id: order.customer_id,
        title: "Driver assigned! ≡ƒÜÜ",
        message: "A driver has been assigned to deliver your order. They will pick up from the shop shortly.",
        type: "success"
      })
    }
    toast.success("Delivery accepted!")
    load()
    } catch(e) { toast.error("Failed to accept delivery") }
  }

  async function declineDelivery(orderId) {
    if (!confirm("Decline this delivery? It will be reassigned to another driver.")) return
    try {
    const order = deliveries.find(d=>d.id===orderId)
    await supabase.from("orders").update({
      delivery_driver_id: null,
      delivery_status: null,
      delivery_attempt_expires_at: null,
      delivery_declined_drivers: [...(order?.delivery_declined_drivers||[]), user.id]
    }).eq("id", orderId)
    toast.success("Delivery declined")
    load()
    } catch(e) { toast.error("Failed to decline delivery") }
  }
  async function generateDeliveryOTP(orderId) {
    setGeneratingOtp(orderId)
    try {
      const { data, error } = await supabase.functions.invoke("marketplace-generate-delivery-otp", { body: { order_id: orderId, driver_id: user.id } })
      if (error || data?.error) throw new Error(data?.error || error.message)
      setArrivedOrder(orderId)
      toast.success("OTP sent to customer! Ask them for the code.")
    } catch(e) { toast.error(e.message || "Failed to generate OTP") }
    finally { setGeneratingOtp(null) }
  }
  async function verifyDeliveryOTP(order) {
    const entered = otpInput[order.id]
    if (!entered || entered.length !== 4) return toast.error("Enter 4-digit OTP")
    setOtpVerifying(order.id)
    try {
      const { data, error } = await supabase.rpc("verify_delivery_otp", { p_order_id: order.id, p_otp: entered })
      if (error) throw error
      if (!data?.success) throw new Error(data?.error || "Verification failed")
      // Trigger the actual payout release now that delivery is genuinely confirmed - both
      // provider and driver shares get checked and released as far as each is eligible
      await supabase.functions.invoke("release-order-payment", { body: { order_id: order.id } })
      if (order.customer_id) {
        await supabase.from("notifications").insert({
          user_id: order.customer_id,
          title: "Order delivered! ≡ƒÄë",
          message: "Your order has been delivered and confirmed. Thank you for shopping with CCC!",
          type: "success"
        })
      }
      setArrivedOrder(null)
      setOtpInput(prev => ({ ...prev, [order.id]: "" }))
      toast.success("Delivery confirmed! ≡ƒÄë")
      load()
    } catch(e) { toast.error(e.message || "Verification failed") }
    finally { setOtpVerifying(null) }
  }

  function formatCountdown(expiresAt) {
    if (!expiresAt) return null
    const diff = new Date(expiresAt).getTime() - now
    if (diff <= 0) return "Expired"
    const mins = Math.floor(diff/60000)
    const secs = Math.floor((diff%60000)/1000)
    return mins+":"+String(secs).padStart(2,"0")
  }

  async function updateDeliveryStatus(orderId, status, customerId) {
    try {
    await supabase.from("orders").update({
      delivery_status: status,
      ...(status==="picked_up"?{ pickup_confirmed_at:new Date().toISOString(), delivery_attempt_expires_at:null }:{}),
      ...(status==="delivered"?{ delivered_at:new Date().toISOString(), status:"delivered" }:{})
    }).eq("id", orderId)
    const messages = {
      picked_up: "Your order has been picked up and is on the way! ≡ƒÜÜ",
      delivered: "Your order has been delivered! Please confirm receipt. ≡ƒÄë"
    }
    if (messages[status] && customerId) {
      await supabase.from("notifications").insert({
        user_id: customerId,
        title: "Order update ≡ƒôª",
        message: messages[status],
        type: "success"
      })
    }
    toast.success("Status updated")
    load()
    } catch(e) { toast.error("Failed to update status: "+e.message) }
  }

  const SC = { driver_assigned:"#378add", picked_up:"#8b5cf6", delivered:"#1d9e75" }
  const activeDeliveries = deliveries.filter(d=>d.delivery_status!=="delivered")
  // Only count as genuinely earned once release-order-payment has actually paid out - matching
  // the same fix already applied to DriverEarnings and DriverPayouts.
  const completedDeliveries = deliveries.filter(d=>d.delivery_status==="delivered" && d.driver_payment_released)
  const earnings = completedDeliveries.reduce((s,d)=>s+Number(d.delivery_fee||0)*marketplaceRate,0)

  return (
    <div>
      <div style={{ marginBottom:"1.25rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:"#000000" }}>Deliveries</div>
        <div style={{ fontSize:12, color:"#777777" }}>CCC parts and accessories deliveries</div>
      </div>

      <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Available", value:available.length, color:available.length>0?"#e6821e":"#555" },
          { label:"Active", value:activeDeliveries.length, color:activeDeliveries.length>0?"#378add":"#555" },
          { label:"Earnings", value:"KES "+earnings.toLocaleString(), color:"#1d9e75" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#ffffff", borderRadius:10, padding:"0.75rem", border:"1px solid #eeeeee", textAlign:"center" }}>
            <div style={{ fontFamily:"Syne", fontSize:isMobile?14:18, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:10, color:"#777777", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>

      <div style={{ display:"flex", gap:6, marginBottom:"1rem" }}>
        {[{k:"available",l:"Available jobs"},{k:"active",l:"My deliveries"},{k:"completed",l:"Completed"}].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{ padding:"7px 14px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#1d9e75":"#555555", color:tab===t.k?"#fff":"#666", fontWeight:tab===t.k?700:400 }}>
            {t.l}
          </button>
        ))}
      </div>

      {loading&&<div style={{ color:"#777777", fontSize:13 }}>Loading...</div>}

      {tab==="available"&&(
        <div>
          {available.length===0&&<div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"2rem" }}>No delivery jobs available right now</div>}
          {available.map(o=>(
            <div key={o.id} style={{ background:"#ffffff", border:"1px solid #e6821e30", borderRadius:12, padding:"1rem", marginBottom:10 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:10 }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:600, color:"#000000", marginBottom:2 }}>#{o.order_number}</div>
                  <div style={{ fontSize:11, color:"#777777", display:"flex", alignItems:"center", gap:3 }}><OrdersIcon size={11} color="#777777"/> Pick up from: {o.provider?.business_name||o.provider?.first_name} ┬╖ {o.provider?.city}</div>
                  {o.provider?.latitude&&o.provider?.longitude&&(
                    <a href={`https://www.google.com/maps/dir/?api=1&destination=${o.provider.latitude},${o.provider.longitude}`} target="_blank" rel="noreferrer" style={{ fontSize:11, color:"#e6821e", textDecoration:"none" }}>≡ƒù║∩╕Å Navigate to pickup ΓåÆ</a>
                  )}
                  <div style={{ fontSize:11, color:"#777777", display:"flex", alignItems:"center", gap:3 }}><LocationIcon size={11} color="#777777"/> Deliver to: {o.delivery_address}</div>
                  <div style={{ fontSize:11, color:"#378add" }}>Zone: {o.delivery_zone}</div>
                  <div style={{ fontSize:10, color:"#888888" }}>{o.order_items?.length} item(s)</div>
                </div>
                <div style={{ textAlign:"right" }}>
                  <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#1d9e75" }}>KES {(Number(o.delivery_fee||0)*marketplaceRate).toLocaleString()}</div>
                  <div style={{ fontSize:10, color:"#777777" }}>Your earnings (85%)</div>
                </div>
              </div>
              <button onClick={()=>acceptDelivery(o.id)} style={{ width:"100%", background:"#1d9e75", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"10px", cursor:"pointer" }}>
                <><CheckIcon size={13} color="currentColor"/> Accept delivery</>
              </button>
            </div>
          ))}
        </div>
      )}

      {tab==="active"&&(
        <div>
          {activeDeliveries.length===0&&<div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"2rem" }}>No active deliveries</div>}
          {activeDeliveries.map(o=>(
            <div key={o.id} style={{ background:"#ffffff", border:"1px solid #378add30", borderRadius:12, padding:"1rem", marginBottom:10 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:10 }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:600, color:"#000000", marginBottom:2 }}>#{o.order_number}</div>
                  <div style={{ fontSize:11, color:"#777777" }}>≡ƒôª {o.provider?.business_name||o.provider?.first_name} ┬╖ {o.provider?.city}</div>
                  {o.provider?.latitude&&o.provider?.longitude&&(
                    <a href={`https://www.google.com/maps/dir/?api=1&destination=${o.provider.latitude},${o.provider.longitude}`} target="_blank" rel="noreferrer" style={{ fontSize:11, color:"#e6821e", textDecoration:"none" }}>≡ƒù║∩╕Å Navigate to provider ΓåÆ</a>
                  )}
                  <div style={{ fontSize:11, color:"#777777", display:"flex", alignItems:"center", gap:3 }}><LocationIcon size={11} color="#777777"/> Deliver to: {o.delivery_address}</div>
                  {(() => {
                    // The order's own delivery_latitude/longitude (captured at checkout for
                    // this specific delivery) is the genuinely correct destination - the
                    // customer's general profile location is a stale, often-unset fallback,
                    // not where they actually asked this order to be delivered.
                    const destLat = o.delivery_latitude || o.profiles?.latitude
                    const destLng = o.delivery_longitude || o.profiles?.longitude
                    return destLat && destLng && (
                      <a href={`https://www.google.com/maps/dir/?api=1&destination=${destLat},${destLng}`} target="_blank" rel="noreferrer" style={{ fontSize:11, color:"#378add", textDecoration:"none" }}>≡ƒù║∩╕Å Navigate to customer ΓåÆ</a>
                    )
                  })()}
                  {o.customer_phone&&(
                    <a href={"tel:"+o.customer_phone} style={{ fontSize:11, color:"#1d9e75", textDecoration:"none", display:"block", marginTop:2 }}>≡ƒô₧ Call customer</a>
                  )}
                  <span style={{ fontSize:10, padding:"2px 8px", borderRadius:8, background:(SC[o.delivery_status]||"#888")+"20", color:SC[o.delivery_status]||"#888", display:"inline-block", marginTop:4 }}>
                    {o.delivery_status?.replace(/_/g," ")||"assigned"}
                  </span>
                </div>
                <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#1d9e75" }}>
                  KES {(Number(o.delivery_fee||0)*marketplaceRate).toLocaleString()}
                </div>
              </div>
              {o.delivery_status==="driver_assigned"&&o.delivery_attempt_expires_at&&(
                <div style={{ background: formatCountdown(o.delivery_attempt_expires_at)==="Expired" ? "#fff5f5" : "#fff8f0", border:"1px solid "+(formatCountdown(o.delivery_attempt_expires_at)==="Expired"?"#e24b4a40":"#e6821e40"), borderRadius:8, padding:"0.6rem 0.85rem", marginBottom:10, display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                  <span style={{ fontSize:12, color: formatCountdown(o.delivery_attempt_expires_at)==="Expired" ? "#e24b4a" : "#e6821e", fontWeight:600 }}>
                    ΓÅ░ {formatCountdown(o.delivery_attempt_expires_at)==="Expired" ? "Time expired - reassigning..." : "Accept within "+formatCountdown(o.delivery_attempt_expires_at)}
                  </span>
                </div>
              )}
              <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
                {o.delivery_status==="driver_assigned"&&(
                  <>
                    <button onClick={()=>updateDeliveryStatus(o.id,"picked_up",o.customer_id)} style={{ background:"#faf5ff", border:"1px solid #8b5cf640", borderRadius:7, color:"#8b5cf6", fontSize:11, padding:"6px 14px", cursor:"pointer", fontWeight:600 }}>
                      <><OrdersIcon size={13} color="currentColor"/> Confirm pickup</>
                    </button>
                    <button onClick={()=>declineDelivery(o.id)} style={{ background:"#fff5f5", border:"1px solid #e24b4a40", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"6px 14px", cursor:"pointer", fontWeight:600 }}>
                      <><CloseIcon size={13} color="currentColor"/> Decline</>
                    </button>
                  </>
                )}
                {o.delivery_status==="picked_up"&&arrivedOrder!==o.id&&(
                  <button onClick={()=>generateDeliveryOTP(o.id)} disabled={generatingOtp===o.id} style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:7, color:"#e6821e", fontSize:11, padding:"6px 14px", cursor:"pointer", fontWeight:600 }}>
                    {generatingOtp===o.id?"...":"≡ƒôì I have Arrived"}
                  </button>
                )}
                {o.delivery_status==="picked_up"&&arrivedOrder===o.id&&(
                  <div style={{ display:"flex", gap:6, alignItems:"center" }}>
                    <input type="text" maxLength={4} placeholder="OTP" value={otpInput[o.id]||""}
                      onChange={e=>setOtpInput(prev=>({...prev,[o.id]:e.target.value.replace(/\D/g,"")}))}
                      style={{ width:60, padding:"6px", borderRadius:7, border:"1px solid #ddd", fontSize:14, textAlign:"center", letterSpacing:4 }}/>
                    <button onClick={()=>verifyDeliveryOTP(o)} disabled={otpVerifying===o.id} style={{ background:"#1d9e75", border:"none", borderRadius:7, color:"#fff", fontSize:11, fontWeight:700, padding:"7px 12px", cursor:"pointer" }}>
                      {otpVerifying===o.id?"...":"Verify OTP"}
                    </button>
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {tab==="completed"&&(
        <div>
          {completedDeliveries.length===0&&<div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"2rem" }}>No completed deliveries yet</div>}
          {completedDeliveries.map(o=>(
            <div key={o.id} style={{ background:"#ffffff", border:"1px solid #1d9e7530", borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:600, color:"#000000" }}>#{o.order_number}</div>
                  <div style={{ fontSize:11, color:"#777777" }}>{o.delivery_zone} ┬╖ {new Date(o.created_at).toLocaleDateString()}</div>
                </div>
                <div style={{ textAlign:"right" }}>
                  <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#1d9e75" }}>KES {(Number(o.delivery_fee||0)*marketplaceRate).toLocaleString()}</div>
                  <div style={{ fontSize:10, color:"#777777" }}>earned</div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from "react"
import { WalletIcon, WarningIcon, SuccessIcon, TargetIcon, FuelIcon, PaymentsIcon, DeliveryIcon, LockedIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

export default function DriverEarnings() {
  const { user, profile, updateProfile } = useAuth()
  const isConcierge = profile?.driver_category === "concierge"
  const [orders, setOrders] = useState([])
  const isMobile = useIsMobile()
  const [bookings, setBookings] = useState([])
  const [loading, setLoading] = useState(true)
  const [commissionRate, setCommissionRate] = useState(15)
  const [marketplaceRate, setMarketplaceRate] = useState(85)
  const [period, setPeriod] = useState("week")
  const [expanded, setExpanded] = useState(null)
  const [goalInput, setGoalInput] = useState("")
  const [editingGoal, setEditingGoal] = useState(false)
  const [savingGoal, setSavingGoal] = useState(false)
  const [expenses, setExpenses] = useState([])
  const [expenseForm, setExpenseForm] = useState({ amount:"", expense_date:new Date().toISOString().split("T")[0], odometer:"", notes:"" })
  const [savingExpense, setSavingExpense] = useState(false)
  const [showExpenseForm, setShowExpenseForm] = useState(false)

  useEffect(() => { if (user) load() }, [user])

  async function load() {
    const { data: surchargeData } = await supabase.from("app_settings").select("value").eq("key","concierge_surcharge_rate").maybeSingle()
    if (surchargeData) setCommissionRate(Number(surchargeData.value));
    (async () => {
      // Commission now varies by the driver\'s own vehicle type, not one flat global rate
      const vt = profile?.driver_vehicle_type || "car"
      const { data: vtRate } = await supabase.from("app_settings").select("value").eq("key",`marketplace_driver_commission_rate_${vt}`).maybeSingle()
      if (vtRate) { setMarketplaceRate(Number(vtRate.value)); return }
      const { data: fallback } = await supabase.from("app_settings").select("value").eq("key","marketplace_driver_commission_rate").maybeSingle()
      if (fallback) setMarketplaceRate(Number(fallback.value))
    })()
    const [{ data }, { data: exps }, { data: ords }] = await Promise.all([
      supabase.from("bookings")
        .select("*, vehicles(make,model,license_plate)")
        .eq("driver_id", user.id)
        .eq("status", "completed").eq("is_archived", false).order("created_at", { ascending:false }),
      supabase.from("driver_expenses").select("*").eq("driver_id", user.id).order("expense_date",{ascending:false}),
      supabase.from("orders").select("*").eq("delivery_driver_id", user.id).eq("status","delivered").eq("driver_payment_released",true).order("created_at",{ascending:false})
    ])
    setBookings(data||[])
    setExpenses(exps||[])
    setOrders(ords||[])
    setLoading(false)
  }
  async function saveExpense(e) {
    e.preventDefault()
    if (!expenseForm.amount || Number(expenseForm.amount)<=0) return toast.error("Enter a valid amount")
    setSavingExpense(true)
    try {
      const { error } = await supabase.from("driver_expenses").insert({
        driver_id: user.id,
        expense_type: "fuel",
        amount: Number(expenseForm.amount),
        expense_date: expenseForm.expense_date,
        odometer: expenseForm.odometer?Number(expenseForm.odometer):null,
        notes: expenseForm.notes,
      })
      if (error) throw error
      toast.success("Fuel expense logged!")
      setExpenseForm({ amount:"", expense_date:new Date().toISOString().split("T")[0], odometer:"", notes:"" })
      setShowExpenseForm(false)
      load()
    } catch(err) {
      toast.error(err.message)
    } finally {
      setSavingExpense(false)
    }
  }
  async function deleteExpense(id) {
    if (!confirm("Delete this expense?")) return
    await supabase.from("driver_expenses").delete().eq("id",id)
    toast.success("Expense deleted")
    load()
  }

  function filterByPeriod(bks) {
    const now = new Date()
    if (period==="today") {
      const today = now.toISOString().split("T")[0]
      return bks.filter(b=>b.booking_date===today)
    }
    if (period==="week") {
      const weekAgo = new Date(now-7*24*60*60*1000)
      return bks.filter(b=>new Date(b.booking_date)>=weekAgo)
    }
    if (period==="month") {
      const monthAgo = new Date(now-30*24*60*60*1000)
      return bks.filter(b=>new Date(b.booking_date)>=monthAgo)
    }
    return bks
  }

  const filtered = filterByPeriod(bookings)
  const filteredOrders = orders.filter(o=>{
    const date = new Date(o.created_at)
    if (period==="today") return date.toDateString()===new Date().toDateString()
    if (period==="week") return date>=new Date(Date.now()-7*24*60*60*1000)
    if (period==="month") return date>=new Date(new Date().getFullYear(),new Date().getMonth(),1)
    return true
  })

  // Use orders for marketplace, bookings for concierge
  const totalCommission = isConcierge
    ? filtered.reduce((s,b)=>s+Number(b.total_amount||0)*0.15, 0)
    : filteredOrders.reduce((s,o)=>s+Number(o.delivery_fee||0)*(marketplaceRate/100), 0)
  const totalAllowance = isConcierge ? filtered.reduce((s,b)=>s+Number(b.transport_allowance||200), 0) : 0
  const totalEarnings = totalCommission + totalAllowance
  const totalJobs = isConcierge ? filtered.length : filteredOrders.length
  const avgPerJob = totalJobs ? (totalEarnings/totalJobs).toFixed(0) : 0
  const unpaidCount = isConcierge ? filtered.filter(b=>b.payment_status!=="paid").length : 0
  // Monthly goal tracking (independent of period filter)
  const now = new Date()
  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1)
  const monthEarnings = bookings.filter(b=>new Date(b.booking_date)>=monthStart).reduce((s,b)=>s+Number(b.driver_earnings||0), 0)
  const monthlyGoal = Number(profile?.monthly_earnings_goal || 0)
  const monthFuelExpenses = expenses.filter(e=>new Date(e.expense_date)>=monthStart).reduce((s,e)=>s+Number(e.amount||0), 0)
  const netMonthEarnings = monthEarnings - monthFuelExpenses
  const totalFuelExpenses = expenses.reduce((s,e)=>s+Number(e.amount||0), 0)
  const goalProgress = monthlyGoal>0 ? Math.min(100, Math.round((monthEarnings/monthlyGoal)*100)) : 0

  async function saveGoal() {
    const val = Number(goalInput)
    if (!val || val<=0) return toast.error("Enter a valid goal amount")
    setSavingGoal(true)
    try {
      await updateProfile({ monthly_earnings_goal: val })
      toast.success("Goal updated!")
      setEditingGoal(false)
    } catch(err) {
      toast.error(err.message)
    } finally {
      setSavingGoal(false)
    }
  }

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:18, fontWeight:800, color:"#000000", marginBottom:"1.25rem" }}>Earnings & History</div>

      {/* Period filter */}
      <div style={{ display:"flex", gap:6, marginBottom:"1.25rem" }}>
        {["today","week","month","all"].map(p=>(
          <button key={p} onClick={()=>setPeriod(p)}
            style={{ padding:"7px 16px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:period===p?"#1d9e75":"#f0f0f0", color:period===p?"#fff":"#666", fontFamily:"'DM Sans',sans-serif", fontWeight:period===p?700:400 }}>
            {p==="today"?"Today":p==="week"?"This week":p==="month"?"This month":"All time"}
          </button>
        ))}
      </div>

      {/* Earnings breakdown */}
      <div style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:12, padding:"1.25rem", marginBottom:"1.5rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#1d9e75", marginBottom:"1rem", display:"flex", alignItems:"center", gap:6 }}><WalletIcon size={14} color="#1d9e75"/> Earnings breakdown</div>
        <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr 1fr":"repeat(4,1fr)", gap:10, marginBottom:12 }}>
          {[
            { label:isConcierge?`Commission (${commissionRate}%)`:`Delivery earnings (${marketplaceRate}%)`, value:`KES ${totalCommission.toFixed(0)}`, color:"#378add" },
            { label:"Transport allowance", value:`KES ${totalAllowance.toFixed(0)}`, color:"#e6821e" },
            { label:"Total earned", value:`KES ${totalEarnings.toFixed(0)}`, color:"#1d9e75" },
            { label:"Avg per job", value:`KES ${Number(avgPerJob).toLocaleString()}`, color:"#8b5cf6" },
          ].map(s=>(
            <div key={s.label} style={{ background:"#ffffff", borderRadius:8, padding:"0.75rem", textAlign:"center" }}>
              <div style={{ fontFamily:"Syne", fontSize:isMobile?13:16, fontWeight:800, color:s.color }}>{s.value}</div>
              <div style={{ fontSize:9, color:"#888888", marginTop:2 }}>{s.label}</div>
            </div>
          ))}
        </div>
        <div style={{ display:"flex", justifyContent:"space-between", fontSize:11, color:"#777777" }}>
          <span>{totalJobs} job{totalJobs!==1?"s":""} completed</span>
          {unpaidCount>0&&<span style={{ color:"#e6821e", display:"flex", alignItems:"center", gap:3 }}><WarningIcon size={12} color="#e6821e"/> {unpaidCount} pending payment</span>}
        </div>
      </div>

      {/* Monthly goal tracker */}
      <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem", marginBottom:"1.5rem" }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#000000", display:"flex", alignItems:"center", gap:6 }}><TargetIcon size={14} color="#e6821e"/> Monthly earnings goal</div>
          {!editingGoal&&<button onClick={()=>{ setEditingGoal(true); setGoalInput(monthlyGoal?String(monthlyGoal):"") }} style={{ background:"none", border:"1px solid #dddddd", borderRadius:7, color:"#666", fontSize:11, padding:"4px 10px", cursor:"pointer" }}>{monthlyGoal>0?"Edit":"Set goal"}</button>}
        </div>
        {editingGoal?(
          <div style={{ display:"flex", gap:8 }}>
            <input type="number" min="0" value={goalInput} onChange={e=>setGoalInput(e.target.value)} placeholder="e.g. 20000"
              style={{ flex:1, background:"#f8f8f8", border:"1px solid #f0f0f0", borderRadius:8, padding:"10px 12px", color:"#000000", fontSize:13, outline:"none" }}/>
            <button onClick={saveGoal} disabled={savingGoal} style={{ background:"#1d9e75", border:"none", borderRadius:8, color:"#fff", fontSize:12, fontWeight:700, padding:"0 16px", cursor:"pointer" }}>
              {savingGoal?"...":"Save"}
            </button>
            <button onClick={()=>setEditingGoal(false)} style={{ background:"none", border:"1px solid #dddddd", borderRadius:8, color:"#666", fontSize:12, padding:"0 14px", cursor:"pointer" }}>
              Cancel
            </button>
          </div>
        ):monthlyGoal>0?(
          <div>
            <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, color:"#555555", marginBottom:6 }}>
              <span>KES {monthEarnings.toFixed(0)} earned this month</span>
              <span style={{ fontWeight:700, color:goalProgress>=100?"#1d9e75":"#e6821e" }}>{goalProgress}%</span>
            </div>
            <div style={{ height:8, background:"#f0f0f0", borderRadius:4, overflow:"hidden" }}>
              <div style={{ height:"100%", background:goalProgress>=100?"#1d9e75":"#e6821e", borderRadius:4, width:(goalProgress+"%"), transition:"width 0.5s" }}/>
            </div>
            <div style={{ fontSize:11, color:"#888888", marginTop:6 }}>
              {goalProgress>=100?"≡ƒÄë Goal reached! Great work.":"KES "+(monthlyGoal-monthEarnings).toFixed(0)+" to go ΓÇö Goal: KES "+monthlyGoal.toLocaleString()}
            </div>
          </div>
        ):(
          <div style={{ fontSize:12, color:"#888888" }}>Set a monthly earnings goal to track your progress.</div>
        )}
      </div>
      {/* Fuel expense tracker */}
      <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem", marginBottom:"1.5rem" }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#000000", display:"flex", alignItems:"center", gap:6 }}><FuelIcon size={14} color="#e6821e"/> Fuel expenses</div>
          <button onClick={()=>setShowExpenseForm(!showExpenseForm)} style={{ background:showExpenseForm?"none":"#e6821e", border:showExpenseForm?"1px solid #dddddd":"none", borderRadius:7, color:showExpenseForm?"#666":"#fff", fontSize:11, fontWeight:700, padding:"5px 12px", cursor:"pointer" }}>
            {showExpenseForm?"Cancel":"+ Log expense"}
          </button>
        </div>

        {showExpenseForm&&(
          <form onSubmit={saveExpense} style={{ background:"#f8f8f8", borderRadius:8, padding:"0.9rem", marginBottom:"1rem" }}>
            <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr 1fr":"repeat(4,1fr)", gap:8, marginBottom:8 }}>
              <div>
                <label style={{ fontSize:10, color:"#666", display:"block", marginBottom:4 }}>Amount (KES)</label>
                <input type="number" min="0" value={expenseForm.amount} onChange={e=>setExpenseForm(f=>({...f,amount:e.target.value}))} placeholder="500" required
                  style={{ width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:7, padding:"8px 10px", color:"#000000", fontSize:12, outline:"none" }}/>
              </div>
              <div>
                <label style={{ fontSize:10, color:"#666", display:"block", marginBottom:4 }}>Date</label>
                <input type="date" value={expenseForm.expense_date} onChange={e=>setExpenseForm(f=>({...f,expense_date:e.target.value}))}
                  style={{ width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:7, padding:"8px 10px", color:"#000000", fontSize:12, outline:"none" }}/>
              </div>
              <div>
                <label style={{ fontSize:10, color:"#666", display:"block", marginBottom:4 }}>Odometer (km, optional)</label>
                <input type="number" min="0" value={expenseForm.odometer} onChange={e=>setExpenseForm(f=>({...f,odometer:e.target.value}))} placeholder="45000"
                  style={{ width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:7, padding:"8px 10px", color:"#000000", fontSize:12, outline:"none" }}/>
              </div>
              <div>
                <label style={{ fontSize:10, color:"#666", display:"block", marginBottom:4 }}>Notes (optional)</label>
                <input value={expenseForm.notes} onChange={e=>setExpenseForm(f=>({...f,notes:e.target.value}))} placeholder="e.g. Shell station"
                  style={{ width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:7, padding:"8px 10px", color:"#000000", fontSize:12, outline:"none" }}/>
              </div>
            </div>
            <button type="submit" disabled={savingExpense} style={{ background:savingExpense?"#ccc":"#1d9e75", border:"none", borderRadius:8, color:"#fff", fontSize:12, fontWeight:700, padding:"8px 18px", cursor:savingExpense?"not-allowed":"pointer" }}>
              {savingExpense?"Saving...":"Log fuel expense"}
            </button>
          </form>
        )}

        <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr 1fr":"repeat(3,1fr)", gap:10, marginBottom:expenses.length>0?"1rem":0 }}>
          <div style={{ background:"#fff5f5", borderRadius:8, padding:"0.75rem", textAlign:"center" }}>
            <div style={{ fontFamily:"Syne", fontSize:isMobile?13:16, fontWeight:800, color:"#e24b4a" }}>KES {monthFuelExpenses.toFixed(0)}</div>
            <div style={{ fontSize:9, color:"#888888", marginTop:2 }}>Fuel this month</div>
          </div>
          <div style={{ background:"#f0fdf4", borderRadius:8, padding:"0.75rem", textAlign:"center" }}>
            <div style={{ fontFamily:"Syne", fontSize:isMobile?13:16, fontWeight:800, color:netMonthEarnings>=0?"#1d9e75":"#e24b4a" }}>KES {netMonthEarnings.toFixed(0)}</div>
            <div style={{ fontSize:9, color:"#888888", marginTop:2 }}>Net this month (after fuel)</div>
          </div>
          <div style={{ background:"#f8f8f8", borderRadius:8, padding:"0.75rem", textAlign:"center" }}>
            <div style={{ fontFamily:"Syne", fontSize:isMobile?13:16, fontWeight:800, color:"#888" }}>KES {totalFuelExpenses.toFixed(0)}</div>
            <div style={{ fontSize:9, color:"#888888", marginTop:2 }}>Total fuel logged</div>
          </div>
        </div>

        {expenses.slice(0,5).map(exp=>(
          <div key={exp.id} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", padding:"8px 0", borderBottom:"1px solid #f0f0f0", fontSize:12 }}>
            <div>
              <span style={{ color:"#000000", fontWeight:600 }}>KES {Number(exp.amount).toFixed(0)}</span>
              <span style={{ color:"#888888", marginLeft:8 }}>{exp.expense_date}</span>
              {exp.odometer&&<span style={{ color:"#888888", marginLeft:8 }}>┬╖ {Number(exp.odometer).toLocaleString()} km</span>}
              {exp.notes&&<span style={{ color:"#888888", marginLeft:8 }}>┬╖ {exp.notes}</span>}
            </div>
            <button onClick={()=>deleteExpense(exp.id)} style={{ background:"none", border:"none", color:"#e24b4a", fontSize:11, cursor:"pointer" }}>Delete</button>
          </div>
        ))}
      </div>
      {/* How earnings work */}
      <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:10, padding:"0.9rem", marginBottom:"1.5rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:12, fontWeight:700, color:"#000000", marginBottom:8 }}>How your earnings work</div>
        {(isConcierge ? [
          { icon:"payments", label:"Commission", desc:`${commissionRate}% of service fee ΓÇö paid after delivery complete` },
          { icon:"delivery", label:"Transport allowance", desc:"KES 200 per job ΓÇö covers your travel costs" },
          { icon:"locked", label:"Payment security", desc:"Both are released only after you complete the delivery and file the dropoff report" },
          { icon:"warning", label:"No-show penalty", desc:"If you accept a job and don't show up, you lose both the commission and allowance" },
        ] : [
          { icon:"payments", label:"Delivery earnings", desc:`${Math.round(marketplaceRate)}% of the delivery fee ΓÇö paid automatically once the customer confirms receipt` },
          { icon:"locked", label:"Payment security", desc:"Released only after the customer provides the delivery verification code to you in person" },
          { icon:"warning", label:"Decline policy", desc:"Declining or missing deliveries too often may affect your ability to receive new job offers" },
        ]).map(item=>(
          <div key={item.label} style={{ display:"flex", gap:10, alignItems:"flex-start", marginBottom:8 }}>
            <span style={{flexShrink:0,display:"flex"}}>{item.icon==="payments"?<PaymentsIcon size={16} color="#e6821e"/>:item.icon==="delivery"?<DeliveryIcon size={16} color="#378add"/>:item.icon==="locked"?<LockedIcon size={16} color="#1d9e75"/>:<WarningIcon size={16} color="#e6821e"/>}</span>
            <div>
              <div style={{ fontSize:12, color:"#000000", fontWeight:600 }}>{item.label}</div>
              <div style={{ fontSize:11, color:"#777777", lineHeight:1.4 }}>{item.desc}</div>
            </div>
