                      {p.status}
                    </span>
                  </div>
                  {!isRejected&&(
                    <div style={{ display:"flex", alignItems:"center" }}>
                      {steps.map((s,i)=>(
                        <div key={s.key} style={{ display:"flex", alignItems:"center", flex:i<steps.length-1?1:"none" }}>
                          <div style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:4 }}>
                            <div style={{ width:22, height:22, borderRadius:"50%", background:i<=currentStepIdx?"#1d9e75":"#f0f0f0", color:i<=currentStepIdx?"#fff":"#aaa", display:"flex", alignItems:"center", justifyContent:"center", fontSize:11, fontWeight:700 }}>
                              {i<currentStepIdx?"Γ£ô":i+1}
                            </div>
                            <div style={{ fontSize:9, color:i<=currentStepIdx?"#1d9e75":"#aaa", fontWeight:i===currentStepIdx?700:400, whiteSpace:"nowrap" }}>{s.label}</div>
                          </div>
                          {i<steps.length-1&&(
                            <div style={{ flex:1, height:2, background:i<currentStepIdx?"#1d9e75":"#f0f0f0", marginBottom:14 }}/>
                          )}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )})}
            </div>
          )}
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from "react"
import { VehicleIcon, MotorcycleIcon, TukTukIcon, DeliveryIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"

export default function DriverPerformance() {
  const { user, profile } = useAuth()
  const isMobile = useIsMobile()
  const [stats, setStats] = useState(null)
  const [loading, setLoading] = useState(true)
  const [marketplaceRate, setMarketplaceRate] = useState(0.85)
  const [recentJobs, setRecentJobs] = useState([])

  useEffect(() => { if (user) load() }, [user])

  async function load() {
    supabase.from("app_settings").select("value").eq("key","marketplace_driver_commission_rate").maybeSingle().then(({data}) => { if (data) setMarketplaceRate(Number(data.value)/100) })
    const [{ data: bks }, { data: revs }, { data: status }, { data: ords }] = await Promise.all([
      supabase.from("bookings").select("status,total_amount,created_at,service_name,driver_earnings").eq("driver_id", user.id),
      supabase.from("reviews").select("driver_rating,driver_review,created_at").eq("driver_id", user.id).order("created_at",{ascending:false}),
      supabase.from("driver_status").select("*").eq("driver_id", user.id).single(),
      supabase.from("orders").select("status,delivery_fee,created_at,order_number").eq("delivery_driver_id", user.id),
    ])
    const isConciergeLoad = profile?.driver_category === "concierge"
    const all = isConciergeLoad ? (bks||[]) : (ords||[])
    const completed = all.filter(b=>b.status==="completed")
    const cancelled = all.filter(b=>b.status==="cancelled")
    const avgRating = revs?.length ? (revs.reduce((s,r)=>s+Number(r.driver_rating||0),0)/revs.length).toFixed(1) : "ΓÇö"
    const acceptanceRate = all.length ? Math.round((completed.length/all.length)*100) : 0
    const completionRate = all.length ? Math.round(((all.length-cancelled.length)/all.length)*100) : 0
    setStats({
      total: all.length,
      completed: completed.length,
      cancelled: cancelled.length,
      avgRating,
      acceptanceRate,
      completionRate,
      noShows: status?.no_show_count||0,
      totalEarnings: isConciergeLoad ? completed.reduce((s,b)=>s+Number(b.driver_earnings||0),0) : completed.reduce((s,o)=>s+Number(o.delivery_fee||0)*marketplaceRate,0),
      onlineHours: 0,
    })
    setRecentJobs(all.slice(0,10).map(j=>({ ...j, service_name: j.service_name || "Order #"+(j.order_number||"") })))
    setLoading(false)
  }

  const vehicleConfig = {
    car: { icon:"vehicle", label:"Car Driver" },
    motorcycle: { icon:"motorcycle", label:"Boda Boda" },
    tuktuk: { icon:"tuktuk", label:"Tuktuk" },
    van: { icon:"delivery", label:"Van Driver" },
  }
  const isConcierge = profile?.driver_category === "concierge"
  const vc = isConcierge ? { icon:"≡ƒºæΓÇìΓ£ê∩╕Å", label:"Concierge Driver" } : (vehicleConfig[profile?.driver_vehicle_type||"car"])

  if (loading) return <div style={{ color:"#777777", fontSize:13 }}>Loading...</div>

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:"#000000", marginBottom:4 }}>Performance</div>
      <div style={{ fontSize:12, color:"#777777", marginBottom:"1.5rem" }}>Your driving stats and ratings</div>

      {/* Rating highlight */}
      <div style={{ background:"#fff8f0", border:"1px solid #e6821e30", borderRadius:16, padding:"1.5rem", marginBottom:"1.5rem", textAlign:"center" }}>
        <div style={{ fontFamily:"Syne", fontSize:48, fontWeight:800, color:"#e6821e" }}>{stats.avgRating}</div>
        <div style={{ fontSize:13, color:"#555555", marginBottom:4 }}>Average rating</div>
        <div style={{ fontSize:12, color:"#777777" }}>{vc.icon} {vc.label}</div>
      </div>

      {/* Stats grid */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(2,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Total jobs", value:stats.total, color:"#000000" },
          { label:"Completed", value:stats.completed, color:"#1d9e75" },
          { label:"Acceptance rate", value:stats.acceptanceRate+"%", color:stats.acceptanceRate>=80?"#1d9e75":"#e6821e" },
          { label:"Completion rate", value:stats.completionRate+"%", color:stats.completionRate>=90?"#1d9e75":"#e6821e" },
          { label:"No-shows", value:stats.noShows, color:stats.noShows>0?"#e24b4a":"#555" },
          { label:"Total earned", value:"KES "+stats.totalEarnings.toLocaleString(), color:"#8b5cf6" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#ffffff", borderRadius:12, padding:"1rem", border:"1px solid #eeeeee", textAlign:"center" }}>
            <div style={{ fontFamily:"Syne", fontSize:isMobile?18:22, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:11, color:"#777777", marginTop:4 }}>{s.label}</div>
          </div>
        ))}
      </div>

      {/* Performance indicators */}
      <div style={{ background:"#ffffff", borderRadius:12, padding:"1rem", marginBottom:"1.5rem", border:"1px solid #eeeeee" }}>
        <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#000000", marginBottom:12 }}>Performance indicators</div>
        {[
          { label:"Rating", value:parseFloat(stats.avgRating)||0, max:5, good:4.0, color:"#e6821e" },
          { label:"Acceptance rate", value:stats.acceptanceRate, max:100, good:80, color:"#1d9e75" },
          { label:"Completion rate", value:stats.completionRate, max:100, good:90, color:"#378add" },
        ].map(ind=>(
          <div key={ind.label} style={{ marginBottom:12 }}>
            <div style={{ display:"flex", justifyContent:"space-between", marginBottom:4 }}>
              <span style={{ fontSize:12, color:"#555555" }}>{ind.label}</span>
              <span style={{ fontSize:12, color:ind.value>=ind.good?ind.color:"#e24b4a", fontWeight:600 }}>{ind.label==="Rating"?ind.value+"/5":ind.value+"%"}</span>
            </div>
            <div style={{ background:"#f0f0f0", borderRadius:4, height:6, overflow:"hidden" }}>
              <div style={{ width:(ind.value/ind.max*100)+"%", height:"100%", background:ind.value>=ind.good?ind.color:"#e24b4a", borderRadius:4, transition:"width 0.5s" }}/>
            </div>
          </div>
        ))}
      </div>

      {/* Recent jobs */}
      <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#000000", marginBottom:10 }}>Recent jobs</div>
      {recentJobs.length===0&&<div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"2rem" }}>No jobs yet</div>}
      {recentJobs.map((job,i)=>(
        <div key={i} style={{ background:"#ffffff", borderRadius:10, padding:"0.75rem", marginBottom:8, display:"flex", justifyContent:"space-between", alignItems:"center", border:"1px solid #eeeeee" }}>
          <div>
            <div style={{ fontSize:13, color:"#000000", marginBottom:2 }}>{job.service_name||"Delivery job"}</div>
            <div style={{ fontSize:11, color:"#777777" }}>{new Date(job.created_at).toLocaleDateString()}</div>
          </div>
          <span style={{ fontSize:11, padding:"3px 10px", borderRadius:20, background:job.status==="completed"?"#f0fdf4":job.status==="cancelled"?"#fff5f5":"#fff8f0", color:job.status==="completed"?"#1d9e75":job.status==="cancelled"?"#e24b4a":"#e6821e" }}>
            {job.status}
          </span>
        </div>
      ))}
    </div>
  )
}

import { useEffect, useState } from "react"
import { VehicleIcon, MotorcycleIcon, TukTukIcon, DeliveryIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import { pushNotify } from "../../lib/pushNotify"
import { sanitizeName, sanitizePhone, sanitizeFreeText } from "../../lib/sanitize"
import { validatePassword } from "../../lib/passwordValidation"
import { validateFile, sanitizeFilePath } from "../../lib/uploadValidation"
import { useAuth } from "../../contexts/AuthContext"
import { useLanguage } from "../../contexts/LanguageContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const LICENSE_CLASSES = ["Class B - Light Motor Vehicle", "Class C - Heavy Motor Vehicle", "Class D - Motorcycle", "Class E - PSV", "Class F - Special Vehicle"]

const DRIVER_VEHICLE_TYPES = [
  { key:"car", label:"Car", icon:"vehicle", desc:"Standard delivery" },
  { key:"motorcycle", label:"Boda Boda", icon:"motorcycle", desc:"Fast parts delivery" },
  { key:"tuktuk", label:"Tuktuk", icon:"tuktuk", desc:"Local delivery" },
  { key:"van", label:"Van/Pickup", icon:"delivery", desc:"Large items" },
]

export default function DriverProfile() {
  const { user, profile, updateProfile } = useAuth()
  const { t } = useLanguage()
  const isMobile = useIsMobile()
  const [tab, setTab] = useState("personal")
  const [saving, setSaving] = useState(false)
  const [stats, setStats] = useState({ total:0, completed:0, rating:0, earnings:0 })
  const [sensitive, setSensitive] = useState({ phone:"", email:"", mpesa_number:"", pochi_number:"", preferred_payment_method:"mpesa" })

  const [vehicleType, setVehicleType] = useState("car")
  const [personalForm, setPersonalForm] = useState({
    first_name:"", last_name:"", city:""
  })

  const [profilePhotoFile, setProfilePhotoFile] = useState(null)
  const [uploading, setUploading] = useState(false)
  const [docs, setDocs] = useState([])
  const [docForm, setDocForm] = useState({ type:"license", expiry_date:"", notes:"" })
  const [docUploading, setDocUploading] = useState(false)
  
  const [credentialsForm, setCredentialsForm] = useState({
    id_number:"",
    license_number:"",
    license_expiry:"",
    license_class:"Class B - Light Motor Vehicle",
    years_experience:"",
    emergency_contact_name:"",
    emergency_contact_phone:"",
  })

  const [passwordForm, setPasswordForm] = useState({ password:"", confirm:"" })

  useEffect(() => {
    if (user) loadDocs()
    if (profile) {
      setPersonalForm({
        first_name: profile?.first_name||"",
        last_name: profile?.last_name||"",
        city: profile?.city||"",
      })
      setCredentialsForm({
        id_number: profile?.id_number||"",
        license_number: profile?.license_number||"",
        license_expiry: profile?.license_expiry||"",
        license_class: profile?.license_class||"Class B - Light Motor Vehicle",
        years_experience: profile?.years_experience||"",
        emergency_contact_name: profile?.emergency_contact_name||"",
        emergency_contact_phone: profile?.emergency_contact_phone||"",
        kra_pin_number: profile?.kra_pin_number||"",
        psv_badge_number: profile?.psv_badge_number||"",
      })
    }
    if (user) { loadSensitive(); loadStats() }
  }, [profile, user])

  async function loadSensitive() {
    const { data } = await supabase.from("profile_sensitive").select("phone,email,mpesa_number,pochi_number,preferred_payment_method").eq("id", user.id).maybeSingle()
    if (data) setSensitive({ phone:data.phone||"", email:data.email||"", mpesa_number:data.mpesa_number||"", pochi_number:data.pochi_number||"", preferred_payment_method:data.preferred_payment_method||"mpesa" })
  }

  async function loadStats() {
    const [{ data: bks }, { data: revs }] = await Promise.all([
      supabase.from("bookings").select("id,status,driver_earnings").eq("driver_id", user.id),
      supabase.from("reviews").select("driver_rating").eq("driver_id", user.id).not("driver_rating","is",null),
    ])
    const completed = bks?.filter(b=>b.status==="completed")||[]
    const totalEarnings = completed.reduce((s,b)=>s+Number(b.driver_earnings||0),0)
    const avgRating = revs?.length ? (revs.reduce((s,r)=>s+Number(r.driver_rating||0),0)/revs.length).toFixed(1) : "ΓÇö"
    setStats({ total:bks?.length||0, completed:completed.length, rating:avgRating, earnings:totalEarnings })
  }

  async function savePersonal(e) {
    e.preventDefault()
    setSaving(true)
    try {
      await updateProfile({ ...personalForm, driver_vehicle_type: vehicleType })
      toast.success("Personal info saved")
    } catch(err) { toast.error(err.message) }
    finally { setSaving(false) }
  }

  async function uploadDocument(file, type) {
    const _v = validateFile(file, "document")
    if (!_v.valid) { toast.error(_v.error); return }

    if (!file) return null
    const ext = file.name.split(".").pop()
    const path = `${user.id}/${type}-${Date.now()}.${ext}`
    const { error } = await supabase.storage.from("driver-documents").upload(path, file, { upsert:true })
    if (error) throw error
    const { data } = supabase.storage.from("driver-documents").getPublicUrl(path)
    return data.publicUrl
  }

  async function saveCredentials(e) {
    e.preventDefault()
    setSaving(true)
    setUploading(true)
    try {
      let profilePhotoUrl = profile?.profile_photo_url
      if (profilePhotoFile) profilePhotoUrl = await uploadDocument(profilePhotoFile, "profile")
      await updateProfile({
        ...credentialsForm,
        years_experience: parseInt(credentialsForm.years_experience)||0,
        profile_photo_url: profilePhotoUrl,
      })
      toast.success("Credentials saved ΓÇö pending admin verification")
    } catch(err) { toast.error(err.message) }
    finally { setSaving(false); setUploading(false) }
  }

  async function loadDocs() {
    const { data } = await supabase.from("driver_documents")
      .select("*").eq("driver_id", user.id).order("created_at", { ascending:false })
    setDocs(data||[])
  }

  async function uploadDoc(file, docType, expiryDate) {
    if (!file) return null
    const ext = file.name.split(".").pop()
    const path = `${user.id}/${docType}-${Date.now()}.${ext}`
    const { error } = await supabase.storage.from("driver-documents").upload(path, file, { upsert:true })
    if (error) throw error
    const { data } = supabase.storage.from("driver-documents").getPublicUrl(path)
    return data.publicUrl
  }

  async function addDocument(e) {
    e.preventDefault()
    if (!docForm.file) return toast.error("Please select a file")
    setDocUploading(true)
    try {
      const url = await uploadDoc(docForm.file, docForm.type, docForm.expiry_date)
      await supabase.from("driver_documents").insert({
        driver_id: user.id,
        type: docForm.type,
        document_url: url,
        expiry_date: docForm.expiry_date||null,
        is_verified: false,
      })

      // Also update profile URL columns
      const urlMap = {
        license: "license_document_url",
        id_front: "id_doc_front_url",
        id_back: "id_doc_back_url",
        psv_badge: "psv_badge_url",
        good_conduct: "good_conduct_url",
        insurance: "insurance_url",
      }
      if (urlMap[docForm.type]) {
        await updateProfile({ [urlMap[docForm.type]]: url })
      }

      toast.success("Document uploaded!")
      setDocForm({ type:"license", expiry_date:"", notes:"" })
      loadDocs()
    } catch(err) { toast.error(err.message) }
    finally { setDocUploading(false) }
  }

  async function deleteDoc(id) {
    if (!confirm("Remove this document?")) return
    await supabase.from("driver_documents").delete().eq("id", id)
    loadDocs()
    toast.success("Document removed")
  }

  async function saveContact(e) {
    e.preventDefault()
    setSaving(true)
    try {
      await supabase.from("profile_sensitive").update({ phone:sensitive.phone, mpesa_number:sensitive.mpesa_number||null, pochi_number:sensitive.pochi_number||null, preferred_payment_method:sensitive.preferred_payment_method||"mpesa" }).eq("id", user.id)
      toast.success("Contact saved")
    } catch(err) { toast.error(err.message) }
    finally { setSaving(false) }
  }

  async function changePassword(e) {
    e.preventDefault()
    if (passwordForm.password !== passwordForm.confirm) return toast.error("Passwords do not match")
    const pwError = validatePassword(passwordForm.password); if (pwError) return toast.error(pwError)
    const { error } = await supabase.auth.updateUser({ password: passwordForm.password })
    if (error) return toast.error(error.message)
    toast.success("Password changed")
    setPasswordForm({ password:"", confirm:"" })
  }

  const initials = `${profile?.first_name?.[0]||""}${profile?.last_name?.[0]||""}`.toUpperCase()
  const inp = { width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"11px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif", marginBottom:12 }
