            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:"1rem", color:"#000000" }}>Change password</div>
            <label style={lbl}>New password</label>
            <input style={inp} type="password" placeholder="Min 8 characters, 1 number" value={passwordForm.password} onChange={e=>setPasswordForm(f=>({...f,password:e.target.value}))} required/>
            <label style={lbl}>Confirm password</label>
            <input style={inp} type="password" placeholder="Repeat password" value={passwordForm.confirm} onChange={e=>setPasswordForm(f=>({...f,confirm:e.target.value}))} required/>
            <button type="submit"
              style={{ background:"#1d9e75", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px 24px", cursor:"pointer" }}>
              Change password
            </button>
          </div>
        </form>
      )}

      {/* Danger Zone */}
      <div style={{ background:"#fff5f5", border:"1px solid #e24b4a30", borderRadius:12, padding:"1.25rem", marginTop:"1.5rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:700, color:"#e24b4a", marginBottom:6 }}>Danger Zone</div>
        <div style={{ fontSize:13, color:"#666", marginBottom:12, lineHeight:1.6 }}>
          Deleting your account permanently removes all your data within 7 days. Active bookings must be resolved first.
        </div>
        <button onClick={async()=>{
          const{data:ab}=await supabase.from("bookings").select("id").eq("driver_id",user.id).in("status",["pending","confirmed","in-progress"])
          if(ab?.length>0)return toast.error("Resolve active bookings first.")
          if(!window.confirm("Delete your account? This cannot be undone."))return
          await supabase.from("deletion_requests").insert({ user_id:user.id, requested_at:new Date().toISOString(), scheduled_for:new Date(Date.now()+7*24*60*60*1000).toISOString(), status:"pending", reason:"User requested deletion from app" })
          // Notify admin
          const { data: admins } = await supabase.from("profiles").select("id").eq("role","admin")
          if(admins?.length > 0) {
            await supabase.from("notifications").insert(admins.map(a=>({
              user_id: a.id,
              type: "account_deletion",
              title: "Account deletion request",
              message: (profile?.first_name||"A user") + " ("+user.id.slice(0,8)+") has requested account deletion. Scheduled for " + new Date(Date.now()+7*24*60*60*1000).toLocaleDateString(),
              data: { user_id: user.id }
            })))
          }
          toast.success("Deletion requested. You will be signed out.")
          // Notify admin
          supabase.from("profiles").select("id").eq("role","admin").then(({data:admins})=>{
            if(admins?.length>0) {
              supabase.from("notifications").insert(admins.map(a=>({
                user_id:a.id, type:"account_deletion",
                title:"Account deletion request ΓÜá∩╕Å",
                message:"A "+user?.user_metadata?.role+" has requested account deletion.",
                data:{ user_id:user.id }
              })))
              // Send push to all admins
              admins.forEach(a => pushNotify.accountDeletionRequest(a.id, user?.user_metadata?.first_name||"A user", user.id))
            }
          })
          setTimeout(()=>supabase.auth.signOut(),2000)
        }} style={{ background:"#fff", border:"1px solid #e24b4a", borderRadius:8, color:"#e24b4a", fontSize:13, fontWeight:600, padding:"10px 20px", cursor:"pointer" }}>
          Request Account Deletion
        </button>
      </div>
    </div>
  )
}

import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

export default function DriverReviews() {
  const { user } = useAuth()
  const isMobile = useIsMobile()
  const [reviews, setReviews] = useState([])
  const [loading, setLoading] = useState(true)
  const [replying, setReplying] = useState(null)
  const [replyText, setReplyText] = useState("")
  const [submitting, setSubmitting] = useState(false)
  const [filter, setFilter] = useState("all")

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("driver-reviews-"+user.id)
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"reviews", filter:"driver_id=eq."+user.id }, () => {
        load()
        toast("New review received!", { icon:"Γ¡É" })
      }).subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function load() {
    const { data } = await supabase.from("reviews")
      .select("*, customer:profile_public!reviews_customer_id_fkey(first_name,last_name)")
      .eq("driver_id", user.id)
      .not("driver_rating", "is", null)
      .order("created_at", { ascending:false })
    setReviews(data||[])
    setLoading(false)
  }

  async function submitReply(id) {
    if (!replyText.trim()) return toast.error("Please write a reply")
    setSubmitting(true)
    const { error } = await supabase.from("reviews")
      .update({ driver_response: replyText })
      .eq("id", id)
      .eq("driver_id", user.id)
    if (error) { toast.error(error.message); setSubmitting(false); return }
    toast.success("Reply posted")
    try {
      const review = reviews.find(r=>r.id===id)
      if(review?.customer_id) {
        await fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/send-push`, {
          method:"POST",
          headers:{"Content-Type":"application/json","Authorization":`Bearer ${import.meta.env.VITE_SUPABASE_ANON_KEY}`},
          body:JSON.stringify({ user_id:review.customer_id, title:"Driver replied to your review ≡ƒÆ¼", message:"Your driver has responded to your review." })
        })
        await supabase.from("notifications").insert({ user_id:review.customer_id, title:"Driver replied to your review ≡ƒÆ¼", message:"Your driver has responded to your review.", type:"info" })
      }
    } catch(e) { console.log("Push failed:",e.message) }
    setReplying(null); setReplyText(""); setSubmitting(false); load()
  }

  const avgRating = reviews.length > 0
    ? (reviews.reduce((s,r)=>s+(r.driver_rating||0),0)/reviews.length).toFixed(1)
    : "0.0"
  const dist = [5,4,3,2,1].map(n => ({
    star: n,
    count: reviews.filter(r=>r.driver_rating===n).length,
    pct: reviews.length ? Math.round(reviews.filter(r=>r.driver_rating===n).length/reviews.length*100) : 0
  }))

  const filtered = filter==="replied" ? reviews.filter(r=>r.driver_response) :
    filter==="pending" ? reviews.filter(r=>!r.driver_response) : reviews

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:18, fontWeight:800, marginBottom:"1.25rem" }}>My Ratings</div>
      {reviews.length > 0 && (
        <div style={{ background:"#fff", border:"1px solid #eee", borderRadius:12, padding:"1.25rem", marginBottom:"1.25rem", display:"flex", gap:"1.5rem", alignItems:"center" }}>
          <div style={{ textAlign:"center", flexShrink:0 }}>
            <div style={{ fontFamily:"Syne", fontSize:40, fontWeight:800, color:"#378add", lineHeight:1 }}>{avgRating}</div>
            <div style={{ display:"flex", justifyContent:"center", gap:2, margin:"6px 0" }}>
              {[1,2,3,4,5].map(s=>(
                <span key={s} style={{ color:s<=Math.round(avgRating)?"#378add":"#ddd", fontSize:18 }}>Γÿà</span>
              ))}
            </div>
            <div style={{ fontSize:11, color:"#777" }}>{reviews.length} rating{reviews.length!==1?"s":""}</div>
          </div>
          <div style={{ flex:1 }}>
            {dist.map(d=>(
              <div key={d.star} style={{ display:"flex", alignItems:"center", gap:8, marginBottom:5 }}>
                <div style={{ fontSize:11, color:"#555", width:10 }}>{d.star}</div>
                <span style={{ color:"#378add", fontSize:12 }}>Γÿà</span>
                <div style={{ flex:1, height:6, background:"#f0f0f0", borderRadius:3, overflow:"hidden" }}>
                  <div style={{ height:"100%", background:"#378add", borderRadius:3, width:d.pct+"%", transition:"width 0.5s" }}/>
                </div>
                <div style={{ fontSize:11, color:"#777", width:24, textAlign:"right" }}>{d.count}</div>
              </div>
            ))}
          </div>
        </div>
      )}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:8, marginBottom:"1rem" }}>
        {[
          { label:"Total", value:reviews.length, color:"#378add" },
          { label:"Replied", value:reviews.filter(r=>r.driver_response).length, color:"#1d9e75" },
          { label:"Pending reply", value:reviews.filter(r=>!r.driver_response).length, color:"#e6821e" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.75rem", textAlign:"center", border:"1px solid #eee" }}>
            <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>
      <div style={{ display:"flex", gap:6, marginBottom:"1rem", overflowX:"auto" }}>
        {[{k:"all",l:"All"},{k:"pending",l:"Needs reply"},{k:"replied",l:"Replied"}].map(t=>(
          <button key={t.k} onClick={()=>setFilter(t.k)}
            style={{ padding:"6px 14px", borderRadius:6, border:"none", fontSize:12, cursor:"pointer", background:filter===t.k?"#378add":"#f0f0f0", color:filter===t.k?"#fff":"#666", whiteSpace:"nowrap" }}>
            {t.l}
          </button>
        ))}
      </div>
      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
      {!loading&&filtered.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No reviews yet</div>}
      {filtered.map(r=>(
        <div key={r.id} style={{ background:"#fff", border:"1px solid #eee", borderRadius:12, padding:"1rem", marginBottom:10 }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
            <div>
              <div style={{ fontSize:13, fontWeight:600 }}>{r.customer?.first_name} {r.customer?.last_name}</div>
              <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{new Date(r.created_at).toLocaleDateString()}</div>
            </div>
            <div style={{ display:"flex", gap:1 }}>
              {[1,2,3,4,5].map(s=><span key={s} style={{ color:s<=r.driver_rating?"#378add":"#ddd", fontSize:16 }}>Γÿà</span>)}
            </div>
          </div>
          {r.driver_review&&<div style={{ fontSize:12, color:"#555", lineHeight:1.5, marginBottom:8, fontStyle:"italic" }}>"{r.driver_review}"</div>}
          {r.driver_response?(
            <div style={{ background:"#eff6ff", border:"1px solid #378add20", borderRadius:8, padding:"0.75rem", marginBottom:8 }}>
              <div style={{ fontSize:10, color:"#378add", fontWeight:600, marginBottom:4 }}>Your reply</div>
              <div style={{ fontSize:12, color:"#333", lineHeight:1.5 }}>{r.driver_response}</div>
            </div>
          ):(
            replying===r.id?(
              <div style={{ marginTop:8 }}>
                <textarea value={replyText} onChange={e=>setReplyText(e.target.value)} placeholder="Write a professional reply..." rows={3}
                  style={{ width:"100%", background:"#f8f8f8", border:"1px solid #ddd", borderRadius:8, padding:"10px 12px", fontSize:12, outline:"none", resize:"none", boxSizing:"border-box" }}/>
                <div style={{ display:"flex", gap:8, marginTop:6 }}>
                  <button onClick={()=>submitReply(r.id)} disabled={submitting||!replyText.trim()}
                    style={{ background:"#378add", border:"none", borderRadius:7, color:"#fff", fontSize:12, fontWeight:700, padding:"8px 16px", cursor:"pointer" }}>
                    {submitting?"Posting...":"Post Reply"}
                  </button>
                  <button onClick={()=>{ setReplying(null); setReplyText("") }}
                    style={{ background:"#f0f0f0", border:"none", borderRadius:7, color:"#555", fontSize:12, padding:"8px 14px", cursor:"pointer" }}>
                    Cancel
                  </button>
                </div>
              </div>
            ):(
              <button onClick={()=>{ setReplying(r.id); setReplyText("") }}
                style={{ background:"#eff6ff", border:"1px solid #378add30", borderRadius:7, color:"#378add", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>
                ≡ƒÆ¼ Reply to review
              </button>
            )
          )}
        </div>
      ))}
    </div>
  )
}

import { useEffect, useState, useRef } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const CATEGORIES = [
  { k:"payment", l:"Payment Issue", icon:"≡ƒÆ│" },
  { k:"delivery", l:"Delivery Problem", icon:"≡ƒÜù" },
  { k:"customer", l:"Customer Complaint", icon:"≡ƒæñ" },
  { k:"vehicle", l:"Vehicle Incident", icon:"≡ƒÜ¿" },
  { k:"account", l:"Account Issue", icon:"ΓÜÖ∩╕Å" },
  { k:"go_service", l:"GO Service Issue", icon:"≡ƒöº" },
  { k:"other", l:"Other", icon:"≡ƒÆ¼" },
]
const PRIORITIES = [
  { k:"low", l:"Low" },
  { k:"medium", l:"Medium" },
  { k:"high", l:"High" },
]
const STATUS_COLOR = { open:"#e6821e", in_progress:"#378add", resolved:"#1d9e75", closed:"#888" }
const FAQ = [
  { q:"When do I receive my earnings?", a:"Driver earnings are sent automatically to your M-Pesa or Pochi la Biashara after each completed delivery or concierge job." },
  { q:"How do I update my M-Pesa number?", a:"Go to Profile, then Payment Settings to update your preferred payout method." },
  { q:"What do I do if a customer is abusive?", a:"End the trip safely and file a support ticket with details. Our team will investigate and take action." },
  { q:"My GO Service alarm is not working?", a:"Ensure notifications are enabled for the CCC app. Go to phone Settings, then Apps, then CCC, then Notifications." },
  { q:"How do I report a vehicle incident?", a:"File a High priority support ticket with incident details, photos, and location. Our team responds within 2 hours." },
  { q:"How do I go online or offline?", a:"Use the toggle switch on your Driver Overview page to set your availability status." },
]

export default function DriverSupport() {
  const { user, profile } = useAuth()
  const isMobile = useIsMobile()
  const [tickets, setTickets] = useState([])
  const [selected, setSelected] = useState(null)
  const [messages, setMessages] = useState([])
  const [newMessage, setNewMessage] = useState("")
  const [loading, setLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const [sending, setSending] = useState(false)
  const [tab, setTab] = useState("faq")
  const [expandedFaq, setExpandedFaq] = useState(null)
  const [form, setForm] = useState({ subject:"", category:"payment", priority:"medium", message:"" })
  const messagesEndRef = useRef(null)

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("driver-support-"+user.id)
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"support_messages" },
        payload => {
          if (selected && payload.new.ticket_id === selected.id) {
            setMessages(m => [...m, payload.new])
            setTimeout(() => messagesEndRef.current?.scrollIntoView({ behavior:"smooth" }), 100)
          }
          load()
        })
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user, selected])

  async function load() {
    const { data } = await supabase.from("support_tickets")
      .select("*").eq("user_id", user.id)
      .order("updated_at", { ascending:false })
    setTickets(data||[])
    setLoading(false)
  }

  async function loadMessages(ticketId) {
    const { data } = await supabase.from("support_messages")
      .select("*, sender:profiles!support_messages_sender_id_fkey(first_name,last_name,role)")
      .eq("ticket_id", ticketId).order("created_at", { ascending:true })
    setMessages(data||[])
    setTimeout(() => messagesEndRef.current?.scrollIntoView({ behavior:"smooth" }), 100)
  }

  async function submitTicket(e) {
    e.preventDefault()
    if (!form.subject.trim() || !form.message.trim()) return toast.error("Please fill all fields")
    setSubmitting(true)
    try {
      const { data: ticket, error } = await supabase.from("support_tickets").insert({
        customer_id: user.id, user_id: user.id, user_role: "driver",
        subject: form.subject, category: form.category, priority: form.priority,
      }).select().single()
      if (error) throw error
      await supabase.from("support_messages").insert({ ticket_id: ticket.id, sender_id: user.id, message: form.message, is_staff: false })
      await supabase.from("notifications").insert({ user_id: user.id, title: "Support ticket created", message: "Ticket "+ticket.ticket_number+" submitted. We respond within 24 hours.", type: "info" })
      const { data: admins } = await supabase.from("profiles").select("id").eq("role","admin")
      for (const admin of (admins||[])) {
        await supabase.from("notifications").insert({ user_id: admin.id, title: "Driver support ticket"+(form.priority==="high"?" HIGH":""), message: (profile?.first_name||"Driver")+" "+(profile?.last_name||"")+" ΓÇö "+form.subject+" ["+form.category+"]", type: form.priority==="high"?"error":"info" })
      }
      toast.success("Ticket "+ticket.ticket_number+" created!")
      setForm({ subject:"", category:"payment", priority:"medium", message:"" })
      setTab("tickets"); load()
    } catch(err) { toast.error(err.message) }
    finally { setSubmitting(false) }
  }

  async function sendMessage(e) {
    e.preventDefault()
    if (!newMessage.trim() || !selected) return
    setSending(true)
    const { error } = await supabase.from("support_messages").insert({ ticket_id: selected.id, sender_id: user.id, message: newMessage.trim(), is_staff: false })
    if (!error) { setNewMessage(""); loadMessages(selected.id) }
    else toast.error(error.message)
    setSending(false)
  }

  const inp = { width:"100%", background:"#fff", border:"1px solid #e0e0e0", borderRadius:8, padding:"10px 12px", fontSize:13, outline:"none", fontFamily:"DM Sans,sans-serif", marginBottom:10, boxSizing:"border-box" }
  const SC = STATUS_COLOR

  if (selected) return (
    <div style={{ display:"flex", flexDirection:"column", height:"calc(100vh - 140px)" }}>
      <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:12 }}>
        <button onClick={()=>{ setSelected(null); setMessages([]) }} style={{ background:"none", border:"none", fontSize:20, cursor:"pointer" }}>ΓåÉ</button>
        <div>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700 }}>{selected.subject}</div>
          <div style={{ display:"flex", gap:6, alignItems:"center", marginTop:2 }}>
            <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:(SC[selected.status]||"#888")+"20", color:SC[selected.status]||"#888" }}>{selected.status?.replace("_"," ")}</span>
            <span style={{ fontSize:10, color:"#888" }}>#{selected.ticket_number}</span>
          </div>
        </div>
      </div>
      <div style={{ flex:1, overflowY:"auto", display:"flex", flexDirection:"column", gap:8, paddingBottom:8 }}>
        {messages.map(m=>(
          <div key={m.id} style={{ display:"flex", flexDirection:"column", alignItems:m.sender_id===user.id?"flex-end":"flex-start" }}>
            <div style={{ fontSize:10, color:"#888", marginBottom:2 }}>{m.is_staff?"CCC Support":((m.sender?.first_name||"")+" "+(m.sender?.last_name||"")).trim()||"You"} ┬╖ {new Date(m.created_at).toLocaleTimeString()}</div>
            <div style={{ maxWidth:"80%", background:m.sender_id===user.id?"#1d9e75":"#f0f0f0", color:m.sender_id===user.id?"#fff":"#000", borderRadius:m.sender_id===user.id?"12px 12px 4px 12px":"12px 12px 12px 4px", padding:"8px 12px", fontSize:13 }}>
              {m.message}
            </div>
          </div>
        ))}
        <div ref={messagesEndRef}/>
      </div>
      <form onSubmit={sendMessage} style={{ display:"flex", gap:8, paddingTop:8, borderTop:"1px solid #eee" }}>
        <input value={newMessage} onChange={e=>setNewMessage(e.target.value)} placeholder="Type your message..." style={{ ...inp, marginBottom:0, flex:1 }}/>
        <button type="submit" disabled={sending||!newMessage.trim()} style={{ background:"#1d9e75", border:"none", borderRadius:8, color:"#fff", padding:"10px 18px", cursor:"pointer", fontWeight:700, fontSize:13 }}>{sending?"...":"Send"}</button>
      </form>
    </div>
  )

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:18, fontWeight:800, marginBottom:4 }}>Driver Support</div>
      <div style={{ fontSize:12, color:"#777", marginBottom:"1.25rem" }}>Get help with deliveries, payments, and account issues.</div>
      <div style={{ display:"flex", gap:6, marginBottom:"1.25rem", overflowX:"auto", paddingBottom:4 }}>
        {[{k:"faq",l:"FAQ"},{k:"tickets",l:"My Tickets ("+tickets.length+")"},{k:"new",l:"+ New Ticket"}].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)} style={{ padding:"8px 16px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#1d9e75":"#f0f0f0", color:tab===t.k?"#fff":"#555", fontWeight:tab===t.k?700:400, whiteSpace:"nowrap" }}>{t.l}</button>
        ))}
      </div>
      {tab==="faq"&&(
        <div>
          {FAQ.map((f,i)=>(
            <div key={i} onClick={()=>setExpandedFaq(expandedFaq===i?null:i)} style={{ background:"#fff", border:"1px solid #eee", borderRadius:10, padding:"0.75rem 1rem", marginBottom:8, cursor:"pointer" }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                <div style={{ fontSize:13, fontWeight:600 }}>{f.q}</div>
                <div style={{ fontSize:14, color:"#888" }}>{expandedFaq===i?"Γû▓":"Γû╝"}</div>
              </div>
              {expandedFaq===i&&<div style={{ fontSize:12, color:"#555", marginTop:8, lineHeight:1.6 }}>{f.a}</div>}
            </div>
          ))}
        </div>
      )}
      {tab==="tickets"&&(
        <div>
          {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
          {!loading&&tickets.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No tickets yet. Tap + New Ticket to get help.</div>}
          {tickets.map(t=>(
            <div key={t.id} onClick={()=>{ setSelected(t); loadMessages(t.id) }} style={{ background:"#fff", border:"1px solid #eee", borderRadius:10, padding:"0.75rem 1rem", marginBottom:8, cursor:"pointer" }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:600 }}>{t.subject}</div>
                  <div style={{ fontSize:10, color:"#888", marginTop:2 }}>#{t.ticket_number} ┬╖ {t.category} ┬╖ {new Date(t.created_at).toLocaleDateString()}</div>
                </div>
                <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:(SC[t.status]||"#888")+"20", color:SC[t.status]||"#888" }}>{t.status?.replace("_"," ")}</span>
              </div>
            </div>
          ))}
        </div>
      )}
      {tab==="new"&&(
        <form onSubmit={submitTicket}>
          <div style={{ fontSize:11, color:"#666", marginBottom:4 }}>Category</div>
          <select style={inp} value={form.category} onChange={e=>setForm(f=>({...f,category:e.target.value}))}>
            {CATEGORIES.map(c=><option key={c.k} value={c.k}>{c.icon} {c.l}</option>)}
          </select>
          <div style={{ fontSize:11, color:"#666", marginBottom:4 }}>Priority</div>
          <select style={inp} value={form.priority} onChange={e=>setForm(f=>({...f,priority:e.target.value}))}>
            {PRIORITIES.map(p=><option key={p.k} value={p.k}>{p.l}</option>)}
          </select>
          <div style={{ fontSize:11, color:"#666", marginBottom:4 }}>Subject</div>
          <input style={inp} placeholder="Brief description of your issue" value={form.subject} onChange={e=>setForm(f=>({...f,subject:e.target.value}))}/>
          <div style={{ fontSize:11, color:"#666", marginBottom:4 }}>Message</div>
          <textarea style={{ ...inp, minHeight:100, resize:"vertical" }} placeholder="Describe your issue in detail..." value={form.message} onChange={e=>setForm(f=>({...f,message:e.target.value}))}/>
          <button type="submit" disabled={submitting} style={{ width:"100%", background:"#1d9e75", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700, padding:"12px", cursor:"pointer" }}>{submitting?"Submitting...":"Submit Ticket"}</button>
        </form>
      )}
    </div>
  )
}

import useIsMobile from "../../lib/useIsMobile"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import toast from "react-hot-toast"
import { validateFile } from "../../lib/uploadValidation"
import { BadgeIcon, ShieldIcon, DocumentIcon, NoteIcon, WarningIcon } from "../../lib/cccIcons"

export default function DriverVehicle() {
  const isMobile = useIsMobile()
  const { user, profile, updateProfile } = useAuth()
  const [docs, setDocs] = useState([])
  const [form, setForm] = useState({ vehicle_model:"", vehicle_color:"", vehicle_plate:"", vehicle_year:"" })
  const [saving, setSaving] = useState(false)
  const [docForm, setDocForm] = useState({ type:"license", expiry_date:"", file:null })
  const [docUploading, setDocUploading] = useState(false)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    if (profile) setForm({ vehicle_model:profile?.vehicle_model||"", vehicle_color:profile?.vehicle_color||"", vehicle_plate:profile?.vehicle_plate||"", vehicle_year:profile?.vehicle_year||"" })
    if (user) loadDocs()
    if (user) {
      const sub = supabase.channel("driver-vehicle-live")
        .on("postgres_changes", { event:"*", schema:"public", table:"driver_documents", filter:`driver_id=eq.${user.id}` }, () => loadDocs())
        .subscribe()
      return () => supabase.removeChannel(sub)
    }
  }, [profile, user])

  async function loadDocs() {
    const { data } = await supabase.from("driver_documents").select("*").eq("driver_id", user.id).order("created_at",{ascending:false})
    setDocs(data||[])
    setLoading(false)
  }

  async function saveVehicle(e) {
    e.preventDefault()
    setSaving(true)
    try {
      await updateProfile({ vehicle_model:form.vehicle_model, vehicle_color:form.vehicle_color, vehicle_plate:form.vehicle_plate, vehicle_year:parseInt(form.vehicle_year)||null })
      toast.success("Vehicle info updated")
    } catch(err) { toast.error(err.message) }
    finally { setSaving(false) }
  }

  async function addDocument(e) {
    e.preventDefault()
    if (!docForm.file) return toast.error("Please select a file to upload")
    setDocUploading(true)
    try {
      const ext = docForm.file.name.split(".").pop()
      const path = `${user.id}/${docForm.type}_${Date.now()}.${ext}`
      const { error: upErr } = await supabase.storage.from("driver-documents").upload(path, docForm.file, { upsert:true })
      if (upErr) throw upErr
      const { data: urlData } = supabase.storage.from("driver-documents").getPublicUrl(path)
      const { error } = await supabase.from("driver_documents").insert({
        driver_id: user.id,
        type: docForm.type,
        expiry_date: docForm.expiry_date||null,
        document_url: urlData.publicUrl
      })
      if (error) throw error
      toast.success("Document uploaded!")
      setDocForm({ type:"license", expiry_date:"", file:null })
      loadDocs()
    } catch(err) { toast.error(err.message) }
    finally { setDocUploading(false) }
  }
  async function deleteDoc(id) {
    if (!confirm("Remove this document?")) return
    await supabase.from("driver_documents").delete().eq("id",id).eq("driver_id",user.id)
    toast.success("Document removed")
    loadDocs()
  }

  const inp = { width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"10px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif", marginBottom:10 }
  const lbl = { fontSize:11, color:"#666", textTransform:"uppercase", letterSpacing:"0.05em", display:"block", marginBottom:4 }
  const docTypeColor = { license:"#e6821e", insurance:"#1d9e75", registration:"#378add", other:"#888" }

  const isExpiringSoon = (date) => {
    if (!date) return false
    const diff = new Date(date) - new Date()
    return diff > 0 && diff < 30*24*60*60*1000
  }

  const isExpired = (date) => {
    if (!date) return false
    return new Date(date) < new Date()
  }

  return (
    <div>
      <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem", marginBottom:"1.5rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:"1rem", color:"#000000" }}>Vehicle information</div>
        <form onSubmit={saveVehicle}>
          <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"1fr 1fr", gap:10 }}>
            <div><label style={lbl}>Model</label><input style={inp} placeholder="e.g. Toyota Fielder" value={form.vehicle_model} onChange={e=>setForm(f=>({...f,vehicle_model:e.target.value}))}/></div>
            <div><label style={lbl}>Color</label><input style={inp} placeholder="e.g. White" value={form.vehicle_color} onChange={e=>setForm(f=>({...f,vehicle_color:e.target.value}))}/></div>
            <div><label style={lbl}>License plate</label><input style={inp} placeholder="e.g. KDA 123A" value={form.vehicle_plate} onChange={e=>setForm(f=>({...f,vehicle_plate:e.target.value}))}/></div>
            <div><label style={lbl}>Year</label><input style={inp} type="number" min="1990" max="2026" placeholder="2020" value={form.vehicle_year} onChange={e=>setForm(f=>({...f,vehicle_year:e.target.value}))}/></div>
          </div>
          <button type="submit" disabled={saving}
            style={{ background:saving?"#555555":"#e6821e", border:"none", borderRadius:8, color:saving?"#666":"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"10px 20px", cursor:saving?"not-allowed":"pointer" }}>
            {saving?"Saving...":"Save vehicle info"}
          </button>
        </form>
      </div>

      <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:"1rem", color:"#000000" }}>Documents</div>
        {loading&&<div style={{ color:"#777777", fontSize:13 }}>Loading...</div>}
        {docs.map(d=>(
          <div key={d.id} style={{ display:"flex", alignItems:"center", gap:12, padding:"0.75rem", background:"#ffffff", borderRadius:8, marginBottom:8, border:`1px solid ${isExpired(d.expiry_date)?"#e24b4a40":isExpiringSoon(d.expiry_date)?"#e6821e40":"#f5f5f5"}` }}>
            <div style={{ width:36, height:36, background:`${docTypeColor[d.type]}20`, borderRadius:8, display:"flex", alignItems:"center", justifyContent:"center", fontSize:18, flexShrink:0 }}>
              {d.type==="license"?<BadgeIcon size={18} color={docTypeColor[d.type]}/>:d.type==="insurance"?<ShieldIcon size={18} color={docTypeColor[d.type]}/>:d.type==="registration"?<DocumentIcon size={18} color={docTypeColor[d.type]}/>:<NoteIcon size={18} color={docTypeColor[d.type]}/>}
            </div>
            <div style={{ flex:1 }}>
              <div style={{ fontSize:13, fontWeight:500, color:"#000000", textTransform:"capitalize" }}>{d.type}</div>
              {d.expiry_date&&(
                <div style={{ fontSize:11, color:isExpired(d.expiry_date)?"#e24b4a":isExpiringSoon(d.expiry_date)?"#e6821e":"#555", marginTop:2 }}>
                  {isExpired(d.expiry_date)?"Expired":"Expires"}: {new Date(d.expiry_date).toLocaleDateString()}
                  {isExpiringSoon(d.expiry_date)&&<WarningIcon size={11} color="#e6821e"/>}
                </div>
              )}
              {d.is_verified&&<div style={{ fontSize:10, color:"#1d9e75", marginTop:2 }}>Γ£ô Verified</div>}
            </div>
            <div style={{ display:"flex", gap:6 }}>
              {d.document_url&&<a href={d.document_url} target="_blank" rel="noreferrer" style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:6, color:"#378add", fontSize:11, padding:"4px 8px", textDecoration:"none" }}>View</a>}
              <button onClick={()=>deleteDoc(d.id)} style={{ background:"none", border:"1px solid #e24b4a40", borderRadius:6, color:"#e24b4a", fontSize:11, padding:"4px 8px", cursor:"pointer" }}>Remove</button>
            </div>
          </div>
        ))}

        <div style={{ marginTop:"1rem", paddingTop:"1rem", borderTop:"1px solid #eeeeee" }}>
          <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, marginBottom:"0.75rem", color:"#000000" }}>Add document</div>
          <form onSubmit={addDocument}>
            <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"1fr 1fr", gap:10 }}>
              <div>
                <label style={lbl}>Document type</label>
                <select style={inp} value={docForm.type} onChange={e=>setDocForm(f=>({...f,type:e.target.value}))}>
                  <option value="license">Driver license</option>
                  <option value="insurance">Insurance</option>
                  <option value="registration">Vehicle registration</option>
                  <option value="other">Other</option>
                </select>
              </div>
              <div>
                <label style={lbl}>Expiry date</label>
                <input style={inp} type="date" value={docForm.expiry_date} onChange={e=>setDocForm(f=>({...f,expiry_date:e.target.value}))}/>
              </div>
            </div>
            
            <div style={{ marginBottom:10 }}>
              <label style={{ fontSize:11, color:"#666", textTransform:"uppercase", letterSpacing:"0.05em", display:"block", marginBottom:4 }}>Upload file (PDF, JPG, PNG) *</label>
              <input type="file" accept="image/*,.pdf" onChange={e=>setDocForm(f=>({...f,file:e.target.files[0]}))}
                style={{ width:"100%", fontSize:12, color:"#555", fontFamily:"DM Sans,sans-serif" }}/>
              {docForm.file&&<div style={{ fontSize:11, color:"#1d9e75", marginTop:4 }}>Γ£ô {docForm.file.name}</div>}
            </div>
            <button type="submit" disabled={docUploading}
              style={{ background:docUploading?"#ccc":"#e6821e", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"10px 20px", cursor:docUploading?"not-allowed":"pointer" }}>
              {docUploading?"Uploading...":"Upload document"}
            </button>
          </form>
        </div>
      </div>
    </div>
  )
}

