export default function AppHomePage() {
  const [activeRole, setActiveRole] = useState(0)
  const [animKey, setAnimKey] = useState(0)
  const [paused, setPaused] = useState(false)
  const [touchStart, setTouchStart] = useState(null)
  const [touchEnd, setTouchEnd] = useState(null)
  const [holdTimer, setHoldTimer] = useState(null)
  const nav = (path) => window.location.href = path

  // Preload all role images on mount
  useEffect(() => {
    ROLES.forEach(r => {
      const img = new Image()
      img.src = r.img
    })
  }, [])

  const goToRole = (i) => {
    setActiveRole(i)
    setAnimKey(k => k + 1)
    setPaused(false)
  }

  const goNext = () => {
    setActiveRole(prev => {
      const next = (prev + 1) % ROLES.length
      setAnimKey(k => k + 1)
      return next
    })
    setPaused(false)
  }

  const goPrev = () => {
    setActiveRole(prev => {
      const next = (prev - 1 + ROLES.length) % ROLES.length
      setAnimKey(k => k + 1)
      return next
    })
    setPaused(false)
  }

  // Touch handlers - swipe + hold to pause
  const handleTouchStart = (e) => {
    setTouchStart(e.targetTouches[0].clientX)
    setTouchEnd(null)
    // Hold to pause after 200ms
    const t = setTimeout(() => setPaused(true), 200)
    setHoldTimer(t)
  }

  const handleTouchMove = (e) => {
    setTouchEnd(e.targetTouches[0].clientX)
    // If moving, cancel hold
    if (holdTimer) { clearTimeout(holdTimer); setHoldTimer(null) }
  }

  const handleTouchEnd = () => {
    if (holdTimer) { clearTimeout(holdTimer); setHoldTimer(null) }
    setPaused(false)
    if (!touchStart || !touchEnd) return
    const distance = touchStart - touchEnd
    if (distance > 50) goNext()
    else if (distance < -50) goPrev()
  }

  useEffect(() => {
    if (paused) return
    const interval = setInterval(goNext, 5000)
    return () => clearInterval(interval)
  }, [paused, activeRole])

  const role = ROLES[activeRole]

  return (
    <div style={{ fontFamily:"DM Sans,sans-serif", background:"#f5f5f5", minHeight:"100vh", overflowX:"hidden" }}>
