                {role.actions.map(a=>(
                  <div key={a} style={{ display:"flex", alignItems:"center", gap:8, background:role.bg, border:"1.5px solid "+role.border, borderRadius:10, padding:"9px 12px", fontSize:12, fontWeight:600, color:role.color }}>
