                  <div style={{ display:"flex", justifyContent:"center" }}>{l.listing_type==="vehicle"?<VehicleIcon size={40} color="#e6821e"/>:l.listing_type==="part"?<PartsIcon size={40} color="#8b5cf6"/>:<MarketplaceIcon size={40} color="#1d9e75"/>}</div>
