  if(_listingType === "part" || _listingType === "accessory") return (
    <div>
      <button onClick={onBack} style={{ background:"none", border:"none", color:"#e6821e", cursor:"pointer", fontSize:13, marginBottom:"1rem", padding:0, fontFamily:"DM Sans,sans-serif" }}>ΓåÉ Back to listings</button>
      {(photos?.length>0||listing.primary_photo)&&(<div style={{ marginBottom:"1rem" }}><img src={photos?.[activePhoto||0]?.photo_url||listing.primary_photo} alt={listing.title} style={{ width:"100%", height:isMobile?220:320, objectFit:"cover", borderRadius:12 }}/></div>)}
      {listing.video_url&&(<div style={{ marginBottom:"1rem" }}><div style={{ fontFamily:"Syne", fontSize:12, fontWeight:700, marginBottom:6 }}>≡ƒÄÑ Video</div><video src={listing.video_url} controls style={{ width:"100%", borderRadius:12, maxHeight:260, background:"#000" }}/></div>)}
      <div style={{ background:"#fff", border:"1px solid #eee", borderRadius:12, padding:"1rem", marginBottom:"1rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:isMobile?18:22, fontWeight:800, marginBottom:4 }}>{listing.title}</div>
        <div style={{ fontFamily:"Syne", fontSize:20, fontWeight:800, color:"#e6821e", marginBottom:4 }}>KES {Number(listing.price).toLocaleString()}</div>
        {listing.negotiable&&<div style={{ fontSize:11, color:"#1d9e75", marginBottom:12 }}>Γ£ô Price negotiable</div>}
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8, marginBottom:12 }}>
          {[{label:"Category",value:listing.part_category||"ΓÇö"},{label:"Condition",value:listing.condition||"ΓÇö"},{label:"Qty",value:listing.quantity||"ΓÇö"},{label:"Compatible with",value:listing.compatible_makes||listing.make||"ΓÇö"}].map(s=>(<div key={s.label} style={{ background:"#f8f8f8", borderRadius:8, padding:"0.5rem 0.75rem" }}><div style={{ fontSize:10, color:"#888", marginBottom:2 }}>{s.label}</div><div style={{ fontSize:12, fontWeight:600 }}>{s.value}</div></div>))}
        </div>
        {listing.description&&<div><div style={{ fontSize:12, fontWeight:700, marginBottom:4 }}>Description</div><div style={{ fontSize:12, color:"#555", lineHeight:1.6 }}>{listing.description}</div></div>}
      </div>
      <div style={{ background:"#fff", border:"1px solid #eee", borderRadius:12, padding:"1rem", marginBottom:"1rem" }}>
