        </div>
        <div style={{ flex:1, minHeight:0, display:"flex", flexDirection:"column" }}>
          <ChatWindow
            listingId={listing.id}
            otherUserId={listing.seller_id}
            otherUserName={sellerInfo?.business_name||sellerInfo?.first_name||"Seller"}
            onClose={()=>setShowChat(false)}
          />

            {/* Comments Section */}
            <div style={{ marginTop:16, background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1rem" }}>
              <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#000", marginBottom:12, display:"flex", alignItems:"center", gap:6 }}><ChatIcon size={16} color="#000"/> Comments ({listing.comments_count||0})</div>
              <div style={{ display:"flex", gap:8, marginBottom:16 }}>
                <textarea id="comment-input" value={newComment} onChange={e=>setNewComment(e.target.value)}
                  placeholder="Write a comment... (contact sharing not allowed)" rows={2}
                  style={{ flex:1, background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:8, padding:"10px 12px", fontSize:12, color:"#000", outline:"none", resize:"none", fontFamily:"DM Sans,sans-serif" }}/>
                <button onClick={()=>submitComment(listing.id)} disabled={submittingComment||!newComment.trim()}
                  style={{ background:submittingComment||!newComment.trim()?"#eeeeee":"#e6821e", border:"none", borderRadius:8, color:submittingComment||!newComment.trim()?"#999":"#fff", fontSize:12, fontWeight:700, padding:"0 14px", cursor:submittingComment||!newComment.trim()?"not-allowed":"pointer", flexShrink:0 }}>
                  {submittingComment?"...":"Post"}
                </button>
              </div>
              {loadingComments&&<div style={{ color:"#888", fontSize:12, textAlign:"center" }}>Loading...</div>}
              {!loadingComments&&comments.length===0&&<div style={{ color:"#888", fontSize:12, textAlign:"center", padding:"1rem" }}>No comments yet. Be the first!</div>}
              {/* Video context label */}
              {listing.video_url&&(
                <div style={{ fontSize:11, color:"#888", marginBottom:12, display:"flex", alignItems:"center", gap:6 }}>
                  <span>≡ƒÄÑ</span> Comments below refer to this listing and its video
                </div>
              )}

              {comments.map(cm=>(
                <div key={cm.id} style={{ marginBottom:14 }}>
                  {/* Main comment */}
                  <div style={{ display:"flex", gap:10, alignItems:"flex-start" }}>
                    <div style={{ width:32, height:32, borderRadius:"50%", background:"#fff8f0", border:"1px solid #e6821e30", display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontSize:12, fontWeight:800, color:"#e6821e", flexShrink:0 }}>
                      {(cm.profiles?.first_name||"?")[0].toUpperCase()}
                    </div>
                    <div style={{ flex:1 }}>
                      <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:2 }}>
                        <span style={{ fontSize:12, fontWeight:700, color:"#000" }}>{cm.profiles?.first_name} {cm.profiles?.last_name}</span>
                        <span style={{ fontSize:10, color:"#888" }}>{new Date(cm.created_at).toLocaleDateString()}</span>
                        {user?.id===cm.user_id&&(
                          <button onClick={()=>deleteComment(cm.id, listing.id)} style={{ marginLeft:"auto", background:"none", border:"none", color:"#e24b4a", fontSize:10, cursor:"pointer", padding:0 }}>Delete</button>
                        )}
                      </div>
                      <div style={{ fontSize:12, color:"#333", lineHeight:1.5, background:"#f8f8f8", borderRadius:"4px 12px 12px 12px", padding:"8px 12px" }}>{cm.comment}</div>
                      {/* Reply button - visible to seller and all users */}
                      <button onClick={()=>{ setReplyingTo(replyingTo===cm.id?null:cm.id); setReplyText("") }}
                        style={{ background:"none", border:"none", color:"#378add", fontSize:10, cursor:"pointer", padding:"4px 0", fontWeight:600 }}>
                        {replyingTo===cm.id?"Cancel":"Γå⌐ Reply"}
                        {user?.id===listing?.seller_id&&" (as seller)"}
                      </button>
                      {/* Reply input */}
                      {replyingTo===cm.id&&(
                        <div style={{ display:"flex", gap:6, marginTop:6 }}>
                          <textarea value={replyText} onChange={e=>setReplyText(e.target.value)}
                            placeholder={user?.id===listing?.seller_id?"Reply as seller...":"Write a reply..."}
                            rows={2} style={{ flex:1, background:"#f0f7ff", border:"1px solid #378add30", borderRadius:8, padding:"8px 10px", fontSize:11, color:"#000", outline:"none", resize:"none" }}/>
                          <button onClick={()=>submitReply(listing.id, cm.id, user?.id===listing?.seller_id)} disabled={submittingComment||!replyText.trim()}
                            style={{ background:submittingComment||!replyText.trim()?"#eeeeee":"#378add", border:"none", borderRadius:8, color:"#fff", fontSize:11, fontWeight:700, padding:"0 12px", cursor:"pointer", flexShrink:0 }}>
                            {submittingComment?"...":"Reply"}
                          </button>
                        </div>
                      )}
                    </div>
                  </div>
                  {/* Replies */}
                  {(cm.replies||[]).filter(r=>!r.is_deleted).map(reply=>(
                    <div key={reply.id} style={{ display:"flex", gap:8, alignItems:"flex-start", marginTop:8, marginLeft:42 }}>
                      <div style={{ width:26, height:26, borderRadius:"50%", background:reply.is_seller_reply?"#eff6ff":"#f8f8f8", border:`1px solid ${reply.is_seller_reply?"#378add30":"#eeeeee"}`, display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontSize:10, fontWeight:800, color:reply.is_seller_reply?"#378add":"#888", flexShrink:0 }}>
                        {(reply.profiles?.first_name||"?")[0].toUpperCase()}
                      </div>
                      <div style={{ flex:1 }}>
                        <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:2 }}>
                          <span style={{ fontSize:11, fontWeight:700, color:"#000" }}>{reply.profiles?.first_name} {reply.profiles?.last_name}</span>
                          {reply.is_seller_reply&&<span style={{ fontSize:9, background:"#eff6ff", color:"#378add", padding:"1px 6px", borderRadius:8, fontWeight:700 }}>Seller</span>}
                          <span style={{ fontSize:9, color:"#888" }}>{new Date(reply.created_at).toLocaleDateString()}</span>
                          {user?.id===reply.user_id&&(
                            <button onClick={()=>deleteComment(reply.id, listing.id)} style={{ marginLeft:"auto", background:"none", border:"none", color:"#e24b4a", fontSize:9, cursor:"pointer", padding:0 }}>Delete</button>
                          )}
                        </div>
                        <div style={{ fontSize:11, color:"#333", lineHeight:1.5, background:reply.is_seller_reply?"#eff6ff":"#f8f8f8", borderRadius:"4px 12px 12px 12px", padding:"6px 10px" }}>{reply.comment}</div>
                      </div>
                    </div>
                  ))}
                </div>
              ))}
            </div>
        </div>
      </div>
    </div>
  )

  async function submitOffer(e) {
    e.preventDefault()
    if (!offerPrice) return
    setSubmitting(true)
    try {
      const { error } = await supabase.from("marketplace_offers").insert({
        listing_id:listing.id, buyer_id:user.id, seller_id:listing.seller_id,
        offered_price:parseFloat(offerPrice), message:offerMessage, status:"pending",
      })
      if (error) throw error
      await supabase.from("notifications").insert({
        user_id:listing.seller_id, title:"New offer on your listing ≡ƒÆ░",
        message:`Someone offered KES ${Number(offerPrice).toLocaleString()} for: ${listing.title}`,
        type:"info",
      })
      toast.success("Offer submitted!")
      setShowOffer(false)
      setOfferPrice("")
      setOfferMessage("")
      onOffer()
    } catch(err) { toast.error(err.message) }
    finally { setSubmitting(false) }
  }

  return (
    <div>
      <button onClick={onBack} style={{ background:"none", border:"none", color:"#e6821e", cursor:"pointer", fontSize:13, marginBottom:"1rem", fontFamily:"'DM Sans',sans-serif", padding:0 }}>
        ΓåÉ Back to marketplace
      </button>

      <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"1fr 1fr", gap:"1.5rem" }}>
        <div>
          <div style={{ background:"#f5f5f5", borderRadius:12, height:isMobile?220:300, display:"flex", alignItems:"center", justifyContent:"center", marginBottom:8, overflow:"hidden" }}>
            {photos.length>0
              ? <img src={photos[activePhoto]?.photo_url} alt={listing.title} style={{ width:"100%", height:"100%", objectFit:"cover" }}/>
              : <div style={{ display:"flex", justifyContent:"center" }}>{listing.listing_type==="vehicle"?<VehicleIcon size={64} color="#e6821e"/>:listing.listing_type==="part"?"≡ƒöº":"Γ£¿"}</div>
            }
          </div>
          {photos.length>1&&(
            <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
              {photos.map((p,i)=>(
                <div key={p.id} onClick={()=>setActivePhoto(i)}
                  style={{ width:48, height:48, borderRadius:6, overflow:"hidden", border:`2px solid ${i===activePhoto?"#e6821e":"transparent"}`, cursor:"pointer" }}>
                  <img src={p.photo_url} alt="" style={{ width:"100%", height:"100%", objectFit:"cover" }}/>
                </div>
              ))}
            </div>
          )}
          {listing.video_url&&listing.video_status==="approved"&&(
            <div style={{ marginTop:10 }}>
              <div style={{ fontSize:12, fontWeight:700, color:"#555", marginBottom:6 }}>≡ƒÄÑ Video</div>
              <video src={listing.video_url} controls style={{ width:"100%", borderRadius:8, maxHeight:250 }}/>
            </div>
          )}
        </div>

        <div>
          <div style={{ marginBottom:8 }}>
            {listing.is_featured&&<span style={{ fontSize:10, background:listing.featured_tier==="premium"?"#8b5cf6":"#e6821e", color:"#fff", padding:"2px 8px", borderRadius:10, marginRight:4 }}>{listing.featured_tier==="premium"?"≡ƒææ Premium":"Γ¡É Featured"}</span>}
            {listing.is_inspected&&<span style={{ fontSize:10, background:"#1d9e75", color:"#fff", padding:"2px 8px", borderRadius:10 }}>Γ£ô CCC Inspected</span>}
          </div>
          <div style={{ fontFamily:"Syne", fontSize:isMobile?18:22, fontWeight:800, color:"#000000", marginBottom:8 }}>{listing.title}</div>
          <div style={{ fontFamily:"Syne", fontSize:isMobile?22:28, fontWeight:800, color:"#e6821e", marginBottom:4 }}>KES {Number(listing.price).toLocaleString()}</div>
          {listing.negotiable&&<div style={{ fontSize:12, color:"#1d9e75", marginBottom:12 }}>Γ£ô Price negotiable</div>}

          {listing.listing_type==="vehicle"&&(
            <div style={{ background:"#ffffff", borderRadius:10, padding:"0.9rem", marginBottom:12 }}>
              <div style={{ fontSize:11, color:"#777777", marginBottom:8, textTransform:"uppercase" }}>Vehicle details</div>
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
                {[{l:"Make",v:listing.make},{l:"Model",v:listing.model},{l:"Year",v:listing.year},{l:"Mileage",v:listing.mileage?`${Number(listing.mileage).toLocaleString()}km`:null},{l:"Color",v:listing.color},{l:"Transmission",v:listing.transmission},{l:"Fuel",v:listing.fuel_type},{l:"Engine",v:listing.engine_size},{l:"Body",v:listing.body_type},{l:"Drive",v:listing.drive_type},{l:"Condition",v:listing.condition}].filter(f=>f.v).map(f=>(
                  <div key={f.l}>
                    <div style={{ fontSize:10, color:"#888888" }}>{f.l}</div>
                    <div style={{ fontSize:12, color:"#000000", fontWeight:500, textTransform:"capitalize" }}>{f.v}</div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {listing.listing_type==="part"&&(
            <div style={{ background:"#ffffff", borderRadius:10, padding:"0.9rem", marginBottom:12 }}>
              <div style={{ fontSize:11, color:"#777777", marginBottom:8, textTransform:"uppercase" }}>Part details</div>
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
                {[{l:"Category",v:listing.part_category},{l:"Condition",v:listing.condition},{l:"Part No.",v:listing.part_number},{l:"Qty",v:listing.quantity}].filter(f=>f.v).map(f=>(
                  <div key={f.l}><div style={{ fontSize:10, color:"#888888" }}>{f.l}</div><div style={{ fontSize:12, color:"#000000" }}>{f.v}</div></div>
                ))}
              </div>
              {listing.compatible_makes?.length>0&&(
                <div style={{ marginTop:8 }}>
                  <div style={{ fontSize:10, color:"#888888", marginBottom:4 }}>Compatible with</div>
                  <div style={{ display:"flex", flexWrap:"wrap", gap:4 }}>
                    {listing.compatible_makes.map(m=><span key={m} style={{ fontSize:10, padding:"2px 7px", borderRadius:6, background:"#f5f5f5", color:"#555555" }}>{m}</span>)}
                  </div>
                </div>
              )}
            </div>
          )}

          {listing.description&&(
            <div style={{ background:"#ffffff", borderRadius:10, padding:"0.9rem", marginBottom:12 }}>
              <div style={{ fontSize:11, color:"#777777", marginBottom:6, textTransform:"uppercase" }}>Description</div>
              <div style={{ fontSize:13, color:"#555555", lineHeight:1.7 }}>{listing.description}</div>
            </div>
          )}

          <div style={{ background:"#ffffff", borderRadius:10, padding:"0.9rem", marginBottom:12 }}>
            <div style={{ fontSize:11, color:"#777777", marginBottom:8, textTransform:"uppercase" }}>Seller</div>
            <div style={{ display:"flex", alignItems:"center", gap:10 }}>
              <div style={{ width:40, height:40, borderRadius:"50%", background:badge.bg, border:`1px solid ${badge.color}40`, display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontSize:14, fontWeight:800, color:badge.color, flexShrink:0 }}>
                {sellerInfo?.first_name?.[0]}{sellerInfo?.last_name?.[0]}
              </div>
              <div>
                <div style={{ fontSize:13, color:"#000000", fontWeight:600 }}>{sellerInfo?.business_name||`${sellerInfo?.first_name} ${sellerInfo?.last_name||""}`}</div>
                <span style={{ fontSize:10, padding:"2px 7px", borderRadius:6, background:badge.bg, color:badge.color }}>{badge.label}</span>
              </div>
            </div>
            {listing.city&&<div style={{ fontSize:11, color:"#777777", marginTop:8, display:"flex", alignItems:"center", gap:4 }}><LocationIcon size={11} color="#777777"/> {listing.city}</div>}
          </div>

          {listing.seller_id!==user?.id&&(
            <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
              {listing._source==="inventory" ? (
                <button onClick={()=>addToCart(listing)}
                  style={{ width:"100%", background:"#e6821e", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700, padding:"13px", cursor:"pointer" }}>
                  ≡ƒ¢Æ Add to Cart
                </button>
              ) : (
                <button onClick={()=>setShowChat(true)}
                  style={{ width:"100%", background:"#000", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700, padding:"13px", cursor:"pointer" }}>
                  <ChatIcon size={14} color="currentColor"/> Message seller
                </button>
              )}

              {/* Social actions */}
              <div style={{ display:"flex", gap:8, marginTop:4 }}>
                <button onClick={()=>toggleLike(listing.id)}
                  style={{ flex:1, display:"flex", alignItems:"center", justifyContent:"center", gap:6, background:userLikes?.has(listing.id)?"#fff0f3":"#f8f8f8", border:`1px solid ${userLikes?.has(listing.id)?"#e24b4a40":"#eeeeee"}`, borderRadius:10, padding:"10px", cursor:"pointer", transition:"all 0.15s" }}>
                  <HeartIcon size={18} color="#e24b4a" active={userLikes?.has(listing.id)} />
                  <span style={{ fontSize:12, fontWeight:700, color:userLikes?.has(listing.id)?"#e24b4a":"#666" }}>{listing.likes_count||0}</span>
                </button>
                <button onClick={()=>{ setShowChat(true); setTimeout(()=>document.getElementById("comment-input")?.focus(), 100) }}
                  style={{ flex:1, display:"flex", alignItems:"center", justifyContent:"center", gap:6, background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:10, padding:"10px", cursor:"pointer" }}>
                  <ChatIcon size={18} color="#8b5cf6" />
                  <span style={{ fontSize:12, fontWeight:700, color:"#666" }}>{listing.comments_count||0}</span>
                </button>
                <button onClick={()=>shareViaWhatsApp(listing)}
                  style={{ flex:1, display:"flex", alignItems:"center", justifyContent:"center", gap:6, background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:10, padding:"10px", cursor:"pointer" }}>
                  <ShareIcon size={18} color="#64748B" />
                  <span style={{ fontSize:12, fontWeight:700, color:"#1d9e75" }}>{listing.shares_count||0}</span>
                </button>
              </div>

              {/* Status banner */}
              {!listing.is_inspected&&listing.listing_type==="vehicle"&&(
                <div style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:10, padding:"0.9rem" }}>
                  <div style={{ fontSize:12, color:"#e6821e", fontWeight:600, marginBottom:4 }}>ΓÅ│ Pending CCC Inspection</div>
                  <div style={{ fontSize:11, color:"#555555", lineHeight:1.6 }}>
                    This listing is awaiting CCC inspection. This ensures all listings on our platform are verified.
                  </div>
                </div>
              )}

              {listing.is_inspected&&(
                <div style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:10, padding:"0.75rem", display:"flex", alignItems:"center", gap:8 }}>
                  <span style={{ fontSize:14 }}>Γ£ô</span>
                  <div>
                    <div style={{ fontSize:12, color:"#1d9e75", fontWeight:600 }}>CCC Verified Vehicle</div>
                    <div style={{ fontSize:10, color:"#777777" }}>Inspected and approved by Car Care Connect</div>
                  </div>
                </div>
              )}

              {/* Offer button - only if inspected */}
              {listing.is_inspected&&(
                existingOffer?(
                  <div style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:10, padding:"0.9rem" }}>
                    <div style={{ fontSize:12, color:"#1d9e75", fontWeight:600 }}>Γ£ô Offer submitted</div>
                    <div style={{ fontSize:11, color:"#777777", marginTop:2 }}>KES {Number(existingOffer.offered_price).toLocaleString()} ┬╖ {existingOffer.status}</div>
                    {existingOffer.counter_price&&<div style={{ fontSize:11, color:"#e6821e", marginTop:4 }}>Counter: KES {Number(existingOffer.counter_price).toLocaleString()}</div>}
                  </div>
                ):(
                  <button onClick={()=>setShowOffer(true)}
                    style={{ background:"#e6821e", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700, padding:"13px", cursor:"pointer" }}>
                    <span style={{display:"flex",alignItems:"center",gap:6}}><MarketplaceIcon size={14} color="currentColor"/> Make an offer</span>
                  </button>
                )
              )}

              {/* Message button - only if inspected */}
              {listing.is_inspected&&(
                <button onClick={()=>setShowChat(s=>!s)}
                style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:10, color:"#378add", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:600, padding:"12px", cursor:"pointer" }}>
                  <><ChatIcon size={14} color="currentColor"/> {showChat?"Close chat":"Open chat"}</>
                </button>
              )}
            {showChat&&(
              <div style={{ marginTop:8, height:400 }}>
                <ChatWindow
                  listingId={listing._source==="inventory" ? undefined : listing.id}
                  inventoryId={listing._source==="inventory" ? listing.id : undefined}
                  otherUserId={listing.seller_id||listing.provider_id}
                  onClose={()=>setShowChat(false)}
                />
              </div>
            )}
            </div>
          )}

          {listing.seller_id===user?.id&&(
            <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:10, padding:"0.9rem", textAlign:"center" }}>
              <div style={{ fontSize:12, color:"#777777", display:"flex", alignItems:"center", gap:4 }}>This is your listing ┬╖ <EyeIcon size={12} color="#777777"/> {listing.views||0} views</div>
            </div>
          )}
        </div>
      </div>

      {showOffer&&(
        <div style={{ position:"fixed", inset:0, zIndex:200, display:"flex", alignItems:isMobile?"flex-end":"center", justifyContent:"center" }}
          onClick={e=>{ if(e.target===e.currentTarget) setShowOffer(false) }}>
          <div style={{ position:"absolute", inset:0, background:"rgba(0,0,0,0.75)" }} onClick={()=>setShowOffer(false)}/>
          <div style={{ position:"relative", zIndex:1, background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:isMobile?"20px 20px 0 0":"16px", padding:"1.5rem", width:isMobile?"100%":"420px" }}>
            {isMobile&&<div style={{ width:40, height:4, background:"#e5e5e5", borderRadius:2, margin:"0 auto 1.5rem" }}/>}
            <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, color:"#000000", marginBottom:4 }}>Make an offer</div>
            <div style={{ fontSize:12, color:"#777777", marginBottom:"1.25rem" }}>Asking: KES {Number(listing.price).toLocaleString()}</div>
            <form onSubmit={submitOffer}>
              <label style={{ fontSize:11, color:"#666", display:"block", marginBottom:4 }}>Your offer (KES) *</label>
              <input type="number" value={offerPrice} onChange={e=>setOfferPrice(e.target.value)} required
                style={{ width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"11px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif", marginBottom:12 }}/>
              <label style={{ fontSize:11, color:"#666", display:"block", marginBottom:4 }}>Message (optional)</label>
              <textarea value={offerMessage} onChange={e=>setOfferMessage(e.target.value)}
                placeholder="Introduce yourself..."
                style={{ width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"11px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif", resize:"vertical", minHeight:70, marginBottom:12 }}/>
              <div style={{ background:"#fff8f0", border:"1px solid #e6821e30", borderRadius:8, padding:"0.75rem", marginBottom:16 }}>
                <div style={{ fontSize:11, color:"#e6821e" }}>ΓÜá∩╕Å Do not share personal contact details. All communication must stay on Car Care Connect.</div>
              </div>
              <div style={{ display:"flex", gap:8 }}>
                <button type="submit" disabled={submitting}
                  style={{ flex:1, background:submitting?"#555555":"#e6821e", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"12px", cursor:submitting?"not-allowed":"pointer" }}>
                  {submitting?"Submitting...":"Submit offer"}
                </button>
                <button type="button" onClick={()=>setShowOffer(false)}
                  style={{ background:"none", border:"1px solid #dddddd", borderRadius:9, color:"#666", fontSize:13, padding:"12px 18px", cursor:"pointer" }}>
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { getCurrentPosition } from "../../lib/geolocation"
import toast from "react-hot-toast"

// Cart/checkout modal used directly from the main Marketplace page (browse to cart, no
// navigation away to a separate screen). Mirrors the exact, already-working checkout flow
// from CustomerPartsMarketplace.jsx (delivery zones, per-provider order splitting, commission
// and platform fee calculation, M-Pesa STK push) - cart state itself lives in Marketplace.jsx
// since "Add to Cart" buttons live on its listing grid, not here.
export default function MarketplaceCart({ cart, setCart, showCart, setShowCart, user, profile, onOrderComplete }) {
  const [zones, setZones] = useState([])
  const [feeMultipliers, setFeeMultipliers] = useState({ motorcycle:1, tuktuk:1.5, van:3, car:1.5 })
  const [platformFeeRateDisplay, setPlatformFeeRateDisplay] = useState({ rate:0.02, cap:200 })
  const [fulfillment, setFulfillment] = useState("pickup")
  const [selectedZone, setSelectedZone] = useState("")
  const [deliveryAddress, setDeliveryAddress] = useState("")
  const [deliveryLat, setDeliveryLat] = useState(null)
  const [deliveryLng, setDeliveryLng] = useState(null)
  const [detectingLocation, setDetectingLocation] = useState(false)
  const [ordering, setOrdering] = useState(false)
  const [checkoutStep, setCheckoutStep] = useState("cart") // cart, details, payment
  const [customerDetails, setCustomerDetails] = useState({ name:"", phone:"" })
  const [pendingOrder, setPendingOrder] = useState(null)
  const [showOrderPayment, setShowOrderPayment] = useState(false)
  const [paying, setPaying] = useState(false)

  useEffect(() => {
    supabase.from("delivery_zones").select("*").eq("is_active", true)
      .then(({ data }) => setZones(data||[]))
    supabase.from("app_settings").select("key,value")
      .in("key",["marketplace_delivery_fee_multiplier_motorcycle","marketplace_delivery_fee_multiplier_tuktuk","marketplace_delivery_fee_multiplier_van","marketplace_delivery_fee_multiplier_car"])
      .then(({ data }) => {
        const m = {}
        data?.forEach(r => {
          if (r.key.endsWith("motorcycle")) m.motorcycle = Number(r.value)
          if (r.key.endsWith("tuktuk")) m.tuktuk = Number(r.value)
          if (r.key.endsWith("van")) m.van = Number(r.value)
          if (r.key.endsWith("car")) m.car = Number(r.value)
        })
        setFeeMultipliers(prev => ({ ...prev, ...m }))
      })
    supabase.from("commission_rates").select("platform_fee_rate,platform_fee_cap").eq("provider_type","parts_dealer").maybeSingle()
      .then(({ data }) => { if (data) setPlatformFeeRateDisplay({ rate: Number(data.platform_fee_rate), cap: Number(data.platform_fee_cap) }) })
  }, [])

  useEffect(() => {
    if (user && profile) setCustomerDetails({ name: (profile.first_name||"")+" "+(profile.last_name||""), phone: profile.phone||"" })
  }, [user, profile])

  function removeFromCart(id) { setCart(prev=>prev.filter(c=>c.id!==id)) }
  function updateQty(id, qty) {
    if (qty<=0) return removeFromCart(id)
    setCart(prev=>prev.map(c=>c.id===id?{...c,qty}:c))
  }

  const cartTotal = cart.reduce((s,c)=>s+Number(c.price)*c.qty, 0)
  const zone = zones.find(z => z.id === selectedZone)
  const cartItemCount = cart.reduce((s,i)=>s+i.qty,0)
  const predictedVehicleType = cartItemCount<=3?"motorcycle":cartItemCount<=6?"tuktuk":"van"
  const deliveryFee = fulfillment === "delivery" && zone ? Math.round(Number(zone.base_fee) * (feeMultipliers[predictedVehicleType]||1)) : 0
  const platformFeeDisplay = Math.min(Math.round(cartTotal * platformFeeRateDisplay.rate), platformFeeRateDisplay.cap)
  const orderTotal = cartTotal + deliveryFee + platformFeeDisplay

  async function placeOrder() {
    if (cart.length === 0) return toast.error("Cart is empty")
    if (checkoutStep === "cart") { setCheckoutStep("details"); return }
    if (checkoutStep === "details") {
      if (!customerDetails.name) return toast.error("Please enter your name")
      if (!customerDetails.phone) return toast.error("Please enter your phone")
      if (fulfillment === "delivery" && !selectedZone) return toast.error("Please select a delivery zone")
      if (fulfillment === "delivery" && !deliveryAddress) return toast.error("Please enter delivery address")
      setCheckoutStep("payment"); return
    }
    setOrdering(true)
    try {
      const { data: rateRow } = await supabase.from("commission_rates").select("platform_rate,platform_fee_rate,platform_fee_cap").eq("provider_type","parts_dealer").maybeSingle()
      const commissionRate = rateRow ? Number(rateRow.platform_rate) : 0.05
      const platformFeeRate = rateRow ? Number(rateRow.platform_fee_rate) : 0.02
      const platformFeeCap = rateRow ? Number(rateRow.platform_fee_cap) : 200
      const byProvider = {}
      cart.forEach(item => {
        if (!byProvider[item.provider_id]) byProvider[item.provider_id] = []
        byProvider[item.provider_id].push(item)
      })
      // All orders from one checkout share this ID, so a single M-Pesa payment can
      // correctly mark every provider's order as paid at once - not just the first one
      // created - since one STK push covers the customer's whole cart, not one provider.
      const groupOrderId = crypto.randomUUID()
      let firstOrderNumber = null
      let totalOrderCount = 0
      let combinedTotal = 0
      for (const [providerId, items] of Object.entries(byProvider)) {
        const subtotal = items.reduce((s, i) => s + Number(i.price) * i.qty, 0)
        const commission = subtotal * commissionRate
        const platformFee = Math.min(Math.round(subtotal * platformFeeRate), platformFeeCap)
        const providerEarnings = subtotal - commission
        const orderDeliveryFee = Object.keys(byProvider).length === 1 ? deliveryFee : 0
        const { data: order, error } = await supabase.from("orders").insert({
          customer_id: user.id,
          provider_id: providerId,
          group_order_id: groupOrderId,
          subtotal,
          delivery_fee: orderDeliveryFee,
          platform_commission: commission,
          // No platform_fee column exists on orders - platformFee is still folded into
          // combinedTotal below so the amount actually charged stays correct.
          provider_earnings: providerEarnings,
          fulfillment_type: fulfillment,
          delivery_zone: zone?.name || null,
          delivery_address: deliveryAddress || null,
          delivery_latitude: deliveryLat || null,
          delivery_longitude: deliveryLng || null,
          customer_name: customerDetails.name,
          customer_phone: customerDetails.phone,
          payment_method: "mpesa",
          payment_status: "awaiting_payment",
          status: "pending_payment",
        }).select("id, order_number").single()
        if (error) throw error
        for (const item of items) {
          await supabase.from("order_items").insert({
            order_id: order.id,
            inventory_id: item.id,
            name: item.name,
            quantity: item.qty,
            unit_price: Number(item.price),
          })
          await supabase.from("inventory").update({ stock_quantity: item.stock_quantity - item.qty }).eq("id", item.id)
        }
        await supabase.from("notifications").insert({
          user_id: providerId,
          title: "New order received!",
          message: customerDetails.name + " ordered " + items.length + " item(s) - KES " + subtotal.toLocaleString() + " (Paid online via M-Pesa)",
          type: "success",
        })
        if (!firstOrderNumber) firstOrderNumber = order.order_number
        totalOrderCount++
        combinedTotal += subtotal + orderDeliveryFee + platformFee
      }
      setCart([])
      setShowCart(false)
      setCheckoutStep("cart")
      setDeliveryAddress("")
      setDeliveryLat(null)
      setDeliveryLng(null)
      setSelectedZone("")
      setPendingOrder({ id: groupOrderId, order_number: totalOrderCount>1?firstOrderNumber+" +"+(totalOrderCount-1):firstOrderNumber, amount: combinedTotal })
      setShowOrderPayment(true)
    } catch(err) { toast.error(err.message) }
    finally { setOrdering(false) }
  }

  // showOrderPayment must keep rendering even after placeOrder() closes the cart
  // (showCart false) to create the order - both modals live in this same component,
  // so hiding on showCart alone hid the payment popup the instant it was meant to open.
  if (!showCart && !showOrderPayment) return null

  return (
    <>
      {showCart&&(
      <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.6)", zIndex:200, display:"flex", alignItems:"flex-end", justifyContent:"center" }} onClick={()=>{ setShowCart(false); setCheckoutStep("cart") }}>
        <div style={{ width:"100%", maxWidth:500, background:"#ffffff", borderRadius:"20px 20px 0 0", padding:"1.5rem", maxHeight:"85vh", overflowY:"auto" }} onClick={e=>e.stopPropagation()}>
          <div style={{ display:"flex", justifyContent:"center", marginBottom:8 }}><div style={{ width:36, height:4, borderRadius:2, background:"#e0e0e0" }}/></div>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1.25rem" }}>
            <div>
              <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, color:"#000000" }}>
                {checkoutStep==="cart"?"Your cart":checkoutStep==="details"?"Delivery details":"Payment"}
              </div>
              <div style={{ display:"flex", gap:4, marginTop:4 }}>
                {["cart","details","payment"].map((s,i)=>(
                  <div key={s} style={{ flex:1, height:3, borderRadius:2, background:checkoutStep===s||(["details","payment"].includes(checkoutStep)&&i===0)||(checkoutStep==="payment"&&i===1)?"#e6821e":"#e0e0e0" }}/>
                ))}
              </div>
            </div>
            <button onClick={()=>{ setShowCart(false); setCheckoutStep("cart") }} style={{ background:"none", border:"none", color:"#777777", fontSize:22, cursor:"pointer" }}>&times;</button>
          </div>
          {cart.length===0&&<div style={{ color:"#888888", textAlign:"center", padding:"2rem" }}>Cart is empty</div>}
          {checkoutStep==="cart"&&cart.map(item=>(
            <div key={item.id} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", padding:"10px 0", borderBottom:"1px solid #eeeeee" }}>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ fontSize:13, color:"#000000" }}>{item.name}</div>
                <div style={{ fontSize:11, color:"#777777" }}>KES {Number(item.price).toLocaleString()} / {item.unit||"unit"}</div>
              </div>
              <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                <button onClick={()=>updateQty(item.id,item.qty-1)} style={{ background:"#f5f5f5", border:"none", borderRadius:6, color:"#000000", width:26, height:26, cursor:"pointer", fontSize:14 }}>-</button>
                <span style={{ fontSize:13, color:"#000000", minWidth:20, textAlign:"center" }}>{item.qty}</span>
                <button onClick={()=>updateQty(item.id,item.qty+1)} style={{ background:"#f5f5f5", border:"none", borderRadius:6, color:"#000000", width:26, height:26, cursor:"pointer", fontSize:14 }}>+</button>
                <span style={{ fontSize:12, color:"#e6821e", fontWeight:600, minWidth:60, textAlign:"right" }}>KES {(Number(item.price)*item.qty).toLocaleString()}</span>
              </div>
            </div>
          ))}
          {cart.length>0&&(
            <>
              <div style={{ marginTop:"1rem", marginBottom:"1rem" }}>
                <div style={{ fontSize:12, color:"#666", marginBottom:8 }}>Fulfillment</div>
                <div style={{ display:"flex", gap:8 }}>
                  {["pickup","delivery"].map(f=>(
                    <button key={f} onClick={()=>setFulfillment(f)}
                      style={{ flex:1, padding:"8px", borderRadius:8, border:"1px solid "+(fulfillment===f?"#e6821e":"#e0e0e0"), background:fulfillment===f?"#fff8f0":"#f5f5f5", color:fulfillment===f?"#e6821e":"#555", fontSize:12, cursor:"pointer", fontWeight:fulfillment===f?700:400 }}>
                      {f==="pickup"?"Pickup from shop":"Delivery to me"}
                    </button>
                  ))}
                </div>
              </div>
              {checkoutStep==="details"&&(
                <div style={{ marginBottom:12 }}>
                  <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#000000", marginBottom:10 }}>Your details</div>
                  <div style={{ marginBottom:8 }}>
                    <div style={{ fontSize:11, color:"#666", marginBottom:4 }}>Full name</div>
                    <input value={customerDetails.name} onChange={e=>setCustomerDetails(d=>({...d,name:e.target.value}))}
                      placeholder="Your full name"
                      style={{ width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"9px 12px", color:"#000000", fontSize:12, outline:"none", boxSizing:"border-box" }}/>
                  </div>
                  <div style={{ marginBottom:8 }}>
                    <div style={{ fontSize:11, color:"#666", marginBottom:4 }}>Phone number</div>
                    <input value={customerDetails.phone} onChange={e=>setCustomerDetails(d=>({...d,phone:e.target.value}))}
                      placeholder="0712 345 678"
                      style={{ width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"9px 12px", color:"#000000", fontSize:12, outline:"none", boxSizing:"border-box" }}/>
                  </div>
                  {fulfillment==="delivery"&&(
                    <>
                      <div style={{ marginBottom:8 }}>
                        <div style={{ fontSize:11, color:"#666", marginBottom:4 }}>Delivery zone</div>
                        <select value={selectedZone} onChange={e=>setSelectedZone(e.target.value)}
                          style={{ width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"9px 12px", color:"#000000", fontSize:12, outline:"none", boxSizing:"border-box" }}>
                          <option value="">Select zone...</option>
                          {zones.map(z=><option key={z.id} value={z.id}>{z.name} - KES {Number(z.base_fee).toLocaleString()}</option>)}
                        </select>
                      </div>
                      <div style={{ marginBottom:8 }}>
                        <div style={{ fontSize:11, color:"#666", marginBottom:4 }}>Delivery address</div>
                        <div style={{ display:"flex", gap:6 }}>
                          <input value={deliveryAddress} onChange={e=>setDeliveryAddress(e.target.value)} placeholder="Your full delivery address..."
                            style={{ flex:1, background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"9px 12px", color:"#000000", fontSize:12, outline:"none" }}/>
                          <button type="button" disabled={detectingLocation} onClick={()=>{ setDetectingLocation(true); Promise.resolve().then(async ()=>{ const pos = await getCurrentPosition(); return pos }).then(async pos=>{ setDeliveryLat(pos.latitude); setDeliveryLng(pos.longitude); const r=await fetch("https://nominatim.openstreetmap.org/reverse?lat="+pos.latitude+"&lon="+pos.longitude+"&format=json"); const d=await r.json(); setDeliveryAddress(d.display_name||"Location detected") }).catch(()=>{}).finally(()=>setDetectingLocation(false)) }} style={{ background:"#e6821e", border:"none", borderRadius:8, color:"#fff", fontSize:11, fontWeight:700, padding:"0 12px", cursor:"pointer", flexShrink:0 }}>
                            {detectingLocation?"...":"Detect"}
                          </button>
                        </div>
                      </div>
                    </>
                  )}
                </div>
              )}
              <div style={{ borderTop:"1px solid #eeeeee", paddingTop:"1rem", marginTop:"0.5rem" }}>
                <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, color:"#666", marginBottom:4 }}>
                  <span>Subtotal</span><span>KES {cartTotal.toLocaleString()}</span>
                </div>
                {fulfillment==="delivery"&&selectedZone&&(
                  <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, color:"#666", marginBottom:4 }}>
                    <span>Delivery fee</span><span>KES {deliveryFee.toLocaleString()}</span>
                  </div>
                )}
                <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, color:"#888", marginBottom:8, paddingBottom:8, borderBottom:"1px dashed #eee" }}>
                  <span>Platform fee <span style={{ fontSize:10, color:"#bbb" }}>({Math.round(platformFeeRateDisplay.rate*100)}%, max KES {platformFeeRateDisplay.cap})</span></span>
                  <span>KES {platformFeeDisplay.toLocaleString()}</span>
                </div>
                <div style={{ display:"flex", justifyContent:"space-between", fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#e6821e", marginBottom:"1rem" }}>
                  <span>Total</span><span>KES {orderTotal.toLocaleString()}</span>
                </div>
                <button onClick={placeOrder} disabled={ordering}
                  style={{ width:"100%", background:ordering?"#ccc":"#e6821e", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700, padding:"14px", cursor:ordering?"not-allowed":"pointer" }}>
                  {ordering?"Placing order...":checkoutStep==="cart"?"Continue":checkoutStep==="details"?"Continue to payment":"Place order"}
                </button>
                <div style={{ fontSize:11, color:"#888888", textAlign:"center", marginTop:8 }}>Secure payment via M-Pesa</div>
              </div>
            </>
          )}
        </div>
      </div>
      )}
      {showOrderPayment&&pendingOrder&&(
        <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.8)", zIndex:210, display:"flex", alignItems:"center", justifyContent:"center", padding:"1rem" }}>
          <div style={{ width:"100%", maxWidth:420, background:"#fff", borderRadius:16, padding:"1.5rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, marginBottom:4 }}>Complete Payment</div>
            <div style={{ fontSize:13, color:"#888", marginBottom:"1.25rem" }}>Order #{pendingOrder.order_number}</div>
            <div style={{ background:"#f8f8f8", borderRadius:10, padding:"1rem", marginBottom:"1.25rem" }}>
              <div style={{ fontSize:12, color:"#888", marginBottom:4 }}>Amount to pay</div>
              <div style={{ fontFamily:"Syne", fontSize:24, fontWeight:800, color:"#e6821e" }}>KES {Number(pendingOrder.amount||0).toLocaleString()}</div>
            </div>
            <button disabled={paying} onClick={async()=>{
              setPaying(true)
              try {
                const { data: sens } = await supabase.from("profile_sensitive").select("mpesa_number, phone").eq("id", user.id).maybeSingle()
                const phone = sens?.mpesa_number || sens?.phone || profile?.mpesa_phone
                if(!phone) { toast.error("Please add your M-Pesa number in Profile settings"); setPaying(false); return }
                const { data, error } = await supabase.functions.invoke("daraja-stk-push", {
                  body: { booking_id: pendingOrder.id, amount: Number(pendingOrder.amount||0), phone, account_ref: pendingOrder.order_number?.substring(0,12)||"CCC", description: "Parts Order #"+pendingOrder.order_number }
                })
                if (error) throw error
                if (data?.error) throw new Error(data.error)
                toast.success("Check your phone for M-Pesa payment prompt")
                setShowOrderPayment(false); setPendingOrder(null)
                if (onOrderComplete) onOrderComplete()
              } catch(err) { toast.error(err.message) }
              finally { setPaying(false) }
            }} style={{ width:"100%", background:paying?"#ccc":"#e6821e", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:15, fontWeight:700, padding:"14px", cursor:paying?"not-allowed":"pointer", marginBottom:10 }}>
              {paying?"Sending payment request...":"Pay via M-Pesa"}
            </button>
            <button onClick={()=>{ setShowOrderPayment(false); setPendingOrder(null) }} style={{ width:"100%", background:"none", border:"1px solid #eee", borderRadius:10, color:"#888", fontSize:13, padding:"12px", cursor:"pointer" }}>
              Cancel
            </button>
          </div>
        </div>
      )}
    </>
  )
}

import { useState, useEffect } from "react"
import { LockedIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import DarajaPayment from "../shared/DarajaPayment"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"
export default function MarketplacePayment({ offer, listing, onSuccess, onCancel }) {
  const { user, profile } = useAuth()
  const isMobile = useIsMobile()
  const [paying, setPaying] = useState(false)
  const [showPayment, setShowPayment] = useState(false)
  const [commissionRate, setCommissionRate] = useState(null)
  const [txnId, setTxnId] = useState(null)
  useEffect(() => {
    const rateKey = listing.listing_type==="vehicle" ? "marketplace_vehicle" : "marketplace_item"
    supabase.from("commission_rates").select("platform_rate").eq("provider_type", rateKey).maybeSingle()
      .then(({ data }) => setCommissionRate(data ? Number(data.platform_rate) : (listing.listing_type==="vehicle" ? 0.02 : 0.08)))
  }, [listing.listing_type])
  const salePrice = offer.counter_price || offer.offered_price
  const commission = commissionRate!=null ? salePrice * commissionRate : 0
  const sellerEarnings = salePrice - commission
  const processingFeeRate = 0.01
  const processingFee = Math.ceil(salePrice * processingFeeRate)
  const totalAmount = salePrice + processingFee
  async function initPayment() {
    setPaying(true)
    try {
      // acceptOffer() in MyListings.jsx already creates the marketplace_transactions record the
      // moment the seller accepts - inserting a second one here would leave two records for the
      // same sale (one permanently stuck "pending"). Look up the existing one instead.
      const { data: txn, error: txnError } = await supabase.from("marketplace_transactions").select("id").eq("offer_id", offer.id).maybeSingle()
      if (txnError) throw txnError
      if (!txn) throw new Error("No transaction found for this offer - please contact support")
      setTxnId(txn.id)
      setShowPayment(true)
    } catch(e) {
      toast.error(e.message || "Payment failed")
    } finally {
      setPaying(false)
    }
  }
  if (showPayment && txnId) {
    return (
      <DarajaPayment
        amount={totalAmount}
        bookingId={txnId}
        description={`Marketplace - ${listing.title}`}
        onSuccess={async () => {
          // No longer updating the transaction here - this only fires once the STK push was
          // merely sent, not once payment genuinely confirmed. The real payment callback
          // (daraja-callback / daraja-stk-query) now handles marking this paid.
          onSuccess && onSuccess()
        }}
        onClose={() => setShowPayment(false)}
      />
    )
  }
  return (
    <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem" }}>
      <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#000000", marginBottom:12 }}>
        Complete Purchase
      </div>
      <div style={{ background:"#ffffff", borderRadius:8, padding:"0.75rem", marginBottom:16 }}>
        <div style={{ fontSize:12, color:"#555555", marginBottom:8, fontWeight:600 }}>{listing.title}</div>
        <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, color:"#555555", marginBottom:4 }}>
          <span>Sale price</span><span>KES {Number(salePrice).toLocaleString()}</span>
        </div>
        <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, color:"#555555", marginBottom:4 }}>
          <span>M-Pesa processing fee (1%)</span><span>KES {processingFee.toLocaleString()}</span>
        </div>
        <div style={{ height:1, background:"#f0f0f0", margin:"8px 0" }}/>
        <div style={{ display:"flex", justifyContent:"space-between", fontSize:13, color:"#e6821e", fontWeight:700, marginBottom:4 }}>
          <span>You pay</span><span>KES {totalAmount.toLocaleString()}</span>
        </div>
        <div style={{ display:"flex", justifyContent:"space-between", fontSize:11, color:"#777777" }}>
          <span>Seller receives</span><span>KES {sellerEarnings.toLocaleString()}</span>
        </div>
        <div style={{ display:"flex", justifyContent:"space-between", fontSize:11, color:"#777777" }}>
          <span>Platform commission</span><span>KES {commission.toLocaleString()}</span>
        </div>
      </div>
      <div style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:8, padding:"0.75rem", marginBottom:16, fontSize:11, color:"#1d9e75", lineHeight:1.6 }}>
        <><LockedIcon size={12} color="#1d9e75"/> Funds held in escrow</> until you confirm receipt. 7-day dispute window after delivery.
      </div>
      <button onClick={initPayment} disabled={paying||commissionRate==null}
        style={{ width:"100%", background:paying?"#ccc":"#e6821e", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700, padding:"13px", cursor:paying?"not-allowed":"pointer", marginBottom:8 }}>
        {paying ? "Processing..." : `Pay KES ${totalAmount.toLocaleString()} via M-Pesa ΓåÆ`}
      </button>
      <button onClick={onCancel}
        style={{ width:"100%", background:"none", border:"1px solid #dddddd", borderRadius:10, color:"#666", fontSize:13, padding:"11px", cursor:"pointer" }}>
        Cancel
      </button>
    </div>
  )
}

import { useEffect, useState } from "react"
import { VehicleIcon, ServicesIcon, LocationIcon, EyeIcon, VideoIcon, MarketplaceIcon, HeartIcon, ChatIcon, ShareIcon } from "../../lib/cccIcons"
import { pushNotify } from "../../lib/pushNotify"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import { useNavigate } from "react-router-dom"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"
import InspectionRequest from "./InspectionRequest"
import PhotoUpload from "./PhotoUpload"
import VideoUpload from "./VideoUpload"
import CreateListing from "./CreateListing"
import FeaturedListing from "./FeaturedListing"

export default function MyListings() {
  const { user } = useAuth()
  const navigate = useNavigate()
  const isMobile = useIsMobile()
  const [listings, setListings] = useState([])
  const [offers, setOffers] = useState([])
  const [loading, setLoading] = useState(true)
  const [tab, setTab] = useState("listings")
  const [expanded, setExpanded] = useState(null)
  const [photoListing, setPhotoListing] = useState(null)
  const [videoListing, setVideoListing] = useState(null)
  const [editingListing, setEditingListing] = useState(null)
  const [featureListing, setFeatureListing] = useState(null)
  const [inspectListing, setInspectListing] = useState(null)
  const [listingPhotos, setListingPhotos] = useState([])
  const [counterPrice, setCounterPrice] = useState("")
  const [processing, setProcessing] = useState(null)
  const [showInspection, setShowInspection] = useState(null)

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("my-listings-live")
      .on("postgres_changes", { event:"*", schema:"public", table:"marketplace_listings", filter:`seller_id=eq.${user.id}` }, () => load())
      .on("postgres_changes", { event:"*", schema:"public", table:"marketplace_offers", filter:`seller_id=eq.${user.id}` }, () => loadOffers())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function load() {
    await Promise.all([loadListings(), loadOffers()])
    setLoading(false)
  }

  async function loadListings() {
    const { data } = await supabase.from("marketplace_listings")
      .select("*, marketplace_photos(photo_url,is_primary,display_order)")
      .eq("seller_id", user.id).order("created_at", { ascending:false })
    setListings((data||[]).map(l=>({...l, primary_photo:l.marketplace_photos?.find(p=>p.is_primary)?.photo_url||l.marketplace_photos?.[0]?.photo_url})))
  }

  async function loadOffers() {
    const { data } = await supabase.from("marketplace_offers")
      .select("*, marketplace_listings(title,price), buyer:profiles!marketplace_offers_buyer_id_fkey(first_name,last_name,city)")
      .eq("seller_id", user.id).order("created_at", { ascending:false })
    setOffers(data||[])
  }

  async function acceptOffer(offer) {
    setProcessing(offer.id)
    try {
      await supabase.from("marketplace_offers").update({ status:"accepted" }).eq("id",offer.id)
      await supabase.from("marketplace_offers").update({ status:"rejected" }).eq("listing_id",offer.listing_id).neq("id",offer.id)
      await supabase.from("marketplace_listings").update({ status:"sold" }).eq("id",offer.listing_id)
      const rateKey = offer.marketplace_listings?.listing_type==="vehicle" ? "marketplace_vehicle" : "marketplace_item"
      const { data: rateRow } = await supabase.from("commission_rates").select("platform_rate").eq("provider_type", rateKey).maybeSingle()
      const rate = rateRow ? Number(rateRow.platform_rate) : (offer.marketplace_listings?.listing_type==="vehicle" ? 0.02 : 0.08)
      const commission = Number(offer.offered_price) * rate
      // Above Safaricom's own KES 250,000 B2C ceiling, CCC can never actually hold the full sale
      // amount via M-Pesa - only the seller's facilitation fee gets collected, and the buyer
      // and seller exchange the real sum directly between themselves once that's paid.
      const isLargeSale = Number(offer.offered_price) > 250000
      await supabase.from("marketplace_transactions").insert({
        listing_id:offer.listing_id, offer_id:offer.id, buyer_id:offer.buyer_id, seller_id:user.id,
        sale_price:offer.offered_price, platform_commission:commission, seller_earnings:Number(offer.offered_price)-commission,
        payment_status: isLargeSale ? "awaiting_facilitation_fee" : "pending",
        facilitation_fee_amount: isLargeSale ? commission : null
      })
      await supabase.from("notifications").insert({
        user_id:offer.buyer_id, title:"Offer accepted! ≡ƒÄë",
        message:"Your offer of KES "+Number(offer.offered_price).toLocaleString()+" has been accepted. Please proceed with payment.",
        type:"success"
      })
      toast.success("Offer accepted!")
      load()
    } catch(err) { toast.error(err.message) }
    finally { setProcessing(null) }
  }

  async function rejectOffer(offerId, buyerId, title) {
    setProcessing(offerId)
    try {
      await supabase.from("marketplace_offers").update({ status:"rejected" }).eq("id",offerId)
      await supabase.from("notifications").insert({ user_id:buyerId, title:"Offer update", message:"Your offer for "+title+" was not accepted.", type:"info" })
      toast.success("Offer rejected")
      load()
    } catch(err) { toast.error(err.message) }
    finally { setProcessing(null) }
  }

  async function counterOffer(offer) {
    if (!counterPrice) return toast.error("Enter counter price")
    setProcessing(offer.id)
    try {
      await supabase.from("marketplace_offers").update({ status:"countered", counter_price:parseFloat(counterPrice) }).eq("id",offer.id)
      await supabase.from("notifications").insert({
        user_id:offer.buyer_id, title:"Counter offer received",
        message:"Seller countered with KES "+Number(counterPrice).toLocaleString(),
        type:"info"
      })
      toast.success("Counter sent")
      setCounterPrice(""); setExpanded(null); load()
    } catch(err) { toast.error(err.message) }
    finally { setProcessing(null) }
  }

  async function openPhotos(listing) {
    const { data } = await supabase.from("marketplace_photos").select("*").eq("listing_id",listing.id).order("display_order")
    setListingPhotos(data||[])
    setPhotoListing(photoListing===listing.id?null:listing.id)
  }

  function shareListing(listing) {
    const msg = encodeURIComponent("Check out this listing on Car Care Connect: " + listing.title + " - KES " + Number(listing.price).toLocaleString() + " https://carcareconnect.care/dashboard/marketplace")
    window.open("https://wa.me/?text=" + msg, "_blank")
  }

  async function deleteListing(id) {
    if (!confirm("Delete this listing?")) return
    const { error } = await supabase.from("marketplace_listings").delete().eq("id",id).eq("seller_id",user.id)
    if (error) { toast.error("Failed to delete listing: "+error.message); return }
    toast.success("Listing deleted")
    loadListings()
  }

  const pendingOffers = offers.filter(o=>o.status==="pending")
  const SC = { pending:"#e6821e", active:"#1d9e75", sold:"#8b5cf6", rejected:"#e24b4a", suspended:"#555" }

  return (
    <div>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1.25rem", flexWrap:"wrap", gap:10 }}>
        <div>
          <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:"#000000" }}>My Listings</div>
          <div style={{ fontSize:12, color:"#777777" }}>Manage your marketplace listings and offers</div>
        </div>
        <button onClick={()=>navigate("/dashboard/marketplace/new")}
          style={{ background:"#e6821e", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"10px 18px", cursor:"pointer" }}>
          + New listing
        </button>
      </div>

      <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:8, marginBottom:"1.25rem" }}>
        {[
          { label:"Total", value:listings.length, color:"#000000" },
          { label:"Active", value:listings.filter(l=>l.status==="active").length, color:"#1d9e75" },
          { label:"Pending", value:listings.filter(l=>l.status==="pending").length, color:"#e6821e" },
          { label:"Offers", value:pendingOffers.length, color:"#8b5cf6" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#ffffff", borderRadius:10, padding:"0.6rem", border:"1px solid #eeeeee", textAlign:"center" }}>
            <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:10, color:"#777777" }}>{s.label}</div>
          </div>
        ))}
      </div>

      {pendingOffers.length>0&&(
        <div style={{ background:"#faf5ff", border:"1px solid #8b5cf640", borderRadius:10, padding:"0.75rem", marginBottom:"1rem" }}>
          <div style={{ fontSize:12, color:"#8b5cf6", fontWeight:600, display:"flex", alignItems:"center", gap:4 }}><WalletIcon size={12} color="#8b5cf6"/> {pendingOffers.length} offer{pendingOffers.length>1?"s":""} waiting</div>
        </div>
      )}

      <div style={{ display:"flex", gap:6, marginBottom:"1rem" }}>
        {[{k:"listings",l:"Listings ("+listings.length+")"},{k:"offers",l:"Offers ("+offers.length+")"}].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{ padding:"7px 14px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#e6821e":"#555555", color:tab===t.k?"#fff":"#666", fontFamily:"DM Sans,sans-serif", fontWeight:tab===t.k?700:400 }}>
            {t.l}
          </button>
        ))}
      </div>

      {loading&&<div style={{ color:"#777777", fontSize:13 }}>Loading...</div>}

      {tab==="listings"&&(
        <div>
          {!loading&&listings.length===0&&(
            <div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"3rem" }}>
              <div style={{ marginBottom:10, display:"flex", justifyContent:"center" }}><MarketplaceIcon size={32} color="#e6821e"/></div>
              No listings yet
              <div style={{ marginTop:12 }}>
                <button onClick={()=>navigate("/dashboard/marketplace/new")}
                  style={{ background:"#e6821e", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"9px 18px", cursor:"pointer" }}>
                  Create first listing
                </button>
              </div>
            </div>
          )}
          {listings.map(l=>(
            <div key={l.id} style={{ background:"#ffffff", border:"1px solid "+(SC[l.status]||"#eeeeee")+"30", borderRadius:12, marginBottom:10, overflow:"hidden" }}>
              <div style={{ display:"flex", gap:0 }}>
                <div style={{ width:90, minHeight:90, background:"#f5f5f5", flexShrink:0, display:"flex", alignItems:"center", justifyContent:"center", overflow:"hidden" }}>
                  {l.primary_photo
                    ? <img src={l.primary_photo} alt="" style={{ width:"100%", height:"100%", objectFit:"cover", minHeight:90 }}/>
                    : <span style={{ display:"flex", justifyContent:"center" }}>{l.listing_type==="vehicle"?<VehicleIcon size={32} color="#e6821e"/>:l.listing_type==="part"?"≡ƒöº":"Γ£¿"}</span>
                  }
                </div>
                <div style={{ flex:1, padding:"0.75rem", minWidth:0 }}>
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", gap:4, marginBottom:3 }}>
                    <div style={{ fontSize:13, fontWeight:600, color:"#000000", flex:1, minWidth:0, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{l.title}</div>
                    <div style={{ fontFamily:"Syne", fontSize:12, fontWeight:800, color:"#e6821e", flexShrink:0 }}>KES {Number(l.price).toLocaleString()}</div>
                  </div>
                  <div style={{ display:"flex", gap:4, alignItems:"center", flexWrap:"wrap", marginBottom:3 }}>
                    <span style={{ fontSize:10, padding:"1px 6px", borderRadius:8, background:(SC[l.status]||"#888")+"20", color:SC[l.status]||"#888" }}>{l.status}</span>
                    {l.is_featured&&<span style={{ fontSize:10, color:"#e6821e" }}>Γ¡É</span>}
                    {l.is_inspected&&<span style={{ fontSize:10, color:"#1d9e75" }}>Γ£ô</span>}
                    {l.video_url&&(
                      <span style={{ fontSize:10, padding:"1px 6px", borderRadius:8,
                        background:l.video_status==="approved"?"#f0fdf4":l.video_status==="rejected"?"#fff5f5":"#fff8f0",
                        color:l.video_status==="approved"?"#1d9e75":l.video_status==="rejected"?"#e24b4a":"#e6821e" }}>
                        <VideoIcon size={12} color="#8b5cf6"/> {l.video_status==="approved"?"Video Γ£ô":l.video_status==="rejected"?"Video Γ£ù":"Video pending"}
                      </span>
                    )}
                  </div>
                  {l.listing_type==="vehicle"&&<div style={{ fontSize:10, color:"#777777", marginBottom:2 }}>{[l.make,l.model,l.year].filter(Boolean).join(" ┬╖ ")}</div>}
                  <div style={{ fontSize:10, color:"#777777", display:"flex", alignItems:"center", gap:4 }}><LocationIcon size={10} color="#777777"/> {l.city||"ΓÇö"} ┬╖ <EyeIcon size={10} color="#777777"/> {l.views||0} ┬╖ {new Date(l.created_at).toLocaleDateString()}</div>
                </div>
              </div>

              {l.status==="pending"&&l.listing_type==="vehicle"&&l.inspection_status!=="passed"&&(
                <div style={{ borderTop:"1px solid #eeeeee", padding:"0.75rem", background:"#fff8f0" }}>
                  <div style={{ fontSize:11, color:"#e6821e", marginBottom:6 }}>ΓÅ│ CCC inspection required before approval</div>
                  <button onClick={()=>setShowInspection(showInspection===l.id?null:l.id)}
                    style={{ background:"#e6821e", border:"none", borderRadius:7, color:"#fff", fontSize:11, padding:"6px 14px", cursor:"pointer", fontWeight:600, width:"100%" }}>
                    {showInspection===l.id?"Close":"Schedule and Pay Inspection"}
                  </button>
                  {showInspection===l.id&&<div style={{ marginTop:8 }}><InspectionRequest listing={l} onSuccess={()=>{ setShowInspection(null); loadListings() }}/></div>}
                </div>
              )}
              {l.status==="pending"&&(l.listing_type!=="vehicle"||l.inspection_status==="passed")&&(
                <div style={{ borderTop:"1px solid #eeeeee", padding:"0.5rem 0.75rem" }}>
                  <div style={{ fontSize:11, color:"#e6821e" }}>ΓÅ│ Under review</div>
                </div>
              )}
              {l.status==="rejected"&&l.admin_notes&&(
                <div style={{ borderTop:"1px solid #eeeeee", padding:"0.5rem 0.75rem" }}>
                  <div style={{ fontSize:11, color:"#e24b4a" }}>Γ¥î {l.admin_notes}</div>
                </div>
              )}

              {inspectListing===l.id&&<div style={{ borderTop:"1px solid #eeeeee", padding:"0.75rem" }}><InspectionRequest listing={l} onSuccess={()=>{ setInspectListing(null); loadListings() }}/></div>}
              {featureListing===l.id&&<div style={{ borderTop:"1px solid #eeeeee", padding:"0.75rem" }}><FeaturedListing listingId={l.id} onSuccess={()=>{ setFeatureListing(null); loadListings() }}/></div>}
              {editingListing===l.id&&(
                <div style={{ borderTop:"1px solid #eeeeee", padding:"0.75rem" }}>
                  <CreateListing editListing={l} onSaved={()=>{ setEditingListing(null); loadListings() }}/>
                </div>
              )}
              {photoListing===l.id&&(
                <div style={{ borderTop:"1px solid #eeeeee", padding:"0.75rem" }}>
                  <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginBottom:8 }}>
                    {listingPhotos.map(p=>(<img key={p.id} src={p.photo_url} alt="" style={{ width:64, height:64, objectFit:"cover", borderRadius:8, border:p.is_primary?"2px solid #e6821e":"1px solid #dddddd" }}/>))}
                    {listingPhotos.length===0&&<div style={{ fontSize:11, color:"#777777" }}>No photos yet</div>}
                  </div>
                  <PhotoUpload listingId={l.id} onUploaded={()=>openPhotos(l)} existingPhotos={listingPhotos}/>
                </div>
              )}
              {videoListing===l.id&&(
                <div style={{ padding:"1rem", background:"#f0f7ff", borderTop:"1px solid #378add20" }}>
                  <VideoUpload listingId={l.id} onUploaded={()=>{ setVideoListing(null); load() }}/>
                </div>
              )}
              {l.video_url&&videoListing!==l.id&&(
                <div style={{ padding:"1rem", borderTop:"1px solid #eeeeee" }}>
                  <div style={{ fontSize:11, fontWeight:700, color:"#555", marginBottom:6 }}>
                    ≡ƒÄÑ Your video
                    <span style={{ marginLeft:6, fontSize:10, padding:"1px 6px", borderRadius:8,
                      background:l.video_status==="approved"?"#f0fdf4":l.video_status==="rejected"?"#fff5f5":"#fff8f0",
                      color:l.video_status==="approved"?"#1d9e75":l.video_status==="rejected"?"#e24b4a":"#e6821e" }}>
                      {l.video_status==="approved"?"Γ£ô Approved":l.video_status==="rejected"?"Γ£ù Rejected ΓÇö "+l.video_rejection_reason:"ΓÅ│ Pending admin review"}
                    </span>
                  </div>
                  <video src={l.video_url} controls style={{ width:"100%", borderRadius:8, maxHeight:200 }}/>
                </div>
              )}

              <div style={{ borderTop:"1px solid #eeeeee", padding:"0.5rem 0.75rem", display:"flex", gap:6, flexWrap:"wrap" }}>
                <button onClick={()=>navigate("/dashboard/marketplace?listing=" + l.id)} style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:10, padding:"5px 10px", cursor:"pointer" }}>View</button>
                <button onClick={()=>setEditingListing(editingListing===l.id?null:l.id)} style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:7, color:"#e6821e", fontSize:10, padding:"5px 10px", cursor:"pointer" }}>Edit</button>
                <button onClick={()=>openPhotos(l)} style={{ background:"#ffffff", border:"1px solid #dddddd", borderRadius:7, color:"#555555", fontSize:10, padding:"5px 10px", cursor:"pointer" }}>Photos {l.marketplace_photos?.length>0?"("+l.marketplace_photos.length+")":""}</button>
                {l.listing_type==="vehicle"&&<button onClick={()=>setFeatureListing(featureListing===l.id?null:l.id)} style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:7, color:"#e6821e", fontSize:10, padding:"5px 10px", cursor:"pointer" }}>Feature</button>}
                <button onClick={()=>setInspectListing(inspectListing===l.id?null:l.id)} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:10, padding:"5px 10px", cursor:"pointer" }}>Inspect</button>
                <button onClick={()=>setVideoListing(videoListing===l.id?null:l.id)}
                  style={{ background:"#f0f7ff", border:"1px solid #378add30", borderRadius:7, color:"#378add", fontSize:10, padding:"5px 10px", cursor:"pointer" }}>
                  ≡ƒÄÑ {l.video_url?"Replace Video":"Add Video"}
                </button>
                {l.status!=="sold"&&<button onClick={()=>deleteListing(l.id)} style={{ background:"none", border:"1px solid #e24b4a30", borderRadius:7, color:"#e24b4a", fontSize:10, padding:"5px 10px", cursor:"pointer" }}>Delete</button>}
              </div>
            </div>
          ))}
        </div>
      )}

      {tab==="offers"&&(
        <div>
          {!loading&&offers.length===0&&(
            <div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"3rem" }}>
              <div style={{ fontSize:32, marginBottom:10 }}>≡ƒÆ░</div>
              No offers yet
            </div>
          )}
          {offers.map(o=>{
            const OC = { pending:"#8b5cf6", accepted:"#1d9e75", rejected:"#e24b4a", countered:"#e6821e", withdrawn:"#555" }
            return (
              <div key={o.id} style={{ background:"#ffffff", border:"1px solid "+(OC[o.status]||"#eeeeee")+"30", borderRadius:12, padding:"1rem", marginBottom:10 }}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontSize:13, fontWeight:600, color:"#000000", marginBottom:4 }}>{o.marketplace_listings?.title}</div>
                    <div style={{ fontSize:11, color:"#777777", marginBottom:2 }}>Asking: KES {Number(o.marketplace_listings?.price||0).toLocaleString()}</div>
                    <div style={{ fontSize:11, color:"#777777", marginBottom:2 }}>From: {o.buyer?.first_name} {o.buyer?.last_name}{o.buyer?.city&&" ┬╖ "+o.buyer.city}</div>
                    {o.message&&<div style={{ fontSize:11, color:"#555555", fontStyle:"italic", marginBottom:4 }}>"{o.message}"</div>}
                    <div style={{ fontSize:10, color:"#888888" }}>{new Date(o.created_at).toLocaleString()}</div>
                  </div>
                  <div style={{ textAlign:"right", flexShrink:0 }}>
                    <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, color:"#e6821e" }}>KES {Number(o.offered_price).toLocaleString()}</div>
                    {o.counter_price&&<div style={{ fontSize:11, color:"#8b5cf6", marginTop:2 }}>Counter: KES {Number(o.counter_price).toLocaleString()}</div>}
                    <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:(OC[o.status]||"#888")+"20", color:OC[o.status]||"#888", marginTop:4, display:"inline-block" }}>{o.status}</span>
                  </div>
                </div>
                {o.status==="pending"&&(
                  <div>
                    <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginBottom:expanded===o.id?10:0 }}>
                      <button onClick={()=>acceptOffer(o)} disabled={processing===o.id}
                        style={{ background:"#1d9e75", border:"none", borderRadius:7, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:11, fontWeight:700, padding:"6px 14px", cursor:"pointer" }}>
                        Accept
                      </button>
                      <button onClick={()=>setExpanded(expanded===o.id?null:o.id)}
                        style={{ background:"#faf5ff", border:"1px solid #8b5cf640", borderRadius:7, color:"#8b5cf6", fontSize:11, padding:"6px 12px", cursor:"pointer" }}>
                        Counter
                      </button>
                      <button onClick={()=>rejectOffer(o.id,o.buyer_id,o.marketplace_listings?.title)} disabled={processing===o.id}
                        style={{ background:"none", border:"1px solid #e24b4a30", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"6px 12px", cursor:"pointer" }}>
                        Decline
                      </button>
                    </div>
                    {expanded===o.id&&(
                      <div style={{ marginTop:8, display:"flex", gap:8 }}>
                        <input type="number" value={counterPrice} onChange={e=>setCounterPrice(e.target.value)}
                          placeholder="Counter price"
                          style={{ flex:1, background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:7, padding:"8px 12px", color:"#000000", fontSize:12, outline:"none" }}/>
                        <button onClick={()=>counterOffer(o)} disabled={processing===o.id}
                          style={{ background:"#8b5cf6", border:"none", borderRadius:7, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:11, fontWeight:700, padding:"8px 14px", cursor:"pointer" }}>
                          Send
                        </button>
                      </div>
                    )}
                  </div>
                )}
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from "react"
import { PaymentsIcon, ShieldIcon, MarketplaceIcon, WalletIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import { useNavigate } from "react-router-dom"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"
import MarketplacePayment from "./MarketplacePayment"

export default function MyOffers() {
  const { user } = useAuth()
  const isMobile = useIsMobile()
  const navigate = useNavigate()
  const [offers, setOffers] = useState([])
  const [payingOffer, setPayingOffer] = useState(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("my-offers-live")
      .on("postgres_changes", { event:"*", schema:"public", table:"marketplace_offers", filter:`buyer_id=eq.${user.id}` }, () => load())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function load() {
    const { data } = await supabase.from("marketplace_offers")
      .select("*, marketplace_listings(title,price,listing_type,make,model,year,status), seller:profiles!marketplace_offers_seller_id_fkey(first_name,last_name,business_name)")
      .eq("buyer_id", user.id)
      .order("created_at", { ascending:false })
    setOffers(data||[])
    setLoading(false)
  }

  async function acceptCounter(offer) {
    try {
      await supabase.from("marketplace_offers").update({ status:"accepted", offered_price:offer.counter_price }).eq("id",offer.id)
      await supabase.from("marketplace_listings").update({ status:"sold" }).eq("id",offer.listing_id)
      const rateKey = offer.marketplace_listings?.listing_type==="vehicle" ? "marketplace_vehicle" : "marketplace_item"
      const { data: rateRow } = await supabase.from("commission_rates").select("platform_rate").eq("provider_type", rateKey).maybeSingle()
      const rate = rateRow ? Number(rateRow.platform_rate) : (offer.marketplace_listings?.listing_type==="vehicle" ? 0.02 : 0.08)
      const commission = Number(offer.counter_price) * rate
      // Same B2C ceiling logic as acceptOffer() in MyListings.jsx - above KES 250,000, CCC can
      // never hold the full amount via M-Pesa, only the seller's facilitation fee.
      const isLargeSale = Number(offer.counter_price) > 250000
      await supabase.from("marketplace_transactions").insert({
        listing_id:offer.listing_id, offer_id:offer.id, buyer_id:user.id,
        seller_id:offer.seller_id, sale_price:offer.counter_price,
        platform_commission:commission, seller_earnings:Number(offer.counter_price)-commission,
        payment_status: isLargeSale ? "awaiting_facilitation_fee" : "pending",
        facilitation_fee_amount: isLargeSale ? commission : null,
      })
      await supabase.from("notifications").insert({
        user_id:offer.seller_id, title:"Counter offer accepted! ≡ƒÄë",
        message:`The buyer has accepted your counter offer of KES ${Number(offer.counter_price).toLocaleString()} for "${offer.marketplace_listings?.title}".`,
        type:"success",
      })
      toast.success("Counter accepted ΓÇö proceed to payment")
      load()
    } catch(err) { toast.error(err.message) }
  }

  async function withdrawOffer(id) {
    if (!confirm("Withdraw this offer?")) return
    await supabase.from("marketplace_offers").update({ status:"withdrawn" }).eq("id",id).eq("buyer_id",user.id)
    toast.success("Offer withdrawn")
    load()
  }

  const OC = { pending:"#8b5cf6", accepted:"#1d9e75", rejected:"#e24b4a", countered:"#e6821e", withdrawn:"#555" }

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:"#000000", marginBottom:4 }}>My Offers</div>
      <div style={{ fontSize:12, color:"#777777", marginBottom:"1.25rem" }}>Track offers you have made on marketplace listings</div>

      {loading&&<div style={{ color:"#777777", fontSize:13 }}>Loading...</div>}
      {!loading&&offers.length===0&&(
        <div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"3rem" }}>
          <div style={{ marginBottom:10, display:"flex", justifyContent:"center" }}><WalletIcon size={32} color="#1d9e75"/></div>
          No offers made yet
          <div style={{ marginTop:12 }}>
            <button onClick={()=>navigate("/dashboard/marketplace")}
              style={{ background:"#e6821e", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"9px 18px", cursor:"pointer" }}>
              Browse marketplace
            </button>
          </div>
        </div>
      )}

      {offers.map(o=>(
        <div key={o.id} style={{ background:"#ffffff", border:`1px solid ${OC[o.status]||"#eeeeee"}30`, borderRadius:12, padding:"1rem", marginBottom:10 }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4, flexWrap:"wrap" }}>
                <span>{o.marketplace_listings?.listing_type==="vehicle"?<VehicleIcon size={16} color="#e6821e"/>:<ServicesIcon size={16} color="#8b5cf6"/>}</span>
                <div style={{ fontSize:13, fontWeight:600, color:"#000000" }}>{o.marketplace_listings?.title}</div>
                <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:`${OC[o.status]||"#888"}20`, color:OC[o.status]||"#888" }}>{o.status}</span>
              </div>
              <div style={{ fontSize:11, color:"#777777", marginBottom:2 }}>
                Asking: KES {Number(o.marketplace_listings?.price||0).toLocaleString()}
              </div>
              <div style={{ fontSize:11, color:"#777777", marginBottom:2 }}>
                Seller: {o.seller?.business_name||`${o.seller?.first_name} ${o.seller?.last_name}`}
              </div>
              {o.message&&<div style={{ fontSize:11, color:"#555555", fontStyle:"italic", marginBottom:4 }}>"{o.message}"</div>}
              <div style={{ fontSize:10, color:"#888888" }}>{new Date(o.created_at).toLocaleString()}</div>
            </div>
            <div style={{ textAlign:"right", flexShrink:0 }}>
              <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#e6821e" }}>
                KES {Number(o.offered_price).toLocaleString()}
              </div>
              {o.counter_price&&<div style={{ fontSize:11, color:"#e6821e", marginTop:2 }}>Counter: KES {Number(o.counter_price).toLocaleString()}</div>}
            </div>
          </div>

          {/* Counter offer action */}
          {o.status==="countered"&&(
            <div style={{ background:"#fff8f0", border:"1px solid #e6821e30", borderRadius:8, padding:"0.75rem", marginBottom:8 }}>
              <div style={{ fontSize:12, color:"#e6821e", fontWeight:600, marginBottom:4, display:"flex", alignItems:"center", gap:4 }}><RefreshIcon size={12} color="#e6821e"/> Seller countered with KES {Number(o.counter_price).toLocaleString()}</div>
              <div style={{ display:"flex", gap:8 }}>
                <button onClick={()=>acceptCounter(o)}
                  style={{ background:"#1d9e75", border:"none", borderRadius:7, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:11, fontWeight:700, padding:"6px 14px", cursor:"pointer" }}>
                  Γ£ô Accept counter
                </button>
                <button onClick={()=>withdrawOffer(o.id)}
                  style={{ background:"none", border:"1px solid #e24b4a30", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"6px 12px", cursor:"pointer" }}>
                  Decline
                </button>
              </div>
            </div>
          )}

          {/* Accepted ΓÇö proceed to payment */}
          {o.status==="accepted"&&o.marketplace_listings?.status!=="sold"&&(
            <div style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:8, padding:"0.75rem" }}>
              <div style={{ fontSize:12, color:"#1d9e75", fontWeight:600, marginBottom:6 }}>Γ£ô Offer accepted ΓÇö proceed to payment</div>
              {/* Buyer protection notice */}
              <div style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:8, padding:"10px 12px", marginBottom:8 }}>
                <div style={{ fontSize:11, fontWeight:700, color:"#1d9e75", marginBottom:4, display:"flex", alignItems:"center", gap:4 }}><ShieldIcon size={12} color="#1d9e75"/> Buyer Protection</div>
                <div style={{ fontSize:10, color:"#555", lineHeight:1.5 }}>
                  Your payment is held securely in escrow by CCC. Funds are only released to the seller after you confirm receipt of the item in good condition. You have 7 days to raise a dispute.
                </div>
              </div>
              <button onClick={()=>setPayingOffer(payingOffer===o.id?null:o.id)}
                style={{ background:"#e6821e", border:"none", borderRadius:7, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"8px 16px", cursor:"pointer" }}>
                <><PaymentsIcon size={14} color="currentColor"/> Pay now</>
              </button>
            </div>
          )}
          {payingOffer===o.id&&o.status==="accepted"&&(
            <div style={{ marginTop:10 }}>
              <MarketplacePayment
                offer={o}
                listing={o.marketplace_listings}
                onSuccess={()=>{ setPayingOffer(null); load() }}
                onCancel={()=>setPayingOffer(null)}
              />
            </div>
          )}
          {o.status==="accepted_old"&&o.marketplace_listings?.status!=="sold"&&(
            <div style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:8, padding:"0.75rem" }}>
              <div style={{ fontSize:12, color:"#1d9e75", fontWeight:600, marginBottom:4 }}>Γ£ô Offer accepted! Proceed to payment</div>
              <div style={{ fontSize:11, color:"#777777" }}>Contact support to complete the transaction securely through Car Care Connect.</div>
            </div>
          )}

          {o.status==="pending"&&(
            <button onClick={()=>withdrawOffer(o.id)}
              style={{ background:"none", border:"1px solid #dddddd", borderRadius:7, color:"#777777", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
              Withdraw offer
            </button>
          )}
        </div>
      ))}
    </div>
  )
}

import { useState } from "react"
import { supabase } from "../../lib/supabase"
import { validateFile, sanitizeFilePath } from "../../lib/uploadValidation"
import { useAuth } from "../../contexts/AuthContext"
import toast from "react-hot-toast"

export default function PhotoUpload({ listingId, existingPhotos=[], onUploaded }) {
  const { user } = useAuth()
  const [uploading, setUploading] = useState(false)
  const [photos, setPhotos] = useState(existingPhotos)
  const [dragOver, setDragOver] = useState(false)

  async function uploadFiles(files) {
    if (!files?.length) return
    if (photos.length + files.length > 10) return toast.error("Maximum 10 photos allowed")
    setUploading(true)
    try {
      const uploaded = []
      for (const file of Array.from(files)) {
        if (!file.type.startsWith("image/")) { toast.error(`${file.name} is not an image`); continue }
        if (file.size > 5*1024*1024) { toast.error(`${file.name} exceeds 5MB limit`); continue }
        const ext = file.name.split(".").pop()
        const path = `${user.id}/${listingId}/${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`
        const { error } = await supabase.storage.from("marketplace").upload(path, file)
        if (error) throw error
        const { data } = supabase.storage.from("marketplace").getPublicUrl(path)
        const isPrimary = photos.length === 0 && uploaded.length === 0
        const { data: photo } = await supabase.from("marketplace_photos").insert({
          listing_id: listingId,
          photo_url: data.publicUrl,
          is_primary: isPrimary,
          display_order: photos.length + uploaded.length,
        }).select().single()
        if (photo) uploaded.push(photo)
      }
      const newPhotos = [...photos, ...uploaded]
      setPhotos(newPhotos)
      if (onUploaded) onUploaded(newPhotos)
      toast.success(`${uploaded.length} photo(s) uploaded`)
    } catch(err) { toast.error(err.message) }
    finally { setUploading(false) }
  }

  async function setPrimary(photoId) {
    await supabase.from("marketplace_photos").update({ is_primary:false }).eq("listing_id",listingId)
    await supabase.from("marketplace_photos").update({ is_primary:true }).eq("id",photoId)
    setPhotos(p=>p.map(ph=>({...ph, is_primary:ph.id===photoId})))
    toast.success("Cover photo updated")
  }

  async function deletePhoto(photo) {
    try {
      const path = photo.photo_url.split("/marketplace/")[1]
      await supabase.storage.from("marketplace").remove([path])
      await supabase.from("marketplace_photos").delete().eq("id",photo.id)
      const remaining = photos.filter(p=>p.id!==photo.id)
      // If deleted was primary, set first remaining as primary
      if (photo.is_primary && remaining.length>0) {
        await supabase.from("marketplace_photos").update({ is_primary:true }).eq("id",remaining[0].id)
        remaining[0].is_primary = true
      }
      setPhotos(remaining)
      if (onUploaded) onUploaded(remaining)
      toast.success("Photo deleted")
    } catch(err) { toast.error(err.message) }
  }

  return (
    <div>
      <div style={{ fontSize:11, color:"#777777", marginBottom:8 }}>
        {photos.length}/10 photos ┬╖ First photo is the cover ┬╖ Click photo to set as cover
      </div>

      {/* Upload area */}
      <div
        onDragOver={e=>{ e.preventDefault(); setDragOver(true) }}
        onDragLeave={()=>setDragOver(false)}
        onDrop={e=>{ e.preventDefault(); setDragOver(false); uploadFiles(e.dataTransfer.files) }}
        style={{ border:`2px dashed ${dragOver?"#e6821e":"#555555"}`, borderRadius:12, padding:"1.5rem", textAlign:"center", marginBottom:12, background:dragOver?"#fff8f0":"transparent", transition:"all 0.2s" }}>
        <div style={{ fontSize:32, marginBottom:8 }}>≡ƒô╕</div>
        <div style={{ fontSize:13, color:"#666", marginBottom:8 }}>
          {uploading?"Uploading...":"Drag photos here or click to select"}
        </div>
        <div style={{ fontSize:11, color:"#888888", marginBottom:12 }}>Max 10 photos ┬╖ 5MB each ┬╖ JPG, PNG, WEBP</div>
        <input type="file" accept="image/*" multiple id="photo-upload" style={{ display:"none" }}
          onChange={e=>uploadFiles(e.target.files)}/>
        <label htmlFor="photo-upload"
          style={{ background:uploading?"#555555":"#e6821e", border:"none", borderRadius:8, color:uploading?"#555":"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"9px 20px", cursor:uploading?"not-allowed":"pointer", display:"inline-block" }}>
          {uploading?"Uploading...":"Select photos"}
        </label>
      </div>

      {/* Photo grid */}
      {photos.length>0&&(
        <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:8 }}>
          {photos.map(photo=>(
            <div key={photo.id} style={{ position:"relative", borderRadius:10, overflow:"hidden", border:`2px solid ${photo.is_primary?"#e6821e":"transparent"}`, cursor:"pointer" }}
              onClick={()=>!photo.is_primary&&setPrimary(photo.id)}>
              <img src={photo.photo_url} alt="" style={{ width:"100%", height:90, objectFit:"cover", display:"block" }}/>
              {photo.is_primary&&(
                <div style={{ position:"absolute", bottom:0, left:0, right:0, background:"rgba(230,130,30,0.9)", fontSize:9, fontWeight:700, color:"#fff", textAlign:"center", padding:"3px" }}>
                  COVER
                </div>
              )}
              <button
                onClick={e=>{ e.stopPropagation(); deletePhoto(photo) }}
                style={{ position:"absolute", top:4, right:4, background:"rgba(0,0,0,0.7)", border:"none", borderRadius:"50%", color:"#fff", width:20, height:20, fontSize:12, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", lineHeight:1 }}>
                ├ù
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { useState, useEffect } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import toast from "react-hot-toast"

export default function SellerProfile({ sellerId, onClose, onSelectListing }) {
  const { user } = useAuth()
  const [seller, setSeller] = useState(null)
  const [listings, setListings] = useState([])
  const [reviews, setReviews] = useState([])
  const [loading, setLoading] = useState(true)
  const [tab, setTab] = useState("listings")

  useEffect(() => { if (sellerId) load() }, [sellerId])

  async function load() {
    setLoading(true)
    try {
      const [{ data: sellerData }, { data: listingsData }, { data: reviewsData }] = await Promise.all([
        supabase.from("profiles").select("id,first_name,last_name,avatar_url,is_verified,marketplace_rating,marketplace_review_count,created_at,city").eq("id", sellerId).single(),
        supabase.from("marketplace_listings").select("*, marketplace_photos(photo_url,is_primary)").eq("seller_id", sellerId).eq("status","active").order("created_at", { ascending:false }),
        supabase.from("marketplace_reviews").select("*, reviewer:profiles!marketplace_reviews_reviewer_id_fkey(first_name,last_name,avatar_url)").eq("seller_id", sellerId).order("created_at", { ascending:false })
      ])
      setSeller(sellerData)
      setListings((listingsData||[]).map(l=>({...l, primary_photo:l.marketplace_photos?.find(p=>p.is_primary)?.photo_url || l.marketplace_photos?.[0]?.photo_url})))
      setReviews(reviewsData||[])
    } catch(e) { toast.error("Failed to load seller profile") }
    finally { setLoading(false) }
  }

  if (!sellerId) return null

  return (
    <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.7)", zIndex:200, display:"flex", alignItems:"flex-end", justifyContent:"center" }}
      onClick={e=>{ if(e.target===e.currentTarget) onClose() }}>
      <div style={{ background:"#fff", borderRadius:"20px 20px 0 0", width:"100%", maxWidth:600, maxHeight:"90vh", display:"flex", flexDirection:"column", overflow:"hidden" }}>
        {/* Header */}
        <div style={{ padding:"1.25rem", borderBottom:"1px solid #eee", display:"flex", alignItems:"center", justifyContent:"space-between" }}>
          <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800 }}>Seller Profile</div>
          <button onClick={onClose} style={{ background:"#f5f5f5", border:"none", borderRadius:"50%", width:32, height:32, cursor:"pointer", fontSize:18 }}>├ù</button>
        </div>

        {loading ? (
          <div style={{ padding:"3rem", textAlign:"center", color:"#888" }}>Loading...</div>
        ) : (
          <div style={{ flex:1, overflowY:"auto" }}>
            {/* Seller info */}
            <div style={{ padding:"1.25rem", borderBottom:"1px solid #eee" }}>
              <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:12 }}>
                <div style={{ width:56, height:56, borderRadius:"50%", background:"#fff8f0", border:"2px solid #e6821e40", display:"flex", alignItems:"center", justifyContent:"center", fontSize:22, fontWeight:800, color:"#e6821e", flexShrink:0 }}>
                  {seller?.avatar_url ? <img src={seller.avatar_url} style={{ width:"100%", height:"100%", borderRadius:"50%", objectFit:"cover" }}/> : (seller?.first_name?.[0]||"S")}
                </div>
                <div>
                  <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800 }}>
                    {seller?.first_name} {seller?.last_name}
                    {seller?.is_verified && <span style={{ marginLeft:6, fontSize:12, color:"#1d9e75" }}>Γ£ô Verified</span>}
                  </div>
                  <div style={{ fontSize:12, color:"#888" }}>{seller?.city} ┬╖ Member since {new Date(seller?.created_at).getFullYear()}</div>
                </div>
              </div>
              <div style={{ display:"flex", gap:16 }}>
                <div style={{ textAlign:"center" }}>
                  <div style={{ fontFamily:"Syne", fontSize:20, fontWeight:800, color:"#e6821e" }}>{listings.length}</div>
                  <div style={{ fontSize:11, color:"#888" }}>Listings</div>
                </div>
                <div style={{ textAlign:"center" }}>
                  <div style={{ fontFamily:"Syne", fontSize:20, fontWeight:800, color:"#e6821e" }}>{seller?.marketplace_rating > 0 ? `Γ¡É ${Number(seller?.marketplace_rating).toFixed(1)}` : "ΓÇö"}</div>
                  <div style={{ fontSize:11, color:"#888" }}>{seller?.marketplace_review_count||0} reviews</div>
                </div>
              </div>
            </div>

            {/* Tabs */}
            <div style={{ display:"flex", gap:0, padding:"0 1rem", borderBottom:"1px solid #eee" }}>
              {[{k:"listings",l:`Listings (${listings.length})`},{k:"reviews",l:`Reviews (${reviews.length})`}].map(t=>(
                <button key={t.k} onClick={()=>setTab(t.k)}
                  style={{ padding:"12px 16px", border:"none", background:"none", fontSize:13, fontWeight:tab===t.k?700:400, color:tab===t.k?"#e6821e":"#888", borderBottom:tab===t.k?"2px solid #e6821e":"2px solid transparent", cursor:"pointer" }}>
                  {t.l}
                </button>
              ))}
            </div>

            {/* Listings tab */}
            {tab==="listings" && (
              <div style={{ padding:"1rem", display:"grid", gridTemplateColumns:"1fr 1fr", gap:10 }}>
                {listings.length === 0 ? (
                  <div style={{ gridColumn:"1/-1", textAlign:"center", padding:"2rem", color:"#888" }}>No active listings</div>
                ) : listings.map(l=>(
                  <div key={l.id} onClick={()=>{ onSelectListing(l); onClose() }}
                    style={{ background:"#fff", border:"1px solid #eee", borderRadius:10, overflow:"hidden", cursor:"pointer" }}>
                    <div style={{ height:100, background:"#f5f5f5", display:"flex", alignItems:"center", justifyContent:"center" }}>
                      {l.primary_photo ? <img src={l.primary_photo} alt={l.title} style={{ width:"100%", height:"100%", objectFit:"cover" }}/> : <div style={{ fontSize:32 }}>{l.listing_type==="vehicle"?"≡ƒÜù":"≡ƒöº"}</div>}
                    </div>
                    <div style={{ padding:"0.5rem" }}>
                      <div style={{ fontSize:12, fontWeight:700, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{l.title}</div>
                      <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:800, color:"#e6821e" }}>KES {Number(l.price).toLocaleString()}</div>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {/* Reviews tab */}
            {tab==="reviews" && (
              <div style={{ padding:"1rem" }}>
                {reviews.length === 0 ? (
                  <div style={{ textAlign:"center", padding:"2rem", color:"#888" }}>No reviews yet</div>
                ) : reviews.map(r=>(
                  <div key={r.id} style={{ background:"#f9f9f9", borderRadius:10, padding:"1rem", marginBottom:10 }}>
                    <div style={{ display:"flex", justifyContent:"space-between", marginBottom:6 }}>
                      <div style={{ fontSize:13, fontWeight:600 }}>{r.reviewer?.first_name} {r.reviewer?.last_name?.[0]}.</div>
                      <div style={{ fontSize:13, color:"#e6821e" }}>{"Γ¡É".repeat(r.rating)}</div>
                    </div>
                    {r.review_text && <div style={{ fontSize:13, color:"#555", lineHeight:1.5 }}>{r.review_text}</div>}
                    <div style={{ fontSize:11, color:"#bbb", marginTop:6 }}>{new Date(r.created_at).toLocaleDateString()}</div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

import { useState } from "react"
import { supabase } from "../../lib/supabase"
import { validateFile, sanitizeFilePath } from "../../lib/uploadValidation"
import { useAuth } from "../../contexts/AuthContext"
import toast from "react-hot-toast"

export default function VideoUpload({ listingId, onUploaded }) {
  const { user } = useAuth()
  const [uploading, setUploading] = useState(false)
  const [uploadProgress, setUploadProgress] = useState(0)
  const [video, setVideo] = useState(null)
  const [dragOver, setDragOver] = useState(false)

  async function uploadVideo(file) {
    const _v = validateFile(file, "video")
    if (!_v.valid) { toast.error(_v.error); return }

    if (!file) return
    if (!file.type.startsWith("video/")) return toast.error("Please upload a video file")
    setUploading(true)
    setUploadProgress(0)
    try {
      const ext = file.name.split(".").pop()
      const path = `${user.id}/${listingId}/video-${Date.now()}.${ext}`
      const { data: { session } } = await supabase.auth.getSession()
      await new Promise((resolve, reject) => {
        const xhr = new XMLHttpRequest()
        xhr.open("POST", `${import.meta.env.VITE_SUPABASE_URL || "https://gcnefnqtjxtqbhynyoxe.supabase.co"}/storage/v1/object/marketplace/${path}`)
        xhr.setRequestHeader("Authorization", `Bearer ${session?.access_token}`)
        xhr.setRequestHeader("x-upsert", "true")
        xhr.upload.onprogress = (evt) => {
          if (evt.lengthComputable) setUploadProgress(Math.round((evt.loaded / evt.total) * 100))
        }
        xhr.onload = () => xhr.status >= 200 && xhr.status < 300 ? resolve() : reject(new Error("Upload failed: " + xhr.responseText))
        xhr.onerror = () => reject(new Error("Network error during upload"))
        xhr.send(file)
      })
      const { data } = supabase.storage.from("marketplace").getPublicUrl(path)
      await supabase.from("marketplace_listings").update({ video_url: data.publicUrl }).eq("id", listingId)
      setVideo(data.publicUrl)
      toast.success("Video uploaded!")
      if (onUploaded) onUploaded(data.publicUrl)
    } catch(e) {
      toast.error("Upload failed: " + e.message)
    } finally {
      setUploading(false)
      setUploadProgress(0)
    }
  }

  return (
    <div style={{ marginTop:16 }}>
      <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:700, color:"#000", marginBottom:6 }}>Add a video ≡ƒÄÑ <span style={{ fontSize:11, color:"#888", fontWeight:400 }}>(optional, max 200MB)</span></div>
      <div
        onDragOver={e=>{ e.preventDefault(); setDragOver(true) }}
        onDragLeave={()=>setDragOver(false)}
        onDrop={e=>{ e.preventDefault(); setDragOver(false); uploadVideo(e.dataTransfer.files[0]) }}
        style={{ border:`2px dashed ${dragOver?"#e6821e":"#dddddd"}`, borderRadius:10, padding:"1.5rem", textAlign:"center", background:dragOver?"#fff8f0":"#fafafa", cursor:"pointer" }}
        onClick={()=>document.getElementById("video-upload-input").click()}>
        {uploading ? (
          <div style={{ color:"#888", fontSize:13 }}>{`ΓÅ│ Uploading... ${uploadProgress}%`}</div>
        ) : video ? (
          <div>
            <video src={video} controls style={{ width:"100%", maxHeight:200, borderRadius:8, marginBottom:8 }}/>
            <div style={{ fontSize:11, color:"#1d9e75", fontWeight:600 }}>Γ£ô Video uploaded</div>
            <div style={{ fontSize:11, color:"#888", marginTop:4, cursor:"pointer" }} onClick={e=>{ e.stopPropagation(); setVideo(null) }}>Replace video</div>
          </div>
        ) : (
          <div>
            <div style={{ fontSize:32, marginBottom:8 }}>≡ƒÄÑ</div>
            <div style={{ fontSize:13, color:"#555", marginBottom:4 }}>Drag & drop a video or tap to browse</div>
            <div style={{ fontSize:11, color:"#888" }}>MP4, MOV, AVI ΓÇó Max 200MB</div>
          </div>
        )}
        <input id="video-upload-input" type="file" accept="video/*" style={{ display:"none" }}
          onChange={e=>uploadVideo(e.target.files[0])}/>
      </div>
    </div>
  )
}

import { useState, useEffect, useRef } from "react"
import { useMechanicAuth } from "../../contexts/MechanicAuthContext"
import { supabase } from "../../lib/supabase"
import { getCurrentPosition } from "../../lib/geolocation"
import { openExternal } from "../../lib/openExternal"
import toast from "react-hot-toast"
import AIAssistant from "../shared/AIAssistant"
import ChatWindow from "../shared/ChatWindow"

const STATUS_COLOR = {
  pending: "#e6821e",
  confirmed: "#378add",
  in_progress: "#8b5cf6",
  completed: "#1d9e75",
  cancelled: "#e24b4a"
}

const URGENCY_COLOR = { normal:"#888", urgent:"#e6821e", critical:"#e24b4a" }

export default function MechanicDashboard() {
  const { mechanic, setMechanic, logoutMechanic } = useMechanicAuth()
  const [tab, setTab] = useState("jobs")
  const [jobs, setJobs] = useState([])
  const [history, setHistory] = useState([])
  const [selectedHistoryJob, setSelectedHistoryJob] = useState(null)
  const [loading, setLoading] = useState(true)
  const [activeJob, setActiveJob] = useState(null)
  const [sharing, setSharing] = useState(false)
  const [available, setAvailable] = useState(mechanic?.is_available ?? true)
  const [partsCarried, setPartsCarried] = useState(mechanic?.parts_carried||[])
  const [carriesParts, setCarriesParts] = useState(mechanic?.carries_parts||false)
  const [locationInterval, setLocationInterval] = useState(null)
  const [uploadingPhoto, setUploadingPhoto] = useState(null)
  const [sosLoading, setSosLoading] = useState(false)
  const [jobNotes, setJobNotes] = useState({})
  const [savingNotes, setSavingNotes] = useState(null)
  const [partsRequest, setPartsRequest] = useState(null)
  const [arrivedJob, setArrivedJob] = useState(null)
  const [otpInput, setOtpInput] = useState({})
  const [otpVerifying, setOtpVerifying] = useState(null)
  const [showCCCParts, setShowCCCParts] = useState(null)
  const [cccInventory, setCCCInventory] = useState([])
  const [cccSelectedPart, setCCCSelectedPart] = useState(null)
  const [cccPartQty, setCCCPartQty] = useState(1)
  const [requestingCCCPart, setRequestingCCCPart] = useState(false)
  const [partForm, setPartForm] = useState({ part_name:"", quantity:1, urgency:"normal", notes:"" })
  const [jobTimers, setJobTimers] = useState({})
  const [timerRef, setTimerRef] = useState(null)
  const [earnings, setEarnings] = useState({ today:0, week:0, month:0, total_jobs:0 })
  const [expandedJob, setExpandedJob] = useState(null)
  const [photos, setPhotos] = useState([])
  const [partsRequests, setPartsRequests] = useState([])
  const [photoFilter, setPhotoFilter] = useState("all")
  const [viewPhoto, setViewPhoto] = useState(null)
  const [docs, setDocs] = useState([])
  const [uploadingDoc, setUploadingDoc] = useState(null)
  const [chatJob, setChatJob] = useState(null)
  const [showGarageChat, setShowGarageChat] = useState(false)
  const [menuOpen, setMenuOpen] = useState(false)
  const [perfStats, setPerfStats] = useState({ avg_rating:0, total_ratings:0, avg_response_mins:0, completion_rate:0 })

  useEffect(() => {
    if (!mechanic) return
    load()
    loadPartsRequests()
    loadHistory()
    loadEarnings()
    loadPerfStats()
    loadDocs()
    loadPhotos()
    const sub = supabase.channel("mechanic-jobs-" + mechanic.mechanic_id)
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"bookings",
        filter:"assigned_mechanic_id=eq." + mechanic.mechanic_id }, payload => {
        load()
        toast.success("New job assigned: " + (payload.new.service_name||"Service") + " ≡ƒöº", { duration:10000 })
      })
      .on("postgres_changes", { event:"UPDATE", schema:"public", table:"bookings",
        filter:"assigned_mechanic_id=eq." + mechanic.mechanic_id }, payload => { load(); if(payload.new.status==="confirmed"&&payload.new.assigned_mechanic_id) toast.success("≡ƒÜ¿ GO Service job assigned! Check your jobs.", { duration:10000 }) })
      .subscribe()
    return () => { supabase.removeChannel(sub); stopSharing() }
  }, [mechanic])

  async function generateArrivalOTP(jobId) {
    try {
      await supabase.functions.invoke("go-generate-otp", { body: { booking_id: jobId } })
      setArrivedJob(jobId)
      toast.success("OTP sent to customer! Ask them for the code.")
    } catch(e) { toast.error(e.message) }
  }
  async function verifyArrivalOTP(job) {
    const entered = otpInput[job.id]
    if(!entered||entered.length!==4) return toast.error("Enter 4-digit OTP")
    setOtpVerifying(job.id)
    try {
      const { data, error } = await supabase.rpc("verify_mechanic_arrival_otp", { p_booking_id: job.id, p_otp: entered })
      if(error) throw error
      if(!data?.success) throw new Error(data?.error||"Verification failed")
      await supabase.functions.invoke("go-release-escrow", { body: { booking_id: job.id } })
      await updateJobStatus(job.id, "in-progress")
      setArrivedJob(null)
      setOtpInput(prev=>({...prev,[job.id]:""}))
      toast.success("OTP verified! Job started. ≡ƒÜÇ")
    } catch(e) { toast.error(e.message) }
    finally { setOtpVerifying(null) }
  }
  async function loadCCCInventory(lat, lng) {
    const { data } = await supabase.from("inventory").select("*, profiles!inventory_provider_id_fkey(first_name,last_name,business_name,latitude,longitude)").eq("is_active",true).gt("stock_quantity",0)
    if(lat && lng && data) {
      data.forEach(i=>{ const p=i.profiles; if(p?.latitude&&p?.longitude){const dLat=(p.latitude-lat)*Math.PI/180;const dLng=(p.longitude-lng)*Math.PI/180;const a=Math.sin(dLat/2)**2+Math.cos(lat*Math.PI/180)*Math.cos(p.latitude*Math.PI/180)*Math.sin(dLng/2)**2;i._distance=6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))}else{i._distance=999}})
      data.sort((a,b)=>a._distance-b._distance)
    }
    setCCCInventory(data||[])
  }
  async function requestCCCPart(job) {
    if(!cccSelectedPart) return toast.error("Select a part")
    setRequestingCCCPart(true)
    try {
      const part = cccInventory.find(i=>i.id===cccSelectedPart)
      if(!part) throw new Error("Part not found")
      const total = part.price * cccPartQty
      await supabase.from("go_parts_requests").insert({
        booking_id: job.id, mechanic_id: mechanic.id, inventory_id: part.id,
        provider_id: part.provider_id, quantity: cccPartQty, unit_price: part.price,
        total_amount: total, customer_id: job.customer_id,
        delivery_location_address: job.emergency_location_address,
        delivery_location_lat: job.emergency_location_lat, delivery_location_lng: job.emergency_location_lng, status: "pending"
      })
      await supabase.from("notifications").insert([
        { user_id: part.provider_id, title: "Part request!", message: "Mechanic needs "+part.name+" x"+cccPartQty+" at "+job.emergency_location_address, type: "info" },
        { user_id: job.customer_id, title: "Mechanic needs a part", message: "Your mechanic needs "+part.name+" ΓÇö KES "+total, type: "info" }
      ])
      toast.success("Part request sent!")
      setShowCCCParts(null); setCCCSelectedPart(null); setCCCPartQty(1)
    } catch(e) { toast.error(e.message) }
    finally { setRequestingCCCPart(false) }
  }
  async function load() {
    setLoading(true)
    const { data } = await supabase.rpc("get_mechanic_jobs", { p_mechanic_id: mechanic.mechanic_id })
    // RPC bypasses RLS since mechanics use PIN auth not Supabase auth



    setJobs(data||[])
    const active = (data||[]).find(j=>j.status==="in-progress")
    if (active) { setActiveJob(active); if (!timerRef) startJobTimer(active.id, active.mechanic_started_at||active.updated_at) }
    setLoading(false)
  }

  async function loadHistory() {
    const { data } = await supabase.rpc("get_mechanic_history", { p_mechanic_id: mechanic.mechanic_id })
    setHistory(data||[])
  }

  async function loadPhotos() {
    const { data, error: photoErr } = await supabase.from("bookings")
      .select("id, service_name, booking_date, before_photo_url, after_photo_url")
      .eq("assigned_mechanic_id", mechanic.mechanic_id)
      .not("before_photo_url", "is", null)
      .order("created_at", { ascending: false })
      .limit(50)
    if (photoErr) console.error("loadPhotos error:", photoErr.message, photoErr.details, photoErr.hint)
    const { data: data2 } = await supabase.from("bookings")
      .select("id, service_name, booking_date, before_photo_url, after_photo_url")
      .eq("assigned_mechanic_id", mechanic.mechanic_id)
      .not("after_photo_url", "is", null)
      .order("created_at", { ascending: false })
      .limit(50)
    const allPhotos = []
    ;(data||[]).forEach(b => allPhotos.push({ url:b.before_photo_url, type:"Before", job:b }))
    ;(data2||[]).forEach(b => allPhotos.push({ url:b.after_photo_url, type:"After", job:b }))
    setPhotos(allPhotos)
  }

  async function loadPartsRequests() {
    const { data } = await supabase.from("mechanic_parts_requests")
      .select("*")
      .eq("mechanic_id", mechanic.mechanic_id)
      .order("created_at", { ascending: false })
      .limit(20)
    setPartsRequests(data||[])
  }

  async function loadDocs() {
    const { data } = await supabase.from("driver_documents")
      .select("*")
      .eq("driver_id", mechanic.mechanic_id)
    setDocs(data||[])
  }

  async function uploadDoc(docType, label) {
    const input = document.createElement("input")
    input.type = "file"
    input.accept = "image/*,.pdf"
    input.onchange = async(e) => {
      const file = e.target.files[0]
      if (!file) return
      if (file.size > 5*1024*1024) return toast.error("File must be under 5MB")
      setUploadingDoc(docType)
      try {
        const ext = file.name.split(".").pop()
        const path = "mechanic-docs/" + mechanic.mechanic_id + "/" + docType + "-" + Date.now() + "." + ext
        // Try upload with public bucket
        const { error } = await supabase.storage.from("provider-photos").upload(path, file, { upsert:true, contentType: file.type })
        if (error) throw error
        const { data } = supabase.storage.from("provider-photos").getPublicUrl(path)
        // Upsert document record
        await supabase.from("driver_documents").upsert({
          driver_id: mechanic.mechanic_id,
          type: docType,
          document_url: data.publicUrl,
          status: "pending",
          file_name: file.name
        }, { onConflict: "driver_id,type" })
        toast.success(label + " uploaded! Pending verification.")
        loadDocs()
      } catch(err) { toast.error("Upload failed: " + err.message) }
      finally { setUploadingDoc(null) }
    }
    input.click()
  }

  async function loadPerfStats() {
    try {
      const { data } = await supabase.from("bookings")
        .select("mechanic_rating, mechanic_started_at, created_at, status")
        .eq("assigned_mechanic_id", mechanic.mechanic_id)
      if (!data) return
      const rated = data.filter(b=>b.mechanic_rating>0)
      const completed = data.filter(b=>b.status==="completed")
      const avgRating = rated.length ? rated.reduce((s,b)=>s+b.mechanic_rating,0)/rated.length : 0
      const completionRate = data.length ? (completed.length/data.length)*100 : 0
      setPerfStats({
        avg_rating: Math.round(avgRating*10)/10,
        total_ratings: rated.length,
        completion_rate: Math.round(completionRate),
      })
    } catch(e) { console.warn("Perf stats error:", e.message) }
  }

  async function loadEarnings() {
    const { data } = await supabase.from("bookings")
      .select("provider_earnings, created_at")
      .eq("assigned_mechanic_id", mechanic.mechanic_id)
      .eq("status", "completed")
    if (!data) return
    const now = new Date()
    const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate()).toISOString()
    const weekStart = new Date(now.getFullYear(), now.getMonth(), now.getDate()-7).toISOString()
    const monthStart = new Date(now.getFullYear(), now.getMonth(), 1).toISOString()
    setEarnings({
      today: data.filter(b=>b.created_at>=todayStart).reduce((s,b)=>s+(mechanic.commission_type==="fixed" ? Number(mechanic.commission_rate||0) : Number(b.provider_earnings||0)*(mechanic.commission_rate||0.15)),0),
      week: data.filter(b=>b.created_at>=weekStart).reduce((s,b)=>s+(mechanic.commission_type==="fixed" ? Number(mechanic.commission_rate||0) : Number(b.provider_earnings||0)*(mechanic.commission_rate||0.15)),0),
      month: data.filter(b=>b.created_at>=monthStart).reduce((s,b)=>s+(mechanic.commission_type==="fixed" ? Number(mechanic.commission_rate||0) : Number(b.provider_earnings||0)*(mechanic.commission_rate||0.15)),0),
      total_jobs: data.length
    })
  }

  async function updateJobStatus(jobId, status) {
    await supabase.rpc("mechanic_update_job_status", { p_booking_id: jobId, p_status: status, p_mechanic_id: mechanic.mechanic_id })
    if (status === "in-progress") {
      const startedAt = new Date().toISOString()
      setActiveJob(jobs.find(j=>j.id===jobId))
      startSharing()
      startJobTimer(jobId, startedAt)
    }
    if (status === "completed") {
      const job = jobs.find(j=>j.id===jobId)
      const isGoServiceAwaitingPayment = job?.service_category==="go_service"
      if(job?.customer_id) {
        if(isGoServiceAwaitingPayment) {
          await supabase.functions.invoke("go-request-service-payment", { body: { booking_id: jobId } })
        } else {
          await supabase.from("notifications").insert({
            user_id: job.customer_id,
            title: "Service complete! Pay now ≡ƒÆ│",
            message: `Your ${job.service_name} is complete. Please pay KES ${Number(job.total_amount||0).toLocaleString()} service fee in the app.`,
            type: "success"
          })
        }
      }
      // Keep the job card visible for GO Service jobs awaiting the customer's payment -
      // only clear it once the fee is genuinely confirmed paid (job leaves the active list
      // entirely once get_mechanic_jobs stops returning it, i.e. go_service_fee_paid becomes true)
      if (!isGoServiceAwaitingPayment) {
        setActiveJob(null)
        stopSharing()
        if (timerRef) { clearInterval(timerRef); setTimerRef(null) }
      }
      loadEarnings()
      loadHistory()
    }
    toast.success("Job " + status.replace("_"," "))
    load()
  }
  async function toggleAvailability() {
    const newVal = !available
    await supabase.from("mechanics").update({ is_available: newVal }).eq("id", mechanic.mechanic_id)
    setAvailable(newVal)
    toast.success(newVal ? "You are now available" : "You are now unavailable")
  }

  async function startSharing() {
    setSharing(true)
    const interval = setInterval(async() => {
      try {
        const pos = await getCurrentPosition()
        await supabase.from("mechanics").update({
          current_latitude: pos.latitude,
          current_longitude: pos.longitude,
          last_seen: new Date().toISOString()
        }).eq("id", mechanic.mechanic_id)
        if (activeJob) {
          await supabase.from("mechanic_location_history").insert({
            mechanic_id: mechanic.mechanic_id,
            booking_id: activeJob.id,
            latitude: pos.latitude,
            longitude: pos.longitude,
          })
        }
      } catch(e) { console.warn("Location:", e.message) }
    }, 15000)
    setLocationInterval(interval)
  }

  function stopSharing() {
    if (locationInterval) { clearInterval(locationInterval); setLocationInterval(null) }
    setSharing(false)
  }

  function startJobTimer(jobId, startedAt) {
    if (timerRef) clearInterval(timerRef)
    const interval = setInterval(() => {
      const elapsed = Math.floor((Date.now() - new Date(startedAt).getTime()) / 1000)
      setJobTimers(prev => ({ ...prev, [jobId]: elapsed }))
    }, 1000)
    setTimerRef(interval)
  }

  function formatTimer(seconds) {
    if (!seconds) return "00:00"
    const h = Math.floor(seconds/3600)
    const m = Math.floor((seconds%3600)/60)
    const s = seconds%60
    if (h > 0) return h + "h " + String(m).padStart(2,"0") + "m"
    return String(m).padStart(2,"0") + ":" + String(s).padStart(2,"0")
  }

  function navigateToCustomer(job) {
    if (job.emergency_location_lat && job.emergency_location_lng)
      openExternal("https://www.google.com/maps/dir/?api=1&destination=" + job.emergency_location_lat + "," + job.emergency_location_lng)
    else toast.error("Customer location not available")
  }

  async function callCustomer(job) {
    // get_mechanic_jobs only returns raw bookings columns - it never joins the customer's
    // phone number, so job.profile_sensitive was always undefined and this never actually
    // worked. Fetch it fresh via a verified RPC instead.
    const { data: phone, error } = await supabase.rpc("mechanic_get_customer_phone", { p_mechanic_id: mechanic.mechanic_id, p_booking_id: job.id })
    if (error || !phone) { toast.error("Customer phone not available"); return }
    openExternal("tel:" + phone)
  }

  async function saveJobNotes(jobId) {
    setSavingNotes(jobId)
    try {
      await supabase.from("bookings").update({ mechanic_notes: jobNotes[jobId] }).eq("id", jobId)
      toast.success("Notes saved!")
    } catch(e) { toast.error("Failed") }
    finally { setSavingNotes(null) }
  }

  async function submitPartsRequest(job) {
    if (!partForm.part_name.trim()) return toast.error("Enter part name")
    try {
      await supabase.from("mechanic_parts_requests").insert({
        booking_id: job.id,
        mechanic_id: mechanic.mechanic_id,
        provider_id: mechanic.provider_id,
        part_name: partForm.part_name,
        quantity: partForm.quantity,
        urgency: partForm.urgency,
        notes: partForm.notes
      })
      await supabase.from("notifications").insert({
        user_id: mechanic.provider_id,
        title: "Parts request ≡ƒö⌐",
        message: mechanic.mechanic_name + " needs " + partForm.quantity + "x " + partForm.part_name + " (Urgency: " + partForm.urgency + ")",
        type: "info"
      })
      toast.success("Parts request sent!")
      setPartsRequest(null)
      setPartForm({ part_name:"", quantity:1, urgency:"normal", notes:"" })
    } catch(e) { toast.error("Failed: " + e.message) }
  }

  async function uploadJobPhoto(jobId, type) {
    const input = document.createElement("input")
    input.type = "file"
    input.accept = "image/*"
    input.onchange = async(e) => {
      const file = e.target.files[0]
      if (!file) return
      setUploadingPhoto(jobId + type)
      try {
        const ext = file.name.split(".").pop()
        const path = "job-photos/" + mechanic.mechanic_id + "/" + jobId + "-" + type + "-" + Date.now() + "." + ext
        const { error } = await supabase.storage.from("provider-photos").upload(path, file, { upsert:true, contentType: file.type })
        if (error) throw error
        const { data } = supabase.storage.from("provider-photos").getPublicUrl(path)
        await supabase.from("bookings").update({
          [type === "before" ? "before_photo_url" : "after_photo_url"]: data.publicUrl
        }).eq("id", jobId)
        toast.success(type + " photo uploaded!")
      } catch(err) { toast.error("Upload failed: " + err.message) }
      finally { setUploadingPhoto(null) }
    }
    input.click()
  }

  async function sendSOS() {
    setSosLoading(true)
    try {
      const pos = await getCurrentPosition().catch(() => null)
      await supabase.from("emergency_alerts").insert({
        user_id: null,
        user_name: mechanic.mechanic_name,
        user_role: "mechanic",
        latitude: pos?.latitude || null,
        longitude: pos?.longitude || null,
        status: "active"
      })
      toast.success("SOS alert sent to admin!")
    } catch(err) { toast.error("SOS failed") }
    finally { setSosLoading(false) }
  }

  const TABS = [
    { k:"jobs", l:"Jobs", icon:"≡ƒöº" },
    { k:"earnings", l:"Earnings", icon:"≡ƒÆ░" },
    { k:"stats", l:"Stats", icon:"Γ¡É" },
    { k:"history", l:"History", icon:"≡ƒôï" },
    { k:"photos", l:"Photos", icon:"≡ƒô╕" },
    { k:"manual", l:"Manual", icon:"≡ƒôû" },
    { k:"parts", l:"Parts", icon:"≡ƒö⌐" },
    { k:"docs", l:"Docs", icon:"≡ƒôä" },
    { k:"sos", l:"SOS", icon:"≡ƒåÿ" },
  ]

  if (loading && jobs.length === 0) return (
    <div style={{ minHeight:"100vh", display:"flex", alignItems:"center", justifyContent:"center", background:"#f8f8f8", fontFamily:"DM Sans,sans-serif" }}>
      <div style={{ textAlign:"center" }}>
        <div style={{ fontSize:48, marginBottom:12 }}>≡ƒæ¿ΓÇì≡ƒöº</div>
        <div style={{ fontSize:14, color:"#888" }}>Loading your jobs...</div>
      </div>
    </div>
  )

  return (
    <div style={{ minHeight:"100vh", background:"#f8f8f8", fontFamily:"DM Sans,sans-serif", maxWidth:500, margin:"0 auto" }}>

      {/* Header */}
