import useIsMobile from "../../lib/useIsMobile"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"

export default function ProviderAnalytics() {
  const isMobile = useIsMobile()
  const { user } = useAuth()
  const [bookings, setBookings] = useState([])
  const [reviews, setReviews] = useState([])
  const [loading, setLoading] = useState(true)

  useEffect(() => { if (user) load() }, [user])

  async function load() {
    const [{ data }, { data: revs }] = await Promise.all([
      supabase.from("bookings")
        .select("*").eq("provider_id", user.id).eq("is_archived", false).order("created_at", { ascending:false }),
      supabase.from("reviews")
        .select("provider_rating, provider_response, created_at").eq("provider_id", user.id).eq("is_hidden", false)
    ])
    setBookings(data||[])
    setReviews(revs||[])
    setLoading(false)
  }

  const completed = bookings.filter(b=>b.status==="completed")
  const cancelled = bookings.filter(b=>b.status==="cancelled")
  const completionRate = bookings.length>0 ? Math.round((completed.length/bookings.length)*100) : 0

  // Service performance
  const byService = bookings.reduce((acc,b) => {
    if (!acc[b.service_name]) acc[b.service_name] = { name:b.service_name, total:0, completed:0, revenue:0 }
    acc[b.service_name].total++
    if (b.status==="completed") { acc[b.service_name].completed++; acc[b.service_name].revenue += Number(b.provider_earnings||0) }
    return acc
  }, {})
  const services = Object.values(byService).sort((a,b)=>b.total-a.total)

  // Customer retention
  const customerBookings = bookings.reduce((acc,b) => {
    if (!acc[b.customer_id]) acc[b.customer_id] = 0
    acc[b.customer_id]++
    return acc
  }, {})
  const returning = Object.values(customerBookings).filter(c=>c>1).length
  const total = Object.keys(customerBookings).length
  const retentionRate = total>0 ? Math.round((returning/total)*100) : 0

  // Rating & responsiveness
  const avgRating = reviews.length>0 ? (reviews.reduce((sum,r)=>sum+(r.provider_rating||0),0)/reviews.length).toFixed(1) : null
  const respondedReviews = reviews.filter(r=>r.provider_response && r.provider_response.trim()!=="").length
  const responseRate = reviews.length>0 ? Math.round((respondedReviews/reviews.length)*100) : 0

  // Monthly revenue
  const byMonth = completed.reduce((acc,b) => {
    const month = b.booking_date?.slice(0,7)
    if (!month) return acc
    acc[month] = (acc[month]||0) + Number(b.provider_earnings||0)
    return acc
  }, {})
  const months = Object.entries(byMonth).sort((a,b)=>b[0].localeCompare(a[0])).slice(0,6)
  const maxRev = Math.max(...months.map(([,v])=>v), 1)

  if (loading) return <div style={{ color:"#777777", fontSize:13 }}>Loading...</div>

  return (
    <div>
      <div style={{ display:"grid", gridTemplateColumns:isMobile?"repeat(2,1fr)":"repeat(5,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Completion rate", value:`${completionRate}%`, color:completionRate>=80?"#1d9e75":completionRate>=50?"#e6821e":"#e24b4a" },
          { label:"Avg rating", value:avgRating?`Γÿà ${avgRating}`:"ΓÇö", color:avgRating>=4?"#1d9e75":avgRating>=3?"#e6821e":avgRating?"#e24b4a":undefined },
          { label:"Review response rate", value:`${responseRate}%`, color:responseRate>=70?"#1d9e75":responseRate>=30?"#e6821e":"#e24b4a" },
          { label:"Returning customers", value:`${retentionRate}%`, color:"#378add" },
          { label:"Cancelled bookings", value:cancelled.length, color:cancelled.length>0?"#e24b4a":undefined },
        ].map(s=>(
          <div key={s.label} style={{ background:"#ffffff", borderRadius:10, padding:"1rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontSize:11, color:"#777777", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:6 }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:22, fontWeight:800, color:s.color||"#000000" }}>{s.value}</div>
          </div>
        ))}
      </div>

      {months.length>0&&(
        <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem", marginBottom:"1.5rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:"1rem", color:"#000000" }}>Revenue trend</div>
          <div style={{ display:"flex", gap:8, alignItems:"flex-end", height:120 }}>
            {months.reverse().map(([month,rev])=>(
              <div key={month} style={{ flex:1, display:"flex", flexDirection:"column", alignItems:"center", gap:4 }}>
                <div style={{ fontSize:10, color:"#378add", fontWeight:600 }}>KES {rev.toFixed(0)}</div>
                <div style={{ width:"100%", background:"#378add", borderRadius:"4px 4px 0 0", height:`${Math.max(4,(rev/maxRev)*80)}px`, transition:"height 0.5s" }}/>
                <div style={{ fontSize:9, color:"#777777" }}>{new Date(month+"-01").toLocaleString("default",{month:"short"})}</div>
              </div>
            ))}
          </div>
        </div>
      )}

      <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:10, color:"#000000" }}>Service performance</div>
      {services.length===0&&<div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"1.5rem" }}>No bookings yet</div>}
      {services.map(s=>(
        <div key={s.name} style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:8 }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
            <div style={{ fontSize:13, fontWeight:500, color:"#000000" }}>{s.name}</div>
            <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#378add" }}>KES {s.revenue.toFixed(2)}</div>
          </div>
          <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:8 }}>
            {[
              { l:"Total bookings", v:s.total },
              { l:"Completed", v:s.completed },
              { l:"Rate", v:`${s.total>0?Math.round((s.completed/s.total)*100):0}%` },
            ].map(f=>(
              <div key={f.l}>
                <div style={{ fontSize:10, color:"#777777", textTransform:"uppercase" }}>{f.l}</div>
                <div style={{ fontSize:13, color:"#000000", marginTop:2 }}>{f.v}</div>
              </div>
            ))}
          </div>
          <div style={{ marginTop:8, height:4, background:"#f0f0f0", borderRadius:2, overflow:"hidden" }}>
            <div style={{ height:"100%", background:"#378add", borderRadius:2, width:`${s.total>0?Math.round((s.completed/s.total)*100):0}%`, transition:"width 0.5s" }}/>
          </div>
        </div>
      ))}

      <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginTop:"1.5rem", marginBottom:10, color:"#000000" }}>Customer summary</div>
      <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem" }}>
        {[
          { label:"Total customers", value:total },
          { label:"Returning customers", value:returning, color:"#1d9e75" },
          { label:"One-time customers", value:total-returning },
          { label:"Retention rate", value:`${retentionRate}%`, color:"#378add" },
        ].map(s=>(
          <div key={s.label} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", padding:"8px 0", borderBottom:"1px solid #eeeeee" }}>
            <div style={{ fontSize:13, color:"#555555" }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:s.color||"#000000" }}>{s.value}</div>
          </div>
        ))}
      </div>
    </div>
  )
}

import useIsMobile from "../../lib/useIsMobile"
import { useEffect, useState } from "react"
import { BookingsIcon, CloseIcon, RefreshIcon, SuccessIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import toast from "react-hot-toast"

const DAYS = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"]
const MONTHS = ["January","February","March","April","May","June","July","August","September","October","November","December"]

export default function ProviderAvailability() {
  const isMobile = useIsMobile()
  const { user } = useAuth()
  const [currentMonth, setCurrentMonth] = useState(new Date())
  const [availability, setAvailability] = useState({})
  const [bookingCounts, setBookingCounts] = useState({})
  const [selected, setSelected] = useState(null)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [form, setForm] = useState({ max_bookings:5, is_blocked:false, block_reason:"" })
  const [dateRange, setDateRange] = useState({ from:"", to:"", reason:"" })
  const [showRangeBlock, setShowRangeBlock] = useState(false)
  const [defaultMaxBookings, setDefaultMaxBookings] = useState(5)

  const year = currentMonth.getFullYear()
  const month = currentMonth.getMonth()
  const firstDay = new Date(year, month, 1).getDay()
  const daysInMonth = new Date(year, month + 1, 0).getDate()
  const monthStr = year + "-" + String(month+1).padStart(2,"0")

  useEffect(() => { if (user) load() }, [user, currentMonth])

  async function load() {
    const startDate = monthStr + "-01"
    const endDate = monthStr + "-" + String(daysInMonth).padStart(2,"0")
    const [{ data: avail }, { data: bookings }] = await Promise.all([
      supabase.from("provider_availability").select("*").eq("provider_id", user.id).gte("date", startDate).lte("date", endDate),
      supabase.from("bookings").select("booking_date").eq("provider_id", user.id).gte("booking_date", startDate).lte("booking_date", endDate).not("status", "eq", "cancelled").eq("is_archived", false)
    ])
    const availMap = {}
    ;(avail||[]).forEach(a => { availMap[a.date] = a })
    setAvailability(availMap)
    const countMap = {}
    ;(bookings||[]).forEach(b => { countMap[b.booking_date] = (countMap[b.booking_date]||0) + 1 })
    setBookingCounts(countMap)
    setLoading(false)
  }

  function getDateStr(day) {
    return monthStr + "-" + String(day).padStart(2,"0")
  }

  function getDayStatus(day) {
    const dateStr = getDateStr(day)
    const avail = availability[dateStr]
    const count = bookingCounts[dateStr] || 0
    const today = new Date(); today.setHours(0,0,0,0)
    const date = new Date(dateStr+"T00:00:00")
    const isPast = date < today
    if (isPast) return { type:"past", label:"", color:"#f0f0f0", textColor:"#bbb" }
    if (avail?.is_blocked) return { type:"blocked", label:"Blocked", color:"#fff5f5", textColor:"#e24b4a" }
    const max = avail?.max_bookings ?? defaultMaxBookings
    if (count >= max) return { type:"full", label:"Full", color:"#fff8f0", textColor:"#e6821e" }
    if (count > 0) return { type:"partial", label:count+"/"+max, color:"#f0fdf4", textColor:"#1d9e75" }
    return { type:"open", label:"Open", color:"#ffffff", textColor:"#888" }
  }

  function selectDay(day) {
    const dateStr = getDateStr(day)
    const today = new Date(); today.setHours(0,0,0,0)
    const date = new Date(dateStr+"T00:00:00")
    if (date < today) return
    setSelected(dateStr)
    const avail = availability[dateStr]
    setForm({ max_bookings:avail?.max_bookings??defaultMaxBookings, is_blocked:avail?.is_blocked??false, block_reason:avail?.block_reason??"" })
  }

  async function saveDay(e) {
    e.preventDefault()
    setSaving(true)
    try {
      const { error } = await supabase.from("provider_availability").upsert({
        provider_id: user.id, date: selected,
        max_bookings: form.is_blocked ? 0 : Number(form.max_bookings),
        is_blocked: form.is_blocked,
        block_reason: form.block_reason || null
      }, { onConflict:"provider_id,date" })
      if (error) throw error
      toast.success("Saved!")
      setSelected(null)
      load()
    } catch(err) { toast.error(err.message) }
    finally { setSaving(false) }
  }

  async function blockDateRange() {
    if (!dateRange.from || !dateRange.to) return toast.error("Select start and end dates")
    if (dateRange.from > dateRange.to) return toast.error("Start must be before end")
    setSaving(true)
    try {
      const dates = []
      const start = new Date(dateRange.from+"T00:00:00")
      const end = new Date(dateRange.to+"T00:00:00")
      const today = new Date(); today.setHours(0,0,0,0)
      for (let d = new Date(start); d <= end; d.setDate(d.getDate()+1)) {
        if (d >= today) dates.push(d.toISOString().split("T")[0])
      }
      for (const date of dates) {
        await supabase.from("provider_availability").upsert({ provider_id:user.id, date, is_blocked:true, block_reason:dateRange.reason||"Date range block", max_bookings:0 }, { onConflict:"provider_id,date" })
      }
      toast.success(dates.length + " days blocked")
      setDateRange({ from:"", to:"", reason:"" })
      setShowRangeBlock(false)
      load()
    } catch(e) { toast.error("Error blocking dates") }
    finally { setSaving(false) }
  }

  async function quickToggleBlock(dateStr) {
    const avail = availability[dateStr]
    await supabase.from("provider_availability").upsert({ provider_id:user.id, date:dateStr, is_blocked:!avail?.is_blocked, block_reason:avail?.is_blocked?null:"Blocked", max_bookings:avail?.is_blocked?5:0 }, { onConflict:"provider_id,date" })
    load()
  }

  async function bulkBlock(type) {
    setSaving(true)
    try {
      const today = new Date(); today.setHours(0,0,0,0)
      const dates = []
      for (let d=1; d<=daysInMonth; d++) {
        const dateStr = getDateStr(d)
        const date = new Date(dateStr+"T00:00:00")
        if (date < today) continue
        const dow = date.getDay()
        if (type==="weekends" && (dow===0||dow===6)) dates.push(dateStr)
        if (type==="all") dates.push(dateStr)
      }
      for (const date of dates) {
        await supabase.from("provider_availability").upsert({ provider_id:user.id, date, max_bookings:0, is_blocked:true, block_reason:type==="weekends"?"Weekend":"Blocked" }, { onConflict:"provider_id,date" })
      }
      toast.success(dates.length + " dates blocked")
      load()
    } catch(err) { toast.error(err.message) }
    finally { setSaving(false) }
  }

  async function clearMonth() {
    if (!confirm("Clear all availability settings for this month?")) return
    setSaving(true)
    await supabase.from("provider_availability").delete().eq("provider_id", user.id).gte("date", monthStr+"-01").lte("date", monthStr+"-"+String(daysInMonth).padStart(2,"0"))
    toast.success("Month cleared")
    setSaving(false)
    load()
  }

  const cells = []
