                    <div style={{ position:"absolute", top:2, left:form.is_blocked?22:2, width:20, height:20, background:"#fff", borderRadius:"50%", transition:"left 0.2s", boxShadow:"0 1px 4px rgba(0,0,0,0.2)" }}/>
                  </div>
                </div>
                <div>
                  <div style={{ fontSize:13, fontWeight:600, color:form.is_blocked?"#e24b4a":"#333" }}>
                    {form.is_blocked?"≡ƒÜ½ Day blocked":"Γ£à Day open"}
                  </div>
                  <div style={{ fontSize:11, color:"#888" }}>{form.is_blocked?"No bookings allowed":"Accepting bookings"}</div>
                </div>
              </label>

              {form.is_blocked&&(
                <div style={{ marginBottom:"1rem" }}>
                  <label style={{ fontSize:11, color:"#666", display:"block", marginBottom:4 }}>Block reason (optional)</label>
                  <input value={form.block_reason} onChange={e=>setForm(f=>({...f,block_reason:e.target.value}))}
                    placeholder="e.g. Public holiday, Training"
                    style={{ width:"100%", background:"#f8f8f8", border:"1px solid #e5e5e5", borderRadius:8, padding:"10px 12px", color:"#000", fontSize:12, outline:"none", fontFamily:"DM Sans,sans-serif" }}/>
                </div>
              )}

              {!form.is_blocked&&(
                <div style={{ marginBottom:"1rem" }}>
                  <label style={{ fontSize:11, color:"#666", display:"block", marginBottom:8 }}>Max bookings this day</label>
                  <div style={{ display:"flex", alignItems:"center", gap:12, background:"#f8f8f8", borderRadius:10, padding:"0.75rem" }}>
                    <button type="button" onClick={()=>setForm(f=>({...f,max_bookings:Math.max(1,f.max_bookings-1)}))}
                      style={{ width:36, height:36, borderRadius:8, background:"#fff", border:"1px solid #ddd", fontSize:20, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center" }}>ΓêÆ</button>
                    <div style={{ flex:1, textAlign:"center" }}>
                      <div style={{ fontFamily:"Syne", fontSize:28, fontWeight:800, color:"#e6821e" }}>{form.max_bookings}</div>
                      <div style={{ fontSize:10, color:"#888" }}>max bookings</div>
                    </div>
                    <button type="button" onClick={()=>setForm(f=>({...f,max_bookings:Math.min(20,f.max_bookings+1)}))}
                      style={{ width:36, height:36, borderRadius:8, background:"#fff", border:"1px solid #ddd", fontSize:20, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center" }}>+</button>
                  </div>
                  <div style={{ fontSize:11, color:"#888", marginTop:6, textAlign:"center" }}>
                    {bookingCounts[selected]||0} booked ┬╖ {Math.max(0,form.max_bookings-(bookingCounts[selected]||0))} slots free
                  </div>
                </div>
              )}

              <button type="submit" disabled={saving}
                style={{ width:"100%", background:saving?"#ccc":"linear-gradient(135deg,#e6821e,#f09840)", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700, padding:"13px", cursor:saving?"not-allowed":"pointer", boxShadow:"0 4px 12px rgba(230,130,30,0.3)" }}>
                {saving?"Saving...":"Γ£ô Save changes"}
              </button>
            </form>
          </div>
        )}
      </div>
    </div>
  )
}

import { useEffect, useState } from "react"
import { MarketplaceIcon, HomeIcon, GOServiceIcon, ServicesIcon, DiscoverIcon, MechanicIcon, CheckIcon, CloseIcon, WalletIcon, ChatIcon, ShieldIcon, WarningIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import { pushNotify } from "../../lib/pushNotify"
import { useAuth } from "../../contexts/AuthContext"
import { useLanguage } from "../../contexts/LanguageContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"
import { downloadInvoice } from "../../lib/invoice"
import VehicleConditionReport from "../shared/VehicleConditionReport"
import ProviderPartsManager from "./ProviderPartsManager"

const SC = { pending:"#e6821e", confirmed:"#378add", "in-progress":"#8b5cf6", completed:"#1d9e75", cancelled:"#e24b4a" }
const SB = { pending:"#fff8f0", confirmed:"#eff6ff", "in-progress":"#faf5ff", completed:"#f0fdf4", cancelled:"#fff5f5" }
const CATEGORIES = {
  shop_standard: { label:"Shop Standard", icon:"marketplace", color:"#378add" },
  shop_premium: { label:"Shop Premium", icon:"home", color:"#8b5cf6" },
  go_service: { label:"GO Service", icon:"emergency", color:"#e24b4a" },
}

export default function ProviderBookings() {
  const { user } = useAuth()
  const { t, language } = useLanguage()
  const isMobile = useIsMobile()
  const [bookings, setBookings] = useState([])
  const [mechanics, setMechanics] = useState([])
  const [filter, setFilter] = useState("all")
  const [loading, setLoading] = useState(true)
  const [partsRequests, setPartsRequests] = useState([])
  const [expanded, setExpanded] = useState(null)
  const [assigningMechanic, setAssigningMechanic] = useState(null)
  const [showReport, setShowReport] = useState(null)
  const [reportType, setReportType] = useState("pickup")
  const [existingReports, setExistingReports] = useState({})
  const [selectedMechanic, setSelectedMechanic] = useState("")
  const [showParts, setShowParts] = useState(null)

  useEffect(() => {
    if (!user) return
    load()
    loadPartsRequests()
    const sub = supabase.channel("provider-bookings-live")
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"bookings", filter:`provider_id=eq.${user.id}` }, payload => {
        load()
        toast.success(`New booking: ${payload.new.service_name} ≡ƒÄë`, { duration:8000 })
      })
      .on("postgres_changes", { event:"UPDATE", schema:"public", table:"bookings", filter:`provider_id=eq.${user.id}` }, payload => {
        load()
        const status = payload.new.status
        if (status === "cancelled") toast.error("Booking cancelled by customer")
        else if (status === "confirmed") toast.success("Booking confirmed Γ£à")
        else if (status === "in-progress") toast("Service started ≡ƒöº")
        else if (status === "completed") toast.success("Service completed Γ£à")
        else toast("Booking updated", { icon:"≡ƒôï" })
      })
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function loadPartsRequests() {
    const { data } = await supabase.from("mechanic_parts_requests")
      .select("*, mechanics(first_name,last_name,specialization), bookings(id,service_name,booking_date)")
      .eq("provider_id", user.id)
      .eq("status", "pending")
      .order("created_at", { ascending: false })
    setPartsRequests(data||[])
  }

  async function updatePartsStatus(id, status) {
    await supabase.from("mechanic_parts_requests").update({ status }).eq("id", id)
    loadPartsRequests()
    toast.success("Parts request " + status)
  }

  async function load() {
    const [{ data: bks }, { data: mechs }] = await Promise.all([
      supabase.from("bookings").select("*").eq("provider_id", user.id).eq("is_archived", false).order("created_at",{ascending:false}),
      supabase.from("mechanics").select("*").eq("provider_id", user.id).eq("is_active", true).eq("is_available", true),
    ])
    setBookings(bks||[])
    setMechanics(mechs||[])

    if (bks?.length) {
      const premiumGoBookings = bks.filter(b=>b.service_category==="shop_premium"||b.service_category==="go_service")
      if (premiumGoBookings.length) {
        const ids = premiumGoBookings.map(b=>b.id)
        const { data: reps } = await supabase.from("vehicle_condition_reports").select("booking_id,report_type").in("booking_id", ids)
        const repMap = {}
        reps?.forEach(r => {
          if (!repMap[r.booking_id]) repMap[r.booking_id] = {}
          repMap[r.booking_id][r.report_type] = true
        })
        setExistingReports(repMap)
      }
    }
    setLoading(false)
  }

  async function updateStatus(id, status) {
    const booking = bookings.find(b=>b.id===id)
    const isConciergeCompletion = status === "completed" && booking?.is_concierge
    // For concierge bookings, the provider marking their service done should NOT overwrite the
    // shared status field, since that would remove the job from the driver's own active list
    // before the driver has finished their separate delivery task. Track it independently instead.
    const updateData = isConciergeCompletion ? { service_completed_at: new Date().toISOString() } : { status }
    if (status === "completed") {
      if (booking?.is_concierge && booking?.pickup_lat && booking?.dropoff_lat) {
        const R = 6371
        const dLat = (booking.dropoff_lat - booking.pickup_lat) * Math.PI/180
        const dLng = (booking.dropoff_lng - booking.pickup_lng) * Math.PI/180
        const a = Math.sin(dLat/2)*Math.sin(dLat/2) + Math.cos(booking.pickup_lat*Math.PI/180)*Math.cos(booking.dropoff_lat*Math.PI/180)*Math.sin(dLng/2)*Math.sin(dLng/2)
        const dist = R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a))
        updateData.actual_mileage = Math.round(dist*10)/10
      }
    }
    const { error } = await supabase.from("bookings").update(updateData).eq("id",id).eq("provider_id",user.id)
    if (error) return toast.error(error.message)
    toast.success(`Booking ${status}`)
    if (booking?.customer_id) {
      const STATUS_MESSAGES = {
        confirmed: { title: "Booking confirmed! Γ£à", message: `Your booking for ${booking.service_name} has been confirmed by the provider.` },
        "in-progress": { title: "Service started ≡ƒöº", message: `Work has started on your ${booking.service_name}.` },
        completed: booking.is_concierge
          ? { title: "Service complete! Γ£à", message: `Your ${booking.service_name} is done. Your driver will bring your vehicle back shortly.` }
          : { title: "Service complete! Γ£à", message: `Your ${booking.service_name} is done. Please confirm to release payment.` },
        cancelled: { title: "Booking declined", message: `Your booking for ${booking.service_name} was declined by the provider.` },
      }
      const msg = STATUS_MESSAGES[status]
      if (msg) {
        await supabase.from("notifications").insert({ user_id: booking.customer_id, title: msg.title, message: msg.message, type: status==="cancelled"?"warning":"success" })
      }
    }
    load()
  }

  async function assignMechanic(bookingId) {
    if (!selectedMechanic && mechanics.length > 0) return toast.error("Please select a mechanic")
    try {
      await supabase.from("bookings").update({ assigned_mechanic_id: selectedMechanic||null, status:"in-progress" }).eq("id", bookingId).eq("provider_id", user.id)
      if (selectedMechanic) {
        await supabase.from("mechanics").update({ is_available:false, current_booking_id:bookingId }).eq("id", selectedMechanic)
        
        // Get mechanic user_id for notification
        const { data: mech } = await supabase.from("mechanics")
          .select("first_name, last_name, provider_id")
          .eq("id", selectedMechanic).single()
        
        // Get booking details
        const booking = bookings.find(b=>b.id===bookingId)
        
        // Notify customer
        if (booking?.customer_id) {
          await supabase.from("notifications").insert({
            user_id: booking.customer_id,
            title: "Mechanic Assigned ≡ƒæ¿ΓÇì≡ƒöº",
            message: "A mechanic has been assigned to your booking. They will be with you shortly.",
            type: "info"
          })
        }
        
        // Notify mechanic via provider notifications (mechanic checks provider app)
        if (mech?.provider_id) {
          await supabase.from("notifications").insert({
            user_id: mech.provider_id,
            title: "Job Assigned to Mechanic",
            message: (mech.first_name + " " + mech.last_name) + " has been assigned to booking #" + bookingId.slice(0,8),
            type: "info"
          })
        }
      }
      toast.success("Mechanic assigned ΓÇö customer notified! ≡ƒæ¿ΓÇì≡ƒöº")
      setAssigningMechanic(null)
      setSelectedMechanic("")
      load()
    } catch(err) { toast.error(err.message) }
  }

  async function markPaid(id) {
    const { error } = await supabase.from("bookings").update({ payment_status:"paid" }).eq("id",id).eq("provider_id",user.id)
    if (error) return toast.error(error.message)
    toast.success("Marked as paid")
    load()
  }

  async function completeAndFreeMechanic(bookingId, mechanicId) {
    const booking = bookings.find(b=>b.id===bookingId)
    // For concierge bookings, do not overwrite the shared status field - it would remove the job
    // from the driver's own active list before their delivery is actually done. Track separately.
    const completionUpdate = booking?.is_concierge ? { service_completed_at: new Date().toISOString() } : { status:"completed" }
    await supabase.from("bookings").update(completionUpdate).eq("id",bookingId).eq("provider_id",user.id)
    if (mechanicId) {
      await supabase.from("mechanics").update({ is_available:true, current_booking_id:null, current_latitude:null, current_longitude:null }).eq("id",mechanicId)
    }
    // Auto notify customer to leave review + pay
    if (booking?.customer_id) {
      await supabase.from("notifications").insert([
        {
          user_id: booking.customer_id,
          title: "Service completed! How was it? Γ¡É",
          message: "Your "+booking.service_name+" has been completed! Please go to My Bookings ΓåÆ tap the booking ΓåÆ Leave a Review. Your feedback helps other customers and earns you 50 bonus loyalty points!",
          type: "success"
        },
        {
          user_id: booking.customer_id,
          title: "Payment reminder ≡ƒÆ│",
          message: "Please complete payment for your "+booking.service_name+" service. Amount: KES "+Number(booking.updated_total||booking.total_amount).toLocaleString(),
          type: "info"
        }
      ])
    }
    toast.success("Booking completed ΓÇö customer notified!")
    load()
  }

  async function downloadBookingInvoice(booking) {
    try {
      const [{ data: provider }, { data: customer }, { data: mechanic }] = await Promise.all([
        supabase.from("profiles").select("*").eq("id", booking.provider_id).single(),
        supabase.from("profiles").select("*").eq("id", booking.customer_id).single(),
        booking.assigned_mechanic_id ? supabase.from("mechanics").select("*").eq("id", booking.assigned_mechanic_id).single() : Promise.resolve({ data:null }),
      ])
      downloadInvoice(booking, provider, customer, mechanic, null)
      toast.success("Invoice downloaded")
    } catch(err) { toast.error("Could not generate invoice") }
  }

  const filtered = filter==="all" ? bookings : bookings.filter(b=>b.status===filter)

  if (showReport) return (
    <div>
      <button onClick={()=>setShowReport(null)} style={{ background:"none", border:"none", color:"#378add", cursor:"pointer", fontSize:13, marginBottom:"1rem", fontFamily:"DM Sans,sans-serif", padding:0 }}>
        ΓåÉ Back to bookings
      </button>
      <VehicleConditionReport
        bookingId={showReport}
        reportType={reportType}
        onComplete={()=>{ setShowReport(null); load() }}
      />
    </div>
  )

  return (
    <div>
      <div style={{ display:"grid", gridTemplateColumns:isMobile?"repeat(2,1fr)":"repeat(4,1fr)", gap:10, marginBottom:"1.25rem" }}>
        {[
          { label:t("pending"), value:bookings.filter(b=>b.status==="pending").length, color:"#e6821e" },
          { label:"Confirmed", value:bookings.filter(b=>b.status==="confirmed").length, color:"#378add" },
          { label:"In progress", value:bookings.filter(b=>b.status==="in-progress").length, color:"#8b5cf6" },
          { label:t("completed"), value:bookings.filter(b=>b.status==="completed").length, color:"#1d9e75" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#ffffff", borderRadius:10, padding:isMobile?"0.75rem":"1rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontSize:10, color:"#777777", textTransform:"uppercase", marginBottom:4 }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:s.color }}>{s.value}</div>
          </div>
        ))}
      </div>

      <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap" }}>
        {["all","pending","confirmed","in-progress","completed","cancelled"].map(s=>(
          <button key={s} onClick={()=>setFilter(s)}
            style={{ padding:isMobile?"5px 10px":"6px 14px", borderRadius:6, border:"none", fontSize:isMobile?11:12, cursor:"pointer", background:filter===s?"#378add":"#555555", color:filter===s?"#fff":"#666", fontFamily:"'DM Sans',sans-serif" }}>
            {s==="all"?"All":s.charAt(0).toUpperCase()+s.slice(1)}
          </button>
        ))}
      </div>

      {/* Parts requests banner */}
      {partsRequests.length>0&&(
        <div style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:10, padding:"0.75rem", marginBottom:"1rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#e6821e", marginBottom:8 }}>≡ƒö⌐ Mechanic Parts Requests ({partsRequests.length})</div>
          {partsRequests.map(pr=>(
            <div key={pr.id} style={{ background:"#ffffff", borderRadius:8, padding:"0.75rem", marginBottom:6, border:"1px solid #eeeeee" }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:4 }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:700, color:"#000" }}>{pr.quantity}x {pr.part_name}</div>
                  <div style={{ fontSize:11, color:"#555" }}>From: {pr.mechanics?.first_name} {pr.mechanics?.last_name}</div>
                  <div style={{ fontSize:11, color:"#888" }}>Booking: #{pr.booking_id?.slice(0,8)}</div>
                  {pr.notes&&<div style={{ fontSize:11, color:"#666", marginTop:2 }}>Note: {pr.notes}</div>}
                </div>
                <span style={{ fontSize:10, padding:"2px 8px", borderRadius:8, fontWeight:700,
                  background:pr.urgency==="critical"?"#fff5f5":pr.urgency==="urgent"?"#fff8f0":"#f8f8f8",
                  color:pr.urgency==="critical"?"#e24b4a":pr.urgency==="urgent"?"#e6821e":"#888" }}>
                  {pr.urgency}
                </span>
              </div>
              <div style={{ display:"flex", gap:6 }}>
                <button onClick={()=>updatePartsStatus(pr.id,"approved")}
                  style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:6, color:"#1d9e75", fontSize:10, fontWeight:700, padding:"4px 10px", cursor:"pointer" }}>
                  Γ£ô Approve
                </button>
                <button onClick={()=>updatePartsStatus(pr.id,"rejected")}
                  style={{ background:"#fff5f5", border:"1px solid #e24b4a40", borderRadius:6, color:"#e24b4a", fontSize:10, fontWeight:700, padding:"4px 10px", cursor:"pointer" }}>
                  Γ£ù Reject
                </button>
              </div>
            </div>
          ))}
        </div>
      )}


      {loading&&<div style={{ color:"#777777", fontSize:13 }}>{t("loading")}</div>}
      {!loading&&filtered.length===0&&<div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"2rem" }}>No bookings found</div>}

      {filtered.map(b=>{
        const cat = CATEGORIES[b.service_category]||CATEGORIES.shop_standard
        const reports = existingReports[b.id]||{}
        return (
          <div key={b.id} style={{ background:"#ffffff", border:`1px solid ${SB[b.status]||"#eeeeee"}`, borderRadius:10, padding:isMobile?"0.75rem":"1rem", marginBottom:8 }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
              <div style={{ flex:1, minWidth:0, marginRight:8 }}>
                <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:4, flexWrap:"wrap" }}>
                  <span style={{display:"flex", alignItems:"center"}}>
                  {cat.icon==="marketplace"?<MarketplaceIcon size={14} color={cat.color}/>:
                   cat.icon==="home"?<HomeIcon size={14} color={cat.color}/>:
                   cat.icon==="emergency"?<GOServiceIcon size={14} color="#e24b4a"/>:
                   cat.icon==="discover"?<DiscoverIcon size={14} color={cat.color}/>:
                   <ServicesIcon size={14} color={cat.color}/>}
                </span>
                  <div style={{ fontSize:isMobile?13:14, fontWeight:500, color:"#000000" }}>{b.service_name}</div>
                  <span style={{ fontSize:10, padding:"1px 7px", borderRadius:10, background:`${cat.color}20`, color:cat.color }}>{cat.label}</span>
                </div>
                <div style={{ fontSize:11, color:"#777777" }}>{b.booking_date} ┬╖ {b.booking_time?.slice(0,5)}</div>
                {b.booking_number&&<div style={{ fontSize:10, color:"#888888", marginTop:2 }}>#{b.booking_number}</div>}
                {b.problem_description&&<div style={{ fontSize:11, color:"#555555", marginTop:4, fontStyle:"italic" }}>&quot;{b.problem_description}&quot;</div>}
                {b.assigned_mechanic_id&&<div style={{ fontSize:11, color:"#1d9e75", marginTop:2, display:"flex", alignItems:"center", gap:3 }}><MechanicIcon size={11} color="#1d9e75"/> Mechanic assigned</div>}
                {(b.before_photo_url||b.after_photo_url)&&(
                  <div style={{ display:"flex", gap:6, marginTop:6 }}>
                    {b.before_photo_url&&<img src={b.before_photo_url} alt="Before" style={{ width:44, height:44, objectFit:"cover", borderRadius:6, border:"1px solid #eee" }}/>}
                    {b.after_photo_url&&<img src={b.after_photo_url} alt="After" style={{ width:44, height:44, objectFit:"cover", borderRadius:6, border:"1px solid #eee" }}/>}
                  </div>
                )}
                {b.parts_details?.length>0&&(
                  <div style={{ fontSize:11, color:b.parts_approved?"#1d9e75":"#e6821e", marginTop:2 }}>
                    <ServicesIcon size={11} color="currentColor"/> Parts: {b.parts_details.length} item{b.parts_details.length!==1?"s":""} ┬╖ {b.parts_approved?"Γ£ô Approved":"Awaiting approval"}
                  </div>
                )}
              </div>
              <div style={{ textAlign:"right", flexShrink:0 }}>
                <span style={{ fontSize:10, fontWeight:500, padding:"2px 8px", borderRadius:20, background:SB[b.status]||"#555555", color:SC[b.status]||"#888", border:`1px solid ${SC[b.status]||"#888"}40`, display:"inline-block" }}>{b.status}</span>
                <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#e6821e", marginTop:4 }}>
                  KES {Number(b.updated_total||b.total_amount).toLocaleString()}
                </div>
              </div>
            </div>

            <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
              {b.status==="pending"&&<>
                <button onClick={()=>updateStatus(b.id,"confirmed")} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>Confirm</button>
                <button onClick={()=>updateStatus(b.id,"cancelled")} style={{ background:"none", border:"1px solid #e24b4a40", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>Decline</button>
              </>}

              {["confirmed","driver-assigned","arrived-for-pickup"].includes(b.status)&&<>
                <button onClick={()=>{ setAssigningMechanic(b.id); setSelectedMechanic("") }}
                  style={{ background:"#faf5ff", border:"1px solid #8b5cf640", borderRadius:7, color:"#8b5cf6", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                  <><MechanicIcon size={13} color="currentColor"/> Assign mechanic</>
                </button>
                <button onClick={()=>updateStatus(b.id,"in-progress")}
                  style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                  Start
                </button>
              </>}

              {b.service_completed_at&&["in-progress","arrived-at-dropoff"].includes(b.status)&&(
                <div style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"5px 10px" }}>Service marked complete - awaiting driver delivery</div>
              )}
              {["in-progress","arrived-at-dropoff"].includes(b.status)&&!b.service_completed_at&&(
                <button onClick={()=>completeAndFreeMechanic(b.id, b.assigned_mechanic_id)}
                  style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                  Γ£ô Complete
                </button>
              )}

              {(b.service_category==="shop_premium"||b.service_category==="go_service")&&b.assigned_mechanic_id&&<>
                {!reports.pickup&&(
                  <button onClick={()=>{ setShowReport(b.id); setReportType("pickup") }}
                    style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                    ≡ƒôï Pickup report
                  </button>
                )}
                {reports.pickup&&!reports.dropoff&&(
                  <button onClick={()=>{ setShowReport(b.id); setReportType("dropoff") }}
                    style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                    ≡ƒôï Dropoff report
                  </button>
                )}
              </>}

              {["confirmed","in-progress"].includes(b.status)&&(
                <button onClick={()=>setShowParts(showParts===b.id?null:b.id)}
                  style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                  ≡ƒöº {b.parts_details?.length>0?"Edit parts":"Add parts"}
                </button>
              )}

              {b.status==="completed"&&(
                <button onClick={()=>downloadBookingInvoice(b)}
                  style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                  ≡ƒº╛ Invoice
                </button>
              )}

              {b.status==="completed"&&b.payment_status!=="paid"&&(
                <button onClick={()=>markPaid(b.id)}
                  style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:7, color:"#e6821e", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                  Mark paid
                </button>
              )}

              <button onClick={()=>setExpanded(expanded===b.id?null:b.id)}
                style={{ background:"none", border:"1px solid #dddddd", borderRadius:7, color:"#666", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                {expanded===b.id?"Less":"Details"}
              </button>
            </div>

            {/* Assign mechanic panel */}
            {assigningMechanic===b.id&&(
              <div style={{ marginTop:10, background:"#faf5ff", border:"1px solid #8b5cf630", borderRadius:10, padding:"1rem" }}>
                <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#8b5cf6", marginBottom:8 }}>Assign mechanic</div>
                {mechanics.length===0?(
                  <div style={{ fontSize:12, color:"#777777", marginBottom:8 }}>No available mechanics.</div>
                ):(
                  <div style={{ marginBottom:10 }}>
                    {mechanics.map(m=>(
                      <div key={m.id} onClick={()=>setSelectedMechanic(m.id)}
                        style={{ display:"flex", alignItems:"center", gap:10, padding:"8px", borderRadius:8, cursor:"pointer", background:selectedMechanic===m.id?"#faf5ff":"transparent", border:`1px solid ${selectedMechanic===m.id?"#8b5cf6":"transparent"}`, marginBottom:4 }}>
                        <div style={{ width:32, height:32, borderRadius:"50%", background:"#f0fdf4", border:"1px solid #1d9e7540", display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontSize:12, fontWeight:800, color:"#1d9e75", flexShrink:0 }}>
                          {m.first_name[0]}{m.last_name[0]}
                        </div>
                        <div>
                          <div style={{ fontSize:12, color:"#000000" }}>{m.first_name} {m.last_name}</div>
                          <div style={{ fontSize:10, color:"#777777" }}>{m.specialization}</div>
                        </div>
                        {selectedMechanic===m.id&&<div style={{ marginLeft:"auto", fontSize:14, color:"#8b5cf6" }}>Γ£ô</div>}
                      </div>
                    ))}
                  </div>
                )}
                <div style={{ display:"flex", gap:8 }}>
                  <button onClick={()=>assignMechanic(b.id)} disabled={mechanics.length>0&&!selectedMechanic}
                    style={{ background:mechanics.length>0&&!selectedMechanic?"#555555":"#8b5cf6", border:"none", borderRadius:8, color:mechanics.length>0&&!selectedMechanic?"#555":"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"8px 16px", cursor:mechanics.length>0&&!selectedMechanic?"not-allowed":"pointer" }}>
                    Assign & notify customer
                  </button>
                  <button onClick={()=>{ setAssigningMechanic(null); setSelectedMechanic("") }}
                    style={{ background:"none", border:"1px solid #dddddd", borderRadius:8, color:"#666", fontSize:12, padding:"8px 14px", cursor:"pointer" }}>
                    Cancel
                  </button>
                </div>
              </div>
            )}

            {/* Parts manager */}
            {showParts===b.id&&(
              <ProviderPartsManager booking={b} onUpdate={()=>{ setShowParts(null); load() }}/>
            )}

            {/* Expanded details */}
            {expanded===b.id&&(
              <div style={{ marginTop:10, paddingTop:10, borderTop:"1px solid #eeeeee" }}>
                <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr 1fr":"repeat(3,1fr)", gap:8, marginBottom:8 }}>
                  {[
                    { l:"Your earnings", v:`KES ${Number(b.provider_earnings||0).toFixed(0)}`, c:"#1d9e75" },
                    { l:"Platform fee", v:`KES ${Number(b.platform_commission||0).toFixed(0)}` },
                    { l:"Payment", v:b.payment_status },
                    { l:"Method", v:b.payment_method },
                    { l:"Category", v:cat.label },
                    { l:"Concierge", v:b.is_concierge?"Yes":"No" },
                  ].map(f=>(
                    <div key={f.l}>
                      <div style={{ fontSize:10, color:"#777777", textTransform:"uppercase", marginBottom:2 }}>{f.l}</div>
                      <div style={{ fontSize:12, color:f.c||"#000000" }}>{f.v||"ΓÇö"}</div>
                    </div>
                  ))}
                </div>
                {b.parts_details?.length>0&&(
                  <div style={{ marginTop:8 }}>
                    <div style={{ fontSize:11, color:"#378add", marginBottom:4 }}>Parts breakdown:</div>
                    {b.parts_details.map((p,i)=>(
                      <div key={i} style={{ display:"flex", justifyContent:"space-between", fontSize:11, color:"#666", padding:"3px 0" }}>
                        <span>{p.name} ├ù {p.quantity}</span>
                        <span>KES {p.total?.toLocaleString()}</span>
                      </div>
                    ))}
                    <div style={{ display:"flex", justifyContent:"space-between", fontSize:11, color:"#e6821e", marginTop:4, fontWeight:600 }}>
                      <span>Parts total</span>
                      <span>KES {Number(b.parts_cost||0).toLocaleString()}</span>
                    </div>
                  </div>
                )}
                {b.notes&&<div style={{ fontSize:11, color:"#666", fontStyle:"italic", marginTop:8 }}>Note: &quot;{b.notes}&quot;</div>}
                {b.problem_description&&<div style={{ fontSize:11, color:"#555555", fontStyle:"italic", marginTop:4 }}>Problem: &quot;{b.problem_description}&quot;</div>}
              </div>
            )}
          </div>
        )
      })}
    </div>
  )
}

import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

export default function ProviderBundles() {
  const isMobile = useIsMobile()
  const { user } = useAuth()
  const [services, setServices] = useState([])
  const [bundles, setBundles] = useState([])
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [showForm, setShowForm] = useState(false)
  const [form, setForm] = useState({ name:"", description:"", service_ids:[], bundle_price:"" })

  useEffect(() => { if (user) load() }, [user])

  async function load() {
    const [{ data: svcs }, { data: bds }] = await Promise.all([
      supabase.from("services").select("*").eq("provider_id", user.id).eq("is_active", true),
      supabase.from("service_bundles").select("*").eq("provider_id", user.id).order("created_at",{ascending:false})
    ])
    setServices(svcs||[])
    setBundles(bds||[])
    setLoading(false)
  }

  function toggleService(id) {
    setForm(f => ({
      ...f,
      service_ids: f.service_ids.includes(id) 
        ? f.service_ids.filter(s=>s!==id) 
        : [...f.service_ids, id]
    }))
  }

  function originalTotal() {
    return form.service_ids.reduce((sum, id) => {
      const s = services.find(sv=>sv.id===id)
      return sum + (s ? Number(s.price) : 0)
    }, 0)
  }

  function weightedCommissionRate() {
    const total = originalTotal()
    if (total === 0) return 0.10
    const weightedSum = form.service_ids.reduce((sum, id) => {
      const s = services.find(sv=>sv.id===id)
      if (!s) return sum
      const rate = Number(s.platform_commission_rate || 0.10)
      return sum + (Number(s.price) * rate)
    }, 0)
    return weightedSum / total
  }

  async function save(e) {
    e.preventDefault()
    if (!form.name || form.service_ids.length < 2 || !form.bundle_price) {
      return toast.error("Name, at least 2 services, and bundle price required")
    }
    const origTotal = originalTotal()
    if (Number(form.bundle_price) >= origTotal) {
      return toast.error("Bundle price must be less than the total of individual services (KES " + origTotal.toLocaleString() + ")")
    }
    setSaving(true)
    try {
      const { error } = await supabase.from("service_bundles").insert({
        provider_id: user.id,
        name: form.name,
        description: form.description,
        service_ids: form.service_ids,
        bundle_price: Number(form.bundle_price),
        original_price: origTotal,
        platform_commission_rate: weightedCommissionRate(),
        is_active: true,
      })
      if (error) throw error
      toast.success("Bundle created!")
      setForm({ name:"", description:"", service_ids:[], bundle_price:"" })
      setShowForm(false)
      load()
    } catch(err) {
      toast.error(err.message)
    } finally {
      setSaving(false)
    }
  }

  async function toggleActive(id, is_active) {
    await supabase.from("service_bundles").update({ is_active: !is_active }).eq("id", id)
    toast.success(is_active ? "Bundle deactivated" : "Bundle activated")
    load()
  }

  async function deleteBundle(id) {
    if (!confirm("Delete this bundle?")) return
    await supabase.from("service_bundles").delete().eq("id", id)
    toast.success("Bundle deleted")
    load()
  }

  const lbl = { display:"block", fontSize:12, color:"#666", marginBottom:4, fontWeight:600 }
  const inp = { width:"100%", background:"#f8f8f8", border:"1px solid #f0f0f0", borderRadius:8, padding:"10px 12px", color:"#000000", fontSize:13, outline:"none", marginBottom:"1rem", fontFamily:"'DM Sans',sans-serif" }

  if (services.length < 2) {
    return (
      <div>
        <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, marginBottom:8 }}>Service Bundles</div>
        <div style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:10, padding:"1rem", fontSize:13, color:"#e6821e" }}>
          You need at least 2 active services to create a bundle. Add more services first.
        </div>
      </div>
    )
  }

  return (
    <div>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800 }}>Service Bundles</div>
        <button onClick={()=>setShowForm(!showForm)}
          style={{ background:"#e6821e", border:"none", borderRadius:8, color:"#fff", fontSize:12, fontWeight:700, padding:"8px 16px", cursor:"pointer" }}>
          {showForm?"Cancel":"+ New Bundle"}
        </button>
      </div>

      <div style={{ fontSize:12, color:"#888", marginBottom:"1rem" }}>
        Bundle 2+ services together at a discounted price. Customers save money, you get more bookings.
      </div>

      {showForm&&(
        <form onSubmit={save} style={{ background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:"1rem" }}>
          <label style={lbl}>Bundle name</label>
          <input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="e.g. Full Service Package" style={inp}/>

          <label style={lbl}>Description (optional)</label>
          <input value={form.description} onChange={e=>setForm({...form,description:e.target.value})} placeholder="What's included" style={inp}/>

          <label style={lbl}>Select services to include (choose 2+)</label>
          <div style={{ marginBottom:"1rem" }}>
            {services.map(s=>(
              <label key={s.id} style={{ display:"flex", alignItems:"center", gap:8, padding:"8px 0", borderBottom:"1px solid #eeeeee", cursor:"pointer", fontSize:13 }}>
                <input type="checkbox" checked={form.service_ids.includes(s.id)} onChange={()=>toggleService(s.id)}/>
                <span style={{ flex:1 }}>{s.name}</span>
                <span style={{ color:"#888" }}>KES {Number(s.price).toLocaleString()}</span>
              </label>
            ))}
          </div>

          {form.service_ids.length>=2&&(
            <div style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:8, padding:"0.75rem", marginBottom:"1rem", fontSize:12 }}>
              Individual total: <strong>KES {originalTotal().toLocaleString()}</strong>
            </div>
          )}

          <label style={lbl}>Bundle price (KES) ΓÇö must be less than individual total</label>
          <input type="number" value={form.bundle_price} onChange={e=>setForm({...form,bundle_price:e.target.value})} placeholder="e.g. 6500" style={inp}/>

          <button type="submit" disabled={saving}
            style={{ background:saving?"#ccc":"#1d9e75", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px 24px", cursor:saving?"not-allowed":"pointer" }}>
            {saving?"Creating...":"Create bundle"}
          </button>
        </form>
      )}

      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
      {!loading&&bundles.length===0&&!showForm&&(
        <div style={{ background:"#f8f8f8", borderRadius:10, padding:"1.5rem", textAlign:"center", color:"#888", fontSize:13 }}>
          No bundles yet. Create one to offer discounted packages!
        </div>
      )}
      {bundles.map(b=>{
        const savings = Number(b.original_price) - Number(b.bundle_price)
        const savingsPct = Math.round((savings / Number(b.original_price)) * 100)
        return (
          <div key={b.id} style={{ background:"#f8f8f8", border:`1px solid ${!b.is_active?"#e24b4a20":"#eeeeee"}`, borderRadius:10, padding:"1rem", marginBottom:8 }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"start", marginBottom:6 }}>
              <div>
                <div style={{ fontSize:14, fontWeight:700, color:"#000" }}>{b.name}</div>
                {b.description&&<div style={{ fontSize:11, color:"#888", marginTop:2 }}>{b.description}</div>}
              </div>
              {!b.is_active&&<span style={{ fontSize:10, color:"#e24b4a", background:"#fff5f5", padding:"1px 6px", borderRadius:10 }}>Inactive</span>}
            </div>
            <div style={{ display:"flex", gap:12, alignItems:"center", marginBottom:8 }}>
              <span style={{ fontSize:13, color:"#888", textDecoration:"line-through" }}>KES {Number(b.original_price).toLocaleString()}</span>
              <span style={{ fontSize:16, fontWeight:800, color:"#1d9e75" }}>KES {Number(b.bundle_price).toLocaleString()}</span>
              <span style={{ fontSize:11, color:"#1d9e75", background:"#f0fdf4", padding:"2px 8px", borderRadius:10 }}>Save {savingsPct}%</span>
            </div>
            {b.platform_commission_rate&&(
              <div style={{ fontSize:10, color:"#888", marginBottom:8 }}>
                Platform commission: {(b.platform_commission_rate*100).toFixed(1)}% (KES {(Number(b.bundle_price)*Number(b.platform_commission_rate)).toFixed(0)}) ┬╖ You earn: KES {(Number(b.bundle_price)*(1-Number(b.platform_commission_rate))).toFixed(0)}
              </div>
            )}
            <div style={{ display:"flex", gap:8 }}>
              <button onClick={()=>toggleActive(b.id,b.is_active)} style={{ background:b.is_active?"#fff5f5":"#f0fdf4", border:`1px solid ${b.is_active?"#e24b4a40":"#1d9e7540"}`, borderRadius:7, color:b.is_active?"#e24b4a":"#1d9e75", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>
                {b.is_active?"Deactivate":"Activate"}
              </button>
              <button onClick={()=>deleteBundle(b.id)} style={{ background:"none", border:"1px solid #e24b4a40", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>
                Delete
              </button>
            </div>
          </div>
        )
      })}
    </div>
  )
}

import { useEffect, useState } from "react"
import { SunIcon, SettingsIcon, BookingsIcon, SuccessIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const DAYS = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"]
const DAY_SHORT = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"]
const DAY_ICONS = ["sun","work","work","work","work","work","success"]

const DEFAULT_HOURS = DAYS.map((day, i) => ({
  day_of_week: i,
  day_name: day,
  is_open: i >= 1 && i <= 6,
  open_time: "08:00",
  close_time: "18:00"
}))

const PRESETS = [
  { label:"MonΓÇôFri", icon:"work", apply:(hours)=>hours.map((d,i)=>({...d,is_open:i>=1&&i<=5,open_time:"08:00",close_time:"18:00"})) },
  { label:"MonΓÇôSat", icon:"bookings", apply:(hours)=>hours.map((d,i)=>({...d,is_open:i>=1&&i<=6,open_time:"08:00",close_time:"18:00"})) },
  { label:"7 Days", icon:"7days", apply:(hours)=>hours.map(d=>({...d,is_open:true,open_time:"08:00",close_time:"18:00"})) },
  { label:"Half day", icon:"halfday", apply:(hours)=>hours.map((d,i)=>({...d,is_open:i>=1&&i<=6,open_time:"08:00",close_time:"13:00"})) },
]

export default function ProviderBusinessHours() {
  const { user } = useAuth()
  const isMobile = useIsMobile()
  const [hours, setHours] = useState(DEFAULT_HOURS)
  const [closures, setClosures] = useState([])
  const [closureForm, setClosureForm] = useState({ closure_date:"", reason:"" })
  const [saving, setSaving] = useState(false)
  const [loading, setLoading] = useState(true)
  const [tab, setTab] = useState("hours")

  useEffect(() => { if (user) load() }, [user])

  async function load() {
    const [{ data: bh }, { data: bc }] = await Promise.all([
      supabase.from("business_hours").select("*").eq("provider_id", user.id).order("day_of_week"),
      supabase.from("business_closures").select("*").eq("provider_id", user.id).order("closure_date")
    ])
    if (bh && bh.length > 0) {
      setHours(DEFAULT_HOURS.map(d => {
        const saved = bh.find(h => h.day_of_week === d.day_of_week)
        return saved ? { ...d, is_open:saved.is_open, open_time:saved.open_time?.slice(0,5)||"08:00", close_time:saved.close_time?.slice(0,5)||"18:00" } : d
      }))
    }
    setClosures(bc||[])
    setLoading(false)
  }

  function updateDay(dayIndex, field, value) {
    setHours(h => h.map((d,i) => i===dayIndex ? {...d, [field]:value} : d))
  }

  function applyPreset(preset) {
    setHours(preset.apply(hours))
    toast.success("Preset applied ΓÇö tap Save to confirm")
  }

  async function saveHours(e) {
    e.preventDefault()
    setSaving(true)
    try {
      for (const day of hours) {
        await supabase.from("business_hours").upsert({
          provider_id: user.id,
          day_of_week: day.day_of_week,
          is_open: day.is_open,
          open_time: day.open_time,
          close_time: day.close_time
        }, { onConflict: "provider_id,day_of_week" })
      }
      toast.success("Business hours saved! Γ£ô")
    } catch(err) { toast.error(err.message) }
    finally { setSaving(false) }
  }

  async function addClosure(e) {
    e.preventDefault()
    const { error } = await supabase.from("business_closures").insert({
      provider_id: user.id,
      closure_date: closureForm.closure_date,
      reason: closureForm.reason || null
    })
    if (error) return toast.error(error.message)
    toast.success("Closure date added")
    setClosureForm({ closure_date:"", reason:"" })
    load()
  }

  async function deleteClosure(id) {
    await supabase.from("business_closures").delete().eq("id", id).eq("provider_id", user.id)
    toast.success("Closure removed")
    load()
  }

  const openDays = hours.filter(d=>d.is_open).length

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:"#000", marginBottom:4 }}>Business Hours</div>
      <div style={{ fontSize:12, color:"#777", marginBottom:"1.5rem" }}>Set when customers can book your services</div>

      {/* Tabs */}
      <div style={{ display:"flex", gap:6, marginBottom:"1.25rem" }}>
        {[{k:"hours",l:"ΓÅ░ Hours"},{k:"closures",l:`≡ƒÜ½ Closures (${closures.length})`}].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{ padding:"8px 18px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#378add":"#f0f0f0", color:tab===t.k?"#fff":"#666", fontFamily:"DM Sans,sans-serif", fontWeight:tab===t.k?700:400 }}>
            {t.l}
          </button>
        ))}
      </div>

      {tab==="hours"&&(
        <form onSubmit={saveHours}>
          {/* Summary pill */}
          <div style={{ background:"linear-gradient(135deg,#378add,#5ba3f5)", borderRadius:12, padding:"1rem 1.25rem", marginBottom:"1.25rem", display:"flex", alignItems:"center", justifyContent:"space-between" }}>
            <div>
              <div style={{ fontFamily:"Syne", fontSize:22, fontWeight:800, color:"#fff" }}>{openDays} days open</div>
              <div style={{ fontSize:11, color:"rgba(255,255,255,0.8)", marginTop:2 }}>
                {hours.filter(d=>d.is_open).map(d=>DAY_SHORT[d.day_of_week]).join(" ┬╖ ")}
              </div>
            </div>
            <div style={{ fontSize:36 }}>≡ƒòÉ</div>
          </div>

          {/* Quick presets */}
          <div style={{ marginBottom:"1.25rem" }}>
            <div style={{ fontSize:11, color:"#888", marginBottom:8, textTransform:"uppercase", letterSpacing:"0.05em" }}>Quick presets</div>
            <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
              {PRESETS.map(p=>(
                <button key={p.label} type="button" onClick={()=>applyPreset(p)}
                  style={{ background:"#f0f7ff", border:"1px solid #378add30", borderRadius:8, color:"#378add", fontSize:12, fontWeight:600, padding:"7px 14px", cursor:"pointer", display:"flex", alignItems:"center", gap:5 }}>
                  {p.icon==="work"?<SettingsIcon size={14} color="currentColor"/>:
   p.icon==="bookings"?<BookingsIcon size={14} color="currentColor"/>:
   p.icon==="7days"?<BookingsIcon size={14} color="currentColor"/>:
   p.icon==="halfday"?<SunIcon size={14} color="currentColor"/>:
   <SunIcon size={14} color="currentColor"/>} {p.label}
                </button>
              ))}
            </div>
          </div>

          {/* Days */}
          {loading&&<div style={{ color:"#777", fontSize:13 }}>Loading...</div>}
          <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:14, overflow:"hidden", marginBottom:"1.25rem" }}>
            {hours.map((day, i) => (
              <div key={day.day_of_week} style={{ padding:"0.9rem 1.1rem", borderBottom:i<6?"1px solid #f5f5f5":"none", background:day.is_open?"#ffffff":"#fafafa" }}>
                <div style={{ display:"flex", alignItems:"center", gap:12 }}>
                  {/* Day toggle */}
                  <div style={{ width:36, height:36, borderRadius:10, background:day.is_open?"#378add":"#e0e0e0", display:"flex", alignItems:"center", justifyContent:"center", fontSize:16, flexShrink:0, transition:"background 0.2s" }}>
                    {day.is_open?(DAY_ICONS[i]==="sun"?<SunIcon size={16} color="#ffffff"/>:DAY_ICONS[i]==="success"?<SuccessIcon size={16} color="#ffffff"/>:<SettingsIcon size={16} color="#ffffff"/>):"ΓÇö"}
                  </div>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontSize:13, fontWeight:day.is_open?700:400, color:day.is_open?"#000":"#999", marginBottom:2 }}>{day.day_name}</div>
                    {day.is_open&&(
                      <div style={{ fontSize:11, color:"#378add" }}>{day.open_time} ΓÇô {day.close_time}</div>
                    )}
                    {!day.is_open&&<div style={{ fontSize:11, color:"#bbb" }}>Closed</div>}
                  </div>
                  {/* Toggle switch */}
                  <label style={{ position:"relative", width:44, height:24, flexShrink:0, cursor:"pointer" }}>
                    <input type="checkbox" checked={day.is_open} onChange={e=>updateDay(i,"is_open",e.target.checked)} style={{ opacity:0, width:0, height:0, position:"absolute" }}/>
                    <div style={{ position:"absolute", inset:0, background:day.is_open?"#378add":"#ddd", borderRadius:12, transition:"background 0.2s" }}>
                      <div style={{ position:"absolute", top:2, left:day.is_open?22:2, width:20, height:20, background:"#fff", borderRadius:"50%", transition:"left 0.2s", boxShadow:"0 1px 4px rgba(0,0,0,0.2)" }}/>
                    </div>
                  </label>
                </div>
                {/* Time inputs - shown when open */}
                {day.is_open&&(
                  <div style={{ display:"flex", alignItems:"center", gap:8, marginTop:10, paddingLeft:48 }}>
                    <div style={{ flex:1 }}>
                      <div style={{ fontSize:10, color:"#888", marginBottom:3 }}>Opens</div>
                      <input type="time" value={day.open_time} onChange={e=>updateDay(i,"open_time",e.target.value)}
                        style={{ width:"100%", background:"#f8f8f8", border:"1px solid #e5e5e5", borderRadius:8, padding:"8px 10px", color:"#000", fontSize:13, outline:"none", fontFamily:"DM Sans,sans-serif" }}/>
                    </div>
                    <div style={{ fontSize:12, color:"#888", marginTop:16 }}>ΓåÆ</div>
                    <div style={{ flex:1 }}>
                      <div style={{ fontSize:10, color:"#888", marginBottom:3 }}>Closes</div>
                      <input type="time" value={day.close_time} onChange={e=>updateDay(i,"close_time",e.target.value)}
                        style={{ width:"100%", background:"#f8f8f8", border:"1px solid #e5e5e5", borderRadius:8, padding:"8px 10px", color:"#000", fontSize:13, outline:"none", fontFamily:"DM Sans,sans-serif" }}/>
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>

          <button type="submit" disabled={saving}
            style={{ width:"100%", background:saving?"#ccc":"linear-gradient(135deg,#378add,#5ba3f5)", border:"none", borderRadius:12, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700, padding:"14px", cursor:saving?"not-allowed":"pointer", boxShadow:"0 4px 12px rgba(55,138,221,0.3)" }}>
            {saving?"Saving...":"Γ£ô Save Business Hours"}
          </button>
        </form>
      )}

      {tab==="closures"&&(
        <div>
          {/* Add closure form */}
          <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:14, padding:"1.25rem", marginBottom:"1.25rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#000", marginBottom:"1rem" }}>≡ƒÜ½ Add closure date</div>
            <form onSubmit={addClosure}>
              <div style={{ marginBottom:10 }}>
                <label style={{ fontSize:11, color:"#666", textTransform:"uppercase", display:"block", marginBottom:4 }}>Date *</label>
                <input type="date" value={closureForm.closure_date} onChange={e=>setClosureForm(f=>({...f,closure_date:e.target.value}))} required
                  min={new Date().toISOString().split("T")[0]}
                  style={{ width:"100%", background:"#f8f8f8", border:"1px solid #e5e5e5", borderRadius:8, padding:"10px 12px", color:"#000", fontSize:13, outline:"none", fontFamily:"DM Sans,sans-serif" }}/>
              </div>
              <div style={{ marginBottom:12 }}>
                <label style={{ fontSize:11, color:"#666", textTransform:"uppercase", display:"block", marginBottom:4 }}>Reason (optional)</label>
                <input placeholder="e.g. Public holiday, Staff training, Annual leave" value={closureForm.reason} onChange={e=>setClosureForm(f=>({...f,reason:e.target.value}))}
                  style={{ width:"100%", background:"#f8f8f8", border:"1px solid #e5e5e5", borderRadius:8, padding:"10px 12px", color:"#000", fontSize:13, outline:"none", fontFamily:"DM Sans,sans-serif" }}/>
              </div>
              <button type="submit"
                style={{ width:"100%", background:"#e24b4a", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"12px", cursor:"pointer" }}>
                + Add closure date
              </button>
            </form>
          </div>

          {/* Closures list */}
          {closures.length===0&&(
            <div style={{ textAlign:"center", padding:"2rem", color:"#888", fontSize:13 }}>
              <div style={{ fontSize:36, marginBottom:8 }}>Γ£à</div>
              No closures set ΓÇö you are open on all your scheduled days
            </div>
          )}
          {closures.map(c=>(
            <div key={c.id} style={{ background:"#ffffff", border:"1px solid #e24b4a20", borderRadius:12, padding:"1rem", marginBottom:8, display:"flex", alignItems:"center", gap:12 }}>
              <div style={{ width:42, height:42, background:"#fff5f5", borderRadius:10, display:"flex", alignItems:"center", justifyContent:"center", fontSize:20, flexShrink:0 }}>≡ƒÜ½</div>
              <div style={{ flex:1 }}>
                <div style={{ fontSize:13, fontWeight:600, color:"#000" }}>
                  {new Date(c.closure_date+"T00:00:00").toLocaleDateString("default",{weekday:"long",year:"numeric",month:"long",day:"numeric"})}
                </div>
                {c.reason&&<div style={{ fontSize:11, color:"#888", marginTop:2 }}>≡ƒô¥ {c.reason}</div>}
              </div>
              <button onClick={()=>deleteClosure(c.id)} style={{ background:"#fff5f5", border:"1px solid #e24b4a40", borderRadius:8, color:"#e24b4a", fontSize:11, fontWeight:600, padding:"6px 12px", cursor:"pointer" }}>
                Remove
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { useState, useEffect, useRef } from "react"
import { ChatIcon, CheckIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import { auditLog, AUDIT_ACTIONS } from "../../lib/auditLog"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import ChatWindow from "../shared/ChatWindow"

export default function ProviderChat() {
  const { user } = useAuth()
  const isMobile = useIsMobile()
  const [conversations, setConversations] = useState([])
  const [selected, setSelected] = useState(null)
  const [loading, setLoading] = useState(true)
  const [menuFor, setMenuFor] = useState(null) // conversation key for context menu
  const [hidden, setHidden] = useState([])
  const longPressRef = useRef(null)
  
  function startLongPress(c) {
    longPressRef.current = setTimeout(() => setMenuFor(c.bookingId||c.inventoryId), 500)
  }
  function cancelLongPress() {
    clearTimeout(longPressRef.current)
  }
  
  async function deleteConversation(c) {
    if (!c.bookingId && !c.inventoryId) return
    const col = c.bookingId ? "booking_id" : "inventory_id"
    const val = c.bookingId || c.inventoryId
    const { error } = await supabase.from("chat_messages").delete()
      .eq(col, val)
    if (error) { console.error("Delete failed:", error.message); return }
    const hidePayload = { user_id: user.id }
    hidePayload[col] = val
    const { error: hideError } = await supabase.from("hidden_conversations").upsert(hidePayload, { onConflict: col==="booking_id"?"user_id,booking_id":"user_id,inventory_id" })
    await auditLog({ action: AUDIT_ACTIONS.CONVERSATION_DELETED, entityType: col, entityId: val })
    setHidden(prev => [...prev, val])
    setMenuFor(null)
  }
  async function markAllRead(c) {
    const col = c.bookingId ? "booking_id" : "inventory_id"
    const val = c.bookingId || c.inventoryId
    await supabase.from("chat_messages").update({ is_read:true })
      .eq(col, val).eq("receiver_id", user.id)
    setConversations(prev => prev.map(x => (x.bookingId||x.inventoryId)===val ? {...x, unread:0} : x))
    setMenuFor(null)
  }

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("provider-chat-list")
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"chat_messages", filter:`receiver_id=eq.${user.id}` }, () => load())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function load() {
    const { data: hiddenData } = await supabase.from("hidden_conversations").select("booking_id,inventory_id").eq("user_id", user.id)
    const hiddenKeys = (hiddenData||[]).map(h => h.booking_id || h.inventory_id)
    setHidden(hiddenKeys)
    const { data: bookings } = await supabase.from("bookings")
      .select("id,service_name,customer_id,status,booking_date")
      .eq("provider_id", user.id)
      .not("status","eq","deleted")
      .order("created_at", { ascending:false })

    if (!bookings||bookings.length===0) { 
    // Still check for inventory chats even with no bookings
  }

    const customerIds = [...new Set(bookings.map(b=>b.customer_id))]
    const { data: profs } = await supabase.from("profiles")
      .select("id,first_name,last_name").in("id", customerIds)

    const { data: lastMessages } = await supabase.from("chat_messages")
      .select("booking_id,message,created_at,sender_id,is_read,receiver_id")
      .in("booking_id", bookings.map(b=>b.id))
      .order("created_at", { ascending:false })

    const convs = bookings.map(b => {
      const customer = profs?.find(p=>p.id===b.customer_id)
      const msgs = lastMessages?.filter(m=>m.booking_id===b.id)||[]
      const last = msgs[0]
      const _hasMessages = msgs.length>0
      const unread = msgs.filter(m=>m.receiver_id===user.id&&!m.is_read).length
      return {
        _hasMessages,
        bookingId: b.id, serviceName: b.service_name, bookingDate: b.booking_date,
        status: b.status, otherUserId: b.customer_id,
        otherUserName: `${customer?.first_name||""} ${customer?.last_name||""}`.trim()||"Customer",
        lastMessage: last?.message||"No messages yet", lastTime: last?.created_at, unread,
      }
    })
    // Fetch inventory/parts chat messages for this provider
    const { data: invMsgs } = await supabase.from("chat_messages")
      .select("*, inventory!chat_messages_inventory_id_fkey(name,provider_id), sender:profiles!chat_messages_sender_id_fkey(first_name,last_name)")
      .not("inventory_id", "is", null)
      .or(`sender_id.eq.${user.id},receiver_id.eq.${user.id}`)
      .order("created_at", { ascending:false })

    if (invMsgs?.length) {
      const inventoryIds = [...new Set(invMsgs.map(m=>m.inventory_id))]
      inventoryIds.forEach(invId => {
        const msgs = invMsgs.filter(m=>m.inventory_id===invId)
        const last = msgs[0]
        const otherUserId = last.sender_id===user.id ? last.receiver_id : last.sender_id
        const otherProfile = last.sender_id===user.id ? null : last.sender
        const unread = msgs.filter(m=>m.receiver_id===user.id&&!m.is_read).length
        if (!convs.find(c=>c.inventoryId===invId)) {
          convs.push({
            _hasMessages: true,
            inventoryId: invId,
            bookingId: null,
            serviceName: last.inventory?.name||"Parts inquiry",
            otherUserId,
            otherUserName: otherProfile ? otherProfile.first_name+" "+otherProfile.last_name : "Customer",
            lastMessage: last.message||"",
            lastTime: last.created_at,
            unread,
          })
        }
      })
    }
    setConversations(convs.filter(c => !hiddenKeys.includes(c.bookingId||c.inventoryId)))
    setLoading(false)
  }

  const SC = { pending:"#e6821e", confirmed:"#378add", "in-progress":"#8b5cf6", completed:"#1d9e75", cancelled:"#e24b4a" }

  return (
    <>
      {selected&&(
        <div style={{ position:"fixed", inset:0, zIndex:1000, display:"flex", flexDirection:isMobile?"column":"row", alignItems:isMobile?"stretch":"center", justifyContent:"center", background:"rgba(0,0,0,0.7)" }}
          onClick={e=>{ if(e.target===e.currentTarget) setSelected(null) }}>
          <div style={{ marginTop:isMobile?"auto":"0", background:"#ffffff", borderRadius:isMobile?"16px 16px 0 0":"16px", border:"1px solid #eeeeee", width:isMobile?"100%":520, height:isMobile?"80vh":600, display:"flex", flexDirection:"column", overflow:"hidden" }}>
            <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"1rem", borderBottom:"1px solid #eeeeee", flexShrink:0 }}>
              <div>
                <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#000000" }}>{selected.otherUserName}</div>
                <div style={{ fontSize:11, color:"#777777" }}>{selected.serviceName}</div>
              </div>
              <button onClick={()=>setSelected(null)} style={{ background:"#f5f5f5", border:"none", borderRadius:"50%", width:32, height:32, color:"#555555", cursor:"pointer", fontSize:18, display:"flex", alignItems:"center", justifyContent:"center" }}>├ù</button>
            </div>
            <div style={{ flex:1, minHeight:0 }}>
              <ChatWindow bookingId={selected.bookingId} inventoryId={selected.inventoryId} otherUserId={selected.otherUserId} otherUserName={selected.otherUserName} onClose={()=>setSelected(null)}/>
            </div>
          </div>
        </div>
      )}
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:18, fontWeight:800, color:"#000000", marginBottom:4 }}>Customer Messages</div>
      <div style={{ fontSize:11, color:"#777777", marginBottom:"1rem" }}>{conversations.length} active conversation{conversations.length!==1?"s":""}</div>
      {loading&&<div style={{ color:"#777777", fontSize:13 }}>Loading...</div>}
      {!loading&&conversations.length===0&&<div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"3rem" }}><div style={{ fontSize:32, marginBottom:10 }}>≡ƒÆ¼</div><div style={{ fontWeight:600, marginBottom:6 }}>No conversations yet</div><div style={{ fontSize:11, color:"#aaa" }}>Conversations appear here when customers book your services</div></div>}
      {/* Context menu overlay */}
      {menuFor&&(
        <div style={{ position:"fixed", inset:0, zIndex:200, background:"rgba(0,0,0,0.5)" }} onClick={()=>setMenuFor(null)}>
          <div style={{ position:"absolute", bottom:0, left:0, right:0, background:"#fff", borderRadius:"20px 20px 0 0", padding:"1.25rem", boxShadow:"0 -4px 24px rgba(0,0,0,0.15)" }}
            onClick={e=>e.stopPropagation()}>
            <div style={{ width:36, height:4, background:"#e0e0e0", borderRadius:2, margin:"0 auto 1.25rem" }}/>
            <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#000", marginBottom:"1rem", textAlign:"center" }}>
              {conversations.find(c=>(c.bookingId||c.inventoryId)===menuFor)?.otherUserName}
            </div>
            {[
              { icon:"Γ£ô", label:"Mark all as read", color:"#1d9e75", action:()=>{ const c=conversations.find(x=>(x.bookingId||x.inventoryId)===menuFor); if(c) markAllRead(c) } },
              { icon:"chat", label:"Open chat", color:"#378add", action:()=>{ const c=conversations.find(x=>(x.bookingId||x.inventoryId)===menuFor); if(c){ setSelected(c); setMenuFor(null) } } },
              { icon:"≡ƒùæ", label:"Delete conversation", color:"#e24b4a", action:()=>{ const c=conversations.find(x=>(x.bookingId||x.inventoryId)===menuFor); if(c) deleteConversation(c) } },
            ].map(item=>(
              <div key={item.label} onClick={item.action}
                style={{ display:"flex", alignItems:"center", gap:14, padding:"1rem", borderRadius:12, cursor:"pointer", marginBottom:6, background:"#f8f8f8" }}>
                <span style={{ fontSize:20 }}>{item.icon}</span>
                <span style={{ fontSize:14, fontWeight:600, color:item.color }}>{item.label}</span>
              </div>
            ))}
            <div onClick={()=>setMenuFor(null)}
              style={{ display:"flex", alignItems:"center", justifyContent:"center", padding:"1rem", borderRadius:12, cursor:"pointer", background:"#f0f0f0", marginTop:4 }}>
              <span style={{ fontSize:14, fontWeight:600, color:"#555" }}>Cancel</span>
            </div>
          </div>
        </div>
      )}

      {conversations.map(c=>{
        const key = c.bookingId||c.inventoryId
        const isSelected = selected?.bookingId===c.bookingId
        const isMenuOpen = menuFor===key
        return (
        <div key={key}
          onClick={()=>{ if(!menuFor) setSelected(c) }}
          onTouchStart={()=>startLongPress(c)}
          onTouchEnd={cancelLongPress}
          onTouchMove={cancelLongPress}
          onContextMenu={e=>{ e.preventDefault(); setMenuFor(key) }}
          style={{ background:isMenuOpen?"#f0f6ff":"#ffffff", border:`1px solid ${isSelected?"#378add40":isMenuOpen?"#378add30":"#f0f0f0"}`, borderRadius:10, padding:"0.9rem", marginBottom:8, cursor:"pointer", transition:"all 0.15s", userSelect:"none" }}>
          <div style={{ display:"flex", alignItems:"flex-start", gap:10 }}>
            <div style={{ width:44, height:44, borderRadius:"50%", background:"#eff6ff", border:"1px solid #378add30", display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Syne", fontSize:16, fontWeight:800, color:"#378add", flexShrink:0 }}>
              {c.otherUserName[0]?.toUpperCase()}
            </div>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:2 }}>
                <div style={{ fontSize:13, fontWeight:c.unread>0?700:500, color:"#000000", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{c.otherUserName}</div>
                <div style={{ display:"flex", alignItems:"center", gap:6 }}>
                  {c.unread>0&&<div style={{ width:20, height:20, borderRadius:"50%", background:"#378add", color:"#fff", fontSize:10, fontWeight:700, display:"flex", alignItems:"center", justifyContent:"center" }}>{c.unread}</div>}
                  <span style={{ fontSize:10, color:"#888888" }}>{c.lastTime?new Date(c.lastTime).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}):""}</span>
                </div>
              </div>
              <div style={{ fontSize:11, color:"#666", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", marginBottom:4 }}>{c.lastMessage||"Tap to start chatting"}</div>
              <div style={{ display:"flex", gap:6, alignItems:"center" }}>
                <span style={{ fontSize:10, color:SC[c.status]||"#555" }}>ΓùÅ {c.status}</span>
                <span style={{ fontSize:10, color:"#888888" }}>┬╖ {c.serviceName}</span>
              </div>
            </div>
            <div style={{ fontSize:11, color:"#378add", flexShrink:0, marginTop:2 }}>≡ƒÆ¼</div>
          </div>
        </div>
      )})}
    </>
  )
}

import { useEffect, useState, useRef } from "react"
import { ShieldIcon, WarningIcon, CameraIcon, ChatIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import { validateFile, sanitizeFilePath } from "../../lib/uploadValidation"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import ClaimChat from "../shared/ClaimChat"
import toast from "react-hot-toast"

const SC = { pending:"#e6821e", under_review:"#8b5cf6", approved:"#1d9e75", rejected:"#e24b4a" }

const CLAIM_REASONS = [
  "Customer provided false vehicle information",
  "Customer was abusive or threatening",
  "Customer damaged provider equipment",
  "Customer disputed legitimate charges fraudulently",
  "Customer provided wrong location deliberately",
  "Customer no-show after booking confirmed",
  "Other",
]

export default function ProviderClaims() {
  const { user, profile } = useAuth()
  const isMobile = useIsMobile()
  const [claims, setClaims] = useState([])
  const [filedClaims, setFiledClaims] = useState([])
  const [penalties, setPenalties] = useState([])
  const [bookings, setBookings] = useState([])
  const [loading, setLoading] = useState(true)
  const [tab, setTab] = useState("against")
  const [chatClaim, setChatClaim] = useState(null)
  const [adminId, setAdminId] = useState(null)
  const [showForm, setShowForm] = useState(false)
  const [submitting, setSubmitting] = useState(false)
  const [evidencePhotos, setEvidencePhotos] = useState([])
  const [uploadingEvidence, setUploadingEvidence] = useState(false)
  const evidenceInputRef = useRef(null)
  const [form, setForm] = useState({ booking_id:"", reason:"", description:"" })

  useEffect(() => {
    if (!user) return
    load()
    supabase.from("profiles").select("id").eq("role","admin").limit(1)
      .then(({ data }) => { if (data?.length) setAdminId(data[0].id) })
    const sub = supabase.channel("provider-claims-"+user.id)
      .on("postgres_changes", { event:"UPDATE", schema:"public", table:"service_claims", filter:`provider_id=eq.${user.id}` }, () => load())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function load() {
    const [{ data: cls }, { data: filed }, { data: pens }, { data: bks }] = await Promise.all([
      supabase.from("service_claims")
        .select("*, bookings(service_name,booking_number,booking_date,total_amount), customer:profiles!service_claims_customer_id_fkey(first_name,last_name)")
        .eq("provider_id", user.id).order("created_at", { ascending:false }),
      supabase.from("service_claims")
        .select("*, bookings(service_name,booking_number,booking_date), against:profiles!service_claims_against_id_fkey(first_name,last_name)")
        .eq("claimant_id", user.id).eq("claimant_type","provider").order("created_at", { ascending:false }),
      supabase.from("provider_penalties")
        .select("*").eq("provider_id", user.id).order("created_at", { ascending:false }),
      supabase.from("bookings")
        .select("id,service_name,booking_number,booking_date,customer_id,profiles!bookings_customer_id_fkey(first_name,last_name)")
        .eq("provider_id", user.id).eq("status","completed").order("created_at", { ascending:false }).limit(20)
    ])
    setClaims(cls||[])
    setFiledClaims(filed||[])
    setPenalties(pens||[])
    setBookings(bks||[])
    setLoading(false)
  }

  async function uploadEvidencePhoto(file) {
    const _v = validateFile(file, "image")
    if (!_v.valid) { toast.error(_v.error); return }

    const ext = file.name.split(".").pop()
    const path = `claims/${Date.now()}_${Math.random().toString(36).slice(2)}.${ext}`
    const { error } = await supabase.storage.from("claim-evidence").upload(path, file)
    if (error) throw error
    const { data } = supabase.storage.from("claim-evidence").getPublicUrl(path)
    return data.publicUrl
  }

  async function handleEvidenceSelect(e) {
    const files = Array.from(e.target.files).slice(0, 3)
    setUploadingEvidence(true)
    try {
      const urls = await Promise.all(files.map(uploadEvidencePhoto))
      setEvidencePhotos(prev => [...prev, ...urls].slice(0, 3))
    } catch(err) { console.error("Photo upload failed:", err.message) }
    setUploadingEvidence(false)
  }

  async function submitClaim(e) {
    e.preventDefault()
    if (!form.booking_id) return toast.error("Please select a booking")
    if (!form.reason) return toast.error("Please select a reason")
    if (!form.description) return toast.error("Please describe the issue")
    setSubmitting(true)
    try {
      const booking = bookings.find(b=>b.id===form.booking_id)
      const { error } = await supabase.from("service_claims").insert({
        claimant_id: user.id,
        claimant_type: "provider",
        against_id: booking?.customer_id,
        against_type: "customer",
        customer_id: booking?.customer_id,
        provider_id: user.id,
        booking_id: form.booking_id,
        reason: form.reason,
        description: form.description,
        status: "pending",
      })
      if (error) throw error
      // Notify admin
      const { data: admins } = await supabase.from("profiles").select("id").eq("role","admin")
      for (const admin of (admins||[])) {
        await supabase.from("notifications").insert({
          user_id: admin.id,
          title: "Provider filed claim against customer ≡ƒ¢í∩╕Å",
          message: (profile?.first_name||"Provider")+" "+(profile?.last_name||"")+" filed a claim: "+form.reason,
          type: "warning"
        })
      }
      // Notify customer
      if (booking?.customer_id) {
        await supabase.from("notifications").insert({
          user_id: booking.customer_id,
          title: "A claim has been filed against you ΓÜá∩╕Å",
          message: "A service provider has filed a claim regarding booking "+booking.booking_number+". Our team will review within 24 hours.",
          type: "warning"
        })
      }
      toast.success("Claim submitted ΓÇö our team will review within 24 hours")
      setShowForm(false)
      setForm({ booking_id:"", reason:"", description:"" })
      setEvidencePhotos([])
      load()
    } catch(err) { toast.error(err.message) }
    finally { setSubmitting(false) }
  }

  const activePenalties = penalties.filter(p=>p.is_active)
  const totalDeducted = penalties.reduce((sum,p)=>sum+Number(p.amount_deducted||0),0)
  const inp = { width:"100%", background:"#f5f5f5", border:"1px solid #e0e0e0", borderRadius:8, padding:"10px 12px", fontSize:13, outline:"none", marginBottom:12, boxSizing:"border-box" }
  const lbl = { fontSize:11, color:"#666", display:"block", marginBottom:4, fontWeight:600 }

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:"#000", display:"flex", alignItems:"center", gap:8, marginBottom:"1rem" }}>≡ƒ¢í∩╕Å Claims Center</div>

      {/* Stats */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:8, marginBottom:"1rem" }}>
        {[
          { label:"Against you", value:claims.length, color:"#e24b4a" },
          { label:"Filed by you", value:filedClaims.length, color:"#8b5cf6" },
          { label:"Penalties", value:activePenalties.length, color:"#e6821e" },
          { label:"Deducted", value:"KES "+totalDeducted.toLocaleString(), color:"#e24b4a" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.75rem 0.5rem", textAlign:"center", border:"1px solid #eee" }}>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>

      {/* Tabs */}
      <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap" }}>
        {[
          { k:"against", l:"Claims against you ("+claims.length+")" },
          { k:"filed", l:"Claims you filed ("+filedClaims.length+")" },
          { k:"penalties", l:"Penalties ("+penalties.length+")" },
        ].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{ padding:"7px 14px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#e6821e":"#f0f0f0", color:tab===t.k?"#fff":"#555", fontWeight:tab===t.k?700:400 }}>
            {t.l}
          </button>
        ))}
        <button onClick={()=>setShowForm(!showForm)}
          style={{ marginLeft:"auto", background:"#8b5cf6", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"7px 14px", cursor:"pointer" }}>
          + File a claim
        </button>
      </div>

      {/* File claim form */}
      {showForm&&(
        <div style={{ background:"#f8f8f8", border:"1px solid #8b5cf640", borderRadius:12, padding:"1.25rem", marginBottom:"1rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, marginBottom:"1rem" }}>File a Claim Against a Customer</div>
          <form onSubmit={submitClaim}>
            <label style={lbl}>Select booking *</label>
            <select style={inp} value={form.booking_id} onChange={e=>setForm(f=>({...f,booking_id:e.target.value}))} required>
              <option value="">Select a completed booking</option>
              {bookings.map(b=>(
                <option key={b.id} value={b.id}>{b.service_name} ΓÇö #{b.booking_number} ┬╖ {b.profiles?.first_name} {b.profiles?.last_name}</option>
              ))}
            </select>
            <label style={lbl}>Reason *</label>
            <select style={inp} value={form.reason} onChange={e=>setForm(f=>({...f,reason:e.target.value}))} required>
              <option value="">Select reason</option>
              {CLAIM_REASONS.map(r=><option key={r} value={r}>{r}</option>)}
            </select>
            <label style={lbl}>Description *</label>
            <textarea style={{ ...inp, resize:"vertical", minHeight:100 }}
              placeholder="Describe what happened in detail..." rows={4}
              value={form.description} onChange={e=>setForm(f=>({...f,description:e.target.value}))} required/>
            <div style={{ background:"#fff8f0", border:"1px solid #e6821e30", borderRadius:8, padding:"0.75rem", marginBottom:12, fontSize:11, color:"#666" }}>
              ΓÜá∩╕Å False claims may result in account suspension. Only file claims for genuine incidents.
            </div>
              {/* Evidence photos */}
              <div style={{ marginBottom:12 }}>
                <div style={{ fontSize:11, color:"#666", fontWeight:600, marginBottom:6 }}>≡ƒô╕ Attach evidence photos (optional, max 3)</div>
                <input ref={evidenceInputRef} type="file" accept="image/*" multiple style={{ display:"none" }} onChange={handleEvidenceSelect}/>
                <div style={{ display:"flex", gap:6, flexWrap:"wrap", alignItems:"center" }}>
                  {evidencePhotos.map((url,i)=>(
                    <div key={i} style={{ position:"relative" }}>
                      <img src={url} alt="Evidence" style={{ width:60, height:60, objectFit:"cover", borderRadius:8, border:"1px solid #eee" }}/>
                      <button type="button" onClick={()=>setEvidencePhotos(p=>p.filter((_,j)=>j!==i))}
                        style={{ position:"absolute", top:-4, right:-4, background:"#e24b4a", border:"none", borderRadius:"50%", width:16, height:16, color:"#fff", fontSize:10, cursor:"pointer" }}>x</button>
                    </div>
                  ))}
                  {evidencePhotos.length<3&&(
                    <button type="button" onClick={()=>evidenceInputRef.current?.click()} disabled={uploadingEvidence}
                      style={{ width:60, height:60, background:"#f8f8f8", border:"2px dashed #ddd", borderRadius:8, cursor:"pointer", fontSize:20, color:"#aaa" }}>
                      {uploadingEvidence?"ΓÅ│":"≡ƒô╖"}
                    </button>
                  )}
                </div>
              </div>
            <div style={{ display:"flex", gap:8 }}>
              <button type="submit" disabled={submitting}
                style={{ background:submitting?"#ccc":"#8b5cf6", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px 24px", cursor:submitting?"not-allowed":"pointer" }}>
                {submitting?"Submitting...":"Submit claim"}
              </button>
              <button type="button" onClick={()=>setShowForm(false)}
                style={{ background:"none", border:"1px solid #ddd", borderRadius:9, color:"#666", fontSize:13, padding:"11px 16px", cursor:"pointer" }}>
                Cancel
              </button>
            </div>
          </form>
        </div>
      )}

      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}

      {/* Claims against provider tab */}
      {tab==="against"&&(
        <div>
          {!loading&&claims.length===0&&(
            <div style={{ textAlign:"center", padding:"2rem", color:"#888" }}>
              <div style={{ fontSize:32, marginBottom:10 }}>Γ£à</div>
              No claims against your services ΓÇö keep up the great work!
            </div>
          )}
          {claims.map(c=>(
            <div key={c.id} style={{ background:"#f8f8f8", border:"1px solid #eee", borderLeft:`4px solid ${SC[c.status]||"#eee"}`, borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4, flexWrap:"wrap" }}>
                    <div style={{ fontSize:13, fontWeight:700, color:"#000" }}>{c.bookings?.service_name}</div>
                    <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:(SC[c.status]||"#888")+"20", color:SC[c.status]||"#888" }}>{c.status?.replace("_"," ")}</span>
                  </div>
                  <div style={{ fontSize:11, color:"#888" }}>#{c.bookings?.booking_number} ┬╖ {c.bookings?.booking_date}</div>
                  <div style={{ fontSize:11, color:"#888" }}>Customer: {c.customer?.first_name} {c.customer?.last_name}</div>
                  <div style={{ fontSize:12, color:"#e6821e", marginTop:4 }}>Reason: {c.reason}</div>
                  {c.admin_notes&&<div style={{ fontSize:11, color:"#378add", marginTop:4 }}>Admin: "{c.admin_notes}"</div>}
                </div>
                <div style={{ textAlign:"right" }}>
