                    {p.is_active?"Active":"Resolved"}
                  </span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"
import { filterReviewContent } from "../../lib/reviewFilter"

function StarRating({ value, onChange, color="#e6821e" }) {
  return (
    <div style={{ display:"flex", gap:6 }}>
      {[1,2,3,4,5].map(star=>(
        <button key={star} type="button" onClick={()=>onChange&&onChange(star)}
          style={{ background:"none", border:"none", cursor:onChange?"pointer":"default", fontSize:26, color:star<=value?color:"#ddd", padding:"2px" }}>Γÿà</button>
      ))}
    </div>
  )
}

export default function ProviderCustomerReviews() {
  const { user, profile } = useAuth()
  const isMobile = useIsMobile()
  const [bookings, setBookings] = useState([])
  const [myReviews, setMyReviews] = useState([])
  const [tab, setTab] = useState("pending")
  const [loading, setLoading] = useState(true)
  const [reviewing, setReviewing] = useState(null)
  const [form, setForm] = useState({ rating:0, review:"" })
  const [submitting, setSubmitting] = useState(false)

  useEffect(() => { if(user) load() }, [user])

  async function load() {
    const [{ data: bk }, { data: rv }] = await Promise.all([
      supabase.from("bookings").select("*, customer:profiles!bookings_customer_id_fkey(first_name,last_name,id)")
        .eq("provider_id", user.id).eq("status","completed").order("created_at",{ascending:false}),
      supabase.from("reviews").select("*").eq("provider_id", user.id)
        .not("customer_rating","is",null).order("created_at",{ascending:false})
    ])
    setBookings(bk||[])
    setMyReviews(rv||[])
    setLoading(false)
  }

  async function submitReview(e) {
    e.preventDefault()
    if(form.rating===0) return toast.error("Please select a rating")
    const check = filterReviewContent(form.review)
    if(check.hasContactInfo) return toast.error("Reviews cannot contain contact details")
    if(check.hasBadWords) return toast.error("Please keep your review professional")
    setSubmitting(true)
    try {
      // Check if review already exists for this booking
      const { data: existing } = await supabase.from("reviews")
        .select("id").eq("booking_id", reviewing.id).eq("provider_id", user.id).maybeSingle()
      
      if(existing) {
        // Update existing review
        await supabase.from("reviews").update({
          customer_rating: form.rating,
          customer_review: form.review||null,
          reviewed_by: "provider"
        }).eq("id", existing.id)
      } else {
        // Insert new review
        await supabase.from("reviews").insert({
          booking_id: reviewing.id,
          customer_id: reviewing.customer_id,
          provider_id: user.id,
          customer_rating: form.rating,
          customer_review: form.review||null,
          reviewed_by: "provider"
        })
      }
      
      // Notify customer
      await supabase.from("notifications").insert({
        user_id: reviewing.customer_id,
        title: "You received a review Γ¡É",
        message: (profile?.business_name||profile?.first_name||"Your provider")+" rated your booking experience "+form.rating+" stars.",
        type: "info"
      })

      // Push notification
      try {
        await fetch(import.meta.env.VITE_SUPABASE_URL+"/functions/v1/send-push", {
          method:"POST",
          headers:{"Content-Type":"application/json","Authorization":"Bearer "+import.meta.env.VITE_SUPABASE_ANON_KEY},
          body:JSON.stringify({ user_id:reviewing.customer_id, title:"You received a review Γ¡É", message:(profile?.business_name||profile?.first_name||"Your provider")+" rated your experience "+form.rating+" stars." })
        })
      } catch(e) {}

      toast.success("Review submitted!")
      setReviewing(null)
      setForm({ rating:0, review:"" })
      load()
    } catch(err) { toast.error(err.message) }
    finally { setSubmitting(false) }
  }

  const reviewedBookingIds = new Set(myReviews.map(r=>r.booking_id))
  const pending = bookings.filter(b=>!reviewedBookingIds.has(b.id))
  const inp = { width:"100%", background:"#fff", border:"1px solid #e0e0e0", borderRadius:8, padding:"10px 12px", fontSize:13, outline:"none", fontFamily:"DM Sans,sans-serif", resize:"vertical", boxSizing:"border-box" }

  if(reviewing) return (
    <div>
      <button onClick={()=>setReviewing(null)} style={{ background:"none", border:"none", color:"#666", cursor:"pointer", fontSize:13, marginBottom:"1rem", padding:0 }}>ΓåÉ Back</button>
      <div style={{ background:"#fff", border:"1px solid #eee", borderRadius:12, padding:"1.25rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, marginBottom:2 }}>{reviewing.service_name}</div>
        <div style={{ fontSize:11, color:"#888", marginBottom:"0.5rem" }}>{reviewing.booking_date} ┬╖ {reviewing.customer?.first_name} {reviewing.customer?.last_name}</div>
        <hr style={{ border:"none", borderTop:"1px solid #f0f0f0", margin:"1rem 0" }}/>
        <div style={{ fontSize:12, color:"#666", marginBottom:8, textTransform:"uppercase", letterSpacing:"0.05em" }}>Rate this customer</div>
        <StarRating value={form.rating} onChange={v=>setForm(f=>({...f,rating:v}))}/>
        {form.rating>0&&<div style={{ fontSize:11, color:"#e6821e", marginTop:4, marginBottom:"1rem" }}>{["","Poor experience","Below average","Average","Good customer","Excellent customer"][form.rating]}</div>}
        <div style={{ fontSize:11, color:"#666", marginBottom:4, marginTop:"1rem" }}>Comments (optional)</div>
        <textarea value={form.review} onChange={e=>setForm(f=>({...f,review:e.target.value}))} rows={3}
          placeholder="Was the customer on time? Cooperative? Any issues?" style={inp}/>
        <div style={{ fontSize:10, color:"#888", marginTop:4, marginBottom:"1rem" }}>Note: Customer ratings help other providers make informed decisions. Keep it honest and professional.</div>
        <button onClick={submitReview} disabled={submitting||form.rating===0}
          style={{ width:"100%", background:form.rating>0?"#378add":"#ccc", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700, padding:"12px", cursor:form.rating>0?"pointer":"not-allowed" }}>
          {submitting?"Submitting...":"Submit Review"}
        </button>
      </div>
    </div>
  )

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:18, fontWeight:800, marginBottom:4 }}>Customer Reviews</div>
      <div style={{ fontSize:12, color:"#777", marginBottom:"1.25rem" }}>Rate your customers to help other providers.</div>
      <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:8, marginBottom:"1rem" }}>
        {[
          { label:"Completed", value:bookings.length, color:"#378add" },
          { label:"Reviewed", value:myReviews.length, color:"#1d9e75" },
          { label:"Pending", value:pending.length, color:"#e6821e" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.75rem", textAlign:"center", border:"1px solid #eee" }}>
            <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>
      <div style={{ display:"flex", gap:6, marginBottom:"1rem" }}>
        {[{k:"pending",l:"Pending ("+pending.length+")"},{k:"submitted",l:"Submitted ("+myReviews.length+")"}].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)} style={{ padding:"8px 16px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#378add":"#f0f0f0", color:tab===t.k?"#fff":"#555", fontWeight:tab===t.k?700:400 }}>{t.l}</button>
        ))}
      </div>
      {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
      {tab==="pending"&&(
        <div>
          {!loading&&pending.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No pending customer reviews</div>}
          {pending.map(b=>(
            <div key={b.id} style={{ background:"#fff", border:"1px solid #eee", borderRadius:10, padding:"1rem", marginBottom:8, display:"flex", alignItems:"center", gap:12 }}>
              <div style={{ width:42, height:42, background:"#eff6ff", borderRadius:9, display:"flex", alignItems:"center", justifyContent:"center", fontSize:20, flexShrink:0 }}>≡ƒæñ</div>
              <div style={{ flex:1 }}>
                <div style={{ fontSize:13, fontWeight:600 }}>{b.customer?.first_name} {b.customer?.last_name}</div>
                <div style={{ fontSize:11, color:"#888", marginTop:2 }}>{b.service_name} ┬╖ {b.booking_date}</div>
              </div>
              <button onClick={()=>{ setReviewing(b); setForm({rating:0,review:""}) }}
                style={{ background:"#378add", border:"none", borderRadius:8, color:"#fff", fontSize:12, fontWeight:700, padding:"8px 14px", cursor:"pointer", flexShrink:0 }}>
                Γ¡É Rate
              </button>
            </div>
          ))}
        </div>
      )}
      {tab==="submitted"&&(
        <div>
          {!loading&&myReviews.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No reviews submitted yet</div>}
          {myReviews.map(r=>(
            <div key={r.id} style={{ background:"#fff", border:"1px solid #eee", borderRadius:10, padding:"1rem", marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:6 }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:600 }}>Booking #{r.booking_id?.slice(0,8).toUpperCase()}</div>
                  <div style={{ fontSize:10, color:"#888" }}>{new Date(r.created_at).toLocaleDateString()}</div>
                </div>
                <StarRating value={r.customer_rating||0} color="#378add"/>
              </div>
              {r.customer_review&&<div style={{ fontSize:12, color:"#555", fontStyle:"italic" }}>"{r.customer_review}"</div>}
              {r.customer_response&&(
                <div style={{ background:"#f0fdf4", border:"1px solid #1d9e7520", borderRadius:8, padding:"0.5rem 0.75rem", marginTop:6 }}>
                  <div style={{ fontSize:10, color:"#1d9e75", fontWeight:600, marginBottom:2 }}>Customer response</div>
                  <div style={{ fontSize:12, color:"#333" }}>{r.customer_response}</div>
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { useState, useEffect, useRef } from "react"
import { supabase } from "../../lib/supabase"
import { ServicesIcon, VehicleIcon, PartsIcon, MarketplaceIcon, DiscoverIcon, PowerIcon, GlobeIcon, MechanicIcon, CloseIcon, OrdersIcon, WalletIcon, SuccessIcon, ShieldIcon, WarningIcon, DeliveryIcon, NotificationsIcon, ClockIcon, BookingsIcon } from "../../lib/cccIcons"
import ProviderOnboarding from "./ProviderOnboarding"
import { validateFile, sanitizeFilePath } from "../../lib/uploadValidation"
import { useAuth } from "../../contexts/AuthContext"
import { useLanguage } from "../../contexts/LanguageContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"


const TYPE_CONFIG = {
  garage:          { label:"Garage / Mechanic",   icon:"services", color:"#e6821e", focus:"bookings" },
  garage_premium:  { label:"Mobile Mechanic",      icon:"vehicle", color:"#378add", focus:"bookings" },
  parts_dealer:    { label:"Parts Dealer",          icon:"parts", color:"#8b5cf6", focus:"inventory" },
  accessories_shop:{ label:"Accessories Shop",      icon:"marketplace", color:"#e6821e", focus:"inventory" },
  tyre_shop:       { label:"Tyre Shop",             icon:"parts2", color:"#1d9e75", focus:"inventory" },
  auto_electrician:{ label:"Auto Electrician",      icon:"power", color:"#e6821e", focus:"bookings" },
  car_wash:        { label:"Car Wash",              icon:"discover", color:"#378add", focus:"bookings" },
  panel_beater:    { label:"Panel Beater",          icon:"mechanic", color:"#e24b4a", focus:"bookings" },
  auto_glass:      { label:"Auto Glass",            icon:"globe", color:"#1d9e75", focus:"bookings" },
}

export default function ProviderDashboard() {
  const { user, profile, updateProfile } = useAuth()
  const [hasGoService, setHasGoService] = useState(false)
  const [isOnlineGo, setIsOnlineGo] = useState(false)
  const { t, language } = useLanguage()
  const isMobile = useIsMobile()
  const fileRef = useRef(null)
  const [bookings, setBookings] = useState([])
  const [bookingStats, setBookingStats] = useState({ pending:0, confirmed:0, completed:0, earnings:0 })
  const [inventory, setInventory] = useState([])
  const [orders, setOrders] = useState([])
  const [orderStats, setOrderStats] = useState({ pending:0, revenue:0, items:0, lowStock:0 })
  const [loading, setLoading] = useState(true)
  const [showOnboarding, setShowOnboarding] = useState(false)
  const [commissionDisplay, setCommissionDisplay] = useState({ platform:10, provider:90 })
  const [showPolicy, setShowPolicy] = useState(!localStorage.getItem("ccc_policy_acknowledged"))
  const [uploadingPhoto, setUploadingPhoto] = useState(false)
  const providerType = profile?.provider_type || "garage"

  // Suspension check
  if (profile?.is_banned) return (
    <div style={{ padding:"2rem", textAlign:"center", color:"#e24b4a" }}>
      <div style={{ marginBottom:10, display:"flex", justifyContent:"center" }}><CloseIcon size={32} color="#e24b4a"/></div>
      <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, marginBottom:8 }}>Account Permanently Banned</div>
      <div style={{ fontSize:13, color:"#666" }}>Your account has been permanently banned due to repeated service violations. Contact support if you believe this is an error.</div>
    </div>
  )
  if (profile?.is_suspended) return (
    <div style={{ padding:"2rem", textAlign:"center", color:"#e6821e" }}>
      <div style={{ fontSize:32, marginBottom:10 }}>ΓÅ╕∩╕Å</div>
      <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, marginBottom:8 }}>Account Suspended</div>
      <div style={{ fontSize:13, color:"#666", marginBottom:8 }}>Your account has been temporarily suspended due to a service claim. You cannot accept new bookings during this period.</div>
      {profile?.suspension_expires_at&&<div style={{ fontSize:12, color:"#e6821e" }}>Suspension lifts: {new Date(profile.suspension_expires_at).toLocaleString()}</div>}
      <div style={{ fontSize:11, color:"#888", marginTop:8 }}>Contact support at carcareconnect254@gmail.com to appeal.</div>
    </div>
  )
  const config = TYPE_CONFIG[providerType] || TYPE_CONFIG.garage
  const isInventoryFocus = config.focus === "inventory"

  useEffect(() => {
    if(profile && !profile.onboarding_complete) setShowOnboarding(true)
  }, [profile])

  useEffect(() => {
    if (!user) return
    load()
    supabase.from("commission_rates").select("platform_rate,provider_rate").eq("provider_type", providerType).maybeSingle()
      .then(({ data }) => { if (data) setCommissionDisplay({ platform:Math.round(data.platform_rate*100), provider:Math.round(data.provider_rate*100) }) })
    const sub = supabase.channel("prov-dash-v2")
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"bookings", filter:`provider_id=eq.${user.id}` }, payload => {
        load()
        toast.success(`New booking: ${payload.new.service_name} ≡ƒÄë`, { duration:10000 })
      })
      .on("postgres_changes", { event:"UPDATE", schema:"public", table:"bookings", filter:`provider_id=eq.${user.id}` }, () => load())
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"orders", filter:`provider_id=eq.${user.id}` }, payload => { load(); toast.success(`New order received! ≡ƒôª Order #${payload.new.order_number||""}`, { duration:10000 }) })
      .on("postgres_changes", { event:"UPDATE", schema:"public", table:"orders", filter:`provider_id=eq.${user.id}` }, () => load())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function load() {
    setLoading(true)
    const [{ data: bks }, { data: inv }, { data: ords }, { data: goSvc }, { data: prof }] = await Promise.all([
      supabase.from("bookings").select("*").eq("provider_id", user.id).eq("is_archived", false).order("created_at",{ascending:false}).limit(10),
      supabase.from("inventory").select("*").eq("provider_id", user.id).order("created_at",{ascending:false}),
      supabase.from("orders").select("*, order_items(*)").eq("provider_id", user.id).order("created_at",{ascending:false}).limit(10),
      supabase.from("services").select("id").eq("provider_id", user.id).eq("category","go_service").eq("is_active", true).limit(1),
      supabase.from("profiles").select("is_online").eq("id", user.id).maybeSingle(),
    ])
    setHasGoService((goSvc||[]).length > 0)
    setIsOnlineGo(!!prof?.is_online)
    const b = bks||[]; const i = inv||[]; const o = ords||[]
    setBookings(b); setInventory(i); setOrders(o)
    setBookingStats({ pending:b.filter(x=>x.status==="pending").length, confirmed:b.filter(x=>x.status==="confirmed").length, completed:b.filter(x=>x.status==="completed").length, earnings:b.filter(x=>x.status==="completed").reduce((s,x)=>s+Number(x.provider_earnings||0),0) })
    setOrderStats({ pending:o.filter(x=>x.status==="pending").length, revenue:o.filter(x=>x.status==="delivered").reduce((s,x)=>s+Number(x.provider_earnings||0),0), items:i.length, lowStock:i.filter(x=>x.stock_quantity<=5&&x.is_active).length })
    setLoading(false)
  }

  async function updateBookingStatus(id, status) {
    const { error } = await supabase.from("bookings").update({ status }).eq("id",id).eq("provider_id",user.id)
    if (error) return toast.error(error.message)
    toast.success("Booking "+status); load()
  }

  async function updateOrderStatus(id, status) {
    await supabase.from("orders").update({ status }).eq("id",id)
    toast.success("Order "+status); load()
  }

  async function uploadPhoto(e) {
    const file = e.target.files[0]
    if (!file) return
    const _v = validateFile(file, "image")
    if (!_v.valid) { toast.error(_v.error); return }
    if (file.size > 5*1024*1024) return toast.error("Photo must be under 5MB")
    setUploadingPhoto(true)
    try {
      const ext = file.name.split(".").pop()
      const path = `${user.id}/profile-${Date.now()}.${ext}`
      const { error } = await supabase.storage.from("provider-photos").upload(path, file, { upsert:true })
      if (error) throw error
      const { data } = supabase.storage.from("provider-photos").getPublicUrl(path)
      await updateProfile({ profile_photo_url: data.publicUrl })
      toast.success("Photo updated!")
    } catch(e) { toast.error(e.message) }
    finally { setUploadingPhoto(false) }
  }

  const SC = { pending:"#e6821e", confirmed:"#378add", "in-progress":"#8b5cf6", completed:"#1d9e75", cancelled:"#e24b4a" }
  const initials = `${profile?.first_name?.[0]||""}${profile?.last_name?.[0]||""}`.toUpperCase()
  const businessName = profile?.business_name||`${profile?.first_name||""} ${profile?.last_name||""}`

  return (
    <div style={{ margin:"-1rem", fontFamily:"DM Sans,sans-serif" }}>
      {showOnboarding && <ProviderOnboarding onComplete={()=>{ setShowOnboarding(false); window.location.reload() }} />}

      {/* STYLE 1 - Colored header */}
      <div style={{ background:config.color, padding:"1.25rem 1.25rem 2.5rem" }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
          <div style={{ flex:1, minWidth:0 }}>
            <div style={{ fontSize:11, color:"rgba(255,255,255,0.75)", marginBottom:2 }}>
              {new Date().toLocaleDateString("en-KE",{weekday:"long",day:"numeric",month:"long"})}
            </div>
            <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:"#fff", marginBottom:2 }}>
              {businessName}
            </div>
            <div style={{ fontSize:11, color:"rgba(255,255,255,0.85)" }}>
              {config.icon} {config.label} ┬╖ Keep {commissionDisplay.provider}%
            </div>
            {profile?.is_verified&&(
              <div style={{ fontSize:10, color:"#fff", marginTop:4, background:"rgba(255,255,255,0.2)", borderRadius:20, padding:"2px 10px", display:"inline-block" }}>
                Γ£ô Verified
              </div>
            )}
          </div>
          {/* Profile photo */}
          <div onClick={()=>fileRef.current?.click()} style={{ width:52, height:52, borderRadius:12, background:"rgba(255,255,255,0.2)", border:"2px solid rgba(255,255,255,0.4)", display:"flex", alignItems:"center", justifyContent:"center", cursor:"pointer", overflow:"hidden", flexShrink:0 }}>
            {profile?.profile_photo_url
              ? <img src={profile.profile_photo_url} alt="Profile" style={{ width:"100%", height:"100%", objectFit:"cover" }}/>
              : <span style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:"#fff" }}>{initials||"?"}</span>
            }
          </div>
          <input ref={fileRef} type="file" accept="image/*" onChange={uploadPhoto} style={{ display:"none" }}/>
        </div>
      </div>

      {/* Floating stats card */}
      <div style={{ margin:"-1.25rem 1rem 1rem", background:"#fff", borderRadius:16, padding:"1rem", boxShadow:"0 4px 20px rgba(0,0,0,0.08)", border:"1px solid #f0f0f0" }}>
        {isInventoryFocus ? (
          <div style={{ display:"grid", gridTemplateColumns:"repeat(2,1fr)", gap:8 }}>
            {[
              { label:"Pending orders", value:orderStats.pending, color:orderStats.pending>0?"#e6821e":"#555", icon:"≡ƒ¢Æ" },
              { label:"Inventory items", value:orderStats.items, color:"#378add", icon:"orders" },
              { label:"Low stock", value:orderStats.lowStock, color:orderStats.lowStock>0?"#e24b4a":"#555", icon:"ΓÜá∩╕Å" },
              { label:"Revenue", value:"KES "+orderStats.revenue.toLocaleString(), color:"#1d9e75", icon:"wallet" },
            ].map(s=>(
              <div key={s.label} style={{ background:s.pulse?"#fff8f0":"#f8f8f8", borderRadius:10, padding:"0.75rem", display:"flex", alignItems:"center", gap:8, border:s.pulse?"2px solid #e6821e30":"2px solid transparent", boxShadow:s.pulse?"0 0 8px #e6821e20":"none" }}>
                <div style={{ display:"flex", justifyContent:"center" }}>
              {s.icon==="orders"?<OrdersIcon size={20} color={s.color}/>:
               s.icon==="wallet"?<WalletIcon size={20} color={s.color}/>:
               s.icon==="success"?<SuccessIcon size={20} color={s.color}/>:
               <ServicesIcon size={20} color={s.color}/>}
            </div>
                <div>
                  <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, color:s.color }}>{s.value}</div>
                  <div style={{ fontSize:10, color:"#888" }}>{s.label}</div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div style={{ display:"grid", gridTemplateColumns:"repeat(2,1fr)", gap:8 }}>
            {[
              { label:"Pending", value:bookingStats.pending, color:"#e6821e", icon:"clock", pulse:bookingStats.pending>0 },
              { label:"Confirmed", value:bookingStats.confirmed, color:"#378add", icon:"bookings" },
              { label:"Completed", value:bookingStats.completed, color:"#1d9e75", icon:"success" },
              { label:"Earnings", value:"KES "+Number(bookingStats.earnings).toLocaleString(), color:"#8b5cf6", icon:"wallet" },
            ].map(s=>(
              <div key={s.label} style={{ background:"#f8f8f8", borderRadius:10, padding:"0.75rem", display:"flex", alignItems:"center", gap:8 }}>
