                I understand
              </button>
              <button onClick={()=>window.open("/terms","_blank")}
                style={{ background:"none", border:"1px solid #e24b4a40", borderRadius:8, color:"#e24b4a", fontSize:12, padding:"9px 14px", cursor:"pointer" }}>
                Read policy
              </button>
            </div>
          </div>
        )}

        {/* Guarantee reminder */}
        {!showPolicy&&(
          <div style={{ background:"#fff5f5", border:"1px solid #e24b4a20", borderRadius:10, padding:"0.75rem", marginBottom:"1rem", display:"flex", justifyContent:"space-between", alignItems:"center" }}>
            <div style={{ fontSize:11, color:"#888", display:"flex", alignItems:"center", gap:4 }}><ShieldIcon size={11} color="#888"/> Service Guarantee active ΓÇö deliver quality service</div>
            <button onClick={()=>setShowPolicy(true)} style={{ background:"none", border:"none", color:"#e24b4a", fontSize:11, cursor:"pointer" }}>View policy</button>
          </div>
        )}

        {/* INVENTORY FOCUS */}
        {isInventoryFocus&&(
          <>
            {orderStats.lowStock>0&&(
              <div style={{ background:"#fff5f5", border:"1px solid #e24b4a40", borderRadius:10, padding:"0.75rem", marginBottom:"1rem", display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                <div style={{ fontSize:13, color:"#e24b4a", fontWeight:600, display:"flex", alignItems:"center", gap:4 }}><WarningIcon size={13} color="#e24b4a"/> {orderStats.lowStock} item{orderStats.lowStock>1?"s":""} low on stock</div>
                <a href="/dashboard/inventory" style={{ fontSize:11, color:"#e6821e", textDecoration:"none" }}>Manage ΓåÆ</a>
              </div>
            )}
            {orderStats.pending>0&&(
              <div style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:10, padding:"0.75rem", marginBottom:"1rem", display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                <div style={{ fontSize:13, color:"#e6821e", fontWeight:600, display:"flex", alignItems:"center", gap:4 }}><OrdersIcon size={13} color="#e6821e"/> {orderStats.pending} order{orderStats.pending>1?"s":""} waiting</div>
                <a href="/dashboard/orders" style={{ fontSize:11, color:"#e6821e", textDecoration:"none" }}>View ΓåÆ</a>
              </div>
            )}
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10, marginBottom:"1rem" }}>
              {[
                { href:"/dashboard/inventory", icon:"orders", label:"Inventory", desc:"Add, edit, update stock", color:config.color },
                { href:"/dashboard/orders", icon:"marketplace", label:"Orders", desc:"Confirm, pack, dispatch", color:"#1d9e75" },
              ].map(q=>(
                <a key={q.label} href={q.href} style={{ background:"#f8f8f8", border:`1px solid ${q.color}20`, borderRadius:12, padding:"1rem", textDecoration:"none", display:"block" }}>
                  <div style={{ marginBottom:6 }}>{q.icon==="orders"?<PartsIcon size={24} color={q.color}/>:<MarketplaceIcon size={24} color={q.color}/>}</div>
                  <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:q.color, marginBottom:2 }}>{q.label}</div>
                  <div style={{ fontSize:11, color:"#888" }}>{q.desc}</div>
                </a>
              ))}
            </div>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#000", marginBottom:"0.75rem" }}>Recent orders</div>
            {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
            {!loading&&orders.length===0&&(
              <div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem", background:"#f8f8f8", borderRadius:12 }}>
                <div style={{ marginBottom:8, display:"flex", justifyContent:"center" }}><NotificationsIcon size={32} color="#ccc"/></div>
                No orders yet ΓÇö add inventory to start selling
              </div>
            )}
            {orders.slice(0,5).map(o=>(
              <div key={o.id} style={{ background:"#fff", border:"0.5px solid #eee", borderRadius:12, padding:"0.85rem", marginBottom:8 }}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                  <div>
                    <div style={{ fontSize:13, fontWeight:600, color:"#000" }}>#{o.order_number}</div>
                    <div style={{ fontSize:11, color:"#888" }}>{o.fulfillment_type==="delivery"?<><DeliveryIcon size={12} color="#378add"/> Delivery</>:"Pickup"} ┬╖ {new Date(o.created_at).toLocaleDateString()}</div>
                    <div style={{ fontSize:11, color:"#888" }}>{o.order_items?.length||0} item(s)</div>
                  </div>
                  <div style={{ textAlign:"right" }}>
                    <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#e6821e" }}>KES {Number(o.subtotal||0).toLocaleString()}</div>
                    <span style={{ fontSize:10, padding:"2px 8px", borderRadius:8, background:"#f5f5f5", color:"#555" }}>{o.status}</span>
                  </div>
                </div>
                {o.status==="pending"&&(
                  <div style={{ display:"flex", gap:8, marginTop:8 }}>
                    <button onClick={()=>updateOrderStatus(o.id,"confirmed")} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"5px 12px", cursor:"pointer", fontWeight:600 }}>Confirm</button>
                    <button onClick={()=>updateOrderStatus(o.id,"cancelled")} style={{ background:"none", border:"1px solid #e24b4a30", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>Cancel</button>
                  </div>
                )}
              </div>
            ))}
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#000", margin:"1rem 0 0.75rem" }}>Your inventory</div>
            {inventory.slice(0,5).map(item=>(
              <div key={item.id} style={{ background:"#fff", border:"0.5px solid #eee", borderRadius:10, padding:"0.75rem 1rem", marginBottom:6, display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                <div>
                  <div style={{ fontSize:12, fontWeight:600, color:"#000" }}>{item.name}</div>
                  <div style={{ fontSize:10, color:"#888" }}>{item.category} ┬╖ {item.stock_quantity} {item.unit}s in stock</div>
                </div>
                <div style={{ textAlign:"right" }}>
                  <div style={{ fontSize:13, fontWeight:700, color:"#e6821e" }}>KES {Number(item.price).toLocaleString()}</div>
                  {item.stock_quantity<=5&&<div style={{ fontSize:9, color:"#e24b4a", display:"flex", alignItems:"center", gap:2 }}><WarningIcon size={9} color="#e24b4a"/> Low stock</div>}
                </div>
              </div>
            ))}
            {inventory.length===0&&!loading&&(
              <div style={{ color:"#888", fontSize:12, textAlign:"center", padding:"1rem" }}>
                No inventory yet ΓÇö <a href="/dashboard/inventory" style={{ color:config.color }}>add items</a>
              </div>
            )}
          </>
        )}

        {/* BOOKING FOCUS */}
        {!isInventoryFocus&&(
          <>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#000", marginBottom:"0.75rem" }}>
              Recent bookings
            </div>
            {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
            {!loading&&bookings.length===0&&(
              <div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem", background:"#f8f8f8", borderRadius:12 }}>
                <div style={{ marginBottom:8, display:"flex", justifyContent:"center" }}><NotificationsIcon size={32} color="#ccc"/></div>
                No bookings yet
              </div>
            )}
            {bookings.map(b=>(
              <div key={b.id} style={{ background:"#fff", border:"0.5px solid #eee", borderRadius:12, padding:"0.85rem", marginBottom:8 }}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
                  <div style={{ flex:1, minWidth:0, marginRight:8 }}>
                    <div style={{ fontSize:13, fontWeight:500, color:"#000", marginBottom:2 }}>{b.service_name}</div>
                    <div style={{ fontSize:11, color:"#888" }}>{b.booking_date} ┬╖ {b.booking_time?.slice(0,5)}</div>
                    {b.booking_number&&<div style={{ fontSize:10, color:"#aaa", marginTop:2 }}>#{b.booking_number}</div>}
                  </div>
                  <div style={{ textAlign:"right", flexShrink:0 }}>
                    <span style={{ fontSize:10, fontWeight:500, padding:"2px 8px", borderRadius:20, background:`${SC[b.status]||"#888"}15`, color:SC[b.status]||"#888", border:`1px solid ${SC[b.status]||"#888"}30` }}>
                      {b.status}
                    </span>
                    <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#e6821e", marginTop:4 }}>
                      KES {Number(b.total_amount||0).toLocaleString()}
                    </div>
                  </div>
                </div>
                <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                  {b.status==="pending"&&<button onClick={()=>updateBookingStatus(b.id,"confirmed")} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>Confirm</button>}
                  {b.status==="confirmed"&&<button onClick={()=>updateBookingStatus(b.id,"in-progress")} style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>Start service</button>}
                  {b.status==="in-progress"&&<button onClick={()=>updateBookingStatus(b.id,"completed")} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>Complete</button>}
                  {(b.status==="pending"||b.status==="confirmed")&&<button onClick={()=>updateBookingStatus(b.id,"cancelled")} style={{ background:"none", border:"1px solid #e24b4a30", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>Cancel</button>}
                </div>
              </div>
            ))}
          </>
        )}
      </div>
    </div>
  )
}

import useIsMobile from "../../lib/useIsMobile"
import { useEffect, useState } from "react"
import { useLanguage } from "../../contexts/LanguageContext"
import { downloadInvoice } from "../../lib/invoice"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"

export default function ProviderEarnings() {
  const isMobile = useIsMobile()
  const { user, profile } = useAuth()
  const { t, language } = useLanguage()
  const [bookings, setBookings] = useState([])
  const [loading, setLoading] = useState(true)
  const [period, setPeriod] = useState("all")

  useEffect(() => { if (user) load() }, [user])

  async function load() {
    const { data } = await supabase.from("bookings")
      .select("*")
      .eq("provider_id", user.id)
      .in("status", ["completed", "in-progress"]).eq("is_archived", false)
      .order("booking_date", { ascending:false })
    setBookings(data||[])
    setLoading(false)
  }

  const now = new Date()
  const filtered = bookings.filter(b => {
    if (period === "all") return true
    const d = new Date(b.booking_date)
    if (period === t("today")) return b.booking_date === now.toISOString().split("T")[0]
    if (period === "week") return (now - d) <= 7*24*60*60*1000
    if (period === "month") return d.getMonth()===now.getMonth() && d.getFullYear()===now.getFullYear()
    return true
  })

  const totalRevenue = filtered.reduce((s,b)=>s+Number(b.total_amount),0)
  const totalEarned = filtered.filter(b=>b.status==="completed").reduce((s,b)=>s+Number(b.provider_earnings||0),0)
  const totalPending = filtered.filter(b=>b.status==="in-progress").reduce((s,b)=>s+Number(b.provider_earnings||0),0)
  const totalCommission = filtered.reduce((s,b)=>s+Number(b.platform_commission||0),0)

  const byMonth = bookings.reduce((acc,b) => {
    const month = b.booking_date?.slice(0,7)
    if (!month) return acc
    if (!acc[month]) acc[month] = { revenue:0, earned:0, count:0 }
    acc[month].revenue += Number(b.total_amount)
    acc[month].earned += Number(b.provider_earnings||0)
    acc[month].count += 1
    return acc
  }, {})

  const months = Object.entries(byMonth).sort((a,b)=>b[0].localeCompare(a[0])).slice(0,6)
  const maxEarned = Math.max(...months.map(([,v])=>v.earned), 1)

  return (
    <div>
      <div style={{ display:"flex", gap:6, marginBottom:"1.25rem", flexWrap:"wrap" }}>
        {[{k:t("today"),l:t("today")},{k:"week",l:language==="sw"?"Wiki hii":"This week"},{k:"month",l:language==="sw"?"Mwezi huu":"This month"},{k:"all",l:language==="sw"?"Wakati wote":"All time"}].map(t=>(
          <button key={t.k} onClick={()=>setPeriod(t.k)}
            style={{ padding:"7px 14px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:period===t.k?"#e6821e":"#555555", color:period===t.k?"#fff":"#666", fontFamily:"'DM Sans',sans-serif", fontWeight:period===t.k?700:400 }}>
            {t.l}
          </button>
        ))}
      </div>

      <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"repeat(3,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:t("earnings"), value:`KES ${totalEarned.toFixed(2)}`, color:"#e6821e" },
          { label:"Total revenue", value:`KES ${totalRevenue.toFixed(2)}` },
          { label:"Total earned", value:`KES ${totalEarned.toFixed(2)}`, color:"#1d9e75" },
          { label:"Pending earnings", value:`KES ${totalPending.toFixed(2)}`, color:"#e6821e" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#ffffff", borderRadius:10, padding:"1rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontSize:11, color:"#777777", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:6 }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:22, fontWeight:800, color:s.color||"#000000" }}>{s.value}</div>
            <div style={{ fontSize:11, color:"#777777", marginTop:4 }}>{filtered.length} completed booking{filtered.length!==1?"s":""}</div>
          </div>
        ))}
      </div>

      {months.length > 0 && (
        <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem", marginBottom:"1.5rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:"1rem", color:"#000000" }}>Monthly earnings</div>
          <div style={{ display:"flex", gap:8, alignItems:"flex-end", height:120 }}>
            {months.reverse().map(([month, data])=>(
              <div key={month} style={{ flex:1, display:"flex", flexDirection:"column", alignItems:"center", gap:4 }}>
                <div style={{ fontSize:10, color:"#e6821e", fontWeight:600 }}>KES {data.earned.toFixed(0)}</div>
                <div style={{ width:"100%", background:"#e6821e", borderRadius:"4px 4px 0 0", height:`${Math.max(4,(data.earned/maxEarned)*80)}px`, transition:"height 0.5s" }}/>
                <div style={{ fontSize:9, color:"#777777", textAlign:"center" }}>
                  {new Date(month+"-01").toLocaleString("default",{month:"short"})}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:10, color:"#000000" }}>Completed bookings</div>
      {loading&&<div style={{ color:"#777777", fontSize:13 }}>Loading...</div>}
      {!loading&&filtered.length===0&&<div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"1.5rem" }}>No completed bookings in this period</div>}
      {filtered.map(b=>(
        <div key={b.id} style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:8, display:"flex", alignItems:"center", gap:12 }}>
          <div style={{ flex:1 }}>
            <div style={{ fontSize:13, fontWeight:500, color:"#000000" }}>{b.service_name}</div>
            <div style={{ fontSize:11, color:"#777777", marginTop:2 }}>{b.booking_date} ┬╖ #{b.booking_number}</div>
          </div>
          <div style={{ textAlign:"right" }}>
              <button onClick={()=>downloadInvoice(b, profile)} style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:6, color:"#378add", fontSize:10, padding:"4px 8px", cursor:"pointer", marginBottom:4, display:"block" }}>Invoice</button>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:b.status==="completed"?"#1d9e75":"#e6821e" }}>{b.status==="completed"?"+ ":"ΓÅ│ "}KES {Number(b.provider_earnings||0).toFixed(2)}</div>
            <div style={{ fontSize:9, color:b.status==="completed"?"#1d9e75":"#e6821e", fontWeight:600 }}>{b.status==="completed"?"Earned":"In progress"}</div>
            <div style={{ fontSize:10, color:"#777777" }}>of KES {Number(b.total_amount).toFixed(2)}</div>
          </div>
        </div>
      ))}
    </div>
  )
}

import { useEffect, useState, useRef } from "react"
import { supabase } from "../../lib/supabase"
import { openExternal, openMapsNavigation } from "../../lib/openExternal"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

export default function ProviderGoRequests() {
  const locationWatchRef = useRef(null)
  const { user } = useAuth()
  const isMobile = useIsMobile()
  const [requests, setRequests] = useState([])
  const [mechanics, setMechanics] = useState([])
  const [loading, setLoading] = useState(true)
  const [assigning, setAssigning] = useState(null)
  const [reassigning, setReassigning] = useState(null)
  const [newMechanic, setNewMechanic] = useState("")
  const [selectedMechanic, setSelectedMechanic] = useState("")
  const [timers, setTimers] = useState({})
  const [showPartsRequest, setShowPartsRequest] = useState(null)
  const [nearbyInventory, setNearbyInventory] = useState([])
  const [selectedPart, setSelectedPart] = useState(null)
  const [partQty, setPartQty] = useState(1)
  const [requestingPart, setRequestingPart] = useState(false)
  const [isOnline, setIsOnline] = useState(false)
  const [togglingOnline, setTogglingOnline] = useState(false)

  useEffect(() => {
    if (!user) return
    supabase.from("profiles").select("is_online").eq("id", user.id).maybeSingle().then(({data}) => { if (data) setIsOnline(!!data.is_online) })
    load()
    requestPushPermission()
    const sub = supabase.channel("provider-go-requests")
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"go_service_requests", filter:`provider_id=eq.${user.id}` },
        payload => {
          playAlarm()
          sendPushNotification("≡ƒÜ¿ EMERGENCY GO REQUEST!", "Customer needs help urgently. Open CCC now!")
          toast("≡ƒÜ¿ NEW EMERGENCY ΓÇö Customer needs help NOW!", { duration:30000, icon:"≡ƒÜ¿", style:{ background:"#e24b4a", color:"#fff", fontWeight:800, fontSize:13 } })
          load()
          let count = 0
          const interval = setInterval(() => {
            count++
            if (count >= 4) { clearInterval(interval); return }
            playAlarm()
          }, 30000)
        })
      .on("postgres_changes", { event:"UPDATE", schema:"public", table:"go_service_requests", filter:`provider_id=eq.${user.id}` },
        () => load())
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  useEffect(() => {
    const interval = setInterval(() => {
      setTimers(prev => {
        const updated = { ...prev }
        requests.forEach(r => {
          if (r.status==="pending") {
            const sent = new Date(r.sent_at).getTime()
            const now = Date.now()
            const elapsed = Math.floor((now - sent) / 1000)
            const remaining = Math.max(0, 15*60 - elapsed)
            updated[r.id] = remaining
            if (remaining === 0) handleTimeout(r)
          }
        })
        return updated
      })
    }, 1000)
    return () => clearInterval(interval)
  }, [requests])

  function requestPushPermission() {
    if ("Notification" in window && Notification.permission === "default") {
      Notification.requestPermission()
    }
  }

  function playAlarm() {
    try {
      const ctx = new (window.AudioContext || window.webkitAudioContext)()
      const freqs = [880, 660, 880, 660, 1100]
      freqs.forEach((freq, i) => {
        const o = ctx.createOscillator()
        const g = ctx.createGain()
        o.connect(g); g.connect(ctx.destination)
        o.frequency.value = freq
        o.type = "square"
        g.gain.setValueAtTime(0.4, ctx.currentTime + i*0.25)
        g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + i*0.25 + 0.2)
        o.start(ctx.currentTime + i*0.25)
        o.stop(ctx.currentTime + i*0.25 + 0.2)
      })
    } catch(e) { /* audio playback failed - non-critical */ }
  }

  function sendPushNotification(title, body) {
    if ("Notification" in window && Notification.permission === "granted") {
      new Notification(title, { body, requireInteraction:true, tag:"go-emergency" })
    }
  }

  function startMechanicTracking(bookingId) {
    if (!navigator.geolocation) return
    if (locationWatchRef.current) navigator.geolocation.clearWatch(locationWatchRef.current)
    locationWatchRef.current = navigator.geolocation.watchPosition(
      async pos => {
        const { latitude, longitude } = pos.coords
        try {
          await supabase.from("mechanic_location_history").insert({
            mechanic_id: user.id,
            booking_id: bookingId,
            latitude,
            longitude,
            recorded_at: new Date().toISOString(),
          })
        } catch(err) { console.error("Mechanic location error:", err) }
      },
      err => console.error("GPS error:", err),
      { enableHighAccuracy: true, maximumAge: 5000, timeout: 10000 }
    )
  }

  function stopMechanicTracking() {
    if (locationWatchRef.current) {
      navigator.geolocation.clearWatch(locationWatchRef.current)
      locationWatchRef.current = null
    }
  }

  async function loadNearbyInventory(lat, lng) {
    const { data } = await supabase.from("inventory").select("*, profiles!inventory_provider_id_fkey(first_name,last_name,business_name,latitude,longitude)").eq("is_active", true).gt("stock_quantity", 0)
    if(lat && lng && data) {
      data.forEach(item => {
        const p = item.profiles
        if(p?.latitude && p?.longitude) {
          const dLat = (p.latitude-lat)*Math.PI/180
          const dLng = (p.longitude-lng)*Math.PI/180
          const a = Math.sin(dLat/2)**2+Math.cos(lat*Math.PI/180)*Math.cos(p.latitude*Math.PI/180)*Math.sin(dLng/2)**2
          item._distance = 6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))
        } else { item._distance = 999 }
      })
      data.sort((a,b)=>a._distance-b._distance)
    }
    setNearbyInventory(data||[])
  }
  async function requestPart(bookingId, customerId, address, lat, lng) {
    if(!selectedPart) return
    setRequestingPart(true)
    try {
      const part = nearbyInventory.find(i=>i.id===selectedPart)
      if(!part) throw new Error("Part not found")
      const total = part.price * partQty
      await supabase.from("go_parts_requests").insert({
        booking_id: bookingId, mechanic_id: user.id, inventory_id: part.id,
        provider_id: part.provider_id, quantity: partQty, unit_price: part.price,
        total_amount: total, customer_id: customerId,
        delivery_location_address: address, delivery_location_lat: lat, delivery_location_lng: lng, status: "pending"
      })
      await supabase.from("notifications").insert([
        { user_id: part.provider_id, title: "Part delivery request!", message: "Mechanic needs "+part.name+" x"+partQty+" at "+address+". KES "+total, type: "info" },
        { user_id: customerId, title: "Mechanic needs a part", message: "Your mechanic needs "+part.name+" ΓÇö KES "+total+". Supplier being contacted.", type: "info" }
      ])
      toast.success("Part request sent!")
      setShowPartsRequest(null); setSelectedPart(null); setPartQty(1)
    } catch(e) { toast.error(e.message) }
    finally { setRequestingPart(false) }
  }
  async function load() {
    const [{ data: reqs }, { data: mechs }] = await Promise.all([
      supabase.from("go_service_requests").select("*, bookings(*)").eq("provider_id", user.id).order("sent_at", { ascending:false }).limit(20),
      supabase.from("mechanics").select("*").eq("provider_id", user.id).eq("is_active", true).eq("is_available", true),
    ])
    setRequests(reqs||[])
    setMechanics(mechs||[])
    setLoading(false)
  }

  async function handleTimeout(request) {
    if (request.status !== "pending") return
    await supabase.from("go_service_requests").update({ status:"timeout", responded_at:new Date().toISOString() }).eq("id", request.id)
    load()
  }

  async function reassignMechanic(bookingId) {
    if(!newMechanic) return toast.error("Please select a mechanic")
    try {
      await supabase.from("bookings").update({ assigned_mechanic_id: newMechanic }).eq("id", bookingId)
      await supabase.from("mechanics").update({ is_available:false, current_booking_id:bookingId }).eq("id", newMechanic)
      const mech = mechanics.find(m=>m.id===newMechanic)
      if(mech?.user_id) {
        await supabase.from("notifications").insert({ user_id:mech.user_id, title:"≡ƒÜ¿ GO Service job assigned!", message:"You have been assigned a new emergency GO service job. Check your dashboard.", type:"error" })
      }
      toast.success("Mechanic reassigned!")
      setReassigning(null); setNewMechanic("")
      load()
    } catch(e) { toast.error(e.message) }
  }
  async function acceptRequest(request) {
    if (!selectedMechanic && mechanics.length > 0) return toast.error("Please select a mechanic to dispatch")
    try {
      await supabase.from("go_service_requests").update({ status:"accepted", responded_at:new Date().toISOString() }).eq("id", request.id)
      await supabase.from("bookings").update({
        status: "confirmed",
        provider_accepted_at: new Date().toISOString(),
        assigned_mechanic_id: selectedMechanic||null,
      }).eq("id", request.booking_id)
      if (selectedMechanic) {
        await supabase.from("mechanics").update({ is_available:false, current_booking_id:request.booking_id }).eq("id", selectedMechanic)
      }
      toast.success("Emergency accepted ΓÇö mechanic dispatched! ≡ƒÜ¿")
      // Start GPS tracking for this booking
      startMechanicTracking(request.booking_id)
      const mechanic = mechanics.find(m=>m.id===selectedMechanic)
      const mName = mechanic ? mechanic.first_name+" "+mechanic.last_name : "Our mechanic"
      const mPhone = mechanic?.phone || "Check notifications"
      const mSpec = mechanic?.specialization || "General Mechanic"
      const { data: bkData } = await supabase.from("bookings").select("customer_id").eq("id", request.booking_id).single()
      if (bkData?.customer_id) {
        await supabase.from("notifications").insert({
          user_id: bkData.customer_id,
          title: "≡ƒÜ¿ Mechanic dispatched ΓÇö help is on the way!",
          message: "Mechanic: "+mName+" | "+mSpec+" | Phone: "+mPhone+" | They are heading to your location now. Please stay safe.",
          type: "success"
        })
      }
      // Notify assigned mechanic
      if (selectedMechanic) {
        const { data: mechData } = await supabase.from("mechanics").select("user_id").eq("id", selectedMechanic).single()
        if (mechData?.user_id) {
          await supabase.from("notifications").insert({
            user_id: mechData.user_id,
            title: "≡ƒÜ¿ New GO Service job assigned!", 
            message: "Emergency: "+request.bookings?.emergency_type?.replace(/_/g," ")+" at "+request.bookings?.emergency_location_address+". Check your dashboard now!",
            type: "error"
          })
        }
      }
      setAssigning(null)
      setSelectedMechanic("")
      load()
    } catch(err) {
      toast.error(err.message)
    }
  }

  async function declineRequest(request) {
    if (!confirm("Decline this emergency request?")) return
    await supabase.from("go_service_requests").update({ status:"declined", responded_at:new Date().toISOString() }).eq("id", request.id)
    // Clear provider_id first - assign-go-provider refuses to run if the booking still shows
    // an assigned provider, which it would since that's the very provider who just declined
    await supabase.from("bookings").update({ provider_id: null }).eq("id", request.booking_id)
    // Trigger reassignment to the next nearest provider immediately - the timeout cron only
    // catches expired "pending" requests, never explicit declines, so without this the customer
    // would be stuck waiting until manual intervention
    await supabase.functions.invoke("assign-go-provider", { body: { booking_id: request.booking_id } })
    toast.success("Request declined")
    load()
  }

  function formatTime(seconds) {
    if (!seconds && seconds !== 0) return "15:00"
    const m = Math.floor(seconds/60)
    const s = seconds%60
    return `${m}:${s.toString().padStart(2,"0")}`
  }

  const pending = requests.filter(r=>r.status==="pending")
  const recent = requests.filter(r=>r.status!=="pending")

  const EMERGENCY_ICONS = { flat_tire:"≡ƒ¢₧", dead_battery:"≡ƒöï", out_of_fuel:"Γ¢╜", car_wont_start:"≡ƒöæ", overheating:"≡ƒîí∩╕Å", towing:"≡ƒÜÜ", other:"≡ƒÜù" }

  async function toggleOnline() {
    setTogglingOnline(true)
    const next = !isOnline
    const { error } = await supabase.from("profiles").update({ is_online: next }).eq("id", user.id)
    if (error) { toast.error(error.message) } else { setIsOnline(next); toast.success(next ? "You're online - ready for GO Service requests" : "You're offline") }
    setTogglingOnline(false)
  }
  return (
    <div>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", background:isOnline?"#f0fdf4":"#f5f5f5", border:`1px solid ${isOnline?"#1d9e7540":"#dddddd"}`, borderRadius:12, padding:"0.9rem 1rem", marginBottom:"1.5rem" }}>
        <div style={{ display:"flex", alignItems:"center", gap:8 }}>
          <div style={{ width:10, height:10, borderRadius:"50%", background:isOnline?"#1d9e75":"#999", boxShadow:isOnline?"0 0 8px #1d9e75":"none" }}/>
          <div>
            <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:isOnline?"#1d9e75":"#555" }}>{isOnline?"Online - receiving GO requests":"Offline"}</div>
            <div style={{ fontSize:11, color:"#888" }}>{isOnline?"Customers can be matched to you":"Go online to start receiving emergency requests"}</div>
          </div>
        </div>
        <button onClick={toggleOnline} disabled={togglingOnline}
          style={{ background:isOnline?"#e24b4a":"#1d9e75", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"9px 16px", cursor:togglingOnline?"not-allowed":"pointer" }}>
          {togglingOnline?"...":isOnline?"Go Offline":"Go Online"}
        </button>
      </div>
      {pending.length > 0 && (
        <div style={{ background:"#fff5f5", border:"2px solid #e24b4a", borderRadius:12, padding:"1rem", marginBottom:"1.5rem" }}>
          <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:10 }}>
            <div style={{ width:10, height:10, borderRadius:"50%", background:"#e24b4a", boxShadow:"0 0 8px #e24b4a" }}/>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#e24b4a" }}>
              ≡ƒÜ¿ {pending.length} Emergency request{pending.length!==1?"s":""} pending
            </div>
          </div>
          {pending.map(r=>(
            <div key={r.id} style={{ background:"#ffffff", borderRadius:10, padding:"1rem", marginBottom:10 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:10 }}>
                <div>
                  <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4 }}>
                    <span style={{ fontSize:20 }}>{EMERGENCY_ICONS[r.bookings?.emergency_type]||"≡ƒÜù"}</span>
                    <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#e24b4a" }}>
                      {r.bookings?.emergency_type?.replace(/_/g," ").toUpperCase()}
                    </div>
                  </div>
                  <div style={{ fontSize:12, color:"#555555", marginBottom:2 }}>≡ƒôì {r.bookings?.emergency_location_address}</div>
                  {r.bookings?.emergency_location_lat&&r.bookings?.emergency_location_lng&&(
                    <a href={`https://www.google.com/maps/dir/?api=1&destination=${r.bookings.emergency_location_lat},${r.bookings.emergency_location_lng}`}
                      target="_blank" rel="noopener noreferrer"
                      style={{ display:"inline-flex", alignItems:"center", gap:6, marginTop:4, marginBottom:4, background:"#4285f4", color:"#fff", borderRadius:8, padding:"6px 12px", fontSize:11, fontWeight:700, textDecoration:"none" }}>
                      ≡ƒù║∩╕Å Navigate to customer
                    </a>
                  )}
                  {r.bookings?.notes&&<div style={{ fontSize:11, color:"#666" }}>≡ƒô¥ {r.bookings.notes}</div>}
                  <div style={{ fontSize:11, color:"#e6821e", marginTop:4 }}>
                    ≡ƒÆ░ KES {Number(r.bookings?.total_amount||0).toLocaleString()} ┬╖ Your earnings: KES {Number(r.bookings?.provider_earnings||0).toFixed(0)}
                  </div>
                  <div style={{ fontSize:11, color:"#777777", marginTop:2 }}>Attempt {r.attempt_number} of 5</div>
                </div>
                <div style={{ textAlign:"center", flexShrink:0 }}>
                  <div style={{ fontFamily:"Syne", fontSize:24, fontWeight:800, color:timers[r.id]<60?"#e24b4a":"#e6821e" }}>
                    {formatTime(timers[r.id])}
                  </div>
                  <div style={{ fontSize:9, color:"#777777" }}>time left</div>
                </div>
              </div>

              {assigning===r.id&&mechanics.length>0&&(
                <div style={{ background:"#faf5ff", border:"1px solid #8b5cf630", borderRadius:8, padding:"0.75rem", marginBottom:10 }}>
                  <div style={{ fontSize:11, color:"#8b5cf6", marginBottom:8, fontWeight:600 }}>Select mechanic to dispatch:</div>
                  {mechanics.map(m=>(
                    <div key={m.id} onClick={()=>setSelectedMechanic(m.id)}
                      style={{ display:"flex", alignItems:"center", gap:8, padding:"6px", borderRadius:7, cursor:"pointer", background:selectedMechanic===m.id?"#1e0a3e":"transparent", marginBottom:4 }}>
                      <div style={{ width:28, height:28, borderRadius:"50%", background:"#f0fdf4", border:"1px solid #1d9e7540", display:"flex", alignItems:"center", justifyContent:"center", fontSize:11, fontWeight:800, color:"#1d9e75" }}>
                        {m.first_name[0]}{m.last_name[0]}
                      </div>
                      <div>
                        <div style={{ fontSize:12, color:"#000000" }}>{m.first_name} {m.last_name}</div>
                        <div style={{ fontSize:10, color:"#777777" }}>{m.specialization}</div>
                      </div>
                      {selectedMechanic===m.id&&<div style={{ marginLeft:"auto", color:"#8b5cf6", fontSize:14 }}>Γ£ô</div>}
                    </div>
                  ))}
      {showPartsRequest&&(
        <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.7)", zIndex:200, display:"flex", flexDirection:"column", justifyContent:"flex-end" }} onClick={()=>setShowPartsRequest(null)}>
          <div style={{ background:"#fff", borderRadius:"20px 20px 0 0", padding:"1.5rem", maxHeight:"80vh", overflowY:"auto" }} onClick={e=>e.stopPropagation()}>
            <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, marginBottom:4 }}>≡ƒöº Request a Part</div>
            <div style={{ fontSize:12, color:"#888", marginBottom:"1rem" }}>Select part from nearby suppliers</div>
            {nearbyInventory.length===0&&<div style={{ fontSize:12, color:"#888", textAlign:"center", padding:"1rem" }}>No parts available nearby</div>}
            {nearbyInventory.map(item=>(
              <div key={item.id} onClick={()=>setSelectedPart(item.id)} style={{ background:selectedPart===item.id?"#f3f0ff":"#f8f8f8", border:"1px solid "+(selectedPart===item.id?"#8b5cf6":"#eee"), borderRadius:10, padding:"0.75rem", marginBottom:8, cursor:"pointer" }}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                  <div><div style={{ fontSize:13, fontWeight:600 }}>{item.name}</div><div style={{ fontSize:11, color:"#888" }}>{item.profiles?.business_name||item.profiles?.first_name} ┬╖ {item._distance<999?item._distance.toFixed(1)+"km":""}</div><div style={{ fontSize:11, color:"#555" }}>Stock: {item.stock_quantity}</div></div>
                  <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#8b5cf6" }}>KES {Number(item.price).toLocaleString()}</div>
                </div>
              </div>
            ))}
            {selectedPart&&(
              <div style={{ marginTop:12 }}>
                <div style={{ display:"flex", gap:8, alignItems:"center", marginBottom:12 }}>
                  <button onClick={()=>setPartQty(q=>Math.max(1,q-1))} style={{ width:36, height:36, borderRadius:8, border:"1px solid #ddd", background:"#f5f5f5", fontSize:18, cursor:"pointer" }}>-</button>
                  <span style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, minWidth:30, textAlign:"center" }}>{partQty}</span>
                  <button onClick={()=>setPartQty(q=>q+1)} style={{ width:36, height:36, borderRadius:8, border:"1px solid #ddd", background:"#f5f5f5", fontSize:18, cursor:"pointer" }}>+</button>
                  <span style={{ fontSize:12, color:"#888" }}>KES {((nearbyInventory.find(i=>i.id===selectedPart)?.price||0)*partQty).toLocaleString()}</span>
                </div>
                <button onClick={()=>{ const r=requests.find(x=>x.booking_id===showPartsRequest); requestPart(showPartsRequest, r?.bookings?.customer_id, r?.bookings?.emergency_location_address, r?.bookings?.emergency_location_lat, r?.bookings?.emergency_location_lng) }} disabled={requestingPart} style={{ width:"100%", background:requestingPart?"#ccc":"#8b5cf6", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne", fontSize:14, fontWeight:700, padding:"13px", cursor:requestingPart?"not-allowed":"pointer" }}>{requestingPart?"Sending...":"Send Part Request"}</button>
              </div>
            )}
            <button onClick={()=>setShowPartsRequest(null)} style={{ width:"100%", background:"none", border:"1px solid #ddd", borderRadius:10, color:"#666", fontSize:13, padding:"11px", cursor:"pointer", marginTop:8 }}>Cancel</button>
          </div>
        </div>
      )}
                </div>
              )}

              <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
                <button onClick={()=>{ setAssigning(assigning===r.id?null:r.id); setSelectedMechanic("") }}
                  style={{ background:"#e24b4a", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"9px 18px", cursor:"pointer" }}>
                  {assigning===r.id?"Cancel":"≡ƒÜ¿ Accept & dispatch"}
                </button>
                {assigning===r.id&&(
                  <button onClick={()=>acceptRequest(r)} disabled={mechanics.length>0&&!selectedMechanic}
                    style={{ background:mechanics.length>0&&!selectedMechanic?"#555555":"#1d9e75", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"9px 18px", cursor:"pointer" }}>
                    Confirm dispatch
                  </button>
                )}
                <button onClick={()=>declineRequest(r)}
                  style={{ background:"none", border:"1px solid #e24b4a40", borderRadius:8, color:"#e24b4a", fontSize:12, padding:"9px 14px", cursor:"pointer" }}>
                  Decline
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#000000", marginBottom:"1rem" }}>
        Recent GO requests
      </div>

      {loading&&<div style={{ color:"#777777", fontSize:13 }}>Loading...</div>}
      {!loading&&recent.length===0&&pending.length===0&&(
        <div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"2rem" }}>
          <div style={{ fontSize:32, marginBottom:10 }}>≡ƒÜ¿</div>
          No GO service requests yet
        </div>
      )}

      {recent.map(r=>(
        <div key={r.id} style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:10, padding:"0.9rem", marginBottom:8 }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
            <div>
              <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4 }}>
                <span>{EMERGENCY_ICONS[r.bookings?.emergency_type]||"≡ƒÜù"}</span>
                <span style={{ fontSize:13, color:"#000000" }}>{r.bookings?.emergency_type?.replace(/_/g," ")}</span>
                <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:r.status==="accepted"?"#f0fdf4":r.status==="declined"?"#fff5f5":"#ffffff", color:r.status==="accepted"?"#1d9e75":r.status==="declined"?"#e24b4a":"#888" }}>{r.status}</span>
              </div>
              <div style={{ fontSize:11, color:"#777777" }}>≡ƒôì {r.bookings?.emergency_location_address}</div>
              {r.bookings?.emergency_location_lat&&r.bookings?.emergency_location_lng&&(
                <a href={`https://www.google.com/maps/dir/?api=1&destination=${r.bookings.emergency_location_lat},${r.bookings.emergency_location_lng}`}
                  target="_blank" rel="noopener noreferrer"
                  style={{ display:"inline-flex", alignItems:"center", gap:6, marginTop:4, marginBottom:4, background:"#4285f4", color:"#fff", borderRadius:8, padding:"5px 10px", fontSize:11, fontWeight:700, textDecoration:"none" }}>
                  ≡ƒù║∩╕Å Navigate to customer
                </a>
              )}
              <div style={{ fontSize:10, color:"#888888", marginTop:2 }}>{new Date(r.sent_at).toLocaleString()}</div>
              {r.bookings?.status==="in-progress"&&<button onClick={()=>{ setShowPartsRequest(r.booking_id); loadNearbyInventory(r.bookings?.emergency_location_lat, r.bookings?.emergency_location_lng) }} style={{ marginTop:8, background:"#8b5cf6", border:"none", borderRadius:8, color:"#fff", fontSize:11, fontWeight:700, padding:"6px 14px", cursor:"pointer" }}>≡ƒöº Request Part</button>}
              {r.status==="accepted"&&r.bookings?.status!=="in-progress"&&(
                reassigning===r.booking_id ? (
                  <div style={{ marginTop:8 }}>
                    <select value={newMechanic} onChange={e=>setNewMechanic(e.target.value)} style={{ width:"100%", padding:"6px 10px", borderRadius:8, border:"1px solid #ddd", fontSize:12, marginBottom:6 }}>
                      <option value="">Select mechanic</option>
                      {mechanics.map(m=><option key={m.id} value={m.id}>{m.first_name} {m.last_name} ┬╖ {m.specialization}</option>)}
                    </select>
                    <div style={{ display:"flex", gap:6 }}>
                      <button onClick={()=>reassignMechanic(r.booking_id)} style={{ flex:1, background:"#378add", border:"none", borderRadius:8, color:"#fff", fontSize:11, fontWeight:700, padding:"6px 10px", cursor:"pointer" }}>Γ£ô Confirm</button>
                      <button onClick={()=>{ setReassigning(null); setNewMechanic("") }} style={{ flex:1, background:"#f0f0f0", border:"none", borderRadius:8, color:"#555", fontSize:11, padding:"6px 10px", cursor:"pointer" }}>Cancel</button>
                    </div>
                  </div>
                ) : (
                  <button onClick={()=>setReassigning(r.booking_id)} style={{ marginTop:8, background:"#378add", border:"none", borderRadius:8, color:"#fff", fontSize:11, fontWeight:700, padding:"6px 14px", cursor:"pointer" }}>≡ƒæ¿ΓÇì≡ƒöº Reassign Mechanic</button>
                )
              )}
              </div>
            <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#e6821e" }}>
              KES {Number(r.bookings?.total_amount||0).toLocaleString()}
            </div>
          </div>
        </div>
      ))}
    </div>
  )
}

import { PartsIcon, MarketplaceIcon, VehicleIcon, ServicesIcon, OilIcon, PowerIcon, OrdersIcon, WarningIcon, EyeIcon, DeleteIcon, EditIcon } from "../../lib/cccIcons"
import { useEffect, useState, useRef } from "react"

import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import PhotoLightbox from "../shared/PhotoLightbox"
import toast from "react-hot-toast"

const CATEGORIES = [
  { key:"parts", label:"Parts", icon:"parts" },
  { key:"accessories", label:"Accessories", icon:"marketplace" },
  { key:"tyres", label:"Tyres", icon:"vehicle" },
  { key:"tools", label:"Tools", icon:"services" },
  { key:"oils", label:"Oils & Fluids", icon:"oil" },
  { key:"electrical", label:"Electrical", icon:"power" },
  { key:"body", label:"Body Parts", icon:"vehicle" },
  { key:"other", label:"Other", icon:"orders" },
]

const PROVIDER_CATEGORY_PRIORITY = {
  parts_dealer: ["parts","tools","electrical","body","other","accessories","oils","tyres"],
  accessories_shop: ["accessories","electrical","other","parts","tools","body","oils","tyres"],
  tyre_shop: ["tyres","tools","other","parts","accessories","electrical","body","oils"],
  auto_glass: ["body","tools","other","parts","accessories","electrical","oils","tyres"],
}

function getOrderedCategories(providerType) {
  const priority = PROVIDER_CATEGORY_PRIORITY[providerType]
  if (!priority) return CATEGORIES
  return [...CATEGORIES].sort((a,b) => priority.indexOf(a.key) - priority.indexOf(b.key))
}

const UNITS = ["piece","set","pair","litre","kg","box","roll"]

const EMPTY = {
  name:"", description:"", category:"parts", subcategory:"",
  price:"", stock_quantity:"", unit:"piece", brand:"",
  compatible_cars:"", is_active:true, photos:[], video_url:""
}

export default function ProviderInventory() {
  const { user, profile } = useAuth()
  const isMobile = useIsMobile()
  const [items, setItems] = useState([])
  const [loading, setLoading] = useState(true)
  const [showForm, setShowForm] = useState(false)
  const [editing, setEditing] = useState(null)
  const [form, setForm] = useState(EMPTY)
  const [saving, setSaving] = useState(false)
  const [uploadingPhoto, setUploadingPhoto] = useState(false)
  const [uploadingVideo, setUploadingVideo] = useState(false)
  const [videoUploadProgress, setVideoUploadProgress] = useState(0)
  const [photoPreview, setPhotoPreview] = useState(null)
  const photoRef = useRef(null)
  const [search, setSearch] = useState("")
  const [catFilter, setCatFilter] = useState("all")
  const [lightbox, setLightbox] = useState({ open:false, photos:[], index:0 })
  const [tab, setTab] = useState("inventory")

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("provider-inventory-live")
      .on("postgres_changes", { event:"*", schema:"public", table:"inventory", filter:"provider_id=eq."+user.id }, () => load())
      .on("postgres_changes", { event:"*", schema:"public", table:"orders", filter:"provider_id=eq."+user.id }, () => { toast("New order received! ≡ƒ¢Æ", { duration:5000 }); load() })
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function load() {
    const { data } = await supabase.from("inventory").select("*").eq("provider_id", user.id).order("created_at", { ascending:false })
    setItems(data||[])
    setLoading(false)
  }

  async function uploadItemPhoto(file) {
    if (!file) return null
    setUploadingPhoto(true)
    try {
      const ext = file.name.split(".").pop()
      const path = user.id + "/item-" + Date.now() + "." + ext
      const { error } = await supabase.storage.from("provider-photos").upload(path, file, { upsert:true })
      if (error) throw error
      const { data } = supabase.storage.from("provider-photos").getPublicUrl(path)
      return data.publicUrl
    } catch(e) { toast.error(e.message); return null }
    finally { setUploadingPhoto(false) }
  }

  async function save(e) {
    e.preventDefault()
    setSaving(true)
    try {
      let photoUrl = form.photos?.[0] || null
      if (photoRef.current?.files?.[0]) {
        photoUrl = await uploadItemPhoto(photoRef.current.files[0])
      }
      const payload = {
        ...form,
        provider_id: user.id,
        price: Number(form.price)||0,
        stock_quantity: Number(form.stock_quantity)||0,
        compatible_cars: form.compatible_cars ? form.compatible_cars.split(",").map(s=>s.trim()) : [],
        photos: photoUrl ? [photoUrl] : [],
        video_url: form.video_url||null,
      }
      if (editing) {
        await supabase.from("inventory").update(payload).eq("id", editing)
        toast.success("Item updated!")
      } else {
        await supabase.from("inventory").insert(payload)
        toast.success("Item added to inventory!")
      }
      setShowForm(false); setEditing(null); setForm(EMPTY); setPhotoPreview(null); load()
    } catch(e) { toast.error(e.message) }
    finally { setSaving(false) }
  }

  async function toggleActive(item) {
    await supabase.from("inventory").update({ is_active:!item.is_active }).eq("id", item.id)
    toast.success(item.is_active?"Item hidden from marketplace":"Item visible in marketplace")
    load()
  }

  async function deleteItem(id) {
    if (!confirm("Delete this item? This cannot be undone.")) return
    await supabase.from("inventory").delete().eq("id", id)
    toast.success("Item deleted")
    load()
  }

  async function updateStock(id, qty) {
    await supabase.from("inventory").update({ stock_quantity:qty, updated_at:new Date().toISOString() }).eq("id", id)
    if (qty<=3&&qty>0) toast("ΓÜá∩╕Å Low stock ΓÇö only "+qty+" left!", { icon:"ΓÜá∩╕Å", duration:5000 })
    if (qty===0) toast.error("Out of stock ΓÇö customers cannot order this item")
    load()
  }

  function startEdit(item) {
    setEditing(item.id)
    setForm({...item, compatible_cars:item.compatible_cars?.join(", ")||""})
    setPhotoPreview(null)
    setShowForm(true)
    window.scrollTo(0,0)
  }

  const orderedCategories = getOrderedCategories(profile?.provider_type)

  const filtered = items.filter(i=>{
    const matchCat = catFilter==="all"||i.category===catFilter
    const matchSearch = !search || i.name.toLowerCase().includes(search.toLowerCase()) || (i.brand||"").toLowerCase().includes(search.toLowerCase())
    return matchCat&&matchSearch
  })

  const totalItems = items.length
  const activeItems = items.filter(i=>i.is_active).length
  const lowStock = items.filter(i=>i.stock_quantity<=5&&i.stock_quantity>0&&i.is_active).length
  const outOfStock = items.filter(i=>i.stock_quantity===0&&i.is_active).length
  const totalValue = items.reduce((s,i)=>s+Number(i.price||0)*Number(i.stock_quantity||0),0)

  const inp = { width:"100%", background:"#f8f8f8", border:"1px solid #e5e5e5", borderRadius:8, padding:"10px 12px", color:"#000", fontSize:13, outline:"none", fontFamily:"DM Sans,sans-serif", marginBottom:10 }
  const lbl = { fontSize:11, color:"#666", display:"block", marginBottom:4, textTransform:"uppercase", letterSpacing:"0.05em" }

  return (
    <div>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:"1.25rem", flexWrap:"wrap", gap:10 }}>
        <div>
          <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:"#000" }}>Inventory</div>
          <div style={{ fontSize:12, color:"#777" }}>Manage your parts, accessories and products</div>
        </div>
        <button onClick={()=>{ setShowForm(true); setEditing(null); setForm(EMPTY); setPhotoPreview(null) }}
          style={{ background:"linear-gradient(135deg,#e6821e,#f09840)", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"10px 20px", cursor:"pointer", boxShadow:"0 4px 12px rgba(230,130,30,0.3)" }}>
          + Add item
        </button>
      </div>

      {/* Stats */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:8, marginBottom:"1.25rem" }}>
        {[
          { label:"Total", value:totalItems, color:"#000", bg:"#f8f8f8" },
          { label:"Active", value:activeItems, color:"#1d9e75", bg:"#f0fdf4" },
          { label:"Low stock", value:lowStock, color:lowStock>0?"#e6821e":"#888", bg:lowStock>0?"#fff8f0":"#f8f8f8" },
          { label:"Out of stock", value:outOfStock, color:outOfStock>0?"#e24b4a":"#888", bg:outOfStock>0?"#fff5f5":"#f8f8f8" },
        ].map(s=>(
          <div key={s.label} style={{ background:s.bg, borderRadius:12, padding:"0.75rem", border:"1px solid #eeeeee", textAlign:"center" }}>
            <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:s.color }}>{s.value}</div>
            <div style={{ fontSize:10, color:"#888", marginTop:2 }}>{s.label}</div>
          </div>
        ))}
      </div>

      {/* Stock value banner */}
      <div style={{ background:"linear-gradient(135deg,#e6821e,#f09840)", borderRadius:12, padding:"0.85rem 1.25rem", marginBottom:"1.25rem", display:"flex", justifyContent:"space-between", alignItems:"center" }}>
        <div style={{ fontSize:12, color:"rgba(255,255,255,0.85)" }}>Total stock value</div>
        <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:"#fff" }}>KES {totalValue.toLocaleString()}</div>
      </div>

      {/* Alerts */}
      {(lowStock>0||outOfStock>0)&&(
        <div style={{ background:"#fff8f0", border:"1px solid #e6821e30", borderRadius:10, padding:"0.75rem 1rem", marginBottom:"1rem", display:"flex", gap:8, alignItems:"center" }}>
          <WarningIcon size={16} color="#e6821e"/>
          <div style={{ fontSize:12, color:"#e6821e" }}>
            {outOfStock>0&&<span style={{ color:"#e24b4a", fontWeight:600 }}>{outOfStock} out of stock</span>}
            {outOfStock>0&&lowStock>0&&" ┬╖ "}
            {lowStock>0&&<span>{lowStock} low on stock</span>}
          </div>
        </div>
      )}

      {/* Add/Edit Form */}
      {showForm&&(
        <div style={{ background:"#ffffff", border:"1px solid #e6821e30", borderRadius:14, padding:"1.25rem", marginBottom:"1.5rem", boxShadow:"0 4px 16px rgba(230,130,30,0.1)" }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1.25rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#000" }}>{editing?"Γ£Å∩╕Å Edit item":"≡ƒôª Add new item"}</div>
            <button onClick={()=>{ setShowForm(false); setEditing(null); setForm(EMPTY); setPhotoPreview(null) }}
              style={{ background:"#f0f0f0", border:"none", borderRadius:"50%", width:30, height:30, cursor:"pointer", fontSize:16, display:"flex", alignItems:"center", justifyContent:"center" }}>├ù</button>
          </div>
          <form onSubmit={save}>
            <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"1fr 1fr", gap:10 }}>
              <div>
                <label style={lbl}>Item name *</label>
                <input style={inp} value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))} required placeholder="e.g. Toyota Vitz Brake Pads"/>
              </div>
              <div>
                <label style={lbl}>Brand</label>
                <input style={inp} value={form.brand} onChange={e=>setForm(f=>({...f,brand:e.target.value}))} placeholder="e.g. Bosch, Genuine Toyota"/>
              </div>
              <div>
                <label style={lbl}>Category</label>
                <select style={inp} value={form.category} onChange={e=>setForm(f=>({...f,category:e.target.value}))}>
                  {orderedCategories.map(c=><option key={c.key} value={c.key}>{c.icon} {c.label}</option>)}
                </select>
              </div>
              <div>
                <label style={lbl}>Subcategory</label>
                <input style={inp} value={form.subcategory} onChange={e=>setForm(f=>({...f,subcategory:e.target.value}))} placeholder="e.g. Front brake pads"/>
              </div>
              <div>
                <label style={lbl}>Price (KES) *</label>
                <input type="number" style={inp} value={form.price} onChange={e=>setForm(f=>({...f,price:e.target.value}))} required placeholder="0" min="0"/>
              </div>
              <div>
                <label style={lbl}>Stock & unit</label>
                <div style={{ display:"flex", gap:6 }}>
                  <input type="number" style={{...inp, marginBottom:0, flex:1}} value={form.stock_quantity} onChange={e=>setForm(f=>({...f,stock_quantity:e.target.value}))} placeholder="0" min="0"/>
                  <select style={{...inp, marginBottom:0, width:"auto"}} value={form.unit} onChange={e=>setForm(f=>({...f,unit:e.target.value}))}>
                    {UNITS.map(u=><option key={u} value={u}>{u}</option>)}
                  </select>
                </div>
              </div>
            </div>

            <div>
              <label style={lbl}>Compatible cars</label>
              <input style={inp} value={form.compatible_cars} onChange={e=>setForm(f=>({...f,compatible_cars:e.target.value}))} placeholder="e.g. Toyota Vitz, Toyota Axio, Toyota Fielder"/>
            </div>
            <div>
              <label style={lbl}>Description</label>
              <textarea style={{...inp, resize:"vertical", minHeight:70}} value={form.description} onChange={e=>setForm(f=>({...f,description:e.target.value}))} placeholder="Describe this item..."/>
            </div>

            {/* Photo upload */}
            <div style={{ marginBottom:12 }}>
              <label style={lbl}>Item photo</label>
              {(photoPreview||form.photos?.[0])&&(
                <div style={{ position:"relative", marginBottom:8 }}>
                  <img src={photoPreview||form.photos[0]} alt="Preview" style={{ width:"100%", maxHeight:160, objectFit:"cover", borderRadius:10 }}/>
                  <button type="button" onClick={()=>{ setPhotoPreview(null); setForm(f=>({...f,photos:[]})); if(photoRef.current) photoRef.current.value="" }}
                    style={{ position:"absolute", top:6, right:6, background:"rgba(0,0,0,0.5)", border:"none", borderRadius:"50%", width:24, height:24, color:"#fff", fontSize:12, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center" }}>├ù</button>
                </div>
              )}
              <label style={{ display:"block", width:"100%", background:"#f8f8f8", border:"2px dashed #e5e5e5", borderRadius:10, padding:"12px", color:"#888", fontSize:12, cursor:"pointer", textAlign:"center" }}>
                {uploadingPhoto?"ΓÅ│ Uploading...":"≡ƒô╖ " +(photoPreview||form.photos?.[0]?"Tap to change photo":"Tap to upload photo")}
                <input ref={photoRef} type="file" accept="image/*" style={{ display:"none" }}
                  onChange={e=>{ const f=e.target.files[0]; if(f) setPhotoPreview(URL.createObjectURL(f)) }}/>
              </label>
            <div style={{ marginBottom:12 }}>
              <label style={lbl}>Video (optional)</label>
              {form.video_url&&(
                <div style={{ position:"relative", marginBottom:8 }}>
                  <video src={form.video_url} controls style={{ width:"100%", maxHeight:160, borderRadius:10 }}/>
                  <button type="button" onClick={()=>setForm(f=>({...f,video_url:""}))}
                    style={{ position:"absolute", top:6, right:6, background:"rgba(0,0,0,0.5)", border:"none", borderRadius:"50%", width:24, height:24, color:"#fff", fontSize:12, cursor:"pointer" }}>├ù</button>
                </div>
              )}
              <label style={{ display:"block", width:"100%", background:"#f8f8f8", border:"2px dashed #e5e5e5", borderRadius:10, padding:"12px", color:"#888", fontSize:12, cursor:"pointer", textAlign:"center" }}>
                {uploadingVideo?`ΓÅ│ Uploading... ${videoUploadProgress}%`:"≡ƒÄÑ " +(form.video_url?"Tap to change video":"Tap to upload video (max 200MB)")}
                <input type="file" accept="video/*" style={{ display:"none" }} onChange={async e=>{
                  const file = e.target.files[0]
                  if (!file) return
                  if (file.size > 200*1024*1024) return toast.error("Video must be under 200MB")
                  setUploadingVideo(true)
                  setVideoUploadProgress(0)
                  try {
                    const ext = file.name.split(".").pop()
                    const path = user.id + "/video-" + Date.now() + "." + ext
                    // supabase-js's own upload() gives no progress feedback at all, so a large
                    // video looked identical whether it was 5% done or about to finish - genuinely
                    // indistinguishable from being stuck. Upload directly via XMLHttpRequest instead,
                    // which supports real upload progress events.
                    const { data: { session } } = await supabase.auth.getSession()
                    await new Promise((resolve, reject) => {
                      const xhr = new XMLHttpRequest()
                      xhr.open("POST", `${import.meta.env.VITE_SUPABASE_URL || "https://gcnefnqtjxtqbhynyoxe.supabase.co"}/storage/v1/object/provider-photos/${path}`)
                      xhr.setRequestHeader("Authorization", `Bearer ${session?.access_token}`)
                      xhr.setRequestHeader("x-upsert", "true")
                      xhr.upload.onprogress = (evt) => {
                        if (evt.lengthComputable) setVideoUploadProgress(Math.round((evt.loaded / evt.total) * 100))
                      }
                      xhr.onload = () => xhr.status >= 200 && xhr.status < 300 ? resolve() : reject(new Error("Upload failed: " + xhr.responseText))
                      xhr.onerror = () => reject(new Error("Network error during upload"))
                      xhr.send(file)
                    })
                    const { data } = supabase.storage.from("provider-photos").getPublicUrl(path)
                    setForm(f=>({...f,video_url:data.publicUrl}))
                    toast.success("Video uploaded!")
                  } catch(e) { toast.error(e.message) }
                  finally { setUploadingVideo(false); setVideoUploadProgress(0) }
                }}/>
              </label>
            </div>
            </div>

            <div style={{ display:"flex", gap:8 }}>
              <button type="submit" disabled={saving}
                style={{ flex:1, background:saving?"#ccc":"linear-gradient(135deg,#e6821e,#f09840)", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700, padding:"12px", cursor:saving?"not-allowed":"pointer", boxShadow:"0 4px 12px rgba(230,130,30,0.3)" }}>
                {saving?"Saving...":(editing?"Update item":"Add item")}
              </button>
              <button type="button" onClick={()=>{ setShowForm(false); setEditing(null); setForm(EMPTY); setPhotoPreview(null) }}
                style={{ background:"none", border:"1px solid #ddd", borderRadius:10, color:"#666", fontSize:13, padding:"12px 20px", cursor:"pointer" }}>
                Cancel
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Search and filter */}
      <div style={{ marginBottom:"1rem" }}>
        <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search by name, brand..."
          style={{ width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:10, padding:"10px 14px", color:"#000", fontSize:13, outline:"none", marginBottom:10 }}/>
        <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
          <button onClick={()=>setCatFilter("all")}
            style={{ padding:"6px 12px", borderRadius:8, border:"none", fontSize:11, cursor:"pointer", background:catFilter==="all"?"#e6821e":"#f0f0f0", color:catFilter==="all"?"#fff":"#555", fontWeight:catFilter==="all"?700:400 }}>
            ≡ƒöì All
          </button>
          {orderedCategories.map(c=>(
            <button key={c.key} onClick={()=>setCatFilter(c.key)}
              style={{ padding:"6px 12px", borderRadius:8, border:"none", fontSize:11, cursor:"pointer", background:catFilter===c.key?"#e6821e":"#f0f0f0", color:catFilter===c.key?"#fff":"#555", fontWeight:catFilter===c.key?700:400 }}>
              {c.icon} {c.label}
            </button>
          ))}
        </div>
      </div>

      {/* Items count */}
      {!loading&&<div style={{ fontSize:11, color:"#888", marginBottom:10 }}>{filtered.length} item{filtered.length!==1?"s":""} {catFilter!=="all"?"in "+catFilter:""}</div>}

      {loading&&<div style={{ color:"#777", fontSize:13, textAlign:"center", padding:"2rem" }}>Loading inventory...</div>}
      {!loading&&filtered.length===0&&(
        <div style={{ textAlign:"center", padding:"3rem", color:"#888" }}>
          <div style={{ marginBottom:10, display:"flex", justifyContent:"center" }}><OrdersIcon size={40} color="#e6821e"/></div>
          <div style={{ fontSize:14, fontWeight:600, color:"#555", marginBottom:6 }}>No items found</div>
          <div style={{ fontSize:12 }}>Add your first item or try a different filter</div>
        </div>
      )}

      {/* Items list */}
      {filtered.map(item=>(
        <div key={item.id} style={{ background:"#ffffff", border:"1px solid "+(item.stock_quantity===0?"#e24b4a20":item.stock_quantity<=5?"#e6821e20":"#eeeeee"), borderRadius:12, padding:"1rem", marginBottom:10, opacity:item.is_active?1:0.6 }}>
          <div style={{ display:"flex", gap:12, alignItems:"flex-start" }}>
            {/* Photo */}
            <div style={{ width:60, height:60, borderRadius:10, overflow:"hidden", flexShrink:0, background:"#f8f8f8", border:"1px solid #eee", display:"flex", alignItems:"center", justifyContent:"center", fontSize:24 }}>
              {item.photos?.[0] ? <img src={item.photos[0]} alt="" style={{ width:"100%", height:"100%", objectFit:"cover", cursor:"zoom-in" }} onClick={()=>setLightbox({ open:true, photos:item.photos, index:0 })}/> : CATEGORIES.find(c=>c.key===item.category)?.icon||"≡ƒôª"}
            </div>

            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:6 }}>
                <div style={{ flex:1, minWidth:0, marginRight:8 }}>
                  <div style={{ fontSize:14, fontWeight:700, color:"#000", marginBottom:2 }}>{item.name}</div>
                  <div style={{ display:"flex", gap:4, flexWrap:"wrap", marginBottom:4 }}>
                    {item.brand&&<span style={{ fontSize:10, color:"#555", background:"#f5f5f5", padding:"2px 7px", borderRadius:6 }}>{item.brand}</span>}
                    <span style={{ fontSize:10, color:"#888", background:"#f5f5f5", padding:"2px 7px", borderRadius:6 }}>{CATEGORIES.find(c=>c.key===item.category)?.icon} {item.category}</span>
                    {!item.is_active&&<span style={{ fontSize:10, color:"#888", background:"#f5f5f5", padding:"2px 7px", borderRadius:6 }}>Hidden</span>}
                    {item.stock_quantity===0&&<span style={{ fontSize:10, color:"#e24b4a", background:"#fff5f5", padding:"2px 7px", borderRadius:6 }}>Γ¥î Out of stock</span>}
                    {item.stock_quantity>0&&item.stock_quantity<=5&&<span style={{ fontSize:10, color:"#e6821e", background:"#fff8f0", padding:"2px 7px", borderRadius:6 }}>ΓÜá∩╕Å Low: {item.stock_quantity}</span>}
                  </div>
                  {item.compatible_cars?.length>0&&<div style={{ fontSize:10, color:"#888" }}>≡ƒÜù {item.compatible_cars.slice(0,3).join(", ")}</div>}
                </div>
                <div style={{ textAlign:"right", flexShrink:0 }}>
                  <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:800, color:"#e6821e" }}>KES {Number(item.price).toLocaleString()}</div>
                  <div style={{ fontSize:10, color:"#888" }}>per {item.unit}</div>
                </div>
              </div>

              {/* Stock stepper */}
              <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:10 }}>
                <div style={{ fontSize:11, color:"#666" }}>Stock:</div>
                <div style={{ display:"flex", alignItems:"center", gap:6, background:"#f8f8f8", borderRadius:8, padding:"4px 8px" }}>
                  <button onClick={()=>updateStock(item.id, Math.max(0,item.stock_quantity-1))}
                    style={{ background:"none", border:"none", color:"#e24b4a", cursor:"pointer", fontSize:16, lineHeight:1, padding:"0 4px", fontWeight:700 }}>ΓêÆ</button>
                  <span style={{ fontSize:13, fontWeight:700, color:"#000", minWidth:24, textAlign:"center" }}>{item.stock_quantity}</span>
                  <button onClick={()=>updateStock(item.id, item.stock_quantity+1)}
                    style={{ background:"none", border:"none", color:"#1d9e75", cursor:"pointer", fontSize:16, lineHeight:1, padding:"0 4px", fontWeight:700 }}>+</button>
                  <span style={{ fontSize:10, color:"#888" }}>{item.unit}s</span>
                </div>
              </div>

              {/* Actions */}
              <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                <button onClick={()=>startEdit(item)}
                  style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:11, fontWeight:600, padding:"5px 12px", cursor:"pointer" }}>
                  Γ£Å∩╕Å Edit
                </button>
                <button onClick={()=>toggleActive(item)}
                  style={{ background:item.is_active?"#fff8f0":"#f0fdf4", border:"1px solid "+(item.is_active?"#e6821e40":"#1d9e7540"), borderRadius:7, color:item.is_active?"#e6821e":"#1d9e75", fontSize:11, fontWeight:600, padding:"5px 12px", cursor:"pointer" }}>
                  {item.is_active?"≡ƒæü Hide":"≡ƒæü Show"}
                </button>
                <button onClick={()=>deleteItem(item.id)}
                  style={{ background:"#fff5f5", border:"1px solid #e24b4a30", borderRadius:7, color:"#e24b4a", fontSize:11, fontWeight:600, padding:"5px 12px", cursor:"pointer" }}>
                  ≡ƒùæ Delete
                </button>
              </div>
            </div>
          </div>
        </div>
      ))}
      {lightbox.open&&<PhotoLightbox photos={lightbox.photos} currentIndex={lightbox.index} onClose={()=>setLightbox(l=>({...l,open:false}))} onPrev={()=>setLightbox(l=>({...l,index:Math.max(0,l.index-1)}))} onNext={()=>setLightbox(l=>({...l,index:Math.min(l.photos.length-1,l.index+1)}))}/>}
    </div>
  )
}

import { useEffect, useState } from "react"
import { MechanicIcon, CheckIcon, CloseIcon, ChatIcon, WalletIcon, StarIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import toast from "react-hot-toast"
import { validateFile } from "../../lib/uploadValidation"
import ChatWindow from "../shared/ChatWindow"

const SPECIALIZATIONS = [
  "General Mechanic","Engine Specialist","Electrical Systems","Brake Specialist",
  "Transmission Specialist","Tire & Wheel Specialist","Body & Paint",
  "AC & Cooling Systems","Suspension & Steering","Diagnostics Specialist",
  "Emergency Roadside","Mobile Mechanic","Diagnostics & Tuning","Fuel Systems"
]

export default function ProviderMechanics() {
  const { user } = useAuth()
  const [mechanics, setMechanics] = useState([])
  const [loading, setLoading] = useState(true)
  const [showAdd, setShowAdd] = useState(false)
  const [expanded, setExpanded] = useState(null)
  const [pinPanel, setPinPanel] = useState(null)
  const [docsPanel, setDocsPanel] = useState(null)
  const [chatPanel, setChatPanel] = useState(null)
  const [commPanel, setCommPanel] = useState(null)
  const [commForm, setCommForm] = useState({ rate:"15", type:"percentage" })
  const [mechanicDocs, setMechanicDocs] = useState({})
  const [pin, setPin] = useState("")
  const [settingPin, setSettingPin] = useState(false)
  const [form, setForm] = useState({ first_name:"", last_name:"", phone:"", email:"", specialization:"General Mechanic", commission_rate:"15", commission_type:"percentage" })
  const [submitting, setSubmitting] = useState(false)

  useEffect(() => { if (user) load() }, [user])

  async function load() {
    setLoading(true)
    const { data } = await supabase.from("mechanics")
      .select("*, profiles!mechanics_provider_id_fkey(business_name)")
      .eq("provider_id", user.id)
      .order("created_at", { ascending: false })
    setMechanics(data||[])
    setLoading(false)
  }

  async function loadDocs(mechanicId) {
    const { data } = await supabase.from("driver_documents")
      .select("*").eq("driver_id", mechanicId)
    setMechanicDocs(prev => ({...prev, [mechanicId]: data||[]}))
    setDocsPanel(docsPanel===mechanicId?null:mechanicId)
  }

  async function addMechanic() {
    if (!form.first_name.trim()||!form.phone.trim()) return toast.error("Name and phone required")
    setSubmitting(true)
    try {
      // Create real auth account + profile via Edge Function (profiles.id requires a genuine auth.users row)
      const accountRes = await fetch("https://gcnefnqtjxtqbhynyoxe.supabase.co/functions/v1/create-mechanic-account", {
        method: "POST",
        headers: { "Content-Type": "application/json", "Authorization": "Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdjbmVmbnF0anh0cWJoeW55b3hlIiwicm9sZSI6ImFub24iLCJpYXQiOjE3Nzk2MDg0MzIsImV4cCI6MjA5NTE4NDQzMn0.Ybyce3psBj2I-hdoF95H5UAklr6hsgQi-mciI9uMIgc" },
        body: JSON.stringify({
          first_name: form.first_name,
          last_name: form.last_name,
          phone: form.phone,
          email: form.email||null,
          provider_id: user.id,
        })
      })
      const accountData = await accountRes.json()
      if (!accountData.success) throw new Error(accountData.error || "Failed to create mechanic account")

      // Create mechanic record, linked to the real profile via user_id
      const { error: mechError } = await supabase.from("mechanics").insert({
        provider_id: user.id,
        user_id: accountData.user_id,
        first_name: form.first_name,
        last_name: form.last_name,
        phone: form.phone,
        specialization: form.specialization,
        commission_rate: form.commission_type==="percentage" ? (parseFloat(form.commission_rate)||15)/100 : parseFloat(form.commission_rate)||500,
        commission_type: form.commission_type||"percentage",
        is_active: true,
        is_available: true,
      })
      if (mechError) throw mechError

      toast.success("Mechanic added! Set their PIN so they can login.")
      setForm({ first_name:"", last_name:"", phone:"", email:"", specialization:"General Mechanic", commission_rate:"15", commission_type:"percentage" })
      setShowAdd(false)
      load()
    } catch(err) { toast.error(err.message) }
    finally { setSubmitting(false) }
  }

  async function toggleActive(m) {
    await supabase.from("mechanics").update({ is_active: !m.is_active }).eq("id", m.id)
    toast.success(m.is_active?"Mechanic deactivated":"Mechanic activated")
    load()
  }

  async function toggleAvailable(m) {
    await supabase.from("mechanics").update({ is_available: !m.is_available }).eq("id", m.id)
    load()
  }

  async function updateCommission(mechanicId) {
    const { error } = await supabase.from("mechanics").update({
      commission_rate: commForm.type==="percentage" ? (parseFloat(commForm.rate)||15)/100 : parseFloat(commForm.rate)||500,
      commission_type: commForm.type
    }).eq("id", mechanicId)
    if (error) return toast.error(error.message)
    toast.success("Pay structure updated!")
    setCommPanel(null)
    load()
  }

  async function setMechanicPin(mechanicId) {
    if (!pin||pin.length<4) return toast.error("PIN must be at least 4 digits")
    setSettingPin(true)
    try {
      const { error } = await supabase.rpc("set_mechanic_pin", { p_mechanic_id: mechanicId, p_pin: pin })
      if (error) throw error
      toast.success("PIN set! Mechanic can now login at carcareconnect.care/mechanic-login")
      setPinPanel(null)
      setPin("")
      load()
    } catch(err) { toast.error(err.message) }
    finally { setSettingPin(false) }
  }

  const DOC_TYPES = [
    { type:"national_id_front", label:"National ID (Front)" },
    { type:"national_id_back", label:"National ID (Back)" },
    { type:"driving_license", label:"Driver License" },
    { type:"good_conduct", label:"Good Conduct" },
    { type:"medical_certificate", label:"Medical Certificate" },
  ]

  if (loading) return (
    <div style={{ textAlign:"center", padding:"3rem", color:"#888", fontFamily:"DM Sans,sans-serif" }}>
      Loading mechanics...
    </div>
  )

  return (
    <div style={{ fontFamily:"DM Sans,sans-serif", maxWidth:600, margin:"0 auto", padding:"1rem" }}>

      {/* Header */}
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1rem" }}>
        <div>
          <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:"#000", display:"flex", alignItems:"center", gap:8 }}><MechanicIcon size={20} color="#e6821e"/> Mechanics</div>
          <div style={{ fontSize:12, color:"#888" }}>{mechanics.length} mechanic{mechanics.length!==1?"s":""} in your garage</div>
        </div>
        <button onClick={()=>setShowAdd(!showAdd)}
          style={{ background:"#1d9e75", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"8px 16px", cursor:"pointer" }}>
          {showAdd?"Cancel":"+ Add Mechanic"}
        </button>
      </div>

      {/* Add mechanic form */}
      {showAdd&&(
        <div style={{ background:"#ffffff", border:"1px solid #1d9e7520", borderRadius:14, padding:"1.25rem", marginBottom:"1rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#1d9e75", marginBottom:"1rem" }}>New Mechanic</div>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10, marginBottom:10 }}>
            <div>
              <div style={{ fontSize:11, color:"#555", marginBottom:4, fontWeight:600 }}>First name *</div>
              <input value={form.first_name} onChange={e=>setForm(f=>({...f,first_name:e.target.value}))}
                placeholder="John" style={{ width:"100%", background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:8, padding:"9px 12px", fontSize:13, color:"#000", outline:"none", boxSizing:"border-box" }}/>
            </div>
            <div>
              <div style={{ fontSize:11, color:"#555", marginBottom:4, fontWeight:600 }}>Last name</div>
              <input value={form.last_name} onChange={e=>setForm(f=>({...f,last_name:e.target.value}))}
                placeholder="Doe" style={{ width:"100%", background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:8, padding:"9px 12px", fontSize:13, color:"#000", outline:"none", boxSizing:"border-box" }}/>
            </div>
          </div>
          <div style={{ marginBottom:10 }}>
            <div style={{ fontSize:11, color:"#555", marginBottom:4, fontWeight:600 }}>Phone number *</div>
            <input value={form.phone} onChange={e=>setForm(f=>({...f,phone:e.target.value}))}
              placeholder="0712 345 678" style={{ width:"100%", background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:8, padding:"9px 12px", fontSize:13, color:"#000", outline:"none", boxSizing:"border-box" }}/>
          </div>
          <div style={{ marginBottom:10 }}>
            <div style={{ fontSize:11, color:"#555", marginBottom:4, fontWeight:600 }}>Specialization</div>
            <select value={form.specialization} onChange={e=>setForm(f=>({...f,specialization:e.target.value}))}
              style={{ width:"100%", background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:8, padding:"9px 12px", fontSize:13, color:"#000", outline:"none", boxSizing:"border-box" }}>
              {SPECIALIZATIONS.map(s=><option key={s} value={s}>{s}</option>)}
            </select>
          </div>
          <div style={{ marginBottom:"1rem" }}>
            <div style={{ fontSize:11, color:"#555", marginBottom:6, fontWeight:600 }}>Pay structure (your agreement with mechanic)</div>
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
              <div>
                <div style={{ fontSize:10, color:"#888", marginBottom:3 }}>Commission type</div>
                <select value={form.commission_type} onChange={e=>setForm(f=>({...f,commission_type:e.target.value}))}
                  style={{ width:"100%", background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:8, padding:"9px 12px", fontSize:12, color:"#000", outline:"none" }}>
                  <option value="percentage">% of job value</option>
                  <option value="fixed">Fixed per job (KES)</option>
                </select>
              </div>
              <div>
                <div style={{ fontSize:10, color:"#888", marginBottom:3 }}>{form.commission_type==="percentage"?"Percentage (%)":"Amount (KES)"}</div>
                <input type="number" value={form.commission_rate} onChange={e=>setForm(f=>({...f,commission_rate:e.target.value}))}
                  placeholder={form.commission_type==="percentage"?"e.g. 15":"e.g. 500"}
                  style={{ width:"100%", background:"#f8f8f8", border:"1px solid #eeeeee", borderRadius:8, padding:"9px 12px", fontSize:12, color:"#000", outline:"none" }}/>
              </div>
            </div>
            <div style={{ fontSize:10, color:"#888", marginTop:4 }}>
              {form.commission_type==="percentage"
                ? `Your private arrangement: mechanic earns ${form.commission_rate}% per completed job`
                : `Your private arrangement: mechanic earns KES ${form.commission_rate} per completed job`}
            </div>
          </div>
          <button onClick={addMechanic} disabled={submitting}
            style={{ width:"100%", background:submitting?"#888":"#1d9e75", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700, padding:"12px", cursor:"pointer" }}>
            {submitting?"Adding...":"Add Mechanic ΓåÆ"}
          </button>
        </div>
      )}

      {/* Mechanics list */}
      {mechanics.length===0&&!showAdd&&(
        <div style={{ textAlign:"center", padding:"3rem 1rem", background:"#ffffff", borderRadius:14, border:"1px solid #eeeeee" }}>
          <div style={{ marginBottom:12, display:"flex", justifyContent:"center" }}><MechanicIcon size={48} color="#e6821e"/></div>
          <div style={{ fontFamily:"Syne", fontSize:16, fontWeight:700, color:"#000", marginBottom:4 }}>No mechanics yet</div>
          <div style={{ fontSize:13, color:"#888" }}>Add mechanics to assign them to jobs</div>
        </div>
      )}

      {mechanics.map(m=>(
        <div key={m.id} style={{ background:"#ffffff", border:"1px solid " + (m.is_active?m.is_available?"#1d9e7520":"#e6821e20":"#eeeeee"), borderRadius:14, marginBottom:10, overflow:"hidden" }}>

          {/* Mechanic header - always visible */}
          <div style={{ padding:"1rem", display:"flex", gap:12, alignItems:"flex-start" }}
            onClick={()=>setExpanded(expanded===m.id?null:m.id)}>
            {/* Avatar */}
            <div style={{ width:44, height:44, borderRadius:"50%", background:m.is_active&&m.is_available?"#f0fdf4":"#f5f5f5", border:"2px solid " + (m.is_active&&m.is_available?"#1d9e75":"#ddd"), display:"flex", alignItems:"center", justifyContent:"center", fontSize:20, flexShrink:0 }}>
              
            </div>
            {/* Info */}
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:800, color:"#000", marginBottom:2 }}>{m.first_name} {m.last_name}</div>
              <div style={{ fontSize:11, color:"#555", marginBottom:4 }}>{m.specialization}</div>
              <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, fontWeight:700,
                  background:m.is_active?m.is_available?"#f0fdf4":"#fff8f0":"#f5f5f5",
                  color:m.is_active?m.is_available?"#1d9e75":"#e6821e":"#888" }}>
                  {m.is_active?m.is_available?"≡ƒƒó Available":"≡ƒƒí Busy":"ΓÜ½ Inactive"}
                </span>
                {m.mechanic_code&&<span style={{ fontSize:10, color:"#888", padding:"2px 8px", background:"#f5f5f5", borderRadius:10 }}>{m.mechanic_code}</span>}
                {m.rating&&<span style={{ fontSize:10, color:"#e6821e", fontWeight:700 }}>Γ¡É {m.rating}</span>}
              </div>
            </div>
            <div style={{ fontSize:14, color:"#888", flexShrink:0 }}>{expanded===m.id?"Γû▓":"Γû╝"}</div>
          </div>

          {/* Expanded panel */}
          {expanded===m.id&&(
            <div style={{ borderTop:"1px solid #f5f5f5", padding:"0.75rem 1rem" }}>

              {/* Contact info */}
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8, marginBottom:12 }}>
                {m.phone&&<div style={{ background:"#f8f8f8", borderRadius:8, padding:"8px 10px" }}>
                  <div style={{ fontSize:10, color:"#888", marginBottom:2 }}>Phone</div>
                  <div style={{ fontSize:12, fontWeight:600, color:"#000" }}>{m.phone}</div>
                </div>}
              {m.commission_rate>0&&<div style={{ background:"#f0fdf4", borderRadius:8, padding:"8px 10px" }}>
                <div style={{ fontSize:10, color:"#888", marginBottom:2 }}>Pay structure</div>
                <div style={{ fontSize:12, fontWeight:600, color:"#1d9e75" }}>
                  {m.commission_type==="fixed"
                    ? "KES "+Number(m.commission_rate).toLocaleString()+" per job"
                    : Math.round(m.commission_rate*100)+"% of job value"}
                </div>
              </div>}
