import { useEffect, useState } from "react"
import { useNavigate } from "react-router-dom"
import { NotificationsIcon, SuccessIcon, WarningIcon, ErrorIcon, ChatIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import toast from "react-hot-toast"

export default function ProviderNotifications() {
  const { user } = useAuth()
  const navigate = useNavigate()
  const [notifications, setNotifications] = useState([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("prov-notifs")
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"notifications", filter:`user_id=eq.${user.id}` }, payload => {
        setNotifications(prev=>[payload.new,...prev])
        toast(payload.new.title, { icon: payload.new.type==="success"?"Γ£à":payload.new.type==="error"?"Γ¥î":payload.new.type==="warning"?"ΓÜá∩╕Å":"≡ƒöö", duration:5000 })
      })
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function load() {
    const { data } = await supabase.from("notifications")
      .select("*").eq("user_id", user.id).order("created_at", { ascending:false })
    setNotifications(data||[])
    setLoading(false)
  }

  async function markRead(id) {
    await supabase.from("notifications").update({ is_read:true }).eq("id", id).eq("user_id", user.id)
    setNotifications(n => n.map(x => x.id===id ? {...x, is_read:true} : x))
  }

  async function deleteNotif(id) {
    await supabase.from("notifications").delete().eq("id", id).eq("user_id", user.id)
    setNotifications(n => n.filter(x => x.id!==id))
  }
  async function clearAll() {
    if (!confirm("Clear all notifications?")) return
    await supabase.from("notifications").delete().eq("user_id", user.id)
    setNotifications([])
    toast.success("All cleared")
  }
  async function markAllRead() {
    await supabase.from("notifications").update({ is_read:true }).eq("user_id", user.id).eq("is_read", false)
    setNotifications(n => n.map(x => ({...x, is_read:true})))
    toast.success("All marked as read")
  }

  

  const unread = notifications.filter(n=>!n.is_read).length
  const typeIcon = { info:"≡ƒöö", success:"Γ£à", warning:"ΓÜá∩╕Å", error:"Γ¥î" }
  const typeColor = { info:"#378add", success:"#1d9e75", warning:"#e6821e", error:"#e24b4a" }
  const typeBg = { info:"#eff6ff", success:"#f0fdf4", warning:"#fff8f0", error:"#fff5f5" }

  return (
    <div>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1.25rem" }}>
        <div>
          <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:"#000000" }}>Notifications</div>
          {unread>0&&<div style={{ fontSize:12, color:"#e6821e", marginTop:2 }}>{unread} unread</div>}
        </div>
        <div style={{ display:"flex", gap:6 }}>
          {unread>0&&<button onClick={markAllRead} style={{ background:"none", border:"1px solid #dddddd", borderRadius:7, color:"#555555", fontSize:12, padding:"6px 12px", cursor:"pointer" }}>Mark all read</button>}
          {notifications.length>0&&<button onClick={clearAll} style={{ background:"none", border:"1px solid #e24b4a30", borderRadius:7, color:"#e24b4a", fontSize:12, padding:"6px 12px", cursor:"pointer" }}>Clear all</button>}
        </div>
      </div>
      {loading&&<div style={{ color:"#777777", fontSize:13 }}>Loading...</div>}
      {!loading&&notifications.length===0&&(
        <div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"3rem" }}>
          <div style={{ marginBottom:10, display:"flex", justifyContent:"center" }}><NotificationsIcon size={32} color="#e6821e"/></div>
          No notifications yet
        </div>
      )}
      {notifications.map(n=>(
        <div key={n.id} onClick={()=>{ 
        if(!n.is_read) markRead(n.id)
        if(n.type==="message"||n.title?.includes("≡ƒÆ¼")) {
          try {
            const meta = n.metadata ? JSON.parse(n.metadata) : {}
            if(meta.booking_id) navigate(`/dashboard/chat?booking=${meta.booking_id}`)
            else navigate("/dashboard/chat")
          } catch(_) { navigate("/dashboard/chat") }
        }
      }}
          style={{ background:n.is_read?"#f8f8f8":"#ffffff", border:`1px solid ${n.is_read?"#eeeeee":typeColor[n.type]||"#e6821e"}30`, borderRadius:10, padding:"1rem", marginBottom:8, cursor:n.is_read?"default":"pointer", display:"flex", alignItems:"flex-start", gap:12 }}>
          <div style={{ width:38, height:38, borderRadius:9, background:typeBg[n.type]||"#fff8f0", display:"flex", alignItems:"center", justifyContent:"center", fontSize:18, flexShrink:0 }}>
            {n.type==="success"?<SuccessIcon size={18} color="#1d9e75"/>:n.type==="error"?<ErrorIcon size={18} color="#e24b4a"/>:n.type==="warning"?<WarningIcon size={18} color="#e6821e"/>:n.type==="message"?<ChatIcon size={18} color="#8b5cf6"/>:<NotificationsIcon size={18} color="#378add"/>}
          </div>
          <div style={{ flex:1, minWidth:0 }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", gap:8 }}>
              <div style={{ fontSize:13, fontWeight:n.is_read?400:600, color:n.is_read?"#888888":"#000000" }}>{n.title}</div>
              {!n.is_read&&<div style={{ width:8, height:8, borderRadius:"50%", background:"#e6821e", flexShrink:0, marginTop:4 }}/>}
            </div>
            <div style={{ fontSize:12, color:"#666", marginTop:3, lineHeight:1.5 }}>{n.message}</div>
            <div style={{ fontSize:10, color:"#888888", marginTop:5 }}>{new Date(n.created_at).toLocaleString()}</div>
          </div>
          <button onClick={e=>{ e.stopPropagation(); deleteNotif(n.id) }} style={{ background:"none", border:"none", color:"#555555", cursor:"pointer", fontSize:16, lineHeight:1, flexShrink:0 }}>├ù</button>
        </div>
      ))}
    </div>
  )
}

import { ClockIcon, CheckIcon, OrdersIcon, SuccessIcon, CloseIcon, MarketplaceIcon, PaymentsIcon, DeliveryIcon, LocationIcon, MovingCarIcon, ProfileIcon, WarningIcon, NoteIcon, PhoneCallIcon, ShareIcon, ServicesIcon, TripReportIcon } from "../../lib/cccIcons"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import { callNumber, openWhatsApp } from "../../lib/openExternal"
import toast from "react-hot-toast"

const STATUS_COLORS = { pending:"#e6821e", confirmed:"#378add", processing:"#8b5cf6", ready:"#1d9e75", delivered:"#1d9e75", cancelled:"#e24b4a" }
const STATUS_FLOW = ["pending","confirmed","processing","ready","delivered"]
const STATUS_LABELS = { pending:"Pending", confirmed:"Confirmed", processing:"Packing", ready:"Ready", delivered:"Delivered", cancelled:"Cancelled" }
const STATUS_ICONS = { pending:"≡ƒòÉ", confirmed:"Γ£ô", processing:"≡ƒôª", ready:"Γ£à", delivered:"≡ƒÄë", cancelled:"Γ£ù" }

export default function ProviderOrders() {
  const { user } = useAuth()
  const isMobile = useIsMobile()
  const [orders, setOrders] = useState([])
  const [loading, setLoading] = useState(true)
  const [goPartsRequests, setGoPartsRequests] = useState([])
  const [riderInfo, setRiderInfo] = useState({}) // {id: {name, phone}}
  const [showRiderForm, setShowRiderForm] = useState(null)
  const [goPartsTab, setGoPartsTab] = useState(false)
  const [filter, setFilter] = useState("pending")
  const [search, setSearch] = useState("")
  const [selectedIds, setSelectedIds] = useState([])
  const [newOrderAlert, setNewOrderAlert] = useState(false)
  const [pickupOtpMode, setPickupOtpMode] = useState(null)
  const [pickupOtpInput, setPickupOtpInput] = useState("")
  const [sendingPickupOtp, setSendingPickupOtp] = useState(null)
  const [verifyingPickupOtp, setVerifyingPickupOtp] = useState(false)

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("provider-orders")
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"orders", filter:"provider_id=eq."+user.id },
        () => {
          setNewOrderAlert(true)
          playNotificationSound()
          toast("≡ƒ¢Æ New order received!", { duration:8000, icon:"≡ƒ¢Æ" })
          load()
          setTimeout(()=>setNewOrderAlert(false), 4000)
        })
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  function playNotificationSound() {
    try {
      const audio = new Audio("data:audio/wav;base64,UklGRl9vT19XQVZFZm10IBAAAAABAAEARKwAAIhYAQACABAAZGF0YQoAAAAAAAAAAAAA")
      audio.volume = 0.3
      audio.play().catch(()=>{})
    } catch(e) {}
  }

  async function acceptGoPartsRequest(id) {
    const req = goPartsRequests.find(r=>r.id===id)
    if(!req) return
    const rider = riderInfo[id] || {}
    // Calculate payouts
    const partsCut = await supabase.from("app_settings").select("value").eq("key","go_parts_provider_rate").single()
    const provRate = Number(partsCut.data?.value||90)/100
    const provPayout = Math.round(req.total_amount * provRate)
    const platformComm = req.total_amount - provPayout
    await supabase.from("go_parts_requests").update({
      status:"accepted", delivery_status:"accepted",
      rider_name: rider.name||null, rider_phone: rider.phone||null,
      provider_payout: provPayout, platform_commission: platformComm
    }).eq("id", id)
    // Notify mechanic
    await supabase.from("notifications").insert({ user_id: req.mechanic_id, title: "Part accepted! ≡ƒôª", message: "Supplier accepted. Rider: "+(rider.name||"on the way")+" "+( rider.phone||""), type: "success" })
    // Notify customer - request payment
    await supabase.from("notifications").insert({ user_id: req.customer_id, title: "Part approved ΓÇö pay now ≡ƒÆ│", message: "Your mechanic needs a "+req.inventory?.name+" ΓÇö KES "+Number(req.total_amount).toLocaleString()+". Check app to approve payment.", type: "info" })
    setGoPartsRequests(prev=>prev.map(r=>r.id===id?{...r,status:"accepted",delivery_status:"accepted",rider_name:rider.name,rider_phone:rider.phone}:r))
    // Send STK push immediately so customer pays fast
    await supabase.functions.invoke("daraja-stk-push", { body: { amount: req.total_amount, booking_id: req.booking_id, customer_id: req.customer_id, provider_id: req.provider_id, service_name: "GO Parts: "+(req.inventory?.name||"Part") } }).catch(e=>console.warn("Parts STK:",e.message))
    setShowRiderForm(null)
    toast.success("Part request accepted! Customer notified to pay.")
  }
  async function updatePartsDeliveryStatus(id, newStatus) {
    await supabase.from("go_parts_requests").update({ delivery_status: newStatus, status: newStatus==="delivered"?"delivered":"accepted" }).eq("id", id)
    setGoPartsRequests(prev=>prev.map(r=>r.id===id?{...r,delivery_status:newStatus,status:newStatus==="delivered"?"delivered":"accepted"}:r))
    const req = goPartsRequests.find(r=>r.id===id)
    if(req) {
      const msgs = { picked_up:"Rider has picked up the part and is heading to you.", on_the_way:"Your part is on the way! Rider: "+(req.rider_name||"")+" "+(req.rider_phone||""), delivered:"Part has been delivered to your mechanic!" }
      await supabase.from("notifications").insert([
        { user_id: req.mechanic_id, title: newStatus.replace(/_/g," ")+" Γ£à", message: msgs[newStatus]||newStatus, type: "info" },
        { user_id: req.customer_id, title: newStatus.replace(/_/g," ")+" Γ£à", message: msgs[newStatus]||newStatus, type: "info" }
      ])
    }
    toast.success("Status updated: "+newStatus.replace(/_/g," "))
  }
  async function markGoPartsDelivered(id) {
    const req = goPartsRequests.find(r=>r.id===id)
    if(!req) return
    // Update status
    await supabase.from("go_parts_requests").update({ status:"delivered", delivery_status:"delivered", payment_released:false }).eq("id", id)
    // Decrement stock
    await supabase.rpc("decrement_stock", { inv_id: req.inventory_id, qty: req.quantity })
    // Notify mechanic + customer
    await supabase.from("notifications").insert([
      { user_id: req.mechanic_id, title: "Part delivered! Γ£à", message: "Your part has been delivered. Fit it and complete the job.", type: "success" },
      { user_id: req.customer_id, title: "Part delivered! ≡ƒÆ│ Pay now", message: `Your mechanic received the ${req.inventory?.name}. Please pay KES ${Number(req.total_amount).toLocaleString()} for the part.`, type: "info" }
    ])
    // Payment released by customer when they confirm receipt
    setGoPartsRequests(prev=>prev.map(r=>r.id===id?{...r,status:"delivered",delivery_status:"delivered"}:r))
    toast.success("Marked as delivered! Customer will be prompted to confirm receipt.")
  }
  async function load() {
    const { data } = await supabase.from("orders")
      .select("*, order_items(*, inventory(name,unit,category)), profiles!orders_customer_id_fkey(first_name,last_name,city)")
      .eq("provider_id", user.id)
      .neq("status","pending_payment")
      .order("created_at", { ascending:false })
    setOrders(data||[])
    setLoading(false)
  }

  async function updateStatus(orderId, status) {
    const order = orders.find(o=>o.id===orderId)
    const { error } = await supabase.from("orders").update({ status, updated_at:new Date().toISOString() }).eq("id", orderId)
    if (error) { toast.error("Failed to update order: "+error.message); return }
    // For pickup orders (no driver involved), the provider marking it delivered/complete
    // themselves is the confirmation - trigger the payout release right here. Delivery
    // orders release separately, only once the customer's OTP genuinely confirms receipt.
    if (status==="delivered" && order?.fulfillment_type!=="delivery") {
      await supabase.functions.invoke("release-order-payment", { body: { order_id: orderId } })
    }
    // A delivery order becoming "ready" with no driver manually assigned yet was previously
    // completely silent - it just sat in the unassigned pool until a driver happened to open
    // the app and check. Notify eligible marketplace drivers directly instead.
    if (status==="ready" && order?.fulfillment_type==="delivery" && !order?.delivery_driver_id) {
      // Match the same size-based vehicle preference assignDriver() already uses, so a tiny
      // one-item order preferentially reaches bike riders rather than paging every van driver
      // too. Falls back to notifying everyone if nobody of the ideal type is currently active.
      const notifyItemCount = order?.order_items?.length || 1
      const notifyPreferredType = notifyItemCount<=3?"motorcycle":notifyItemCount<=6?"tuktuk":"van"
      const { data: eligibleDrivers } = await supabase.from("profiles")
        .select("id,driver_vehicle_type")
        .eq("role","driver")
        .eq("is_active",true)
        .eq("documents_verified",true)
        .eq("driver_category","marketplace")
      const preferredDrivers = (eligibleDrivers||[]).filter(d=>d.driver_vehicle_type===notifyPreferredType)
      const driversToNotify = preferredDrivers.length>0 ? preferredDrivers : (eligibleDrivers||[])
      if (driversToNotify?.length) {
        await supabase.from("notifications").insert(
          driversToNotify.map(d => ({
            user_id: d.id,
            title: "≡ƒÜÜ New delivery available!",
            message: `A new delivery is ready for pickup${order.delivery_zone ? " in " + order.delivery_zone : ""}. Check the Available tab.`,
            type: "info"
          }))
        )
      }
    }
    if (order?.customer_id) {
      const messages = {
        confirmed: "Your order has been confirmed! We are preparing your items.",
        processing: "Your order is being processed and packed.",
        ready: order.fulfillment_type==="delivery"?"Your order is ready ΓÇö driver will pick up soon!":"Your order is ready for pickup!",
        delivered: "Your order has been delivered. Thank you! ≡ƒÄë",
        cancelled: "Your order has been cancelled. Contact support for refund."
      }
      await supabase.from("notifications").insert({
        user_id: order.customer_id,
        title: "Order update ≡ƒôª",
        message: messages[status]||"Order status updated to "+status,
        type: status==="cancelled"?"error":"success"
      })
    }
    toast.success("Order "+status)
    load()
  }

  async function bulkConfirm() {
    if (selectedIds.length===0) return
    for (const id of selectedIds) {
      await updateStatus(id, "confirmed")
    }
    setSelectedIds([])
    toast.success(selectedIds.length+" orders confirmed")
  }

  function toggleSelect(id) {
    setSelectedIds(prev => prev.includes(id) ? prev.filter(i=>i!==id) : [...prev, id])
  }

  async function sendPickupOtp(orderId) {
    setSendingPickupOtp(orderId)
    try {
      const { data, error } = await supabase.rpc("generate_pickup_otp", { p_order_id: orderId, p_provider_id: user.id })
      if (error) throw error
      if (!data?.success) throw new Error(data?.error || "Failed to send code")
      toast.success("Code sent to customer - ask them to read it out")
      setPickupOtpMode(orderId)
    } catch(e) { toast.error(e.message) }
    finally { setSendingPickupOtp(null) }
  }
  async function verifyPickupOtp(order) {
    if (!pickupOtpInput || pickupOtpInput.length !== 4) return toast.error("Enter 4-digit code")
    setVerifyingPickupOtp(true)
    try {
      const { data, error } = await supabase.rpc("verify_pickup_otp", { p_order_id: order.id, p_otp: pickupOtpInput })
      if (error) throw error
      if (!data?.success) throw new Error(data?.error || "Verification failed")
      // Same reasoning as delivery: only release the provider's payout once the customer
      // has genuinely confirmed receipt via their own code, not just the provider's word.
      await supabase.functions.invoke("release-order-payment", { body: { order_id: order.id } })
      setPickupOtpMode(null)
      setPickupOtpInput("")
      toast.success("Pickup confirmed! \ud83c\udf89")
      load()
    } catch(e) { toast.error(e.message) }
    finally { setVerifyingPickupOtp(false) }
  }
  async function assignDriver(orderId) {
    const order = orders.find(o=>o.id===orderId)
    const itemCount = order?.order_items?.length||1
    const preferredType = itemCount<=3?"motorcycle":itemCount<=6?"tuktuk":"van"
    const { data: drivers } = await supabase.from("profiles")
      .select("id,first_name,last_name,driver_vehicle_type,city")
      .eq("role","driver")
      .eq("is_active",true)
      .eq("documents_verified",true)
      .eq("driver_category","marketplace")
    if (!drivers?.length) return toast.error("No verified drivers available")
    const preferred = drivers.filter(d=>d.driver_vehicle_type===preferredType)
    const driver = preferred.length>0 ? preferred[0] : drivers[0]
    const { error: assignError } = await supabase.from("orders").update({ delivery_driver_id:driver.id, delivery_status:"driver_assigned", delivery_attempt_expires_at:new Date(Date.now()+15*60*1000).toISOString() }).eq("id", orderId)
    if (assignError) { toast.error("Failed to assign driver: "+assignError.message); return }
    await supabase.from("notifications").insert({
      user_id: driver.id,
      title: "≡ƒÜÜ New delivery job!",
      message: "New delivery assigned: "+order?.order_items?.length+" item(s) to "+order?.delivery_address+". Zone: "+order?.delivery_zone+". You have 15 minutes to accept!",
      type: "success"
    })
    toast.success("Driver assigned: "+driver.first_name+" "+driver.last_name+" ("+driver.driver_vehicle_type+")")
    load()
  }

  function shareReceipt(o) {
    const items = o.order_items?.map(oi=>oi.name+" x"+oi.quantity+" - KES "+Number(oi.unit_price*oi.quantity).toLocaleString()).join("\n")
    const text = "CCC Order #"+o.order_number+"\n\nCustomer: "+o.customer_name+"\n\n"+items+"\n\nSubtotal: KES "+Number(o.subtotal).toLocaleString()+(o.delivery_fee>0?"\nDelivery: KES "+Number(o.delivery_fee).toLocaleString():"")+"\n\nStatus: "+o.status
    if (navigator.share) {
      navigator.share({ title:"Order #"+o.order_number, text }).catch(()=>{})
    } else {
      navigator.clipboard.writeText(text)
      toast.success("Receipt copied to clipboard")
    }
  }

  const filtered = (filter==="all" ? orders : orders.filter(o=>o.status===filter))
    .filter(o => !search || o.customer_name?.toLowerCase().includes(search.toLowerCase()) || o.order_number?.toLowerCase().includes(search.toLowerCase()))

  const pending = orders.filter(o=>o.status==="pending").length
  const today = orders.filter(o=>new Date(o.created_at).toDateString()===new Date().toDateString()).length
  const revenue = orders.filter(o=>o.status==="delivered").reduce((s,o)=>s+Number(o.provider_earnings||0),0)

  return (
    <div>
      <div style={{ marginBottom:"1.25rem" }}>
        <div style={{ fontFamily:"Syne", fontSize:isMobile?16:20, fontWeight:800, color:"#000" }}>Orders</div>
        <div style={{ fontSize:12, color:"#777" }}>Manage parts and accessories orders</div>
      </div>
      {/* GO Parts Requests */}
        {goPartsRequests.filter(r=>r.status==="pending"||r.status==="accepted").length > 0 && (
        <div style={{ background:"#f3f0ff", border:"1px solid #8b5cf640", borderRadius:12, padding:"1rem", marginBottom:"1.25rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#8b5cf6", marginBottom:8, display:"flex", alignItems:"center", gap:6 }}><ServicesIcon size={14} color="#8b5cf6"/> GO Service Part Requests</div>
          {goPartsRequests.filter(r=>r.status==="pending"||r.status==="accepted").map(r=>(
            <div key={r.id} style={{ background:"#fff", borderRadius:10, padding:"0.75rem", marginBottom:8 }}>
              <div style={{ marginBottom:8 }}>
                <div style={{ fontSize:13, fontWeight:600 }}>{r.inventory?.name} x{r.quantity}</div>
                <div style={{ fontSize:11, color:"#888" }}>KES {Number(r.total_amount).toLocaleString()} ┬╖ Your cut: KES {Number(r.provider_payout||r.total_amount*0.9).toLocaleString()}</div>
                <div style={{ fontSize:11, color:"#555", marginTop:2, display:"flex", alignItems:"center", gap:3 }}><LocationIcon size={11} color="#555"/> {r.delivery_location_address}</div>
                {r.delivery_location_lat&&r.delivery_location_lng&&<a href={`https://www.google.com/maps/dir/?api=1&destination=${r.delivery_location_lat},${r.delivery_location_lng}`} target="_blank" rel="noopener noreferrer" style={{ fontSize:11, color:"#4285f4", fontWeight:600 }}><TripReportIcon size={13} color="#4285f4"/> Navigate to customer</a>}
                <div style={{ fontSize:11, color:"#888" }}>Mechanic: {r.mechanic?.first_name}</div>
                {r.rider_name&&<div style={{ fontSize:11, color:"#555", display:"flex", alignItems:"center", gap:3 }}><MovingCarIcon size={11} color="#555"/> Rider: {r.rider_name} {r.rider_phone&&<a href={"tel:"+r.rider_phone} style={{ color:"#1d9e75" }}>{r.rider_phone}</a>}</div>}
                <div style={{ display:"flex", gap:4, marginTop:6, marginBottom:4 }}>{["accepted","picked_up","on_the_way","delivered"].map((s,i)=>(<div key={s} style={{ flex:1, height:3, borderRadius:3, background:["accepted","picked_up","on_the_way","delivered"].indexOf(r.delivery_status||"accepted")>=i?"#8b5cf6":"#eee" }}/>))}</div>
                <div style={{ fontSize:10, padding:"2px 8px", borderRadius:8, display:"inline-block", marginTop:4, background:r.delivery_status==="delivered"?"#f0fdf4":r.delivery_status==="on_the_way"?"#eff6ff":r.delivery_status==="picked_up"?"#fff8f0":"#f3f0ff", color:r.delivery_status==="delivered"?"#1d9e75":r.delivery_status==="on_the_way"?"#378add":r.delivery_status==="picked_up"?"#e6821e":"#8b5cf6", fontWeight:600 }}>{r.delivery_status?.replace(/_/g," ")||"pending"}</div>
              </div>
              {/* Pending - show accept with optional rider info */}
              {r.status==="pending"&&(
                <div>
                  {showRiderForm===r.id&&(
                    <div style={{ marginBottom:8 }}>
                      <input placeholder="Rider name (optional)" value={riderInfo[r.id]?.name||""} onChange={e=>setRiderInfo(p=>({...p,[r.id]:{...p[r.id],name:e.target.value}}))} style={{ width:"100%", padding:"6px 8px", borderRadius:7, border:"1px solid #ddd", fontSize:11, marginBottom:4, boxSizing:"border-box" }}/>
                      <input placeholder="Rider phone (optional)" value={riderInfo[r.id]?.phone||""} onChange={e=>setRiderInfo(p=>({...p,[r.id]:{...p[r.id],phone:e.target.value}}))} style={{ width:"100%", padding:"6px 8px", borderRadius:7, border:"1px solid #ddd", fontSize:11, boxSizing:"border-box" }}/>
                    </div>
                  )}
                  <div style={{ display:"flex", gap:6 }}>
                    <button onClick={()=>setShowRiderForm(showRiderForm===r.id?null:r.id)} style={{ flex:1, background:"#f3f0ff", border:"1px solid #8b5cf640", borderRadius:8, color:"#8b5cf6", fontSize:11, padding:"6px 10px", cursor:"pointer" }}>≡ƒÜ┤ {showRiderForm===r.id?"Hide":"Add rider"}</button>
                    <button onClick={()=>acceptGoPartsRequest(r.id)} style={{ flex:1, background:"#8b5cf6", border:"none", borderRadius:8, color:"#fff", fontSize:11, fontWeight:700, padding:"6px 10px", cursor:"pointer" }}>Γ£ô Accept</button>
                  </div>
                </div>
              )}
              {/* Accepted - show delivery status buttons */}
              {r.status==="accepted"&&(
                <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                  {r.delivery_status==="accepted"&&<button onClick={()=>updatePartsDeliveryStatus(r.id,"picked_up")} style={{ background:"#e6821e", border:"none", borderRadius:8, color:"#fff", fontSize:10, fontWeight:700, padding:"5px 10px", cursor:"pointer" }}>≡ƒôª Picked Up</button>}
                  {r.delivery_status==="picked_up"&&<button onClick={()=>updatePartsDeliveryStatus(r.id,"on_the_way")} style={{ background:"#378add", border:"none", borderRadius:8, color:"#fff", fontSize:10, fontWeight:700, padding:"5px 10px", cursor:"pointer" }}>≡ƒÜÜ On the Way</button>}
                  {r.delivery_status==="on_the_way"&&<button onClick={()=>markGoPartsDelivered(r.id)} style={{ background:"#1d9e75", border:"none", borderRadius:8, color:"#fff", fontSize:10, fontWeight:700, padding:"5px 10px", cursor:"pointer" }}>Γ£à Mark Delivered</button>}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
      {/* Gradient stats header */}
      <div style={{ background: newOrderAlert ? "linear-gradient(135deg,#1d9e75,#22c98f)" : "linear-gradient(135deg,#e6821e,#f09840)", borderRadius:14, padding:"1rem 1.25rem", marginBottom:"1.25rem", display:"flex", justifyContent:"space-between", alignItems:"center", transition:"background 0.5s" }}>
        <div>
          <div style={{ fontFamily:"Syne", fontSize:22, fontWeight:800, color:"#fff", display:"flex", alignItems:"center", gap:8 }}>{newOrderAlert ? "≡ƒ¢Æ New order!" : today+" orders today"}</div>
          <div style={{ fontSize:11, color:"rgba(255,255,255,0.8)", marginTop:2 }}>KES {revenue.toLocaleString()} earned from delivered orders</div>
        </div>
        <div style={{ textAlign:"center" }}>
          <div style={{ fontFamily:"Syne", fontSize:24, fontWeight:800, color:pending>0?"#fde68a":"rgba(255,255,255,0.9)" }}>{pending}</div>
          <div style={{ fontSize:10, color:"rgba(255,255,255,0.7)" }}>Pending</div>
        </div>
      </div>

      {pending>0&&(
        <div style={{ background:"#fff8f0", border:"1px solid #e6821e40", borderRadius:10, padding:"0.75rem 1rem", marginBottom:"1rem", display:"flex", justifyContent:"space-between", alignItems:"center" }}>
          <div style={{ fontSize:13, color:"#e6821e", fontWeight:600, display:"flex", alignItems:"center", gap:4 }}><WarningIcon size={13} color="#e6821e"/> {pending} order{pending>1?"s":""} waiting for confirmation</div>
        </div>
      )}

      {/* Search */}
      <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search by customer name or order number..."
        style={{ width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:10, padding:"9px 14px", color:"#000", fontSize:13, outline:"none", marginBottom:10 }}/>

      {/* Status filter */}
      <div style={{ display:"flex", gap:6, marginBottom:"1rem", flexWrap:"wrap" }}>
        {["pending","confirmed","processing","ready","delivered","cancelled","all"].map(f=>(
          <button key={f} onClick={()=>setFilter(f)}
            style={{ padding:"6px 12px", borderRadius:8, border:"none", fontSize:11, cursor:"pointer", background:filter===f?(STATUS_COLORS[f]||"#8b5cf6"):"#f0f0f0", color:filter===f?"#fff":"#555", fontWeight:filter===f?700:400 }}>
            {f==="all"?<MarketplaceIcon size={14} color="currentColor"/>:STATUS_ICONS[f]==="clock"?<ClockIcon size={14} color="currentColor"/>:STATUS_ICONS[f]==="check"?<CheckIcon size={14} color="currentColor"/>:STATUS_ICONS[f]==="orders"?<OrdersIcon size={14} color="currentColor"/>:STATUS_ICONS[f]==="success"?<SuccessIcon size={14} color="currentColor"/>:<CloseIcon size={14} color="currentColor"/>} {f==="all"?"All":STATUS_LABELS[f]} ({f==="all"?orders.length:orders.filter(o=>o.status===f).length})
          </button>
        ))}
      </div>

      {/* Bulk actions */}
      {filter==="pending"&&filtered.length>0&&(
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:10, background:"#f8f8f8", borderRadius:8, padding:"0.5rem 0.75rem" }}>
          <label style={{ display:"flex", alignItems:"center", gap:6, fontSize:12, color:"#555", cursor:"pointer" }}>
            <input type="checkbox" checked={selectedIds.length===filtered.length&&filtered.length>0} onChange={e=>setSelectedIds(e.target.checked?filtered.map(o=>o.id):[])}/>
            Select all ({selectedIds.length} selected)
          </label>
          {selectedIds.length>0&&(
            <button onClick={bulkConfirm} style={{ background:"#1d9e75", border:"none", borderRadius:7, color:"#fff", fontSize:11, fontWeight:700, padding:"6px 14px", cursor:"pointer" }}>
              Γ£ô Confirm {selectedIds.length} order{selectedIds.length>1?"s":""}
            </button>
          )}
        </div>
      )}

      {loading&&<div style={{ color:"#777", fontSize:13 }}>Loading...</div>}
      {!loading&&filtered.length===0&&(
        <div style={{ textAlign:"center", padding:"2rem", color:"#888" }}>
          <div style={{ marginBottom:8, display:"flex", justifyContent:"center" }}><OrdersIcon size={36} color="#e6821e"/></div>
          <div style={{ fontSize:13 }}>No orders found</div>
        </div>
      )}

      {filtered.map(o=>{
        const flowIdx = STATUS_FLOW.indexOf(o.status)
        return (
          <div key={o.id} style={{ background:"#ffffff", border:"1px solid "+(STATUS_COLORS[o.status]||"#eeeeee")+"30", borderRadius:14, padding:"1rem", marginBottom:10, boxShadow:"0 1px 4px rgba(0,0,0,0.04)" }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:10 }}>
              <div style={{ display:"flex", gap:8, alignItems:"flex-start" }}>
                {o.status==="pending"&&(
                  <input type="checkbox" checked={selectedIds.includes(o.id)} onChange={()=>toggleSelect(o.id)} style={{ marginTop:3 }}/>
                )}
                <div>
                  <div style={{ fontSize:13, fontWeight:700, color:"#000", marginBottom:2 }}>#{o.order_number}</div>
                  <div style={{ fontSize:11, color:"#777", display:"flex", alignItems:"center", gap:3 }}><ProfileIcon size={11} color="#777"/> {o.customer_name||o.profiles?.first_name+" "+o.profiles?.last_name}</div>
                  <div style={{ fontSize:11, color:"#777" }}>{o.fulfillment_type==="delivery"?<><DeliveryIcon size={11} color="#378add"/> Delivery to {o.delivery_address}</>:<><MarketplaceIcon size={11} color="#888"/> Customer pickup</>}</div>
                  {o.delivery_zone&&<div style={{ fontSize:11, color:"#378add", display:"flex", alignItems:"center", gap:3 }}><LocationIcon size={11} color="#378add"/> Zone: {o.delivery_zone}</div>}
                  <div style={{ fontSize:10, color:"#888" }}>{new Date(o.created_at).toLocaleString()}</div>
                </div>
              </div>
              <div style={{ textAlign:"right" }}>
                <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:"#e6821e" }}>KES {Number(o.subtotal||0).toLocaleString()}</div>
                <div style={{ fontSize:10, color:"#1d9e75" }}>Your cut: KES {Number(o.provider_earnings||0).toLocaleString()}</div>
                <span style={{ fontSize:10, padding:"3px 10px", borderRadius:20, background:(STATUS_COLORS[o.status]||"#888")+"20", color:STATUS_COLORS[o.status]||"#888", display:"inline-block", marginTop:4, fontWeight:600 }}>{STATUS_ICONS[o.status]} {STATUS_LABELS[o.status]}</span>
              </div>
            </div>

            {/* Progress bar */}
            {o.status!=="cancelled"&&(
              <div style={{ display:"flex", alignItems:"center", marginBottom:10, padding:"0 4px" }}>
                {STATUS_FLOW.map((s,i)=>(
                  <div key={s} style={{ display:"flex", alignItems:"center", flex:i<STATUS_FLOW.length-1?1:0 }}>
                    <div style={{ width:18, height:18, borderRadius:"50%", background:i<=flowIdx?STATUS_COLORS[s]:"#e5e5e5", display:"flex", alignItems:"center", justifyContent:"center", fontSize:9, color:"#fff", flexShrink:0 }}>
                      {i<flowIdx?"Γ£ô":i+1}
                    </div>
                    {i<STATUS_FLOW.length-1&&<div style={{ flex:1, height:2, background:i<flowIdx?STATUS_COLORS[s]:"#e5e5e5" }}/>}
                  </div>
                ))}
              </div>
            )}

            <div style={{ background:"#f8f8f8", borderRadius:8, padding:"0.75rem", marginBottom:10 }}>
              {o.order_items?.map(oi=>(
                <div key={oi.id} style={{ display:"flex", justifyContent:"space-between", fontSize:12, color:"#555", padding:"3px 0" }}>
                  <span>{oi.name} ├ù {oi.quantity} {oi.inventory?.unit||""}</span>
                  <span>KES {Number(oi.unit_price*oi.quantity).toLocaleString()}</span>
                </div>
              ))}
              {o.delivery_fee>0&&(
                <div style={{ display:"flex", justifyContent:"space-between", fontSize:11, color:"#777", borderTop:"1px solid #eeeeee", paddingTop:4, marginTop:4 }}>
                  <span>Delivery fee</span><span>KES {Number(o.delivery_fee).toLocaleString()}</span>
                </div>
              )}
            </div>

            <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
              {o.status==="pending"&&(
                <>
                  <button onClick={()=>updateStatus(o.id,"confirmed")} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"6px 12px", cursor:"pointer", fontWeight:600 }}>Γ£ô Confirm order</button>
                  <button onClick={()=>updateStatus(o.id,"cancelled")} style={{ background:"none", border:"1px solid #e24b4a40", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"6px 10px", cursor:"pointer" }}>Cancel</button>
                </>
              )}
              {o.status==="confirmed"&&(
                <button onClick={()=>updateStatus(o.id,"processing")} style={{ background:"#faf5ff", border:"1px solid #8b5cf640", borderRadius:7, color:"#8b5cf6", fontSize:11, padding:"6px 12px", cursor:"pointer" }}>≡ƒôª Start packing</button>
              )}
              {o.status==="processing"&&(
                <button onClick={()=>updateStatus(o.id,"ready")} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"6px 12px", cursor:"pointer" }}>Γ£à Mark ready</button>
              )}
              {o.status==="ready"&&o.fulfillment_type==="delivery"&&!o.delivery_driver_id&&(
                <button onClick={()=>assignDriver(o.id)} style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:11, padding:"6px 12px", cursor:"pointer" }}>≡ƒÜÜ Assign driver</button>
              )}
              {o.status==="ready"&&o.fulfillment_type==="pickup"&&(
                pickupOtpMode===o.id ? (
                  <div style={{ display:"flex", gap:6, alignItems:"center" }}>
                    <input value={pickupOtpInput} onChange={e=>setPickupOtpInput(e.target.value.replace(/\\D/g,"").slice(0,4))} placeholder="4-digit code" maxLength={4}
                      style={{ width:90, padding:"6px 8px", borderRadius:7, border:"1px solid #ddd", fontSize:12 }}/>
                    <button disabled={verifyingPickupOtp} onClick={()=>verifyPickupOtp(o)} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"6px 12px", cursor:verifyingPickupOtp?"not-allowed":"pointer", fontWeight:600 }}>
                      {verifyingPickupOtp?"Verifying...":"Γ£ô Verify & Complete"}
                    </button>
                    <button onClick={()=>{ setPickupOtpMode(null); setPickupOtpInput("") }} style={{ background:"none", border:"1px solid #ddd", borderRadius:7, color:"#888", fontSize:11, padding:"6px 10px", cursor:"pointer" }}>Cancel</button>
                  </div>
                ) : (
                  <button disabled={sendingPickupOtp===o.id} onClick={()=>sendPickupOtp(o.id)} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"6px 12px", cursor:sendingPickupOtp===o.id?"not-allowed":"pointer" }}>
                    {sendingPickupOtp===o.id?"Sending...":"≡ƒöö Customer arrived - Send code"}
                  </button>
                )
              )}
              {o.customer_phone&&(
                <button onClick={()=>callNumber(o.customer_phone)} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"6px 12px", cursor:"pointer" }}>≡ƒô₧ Call</button>
              )}
              {o.customer_phone&&(
                <button onClick={()=>openWhatsApp(o.customer_phone)} style={{ background:"#f0fdf4", border:"1px solid #1d9e7540", borderRadius:7, color:"#1d9e75", fontSize:11, padding:"6px 12px", cursor:"pointer" }}>≡ƒÆÜ WhatsApp</button>
              )}
              <button onClick={()=>shareReceipt(o)} style={{ background:"#f5f3ff", border:"1px solid #8b5cf640", borderRadius:7, color:"#8b5cf6", fontSize:11, padding:"6px 12px", cursor:"pointer" }}>≡ƒôñ Share receipt</button>
            </div>
          </div>
        )
      })}
    </div>
  )
}

import { useAuth } from "../../contexts/AuthContext"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

export default function ProviderPartsManager({ booking, onUpdate }) {
  const isMobile = useIsMobile()
  const [parts, setParts] = useState(booking.parts_details||[])
  const [newPart, setNewPart] = useState({ name:"", quantity:1, unit_price:"" })
  const [saving, setSaving] = useState(false)
  const [commissionRate, setCommissionRate] = useState(0.10)

  useEffect(() => {
    // Fetch commission rate for parts based on provider type
    supabase.from("profiles").select("provider_type").eq("id", booking.provider_id).maybeSingle()
      .then(({ data: prov }) => {
        if (!prov?.provider_type) return
        const key = prov.provider_type === "parts_dealer" ? "parts_dealer" : "marketplace_item"
        supabase.from("commission_rates").select("platform_rate").eq("provider_type", key).maybeSingle()
          .then(({ data: rate }) => { if (rate) setCommissionRate(Number(rate.platform_rate)) })
      })
  }, [booking.provider_id])

  function addPart() {
    if (!newPart.name||!newPart.unit_price) return toast.error("Part name and price required")
    const part = {
      id: Date.now(),
      name: newPart.name,
      quantity: parseInt(newPart.quantity)||1,
      unit_price: parseFloat(newPart.unit_price),
      total: parseInt(newPart.quantity||1) * parseFloat(newPart.unit_price),
    }
    setParts(p=>[...p, part])
    setNewPart({ name:"", quantity:1, unit_price:"" })
  }

  function removePart(id) {
    setParts(p=>p.filter(p=>p.id!==id))
  }

  const totalPartsCost = parts.reduce((s,p)=>s+p.total, 0)
  const partsCommission = totalPartsCost * commissionRate
  const partsProviderEarnings = totalPartsCost * (1 - commissionRate)
  const updatedTotal = Number(booking.total_amount) + totalPartsCost

  async function saveParts() {
    setSaving(true)
    try {
      const { error } = await supabase.from("bookings").update({
        parts_details: parts,
        parts_cost: totalPartsCost,
        parts_commission: partsCommission,
        parts_provider_earnings: partsProviderEarnings,
        updated_total: updatedTotal,
        parts_needed: parts.length > 0,
        parts_approved: false,
      }).eq("id", booking.id)
      if (error) throw error

      await supabase.from("notifications").insert({
        user_id: booking.customer_id,
        title: "Parts added to your booking ≡ƒöº",
        message: `Your provider has added parts worth KES ${totalPartsCost.toLocaleString()} to your booking. New total: KES ${updatedTotal.toLocaleString()}. Please review and approve.`,
        type: "info",
      })

      toast.success("Parts saved ΓÇö customer notified")
      onUpdate()
    } catch(err) {
      toast.error(err.message)
    } finally {
      setSaving(false)
    }
  }

  const inp = { background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"9px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif" }

  return (
    <div style={{ background:"#ffffff", border:"1px solid #378add30", borderRadius:12, padding:"1rem", marginTop:10 }}>
      <div style={{ fontFamily:"Syne", fontSize:13, fontWeight:700, color:"#378add", marginBottom:8 }}>≡ƒöº Parts & materials</div>

      {booking.problem_description&&(
        <div style={{ background:"#ffffff", borderRadius:8, padding:"0.75rem", marginBottom:12 }}>
          <div style={{ fontSize:10, color:"#777777", marginBottom:4 }}>Customer reported problem:</div>
          <div style={{ fontSize:12, color:"#555555", lineHeight:1.5 }}>"{booking.problem_description}"</div>
          {booking.parts_description&&(
            <div style={{ fontSize:11, color:"#666", marginTop:4 }}>Parts mentioned: {booking.parts_description}</div>
          )}
        </div>
      )}

      {parts.map(p=>(
        <div key={p.id} style={{ display:"flex", alignItems:"center", gap:8, padding:"8px 0", borderBottom:"1px solid #eeeeee" }}>
          <div style={{ flex:1 }}>
            <div style={{ fontSize:12, color:"#000000" }}>{p.name}</div>
            <div style={{ fontSize:10, color:"#777777" }}>Qty: {p.quantity} ├ù KES {p.unit_price.toLocaleString()}</div>
          </div>
          <div style={{ fontFamily:"Syne", fontSize:12, fontWeight:700, color:"#e6821e" }}>KES {p.total.toLocaleString()}</div>
          <button onClick={()=>removePart(p.id)} style={{ background:"none", border:"none", color:"#e24b4a", cursor:"pointer", fontSize:16, padding:"0 4px" }}>├ù</button>
        </div>
      ))}

      <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"2fr 1fr 1fr auto", gap:8, marginTop:10, marginBottom:10 }}>
        <input style={{ ...inp, width:"100%" }} placeholder="Part name (e.g. Brake pads)" value={newPart.name} onChange={e=>setNewPart(p=>({...p,name:e.target.value}))}/>
        <input style={{ ...inp, width:"100%" }} type="number" placeholder="Qty" min="1" value={newPart.quantity} onChange={e=>setNewPart(p=>({...p,quantity:e.target.value}))}/>
        <input style={{ ...inp, width:"100%" }} type="number" placeholder="Unit price (KES)" value={newPart.unit_price} onChange={e=>setNewPart(p=>({...p,unit_price:e.target.value}))}/>
        <button onClick={addPart} style={{ background:"#378add", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"9px 14px", cursor:"pointer", whiteSpace:"nowrap" }}>+ Add</button>
      </div>

      {parts.length>0&&(
        <div style={{ background:"#ffffff", borderRadius:8, padding:"0.75rem", marginBottom:10 }}>
          <div style={{ display:"flex", justifyContent:"space-between", fontSize:11, color:"#777777", marginBottom:4 }}>
            <span>Parts total</span><span>KES {totalPartsCost.toLocaleString()}</span>
          </div>
          <div style={{ display:"flex", justifyContent:"space-between", fontSize:11, color:"#777777", marginBottom:4 }}>
            <span>Platform fee ({Math.round(commissionRate*100)}%)</span><span>KES {partsCommission.toFixed(0)}</span>
          </div>
          <div style={{ display:"flex", justifyContent:"space-between", fontSize:11, color:"#1d9e75", marginBottom:4 }}>
            <span>Your earnings (90%)</span><span>KES {partsProviderEarnings.toFixed(0)}</span>
          </div>
          <div style={{ height:1, background:"#f0f0f0", margin:"6px 0" }}/>
          <div style={{ display:"flex", justifyContent:"space-between", fontSize:13, color:"#e6821e", fontWeight:700 }}>
            <span>New booking total</span><span>KES {updatedTotal.toLocaleString()}</span>
          </div>
        </div>
      )}

      <button onClick={saveParts} disabled={saving||parts.length===0}
        style={{ background:saving||parts.length===0?"#555555":"#378add", border:"none", borderRadius:8, color:saving||parts.length===0?"#555":"#fff", fontFamily:"Syne,sans-serif", fontSize:12, fontWeight:700, padding:"9px 18px", cursor:saving||parts.length===0?"not-allowed":"pointer" }}>
        {saving?"Saving...":"Save parts & notify customer"}
      </button>
    </div>
  )
}

import useIsMobile from "../../lib/useIsMobile"
import { useEffect, useState } from "react"
import { LockedIcon, PayoutIcon, WarningIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import toast from "react-hot-toast"

export default function ProviderPayouts() {
  const isMobile = useIsMobile()
  const { user } = useAuth()
  const [payouts, setPayouts] = useState([])
  const [earnings, setEarnings] = useState(0)
  const [paid, setPaid] = useState(0)
  const [loading, setLoading] = useState(true)
  const [bankInfo, setBankInfo] = useState({ bank_name:"", bank_account_name:"", bank_account_number:"", mpesa_number:"", id_number:"", kra_pin:"" })
  const [bankSaved, setBankSaved] = useState(false)
  const [amount, setAmount] = useState("")
  const [submitting, setSubmitting] = useState(false)
  const [minPayout, setMinPayout] = useState(500)
  const [savingBank, setSavingBank] = useState(false)
  const [tab, setTab] = useState("payouts")
  const [autoPayouts, setAutoPayouts] = useState([])

  useEffect(() => {
    if (!user) return
    load()
    supabase.from("app_settings").select("value").eq("key","min_payout_amount").maybeSingle()
      .then(({ data }) => { if (data) setMinPayout(Number(data.value)) })
  }, [user])

  async function load() {
    const [{ data: bks }, { data: pts }, { data: sens }] = await Promise.all([
      supabase.from("bookings").select("provider_earnings").eq("provider_id", user.id).eq("status", "completed"),
      supabase.from("payout_requests").select("*").eq("user_id", user.id).order("created_at", { ascending:false }),
      supabase.from("profile_sensitive").select("bank_name,bank_account_name,bank_account_number").eq("id", user.id).single()
    ])
    const totalEarned = (bks||[]).reduce((s,b)=>s+Number(b.provider_earnings||0),0)
    const totalPaid = (pts||[]).filter(p=>p.status==="paid").reduce((s,p)=>s+Number(p.amount),0)
    setEarnings(totalEarned)
    setPaid(totalPaid)
    setPayouts(pts||[])
    if (sens?.bank_name) {
      setBankInfo({ bank_name:sens.bank_name||"", bank_account_name:sens.bank_account_name||"", bank_account_number:sens.bank_account_number||"", mpesa_number:sens.mpesa_number||"", id_number:sens.id_number||"", kra_pin:sens.kra_pin||"" })
      setBankSaved(true)
    }
    setLoading(false)
  }

  async function saveBank(e) {
    e.preventDefault()
    setSavingBank(true)
    const { error } = await supabase.from("profile_sensitive").update({
      bank_name: bankInfo.bank_name,
      bank_account_name: bankInfo.bank_account_name,
      bank_account_number: bankInfo.bank_account_number,
      mpesa_number: bankInfo.mpesa_number,
      id_number: bankInfo.id_number,
      kra_pin: bankInfo.kra_pin,
    }).eq("id", user.id)
    if (error) { toast.error(error.message); setSavingBank(false); return }
    toast.success("Bank details saved")
    setBankSaved(true)
    setSavingBank(false)
  }

  async function requestPayout(e) {
    e.preventDefault()
    if (!bankSaved) return toast.error("Save your bank details first")
    const amt = Number(amount)
    const available = earnings - paid
    if (amt < minPayout) return toast.error(`Minimum payout is KES ${minPayout.toLocaleString()}`)
    if (amt > available) return toast.error(`Maximum available is KES ${Number(available).toLocaleString()}`)
    setSubmitting(true)
    const { data, error } = await supabase.functions.invoke("process-payout-request", {
      body: { user_id: user.id, amount: amt, source_label: "Provider payout" }
    })
    if (error || !data?.success) { toast.error(error?.message || "Payout request failed"); setSubmitting(false); return }
    toast.success(data.automatic ? "Payout sent! Check your M-Pesa." : "Payout request submitted for review")
    setAmount("")
    setSubmitting(false)
    load()
  }

  const available = earnings - paid
  const RC = { pending:"#e6821e", approved:"#378add", paid:"#1d9e75", rejected:"#e24b4a" }
  const inp = { width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"10px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif", marginBottom:10 }
  const lbl = { fontSize:11, color:"#666", textTransform:"uppercase", letterSpacing:"0.05em", display:"block", marginBottom:4 }

  return (
    <div>
      <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"repeat(3,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {[
          { label:"Total earned", value:`KES ${Number(earnings).toLocaleString()}` },
          { label:"Available", value:`KES ${Number(available).toLocaleString()}`, color:available>0?"#e6821e":undefined },
          { label:"Total paid out", value:`KES ${Number(paid).toLocaleString()}`, color:"#1d9e75" },
        ].map(s=>(
          <div key={s.label} style={{ background:"#ffffff", borderRadius:10, padding:"1rem", border:"1px solid #eeeeee" }}>
            <div style={{ fontSize:11, color:"#777777", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:6 }}>{s.label}</div>
            <div style={{ fontFamily:"Syne", fontSize:22, fontWeight:800, color:s.color||"#000000" }}>{s.value}</div>
          </div>
        ))}
      </div>

      <div style={{ display:"flex", gap:6, marginBottom:"1.5rem" }}>
        {[{k:"payouts",l:"Payouts"},{k:"bank",l:"Bank details"}].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{ padding:"8px 16px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#378add":"#555555", color:tab===t.k?"#fff":"#666", fontFamily:"'DM Sans',sans-serif", fontWeight:tab===t.k?700:400 }}>
            {t.l} {t.k==="bank"&&!bankSaved&&<span style={{ color:"#e24b4a" }}>ΓÜá∩╕Å</span>}
          </button>
        ))}
      </div>

      {tab==="bank"&&(
        <div style={{ background:"#ffffff", border:`1px solid ${bankSaved?"#1d9e7530":"#e6821e30"}`, borderRadius:12, padding:"1.25rem" }}>
          <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:"1rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, color:"#000000" }}>Bank account details</div>
            {bankSaved&&<span style={{ fontSize:11, color:"#1d9e75", background:"#f0fdf4", padding:"2px 8px", borderRadius:10 }}>Γ£ô Saved</span>}
          </div>
          {!bankSaved&&<div style={{ fontSize:12, color:"#e6821e", marginBottom:"1rem", background:"#fff8f0", borderRadius:8, padding:"0.75rem" }}>Add your bank details to receive payouts</div>}
          <form onSubmit={saveBank}>
            <label style={lbl}>Bank name</label>
            <input style={inp} placeholder="e.g. Equity Bank, KCB, Co-op Bank" value={bankInfo.bank_name} onChange={e=>setBankInfo(b=>({...b,bank_name:e.target.value}))} required/>
            <label style={lbl}>Account holder name</label>
            <input style={inp} placeholder="Full name as on account" value={bankInfo.bank_account_name} onChange={e=>setBankInfo(b=>({...b,bank_account_name:e.target.value}))} required/>
            <label style={lbl}>Account number</label>
            <input style={inp} placeholder="Your bank account number" value={bankInfo.bank_account_number} onChange={e=>setBankInfo(b=>({...b,bank_account_number:e.target.value}))} required/>
            <div style={{ background:"#f0fdf4", border:"1px solid #1d9e7530", borderRadius:8, padding:"0.75rem", marginBottom:12 }}>
              <div style={{ fontSize:12, fontWeight:600, color:"#1d9e75", marginBottom:4, display:"flex", alignItems:"center", gap:4 }}><LockedIcon size={12} color="#1d9e75"/> Why we collect this information</div>
              <div style={{ fontSize:11, color:"#555", lineHeight:1.6 }}>Your bank details, national ID and KRA PIN are required for secure payout processing and Kenya Revenue Authority (KRA) tax compliance. This information is encrypted and only accessible to CCC administrators for payment purposes. We never share your details with third parties.</div>
            </div>
            <label style={lbl}>M-Pesa number (for faster payouts)</label>
            <input style={inp} placeholder="e.g. 0712345678" value={bankInfo.mpesa_number} onChange={e=>setBankInfo(b=>({...b,mpesa_number:e.target.value}))}/>
            <label style={lbl}>National ID number *</label>
            <input style={inp} placeholder="Your national ID number" value={bankInfo.id_number} onChange={e=>setBankInfo(b=>({...b,id_number:e.target.value}))} required/>
            <label style={lbl}>KRA PIN (required for payouts above KES 24,999)</label>
            <input style={inp} placeholder="e.g. A012345678B" value={bankInfo.kra_pin} onChange={e=>setBankInfo(b=>({...b,kra_pin:e.target.value}))}/>
            <button type="submit" disabled={savingBank}
              style={{ background:savingBank?"#555555":"#378add", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px 24px", cursor:savingBank?"not-allowed":"pointer" }}>
              {savingBank?"Saving...":"Save bank details"}
            </button>
          </form>
        </div>
      )}

      {tab==="auto"&&(
        <div>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:12 }}>Automatic Payouts from Safaricom Daraja</div>
          {autoPayouts.length===0&&(
            <div style={{ textAlign:"center", padding:"2rem", color:"#888" }}>
              <div style={{ marginBottom:8, display:"flex", justifyContent:"center" }}><PayoutIcon size={32} color="#e6821e"/></div>
              <div>No automatic payouts yet. They appear here after bookings are completed.</div>
            </div>
          )}
          {autoPayouts.map(p=>(
            <div key={p.id} style={{ background:"#f8f8f8", borderRadius:10, padding:"1rem", marginBottom:8, border:"1px solid #eee" }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                <div>
                  <div style={{ fontFamily:"Syne", fontSize:15, fontWeight:700 }}>KES {Number(p.amount).toLocaleString()}</div>
                  <div style={{ fontSize:12, color:"#888" }}>{new Date(p.created_at).toLocaleString()}</div>
                  <div style={{ fontSize:11, color:"#aaa" }}>Ref: {p.daraja_ref||p.id?.slice(0,8)}</div>
                </div>
                <span style={{ fontSize:11, padding:"3px 10px", borderRadius:8,
                  background:p.status==="completed"?"#f0fdf4":p.status==="failed"?"#fff5f5":"#fff8f0",
                  color:p.status==="completed"?"#1d9e75":p.status==="failed"?"#e24b4a":"#e6821e",
                  fontWeight:600 }}>
                  {p.status}
                </span>
              </div>
            </div>
          ))}
        </div>
      )}
      {tab==="payouts"&&(
        <div>
          {!bankSaved&&(
            <div style={{ background:"#fff8f0", border:"1px solid #e6821e30", borderRadius:10, padding:"1rem", marginBottom:"1.5rem", display:"flex", justifyContent:"space-between", alignItems:"center" }}>
              <div>
                <div style={{ fontSize:13, color:"#e6821e", fontWeight:500 }}>Bank details required</div>
                <div style={{ fontSize:11, color:"#777777", marginTop:2 }}>Add your bank details to request payouts</div>
              </div>
              <button onClick={()=>setTab("bank")} style={{ background:"#e6821e", border:"none", borderRadius:7, color:"#fff", fontSize:12, fontWeight:700, padding:"7px 14px", cursor:"pointer", fontFamily:"Syne,sans-serif" }}>Add now</button>
            </div>
          )}

          {bankSaved&&(
            <div style={{ background:"#ffffff", border:"1px solid #1d9e7530", borderRadius:10, padding:"1rem", marginBottom:"1.5rem" }}>
              <div style={{ fontSize:11, color:"#777777", marginBottom:6 }}>Payout to</div>
              <div style={{ fontSize:13, fontWeight:500, color:"#000000" }}>{bankInfo.bank_account_name}</div>
              <div style={{ fontSize:12, color:"#777777", marginTop:2 }}>{bankInfo.bank_name} ┬╖ {bankInfo.bank_account_number}</div>
              <button onClick={()=>setTab("bank")} style={{ background:"none", border:"none", color:"#378add", fontSize:11, cursor:"pointer", marginTop:6, padding:0, fontFamily:"'DM Sans',sans-serif" }}>Change bank details</button>
            </div>
          )}

          <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem", marginBottom:"1.5rem" }}>
            <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:4, color:"#000000" }}>Request payout</div>
            <div style={{ fontSize:12, color:"#777777", marginBottom:"1rem" }}>{`Minimum KES ${minPayout.toLocaleString()} ┬╖ Available: KES ${Number(available).toLocaleString()} ┬╖ Transfer takes 2-3 business days`}</div>
            {available < minPayout ? (
              <div style={{ fontSize:13, color:"#777777", padding:"1rem", background:"#ffffff", borderRadius:8 }}>
                {`You need KES ${Number(minPayout-available).toLocaleString()} more to reach the minimum payout threshold.`}
              </div>
            ) : (
              <form onSubmit={requestPayout}>
                <label style={lbl}>Amount to withdraw (KES)</label>
                <input style={inp} type="number" min={minPayout} max={available} placeholder={`${minPayout.toLocaleString()} ΓÇö ${Number(available).toLocaleString()}`} value={amount} onChange={e=>setAmount(e.target.value)} required/>
                {amount&&Number(amount)>=50&&(
                  <div style={{ fontSize:12, color:"#777777", marginBottom:10, marginTop:-6 }}>
                    You will receive: <span style={{ color:"#1d9e75", fontWeight:600 }}>KES {Number(amount).toLocaleString()}</span> to {bankInfo.bank_name}
                  </div>
                )}
                <button type="submit" disabled={submitting||!bankSaved}
                  style={{ background:submitting||!bankSaved?"#555555":"#378add", border:"none", borderRadius:9, color:submitting||!bankSaved?"#666":"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px 24px", cursor:submitting||!bankSaved?"not-allowed":"pointer" }}>
                  {submitting?"Submitting...":"Request payout"}
                </button>
              </form>
            )}
          </div>

          {payouts.length>0&&(
            <div>
              <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:10, color:"#000000" }}>Payout history</div>
              {payouts.map(p=>{
                const steps = [
                  { key:"pending", label:"Requested" },
                  { key:"approved", label:"Approved" },
                  { key:"paid", label:"Paid" },
                ]
                const isRejected = p.status === "rejected"
                const currentStepIdx = isRejected ? -1 : steps.findIndex(s=>s.key===p.status)
                return (
                <div key={p.id} style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:8 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:12 }}>
                    <div style={{ flex:1 }}>
                      <div style={{ fontSize:14, fontWeight:500, color:"#000000" }}>KES {Number(p.amount).toLocaleString()}</div>
                      <div style={{ fontSize:11, color:"#777777", marginTop:2 }}>{p.bank_name} ┬╖ {p.bank_account_number}</div>
                      <div style={{ fontSize:10, color:"#888888", marginTop:2 }}>{new Date(p.created_at).toLocaleDateString()}</div>
                      {p.admin_note&&<div style={{ fontSize:11, color:"#666", marginTop:4, fontStyle:"italic" }}>&quot;{p.admin_note}&quot;</div>}
                    </div>
                    <span style={{ fontSize:11, padding:"3px 9px", borderRadius:20, background:`${RC[p.status]}20`, color:RC[p.status], border:`1px solid ${RC[p.status]}40`, flexShrink:0 }}>
                      {p.status}
                    </span>
                  </div>
                  {!isRejected&&(
                    <div style={{ display:"flex", alignItems:"center" }}>
                      {steps.map((s,i)=>(
                        <div key={s.key} style={{ display:"flex", alignItems:"center", flex:i<steps.length-1?1:"none" }}>
                          <div style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:4 }}>
                            <div style={{ width:22, height:22, borderRadius:"50%", background:i<=currentStepIdx?"#1d9e75":"#f0f0f0", color:i<=currentStepIdx?"#fff":"#aaa", display:"flex", alignItems:"center", justifyContent:"center", fontSize:11, fontWeight:700 }}>
                              {i<currentStepIdx?"Γ£ô":i+1}
                            </div>
                            <div style={{ fontSize:9, color:i<=currentStepIdx?"#1d9e75":"#aaa", fontWeight:i===currentStepIdx?700:400, whiteSpace:"nowrap" }}>{s.label}</div>
                          </div>
                          {i<steps.length-1&&(
                            <div style={{ flex:1, height:2, background:i<currentStepIdx?"#1d9e75":"#f0f0f0", marginBottom:14 }}/>
                          )}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )})}
            </div>
          )}
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from "react"
import { ServicesIcon, PartsIcon, MarketplaceIcon, VehicleIcon, DiscoverIcon, PowerIcon, MechanicIcon, GlobeIcon, CameraIcon, UploadShareIcon, WarningIcon, ClockIcon, DocumentIcon, AnalyticsIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import { pushNotify } from "../../lib/pushNotify"
import { sanitizeName, sanitizePhone, sanitizeFreeText } from "../../lib/sanitize"
import { validatePassword } from "../../lib/passwordValidation"
import { getCurrentPosition } from "../../lib/geolocation"
import PhotoManager from "../shared/PhotoManager"
import { useAuth } from "../../contexts/AuthContext"
import { useLanguage } from "../../contexts/LanguageContext"
import useIsMobile from "../../lib/useIsMobile"
import { exportUserData, downloadJSON, downloadCSV, downloadPDF } from "../../lib/dataExport"
import toast from "react-hot-toast"

const PROVIDER_TYPES = [
  { key:"garage", label:"Garage/Mechanic", icon:"services" },
  { key:"parts_dealer", label:"Parts Dealer", icon:"parts" },
  { key:"accessories_shop", label:"Accessories Shop", icon:"marketplace" },
  { key:"tyre_shop", label:"Tyre Shop", icon:"vehicle" },
  { key:"auto_electrician", label:"Auto Electrician", icon:"power" },
  { key:"car_wash", label:"Car Wash", icon:"discover" },
  { key:"panel_beater", label:"Panel Beater", icon:"mechanic" },
  { key:"auto_glass", label:"Auto Glass", icon:"globe" },
]

export default function ProviderProfile() {
  const { profile, updateProfile, user } = useAuth()
  const { t } = useLanguage()
  const isMobile = useIsMobile()
  const [form, setForm] = useState({ first_name:"", last_name:"", business_name:"", city:"", go_service_radius_km:"15" })
  const [sensitive, setSensitive] = useState({ phone:"", email:"", mpesa_number:"", till_number:"", paybill_number:"", paybill_account:"", pochi_number:"", preferred_payment_method:"mpesa" })
  const [location, setLocation] = useState({ latitude:null, longitude:null, address:"" })
  const [saving, setSaving] = useState(false)
  const [locating, setLocating] = useState(false)
  const [tab, setTab] = useState("business")
  const [exporting, setExporting] = useState(false)
  const [exportData, setExportData] = useState(null)

  useEffect(() => {
    if (profile) {
      setForm({ first_name:profile?.first_name||"", last_name:profile?.last_name||"", carries_parts_for_go:profile?.carries_parts_for_go||false, business_name:profile?.business_name||"", city:profile?.city||"", go_service_radius_km:profile?.go_service_radius_km?String(profile.go_service_radius_km):"15" })
      setLocation({ latitude:profile?.latitude||null, longitude:profile?.longitude||null, address:"" })
    }
    if (user) loadSensitive()
  }, [profile, user])

  async function loadSensitive() {
    const { data } = await supabase.from("profile_sensitive").select("phone,email,mpesa_number,till_number,paybill_number,paybill_account,pochi_number,preferred_payment_method").eq("id", user.id).single()
    if (data) setSensitive({ phone:data.phone||"", email:data.email||"", mpesa_number:data.mpesa_number||"", till_number:data.till_number||"", paybill_number:data.paybill_number||"", paybill_account:data.paybill_account||"", pochi_number:data.pochi_number||"", preferred_payment_method:data.preferred_payment_method||"mpesa" })
  }

  async function saveProfile(e) {
    e.preventDefault()
    setSaving(true)
    try { await updateProfile({...form, carries_parts_for_go: form.carries_parts_for_go, go_service_radius_km: form.go_service_radius_km?Number(form.go_service_radius_km):15}); toast.success(t("saveChanges")) }
    catch(err) { toast.error(err.message) }
    finally { setSaving(false) }
  }

  async function saveContact(e) {
    e.preventDefault()
    setSaving(true)
    try {
      await supabase.from("profile_sensitive").update({ 
        phone:sensitive.phone, 
        mpesa_number:sensitive.mpesa_number,
        till_number:sensitive.till_number||null,
        paybill_number:sensitive.paybill_number||null,
        paybill_account:sensitive.paybill_account||null,
        pochi_number:sensitive.pochi_number||null,
        preferred_payment_method:sensitive.preferred_payment_method||"mpesa"
      }).eq("id", user.id)
      toast.success(t("saveChanges"))
    } catch(err) { toast.error(err.message) }
    finally { setSaving(false) }
  }

  async function saveLocation(e) {
    e.preventDefault()
    setSaving(true)
    try {
      await updateProfile({ latitude:parseFloat(location.latitude)||null, longitude:parseFloat(location.longitude)||null, city:form.city, address:location.address||null })
      toast.success("Location saved")
    } catch(err) { toast.error(err.message) }
    finally { setSaving(false) }
  }

  async function detectLocation() {
    setLocating(true)
    getCurrentPosition().then(async pos => {
        const lat = pos.latitude
        const lng = pos.longitude
        setLocation(l=>({...l, latitude:lat, longitude:lng}))
        try {
          const res = await fetch(`https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lng}&format=json`)
          const data = await res.json()
          const city = data.address?.city || data.address?.town || data.address?.suburb || ""
          setLocation(l=>({...l, address:data.display_name||""}))
          if (city) setForm(f=>({...f, city}))
        } catch { /* location parse failed - non-critical */ }
        setLocating(false)
      }).catch(err => { console.warn('Location error:', err.message); toast.error('Could not detect location: ' + err.message) }).finally(() => setLocating(false))
  }

  async function changePassword(e) {
    e.preventDefault()
    const pw = e.target.password.value
    const confirm = e.target.confirm.value
    if (pw !== confirm) return toast.error("Passwords do not match")
    const pwError = validatePassword(pw); if (pwError) return toast.error(pwError)
    const { error } = await supabase.auth.updateUser({ password: pw })
    if (error) return toast.error(error.message)
    toast.success("Password changed")
    e.target.reset()
  }

