          Deleting your account permanently removes all your data within 7 days. Active bookings must be resolved first.
        </div>
        <button onClick={async()=>{
          const{data:ab}=await supabase.from("bookings").select("id").eq("provider_id",user.id).in("status",["pending","confirmed","in-progress"])
          if(ab?.length>0)return toast.error("Resolve active bookings first.")
          if(!window.confirm("Delete your account? This cannot be undone."))return
          await supabase.from("deletion_requests").insert({ user_id:user.id, requested_at:new Date().toISOString(), scheduled_for:new Date(Date.now()+7*24*60*60*1000).toISOString(), status:"pending", reason:"User requested deletion from app" })
          // Notify admin
          const { data: admins } = await supabase.from("profiles").select("id").eq("role","admin")
          if(admins?.length > 0) {
            await supabase.from("notifications").insert(admins.map(a=>({
              user_id: a.id,
              type: "account_deletion",
              title: "Account deletion request",
              message: (profile?.first_name||"A user") + " ("+user.id.slice(0,8)+") has requested account deletion. Scheduled for " + new Date(Date.now()+7*24*60*60*1000).toLocaleDateString(),
              data: { user_id: user.id }
            })))
          }
          toast.success("Deletion requested. You will be signed out.")
          // Notify admin
          supabase.from("profiles").select("id").eq("role","admin").then(({data:admins})=>{
            if(admins?.length>0) {
              supabase.from("notifications").insert(admins.map(a=>({
                user_id:a.id, type:"account_deletion",
                title:"Account deletion request ΓÜá∩╕Å",
                message:"A "+user?.user_metadata?.role+" has requested account deletion.",
                data:{ user_id:user.id }
              })))
              // Send push to all admins
              admins.forEach(a => pushNotify.accountDeletionRequest(a.id, user?.user_metadata?.first_name||"A user", user.id))
            }
          })
          setTimeout(()=>supabase.auth.signOut(),2000)
        }} style={{ background:"#fff", border:"1px solid #e24b4a", borderRadius:8, color:"#e24b4a", fontSize:13, fontWeight:600, padding:"10px 20px", cursor:"pointer" }}>
          Request Account Deletion
        </button>
      </div>
    </div>
  )
}

import useIsMobile from "../../lib/useIsMobile"
import { useEffect, useState } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import toast from "react-hot-toast"
import { useLanguage } from "../../contexts/LanguageContext"

export default function ProviderReviews() {
  const isMobile = useIsMobile()
  const { user, profile } = useAuth()
  const { t, language } = useLanguage()
  const [reviews, setReviews] = useState([])
  const [loading, setLoading] = useState(true)
  const [replying, setReplying] = useState(null)
  const [replyText, setReplyText] = useState("")
  const [submitting, setSubmitting] = useState(false)

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("provider-reviews")
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"reviews", filter:`provider_id=eq.${user.id}` }, () => {
        load()
        toast("New review received!", { icon:"Γ¡É" })
      }).subscribe()
    return () => supabase.removeChannel(sub)
  }, [user])

  async function load() {
    const { data } = await supabase.from("reviews")
      .select("*, profile_public!reviews_customer_id_fkey(first_name,last_name)")
      .eq("provider_id", user.id)
      .order("created_at", { ascending:false })
    setReviews(data||[])
    setLoading(false)
  }

  async function submitReply(id) {
    if (!replyText.trim()) return toast.error("Please write a reply")
    setSubmitting(true)
    const { error } = await supabase.from("reviews")
      .update({ provider_response: replyText })
      .eq("id", id)
      .eq("provider_id", user.id)
    if (error) { toast.error(error.message); setSubmitting(false); return }
    toast.success("Reply posted")
    // Notify customer of provider reply
    try {
      const review = reviews.find(r=>r.id===id)
      if(review?.customer_id) {
        await fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/send-push`, {
          method:"POST",
          headers:{"Content-Type":"application/json","Authorization":`Bearer ${import.meta.env.VITE_SUPABASE_ANON_KEY}`},
          body:JSON.stringify({ user_id:review.customer_id, title:"Provider replied to your review ≡ƒÆ¼", message:`${profile?.business_name||profile?.first_name||"Your provider"} has responded to your review.` })
        })
        await supabase.from("notifications").insert({ user_id:review.customer_id, title:"Provider replied to your review ≡ƒÆ¼", message:`${profile?.business_name||profile?.first_name||"Your provider"} has responded to your review.`, type:"info" })
      }
    } catch(e) { console.log("Push failed:",e.message) }
    setReplying(null); setReplyText(""); setSubmitting(false); load()
  }

  const avgRating = reviews.length > 0
    ? (reviews.reduce((s,r) => s + (r.provider_rating||0), 0) / reviews.length).toFixed(1)
    : "0.0"

  const dist = [5,4,3,2,1].map(n => ({
    star: n,
    count: reviews.filter(r => r.provider_rating === n).length,
    pct: reviews.length ? Math.round(reviews.filter(r=>r.provider_rating===n).length/reviews.length*100) : 0
  }))

  return (
    <div>
      {reviews.length > 0 && (
        <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem", marginBottom:"1.25rem", display:"flex", gap:"1.5rem", alignItems:"center" }}>
          <div style={{ textAlign:"center", flexShrink:0 }}>
            <div style={{ fontFamily:"Syne", fontSize:40, fontWeight:800, color:"#e6821e", lineHeight:1 }}>{avgRating}</div>
            <div style={{ display:"flex", justifyContent:"center", gap:2, margin:"6px 0" }}>
              {[1,2,3,4,5].map(s=>(
                <span key={s} style={{ color: s <= Math.round(avgRating) ? "#e6821e" : "#555555", fontSize:16 }}>Γÿà</span>
              ))}
            </div>
            <div style={{ fontSize:11, color:"#777777" }}>{reviews.length} review{reviews.length!==1?"s":""}</div>
          </div>
          <div style={{ flex:1 }}>
            {dist.map(d => (
              <div key={d.star} style={{ display:"flex", alignItems:"center", gap:8, marginBottom:5 }}>
                <div style={{ fontSize:11, color:"#555555", width:10 }}>{d.star}</div>
                <span style={{ color:"#e6821e", fontSize:12 }}>Γ£ô</span>
                <div style={{ flex:1, height:6, background:"#f0f0f0", borderRadius:3, overflow:"hidden" }}>
                  <div style={{ height:"100%", background:"#e6821e", borderRadius:3, width:`${d.pct}%`, transition:"width 0.5s" }} />
                </div>
                <div style={{ fontSize:11, color:"#777777", width:24, textAlign:"right" }}>{d.count}</div>
              </div>
            ))}
          </div>
        </div>
      )}

      {loading && <div style={{ color:"#777777", fontSize:13 }}>Loading...</div>}
      {!loading && reviews.length === 0 && (
        <div style={{ color:"#888888", fontSize:13, textAlign:"center", padding:"2rem" }}>No reviews yet. {["parts_dealer","accessories_shop"].includes(profile?.provider_type) ? "Complete orders" : "Complete bookings"} to receive ratings.</div>
      )}

      {reviews.map(r => (
        <div key={r.id} style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:10, padding:"1rem", marginBottom:10 }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
            <div style={{ display:"flex", alignItems:"center", gap:10 }}>
              <div style={{ width:36, height:36, borderRadius:"50%", background:"#fff8f0", border:"1px solid #e6821e30", display:"flex", alignItems:"center", justifyContent:"center", fontSize:12, fontWeight:700, color:"#e6821e" }}>
                {r.profile_public?.first_name?.[0]}{r.profile_public?.last_name?.[0]}
              </div>
              <div>
                <div style={{ fontSize:13, fontWeight:500, color:"#000000" }}>{r.profile_public?.first_name} {r.profile_public?.last_name}</div>
                <div style={{ fontSize:10, color:"#888888" }}>{new Date(r.created_at).toLocaleDateString()}</div>
              </div>
            </div>
            <div style={{ display:"flex", gap:1 }}>
              {[1,2,3,4,5].map(s=>(
                <span key={s} style={{ color: s <= r.provider_rating ? "#e6821e" : "#555555", fontSize:16 }}>Γÿà</span>
              ))}
            </div>
          </div>

          {r.provider_review && (
            <div style={{ fontSize:13, color:"#666666", lineHeight:1.6, marginBottom:10 }}>"{r.provider_review}"</div>
          )}

          {r.driver_rating > 0 && (
            <div style={{ fontSize:11, color:"#777777", marginBottom:10 }}>
              Driver rated: {[1,2,3,4,5].map(s=><span key={s} style={{ color: s<=r.driver_rating?"#378add":"#555555" }}>Γÿà</span>)}
            </div>
          )}

          {r.provider_response ? (
            <div style={{ background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"0.75rem" }}>
              <div style={{ fontSize:10, color:"#777777", marginBottom:4 }}>Your reply</div>
              <div style={{ fontSize:12, color:"#555555", lineHeight:1.5 }}>{r.provider_response}</div>
              <button onClick={() => { setReplying(r.id); setReplyText(r.provider_response) }}
                style={{ background:"none", border:"none", color:"#777777", fontSize:11, cursor:"pointer", marginTop:6, fontFamily:"'DM Sans',sans-serif", padding:0 }}>
                Edit reply
              </button>
            </div>
          ) : (
            <button onClick={() => { setReplying(r.id); setReplyText("") }}
              style={{ background:"none", border:"1px solid #dddddd", borderRadius:7, color:"#555555", fontSize:11, padding:"5px 12px", cursor:"pointer" }}>
              Reply to review
            </button>
          )}

          {replying === r.id && (
            <div style={{ marginTop:10 }}>
              <textarea value={replyText} onChange={e=>setReplyText(e.target.value)} rows={3}
                placeholder="Write your reply to this review..."
                style={{ width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"10px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif", resize:"vertical", marginBottom:8 }} />
              <div style={{ display:"flex", gap:8 }}>
                <button onClick={() => submitReply(r.id)} disabled={submitting}
                  style={{ background:"#e6821e", border:"none", borderRadius:7, color:"#fff", fontSize:12, fontWeight:700, padding:"7px 16px", cursor:"pointer", fontFamily:"Syne,sans-serif" }}>
                  {submitting ? "Posting..." : language==="sw"?"Chapisha jibu":"Post reply"}
                </button>
                <button onClick={() => { setReplying(null); setReplyText("") }}
                  style={{ background:"none", border:"1px solid #dddddd", borderRadius:7, color:"#555555", fontSize:12, padding:"7px 16px", cursor:"pointer" }}>
                  Cancel
                </button>
              </div>
            </div>
          )}
        </div>
      ))}
    </div>
  )
}

import { useEffect, useState } from "react"
import { MarketplaceIcon, HomeIcon, GOServiceIcon, DiscoverIcon, ServicesIcon, StarIcon, MechanicIcon, PartsIcon } from "../../lib/cccIcons"
import { supabase } from "../../lib/supabase"
import PhotoManager from "../shared/PhotoManager"
import { useAuth } from "../../contexts/AuthContext"
import { useLanguage } from "../../contexts/LanguageContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const GARAGE_CATEGORIES = [
  { key:"shop_standard", label:"Shop Standard", icon:"marketplace", desc:"Customer brings car to your shop", color:"#378add", bg:"#eff6ff", border:"#bfdbfe" },
  { key:"shop_premium", label:"Shop Premium", icon:"home", desc:"Your mechanic goes to customer", color:"#8b5cf6", bg:"#faf5ff", border:"#e9d5ff" },
  { key:"go_service", label:"GO Service", icon:"emergency", desc:"Emergency roadside assistance", color:"#e24b4a", bg:"#fff5f5", border:"#fecaca" },
]
const WASH_CATEGORIES = [
  { key:"basic_wash", label:"Basic Wash", icon:"discover", desc:"Exterior rinse and dry", color:"#378add", bg:"#eff6ff", border:"#bfdbfe" },
  { key:"standard_wash", label:"Standard Wash", icon:"star", desc:"Exterior + interior clean", color:"#8b5cf6", bg:"#faf5ff", border:"#e9d5ff" },
  { key:"premium_detail", label:"Premium Detail", icon:"star", desc:"Full detailing service", color:"#1d9e75", bg:"#f0fdf4", border:"#bbf7d0" },
]
const PANEL_CATEGORIES = [
  { key:"shop_standard", label:"In Shop", icon:"marketplace", desc:"Customer brings car to shop", color:"#378add", bg:"#eff6ff", border:"#bfdbfe" },
  { key:"shop_premium", label:"On Site", icon:"mechanic", desc:"Go to customer location", color:"#8b5cf6", bg:"#faf5ff", border:"#e9d5ff" },
]
function getCategories(providerType) {
  if (providerType === "car_wash") return WASH_CATEGORIES
  if (["panel_beater","auto_glass","auto_electrician"].includes(providerType)) return PANEL_CATEGORIES
  return GARAGE_CATEGORIES
}

const EMPTY = { name:"", description:"", price:"", discounted_price:"", duration_minutes:"", category:"shop_standard", service_category_id:"", photos:[] }

export default function ProviderServices() {
  const { user, profile } = useAuth()
  const providerType = profile?.provider_type || "garage"
  const CATEGORIES = getCategories(providerType)
  const isInventoryProvider = ["parts_dealer","accessories_shop"].includes(providerType)
  const { t } = useLanguage()
  const isMobile = useIsMobile()
  const [services, setServices] = useState([])
  const [loading, setLoading] = useState(true)
  const [tierRates, setTierRates] = useState({})
  const [showForm, setShowForm] = useState(false)
  const [editing, setEditing] = useState(null)
  const [form, setForm] = useState(EMPTY)
  const [saving, setSaving] = useState(false)
  const [activeCategory, setActiveCategory] = useState("all")
  const [serviceCategories, setServiceCategories] = useState([])
  const [search, setSearch] = useState("")

  useEffect(() => {
    if (!user) return
    load()
    supabase.from("service_categories").select("*").eq("is_active", true).order("name")
      .then(({ data }) => setServiceCategories(data||[]))
    // Load commission rates for every tier this provider type can use
    const providerType = profile?.provider_type || "garage"
    const tierKeys = getCategories(providerType).map(cat => providerType + "_" + cat.key)
    supabase.from("commission_rates").select("provider_type,platform_rate,provider_rate")
      .in("provider_type", tierKeys)
      .then(({ data }) => {
        const map = {}
        for (const row of (data||[])) {
          const tierKey = row.provider_type.replace(providerType + "_", "")
          map[tierKey] = { platform: row.platform_rate, provider: row.provider_rate }
        }
        setTierRates(map)
      })
  }, [user, profile?.provider_type])

  async function load() {
    const { data } = await supabase.from("services").select("*").eq("provider_id", user.id).order("created_at", { ascending:false })
    setServices(data||[])
    setLoading(false)
  }

  async function save(e) {
    e.preventDefault()
    if (!form.name||!form.price) return toast.error("Name and price required")
    setSaving(true)

    const cat = CATEGORIES.find(c=>c.key===form.category)
    const rate = tierRates[form.category]
    const platformRate = rate ? Number(rate.platform) : 0.10
    const providerRate = rate ? Number(rate.provider) : 0.90

    try {
      if (editing) {
        const { error } = await supabase.from("services").update({
          name: form.name,
          description: form.description,
          price: parseFloat(form.price),
          duration_minutes: parseInt(form.duration_minutes)||60,
          category: form.category,
          service_category_id: form.service_category_id||null,
          provider_commission_rate: providerRate,
          photos: form.photos||[],
        }).eq("id", editing).eq("provider_id", user.id)
        if (error) throw error
        toast.success("Service updated")
      } else {
        const { error } = await supabase.from("services").insert({
          provider_id: user.id,
          name: form.name,
          description: form.description,
          price: parseFloat(form.price),
          category: form.category||"shop_standard",
          duration_minutes: parseInt(form.duration_minutes)||60,
          photos: form.photos||[],
          platform_commission_rate: platformRate,
          is_active: true,
        })
        if (error) throw error
        toast.success("Service added")
      }
      setForm(EMPTY)
      setShowForm(false)
      setEditing(null)
      load()
    } catch(err) {
      toast.error(err.message)
    } finally {
      setSaving(false)
    }
  }

  async function toggleActive(id, is_active) {
    await supabase.from("services").update({ is_active:!is_active }).eq("id",id).eq("provider_id",user.id)
    load()
  }

  async function deleteService(id) {
    if (!confirm("Delete this service?")) return
    // Soft delete - deactivate service
    await supabase.from("services").update({ is_active:false }).eq("id",id).eq("provider_id",user.id)
    
    // Cancel pending bookings for this service
    const { data: pendingBookings } = await supabase
      .from("bookings")
      .select("id,customer_id,service_name")
      .eq("service_id", id)
      .in("status", ["pending","confirmed"])
    
    if (pendingBookings?.length > 0) {
      // Cancel the bookings
      await supabase.from("bookings")
        .update({ status:"cancelled", cancellation_reason:"Service no longer available" })
        .eq("service_id", id)
        .in("status", ["pending","confirmed"])
      
      // Notify each affected customer
      for (const booking of pendingBookings) {
        await supabase.from("notifications").insert({
          user_id: booking.customer_id,
          title: "Booking cancelled",
          message: `Your booking for "${booking.service_name}" has been cancelled as the service is no longer available. Please book an alternative service.`,
          type: "warning",
        })
      }
      toast.success(`Service deactivated ┬╖ ${pendingBookings.length} pending booking(s) cancelled and customers notified`)
    } else {
      toast.success("Service deactivated")
    }
    toast.success("Service deleted")
    load()
  }

  function startEdit(s) {
    setEditing(s.id)
    setForm({ name:s.name, description:s.description||"", price:s.price, discounted_price:s.discounted_price||"", duration_minutes:s.duration_minutes||60, category:s.category||"shop_standard", service_category_id:s.service_category_id||"" })
    setShowForm(true)
  }
  const filtered = services.filter(s=> (activeCategory==="all" || s.category===activeCategory) && (!search || s.name.toLowerCase().includes(search.toLowerCase()) || (s.description||"").toLowerCase().includes(search.toLowerCase())))
  const inp = { width:"100%", background:"#ffffff", border:"1px solid #e5e5e5", borderRadius:8, padding:"11px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif" }
  const lbl = { fontSize:11, color:"#666", textTransform:"uppercase", letterSpacing:"0.05em", display:"block", marginBottom:4 }

  if (isInventoryProvider) return (
    <div style={{ textAlign:"center", padding:"3rem 1rem" }}>
      <div style={{ fontSize:48, marginBottom:16 }}>≡ƒôª</div>
      <div style={{ fontFamily:"Syne", fontSize:18, fontWeight:800, color:"#000000", marginBottom:8 }}>
        {providerType==="parts_dealer"?"Parts Dealer":"Accessories Shop"}
      </div>
      <div style={{ fontSize:13, color:"#777777", marginBottom:"1.5rem", lineHeight:1.7 }}>
        As a {providerType.replace(/_/g," ")}, you manage your products through Inventory, not services.
        Customers browse and order your items from the Parts Marketplace.
      </div>
      <div style={{ display:"flex", gap:10, justifyContent:"center", flexWrap:"wrap" }}>
        <a href="/dashboard/inventory" style={{ background:"#8b5cf6", border:"none", borderRadius:10, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px 24px", textDecoration:"none" }}>
          ≡ƒôª Go to Inventory
        </a>
        <a href="/dashboard/orders" style={{ background:"#ffffff", border:"1px solid #dddddd", borderRadius:10, color:"#555555", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"11px 24px", textDecoration:"none" }}>
          ≡ƒ¢Æ View Orders
        </a>
      </div>
    </div>
  )

  return (
    <div>
      {/* Category overview cards */}
      <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"repeat(3,1fr)", gap:10, marginBottom:"1.5rem" }}>
        {CATEGORIES.map(c=>(
          <div key={c.key} style={{ background:c.bg, border:`1px solid ${c.border}`, borderRadius:12, padding:"1rem" }}>
            <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:6 }}>
              <span style={{display:"flex", alignItems:"center"}}>
              {c.icon==="marketplace"?<MarketplaceIcon size={20} color={c.color}/>:
               c.icon==="home"?<HomeIcon size={20} color={c.color}/>:
               c.icon==="emergency"?<GOServiceIcon size={20} color="#e24b4a"/>:
               c.icon==="discover"?<DiscoverIcon size={20} color={c.color}/>:
               c.icon==="star"?<StarIcon size={20} color={c.color}/>:
               c.icon==="mechanic"?<MechanicIcon size={20} color={c.color}/>:
               <ServicesIcon size={20} color={c.color}/>}
            </span>
              <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:800, color:c.color }}>{c.label}</div>
            </div>
            <div style={{ fontSize:11, color:"#666", marginBottom:4 }}>{c.desc}</div>
            <div style={{ fontSize:10, color:c.color, fontWeight:600 }}>{c.commission}</div>
            <div style={{ fontSize:10, color:"#888888", marginTop:4 }}>
              {services.filter(s=>s.category===c.key).length} service{services.filter(s=>s.category===c.key).length!==1?"s":""}
            </div>
          </div>
        ))}
      </div>

      <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search your services..." style={{ width:"100%", background:"#f8f8f8", border:"1px solid #eee", borderRadius:8, padding:"9px 12px", fontSize:13, outline:"none", marginBottom:"1rem", boxSizing:"border-box" }}/>
      {/* Header */}
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1rem", flexWrap:"wrap", gap:10 }}>
        <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
          {["all",...CATEGORIES.map(c=>c.key)].map(k=>(
            <button key={k} onClick={()=>setActiveCategory(k)}
              style={{ padding:"6px 12px", borderRadius:7, border:"none", fontSize:11, cursor:"pointer", background:activeCategory===k?"#e6821e":"#555555", color:activeCategory===k?"#fff":"#666", fontFamily:"'DM Sans',sans-serif" }}>
              {k==="all"?"All":CATEGORIES.find(c=>c.key===k)?.label}
            </button>
          ))}
        </div>
        <button onClick={()=>{ setShowForm(true); setEditing(null); setForm(EMPTY) }}
          style={{ background:"#e6821e", border:"none", borderRadius:9, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:13, fontWeight:700, padding:"9px 18px", cursor:"pointer" }}>
          + Add service
        </button>
      </div>

      {/* Add/Edit form */}
      {showForm&&(
        <div style={{ background:"#ffffff", border:"1px solid #eeeeee", borderRadius:12, padding:"1.25rem", marginBottom:"1.5rem" }}>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700, marginBottom:"1rem", color:"#000000" }}>
            {editing?"Edit service":"Add new service"}
          </div>

          {/* Service type selector (admin-managed categories like Oil Change, Brake Repair) */}
          {serviceCategories.length>0&&(
            <div style={{ marginBottom:16 }}>
              <label style={lbl}>What type of service is this?</label>
              <select value={form.service_category_id} onChange={e=>setForm(f=>({...f,service_category_id:e.target.value}))}
                style={{ width:"100%", background:"#ffffff", border:"1px solid #f0f0f0", borderRadius:8, padding:"10px 12px", color:"#000000", fontSize:13, outline:"none", fontFamily:"'DM Sans',sans-serif" }}>
                <option value="">Select a category...</option>
                {serviceCategories.map(sc=>(
                  <option key={sc.id} value={sc.id}>{sc.icon} {sc.name}</option>
                ))}
              </select>
            </div>
          )}

          {/* Category selector */}
          <div style={{ marginBottom:16 }}>
            <label style={lbl}>Pricing tier</label>
            <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"repeat(3,1fr)", gap:8 }}>
              {CATEGORIES.map(c=>(
                <button key={c.key} type="button" onClick={()=>setForm(f=>({...f,category:c.key}))}
                  style={{ background:form.category===c.key?c.bg:"#ffffff", border:`1px solid ${form.category===c.key?c.color:"#f5f5f5"}`, borderRadius:9, padding:"0.75rem", cursor:"pointer", textAlign:"left" }}>
                  <div style={{ marginBottom:4, display:"flex" }}>
                  {c.icon==="marketplace"?<MarketplaceIcon size={16} color={c.color}/>:
                   c.icon==="home"?<HomeIcon size={16} color={c.color}/>:
                   c.icon==="emergency"?<GOServiceIcon size={16} color="#e24b4a"/>:
                   c.icon==="discover"?<DiscoverIcon size={16} color={c.color}/>:
                   c.icon==="star"?<StarIcon size={16} color={c.color}/>:
                   c.icon==="mechanic"?<MechanicIcon size={16} color={c.color}/>:
                   <ServicesIcon size={16} color={c.color}/>}
                </div>
                  <div style={{ fontSize:12, fontWeight:600, color:form.category===c.key?c.color:"#666", marginBottom:2 }}>{c.label}</div>
                  <div style={{ fontSize:10, color:"#888888" }}>{c.commission}</div>
                </button>
              ))}
            </div>
          </div>

          <form onSubmit={save}>
            <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"1fr 1fr", gap:12, marginBottom:12 }}>
              <div>
                <label style={lbl}>Service name</label>
                <input style={inp} placeholder="e.g. Oil Change" value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))} required/>
              </div>
              <div>
                <label style={lbl}>Price (KES)</label>
                <input style={inp} type="number" placeholder="e.g. 2500" value={form.price} onChange={e=>setForm(f=>({...f,price:e.target.value}))} required min="0" step="0.01"/>
              </div>
              <div>
                <label style={lbl}>Discounted price (KES) ΓÇö optional</label>
                <input style={inp} type="number" placeholder="Leave empty if no discount" value={form.discounted_price} onChange={e=>setForm(f=>({...f,discounted_price:e.target.value}))} min="0" step="0.01"/>
              </div>
            </div>
            <div style={{ display:"grid", gridTemplateColumns:isMobile?"1fr":"1fr 1fr", gap:12, marginBottom:12 }}>
              <div>
                <label style={lbl}>Duration (minutes)</label>
                <input style={inp} type="number" placeholder="60" value={form.duration_minutes} onChange={e=>setForm(f=>({...f,duration_minutes:e.target.value}))} min="15"/>
              </div>
              <div style={{ display:"flex", flexDirection:"column", justifyContent:"flex-end" }}>
                {form.category&&(
                  <div style={{ background:CATEGORIES.find(c=>c.key===form.category)?.bg||"#555555", border:`1px solid ${CATEGORIES.find(c=>c.key===form.category)?.border||"#f5f5f5"}`, borderRadius:8, padding:"0.6rem 0.75rem" }}>
                    <div style={{ fontSize:10, color:"#777777", marginBottom:2 }}>Commission preview</div>
                    <div style={{ fontSize:12, color:CATEGORIES.find(c=>c.key===form.category)?.color||"#888", fontWeight:600 }}>
                      {CATEGORIES.find(c=>c.key===form.category)?.commission}
                    </div>
                    {form.price&&<div style={{ fontSize:11, color:"#777777", marginTop:2 }}>
                      Your earnings: KES {(parseFloat(form.price||0)*(tierRates[form.category]?Number(tierRates[form.category].provider):0.90)).toFixed(0)}
                    </div>}
                  </div>
                )}
              </div>
            </div>
            <div style={{ marginBottom:14 }}>
              <label style={lbl}>Description</label>
