            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", gap:10 }}>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4, flexWrap:"wrap" }}>
                  <span style={{display:"flex", alignItems:"center"}}>
    {cat.icon==="marketplace"?<MarketplaceIcon size={16} color={cat.color}/>:
     cat.icon==="home"?<HomeIcon size={16} color={cat.color}/>:
     cat.icon==="emergency"?<GOServiceIcon size={16} color="#e24b4a"/>:
     cat.icon==="discover"?<DiscoverIcon size={16} color={cat.color}/>:
     cat.icon==="star"?<StarIcon size={16} color={cat.color}/>:
     cat.icon==="mechanic"?<MechanicIcon size={16} color={cat.color}/>:
     cat.icon==="parts"?<PartsIcon size={16} color={cat.color}/>:
     <ServicesIcon size={16} color={cat.color}/>}
  </span>
                  <div style={{ fontSize:13, fontWeight:600, color:"#000000" }}>{s.name}</div>
                  <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:cat.bg, color:cat.color, border:`1px solid ${cat.border}` }}>{cat.label}</span>
                  {!s.is_active&&<span style={{ fontSize:10, color:"#777777", background:"#f5f5f5", padding:"2px 8px", borderRadius:10 }}>Inactive</span>}
                </div>
                {s.photos?.length>0&&(
                  <div style={{ display:"flex", gap:6, marginBottom:6, flexWrap:"wrap" }}>
                    {s.photos.slice(0,3).map((url,i)=>(
                      <img key={i} src={url} alt="" style={{ width:56, height:56, objectFit:"cover", borderRadius:8, border:"1px solid #eee" }}/>
                    ))}
                    {s.photos.length>3&&<div style={{ width:56, height:56, borderRadius:8, background:"#f0f0f0", display:"flex", alignItems:"center", justifyContent:"center", fontSize:12, color:"#888" }}>+{s.photos.length-3}</div>}
                  </div>
                )}
                {s.description&&<div style={{ fontSize:11, color:"#666", marginBottom:4, lineHeight:1.5 }}>{s.description}</div>}
                <div style={{ display:"flex", gap:12, flexWrap:"wrap" }}>
                  {s.discounted_price ? (
                    <span>
                      <span style={{ fontSize:12, color:"#888", textDecoration:"line-through", marginRight:4 }}>KES {Number(s.price).toLocaleString()}</span>
                      <span style={{ fontSize:12, color:"#1d9e75", fontFamily:"Syne", fontWeight:700 }}>KES {Number(s.discounted_price).toLocaleString()}</span>
                      <span style={{ fontSize:10, color:"#1d9e75", background:"#f0fdf4", padding:"1px 6px", borderRadius:10, marginLeft:4 }}>
                        {Math.round((1-s.discounted_price/s.price)*100)}% OFF
                      </span>
                    </span>
                  ) : (
                    <span style={{ fontSize:12, color:"#e6821e", fontFamily:"Syne", fontWeight:700 }}>KES {Number(s.price).toLocaleString()}</span>
                  )}
                  <span style={{ fontSize:11, color:"#777777" }}>ΓÅ▒ {s.duration_minutes||60} min</span>
                  <span style={{ fontSize:11, color:cat.color }}>{tierRates[cat.key]?`You keep ${Math.round(tierRates[cat.key].provider*100)}% ┬╖ Platform ${Math.round(tierRates[cat.key].platform*100)}%`:"Loading rate..."}</span>
                </div>
              </div>
              <div style={{ display:"flex", gap:6, flexShrink:0, flexWrap:"wrap", justifyContent:"flex-end" }}>
                <button onClick={()=>startEdit(s)}
                  style={{ background:"#eff6ff", border:"1px solid #378add40", borderRadius:7, color:"#378add", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                  Edit
                </button>
                <button onClick={()=>toggleActive(s.id, s.is_active)}
                  style={{ background:s.is_active?"#fff5f5":"#f0fdf4", border:`1px solid ${s.is_active?"#e24b4a40":"#1d9e7540"}`, borderRadius:7, color:s.is_active?"#e24b4a":"#1d9e75", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                  {s.is_active?"Deactivate":"Activate"}
                </button>
                <button onClick={()=>{ if(confirm("Deactivate this service? Pending bookings will be cancelled and customers notified.")) deleteService(s.id) }}
                  style={{ background:"none", border:"1px solid #e24b4a20", borderRadius:7, color:"#e24b4a", fontSize:11, padding:"5px 10px", cursor:"pointer" }}>
                  Delete
                </button>
              </div>
            </div>
          </div>
        )
      })}
    </div>
  )
}

import { useEffect, useState, useRef } from "react"
import { supabase } from "../../lib/supabase"
import { useAuth } from "../../contexts/AuthContext"
import useIsMobile from "../../lib/useIsMobile"
import toast from "react-hot-toast"

const CATEGORIES = [
  { k:"commission", l:"Commission Dispute", icon:"≡ƒÆ░" },
  { k:"payment", l:"Payment Issue", icon:"≡ƒÆ│" },
  { k:"booking", l:"Booking Problem", icon:"≡ƒôà" },
  { k:"account", l:"Account Issue", icon:"≡ƒæñ" },
  { k:"inventory", l:"Inventory/Orders", icon:"≡ƒôª" },
  { k:"mechanic", l:"Mechanic Issue", icon:"≡ƒöº" },
  { k:"go_service", l:"GO Service", icon:"≡ƒÜ¿" },
  { k:"technical", l:"Technical Problem", icon:"ΓÜÖ∩╕Å" },
  { k:"other", l:"Other", icon:"≡ƒÆ¼" },
]
const PRIORITIES = [
  { k:"low", l:"Low" },
  { k:"medium", l:"Medium" },
  { k:"high", l:"High ≡ƒö┤" },
]
const STATUS_COLOR = { open:"#e6821e", in_progress:"#378add", resolved:"#1d9e75", closed:"#888" }
const FAQ = [
  { q:"How is my commission calculated?", a:"Commission is deducted automatically from each booking. Rates are set by admin and visible in your earnings dashboard." },
  { q:"When do I receive my payout?", a:"Payouts are sent automatically to your M-Pesa/Till/Paybill after customer payment is confirmed." },
  { q:"How do I add a mechanic?", a:"Go to Mechanics tab, then Add Mechanic. Set their PIN for mobile login." },
  { q:"How do I handle a GO Service request?", a:"GO requests appear with a loud alarm. You have 15 minutes to accept and dispatch a mechanic." },
  { q:"What happens if a claim is filed against me?", a:"Admin will investigate and contact you for evidence. Approved claims result in penalties per our Service Guarantee policy." },
  { q:"How do I update my business hours?", a:"Go to Business Hours tab in your dashboard to set available days and times." },
]

export default function ProviderSupport() {
  const { user, profile } = useAuth()
  const isMobile = useIsMobile()
  const [tickets, setTickets] = useState([])
  const [selected, setSelected] = useState(null)
  const [messages, setMessages] = useState([])
  const [newMessage, setNewMessage] = useState("")
  const [loading, setLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const [sending, setSending] = useState(false)
  const [tab, setTab] = useState("faq")
  const [expandedFaq, setExpandedFaq] = useState(null)
  const [form, setForm] = useState({ subject:"", category:"commission", priority:"medium", message:"" })
  const messagesEndRef = useRef(null)

  useEffect(() => {
    if (!user) return
    load()
    const sub = supabase.channel("provider-support-"+user.id)
      .on("postgres_changes", { event:"INSERT", schema:"public", table:"support_messages" },
        payload => {
          if (selected && payload.new.ticket_id === selected.id) {
            setMessages(m => [...m, payload.new])
            setTimeout(() => messagesEndRef.current?.scrollIntoView({ behavior:"smooth" }), 100)
          }
          load()
        })
      .subscribe()
    return () => supabase.removeChannel(sub)
  }, [user, selected])

  async function load() {
    const { data } = await supabase.from("support_tickets")
      .select("*").eq("user_id", user.id)
      .order("updated_at", { ascending:false })
    setTickets(data||[])
    setLoading(false)
  }

  async function loadMessages(ticketId) {
    const { data } = await supabase.from("support_messages")
      .select("*, sender:profiles!support_messages_sender_id_fkey(first_name,last_name,role)")
      .eq("ticket_id", ticketId).order("created_at", { ascending:true })
    setMessages(data||[])
    setTimeout(() => messagesEndRef.current?.scrollIntoView({ behavior:"smooth" }), 100)
  }

  async function submitTicket(e) {
    e.preventDefault()
    if (!form.subject.trim() || !form.message.trim()) return toast.error("Please fill all fields")
    setSubmitting(true)
    try {
      const { data: ticket, error } = await supabase.from("support_tickets").insert({
        customer_id: user.id, user_id: user.id, user_role: "provider",
        subject: form.subject, category: form.category, priority: form.priority,
      }).select().single()
      if (error) throw error
      await supabase.from("support_messages").insert({ ticket_id: ticket.id, sender_id: user.id, message: form.message, is_staff: false })
      await supabase.from("notifications").insert({ user_id: user.id, title: "Support ticket created", message: "Ticket "+ticket.ticket_number+" submitted. We respond within 24 hours.", type: "info" })
      const { data: admins } = await supabase.from("profiles").select("id").eq("role","admin")
      for (const admin of (admins||[])) {
        await supabase.from("notifications").insert({ user_id: admin.id, title: "Provider support ticket"+(form.priority==="high"?" HIGH":""), message: (profile?.business_name||profile?.first_name||"Provider")+" ΓÇö "+form.subject+" ["+form.category+"]", type: form.priority==="high"?"error":"info" })
      }
      toast.success("Ticket "+ticket.ticket_number+" created!")
      setForm({ subject:"", category:"commission", priority:"medium", message:"" })
      setTab("tickets"); load()
    } catch(err) { toast.error(err.message) }
    finally { setSubmitting(false) }
  }

  async function sendMessage(e) {
    e.preventDefault()
    if (!newMessage.trim() || !selected) return
    setSending(true)
    const { error } = await supabase.from("support_messages").insert({ ticket_id: selected.id, sender_id: user.id, message: newMessage.trim(), is_staff: false })
    if (!error) { setNewMessage(""); loadMessages(selected.id) }
    else toast.error(error.message)
    setSending(false)
  }

  const inp = { width:"100%", background:"#fff", border:"1px solid #e0e0e0", borderRadius:8, padding:"10px 12px", fontSize:13, outline:"none", fontFamily:"DM Sans,sans-serif", marginBottom:10, boxSizing:"border-box" }
  const SC = STATUS_COLOR

  if (selected) return (
    <div style={{ display:"flex", flexDirection:"column", height:"calc(100vh - 140px)" }}>
      <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:12 }}>
        <button onClick={()=>{ setSelected(null); setMessages([]) }} style={{ background:"none", border:"none", fontSize:20, cursor:"pointer" }}>ΓåÉ</button>
        <div>
          <div style={{ fontFamily:"Syne", fontSize:14, fontWeight:700 }}>{selected.subject}</div>
          <div style={{ display:"flex", gap:6, alignItems:"center", marginTop:2 }}>
            <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:(SC[selected.status]||"#888")+"20", color:SC[selected.status]||"#888" }}>{selected.status?.replace("_"," ")}</span>
            <span style={{ fontSize:10, color:"#888" }}>#{selected.ticket_number}</span>
          </div>
        </div>
      </div>
      <div style={{ flex:1, overflowY:"auto", display:"flex", flexDirection:"column", gap:8, paddingBottom:8 }}>
        {messages.map(m=>(
          <div key={m.id} style={{ display:"flex", flexDirection:"column", alignItems:m.sender_id===user.id?"flex-end":"flex-start" }}>
            <div style={{ fontSize:10, color:"#888", marginBottom:2 }}>{m.is_staff?"CCC Support":((m.sender?.first_name||"")+" "+(m.sender?.last_name||"")).trim()||"You"} ┬╖ {new Date(m.created_at).toLocaleTimeString()}</div>
            <div style={{ maxWidth:"80%", background:m.sender_id===user.id?"#378add":"#f0f0f0", color:m.sender_id===user.id?"#fff":"#000", borderRadius:m.sender_id===user.id?"12px 12px 4px 12px":"12px 12px 12px 4px", padding:"8px 12px", fontSize:13 }}>
              {m.message}
            </div>
          </div>
        ))}
        <div ref={messagesEndRef}/>
      </div>
      <form onSubmit={sendMessage} style={{ display:"flex", gap:8, paddingTop:8, borderTop:"1px solid #eee" }}>
        <input value={newMessage} onChange={e=>setNewMessage(e.target.value)} placeholder="Type your message..." style={{ ...inp, marginBottom:0, flex:1 }}/>
        <button type="submit" disabled={sending||!newMessage.trim()} style={{ background:"#378add", border:"none", borderRadius:8, color:"#fff", padding:"10px 18px", cursor:"pointer", fontWeight:700, fontSize:13 }}>{sending?"...":"Send"}</button>
      </form>
    </div>
  )

  return (
    <div>
      <div style={{ fontFamily:"Syne", fontSize:isMobile?16:18, fontWeight:800, marginBottom:4 }}>Provider Support</div>
      <div style={{ fontSize:12, color:"#777", marginBottom:"1.25rem" }}>Get help with your business account, payments, and services.</div>
      <div style={{ display:"flex", gap:6, marginBottom:"1.25rem", overflowX:"auto", paddingBottom:4 }}>
        {[{k:"faq",l:"FAQ"},{k:"tickets",l:"My Tickets ("+tickets.length+")"},{k:"new",l:"+ New Ticket"}].map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)} style={{ padding:"8px 16px", borderRadius:8, border:"none", fontSize:12, cursor:"pointer", background:tab===t.k?"#378add":"#f0f0f0", color:tab===t.k?"#fff":"#555", fontWeight:tab===t.k?700:400, whiteSpace:"nowrap" }}>{t.l}</button>
        ))}
      </div>
      {tab==="faq"&&(
        <div>
          {FAQ.map((f,i)=>(
            <div key={i} onClick={()=>setExpandedFaq(expandedFaq===i?null:i)} style={{ background:"#fff", border:"1px solid #eee", borderRadius:10, padding:"0.75rem 1rem", marginBottom:8, cursor:"pointer" }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                <div style={{ fontSize:13, fontWeight:600 }}>{f.q}</div>
                <div style={{ fontSize:14, color:"#888" }}>{expandedFaq===i?"Γû▓":"Γû╝"}</div>
              </div>
              {expandedFaq===i&&<div style={{ fontSize:12, color:"#555", marginTop:8, lineHeight:1.6 }}>{f.a}</div>}
            </div>
          ))}
        </div>
      )}
      {tab==="tickets"&&(
        <div>
          {loading&&<div style={{ color:"#888", fontSize:13 }}>Loading...</div>}
          {!loading&&tickets.length===0&&<div style={{ color:"#888", fontSize:13, textAlign:"center", padding:"2rem" }}>No tickets yet. Tap + New Ticket to get help.</div>}
          {tickets.map(t=>(
            <div key={t.id} onClick={()=>{ setSelected(t); loadMessages(t.id) }} style={{ background:"#fff", border:"1px solid #eee", borderRadius:10, padding:"0.75rem 1rem", marginBottom:8, cursor:"pointer" }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:600 }}>{t.subject}</div>
                  <div style={{ fontSize:10, color:"#888", marginTop:2 }}>#{t.ticket_number} ┬╖ {t.category} ┬╖ {new Date(t.created_at).toLocaleDateString()}</div>
                </div>
                <span style={{ fontSize:10, padding:"2px 8px", borderRadius:10, background:(SC[t.status]||"#888")+"20", color:SC[t.status]||"#888" }}>{t.status?.replace("_"," ")}</span>
              </div>
            </div>
          ))}
        </div>
      )}
      {tab==="new"&&(
        <form onSubmit={submitTicket}>
          <div style={{ fontSize:11, color:"#666", marginBottom:4 }}>Category</div>
          <select style={inp} value={form.category} onChange={e=>setForm(f=>({...f,category:e.target.value}))}>
            {CATEGORIES.map(c=><option key={c.k} value={c.k}>{c.icon} {c.l}</option>)}
          </select>
          <div style={{ fontSize:11, color:"#666", marginBottom:4 }}>Priority</div>
          <select style={inp} value={form.priority} onChange={e=>setForm(f=>({...f,priority:e.target.value}))}>
            {PRIORITIES.map(p=><option key={p.k} value={p.k}>{p.l}</option>)}
          </select>
          <div style={{ fontSize:11, color:"#666", marginBottom:4 }}>Subject</div>
          <input style={inp} placeholder="Brief description of your issue" value={form.subject} onChange={e=>setForm(f=>({...f,subject:e.target.value}))}/>
          <div style={{ fontSize:11, color:"#666", marginBottom:4 }}>Message</div>
          <textarea style={{ ...inp, minHeight:100, resize:"vertical" }} placeholder="Describe your issue in detail..." value={form.message} onChange={e=>setForm(f=>({...f,message:e.target.value}))}/>
          <button type="submit" disabled={submitting} style={{ width:"100%", background:"#378add", border:"none", borderRadius:8, color:"#fff", fontFamily:"Syne,sans-serif", fontSize:14, fontWeight:700, padding:"12px", cursor:"pointer" }}>{submitting?"Submitting...":"Submit Ticket"}</button>
        </form>
      )}
    </div>
  )
}

