      <div style={{ maxWidth:480, margin:"0 auto", padding:"1.5rem 1rem" }}>
        {/* Service card */}
        <div style={{ background:"#fff", borderRadius:16, overflow:"hidden", marginBottom:"1rem", boxShadow:"0 2px 12px rgba(0,0,0,0.06)" }}>
